(window.AQIDA_TEXTS = window.AQIDA_TEXTS || {})["687"] = {"atoms": {"687.1": {"x": [[5, "بسم الله الرحمن الرحيم\rدراسة مقارنة بين شراح المحصل\r"]], "pg": [5, 5]}, "687.2": {"x": [[5, "وموقف فخر الدين الرازى من علم الكلام\rان فلسفة الدين الاسلامى عند بعض المفكرين المسلمين هى علم الكلام والحقيقة أن علم الكلام ينبغى أن يقال له «فلسفة الدين الإسلامى» لأنه يضع أسس الدين الاسلامى الفكرية «العقائدية النظرية» ويناقشها ويدافع عنها على أسس عقلية ومنطقية وتجارب علمية داعما اياها بالوحى المنزل، ومفسرا النصوص الدينية على حسب ارتقاء العقل البشرى بتجاربه العلمية النافذة لفهم قوانين وأسرار الكون والمجتمع الإنسانى.\rوقد مرّ علم الكلام بمراحل فى الفكر الاسلامى وان كان هناك فكرة تعمل ضده وتناقضه منذ ظهوره وحتى يومنا هذا ولكن ظهر مفكرون اشتغلوا بعلم الكلام، سمّوا متكلمين أو علماء الكلام حقا وبتعبير آخر فلاسفة الدين الاسلامى.\rويعتبر القرن الخامس والسادس والسابع الهجرى، والحادى عشر والثانى والثالث عشر الميلادى عصور نضوج علم الكلام. وفى تلك الفترة عاش فخر الدين الرازى وأصبح من أفذاذ المتكلمين، والذين جاءوا بعده مباشرة من المتكلمين الفلاسفة والقضاة المتكلمين اهتموا بمنهجه وشرحوا ولخصوا كتبه المتعددة خاصة «المحصل» فى علم الكلام.\rفان فخر الدين الرازى كنيته واسمه أبو عبد الله محمد بن عمر بن حسين"], [6, "ابن على؛ ولد فى مدينة الرى عام 542 أو 544 ه‍1148 م؛ وتوفى فى مدينة هراة عام 606 ه‍ ـ 1209 م\rوهو امام وفيلسوف فى علم الكلام وفلسفة الدين، الا أنه لا يوجد كتاب يتحدث عن شخصية الرازى فى لغة غير اللغة العربية. وفى السنوات الأخيرة بدأ العلماء والباحثون يهتمون بالرازى متكلما ومفسرا. ولا شك أن فخر الدين الرازى لم يأخذ حقه من الدراسة والبحث فى نطاق البحوث الاسلامية بعد؛ اذ لم تقدم عنه ابحاث علمية تتناوله كفيلسوف مسلم.\rومن خلال اطلاعنا على ما كتب عن هذا العالم الكبير، وعلى ضوء ما وصلنا إليه من نتائج نستطيع أن نقول: ان الرازى قد لعب دورا كبيرا فى علم الكلام والفلسفة الاسلامية ويمكن ايجاز ذلك فى نقطتين.\rالأولى ـ انه استوعب فلسفة ارسطو التقليدية ثم كان أول من أدخل هذه الفلسفة فى علم الكلام. ونتيجة لما قام به الرازى أصبح علم الكلام فلسفة ويمكن أن نقول بعبارة أخرى انه جعل تلك الفلسفة كلاما. وهكذا امتزج علم الكلام بالفلسفة، ولكن لا ينبغى أن يفهم من ذلك ان المسائل الفلسفية التى عارضها علم الكلام أصبحت بذلك مشروعة؛ بحيث اعتبرت كلاما. لقد ادى ذلك المنهج الّذي اختلطت فيه الفلسفة بعلم الكلام، الى عدم دراسة الفلسفة كعلم مستقل وبالتالى الى خمود التفكير الحر فى العالم الاسلامى.\rوبعد ذلك فقد اتبع نهج الرازى حتى دخلت الفلسفة فى علم الكلام وامتزجت به ومن ثم فلم تدرس الفلسفة كعلم مستقل أو لم تصبح دراسة مستقلة عن علم الكلام. ثم أصبحت هذه الفلسفة الممتزجة بعلم الكلام سببا للتأخر ولإخماد شعلة التفكير الحر فى العالم الاسلامى. ومن جهة أخرى فان محيى الدين بن عربى والسهروردى قد اهتما بالجانب الوجودى من الفلسفة فى التصوف وجعلاها منه وبذلك انسحبت الفلسفة المحضة أو العامة عن ميدان الفلسفة ولم يكن الرازى وحده رائدا فى هذا المجال، بل نجد أيضا محيى الدين بن عربى والسهروردى يدخلان الجانب الوجودى من الفلسفة فى التصوف حتى وصل بهما الحد الى اعتباره جزءا منها. وهكذا امتزجت الفلسفة المحضة والتفكير الحر بالتصوف"], [7, "فأصبحت الفلسفة تدرس بين سطور علم الكلام والتصوف بقدر ما أعطيت من العناية.\rوبعد عهد الرازى (606 ه‍، 1209 م) وشهاب الدين السهروردى (587 ه‍، 1191 م) لا نصادف فيلسوفا حقيقيا. لأن محبى الفلسفة اكتفوا منها بالقدر الّذي دخل فى علم الكلام والتصوف وبسبب ذلك لم ينم التفكير الفلسفى المحايد الحر؛ لأن منشأ التفكير الفلسفى وسبب تقدمه فى الحقيقة هو التفكير الحر المحايد التام.\rوالمعلوم أن التفكير الفلسفى لا يخطو الى الإمام الا فى ظل جو يسوده التفكير الحر الّذي لا يخضع لا غلال تقيده، تلك الأغلال التى من شأنها أن تطفئ اللهب المتوقد فى سماء فسيحة رحبة.\rوالّذي لا بد من قوله هنا هو أن الفلسفة انما تنتج وتثمر اذا درست لذاتها لا من أجل غيرها. ولهذا يجب أن تدرس الفلسفة من أجل التفلسف فقط. ولكن فخر الدين الرازى خالف ذلك عند ما دمج الفلسفة بالكلام، بحيث أصبحت الفلسفة تدرس من خلال علم الكلام. واذا كان علم الكلام قد استفاد من الفلسفة فى بداية الأمر فانه توقف عند ما توقفت الدراسات الفلسفية وأعتقد ان الأستاذ اسماعيل حقى الإزميري قد أخطأ عند ما جعل سيف الدين الآمدي اوسع علما بالفلسفة من فخر الدين الرازى (1).\rالثانية ـ واذا كان الرازى قد أدخل الفلسفة فى علم الكلام فانه ـ على ضوء فلسفة ارسطو التقليدية ـ قد أعطى اتجاها جديدا لعلم الكلام، فأثر بذلك على الفكر الاسلامى وقد ظهر تأثير الرازى جليا فى غيره من خلال بقاء العديد من العلماء والمفكرين أسرى اتجاهه ومنهجه بعد ذلك (2). لقد أدى هذا التيار\r__________________\r(1) أزميرلى اسماعيل حقي، يكى علم الكلام علم الكلام الجديد، جلد 1/ 87 استنبول، اوقاف اسلامية مطبعة سى. 1339.\r(2) يبدو واضحا عند من يقارن المحصل مع متن «طوانع الانوار» للقاضى عبد الله بن عمر البيضاوي المتوفى سنة 685 ه ـ 1286 م. ان اول من اقتفى اثر المحصل هو القاضي اليضاوي في متنه المذكور وهو لم يكتف بالسير على نهج المحصل"], [8, "الجديد الى انتشار مذهب الاشاعرة، كما كان له تأثير فى اختفاء وانكماش مذهب الماتريدية، بالرغم من أن أسلوب ومنهج الماتريدية فى دراسة علم الكلام يختلف عن منهج وأسلوب الرازى. ويتضح هذا التأثير أكثر بعد وفاة أكبر متكلمى الماتريدية وهو أبو المعين النسفى (508 ه‍/ 1114 م) اذ لا نرى أحدا يتبع منهجه من بعده. ومن ثم أهمل كتابه «تبصرة الأدلة» لقد كان منهج النسفى يختلف اختلافا كبيرا عن منهج أرسطو التقليدى حيث انه شبيه بمنهج «السمنتكس (*)» اليوم. بعد ذلك استولت المدرسة الأشعرية التى تقبلت الفلسفة المشائية على الفلسفة الأخرى، وأصبحت ممثلا لها فى العالم الاسلامى بعد فخر الدين الرازى.\rواذا كان قد أهمل ذلك حتى الآن فانه ينبغى أن يهتم به مستقبلا؛ ولهذا فاننا نفكر ان نقوم بعمل علمى آخر حول كتاب تبصرة الأدلة لأبى المعين النسفى.\rان تلك المحاولة الفلسفية الكلامية أدت الى نشأة مذهب كلامى ذى اتجاه واحد فى البحث والدراسة، ولم تتح فرصة لنمو الأفكار الفلسفية الحرة.\rولكى نبرز دور فخر الدين الرازى فى علم الكلام بوجه عام، نرى من المناسب أن نبين رأينا فى الغزالى أولا؛ لأن الامام الغزالى هو الآخر قد لعب دورا كبيرا فى التفكير الاسلامى قبل ذلك ومهد الطريق للرازى ويمكن تلخيص ذلك فى النقاط التالية:\r1 ـ لقد ألمّ الغزالى بجميع العلوم الإسلامية. وفى كل علم من تلك العلوم كان له الدور الموجه وخاصة فى أربعة علوم رئيسية. وبذلك تميز عمن سبقوه لقد\r__________________\rفحسب بل اقتبس منسبه العبارات والتعاريف والتعابير والاصطلاحات. ومع ذلك فانه لم يشر لا من قريب ولا من بعيد الرازي ولكن الشارح شمس الدين بن محمود ابن عبد الرحمن الاصفهاني المتوفى سنة 749 ه، 1348 م قد ذكر لفظ «الامام» مشيرا الى الرازي. وبذلك مهد الامام الرازي طريقا ومنهجا جديدا في علم الكلام لمن اتى بعده امثل عذد الدين عبد الرحمن بن احمد الايجي القاضي المتوفى سنة 752 ه، 1355 م حيث كان قد بني مؤلفه المشهور المواقف في علم الكلام اعتمادا على المحصل لفخر الدين الرازي وكما استفاد ايضا من المتكلمين الذين سبقوه.\r(*)  semantpigs  علم معنى الالفاظ ومرادفها  semasiology  علم مدلول الالفاظ وارتباط الفكر باللغة وتطور دلالات الالفاظ."], [9, "أصبحت شخصية الغزالى العالم والمفكر مثلا حيا لمن أتى بعده، لكن ذلك تطلب ممن نهج منهجه واقتفى أثره عملا كبيرا وجهدا شاقا. أما العلوم الأربعة الرئيسية التى برز فيها الغزالى هى: 1 ـ الفقه وأصوله. 2 ـ علم الكلام. 3 ـ الفلسفة. 4 ـ التصوف. لقد ضلع فى هذه الجوانب الأربعة وأصبح له فيها دور التوجيه لقد كان عالما وإماما فى تلك العلوم جميعا، ولا شك ان ذلك يرجع الى تميزه بذكاء حاد وشغف بالعلوم على اختلاف أنواعها ولهذا من الصعب ان نجد قبله عالما يحمل نفس ثقافته الواسعة تلك.\r2 ـ ان ثقافة الغزالى لم تقف عند حد معرفته للعلوم الاسلامية فحسب، بل تعدتها الى حد الالمام والاحاطة بالثقافة التى تعارض الاسلام عالما بما لدى خصومه فى نفس الوقت من أدلة وحجج. واعتمادا على ذلك كان يسوق آراءه المستندة على أساس راسخ متين. فمثلا عند ما يقوم التصوف من الناحية التشريعية يستند فى ذلك على ما لديه من ثقافة فى الفقه وأصوله ولذلك عند ما يقال ان الغزالى يتحدث فى الفقه كذا أو فى التصوف كذا لا ينظر الى رأيه كأى رأى من الآراء بل ينظر الى أنه أهل لرأيه وصاحب كلمة صحيحة فيما يقول. وكذلك الأمر فيما يتعلق بالعلوم الأخرى التى ضلع فيها مثل علم الكلام والفلسفة. وهكذا جذب الغزالى بثقافته الواسعة انظار غيره من العلماء؛ فأثار فيهم روح التوسع فى العلوم حيث نشأ من بعده نهج التوسع فى الأبحاث والعلوم، لكن ذلك أصبح حائلا أمام التعمق فيها، لقد حاول العلماء من بعده التشبه به فى ثقافته الواسعة تاركين التخصص فى المواضيع مما أدى الى ضياع العلم والفلسفة.\r3 ـ لم يكن الغزالى ضد الفلسفة فحسب؛ بل عارض علم الكلام أيضا، ولذلك كان له تأثير ملحوظ فى هذين الموضوعين الذين يعتبران مجال تفكير أكثر من العلوم الأخرى ولكون الغزالى يتمتع بمكانة علمية ودينية لدى جمهور المسلمين فان عداوته لعلم الكلام والفلسفة انتشرت لدى الأوساط المختلفة، ومن ثم ازداد خصومهما من مختلف الطبقات. ولا تزال هذه الفكرة منتشرة فى الأوساط الدينية حتى يومنا هذا. ان هذا الموقف السلبى من الغزالى قد أعاق نمو التفكير ومشروعية الحرية التى تحتاج إليها بالضرورة التنمية الفكرية."], [10, "4 ـ عند ما قام الغزالى بوضع معيار للعلوم المختلفة أخطأ فى اعطاء كل علم من العلوم حقه. فهو قد أعطى للتصوف مثلا قيمة أكثر مما يستحق؛ مما أدى الى اختلال التوازن بين العلوم المختلفة. لقد استطاع الغزالى بما له من شخصية ومكانة علمية فذة لدى الجمهور كما قلنا؛ أن يلعب دورا كبيرا فى إقناع الناس بصحة رايه ومنهجه. وقد كان ذلك سببا من الأسباب التى أدت الى ترجيح رأيه عند ما تعرض لكل من الفلسفة وعلم الكلام. ان الغزالى لم يكتف بذكر آرائه تلك فى كتاب أو فى موضوع معين بل بثها بين ثنايا كتبه المختلفة فى التفسير والحديث والشريعة والتصوف. وبين رأيه بوضوح فى ذلك كله وتصح فيما يتعلق بعلم الكلام بعدم التعمق فيه لأنه لا حاجة تدعو الى الاستفاضة فى موضوعاته وقال نفس الشيء بالنسبة للعلوم الشرعية الأخرى فهو يقول بهذا الصدد:\r«فان العلم كثير والعمر قصير وهذه العلوم آلات أو مقدمات وليست مطلوبة لعينها بل لغيرها. وكل ما يطلب لغيره فلا ينبغى أن ينسى فيه المطلوب ويستكثر منه فاقتصر من شائع علم اللغة على ما تفهم منه لغة العرب. وتنطق به ومن غريبه على غريب القرآن وغريب الحديث ودع التعمق فيه. واقتصر من النحو على ما يتعلق بالكتاب والسنة ... فما من علم الا وله اقتصار واقتصاد واستقصاء .. ونحن نشير إليها فى الحديث والتفسير والفقه والكلام لتقيس بها غيرها. فالاقتصار فى التفسير هو ما يبلغ ضعف القرآن فى المقدار كما صنفه على الواحدى النيسابورى وهو الوجيز، والاقتصاد هو ما يبلغ ثلاثة أضعاف القرآن: كما صنفه من الوسيط فيه. وما وراء ذلك استقصاء مستغنى عنه فلا مرد الى انتهاء العمر.\rواما الحديث فالاقتصار فيه تحصيل ما فى الصحيح بتصحيح نسخة على رجل خبير بعلم متن الحديث واما حفظ اسامى الرجال فقد كفيت به بما تحمله عنك قبلك ولك أن تقول على كتبهم. وليس يلزمك حفظ متون الصحيحين ولكن تحصله تحصيلا تقدر منه على طلب ما يحتاج إليه عند الحاجة واما الاقتصاد فيه فان تضيف إليها ما خرج عنهما مما ورد فى المسندات الصحيحة.\rواما الفقه فالاقتصار فيه على ما يحويه مختصر المزنى وهو الّذي رتبناه فى"], [11, "خلاصة المختصر والاقتصاد فيه ما يبلغ ثلاثة امثاله وهو القدر الّذي أوردناه فى الوسيط والاستقصاء ما أوردناه فى البسيط.\rوأما الكلام فمقصوده حماية المعتقدات التى نقلها أهل السنة من السلف الصالح لا غير. وما وراء ذلك طلب لكشف حقائق الأمور من غير طريقها، ومقصود حفظ السنة تحصيل رتبة الاقتصار منه بمعتقد مختصر، وهو القدر الّذي أوردناه فى كتاب قواعد العقائد من جملة هذا الكتاب. والاقتصاد فيه ما يبلغ قدر مائة ورقة وهو الّذي أوردناه فى كتاب الاقتصاد فى الاعتقاد» (3).\rوبعد اطلاعنا على موقف الغزالى من الفلسفة وعلم الكلام ذلك الموقف الّذي أوجزناه آنفا يأتى فخر الدين الرازى ليوحد بين الفلسفة وعلم الكلام كما أسلفنا وهكذا تكتسب الفلسفة مشروعيتها من مشروعية علم الكلام. ولكن بسبب عدم استقلالها لم تستطع أن تتقدم، ثم ان هذا الوضع قد أثر بدوره فى العلوم التجريبية.\rواذا أردنا ان نفهم التفكير الاسلامى بعد الرازى علينا أن نبدأ بالرازى قبل ذلك ونفهمه جيدا. وبكل أسف نقول ان الرازى لم يفهم كما ينبغى لعدم اهتمام الناس بمؤلفاته الأخرى كاهتمامهم بتفسيره الكبير لقد أخذ الرازى لقب الامام بناء على موفقه من علم الكلام علما أن بعض أعماله العلمية الخاصة بهذا العلم لم تنشر بعد مثل «المطالب العلية» و «الملخص» و «نهاية العقول» و «المحصول (*) فى الأصول» وغيرها من الأعمال العلمية المهمة، ومن جهتنا ننوى القيام بنشر تلك الأعمال المهمة بقدر استطاعتنا وبقدر ما تسمح به امكاناتنا.\rدراسة مقارنة بين المحصل وشروحه:\rاذا قلنا ان فخر الدين الرازى هو نقطة بداية أو نهاية الملتقى بين المتقدم\r__________________\r(3) الغزالي، احياء علوم الدين، 1/ 58، القاهرة، 1967.\r(*) طبعت جامعة الامام محمد بن سعود الاسلامية، المحصل في علم اصول الفقه في ست مجلدات 1401 ه ـ 1981 م. وهذه المقالة كتبت قبل ذلك."], [12, "والمتأخر نكون قد أنصفناه بلا شك فهو نقطة بداية بمعنى ان الثقافة الفلسفية والكلامية الاسلامية اتخذت اتجاها جديدا بعده وهو ملتقى الطرق بين المتقدم والمتأخر بمعنى أن الثقافة الاسلامية الفلسفية والكلامية التقليدية قد انتهت إليه واذا جاز التعبير فان منزلته تعادل منزلة ارسطو فى الثقافة اليونانية من حيث الأهمية. لقد استطاع الالمام بكل ما توصل إليه الأقدمون ثم صاغه فى قالب جديد. ونعتقد أن هذا يكفى لأن تفتخر به الثقافة الاسلامية.\rلقد قسم الرازى كتاب المحصل الى أربعة أقسام:\r1 ـ القسم الأول فى مبادي المعرفة ومصادرها وكيفية اكتسابها.\r2 ـ القسم الثانى فى الموجود والأشياء الموجودة وترتيبها وخصائصها المميزة بعضها من بعض.\r3 ـ القسم الثالث فى اثبات المبدأ الأول وواجب الوجود ومصدر كل الموجودات.\r4 ـ القسم الرابع فى السمعيات وما يدخل فيها من نبوة، وآراء الفرق المختلفة النشأة من فهم النصوص والأخبار.\rلم يكن الرازى السبّاق لمثل هذا التقسيم. فان ابن سينا يذكر فى أول الاشارات بانه يبدأ بالمنطق ثم بالأشياء الطبيعية وثلث بما بعد الطبيعة. ان هذا النهج مفيد ونافع للقارئ حيث انه يتبين له لأول وهلة ما ذا يحتوى الكتاب وما هى الغاية منه وكأن المؤلف قد لخص كتابه للقارئ ببضع كلمات ليشوقه ويجعله يستمر فى القراءة. وهكذا نرى أن من سبق فخر الدين الرازى من المتكلمين قد اتبع هذا النهج لقد كان العلماء يبوبون كتبهم مبتدئين أولا بنظرية المعرفة ثم بأنواع الأدلة والكائنات الطبيعية كما درجوا الى البحث عن وجود الله تعالى ثم النبوات. وكأنهم رأوا قبل كل شيء أنه من الضرورى الايمان بالله تعالى ورسوله محمد صلىلله عليه وسلم لأن ذلك يجعل الانسان مدركا لمدى المعرفة ولأن الله تعالى قال: «فاعلم انه لا إله الا الله»، ومن ثم ليعرف بأن هناك كائنات حية"], [13, "كثيرة فى هذا الكون وأن رب العالمين قد اصطفى الانسان من بين هذه الموجودات بانزال الوحى إليه. والى جانب هذا لا شك انه كانت هناك مواضيع أخرى أو خاصة افردت لها الكتب والتآليف. اما اليوم فان كل مؤلف يتبع منهجا خاصا به بحيث يستطيع ابداء رأيه بشكل ينسجم مع مستوى استيعاب الناس مسلطا الأضواء على بعض المشاكل التى تدور فى اذهان الآخرين.\rان المؤلف يشرح غايته ومنهجه فى مقدمة كتابه ويبين موقف كتابه البيئات العلمية. والشارح كذلك يبين غايته من خلال شرحه ووضع الكتاب الّذي يشرحه بين الأوساط العلمية.\rان المحصل لفخر الدين الرازى كما يفهم من اسمه هو محصل أفكار وآراء الرازى أولا ثم محصل أفكار المتقدمين والمتأخرين من الفلاسفة والمتكلمين ثانيا. ولهذا فانه جدير بأن يوضع بين الكتب التى عنى بها شارحوها وأعطوها عناية كبيرة ووجدوا فيها أشياء مبهمة فأوضحوها وأفكارا جديدة فنقدوها.\rالحقيقة أن القارئ يجد فى المحصل آراء استطاع المتقدمون أن يسبقوا المؤلف فيها الا أن المؤلف قد أتى بشيء جديد فى الايضاح والشرح والبيان وقد لخص ما كتبه فى كتبه المختلفة مثل المباحث المشرقية ونهاية العقول والملخص وغيرها. فالقارئ يلاحظ الأفكار والعبارات المركزة فى المحصل، اذا قارن ما فيه بكتب المؤلفين الآخرين.\rان المحصل يحتوى على فلسفة المشائين بدءا من ارسطو وحتى ابن سينا فى المنطق والفلسفة الطبيعية وما وراء الطبيعة وناقش واجب الوجود وامكانية وجود العالم كما ورد عند الفارابى وابن سينا فى الفلسفة الوجودية لقد كان الكلام والفلسفة قبل الرازى مفترقين فى المنهج والمحتوى؛ ولكن الرازى جمع بين آراء ومناهج الفلاسفة والمتكلمين فى كتابه «المحصل» مثل أدلة اثبات وجود الله تعالى. لقد اتخذ المتكلمون من قبله من جملة ما اتخذوه من الطرق فى اثبات وجود الله تعالى طريق الحدوث. وأما الفلاسفة فكانوا يتبعون طريق الامكان. والرازى جمعهما فى مؤلفه هذا. لقد رجح الرازى طريق الامكان على طريق"], [14, "الحدوث فى قوله: «علة الحاجة الى المؤثر لما سبق الامكان لا الحدوث» (4) فانه رجح دليل الامكان على دليل الحدوث فى خلق الله للكون. وبهذا الصدد يقول:\r(أ) لأن الحدوث كيفية لوجود الحادث فيكون متأخرا عنه والوجود متأخر تأثير القادر فيه المتأخر عنه احتياج الممكن إليه، المتأخر عن علة احتياجه إليه، فلو كانت العلة هى الحدوث لزم تأخر الشيء عن نفسه بمراتب.\r(ب) احتجوا (أى المتكلمين) بأن علة الحاجة لو كانت هى الامكان، لزم احتياج العدم الممكن الى المؤثر، وهو محال لأن التأثير يستدعى حصول الأثر والعدم نفى محض فلا يكون أثرا.\r(ج) جوابه: فان قيل: ان علة العدم عدم العلة (5).\rان فخر الدين الرازى فى بند (ا) يبين سبب ترجيحه علة حاجة الكون الى وجود الله تعالى بأنه الامكان ويعطى سبب ترجيحه بأن احتياج الممكن الى الواجب الوجود احتياج مباشر وملازم وموجود منذ بداية الأمر وقبل احداث الممكن.\rولذلك لا يمكن ان يخطر ببال الانسان المفكر درجات أو مراحل فى علية الحاجة لأن الانسان يضل فى الطريق الحق عند ما يندرج فى وسائل الاحتياج المتعددة. والاحتياج متلاحم ومتلاصق وبتعبير آخر اذا كانت علة الحاجة هى الامكان. وأما اذا كان علة الحاجة هى الحدوث تتأخر علة الحاجة عن الحدوث. وهذا هو المعنى الدقيق فى المسألة. وعلى ذلك تظهر علة الحاجة بعد أن يحدث الكون، يعنى بعد أن يخلق الله الكون ونراه بأعيننا وحواسنا حينئذ نفهم أو نستدل بما أن الكون قد حدث وصار بعد أن لم يكن موجودا. إن الله احدثه وكونه وخلقه. هنا علة الحاجة تأخرت عن الحدوث أو على الأقل بالنسبة الى فهم الانسان. فأما فى الامكان فان الانسان يفهم فى بداية الحاجة قبل كون الحدوث\r__________________\r(4) الحمل، 54، مصر 1323.\r(5) نفس المحصل."], [15, "أو قبل ايجاد وخلق الكون، فانه محتاج الى موجود وخالق قبل أن يكون أى شيء. وهنا يفهم من امكانيته أنه محتاج الى واجب الوجود لأن يكون موجودا. هنا علة الحاجة سابقة الى الايجاد. وهذا يستند على التفكير المحض والبحث، ويعتبر آخر مسألة ميتافيزيقية.\rوفى بند (ب) فان الرازى أتى بدليل المتكلمين المتقدمين فى ترجيح علية الحدوث على الامكان، واستدلال المتقدمين من المتكلمين بأن الامكان لو كان هو علة الاحتياج وأن الامكان هو استواء طرفى الوجود والعدم لكن العدم الممكن يعنى لا العدم المستحيل، محتاج الى مؤثر. فالمتفق عليه أن يفهم ان العدم نفى محض، ولا يحتاج الى مؤثر، حتى لا يخطر ببال انسان ان ادعاء الحاجة الى المؤثر محال لأن العدم غير محتاج لأنه اذا احتاج، معناه أصبح موجودا وأثرا لمؤثر لأنه لما كان محتاجا الى المؤثر والمؤثر يؤثر فيه ويصبح أثرا لأن علية الحاجة سابقة على الوجود فى الامكان، وان كانت الحاجة ثابتة يلزم أن يكون العدم ثابتا وموجودا وهو محال. ولذلك اعتبر المتكلمون القدماء وبعض المحدثين منهم حاجة الكون الى واجب الوجود هى الحدوث لا الامكان.\rوفى بند (ج) فان الرازى أعطى لهم الجواب، بأن الممكن فى حالة الامكان بما أنه مستوى طرفى العدم والوجود. والممكن ليس هو موجودا ولا معدوما على حد تعبير الفلاسفة نظريا فانه غير موجود فعلا فلا يحتاج الى المؤثر ولا يخطر ببال المفكر احتياجه إليه لأنه عدم ولا حاجة الى تفكير وجوده ولا سبب له ولا علة. لأنه ما دام فى حيز العدم فانه عدم سبب التفكير فى حاجته الى المؤثر، هو عدمه يعنى عدم علته وهو قاعدة عند المتكلمين والفلاسفة: علة العدم عدم العلة. فمعناه أن العلة فى ان الشيء غير موجود ومعدوم هو عدم وجود علته يعنى لا يوجد دليل لعلة وجوده. وهذا دليل على عدم وجوده وكذلك استدلال المتكلمين على أن العدم الممكن محتاج الى مؤثر غير وارد ولا مستند على تفكير منطقى. وهذا الجواب يظهر ويعتمد على استعمال المصطلحات الفلسفية والكلامية، وتحقيق أو تبين معانيها كما هى مصطلح عليها بدقة ممكنة.\rومن جانبنا كان من الممكن أن يقوم بجواب ثان لذلك. فى الحقيقة، الممكن"], [16, "الحقيقى هو مستوى طرفى العدم والوجود محتاج الى مؤثر؛ وطرفه العدمى أيضا محتاج الى المؤثر لأن يكون موجودا ولا غبار فيه، والا كيف يمكن أن يكون موجودا، فان عدم الوجود سابق على الوجود فى الممكن الموجود، واذا لم نعتبر الحاجة هنا يعنى فى الممكن حالة عدم وجوده كيف، يمكن أن يكون موجودا فيما بعد، ينبغى ألا يكون هناك أى مانع من أن العدم الممكن محتاج الى المؤثر، وبطبيعة الحال الممكن محتاج الى المؤثر حال عدمه لأن يكون موجودا وحال وجوده لأن يكون وجوده دائما ومستمرا ولذلك يحتاج الممكن الموجود الى المؤثر فى الوجود والدوام.\rفى الجملة، ان الممكن فى كلتا الحالتين الوجود والعدم محتاج الى المؤثر نظريا فى حالة العدم، لأننا نفكر أنه سيكون موجودا بمؤثر، وفى هذه الحالة هو معدوم ومحتاج. والممكن محتاج الى المؤثر وجوديا فى حالة الوجود ليستمر وجوده.\rويقول فخر الدين الرازى فى ترجيحه الامكان على الحدوث بناء على تعليله ماهية الامكان. ويظهر من عبارات الرازى فى ترجيحه هذه المرة أنه بالامكان يستطيع الانسان أن يثبت استمرارية ودوام الحاجة؛ يقول بهذا الصدد:\r(1) «والممكن حال بقائه، لا يستغنى عن المؤثر، لأن علة الحاجة الامكان والامكان ضرورى اللزوم للماهية الممكنة، فهى ابدا محتاجة. لا يقال إنه صار الوجود أولى به حال البقاء. لأنا نقول هذه الأولوية المغنية عن المرجح، ان كانت حاصلة حال الحدوث، وجب الاستغناء عن المؤثر حال الحدوث، وان لم تكن حاصلة حال الحدوث فهو أمر حدث حال البقاء؛ ولو لاه لما حصل الاستمرار. فالشيء حال استمراره مفتقر الى المرجح» (6).\rيشير الرازى فى هذه العبارات الى ماهية الممكن، وهى أن الماهية ليست غنية عن المؤثر. ان ماهية الممكن كما بينا آنفا، اذا اخرجت من العدم الى\r__________________\r(6) المحصل 54."], [17, "الوجود؛ فصفة الامكان لا تنفصل عنه وتلازمه؛ فصفة الامكان بما أنها لازمة وضرورية للماهية والماهية اذا خرجت من العدم الى الوجود، لا تنقلب من الامكان الى الوجوب وتبقى الماهية على صفة الامكان كما كانت عليه قبل اتصافها بالوجود. وفى هذه الحالة تحتاج الى الواجب الوجود. ونظرية الامكان عند ما وضعت من قبل الفارابى وشرحها بعده ابن سينا وهما قصدا هذا المعنى وهو خلاف الحدوث. ان الحدوث اذا قبل بالمعنى الّذي حدده المتكلمون بأنه خروج الشيء من العدم الى الوجود، وقبل وجوده لم يكن متصفا بأية صفة من صفات النفى ولم يسمّ ـ باسم من الأسماء سوى النفى المحض حيث ليس له اسم يقابله. واذا وجد وحدث لم يكن له أى صلة بما كان قبل وجوده، لأنه قبل وجوده لم يكن شيئا مذكورا حتى يستطيع الانسان أن يفكر بأن له علاقة بما قبله وما بعده. واذا وجد لم يكن محتاجا بدوره الى المؤثر ليوجده ويحدثه مرة ثانية لأنه يلزمه تحصيل الحاصل.\rوأما احتياج الممكن الوجود الى المؤثر حال وجوده لا يستلزم تحصيل الحاصل فالفرق هو أن الممكن لا يحتاج الى المؤثر فى وجوده أو لاتصاف الماهية بالوجود، بل لاتصاف الماهية بالامكان وهذا الامكان باق بعد وجوده، ولكن فى الحدوث غير باق ما هو قبله ولذلك يمكن التفكير بعدم احتياجه الى المؤثر؛ لأن المؤثر قد اظهر اثره وأتم عمله وانتهى، ولم يبق له علاقة مع عمله فى نظرية الحدوث وحاجة الوجود الى الاستمرار فى نظرية الحدوث ينبغى أن تبنى على نظرية أخرى أو تستند على دليل آخر. ودليل الحدوث لا يعطى ذلك بصراحة ووضوح واما نظرية الامكان فانها تتضمنه؛ وهذا هو سبب الترجيح عند الرازى.\r(2) «احتجوا (المتكلمون الذين يرجحون نظرية الحدوث) بأن المؤثر حال البقاء اما ان يكون له فيه تأثير أو لا يكون. فان كان له فيه تأثير؛ فذلك الأثر اما ان يكون الوجود الّذي كان حاصلا وهو محال. لأن تحصيل الحاصل محال. واما أن يكون أمرا جديدا؛ كأن يكون المؤثر مؤثرا فى الجديد لا فى الباقى. وان لم يكن له فيه تأثير أصلا؛ استحال أن يكون مؤثرا»."], [18, "ويقول هنا أصحاب نظرية الحدوث ان الشيء المحدث متى ما أحدث وخلق فأنه يصبح بغنى عن المؤثر وغير محتاج إليه مرة ثانية، اذ لم يبق له حاجة به لأن الشيء المحدث عند ما حدث وتم انقطعت علاقته مع مؤثره وان فرض علاقته به لا يعطى أى معنى لأنه ما ذا يعمل المؤثر فى المرة الثانية هل يعطى وجودا لموجود وهذا لا يمكن بالطبع لأن الموجود غير محتاج الى الوجود والا يكون ايجاد الموجود وهو محال وبتعبيرهم هو تحصيل الحاصل. واذا اعطى المؤثر وأوجد شيئا جديدا. وهو شيء جديد ومحدث آخر ليس هو الشيء المحدث الأول السابق. وبما أن المؤثر لا يعمل شيئا فى المحدث لا فى ايجاده بعد ان وجد ولا فى ابقائه لأن الابقاء تزويد الشيء بالوجود مرة ثانية ولا حاجة إليه لأن الموجود بما أنه موجود لا يحتاج الى الموجود ولا يبقى المؤثر مؤثرا.\r(3) «والجواب: لا نعنى بالتأثير تحصيل أمر جديد بل بقاء الأثر لبقاء المؤثر» (4).\rجواب الرازى هنا ليس مقنعا. فهو وان لم يكن تحصيل أمر جديد، فانه استمرار وتزويد الموجود بالوجود لكى يبقى الموجود دائم الوجود. وصحة هذه الدعوى تقوم على اثبات وجود العلاقة المستمرة بين المؤثر والأثر ودوام حاجة الموجود الى الموجود حال وجوده.\rوهنا ارى انه من الأحرى ان توضع هنا أقوال الشراح نصب الأعين حتى يمكن للقارئ الكريم المقارنة فى إيضاح وشرح وفهم عبارات الرازى حيث نتمكن من خلال ذلك تقديم وتقريب المعنى الى الأذهان.\rيقول نصير الدين الطوسى فى شرح النصوص فى ب ج: «أقول: الحدوث هو كون الوجود مسبوقا بالعدم فهو للوجود الموصوف به. والصفة متأخرة بالطبع عن موصوفها. والوجود الموصوف به متأخر عن تأثير موجوده بالذات تأخير المعلول عن العلة. وتأثير الموجود متأخرا عن احتياج الأثر إليه فى الوجود تأخيرا بالطبع.\r__________________\r(4) المحصل (هامش) 54."], [19, "واحتياج الأثر متأخر عن علته بالذات وجميعها أربع تأخرات. اثنان بالطبع واثنان بالذات وذلك يقتضي امتناع كون الحدوث علة للاحتياج.\rوقد قالوا فى معارضة الامكان صفة للممكن فهو متأخر عنه. والممكن متأخر عن تأثير المؤثر فيه. والتأثير متأخر عن الاحتياج المتأخر عن علته وهى فاسدة. لأن الممكن الموصوف بالامكان ليس متأخرا عن تأثير المؤثر. انما يتأخر عنه وجوده أو عدمه المتأخران عن ذاته اللذين بسببهما احتاج الى مؤثر ثم الى علة الاحتياج.\rوالقائلون بكون الامكان علة الحاجة هم الفلاسفة والمتأخرون من المتكلمين، والقائلون بكون الحدوث علة لها هم الأقدمون منهم.\rوقولهم: لو كان الامكان علة الحاجة لزم احتياج العدم الى المؤثر وهو محال ليس بشيء لأن عدم المعلول ليس نفيا صرفا ولا مانع من أن يكون معلولا لعدم العلة كما مر القول فيه. وقد تبين أن ذلك غير مشتمل على فساد. (5) وفى شرح النصوص: 1، 2، 3.\r«أقول: القول بأن الممكن حال بقائه محتاج الى المؤثر هو قول الحكماء والمتأخرين من المتكلمين. وبعض منهم يفرقون بين الموجد وبين المبقى. والاعتراض بأن المؤثر حال البقاء اما أن يكون له فى الأثر تأثير أم لا، يشتمل على غلط. فان المؤثر فى البقاء لا يكون له أثر البقاء حال العدم. وتحصيل الحاصل انما لزم منه. والحق أن المؤثر يفيد البقاء بعد الاحداث.\rوقوله وان كان أمرا جديدا كان المؤثر مؤثرا فى الجديد لا فى الباقى. جوابه: نعم تأثيره بعد الأحداث فى أمر جديد هو البقاء فانه غير الاحداث فهو مؤثر فى أمر جديد صار به باقيا، لا فى الّذي كان باقيا.\rوقوله فى الجواب. لا نعنى بالتأثير تحصيل أمر جديد بل بقاء الأثر لبقاء\r__________________\r(5) المحصل (هامش) 54. الطوسي، تلخيص المحصل 120 ـ 121 طهران 1980."], [20, "المؤثر، ليس بشيء لأن البقاء المستفاد من المؤثر أمر جديد لو لاه لكان الأثر مما لا يبقى» (6).\rلا أريد أن أعلق على عبارات الطوسى لأنها واضحة الا الجملة الأخيرة مع استصغاره عبارة الرازى فى الجواب ولم يزد عليها شيئا وانما اعاد نفس المعنى بعبارات أخرى.\rوأما ابن أبى الحديد فقد علق على قول الرازى قائلا: «فصل: ثم تكلم فى أن الممكن الباقى هل يستغنى حال بقائه عن المؤثر أم لا وهى مسئلة خلاف بين الفلاسفة وكبير من المتكلمين. فاحتج لمذهب الفلاسفة بأن الحاجة الى المؤثر الامكان. والامكان ضرورى اللزوم لماهية الممكن فيكون محتاجا أبدا ثم سأل نفسه فقال انه حال البقاء صار أولى بالوجود واجاب بأن هذه الأولوية المغنية عن المرجح ان كانت حاصلة حال الحدوث وجب الاستغناء عن المؤثر حال الحدوث وان لم تكن حاصلة حال الحدوث فهى أمر حصل (و) حدث حال البقاء ولو لاه لما حصل الاستمرار. فالممكن حال استمراره مفتقر الى المرجح (7).\rوفى شرح نص الرازى (1، 2، 3) يقول ابن أبى الحديد:\r«أقول: ان هذا خروج عن محل النزاع لأن الفلاسفة ومن وافقهم من المتكلمين على هذه المسألة يزعمون أن الممكن الباقى محتاج حال بقائه الى مؤثر خارج عن هذه الأولوية سواء صح القول بها أو فسد. ولو جاز عند الفلاسفة أن يكون وجود العالم حال استمراره تسليم هذه الأولوية من علة خارجة عنه بالكلية واجبة الوجود يقتضي دوامه واستمراره. وفى هذا وقع النزاع وهو محل البحث والنظر وكلام صاحب الكتاب تصريح بالرجوع عن المذهب الّذي يروم ان ينتصر له. حكى حجة لمن زعم انه لا يكون المؤثر مؤثرا الا فى أمر حادث. ومحصولها ان المؤثر حال بقاء الأثر اما ان يكون له تأثير أو لا يكون. فان كان له فيه تأثير فذلك التأثير اما الوجود الّذي كان حاصلا وهو محال لأن تحصيل الحاصل محال،\r__________________\r(6) المحصل (هامش) 54، 55. تلخيص المحصل 141.\r(7) تعليقات ابن ابي الحديد، 455 ب، مكتبة جامعة استانبول تحت 3297."], [21, "واما أمر جديد فيكون المؤثر مؤثرا فى (*) أمر متجدد لا فى الباقى، وان لم يكن له فيه تأثير أصلا استحال أن يكون له فيه أثر. واجاب فقال (الرازى) «انا لا نعنى بالتأثير تحصيل أمر جديد بل بقاء الأثر لبقاء المؤثر».\r«أقول: ان حجة الخصم قد أتت على هذا الجواب. لأن بقاء الأثر الّذي زعم (456 ـ 1) أنه معلول المؤثر هل هو الحاصل أم غيره. ان كان الأول فتحصيل الحاصل محال.\rوان كان غيره فهو شيء متجدد حصل بالمؤثر وذلك قول بأن المؤثر لم يؤثر الا فى أمر متجدد وهو مطلوب الخصم. وليس معك قسم ثالث. فان قلت المؤثر أثر فى استمرار (و) دوام الباقى قيل لك هذا الاستمرار هو نفس الشيء الحاصل بعينه أم زائد على نفسه أما كيفية أو نسبة أو مهما شئت فقل: الأول قول بتحصيل الحاصل، والثانى رجوع الى مذهب صاحب الحجة وقد استقصيت البحث فى هذا الموضع فى التعليق على كتاب الأربعين» (8)\rان صاحب المفصل فى شرح المحصل على بن عمر الكاتب القزوينى أوضح وشرح نصوص المحصل (ا، ب، ج) بعباراته الآتية: «علة الحاجة الى المؤثر الامكان لا الحدوث الى آخره: أقول اختلف الناس فى أن علة الحاجة الى المؤثر الامكان أو الحدوث فذهب الحكماء وبعض المتكلمين الى أنها الامكان؛ والحدوث غير معتبر أصلا. وذهب بعضهم الى أنها الحدوث وذهب الباقون الى أن علة الحاجة الامكان والحدوث.\rاذا عرفت هذا؛ فنقول الدليل على أن الحدوث غير معتبر أصلا هو أن الحدوث عبارة عن كون الشيء مسبوقا بالعدم، فيكون صفة وكيفية لذلك الشيء الحادث فيكون متأخرا عنه لوجوب تأخر الصفة عن الموصوف؛ ووجود الشيء الحادث متأخر عن تأثير الفاعل فيه، وهو أعنى تأثير الفاعل فيه متأخر عن احتياجه الى الفاعل لأنه لو لا احتياجه لما وقع بالفاعل لأنه حينئذ يكون اما واجبا أو ممتنعا.\r__________________\r(*) في المخطوطة: من.\r(8) نفس المرجع، 455 ب ـ 456 ـ 1."], [22, "واحتياجه الى الفاعل متأخر عن علة احتياجه الى الفاعل فاذن الحدوث متأخر عن علة الحاجة فلو كان هو علة أو جزءا منها؛ لزم تأخر الشيء عن نفسه بمراتب وأنه محال.\rواذا ثبت أن الحدوث غير معتبر أصلا والمحوج الى المؤثر اما الامكان أو الحدوث لأن عند انتفائهما كان الشيء واجبا قديما. ومثله لا يحتاج الى سبب فتعين كون الامكان هو العلة للحاجة الى العلة هكذا قرره فى الكتب.\rوفيه نظر لأنا لا نسلم تأخر كل صفة عن الموصوف. فان الامكان صفة وهى سابقة على موصوفه سلمناه لكن لم قلتم بأنه يلزم من عدم كون الحدوث معتبرا ان يكون المحوج الى السبب هو الامكان وانما يلزم ذلك ان لو انحصرت علة الحاجة الى المؤثر فى الامكان أو الحدوث أو فيهما وهو ممنوع. وما ذكرتموه لبيان هذه المقدمة يقتضي ان كل محتاج الى المؤثر فهو ممكن أو حادث لكن لا يلزم من ذلك أن تكون علة للحاجة هذه الأمور الثلاثة.\rوالصواب أن يقول الحدوث لما كان عبارة عن كون الشيء مسبوقا بالعدم لزم بالضرورة تأخره عن ذلك الشيء للعلم الضرورى بامتناع عروض العارض للشئ الا بعد وجوده واما أن الحدوث اذا كان غير معتبر لزم أن يكون علة الحاجة الامكان لاتفاق الكل على أن علة الحاجة منحصرة فى الامكان أو الحدوث أو فيهما.\r(57 ـ 1) قال المتكلمون هذا الدليل فى حيز التعارض لأنا نقول المحوج الى المؤثر اما الامكان أو الحدوث لما بينتم. والامكان ليس علة لأنه صفة للممكن فتكون متأخرة عنه وهو متأخر عن تأثير الفاعل فيه المتأخر عن احتياجه الى المؤثر المتأخر عن علة الاحتياج. فلو كان الامكان علة أو جزءا منها لزم تأخر الشيء عن نفسه مراتب وأنه محال.\rأجاب عنه الحكماء بأنا لا نسلم تأخر كل صفة عن موصوفها. فان الامكان صفة للممكن وهى عندنا متقدمة والا لكان الممكن قبل وجوده اما واجبا أو"], [23, "ممتنعا. ولو كان كذلك لزم انقلاب الشيء من الوجوب أو الامتناع الى الامكان وأنه محال يأباه العقل الصريح والطبع المستقيم. على أنا نقول الحدوث فهو مركب من الوجود والعدم السابق والجزء متقدم على الكل أو يوجد معه فالوجود متقدم على مفهوم الحدوث أو يوجد معه فلو كان الحدوث علة أو جزأ منها لزم تقدم الشيء على نفسه بمراتب وأنه محال ومثل هذا لا يتمشى فى الامكان».\r«قال: احتجوا بأن علة الحاجة لو كانت هى الامكان لزم احتياج العدم الممكن الى المؤثر الى آخره».\rأقول: لو كان الامكان محوجا فى جانب الوجود الى السبب لكان محوجا فى جانب العدم إليه. والثانى باطل فالمقدم مثله.\rبيان الشرطية وانتفاء التالى قد مر كل منهما على أقصى ما يمكن أن يذكر وقول الامام فى الجواب ان علة العدم عدم العلة منع للمقدمة القائلة بأن العدم نفى محض فلا يكون أثرا.\rفقال: العدم لا يكون أثرا لأمر وجودى. اما لأمر عدمى فلا. فان عدم (عدم مكرر) المشروط معلل بعدم الشرط وعدم المسبب بعدم السبب.\rوقوله: وفيه ما فيه: اشارة الى ما يقال من أن العلية والمعلولية من الصفات الوجودية فلا يوصف بها العدم وأنت قد عرفت ما فيه فلا نعيده مرة أخرى.\r«قال الممكن حال بقائه لا يستغنى عن المؤثر الى آخره: «أقول: الدليل على أن الممكن حال البقاء مفتقر الى المؤثر هو ان علة الحاجة الى المؤثر الامكان لما مر والامكان من لوازم ماهية الممكن، والا لجاز أن يصير الموصوف بالامكان فى الجملة واجبا لذاته أو ممتنعا بذاته وأنه محال. واذا كان كذلك لزم بالضرورة تحقق علة الحاجة الى المؤثر حال البقاء فتلزم الحاجة إليه فى تلك الحالة عملا بالعلة.\rقال: لا يقال انه حال البقاء صار أولا بالوجود الى آخره: «أقول: توجيه هذا الكلام أن يقال: لم قلتم بأن الامكان اذا كان من لوازم ماهية الممكن لزم"], [24, "احتياج الثانى الى المؤثر وانما يلزم ذلك أن لو لم يكن الثانى حال البقاء أولى بالوجود وهو ممنوع. فان عندنا الممكن حال (57 ـ ب) البقاء أولى بالوجود، وتلك الأولوية مانعة من احتياجه الى المؤثر والحاصل أنهم يمنعون كون الامكان علة تامة للحاجة الى المؤثر.\r«قال: لأنا نقول هذه الأولوية المستغنية عن المرجح ان كانت حاصلة حال الحدوث وجب الاستغناء عن المؤثر حال الحدوث الى آخره: «أقول: هذا الجواب فى الظاهر كالكلام على المستند لكن نوجهه ونقول: تلك الأولوية اما أن تكون مانعة من الحاجة الى المؤثر أو لم تكن، أو انما كان يلزم احتياج الباقى الى المؤثر حال البقاء أما اذا لم تكن مانعة فلما ذكرنا من الدليل السالم عن مانعية تلك الأولوية أما اذا كانت مانعة فلأن تلك الأولوية المانعة عن الحاجة الى المؤثر اما أن تكون حاصلة حال الحدوث أو لم تكن. فالأول باطل؛ والا لزم استغناء الممكن عن المؤثر حال الحدوث عملا بالمانع، فتعين الثانى واذا لم تكن حاصلة حال الحدوث فهى أمر حصل حال البقاء ولولاه لما حصل الاستغناء الموجب لاستمرار الباقى. فالباقى حال بقائه فى استمراره محتاج الى المؤثر والعلة فوجب استمراره وبقاؤه ولا معنى لاحتياج الباقى الى المؤثر الا ذلك.\r«قال: احتجوا بأن المؤثر حال بقاء الأثر اما أن يكون له فيه تأثير أم لا؛ الى آخره».\r«أقول: تقرير هذا السؤال أن يقال لو افتقر الباقى حال بقائه الى المؤثر فالمؤثر اما ان يكون له فيه تأثير أو لا يكون وكلاهما محالان. أما الأول فلأن التأثير يستدعى حصول أثر فالأثر الحاصل منه اما أن يكون هو الوجود الّذي كان حاصلا قبل ذلك واما أن يكون أمرا جديدا.\rالأول محال لامتناع تحصيل الحاصل. والثانى أيضا محال لأنه حينئذ يكون تأثير المؤثر فى أمر جديد لا فى الباقى. وقد فرضنا انه أثر فى الباقى هذا خلف وأما الثانى وهو أن لا يكون فيه تأثير فهو أيضا باطل لأنه حينئذ لا يكون هناك"], [25, "أثر لامتناع حصول الأثر بدون التأثير واذا لم يحصل فيه منه أثر كان مستغنيا عن المؤثر وقد فرضنا افتقاره هذا خلف.\r«قال: والجواب لا نعنى بالتأثير تحصيل أمر جديد بل بقاء الأثر بقاء المؤثر.\r«أقول: توجيه هذا الجواب ان يقال لا نسلم انحصار الأثر فيما ذكرتم، فانه لا يلزم من عدم كون الأثر الوجود الّذي كان حاصلا أن يكون أمرا جديدا لجواز أن يكون بقاء الموجود الحاصل. فان المعنى باحتياج الباقى الى المؤثر هو أن يبقى الأثر ببقاء المؤثر لا انه حصل هناك أمر جديد.\rولقائل أن يعود ويقول: بقاء الأثر اما أن يكون أمرا حاصلا أو لم يكن. والأول يوجب تحصيل الحاصل والثانى يقتضي أن يكون التأثير فى أمر جديد لا فى الباقى والأولى فى الجواب ان (58 ـ 1) يختار أن التأثير فى أمر جديد وهو بقاء الأثر واستمراره فى الزمان الثانى ولا معنى لتأثير المؤثر فى الباقى سوى ذلك» (9).\rنشير هنا كما أشرنا سابقا الى مدى الدور الّذي لعبه المحصل فى تطوير علم الكلام لمن جاء بعده من المفكرين المتكلمين. والمثالى الّذي أخذناه هنا من المحصل هو البحث عن علة الحاجة الى المؤثر هل هى الامكان أو الحدوث أو هما معا كما أضافه الكاتب القزوينى فى شرحه نقلا من كتب الرازى (10) وكل من ابن أبى الحديد ونصير الدين الطوسى والقزوينى وجد شيئا أو رأى حاجة الى الايضاح فى افادة الرازى ورأى أن يضيف ذلك مع الرغم باطلاع كل من تأخر منهم لمن سبق.\rوفى الحقيقة وان كنا نرى ان شروحهم وبياناتهم تتفق أحيانا فى المعنى ولا\r__________________\r(9) المغصل في شرح المحصل لعلى بن عمر الكاتب القزويني (56 ـ ب ـ 58 ـ 1 مكتبة راغب باشا الرقم 791.)\r(10) الاربعين للرازي، ص 7، حيدر آباد 1353، المطالب العالية 1/ 12 ـ 1، فخر الدين الرازي وآرائه الكلامية والفلسفية، محمد صالح الزركان 187."], [26, "يتركون البحث الا بمزيد من التوضيحات. وبالرغم من أن بحوثهم فى علم الكلام هى محل نقاش وجدال بين الفلاسفة والمتكلمين القدماء. فاننى أحب ان اتطرق الى تاريخ البحث بكلمات موجزة. فانا لم أصادف حتى الآن أى مفكر أو فيلسوف أو متكلم طرق باب هذا البحث بهذا الاسهاب ووضع المسألة فى هذا الأسلوب: الامكان والحدوث جنبا الى جنب ومميزات كل منهما الا فخر الدين الرازى وربما كان هو السبب لخوض الباحثين المفكرين من الفلاسفة والمتكلمين فى اتخاذ الموضوع للدراسة واعطائه أهمية كبيرة لأننا اذا قارنا هذه الشروح الثلاثة للمحصل نرى أن كل واحد منها يطيل الايضاح فى مكان ويقصر فى آخر، وغيره يعمل بالعكس يقصر فيما لا يطول فيه غيره ويطول فيما يقصر فيه غيره أو أحيانا يترك ما يطول فيه غيره دون قول أو إيضاح أو شرح. وبما أن مسألة الحاجة الى المؤثر كانت لها أهمية كبيرة، فقد أسهب فيها الشراح كلهم.\rان القارئ الكريم يرى الفرق بين كل من هذه الشروح ويستطيع أن يقارن بينها ولا أريد أن أتعرض لها بأى تعليق الا أنى أود أن ألخص البحث حسب فهمى وادراكى.\rفالمتكلمون قبل الرازى كانوا يتخذون حدوث الجواهر والاعراض كسبب أو دليل لاثبات وجود الله تعالى وما كانوا يتطرقون الى دليل الامكان بالايجاب ولا بالسلب. وسنعطى أمثلة لذلك من المفكرين والمتكلمين الذين سبقوا فخر الدين الرازى.\rأصول الدين للامام أبى منصور عبد القاهر البغدادى المتوفى 429\rالاعتقاد على مذهب السلف أهل السنة والجماعة للامام الحافظ أبى بكر البيهقى المتوفى 458.\rالشامل فى أصول الدين لامام الحرمين الجوينى المتوفى 478 والارشاد الى قواطع الأدلة فى أصول الاعتقاد له أيضا.\rأصول الدين أبو يسر محمد البزدوى المتوفى 493، الاقتصاد فى الاعتقاد لأبى حامد محمد بن محمد الغزالى المتوفى 505"], [27, "تبصرة الأدلة لأبى المعين النسفى المتوفى 508.\rنهاية الأقدام فى علم الكلام للامام عبد الكريم الشهرستانى المتوفى 548، البداية فى أصول الدين لنور الدين أبى بكر الصابونى المتوفى 580\rقلنا فيه كلام سيأتى:\rفان مسألة الامكان والوجوب لم تكن معروفة فى الفلسفة قبل الفارابى وانه قد اخترع هذين الاصطلاحين وشرحهما أبو على ابن سينا بعده ثم من جاء بعدهما من الفلاسفة أمثال أبى البركات البغدادى استعملهما فى إيضاح الاتصال أو الرابطة بين الله تعالى والكون على معنى بين الواجب الوجود والممكن الوجود. ان أول فيلسوف فى الاسلام أبو اسحاق يعقوب الكندى لم يستعمل دليل الامكان فى اثبات وجود الله تعالى؛ لأنه قد سبق الفارابى. وكان هناك طريقان فى اثبات وجود الله تعالى طريق الحدوث وهو يستند على حدوث أو وجود الجواهر أو الاعراض. وهو طريق المتكلمين الأقدمين من الرازى وطريق آخر هو طريق الامكان ويبدأ هذا الطريق من الفارابى يبتنى على امكان ماهية الكون وهو ما سوى الله تعالى. فان الله تعالى واجب الوجود وما سواه ممكن الوجود. وهاتان الطريقان كانتا منفصلتين واحدة عن الأخرى وموزعتين بين المتكلمين والفلاسفة الى ظهور فخر الدين الرازى الّذي جمع بينهما وفصلهما وبوبهما فى تآليفه. ولكن نرى صاحب نهاية الأقدام عبد الكريم الشهرستانى أول من استعمل من المتكلمين امكان الوجوب فى إيضاح وشرح الاتصال أو العلاقة بين الله تعالى والمكونات الا أنه وان كان قد ذكر الفارابى وابن سينا وأرسطو أثناء كلامه فى ذلك فهو لم يفرق أو لم يميز بين الامكان والحدوث ولا دليل الامكان والحدوث؛ ولم يناقشهما بصورة واضحة حتى أنه لم يضعهما فى صياغتهما الاصطلاحية.\rوأود هنا ان أنتقل الى ما قاله فى نهاية الاقدام بصدد اثبات وجود الله وخلقه الكون:\r«مثل أبى نصر الفارابى وأبى على الحسين بن عبد الله بن سينا وغيرهما من"], [28, "فلاسفة الاسلام، ان للعالم صانعا مبدعا وهو واجب الوجود بذاته والعالم ممكن الوجود بذاته واجب الوجود بالواجب بذاته غير محدث حدوثا يسبقه عدم بل معنى حدوثه وجوبه به وصدوره عنه واحتياجه إليه» (11).\r«فنقول للمتكلمين طريقان فى المسألة أحدهما اثبات حدوث العالم والثانى ابطال القول بالقدم. فقد سلك عامتهم طريق الاثبات باثبات الأعراض أولا واثبات حدوثها ثانيا وبيان استحالة خلق الجواهر عنها ثالثا وبيان استحالة حوادث لا أول لها رابعا» (12).\rكما نرى الشهرستانى يستعمل طريق الامكان من دون أن يشير الى أنها طريق المتكلمين أو الفلاسفة وانما خلط بين المصطلحات الفلسفية والمعانى الكلامية أو بتعبير آخر استخدم المصطلحات الفلسفية فى بيان الأدلة الكلامية».\r«فوجه تركيب البرهان منه أن نقول كل متغير أو متكثر فهو ممكن الوجود باعتبار ذاته وكل ممكن الوجود باعتبار ذاته فوجوده بايجاد غيره، فكل متغير أو متكثر فوجوده بايجاد غيره» (13).\rويقول فى مكان آخر فى تعريف الممكن ويستعمل أحيانا الجائز مكان الممكن: «والممكن معناه انه جائز الوجود وجائز العدم فيستوى طرفاه أعنى الوجود والعدم باعتبار ذاته فان أوجد فانما يوجد باعتبار موجده ولو لا موجده لما استحق الا العدم فهو اذن مستحق الوجود والعدم بالاعتبارين المذكورين» (14).\r«ثم جواز الوجود سابق على الوجود بالذات فنقول انما وجوبه لأنه كان جائز الوجود ولا نقول: انما كان جائز الوجود لأنه وجد. فجواز وجوده ذاتى\r__________________\r(11) نهاية الاقدام ص 6. نشر.\r(12) نفس المصدر 11.\r(13) نفس المصدر 15.\r(14) نفس المصدر 18."], [29, "له والوجود عرضى والذاتى سابق على العرضى سبقا ذاتيا. ثم بينا ان الجائز مستحق العدم باعتبار ذاته لو لا موجده فكان مسبوقا بوجوده ومسبوقا بعدم ذاته لو لا موجده لأن استحقاق وجوده عرضى مأخوذ من الغير واستحقاق عدمه ذاتى مأخوذ من ذاته فهو اذن مسبوق بوجود واجب ومسبوق بعدم جائز فتحقق له أول» (15).\r«ان الممكن معناه أنه جائز وجوده وجائز عدمه لا جائز وجوبه وجائز امتناعه. وانما استفاد من المرجح وجوده لا وجوبه. نعم لما وجد، عرض له الوجوب عند ملاحظة السبب لأن السبب أفاده الوجوب حتى يقال وجد بايجاده ثم عرض له الوجوب بل افاده الوجود فصح ان يقال وجد بايجاده وعرض له الوجوب فانتسب إليه وجوده اذ كان ممكن الوجود لا ممكن الوجوب» (16).\r«ان الامكان من حيث هو امكان ليس يستدعى مادة وسبقه على الموجود الحادث ليس الا سبقا فى الذهن سميتموه سبقا ذاتيا.\r«ونقول: ان كل حادث حدوثا زمنيا أو حدوثا ذاتيا على أصلكم (الفلاسفة) فانه يسبقه امكان الوجود فان الموجود المحدث قد تردد بين طرفى الوجود والعدم وهذا التردد والسبق والامكان كله يرجع الى تقدير فى الذهن والا فالشيء فى ذاته على صفة واحدة من الوجود لكن الوجود باعتبار ذاته انقسم الى ما يكون وجوده لوجوده هو له لذاته أى هو غير مستفاد له من (35) غيره. فيقال الوجود أولى به والى ما يكون وجوده لوجود هو له من غيره؛ فيقال الوجود ليس أولى به ولا أول؛ وهذا الوجود لم يتحقق الا أن يكون له أول مسبوق بوجود لا أول له؛ ويكون له فى ذاته امكان الوجود يعبر عنه بأنه مسبوق بامكان الوجود لا أنه وجود يسبقه امكان الوجود بل الوجود فى ذاته وجود الممكن؛ فقد وجد هاهنا سبقان: أحدهما سبق وجود الموجود والثانى سبق امكان الوجود» (17).\r__________________\r(15) نفس المصدر 4.\r(16) نفس المصدر 21.\r(17) نفس المصدر 34 ـ 35."], [30, "أعتقد أننا على الحق عند ما نقول ان فخر الدين الرازى هو الّذي التقى عنده الفلاسفة والمتكلمون وصاروا جنبا الى جنب فى اثبات وتثبيت المبادي الكلامية والفلسفة فى خدمة الاسلام والحضارة الاسلامية.\rففى المحصل وضع فخر الدين الرازى بحثين فى النقاش الأول هو ترجيحه الامكان على الحدوث. وظهر من النقاش أو ابداء الآراء بين الشراح على ترجيح علية الامكان على الحدوث بأن الحدوث تأخر عن العلة بمراتب اربع ولذا فان الامكان لا يتأخر الا بمرتبة واحدة ليس حينئذ نظرية الحدوث أولى عند المتكلمين؛ لأن الحدوث اذا كان متأخرا بأربع مراتب معناه يجعل الشقة بين القديم والحادث أوسع بأربع مرات ولا يفكر الانسان بقدم الكون الا اذا قطع تلك المسافة البعيدة واذا كان الامكان بمرتبة واحدة معناه أنه يلتبس على الانسان هل الكون أزلى وقديم أو حادث ومخلوق منفصل بزمان أم لا؟.\rومع كل ذلك فان الامكان يشعر أن الكون محتاج الى واجب الوجود لأن يكون موجودا حتى قبل وجوده والاحتياج سابق فى الامكان على الوجود سبقا ذاتيا كما أفاده الشهرستانى فى عباراته السابقة غاية وذهنا آنفا كما فى حياتنا اليومية نفكر بالاحتياج الى المنضدة ثم نعملها. هنا العلة الغائية موجودة قبل العلة المادية ذهنا ومتأخرة عنها تحققا يعنى تحقيق العلة الغائية متأخر عن عمل المنضدة فى الحدوث ولذلك يبدو أن علة الاحتياج متأخرة عن الحدوث لأن الشيء بعد ما يحدث نفهم أنه سبقه عدم وكان قبل حدوثه محتاجا الى المؤثر. واما فى الامكان قبل أن يخرج الى الوجود فنفهم أنه محتاج الى مؤثر سابقا ولاحقا لأنه ممكن يستوى فيه طرفا الوجود والعدم.\rفان الفارابى وابن سينا لم يقبلا سبقية الامكان على الممكن الموجود فى المبدعات وقالا انه مع الممكن الموجود وعلى هذا علة الحاجة غير سابقة فى الامكان فى الابداع (*).\r__________________\r(*) لقد شرح هذا «في الخلق عند الفارابي وابن سينا» لصاحب المقال المطبوع في انقره باللغة الشركية."], [31, "ولهذا السبب فان الرازى رجح نظرية الامكان على الحدوث والنقطة الثانية هى تأمين ومحافظة دوام الكائنات من ناحية، ومن ناحية أخرى اثبات عدم استقلالية الكائنات وانقطاعها عن واجب الوجود ودوام احتياجها إليه ليس فى وجودها فقط بل فى استمرار وجودها كذلك، وهو من دون أن يحتاج الى أدلة منفصلة أخرى. فان نظرية الامكان متضمنة اياه لأن ماهية الامكان متساوية الطرفين الوجود والعدم فاذا رجح طرف الوجود وأصبح الامكان موجودا فان الوجود لا يطرد امكانيته ولا يخرج عن الامكان وامكانيته باقية بما أن الامكان موجود فى الممكن الوجود وهو محتاج الى واجب الوجود دوما واستمرارا مثل الكهرباء للقنديل. والقنديل (المصباح) محتاج الى الكهرباء لاضاءته فى أول وجوده ودوامه. وأما هذا فانه غير موجود أو مشعور به فى الحدوث. فان الحدوث مثل النواة اذا ألقيت فى الأرض وانفلقت وظهر النبت لا تبقى النواة موجودة لأنه ما كان بالقوة أصبح بالفعل ولم يعد يسمى بالقوة. ولذلك هنا يكمن الفرق بين ما هو بالقوة وبين ما هو بالامكان. والامكان أصبح ممكنا وامكانه معه ولا يفارقه وعلى هذا فان علة الحاجة الى المؤثر اذا كان هو الامكان قد تحصل على الشيئين بشيء واحد.\rواننا نرى من المتكلمين المعاصرين من رجح نظرية الحدوث على نظرية الامكان وفى ذلك يقول الشيخ العلامة شيخ الاسلام فى الدولة العثمانية (1919 ـ 1920) مصطفى صبرى (1860 ـ 1954) فى كتابه موقف العقل والعلم والعالم من رب العالمين وعباده المرسلين:\r«ثم ان كانت الشبهة تخالجك فى مسئلة المحوج هل هو امكان المحتاج أو حدوثه فلننظر لما ذا يحتاج المحتاج الى العلة.\rفالممكن يشمل الموجود والمعدوم وهو ما دام معدوما لا يحتاج الى العلة وانما حاجته إليه ليكون موجودا وليدوم له الوجود مدة دوامه فمنشأ الحاجة اذن اتصاف الممكن بالوجود ابتداء وبقاء الا أن الموجود القديم لما لم يحتج الى علة كما حققناه تعين الوجود الحادث للحاجة فاذا اختصرته قلت الحدوث أى الحدوث المقابل للقدم لا المقابل للبقاء لأن وجود الحادث حال بقائه وجود حادث كابتدائه فلا"], [32, "يصح تمثيل الحادث المحتاج الى العلة بالبناء المستغنى بعد انشائه عن البانى فالمحوج هو حدوث الممكن لا امكانه بالرغم من أن مذهب الفلاسفة هو الثانى وبالرغم من أن بعض المتكلمين المحققين متفقون معهم فى ذلك (*). ولعل سبب خطأ الفلاسفة قولهم بقدم العالم مع امكانه واستناده الى الله وسبب خطأ أولئك البعض من المتكلمين قولهم بامكان صفات الله مع قدمها وصدورها عن الله ايجابا والكل بعيد عن الحقيقة كما عرفت (18).\rولا أريد ان أطيل فى الموضوع أكثر من اللازم واكتفى بهذا مع الاشارة الى أن القارئ يمكن له أن يرجع الى ما قيل فى الحاجة الى المؤثر هل الامكان أو الحدوث والّذي نقلناه آنفا من المحصل وشروحه ويستطيع الانسان أن يقارن ويجد الجواب من خلال اختلافهم فى المسألة:\rان منشأ أو منطلق الفلسفة الوجودية المعاصرة هو التفريق والتمييز بين الماهية والوجود أو بين ماهية الشيء ووجوده. الشيء الموجود له ماهية ووجود؛ وماهيته غير وجوده. وهذا الفرق والتمييز أو هذا المفهوم قد اكتشف من قبل الفارابى وليس له سابق فى وضع هذا المفهوم والمعنى. وعند ما يقرأ طالب الفلسفة فلسفة الوجود الحديثة يرى انها تدور على الماهية والوجود وأى واحد منهما سابق على الآخر ولكل فيلسوف له اتجاه خاص لاتخاذه واحدا منهما مبدأ له مثل جان بول سارتر الّذي يقدم الوجود على الماهية.\rوأما الفارابى وابن سينا فلا يقدمان أى واحد من الماهية أو الوجود على الآخر. وهذا مخالف لمذهبهما فى التفريق بينهما لأنه اذا كان\r__________________\r(*) بعد ان كتبت هذا، رايت «مرقاة الطارم» العالم الهند الكبير محمد انور شاه الكشميري رحمه الله يقول فيه ص 37 «والحوج الى 1 لعلة ليس هو الامكان كالذي يكون في ممكن بقي في العدم ولا حدوث في اول آن، بل وجود يكون من الغير. فالسلة هي الموجودية الحادثة وكان المراد بالحدوث هو الوجود في مقابل العسدم» (كلام الشيخ مصطفى هسري) موقف العقل ج 3 ص 327.\r(18) موقف العقل والعلم والعالم من رب العالمين وعباده المرسلين، مصطفى صبري، شيخ الاسلام للدولة العثمانية، 3/ 326 ـ 327 مصر 1950."], [33, "للماهية تقدم على الوجود معناه أن الماهية لها ثبوت أو وجود بنوع ما من الوجود حتى يثبت لها السبقية والتقدمية على الوجود وحينئذ لا تحتاج الماهية الى الوجود مرة ثانية لأن الموجود لا يحتاج الى الوجود لأن يكون موجودا وهو تحصيل الحاصل على اصطلاح الفلاسفة والمتكلمين. ولذلك فالماهية ليس لها سبقية على الوجود على خلاف ما يقوله المستشرقون فى تسميتهم ابن سينا بالداعى الى نظرية تقدم الماهية أو صاحب نظرية تقدم الماهية (باللغة التركية الماهيتجى)  Essentialist  وبهذا يظهر انهم لم يعرفوا الفارابى ولا ابن سينا على ما هما عليه من النظرية الفلسفية وهما لا يقدمان الوجود على الماهية كذلك، لأنه على ذلك يكون الشيء الموجود أو الوجود نفسه؛ اذا وجد دون ماهية فارغا عن المعنى والمفهوم؛ ويكون الوجود نفسه قائما بالوجود نفسه وهذا ينجر الى وحدة الوجود فالفارابى وابن سينا لا يقولان بهذا ولكن الفارابى وابن سينا عند ما يقولان بغيرية الماهية للوجود ولا يطبقان هذه القاعدة على الموجودات كلها وانما يقولان الماهية غير الوجود فى الأشياء أو الموجودات الممكنة وهذا هو الشرط الأول.\rوالثانى هو ان هذا التفريق بين الماهية والوجود لا يوجد فى الأعيان وانما هو فى الذهن فقط. وبمعنى آخر عند ما يتصور الانسان الأشياء أو الموجودات الممكنة يستطيع أن يتصور ان لها ماهيات مفارقة لوجودها وان وجودها غير ماهيتها فى الذهن واما اذا وجدت الموجودات الممكنة فى الخارج فلا يوجد وجودها مفارقا لماهيتها ولا منفصلا ولا منفردا عنها وانما يوجدان معا متحدان دون أى تفريق وتمييز بينهما.\rواما فى واجب الوجود فانه لا يمكن تصور التفريق بين ماهيته ووجوده عند الفارابى وابن سينا. ولذلك يقولان ليس لواجب الوجود ماهية وانما له الآنية وهى تأكيد الوجود أو له الوجود الخاص أو بتعبير آخر وجوده وماهيته شيء واحد؛ وجوده عين ماهيته وماهيته عين وجوده الخاص به. ولا يقال عندهما ماهية الواجب الوجود. واما عند المتكلمين فانهم يفرقون بين الماهية والوجود فى الواجب الوجود والممكن الوجود."], [34, "وعند الفلاسفة الاسلاميين اذا لم يكن للماهية أو الوجود أى تقدم أو سبقية على الآخر معناه هو ممكن والامكان ليس موجودا ولا معدوما ولذلك عرفوا الامكان بانه تساوى طرفى الوجود والعدم. اذا قيل انه موجود رجح طرف الوجود على العدم واذا قيل انه معدوم رجح طرف العدم على الوجود وفى كلتا الحالتين لا يبقى الامكان على تعريفه الحقيقى بتساوى الطرفين. اذا انتقض التساوى أصبح أحد الطرفين مرجحا والآخر مرجوحا.\rوعلى هذه الخلاصة الوجيزة جدا ينظر الى قول الرازى فى المحصل استنادا على هذه النظرية كيف يفند اعتراضات الحسيين ضد المبادي البديهية؛ فهو يستخدم نظرية التفرقة بين الماهية والوجود.\r«فمن المعلوم بالضرورة أن قولنا السواد اما ان يكون موجودا أو لا يكون. لا يمكن التصديق به الا بعد تصور مفهوم قولنا: السواد موجود؛ السواد معدوم لكن كل واحد منهما باطل. اما الأول فلأنا اذا قلنا السواد موجود؛ فاما أن يكون كونه سوادا هو نفس كونه موجودا أو مغايرا له» (يستند الرازى فى قوله هذا على مغايرة الماهية للوجود).\rشرح الطوسى: أقول: الكائن سوادا هو غير الكائن موجودا والسواد مغاير للموجود وذلك لأن هاهنا شيئا واحدا يقال له تارة انه سواد وتارة انه موجود فالمقول عليه منهما واحد والمقولان متغايران فاذا القسمة ان كون أحدهما عين الآخر أو مغايرا له ليست بحاصرة ويعوزه قسم آخر وهو ان يكونا متحدين من وجه على مغايرتين من جهة أخرى (19).\rشرح الكاتب القزوينى: «أقول لا حاجة له الى الشرح لكنا نجيب عنه فنقول: لم قلتم بأن التالى فى قولكم الوجود اذا كان نفس السواد لم يكن بين قولنا السواد (9 ـ ب) موجود وبين قولنا: السواد سواد؛ وبين قولنا: الموجود موجود، فرق باطل فان عندنا الفرق بين هذه الأقوال ثابت فى اللفظ\r__________________\r(19) المحصل 15 مصر 1323."], [35, "فقط واما فى المعنى فلا. قوله: لأن القولين الأخيرين لا يفيدان (*) والأول يفيد ممنوع. فان عندنا لا فرق بينها فى الافادة وعدم الافادة أصلا. وان ادعى الضرورة فى ذلك فقد ناقض، سلمنا؛ لكن لم قلتم بأن الوجود اذا كان مغايرا للماهية كان الوجود قائما بما ليس بموجود» (20).\r«فان كان الأول كان قولنا: السواد موجود جاريا مجرى قولنا: السواد سواد وقولنا: الموجود موجود. ومعلوم انه ليس كذلك لأن هذا الأخير هذر والأول مفيد (لأنه يستند على مغايرة الماهية للوجود واذا كان كذلك كان قولنا «السواد موجود» يفيد معنى للسامع. وأما اذا لم يكن التغاير بين الماهية والوجود فيكون قولنا السواد سواد لا يفيد معنى جديدا للسامع) (*).\rوان كان الثانى فهو باطل من وجهين: الأول انه اذا كان الوجود قائما بالسواد فالسواد فى نفسه ليس بموجود (لأن السواد ماهية قبل انصافه بالوجود لا يكون موجودا) والا لعاد البحث فيه ولكان الشيء الواحد بالاعتبار الواحد موجودا مرتين. واذا كان كذلك كان الوجود قائما بما ليس بموجود لكن الوجود صفة موجودة والا لثبت المتوسط بين الموجود والمعدوم وأنتم أنكرتموه فحينئذ تكون الصفة الموجودة حالة فى محل معدوم، وذلك غير معقول. اذ لو جاز ذلك لجاز أن يكون محل هذه الألوان والحركات غير موجودة وذلك يوجد الشك فى وجود الأجسام وهو عين السفسطة» (*2).\rشرح الطوسى «أقول: لا يلزم من كون المغايرة قيام أحدهما بالآخر. فانها اذا قيل الحيوان جسم لا يلزم منه قيام الجسم بالحيوان وأيضا لا يلزم من كون الوجود قائما بالسواد كون السواد فى نفسه معدوما. واذا كان السواد فى نفسه لا موجودا ولا معدوما؛ لم يعد البحث ولم يكن الشيء الواحد موجودا مرتين\r__________________\r(*) هنا يظهر ان القزويني استند على مخطوطة مخالفة النص لما عندنا لان العبارات عندنا: «لان هذا القول الاخير هذر والاول مفيد» المحصل 16، تلخيص المحصل 21 طهران 1980.\r(20) المفصل في شرح المحصل لابي على الكاتب القزويني (9 ـ ب) راغب ماشا 791.\r(*) ما بين المعفوفتين من حسين اتاي.\r(*2) المحصل: 16"], [36, "وليس الوجود صفة موجودة. فان ذلك يقتضي ثبوت وجود الوجود ويتسلسل ولا يلزم من سلب صفة الوجود عن الوجود ثبوت العدم له أو ثبوت الواسطة فان ذلك انما يلزم بملاحظة نفى الوجود أو العدم أو سلبهما مع مفهوم الوجود وحين نلاحظ نفس الوجود لا مع ملاحظة الغير لم يلزم ذلك ولا يلزم من ذلك كون الألوان والحركات فى محل غير موجود. فان كون الوجود حالا فى محل غير موجود ليقتضى كون اللون والحركة حالين فى محل غير ملون ولا متحرك وظاهر ان جميع ما قاله فى هذا الموضع خبط لا يليق ايراده بأمثاله (21).\rوهذا اذا راجعنا التعليقات المنسوبة الى ابن أبى الحديد حيث يقول فيها: «فالاشكال على ان وجود السواد ان كان هو كونه سوادا كان قولنا السواد ليس بموجود جاريا مجرى قولنا: السواد ليس بسواد وهذا متناقض وان كان وجوده زائدا (على الماهية) من وجوه: منها انه يلزم قيام الوجود الّذي هو صفة موجودة بالماهية المعدومة وهو محال. ومنها ان سلب الوجود عن ماهية السواد لا يمكن الا اذا تميز السواد عن غيره. وكل ما يتميز عن غيره فله تعين فى نفسه وكل ما له تعين فى نفسه فله ثبوت فى نفسه. فالسواد لا يمكن سلب الثبوت عنه اذا كان ثابتا فى نفسه ويكون حصول الوجود له شرطا فى سلب الوجود عنه هذا خلف. ومنها انا سنقيم دلالة فى مسئلة ان المعدوم ليس على امتناع خلو الماهية عن الوجود وعلى هذا يستحيل الحكم على الماهية بالعدم. فظهر انه ليس لقولنا السواد موجود، السواد معدوم، مفهوم محصل. فامتنع صحة التصديق بأن السواد اما أن يكون موجودا أو معدوما (22).\rشرح الكاتب القزوينى:\r«قوله: لأن السواد حينئذ يكون معدوما والا لعاد البحث فيه ولكان الواحد موجودا مرتين. قلنا: لا نسلم وانما يلزم ذلك ان لو كان موجودا بوجود مغاير لهذا الوجود، اما اذا كان موجودا بهذا الوجود فلا يلزم شيء مما ذكرتموه وعندنا\r__________________\r(21) المحصل 16 (متن والهامش).\r(22) تعليقات ابن ابي الحديد على المحصل 112 ـ ب جامعة استانبول برقم 3297."], [37, "السواد موجود بهذا الوجود. لم قلتم بأنه ليس كذلك؛ لا بد له من دليل» (23).\rالمحصل:\r«الثانى انه اذا كان الوجود مغايرا للماهية كان مسمى قولنا السواد غير مسمى قولنا موجود فاذا قلنا السواد موجود بمعنى ان السواد هو موجود كان ذلك حكما بوحدة الاثنين وهو محال. فان قلت ليس المراد من قولنا: السواد موجود هو ان مسمى السواد هو مسمى الوجود، بل المراد منه أن السواد موصوف بالموجودية. قلت: فحينئذ ينتقل الكلام الى مسمى الموصوفية بالوجود فانه اما ان يكون مسمى السواد هو مسمى الموصوفية بالوجود فحينئذ يكون قولنا السواد موصوف بالوجود جاريا مجرى قولنا: السواد سواد. واما ان يكون مغايرا له؛ فالحكم على السواد بأنه موصوف بالوجود حكم بوحدة الاثنين؛ الا ان يقال المراد من كون السواد موصوفا بالوجود انه موصوف بتلك الموصوفية. وحينئذ يعود التقسيم فى تلك الموصوفية الثانية. فاما أن يتسلسل وهو محال أو يقتضي رفع الموصوفية وحينئذ يبطل قولنا: السواد موجود على التقدير كون الماهية غير الموجودية (24).\rشرح الطوسى:\r«أقول لو كان السواد والوجود متغايرين مطلقا للزم الحكم بوحدة الاثنين لكن هما ليسا كذلك؛ وليس المراد أيضا ان مسمى السواد مسمى الوجود ولا أن السواد موصوف بالموجودية أو موصوف بتلك الموصوفية حين يعود اما التكرار أو وحدة الاثنين بل المراد أن الشيء الّذي يقال انه سواد هو تعينه الّذي يقال له انه موجود وذلك هو القسم الخارج من قسميه اللذين أوردهما» (25).\rشرح الكاتب القزوينى لنفس النص:\r«قوله فى الوجه الثانى ان الوجود لو كان مغايرا للسواد لكان قولنا\r__________________\r(23) المفصل 9 ـ ب.\r(24) المحصل 16 مصر 1323.\r(25) المحصل 16 هامش."], [38, "السواد موجود حكم بوحدة الاثنين، ممنوع. لأن المراد من قولنا السواد موجود ليس هو أن حقيقة السواد هى حقيقة الموجودية بل المراد ان الذات التى يصدق عليها أنها سواد يصدق عليها أيضا أنها موجودة ولا امتناع فى صدق الأمور المتغيرة على ذات واحدة. وتحقيق ذلك يرجع الى تحقيق معنى الجمل والوضع وقد بيناه فى كتبنا المنطقية. فليطالع فيها وبعد احاطتك بهذا لا يخفى عليك فساد ما قاله بعد هذا من السؤال والجواب» (26).\rلا أرى حاجة للاطالة فى المقارنة بين المحصل وشروحه وانما أردت أن أجلب الانتباه الى بعض المسائل الفلسفية الكلامية عند المسلمين فى العصور الوسطى حيث انها تحافظ على حيويتها فى الفلسفة المعاصرة. وأحببت أن أذكر نقد الشراح للمحصل لتبين درجات فهمهم وادراكهم المسائل التى نقدوها أولا ودرجات الأخطاء التى وقع فيها فخر الدين الرازى ثانيا، ودرجة قيمة المحصل العلمية ثالثا. والشيء الّذي يؤسف عليه اننا لم نحصل على كل الشروح للمحصل ونرجو أن تظهر للوجود فى المستقبل وعندى أربعة شروح.\r1 ـ الشرح الّذي قام به تلميذ فخر الدين الرازى، وهو قطب الدين أبو اسحاق ابراهيم بن على محمد السلمى قتل فى نيسابور سنة 168 ه‍، 1221 م من قبل التتر الذين احتلوا تلك المدينة فى تلك الآونة (27) لكن هذا الشرح ناقص اذا انه وصل الى القسم الثانى فى الصفات عند شرح المسألة السادسة فى قوله:\r«واما القسم الثانى فهو أن يكون حاصلا فى مكان غير معين فى نفس الأمر فهو محال بالضرورة اما القسم الثالث فهو ان يقال ان كان مساويا لغيره من الأمكنة أو لا يكون مساويا لغيره من الأمكنة فكما جاز حلول الله تعالى فيه جاز حلوله فى غيره من الأمكنة لأن ما جاز على أحد المثلين جاز على مساويه فيفتقر\r__________________\r(26) المفصل شرح المحصل للقزويني (9 ـ ب).\r(27) وكان اصله معربيا وائعا انتقل الى مصر وافام بها مدة ثم سافر بعد ذلك الى بلاد العجم واشتغل على فخر الدين خطيب الرى وكان من اجل تلاميذه ابن الخطيب وصنف كتبا كثيرة في الطب والحكمة وشرح الكليات باسرها من كتاب القانون لابن سينا وكان يفضل المسيحي وابن الخطيب على الشيخ ابي على ابن سينا (عيون الاناء لابن ابي اصيبعة 2/ 45 ـ 46 مصر 1957، حسن المحاضرة لجلال الدين السيوطي 91/ 412 القاهرة 1299. عمر رضا كحالة معجم المؤلفين 91/ 318)."], [39, "حصوله فى ذلك المكان المعين الى مخصص أو لا يفتقر إليه والثانى محال والا لزم رجحان الممكن لا لمرجح ولأن مكانه تعالى ان ساوى سائر الأمكنة كان اختصاصه به دون سائر الأمكنة الى آخر (28) نبذة من شرحه.\r«التفسير هذا هو الوجه الثانى لبيان استحالة حصول الاله فى المكان والجهة. وتقريره ان نقول لو كان الرب تعالى حاصلا فى مكان معين فاما ان يحصل فى جميع الأمكنة، أو فى مكان غير معين أو مكان معين والأقسام بأسرها ممتنعة.\rفيمتنع القول بكونه حاصلا فى المكان، وانما قلنا يمتنع حصوله فى الأمكنة لذاته حقيقة. أما أولا فلأنه يلزم مداخلا للأجسام وبطون الحيات والكلاب وتعالى الله عنه علوا كبيرا.\rوأما ثانيا فلأنه يلزم أن يكون ذا مقدار ما بالضرورة فيكون مركبا؛ وكل مركب ممكن لذاته فواجب الوجود لذاته ممكن لذاته هذا خلف ...\rواما ان افتقر الى مخصص ومرجح فذلك المخصص اما أن يكون موجبا أو مختارا والأول محال والا لزم رجحان أحد المثلين على الآخر لا لمرجح فى الموجب ولا علة فهو محال بالضرورة وباتفاق العقلاء. فانهم وان اختلفوا فى وجود ذلك بالنسبة الى القادر المختار ولكنهم اتفقوا على امتناعه فى الموجب والعلة. والثانى أيضا محال وهو أن يكون المخصص أيضا مختارا لأن كل ما كان واقعا بالاختيار فلا بد وان يكون حادثا فيلزم ان يكون حصول الا له فى المكان حادثا وهو محال. والله أعلم بالصواب تم الكتاب بحمد الله وحسن توفيقه والصلاة على محمد خير خلقه» (29).\rوهذا هو آخر شرح قطب الدين المصرى وفيه أيضا اسلوب وطراز إيضاحه\r__________________\r(28) شرح قطب الدين 214 ـ ب راغب باشا 792 الموافق للمحصل ص 113 مصر 1323.\r(29) شرح قطب الدين المصري 214 ـ 1، راغب باشا 792 وقع الفراغ من تحريره يوم الجمعة غرة شهر ربيع الآخر سنة خمس وعشرين وستمائة في المدرسة الصلاحية بمدينة دمشق حرسها الله من كل سوء على يد العبد الفقير الى رحمة الله القدير على بن عمر بن علي القزويني."], [40, "وشرحه وهو يبين درجة بيانه ومستوى علمه. وللمقارنة مع الآخرين انقل هنا بعض الجمل من الطوسى وانه مطبوع قديما ويمكن المراجعة على تمامه.\rشرح الطوسى على هذه العبارة فى المحصل: «أقول جميع المجسمة اتفقوا على انه تعالى فى جهة وأصحاب أبى عبد الله بن الكرام اختلفوا فقال محمد ابن الهيصم انه تعالى فى جهة فوق العرش لا نهاية لها والبعد بينه وبين العرش أيضا غير متناه .. وهاهنا قسم آخر وهو ان يكون خلاء لو لا الجسم وقد مر فيه ما كان ينبغى أن يقال فيه والمعتمد منها ان الكائنة فى الجهة قابل للقسمة والاشكال غير منفك من الأكوان وكل ذلك محال فى حق واجب الوجود» (30).\rيقول قطب الدين فى مقدمة شرحه: «فان كتاب المحصل اشتمل على عموم مباحث القدماء من المتكلمين واحاط بمجامع كلمات الحكماء المتقدمين والمتأخرين وسألنى ...\rالامام العالم الأفضل الأمجد فخر الملة والدين ركن الاسلام والمسلمين ادام الله ... واسبغ عليه انعامه بشرح مشكلاته وإيضاح معضلاته فأجبته الى ما التمس لوجوه: الأول أنى رأيت أهلا لما سأل وأن لا أقف على بحث الحكماء وإلغائهم بنهاية أقدام العلماء. والثانى لما تفرد له عندى من الأيادى السالفة والإنعامات الوافية. والثالث بما ورد من التهديد والترجى والوعيد من منع أهل العلم. واستخرت الله تعالى وشرعت فى تفسيره طلبا للثواب وزخرا ليوم الحساب وسألته ان يهدينى سواء السبيل (31).\rلقد ذكر نصير الدين الطوسى شرح قطب الدين المصرى بقوله: هكذا فسر قوله تلميذه قطب الدين المصرى (32) يفيد انه قد قرأ شرح القطب واستفاد منه.\rوفى نفس الوقت نرى على بن عمر الكاتب القزوينى قد استنسخ شرح قطب الدين المصرى كما يظهر من مخطوطة راغب باشا رقم 792، ومع ذلك فانه ذكره\r__________________\r(30) تلخيص المحصل ص 114 مصر 1323.\r(31) شرح قطب الدين (1 ـ ب) راغب باشا 792.\r(32) المحصل 77 هامش مصر 1313."], [41, "أيضا فى شرحه للمفصل بقوله «أقول قال الامام قطب الدين المصرى رحمه الله فى هذا الجواب نظر» (33).\rفان لعز الدين عبد الحميد بن هبة الله بن أبى الحديد تعليقة على المحصل على ما ذكره صاحب كشف الظنون (34) وفوات الوفيات لابن شاكر الكتبى (35).\rيوجد بأيدينا مخطوطة فى جامعة استانبول تحت الرقم 3297 من ورقة 374 ـ ب الى 464 ـ ب، المنسوبة الى عبد الحميد بن أبى الحديد الا انه بين هذه الأوراق نسختان الأولى تبدأ بقوله: «أحمد الله على نعمه التى التوفيق بحمده عليها محسوب منها واشهد بتوحيده وعدله شهادة أرجو أن أنطق بها يوم اسئل عنها واصلى على رسوله وأمينه وأصحابه القائمين بنصره ودينه ثم أى (انى) متتبع فى هذا الكتاب الرازى الأشعرى المعروف بالمحصل وجار فى ذلك على منهاجى فى تتبع كتبه الكلامية وتصفحها مع تجنب التكرير وبذل الجهد فى الاتيان فى كل تعليق بما لم آت به فى التعليق الّذي قبله والاضراب على كثير من الستة (كذا) التى قد اشتهرت واشتهر الكلام عليها تعويلا على بسط القول فيها ... مسئلة فى اكتساب التصورات قوله عندى ... أقول» (36). وتنتهى بقوله: «وهذا آخر كلامنا فى هذا الكتاب ونحن نسأل ان يجعل ما ذكرناه حجة لنا لا علينا ... وافق الفراغ من نسخه ثامن شهر شعبان المبارك سنة ثمان وسبعين وستمائة. وصلى الله على سيدنا محمد النبي وآله الطاهرين لله الحمد (37).\rومن ميزة هذا الشرح أنه يذكر مسئلة ويعطى من نفسه عنه انارة للبحث ثم ينقل قول الامام ب «قال» ثم يجيب بأقول. ولكن فى غير هذا يخلط أحيانا\r__________________\r(33) شرح المحصل لعلى بن عمر الكاتب القزويني (ورق 83 ـ ب) راغب باشا 792.\r(34) كشف الظنون 2/ 1614 فان الدكتور صالح الزركان قد وقع في خطا السفل او الطبع عندما ذكر لقب عز الدين لعبد الحميد كانه ابنه مثل قوله عز الدين ابن عبد الحميد انظر في كتابه فخر الدين الرازي وآراؤه الكلامية والفلسفية ص 93.\r(35) فوات الوفيات 1/ 519.\r(36) المخطوطة 3297 (374 ـ ب) جامعة استانبول.\r(37) تفس المخطوطة (441 ـ 1)."], [42, "كلام الامام بكلامه نفسه. وهناك ميزة أخرى وهى قوله: «من كلام ابن أبى الحديد على المحصل» (38).\rان القسم الثانى من نفس المخطوطة يبدأ مباشرة من نفس الصحيفة بقوله: قال فى المحصل فى باب نفى اثبات التصورات تعريف الماهية .. أقول لمطالب ان يطالبه ... » (39).\rفانى أرى أن القسم الأول والثانى هما لنفس المؤلف وهو ينبغى أن يكون معتزليا لما فيهما من أمثال هذه العبارات «على طريقة شيخنا أبى الهاشم» (40).\r«فى اثبات النبوة أعلم أن أصحابنا قد أجمعوا على ان من لا يقول بالعدل لا يمكنه اثبات النبوات» (41). ذهب شيخنا أبو الحسين الى استحالة ذلك وذهب جمهور المتكلمين الى جوازه (اعادة المعدوم) (42). واعلم انه لو لا ان تكون هاتان المسألتان من الأصول الخمس عند صاحبنا لم نذكرها (43) وفى القسم الثالث أقول أنهم لا يحدونها بذلك لأن صفات الأجناس عند أصحابنا كالجوهرية (44). هذا شيخنا أبو إسحاق بن عباس وهو جليل القدر بين المتكلمين وقد حكى هذا القول عنه شيخنا أبو الحسين (45).\rوفى القسم الثانى من المخطوطة نفسها نجد قوله: «فقد تكلمنا فى الأعراض على المحصل فى هذا الموضع بما فيه كفاية» (46) «وقد ذكرنا فى التعليق على المحصل» (47).\r__________________\r(38) نفس المخطوطة (402 ـ 1)، (405 ـ 1).\r(39) نفس المخطوطة (441 ـ 1).\r(40) (425 ـ 1).\r(41) 421 ـ 1.\r(42) 428 ـ 1.\r(43) 439 ـ ب.\r(44) 454 ـ 1.\r(45) 459 ـ 1.\r(46) 445 ـ 1.\r(47) 448 ـ ب."], [43, "ونستنتج من هذا كله بأن مؤلف هذه المخطوطة من أولها الى آخرها هو مؤلف واحد وانما استدرك بالقسم الثالث ما تركه فى القسم الأول. وبما انه على أغلب الظن والأستاذ محمد بن تاويت الطنجى رحمه الله أيضا كان يعتقد ان المخطوطة من تعليقات ابن أبى الحديد وبما انى لم استطع الحصول على نسخة أخرى من هذا المخطوطة وهى كادت أن تكون غير معروفة أحب أن أنقل هنا نبذة من كلامه فى نقد المحصل وصاحبه وإيضاحاته فى بعض المسائل المهمة كذلك فان ابن أبى الحديد علق على قول الرازى فى مسئلة صفة العلم والقدرة لله تعالى بقوله: «مسئلة فى كونه تعالى عالما هل هو لذاته أم بعلم قديم قال صاحب الكتاب أهم المهمات فى هذه المسألة الكشف عن محل النزاع» (48). «أقول ان هذا الموضع عن (الّذي) ذكرته فى الرسالة النظامية واعترضته واشعب القول فيه ولما لم يكن لائقا أن يتكلم على هذا الموضع فى كتاب (كذا) عن المحصل ويضرب عن ذكره فى الكتاب الموضوع الاعتراض (كذا) على المحصل خاصة؛ تعين ان يتكلم فيه هاهنا. ولا بد من تقديم مقدمات «منها الفرق بين الذات والصفات وأنا أذكر فى هذا الموضع تفصيلا نافعا فاقول: (49) واطال ابن أبى الحديد هنا وكتب تسع صفحات ونصف صحيفة. فانى انتخبت منها المقدمات السادسة والسابعة والثامنة والتاسعة وهى عشر مقدمات على حسب ترقيمه. وفى المخطوطة يأخذ الصفحات التالية 412 ـ ب ـ 417 ـ ا.\r«المقدمة السادسة فى تحقيق مذهب مثبتى الأحوال عن أصحابنا فى هذه المسألة فهم الشيخ أبو هاشم رحمه الله وأصحابه، مذهبهم ان البارى تعالى عالم وكونه عالما صفة له ومرادهم بالصفة هاهنا الحال. وهذه الصفة تقتضيها ذاته تعالى لا مجرد كونها ذاتا لأن الذوات عندهم متساوية ومماثلة فى الذاتية؛ لكن لاختصاصها بالصفة الخاصة وهى الصفة الخامسة وليست صفته تعالى بكونه عالما معللة معنى متفصل كما يذهب إليه الأشعرى ويقولون ان هذه الصفة باعتبارها تتعلق ذات البارى بالمعلومات المختلفة.\rالمقدمة السابعة: فى تحقيق مثبتى الأحوال من الأشعرية فى هذه المسألة:\r__________________\r(48) المحصل ص 131 سفلر 1 ـ 18 تعليق ابن ابي الحديد 412 ـ 1.\r(49) تعليق ابن ابي الحديد 412 ـ ب (نقل من قوله هذا واهم المهمات ... الى يكون الله تعالى عالما، ورق 412 ـ 1."], [44, "هو، لا يقولون مثل قول شيخنا أبى هاشم وأصحابه الا أنهم لا يجعلون المقتضى لتلك الصفة ذاته تعالى لا مجرد كونها ذاتا مخصوصة بنفسها ولا باعتبار الصفة الأخرى الخاصة التى يسميها أصحابنا الخامسة بل يجعلون المقتضى لتلك الصفة معنى قديم غير معلل بعلة لا ذات البارى ولا غيرها بل هو موجود لذاته كما ان ذات البارى تعالى موجود لذاتها. الا أنها تقتضى حصول صفة العالمية لذات البارى سبحانه ولو لا هذا المعنى لم تكن ذات البارى سبحانه عالمة. وكذا القول فى القدرة والحياة وغيرها من المعانى وهذا قول ابن الباقلانى والجوينى وغيرهما فمن يستحق أن يخاطب من هذه الطائفة. وكل قول يقوله من ينتمى الى الأشعرية غير هذا القول فى هذه المسألة. اما أن لا يصح واما (411 ـ ا) ان ترجع الى مذهب الشيخ أبى الحسين رحمه الله.\rالمقدمة الثامنة فى تحقيق قوم نفاة الأحوال من أصحابنا فى هذه المسألة: مذهبهم فى هذا الموضع مضطرب جدا لأنهم لا يثبتون للبارى تعالى بكونه عالما صفة ولا معنى هو ذات فيصعب عليهم تفسير مفهوم قولنا انه عالم. فقال الشيخ أبو على وأبو بكر بن إخشيد وأصحابهما مفهوم كونه عالما، ان له معلوما ومفهوم كونه قادرا ان له مقدورا وليس للذات من هذا المفهوم صفة ولا معنى. وقد تكلم الشيخ أبو الحسين رحمة الله عليهم (كذا) فى التصفح بما ليس هذا موضع ذكره.\rالمقدمة التاسعة فى تحقيق قول الشيخ أبى الحسين رحمه الله فى هذه المسألة مذهبه: ان البارى تعالى عالم ومعنى ذلك كونه متبينا للأشياء وهذا ليس أمر (ا) زائد (ا) على ذاته مضافا (ا) إليها وذاته يقتضيها بحقيقتها المخصوصة المخالفة لسائر الحقائق بنفسها فتارة يسميه تعلقا والمقصود انه أمر ثبوتى ذاته تعالى موصوفة به يتجدد بتجدد المعلومات وهو متعدد ليس بمتحد وهل هو أمر له اضافة أو هو نفس الاضافة. هذا مما يختلف قوله فيه.\rوليس للبارى تعالى من كونه قادرا صفة راجعة الى ذاته عنده كما له من كونه عالما لأنه لا معنى لكونه قادرا الا صحة الفعل ووقوعه على دواعيه تعالى وصحة العقل أمر راجع الى الفعل. فذاته تعالى يقتضي كون الفعل صحيحا منه وموقوفا"], [45, "على دواعيه، فليس له بذلك صفة كماله بكونه عالما صفة وقد تكلمت على هذا الموضوع فى غير هذا الكتاب.\rوثبت أن ما فرق به الشيخ أبو الحسين رحمه الله من الموضعين ليس بجيد. وقلت أن ذاته تعالى لا تقتضى صحة الفعل، الصحة الراجعة الى ذات الفعل لأن تلك الصحة ذاتية للفعل ومن لوازمه. ولو قدرنا انتفاء كل قادر فى الوجود لكان الممكن ممكنا والممتنع ممتنعا. فاذا ذاته تعالى يقتضي صحة صدور الفعل الممكن عنه فهما صحتان أحدهما صحة الممكن فى نفسه والآخر صحة وجوده بالفاعل. فالصحة الثانية لا بد من اثباتها لذاته تعالى، فلا بد من اثبات صفة له بكونه قادرا راجعة الى ذاته كما قال فى كونه عالما لا فرق بين الموضعين» (50).\r«مسئلة» فى «التحسين والتقبيح»\r«ونقول لا نسلم انه تعالى أخبر فى حياة أبى لهب أنه لا يؤمن. ولم لا يكون سورة تبت انزلت بعد موت أبى لهب. المحال انما يلزم لو كان تعالى قد اخبر وأبو لهب حي بأنه لا يؤمن (*) وهو مع هذا مكلف ان يؤمن واذا كانت قد أنزلت بعد موت أبى لهب فقد اندفع الاشكال.\rان قيل فيجب على هذا ان يقولوا أنه تعالى ما أخبر عن أقوام بأعيانهم انهم لا يؤمنون وهم أحياء.\rقيل كذلك يقول. انه لم يخبر عن أحد أنه لا يؤمن وهو فى حال الاخبار عنه مكلف بأنه يؤمن. ان قيل: فما قولكم فى قوله تعالى: (إِنَّ الَّذِينَ كَفَرُوا سَواءٌ عَلَيْهِمْ أَأَنْذَرْتَهُمْ أَمْ لَمْ تُنْذِرْهُمْ لا يُؤْمِنُونَ) قيل: ان هذه الآية وردت فى حق أقوام مخصوصين. وقوله تعالى (لا يُؤْمِنُونَ) اعم من قوله: لا يؤمنون مدة حياتهم. ومن قوله: لا يؤمنون الآن. لأنه يمكن تقسيمه الى كل واحد من القسمين ومورد التقسيم مشترك بين القسمين. فلم لا يجوز أن يكون المراد:\r__________________\r(50) ابن ابي الحديد، 415 ـ ب ـ 416 ـ 1.\r(*) في الاصل: يؤمن لا: والمعنى: لا يؤمن."], [46, "لا يؤمنون الآن فقط، ولا يكون اخبارا عن انتفاء الايمان منهم طول حياتهم فلا يلزم المحال» (51).\rمن جملة نقد ابن أبى الحديد لفخر الدين الرازى.\r«ثم ان صاحب الكتاب تكلم فى اثبات النبوة المحمدية واستدل عليها بوجوه ثم اعترضها باعتراضات كثيرة ولم يجب عنها ... وقد وقفت على رسالة لبعض قدماء الاسماعيلية يذكر فيها فوائد التعليم. واظن صاحب الكتاب وقف عليها وحسنت عنده فنقلها الى هذا الموضع لأنى رأيت كثيرا من ألفاظ الرسالة بعينها منقولة فى المحصل: فمن جملتها قوله:\r«ان كل جنس تحته أنواع فانه يوجد فيما بين تلك الأنواع نوع واحد هو اكملها. وكذا الأنواع بالنسبة الى الأصناف بالنسبة الى الأشخاص بالنسبة الى الأعضاء وأشرف الأعضاء ورئيسها هو القلب وخليفته الدماغ ومنه يثبت القوى (*) (434 ـ ا) على جميع جوانب البدن. فكذا أنواع الانسان لا بد فيه من رئيس والرئيس اما ان يكون حكمه على الظاهر فقط وهو السلطان أو على الباطن فقط وهو العالم أو عليهما معا وهو النبي أو الامام. فالنبى يكون كالقلب فى العالم والامام كالدماغ وكما أن القوى المذكورة انما تفيض من الدماغ على الأعضاء وكذا قوة البيان والتعليم انما تفيض بواسطة الامام المعلم الّذي هو خليفة النبي على جميع أهل العالم وهذا الكلام محض مذهب التعليمية وهم الاسماعيلية من الشيعة. وكثيرا ما اعجب من هذا الرجل فى كتبه ومصنفاته وخصوصا فى هذا الكتاب فانه وضعه على قاعدة الايجاز والاختصار ثم توخى المواضع المهمة فى صناعة الكلام فاختصرها حتى أحل (*2) بفهمها بالكلية بل حذف الكثير منها وأهمله وأعرض فى مواضع شريفة عظيمة الخطر. ولم يجب عن الاعتراض قصدا للايجاز بزعمه ثم اطال فى مواضع كثيرة لا يناسب اطالته فيها الايجاز فى غيرها ولا يقتضي قاعدة الكتاب وأمثاله من المختصرات الاسهاب فيها ...\r__________________\r(51) نفس المخطوط، 427 ـ ب.\r(*) نفس المخطوط 422 ـ ب كذا في الاصل، والاصح: تنبت.\r(*2) والاصح: اخل"], [47, "«والكلام فى تعديد الآيات الدالة على انا فاعلون على رأى المعتزلة وهو منقول من رسالة مفردة للصاحب أبى القاسم ابن عباد أحد جوامعها فنقلها الى هذا الكتاب ... وعلى انه قد وهم فى عدد الأئمة الاثنا عشرية وفى انسابهم فى موضعين فانه اسقط الامام العاشر عندهم وهو على الهادى بن محمد على بن موسى ... وقال ان من الناس من جعل الامام بعد محمد بن على بن موسى فى أبيه (ابنه) جعفر وليس جعفر هو ابن محمد كما توهمه بل هو ابن على الهادى بن محمد ... (434 ـ ب) فحسب أحد عشر باثنى عشر هكذا رأيته فى جميع النسخ التى وصلت إلينا الى بغداد بهذا الكتاب ووقفنا عليها ولعله غلط الناسخ والا فالرجل ان لا يكون يعرف ذلك ... » (52).\rولكن اذا رجعنا الى نسخ المحصل الموجودة لدينا من مخطوطة ومطبوعة لا نرى العبارة التى ذكرها ابن أبى الحديد آنفا وانما نرى فى المحصل عندنا هذه العبارة الآتية:\r«فالذين استقر عليه رأيهم ان الامام بعد الرسول عليه السلام على بن أبى طالب ثم ولده الحسن ثم أخوه الحسين ثم ابنه على ثم ابنه محمد الباقر ثم ابنه جعفر الصادق ثم ابنه موسى الكاظم ثم ابنه على الرضا ثم ابنه محمد التقى ثم ابنه على النقى (الهادى) (53) ثم ابنه الحسن الزكى ثم ابنه محمد وهو القائم المنتظر» (54).\rوعدا ذلك نستطيع أن نقول ان نقد ابن أبى الحديد مصيب وغير مصيب.\rواحب أن اقرأ شيئا من النقد لابن أبى الحديد لأنى وجدت افادته شيقة ومفيدة على الأقل من ناحية تسبق العلوم ودرجة فهمهم العلم والدرجة العلمية وكيف كانوا يقيمون علوم العلماء وتآليفهم العلمية.\r«وما زال أهل العلم يستهجنون ان يمزج علم بعلم آخر ويجمع بين الكتب بين العلمين ويعدون ذلك قصورا فى صناعة التصنيف وقال الشيخ أبو الحسين\r__________________\r(52) نفس المخطوط (434 ـ 1 ـ 434 ـ ب).\r(53) شرح تجريد العقائد للعلامة الحلي (المتوفى 726) ص 250 مطبعة العرفان صيدا / 1352.\r(54) المحصل ص 177 مصر 1323."], [48, "رحمه الله فى خطبة المعتمد انى انما صنعته بعد استقصاء فى شرح العمد لأنى تكلمت فى شرح العمد فى كثير من المباحث الكلامية اتباعا لمصنف العمد وهو قاضى القضاة فاستهجنت ذلك ورأيت الى (ان) العلوم المختلفة لا يجوز أن يجمع بينها فى الكتاب الواحد، فدعانى ذلك الى تصنيف المعتمد ... (435 ـ ا) وانما حذا (يعنى الرازى) فى ذلك حذو الغزالى فى المستصفى فانه صنف كتابا فى أصول الفقه مزجه بعلم المنطق ... قوم غلب حب العلوم الحكمية عليهم ... ولا أقول هذا مبالغة فان هذا المصنف قد فسر القرآن العزيز، كتاب كبير نحو عشر مجلدات أكثرها على القواعد الحكمية وهو من عجائب الدنيا وما رأينا قبله مثله. فانا عهدنا كتب التفسير يقال فيها عند ذكر الآية قال على وابن عباس وهذا عند ذكر الآية يقول قال الفارابى وابن سينا ولا قوة الا بالله (55).\rانه من المفيد والنافع ان يعرف المسائل التى خالف فيها فخر الدين الرازى مذهبه الأشعرى على قلم لابن أبى الحديد بقوله: «وقبل ان نختم الكتاب نعقد فصلا نذكر فيه المسائل التى فارق فيها مذهب الأشعرية وأخذ فيها بقول الشيخ أبى الحسين رحمه الله وهى «كو» مسئلة ف (1) ـ ليس النظر معنى زائدا على ترتيب العلوم والظنون بل هو مجرد ترتيب علوم أو ظنون فى الذهن ليتوصل بها الى علم أو ظن.\r(ب) النظر الفاسد يستلزم الجهل.\r(ج) ليس الوجود صفة زائدة على الذات وهذا وان قال به الأشعرى نفسه لكن جمهور أصحابه انكروه.\r(د) ليس حدوث الحادث علة الحاجة الى المحدث بل جواز الحدوث هو العلة.\r(ه) ليس حصول الجوهر فى الحيز معللا بمعنى هو الكون.\r(و) ليس الحياة معنى زائدة على اعتدال المزاج وقوة الحس والحركة.\r(ز) ليس الموت معنى وجوديا يضاد الحياة.\r__________________\r(55) تعليق ابن ابي الحديد (434 ـ ب ـ 435 ـ 1)."], [49, "(ح) ليس العلم معنى يوجب كون العالم عالما ولا العلم عبارة عن حالة يتعلق المعلوم بل العلم هو التعلق نفسه.\r(ط) ليس العقل عبارة عن نفس العلم بوجوب الواجبات واستحالة المستحيلات بل غريزة يلازمها العلوم البديهية عند ارتفاع المانع.\r(ى) ليست القدرة (441 ـ ا) عبارة عن معنى زائد على صحة البنية [الصحيح البنية] أو اعتدال مزاج الأعصاب.\rيا ـ ليس العجز معنى وجوديا يضاد القدرة.\rيب ـ ليس الادراك معنى زائدا على العلم.\rيج ـ الاعراض ليست نستحيله (مستحيلة) البقاء بل يجوز بقاؤها.\rيد ـ الأجسام لا يستحيل خلوها من الألوان والطعوم والأراييح.\rيه ـ المعلول بالنوع يجوز تعليله بأكثر من علة واحدة بالشخص.\rيو ـ الموجب العقلى يجوز أن يتوقف ايجابه الأثر على شرط منفصل عن ذاته.\rير ـ الموجب العقلى يجوز أن يكون مركبا.\rيح ـ لم يثبت بحجة قاطعة أن كون الله تعالى سميعا بصيرا أمر زائد على كونه عالما.\rيط ـ لم يثبت بحجة قاطعة انه تعالى موصوف بما تزعم الأشعرية انه معنى مفرد يسمونه كلام النفس.\rكا (*) (ك) ـ ليس البارى تعالى عالما بمعنى يقتضي له كونه عالما بل ليس الا ذاته والاضافة المسماة العلم لا غير.\r__________________\r(*) الناسخ اخطا هنا وتجاوز «ك» ولكن اضع ما هو في المخطوط واصححه بين المعفوفين."], [50, "كب (كا) ـ لم يثبت بحجة قاطعة ان للبارى تعالى صفات غير هذه الصفات المتفق عليها وما أثبته الأشعرى وأصحابه من اليد والوجه والاستواء وغيرها لا يصح.\rكج (كب) ـ لم يثبت بحجة قاطعة ان البارى تعالى تصح رؤيته.\rكد (كج) ـ لم يثبت بالدليل ان قدرة العبد لا تؤثر فى مقدوره اصلا كما قال الأشعرى ولا أنها لا تؤثر فى ذاته بل فى صفة زائدة على ذاته كما قاله ابن الطيب.\rكه (كد) ـ لم يثبت بالدليل ان أجزاء الأجسام البشرية تعدم ثم تعاد فى القيامة عن العدم.\rكو (كه) ـ لا يكفر أحد من أهل القبلة وان اختلفوا فى المسائل الكلامية.\rكر (كو) ـ الامامة واجبة لأنها تتضمن (أن) دفع الضرر عن النفس واجب بهذه.\rفهذه المسائل هى علم الكتاب كله. وقد بان انه رفض مذهب شيوخه فيها واعترف بفساد أقوالهم وهذا آخر كلامنا فى هذا الكتاب» (56). فان ابن أبى الحديد قد شدد نقده وزاد فى التهجين بقوله فى العبارات كما يأتى فمثلا فى نقده كلام الامام فى المحصل على التعليمية فى القسم الثانى من المخطوط. فاذا كنت قد طعنت فى الاستدلال بالتسلسل فكيف عدت إليه وتمسكت به وقد رام بعض المكلفين من اتباعه لما سمع من هذا الاعتراض ان ينتصر له فقال ان لجوابه تفسيرا سلم به من مناقضة ما قاله أولا حيث زيف كلام المتكلمين فاستدلالهم بالتسلسل» (57).\rوقال بعض من يتعصب له ويقلده فى الصحيح والفاسد لعل مراده بالعلة المتممة وهى احدى علتين لا بعينها .. » (58).\r__________________\r(56) نفس المخطوط (440 ـ ب ـ 44 ـ 1).\r(57) 447 ـ 1.\r(58) 452 ـ ب."], [51, "«والرجل (يقصد الرازى) حاطب ليل وكان غرضه التصنيف لا التحقيق. ومن نظر فى مصنفاته بعين الانصاف لا بعين الهوى والعصبية علم بعدها على التحقيق وانه كان يجمع اضغاثا من كل نوع ويقولها ولا يبالى لعلمه بالسعادة الشاملة والصيت المنتشر عنه أصاب أم أخطأ» (وتكلمنا نحن عليه فى نقض الأربعين) (59).\r«أقول: ان هذا الرجل له عادة أن يورد الأدلة غير موضعها وأنا أوضح ذلك فى هذا الموضع» (60).\r«ثم حكى شبهة لمن نفى كون البارى مريدا وهى انه اما أن يريد الشيء لغرض والأول يقضى الى كونه تعالى مستكملا بذلك الغرض. والثانى عبث وأجاب، فقال أراد (ة) الله تعالى منزهة عن الأغراض بل هى واجبة التعلق بايجاد ذلك الشيء فى ذلك الوقت بذاتها» (61).\r«أقول: هذا تصريح بأنه تعالى موجب بالذات لا فاعل بالاختيار لأنه لا يتمكن من فعل ما يخالف مقتضى الإرادة القديمة الواجبة التعلق بايجاد الأشياء فى أوقاتها فيكون تعالى كالملجإ الى تلك الأفعال المسلوب التخير والتمكن منها وقد شرحت هذا الموضع فى الرسالة الشرقية فى كشف الفلسفة الحقية شرحا لا مزيد عليه» (62).\rفابن أبى الحديد فى نقده اللاذع كأنه مملوء بالحقد وأنه ينتقم من الرازى ويظهر تحامله على الخصم. وتعصبه للاعتزال بصورة ما كان له حاجة الى نقده ذلك النقد غير العلمى. وهناك نقد علمى لا شك فيه وكذلك نقد موجه الى المنهج\r__________________\r(59) 452 ـ 1.\r(60) 458 ـ ب.\r(61) المحصل، قوله المريد اما ان يرجع لفرض او لا لفرض قلنا ارادة الله تعالى صفة منزهة عن الاغراض. بل هي واجبة التعلق بذلك الشيء في ذلك الوقت بذاته. ص 123 مصر 1323.\r(62) المخطوطة 462 ـ 1 في الاصل «الرسالة الشرفية» بالفاء."], [52, "وهو طريق فخر الدين الرازى فى البحث عن المسألة ونقاشها دون أن يتميز ما هو صحيح منها وما هو غير صحيح ويترك القارئ حائرا بين الآراء والأقوال. وأحيانا فى المسائل الكلامية يميل فى آخر البحث صراحة أو اشارة الى رأى الخصم واما نقده فى ادخاله أو مزجه المنطق والفلسفة بالكلام فى كتاب واحد فهو نقد غير لازم لأن الانسان يقسم كتابه الى أقسام والقسم الأول فى علم والثانى فى علم آخر والثالث فى علم ثالث مثل الشفاء والنجاة لابن سينا.\rوان شرح وتعليل المسائل الكلامية بمنهج فلسفى مستعينا بالفلسفة لا اعتقاد انه يضر الكلام وانما يفيده جدا واذا استقصينا آيات القرآن الكريم وأعملنا عقولنا فى فهمها فانها لا تخرج الا بنقاش فلسفى وعلمى خالص.\r3 ـ ان نصير الدين الطوسى اتبع طريقا خاصا له فى كتابه «تلخيص المحصل» وإن كان بعضهم يسميه نقد المحصل وهو غير صحيح لأنه نفسه سماه تلخيص المحصل فى مقدمته عليه. ان نصير الدين الطوسى يبين فى مقدمته بعض الأشياء المهمة وأهمية علم أصول الدين بين العلوم الاسلامية وانه يشرح لنا إيضاحات وجو تدريس العلوم واهتمام الناس بها أو عدمه وانكباب الناس على المحصل وكيفية تداوله بينهم. ولهذا السبب تناوله الناس بالشرح والتعليق ولكن هذا لم يرض الطوسى ورأى انه من الضرورى ان يكتب أيضا بدوره شرحا له ويكشف بما أورده الرازى فيه من أفكاره ويوضح الخلل فى نقاشه واعتراضاته أو ايراد الشبهات والاجابة على الاعتراضات. ولهذا كله نجد أنه من النافع أن يرى القارئ الكريم مقدمة الطوسى كاملة ليصل الى نتائج من فهمه واستدلاله يقول:\r«فان أساس العلوم الدينية علم أصول الدين الّذي يحوم سائله حول اليقين ولا يتم بدونه الخوض فى سائرها كأصول الفقه وفروعه فان الشروع فى جميعه يحتاج الى تقديم شروعه حتى لا يكون الخائض فيها وان كان مقلدا لأصولهم كان على غير أساس» ...\r«وفى هذا الزمان لما انصرفت الهمم عن تحصيل الحق بالتحقيق وزلت"], [53, "الأقدام عن سواء الطريق بحيث لا يوجد راغب فى العلوم ولا خاطب للفضيلة وصارت الطباع كأنها مجبولة على الجهل والرذيلة. اللهم الا بقية يرمون فيما يرمون رمية رام فى ليلة ظلماء ويخبطون فيما ينحون نحوه خبط عشواء ولم تبق فى الكتب التى يتداولونها فى علم الأصول عيان ولا خبر ولا فى تمهيد القواعد الحقيقية عين ولا أثر، سوى كتاب المحصل الّذي اسمه غير مطابق لمعناه وبيانه غير موصول الى دعواه وهم يحسبون انه فى ذلك العلم كاف وعن أمراض الجهل والتقليد شاف.\rالحق أن فيه من الغث والسمين ما لا يحصر. والمعتمد عليه فى اصابة اليقين بطال لا يحظى بل يجعل طالب الحق بنظره فيه كعطشان يصل الى السراب رأيت أن أكشف القناع عن وجوه أبكار مخدرات وأبين الخلل فى مكان شبهاته وادل على غثه وسمينه وان كان ..\rوقوم فى نقض قواعده وجرحه ولم يجر أكثرهم على قاعدة الانصاف ولم تخل بياناتهم عن الميل والاعتساف واسمى الكتاب «تلخيص المحصل» (63).\rعند ما يقرأ الانسان تلخيص المحصل يرى أن ما قاله صاحبه يوافق أقواله فى المتن أثناء الشرح وان كان مخالفا فى مذهب المصنف فسيلاحظ القارئ تقديره للمصنف حتى فى نقده وفى هذا يخالف ابن أبى الحديد فى تحامله على المصنف وهو ممن سبق الطوسى فى الكتابة على المحصل وصدق الطوسى فى قوله فى المقدمة بالاعتساف والانصراف عن قاعدة الانصاف. لقد أشار الى من خادعه سواء السبيل والمنهج العلمى ولنكتف بهذا عن تلخيص المحصل لأنه لا يمكن أن يأتى الانسان على كل صغيرة وكبيرة فى الشرح من اصابة فى النقد واصابة فى التأكيد.\rان نصير الدين الطوسى فرغ من تحرير شرحه سنة 669 وهى موجودة فى\r__________________\r(63) المحصل (الهامش) ص 2، مصر 1323 وهو مطبوع في مصر موتين مع المحصل مرة 1242 ه ومرة دون تاريخ وطبع مع المحصل ايضا في طهران 1980، ومع ذلك يحتاج الطبع الى التحقيق."], [54, "طوبقابى سراى بخطه تحت رقم 1768 وله عدة نسخ مخطوطة فى مكتبات استانبول.\r4 ـ الشرح لعلى بن عمر بن على الكاتب القزوينى الّذي سماه المفصل فى شرح المحصل. ان القزوينى معاصر لنصير الدين الطوسى وان كان الطوسى أقدم منه بثلاث سنوات مولدا وبثلاث سنوات وفاة ويذكر أن الطوسى أصبح مرة استاذا للقزوينى ولا شك أن الأستاذية لا تتوقف على قدم السن وان كان هنا هذا التقدم موجودا ولو بثلاث سنوات. رغم ذلك كله نرى ان القزوينى قد كتب شرحا للمحصل بالحاح أبى الفضائل بن عبد الحميد القزوينى وهذا يعطينا الفكرة القائمة على عدم ارتضاء بعض الجهات المختصة العلمية أو السياسية بما كتب عن المحصل من شروح وتعليقات ولهذا نرى كعادتنا انه من المفيد أن ننقل هنا بعض ما يمكن أن يحتاج إليه القارئ من مقدمة القزوينى وهو صاحب المفصل والمنصص شرح الملخص للرازى أيضا وصاحب النص فى المنطق المسمى بالشمسية وأخرى من التآليف.\r«فان كتاب المحصل الّذي صنفه ... أبو عبد الله محمد بن عمر الرازى تغمده الله بغفرانه كتاب يحتوى على كل كلام المتكلمين وأدلتهم مع دقائق لطيفة ونكت شريفة من مباحث الحكماء المتقدمين والمتأخرين. الا أن فيه مغالطات يصعب على الناظرين حلها ومواضع منغلقة غير واردة على النظم الطبيعى براهينها فأشار الى من خصنى بالانعامات الوافرة والأيادى المتواترة وهو المولى المعظم الصدر الأعظم ملك ... سلطان القضاة والحكام مفتى الفرق علامة العالم منشئ الدقائق مخترع الحقائق أبو الحسن بن المولى المعظم السعيد الشهيد عز الملة والدين حجة الاسلام أبى الفضائل بن عبد الحميد القزوينى أدام الله معاليه بحل تلك المغالطات وشرح المواضع المنغلقة واخراج براهينها من القوة الى الفعل فبادرت الى مقتضى اشاراته وشرعت فى نيته وكتابته على الوجه المشار إليه مع التنبيه على تقريرات وتدقيقات سنحت حال التحرير وسميته بالمفصل فى شرح المحصل واستعنت بالله واهب العقل ومفيض الله» (64) وهذا الشرح ينتهى فى مسئلة وجوب الامامة\r__________________\r(64) المفصل في شرح المحصل لعلى بن عمر الكاتب القزويني (1 ـ ب) راغب باشا 791، وهذا الشرح قد نسخ بمراغة سنة 688."], [55, "ولا يستمر الى آخر الكتاب مثل شرح الطوسى كما أنه يظهر عند القارئ ان آخر المحصل هو فى تفصيل بعض الفرق الاسلامية ولم يكن هناك حاجة الى اعطاء الايضاحات أكثر وانما علق الطوسى على بعض نقاط وأمكنة منها. وكاتب جلبى يقول فى كشف الظنون فانه ألفه لمحيى الدين الصدر الشهيد الحميد القزوينى (65) فان نسخة المؤلف على ما أعتقد موجودة فى مكتبة داماد ابراهيم باشا برقم 861 وهى 274 ورقة فرغ من تحريره مؤلفه على بن عمر القزوينى فى سلخ رمضان المبارك لسنة اثنتين وستين وستمائة وفى (139 ـ ب) عند ما يقول: «وهذه صورته» يرسم الصورة ولكن النسخ الأخرى المتأخرة عنها التى رأيتها لا توجد فيها تلك الصورة. ولهذا فان هذه النسخة أى نسخة داماد ابراهيم باشا (رقم 821) أصبحت مهمة لأنها نسخة المؤلف لأن خط هذه النسخة هو نفس خط نسخة شرح قطب الدين الموجودة فى راغب باشا برقم 792 كما أشرنا إليها سابقا.\rوانه من الأحرى أن نذكر هنا مسألة مهمة تتعلق بعناية الله للكون وتخصيص كل شيء بهيئته الخاصة أو شكل أو حركة خاصة أو زمان معين الى غير ذلك وهى نظرية قديمة لايضاح تكون الفصول السنوية والأيام والشهور حسب أوضاع الأفلاك يستدل بها على إرادة الله وتخصيص الأشياء بميزاتها الخاصة وفى ذلك يقول فخر الدين الرازى:\r«لأنه منقوض باختصاص الكوكب بالموضع المعين من الفلك مع كونه بسيطا واختصاص أحد جانبى المتمم بالثخن والجانب الآخر بالدقة» (66).\r«أقول: اعلم ان الفلك الّذي مركزه مركز العالم اذا انفصل عنه فلك آخر مركزه خارج عن مركز العالم بحيث يماس محيطه الفلك الأول على نقطة مركبة بينها ويقال له الأوج والنقطة المقابلة له الحضيض حصل بسبب ذلك جسمان مختلفا الثخن والدقة أحدهما حاو للفلك الخارج المركز والآخر محوى فيه دقة الحاوى\r__________________\r(65) كشف الظنون 2/ 1614.\r(66) المحصل 91 مصر 1223."], [56, "مما يلى الخارج، والغلظ مما يلى الحضيض ودقة المحوى وغلظه بالعكس ويقال لهذين الجسمين المتممان وهذه صورته» (67).\r/\rوالى جانب ذلك فان هناك شروحا أخرى للمحصل كما افاد ذلك الطوسى فى مقدمة تلخيص المحصل وذكر الحاج خليفة بعضها فى كتابه المشهور «كشف الظنون» (2/ 1614).\rولابن تيمية (827 ه‍/ 1326 م) كتاب ينقد المحصل كما ذكره هو فى أثره درء تعارض العقل، والنقل يقول: وقد كنا صنفنا فى فساد هذا الكلام مصنفا قديما من نحو ثلاثين سنة وذكرنا طرفا من بيان فساده فى الكلام على «المحصل» وفى غير ذلك (68) وتأليف ابن تيمية على المحصل مفقود على ما أظن وان ابن تيمية قد درس هذا الكتاب وكتب عليه عند ما كان فى حوالى الثلاثين من عمره وانه قد\r__________________\r(67) المفصل في شرح المحصل الكتاب القزويني 139 ـ ب، داماد ابراهيم باشا 861.\r(68) درء تعارنس العقل والنقل ص 22. تحقيق د. محبها رشاد سالم، مصر 1971."], [57, "ذكر المحصل فى كتابه المذكور أحيانا للنقد وأحيانا للاستفادة منه واما الدكتور محمد رشاد سالم فقد ذكر فى التعليق على ما نقل ابن تيمية (69) من نهاية العقول للرازى بأنه لم يجد النص الّذي نقده ابن تيمية وقد أدمج هذا الكتاب من قبل أحد تلامذة ابن تيمية فى شرحه للبخارى. وانما عمل ذلك لحفظ الكتاب من خصومه، اخبرنى بذلك المرحوم الأستاذ محمد التنجى واخبرنى أيضا ان الكتاب موجود فى الشام. من المحتمل ان يكون ذلك الكتاب «الكواكب الدرارى» لابن زكنون الحنبلى شرح البخارى فى المكتبة الظاهرية. الا انى لم أستطع تحقيق ذلك.\rوابن خلدون (732 ه‍/ 1331 م) قد درس المحصل على يد شيخه أبى عبد الله محمد بن ابراهيم ثم اختصره وسماه لباب المحصل فى أصول الدين وهو فى التاسعة عشرة من عمره، وقد نشره الراهب الأسبانى  Pluciano Rubio  فى  Tetuan\rلقد كان كتاب المحصل كتاب التدريس عند الشبان المسلمين حيث أن ابن تيمية قد قرأه وكتب عليه وهو ابن ثلاثين سنة وابن خلدون درسه ولخصه وهو فى التاسعة عشرة.\rوفى احدى المخطوطات التى تسند الى نصير الدين الطوسى والتى توجد فى مكتبة طوبقابى فى استانبول برقم 1461 (137 ـ 1 ـ 137 ـ ب) تحت عنوان المخطوطات العربية وفيه توجد قائمة بمؤلفات فخر الدين الرازى فنذكر هنا هذه القائمة للفائدة فيما يلى كما ذكر فى المخطوطة:\r1 ـ نهاية العقول فى دراية الأصول.\r2 ـ شرح الاشارات.\r3 ـ المباحث المشرقية.\r4 ـ الملخص.\r5 ـ البراهين البهائية.\r__________________\r(69) دره تعارض المفل 21."], [58, "6 ـ الأربعين فى أصول الدين.\r7 ـ المحصول فى علم الأصول.\r8 ـ أحكام القياس الشرعى.\r9 ـ الرسالة الكمالية.\r10 ـ تعجيز الفلاسفة.\r11 ـ السر المكتوم.\r12 ـ الخلق والبعث.\r13 ـ المعالم.\r14 ـ الفصول الخمسين.\r15 ـ تأسيس التقديس.\r16 ـ الجوهر الفرد.\r17 ـ الطب الكبير.\r18 ـ شرح كليات القانون.\r19 ـ التفسير الكبير المسمى بمفاتيح الغيب.\r20 ـ أسرار التنزيل وأنوار التأويل.\r21 ـ الخلافيات الصغيرة.\r22 ـ الخلافيات الكبيرة.\r23 ـ شرح الوجيز.\r24 ـ لباب الاشارات.\r25 ـ المحصل فى علم الأصول (علم الكلام).\r26 ـ الرياض المؤنقة."], [59, "27 ـ المحرر فى حقائق النحو.\r28 ـ الاختيارات العلائية.\r29 ـ اشارات النظام.\r30 ـ مختصر الأخلاق.\r31 ـ اقليدس.\r32 ـ الهيئة.\r33 ـ عصمة الأنبياء.\r34 ـ نهاية الايجاز.\r35 ـ رسالة فى نفى الجهة.\r36 ـ مناقب الشافعى.\r37 ـ تعزيز التقدير.\r38 ـ لوامع البينات.\r39 ـ رسالة فى الهيولى.\r40 ـ اللطائف الغياثية فى المباحث الالهية.\r41 ـ كتاب فى الحيز والأزل.\r42 ـ شرح سقط الزند.\r43 ـ الآيات والبينات.\r44 ـ شرح المصدرات لاقليدس، (137 ـ 1).\r45 ـ المنطق الكبير.\r46 ـ تتمة الأربعين.\r47 ـ الجامع الكبير."], [60, "48 ـ الجامع الصغير.\r49 ـ شرح النجاة.\r50 ـ شرح الارشاد.\r51 ـ شرح عيون الحكمة.\r52 ـ المطالب الالهية.\r53 ـ كتاب فى الرمل.\r54 ـ كتاب الفراسة.\r55 ـ جامع العلوم.\r56 ـ البراهين المحدثة.\r57 ـ رسالة فى اثبات المعراج الجسمانى (137 ـ ب).\rوهنا ارى من المفيد ان اذكر مجموعة المراجع المخطوطة التى راجعتها أثناء تحقيق المحصل؛ ولا داعى هنا لذكر بعض الأوصاف التفصيلية الخاصة بوصف كتابة المخطوطات مثل ألوان الحبر والورق والجلد؛ وما الى ذلك؛ وخاصة فى مثل هذا المخطوط الّذي له عديد من النسخ؛ ولو كانت نسخة واحدة ربما كان ذلك لازما. ونورد هذه النسخ فيما يلى:\r1 ـ نسخة مكتبة أيا صوفيا فى استانبول المرقمة ب 2351 والمستنسخة عام 616/ 1219 م، وهى عبارة عن 104 ورقة أى 208 صفحة والصفحة 18 سطرا وأشرنا الى هذه النسخة بحرف (ا).\r2 ـ نسخة دار الكتب المصرية فى مصر فرع مكتبة التيمورية برقم 268 كتبت فى 616 ه‍/ 1219 م؛ وأشرنا الى ذلك ب (ت) وهى عبارة عن 328 صفحة.\r3 ـ نسخة مكتبة جار الله فى استانبول المرقمة ب 1261 والمستنسخة فى 621 ه‍ ـ 1224 م؛ 75 ورقة 150 صفحة وفى كل صفحة 23 سطرا. وأشرنا الى ذلك ب (ج) وفى الصفحات الأولى توجد نقط هامشية."], [61, "4 ـ نسخة مكتبة طوبقابى باستانبول فرع أحمد الثالث برقم 3199 وهى النسخة التى شرحها الطوسى والتى توجد فى آخرها نسخة أخرى وهى عبارة عن 4 ورقات؛ أى 8 صفحات. وكتبت فى 617 ه‍/ 1220 م. وهذه النسخة توجد فيها بداية مستقلة وهى تكمل النسخة الموجودة فى أيا صوفيا وخطها شبيه بخط نسخة أيا صوفيا ومخالف لخط المجلد الّذي فيه. والتى تنطبق مع النسخة التى طبعت فى مصر سنة 1323 ه‍ومع النسخ التى قابلناها. وأشرنا إليها بحرف (د) وشرح الطوسى موجود فى أولها.\r5 ـ نسخة مكتبة الفاتح فى استانبول برقم 2901 المستنسخة فى 680 ه‍1281 م، وتوجد بين الصفحات (120 ب ـ 72 ـ 1) وكل صفحة 25 سطرا وأشرنا الى ذلك بحرف (ف) وكتبت فى المدرسة الجلالية فى مدينة قونيا.\r6 ـ نسخة مكتبة قره جلبى زاده فى استانبول. برقم 233 والمستنسخة فى 718 ه‍/ 1318 م وهى 167 ورقة (234 صفحة) وكل صفحة 17 سطرا أكثرها متآكلة وأشرنا إليها بحرف (ق).\r7 ـ نسخة مكتبة كوبرلى باستانبول برقم 851، كتبت فى مصر سنة 664 ه‍/ 1265 م، 113 ورقة (226 صفحة) وكل صفحة 19 سطرا. وأشرنا الى ذلك بحرف الكاف (ك).\r8 ـ نسخة مكتبة «لا له لى» باستانبول برقم 2152 كتبت سنة 651 ه‍1254 م؛ 137 ورقة (274 صفحة) وكل صفحة 23 سطرا. وأشرنا الى ذلك بحرف اللام «ل».\r9 ـ نسخة أخرى فى مكتبة «لا له لى» برقم 2436 كتبت 716 ه‍1316 م، 82 ورقة (164 صفحة 29 ـ 30 سطرا) وأشرنا إليها بحرف اللام والباء (لب) وتوجد فى هامشها نقط واضافات وتوضيحات.\r10 ـ نسخة مكتبة عاطف افندى باستانبول برقم 1365 كتبت سنة 881/ 1476 م 145 ورقة (290 صفحة) 21 سطرا؛ وأشرنا إليها بحرف (ع)"], [62, "11 ـ نسخة مكتبة يوسف آغا بمدينة قونتيا برقم 5082/ 841 84 ورقة؛ (168 صفحة) وكل صفحة 23 سطرا؛ ولا يوجد فيها تاريخ الكتابة واظنها كتبت فى عهد السلاجقة وأشرنا إليها بحرف الياء (ى).\r12 ـ نسخة مكتبة طوبقابى فرع أحمد الثالث برقم 1768 وكتبت فى 669 وقد استخدمنا ما فيها من متن فى شرح الطوسى لتصحيح وتثبيت بعض الكلمات والمفاهيم والعبارات وهى 177 ورقة 354 صفحة وكل صفحة 23 سطرا وأشرنا الى ذلك بحرف النون (ن) واظنها مكتوبة بخط المؤلف الطوسى كما سبق.\r13 ـ نسخة ولى الدين فى مكتبة بايزيد برقم 2146 نسخت فى 694 ه‍، وهى 70 ورقة 140 صفحة والصفحة 19 سطرا راجعتها من حين لآخر ولذلك لم أشر إليها فى الفروق فى الهامش.\r14 ـ نسخة أحمد الثالث رقم 1884 نسخت فى سنة 724، 228 ورقة، 456 صفحة 15 سطرا جديد الخط صغير الحجم أشرت إليها بحرف (س).\r15 ـ نسخة مكتبة راغب باشا باستانبول برقم 791 مكتوبة سنة 688 ه‍.\rوهى نسخة على بن عمر الكاتب القزوينى شرحها تحت عنوان المفصل فى شرح المحصل وهى 250 ورقة (500 صفحة) وكل صفحة 25 سطرا، أشرنا إليها عند تصحيح المتن ـ بحرف الصاد (ص).\r16 ـ نسخة مطبوعة فى مصر سنة 1323 ه‍ولها نسخ عديدة منتشرة فى مكتبات البلدان المختلفة واستخدمت كمرجع منذ طبعها حتى الآن وبما أنها طبعت اعتمادا على نسخة واحدة اعتبرناها نسخة واحدة، وأشرنا إليها بحرف الميم (م) تسهيلا لتصحيحها لمن بيده. انه من المناسب ان اذكر هنا ان المحصل قد طبع مرة ثانية فى مصر بعد المراجعة والتقديم لطه عبد الرءوف سعد ونشرته مكتبة كلية الأزهر دون تاريخ الا أن المراجع (لا ندرى على ما راجع) قد جنى على الكتاب دون الشعور بأى مسئولية علمية ولم يراجع حتى المخطوطات الموجودة فى دار الكتب المصرية بل اكتفى بمثال انه فى صفحة 99 من طبعه فى السطر الأول: بعد قول المصنف بهذه الصفة يضيف فى نفسه (وهى الحياة) دون اشارة الى أى"], [63, "مخطوطة وهى غير موجودة فى الطبعة الأولى وكيف له الحق بالتلاعب فى متن المصنف أين هى الأمانة العلمية وعلى الأقل كان يجب عليه أن يشير الى أنه من اضافته نفسه ليتجنب الافتراء على المصنف. بعد تحقيق المحصل اعتمادا على تلك النسخ المخطوطة التى ذكرناها وبعد بيان أهم الفروق فى المتن بين النسخ حسب ما وصلنا إليه من نتائج البحث يجب أن نشير هنا أيضا الى ثلاث نقاط مهمة:\r(ا) فالفرق المهم بين النسخ هو ما كتب فى الصفحة الأولى والّذي يبين لأجل من كتب هذا الكتاب أو من يخاطب هذا الكتاب، وبناء على ذلك ينبغى ان نقسم المخطوطات الى مجموعتين:\r1 ـ يتبين من المجموعة الأولى ان الكتاب كتبه بناء على رغبة مجموعة من الأصدقاء كما هى العادة فى ذلك الوقت، وتلك المجموعة من المخطوطات موجودة فى مكتبة أيا صوفيا، وجار الله؛ نسخة شرح الطوسى؛ ونسخة ولى الدين وأخيرا النسخة المطبوعة فى مصر سنة 1323 ه‍.\r(ب) يبدو أنه كتب الى أحد كبار رجال الدولة وهو برتبة رئيس الوزراء أو وزير على أقل تقدير؛ لأنه يصفه بأنه قوام الدين عز الملك الصدر العادل قوام الدولة والدين نظام الاسلام عميد الممالك، وهذه المجموعة توجد فى مكتبة عاطف أفندى، كوبرلو؛ وقره جلبى ولا له لى فى استانبول؛ يوسف آغا فى قونيا والمكتبة التيمورية فى مصر، مغنيسا تحت رقم 996.\r1 ـ واما بالنسبة الى اسم الكتاب فانه كما يلى: بناء على النسخ الموجودة فى مكتبة الفاتح وقره جلبى ولا له لى برقم 2152 يبدو أن اسم الكتاب هو «أنوار القوامية فى أسرار الكلامية».\r(ب) اما بناء على النسخ الموجودة فى مكتبة كوبرولو ولا له لى برقم 2436 ويوسف آغا فيبدو انه هو كتاب «المحصل». واما بناء على النسخ الأخرى الموجودة فى مكتبة أيا صوفيا وجار الله وولى الدين والتى لها شرح للطوسى فانه كما سماه الطوسى تلخيص «المحصل» وبناء على النسخة المطبوعة فاننا لا نجد الاسمين معا لكن عنوان النسخ المخطوطة كلها فى صفحتها الأولى هو اسم المحصل الا نسخة الفاتح كما سبق واسم المحصل فيها بين قوسين."], [64, "3 ـ فى النسخة المطبوعة وفى صفحة 178 وبعد جملة: «لخلا الزمان من الامام المعصوم» تنتهى (تكتمل) النسخ الموجودة فى مكتبة تيمور ويوسف آغا، وأياصوفيا؛ ولا له لى 2152، وجار الله ومغنيسا وفيما يتعلق بالنسخة الأخرى الموجودة فى مكتبة أحمد الثالث كما أشرنا إليها آنفا برقم 3199 تبدأ من هنا الى آخر الكتاب وكذلك نسخة الفاتح ولا له لى 2436 وقره جلبى وولى الدين ومتن شرح الطوسى يستمر الى آخر متن المطبوع يعنى الى آخر صفحة 182 من المطبوع. ونحن من جهتنا أتممنا المتن العربى بناء على ما فى هذه النسخ الأخيرة ثم ترجمنا الكتاب الى اللغة التركية اعتمادا على تحقيقنا.\rبعد هذا كله بقى شيء واحد مهم لا بد من بيانه وهو المنهج الّذي سلكناه فى تثبيت المتون ونحب تلخيصها فى النقاط الآتية:\r1 ـ اذا كانت نسخة واحدة مخالفة للنسخ الأخرى كلها ذكرت تلك النسخة وذكرت معها النسخ الأخرى.\r2 ـ وكثيرا ما ذكرت النسخ كلها فى الهامش للاشارة الى الفرق بينها.\r3 ـ اذا كان النقص فى نسخة واحدة ذكرت تلك النسخة فقط.\r4 ـ أشرت أحيانا الى فروق النسخ فى التنقيط لا عطاء فكرة على ان هناك اختلافا أيضا فى التنقيط فى النسخ المعتبرة القديمة.\r5 ـ واذا تفردت نسخة فى المخالفة ذكرتها فقط.\r6 ـ ان نسخة (ت) تذكر المؤنثات الاعتبارية. عدا ذلك فان القارئ ينبغى أن يضع نصب عينه ان نسخة (ت) تضع النقط حسب زمانه حيث يختلف التنقيط فى زمانه عما كان بعده. مثلا تضع نقطة على الصاد يظن انه الضاد وتضع الباء فى مكان التاء الفوقانية: ايصالا: ايضالا (286) التقاتل: التقابل (286) واما نحن فنضع الفروق النسخية كما هى موجودة فى المخطوطة فلا ينخدع القارئ بذلك. كما هى واضحة فى (304) فى كلمة حدثنا ينبغى ان يكون حدثنا واتفقت نسخة (ا) مع (ت) هنا أيضا وبعض النساخ لم ينتبه على ما أعتقد الى منهج التنقيط فى عصريهما (ا، ت) اما نحن فاننا نصحح المتن حسب منهج التنقيط المتأخر المستعمل فى زماننا. والله أسأل التوفيق."], [65, "/"], [67, "/"], [69, "/"], [71, "/"], [73, "/"], [75, "/"], [77, "/"], [79, "[نص الكتاب]\r"]], "pg": [5, 79]}, "687.3": {"x": [[79, "بسم الله الرحمن الرّحيم\rرب يسر بفضلك\rالحمد لله المتعالى بجلال أحديته عن مشابهة الأعراض والجواهر، المتقدس بعلو صمديته عن مناسبة الأوهام والخواطر، المتنزه بسمو سرمديته عن مقابلة الاحداق والنواظر؛ المستغنى بكمال قدرته عن معاضدة الأشباه والنظائر، العليم الّذي لا يعزب عن علمه شيء من مستودعات السرائر ومكنونات الضمائر، العظيم الّذي غرقت فى مطالعة أنوار كبريائه أنظار الأوائل وأفكار الأواخر.\rوالصلاة على محمد المبعوث الى الأصاغر والأكابر؛ والشفيع المشفع فى الصغائر والكبائر، وعلى آله وأصحابه وسلم تسليما كثيرا.\r__________________\r2 ـ رب ... بفضلك: ت، رب تمم بفضلك وكرمك: ف، رب تهم بالخير: لب، وبالله التوفيق رب يسر ولا تعسر: 1، الحمدلله الولي العال: ك، ـ: ج ل م.\r4 ـ المتقدس: 1 ت ك ل ي، المقدس: ف م. بعلو ... سر مديتة: ا ت ك ج ل م ف ي ق، بسهر سرمديته عن مناسبة الاوهام والخواطر المقدس بعلو صمديته: لب. المتنزه: ا ت ج ل م ي، المنبزه: ف ك لب.\r6 ـ النظائر: ل لب ق ا ف ج ن النواظر: ت\r7 ـ مستودعات ... الظمائر: ت ف ج ك ل لب ي، مكنونات الضمائر ومستودعات ... السرائر: 1 م. في: ا ج ل لب ف، عن: ت\r8 ـ مطالعة: ت ل لب م، مطالعات: ك.\r9 ـ والصلاة: ت لب م، ثم الصلاة: ل، الشفيع ... الكبائر: ا ت ج ف ك ل م ي،: لب.\r10 ـ اله: ا ت ج ل لب م، اله النجوم الزواخر: ك، واصحابه: ل.\r11 ـ كثيرا: 1 ج ل لب ف م، ب: ت ك ي. وعلى اله ... كثيرا: ق."], [80, "أما بعد.\rفقد التمس منى جمع من أفاضل العلماء وأماثل الحكماء أن أصنف لهم مختصرا فى علم الكلام مشتملا على أحكام الأصول والقواعد، دون التفاريع والزوائد؛ فصنفت لهم هذا المختصر الّذي لا يحيط بمضمونه الا الأفراد من أولى الألباب وجمعت فيه محصل أفكار المتقدمين والمتأخرين من الحكماء والمتكلمين وسميته بالمحصل.\rوسألت الله تعالى أن يعصمنى من الغواية فى الرواية ويسعدنى بالاعانة على الابانة انه خير موفق ومعين.\rعلم الكلام مرتب على أركان أربعة:\r__________________\r2 ـ فقد التمس ... علم علمي: ج الكلام واصول الفقه: ا ج ي احكام: ـ 1 ... فصنفت: ا ج م ن، فقد فلما: ف ق ل جاولت التقرب الى عالى: ت ف ل لب مجلس فلان قوام الدين عز الملك: ق، الصدر العادل قوام الدولة والدين نظام الاسلام عيد الممالك اعز الله انصاره وضاعف اقتداره: ف وهو الذي خصه الله تعالى بالنفس القدسية والرياسة الانسية وجعله ينبوع المناقب النفسانية والفضائل الانسانية صنعت فصنف: ك ع ت ع ف ك ل لب ي.\r4 ـ المختصر: ا ج م ي هامش، الكتاب: ت ف ق ك لب. الذي .. ا لا ـ: ك ... الا ـ: ك ... فيه ـ: ت ك ع ... من الحكماء ـ: ف لب .. بالمحصل بانوار (بالانوار: ق ل) القوامية في اسرار الكلامية: ق: ت ف ق ك ل لب ي، ـ: ا ج م ن ي.\r7 ـ تعالى: ت ف لب ي، ـ: 1 ق ك م، في الرواية ـ: ق.\r8 ـ انه: ا ت ف ق ل م ي، وانه: لب، وهو: ك، الانابة: ي فقط. موفق ومعين: ا ف ج ق ل م، معين وموفق: ت ك لب ي.\r9 ـ علم الكلام مرتب ... اربعة: ج ي، علم الكلام مرتب على اركان: ا م، وفيه اركان: ت ك لب، اعلم ان الكلام مرتب على اركان: ف، علم الكلام مرتب على الاركان: ق، ب: ل."], [81, "الركن الأول\rفى المقدمات\rوهى ثلاث:\rالمقدمة الأولى\rفى العلوم الأولية\rاذا أدركنا حقيقة فاما أن نعتبرها من حيث هى هى من غير حكم عليها لا بالنفى ولا بالاثبات وهو التصور أو نحكم عليها بنفى أو اثبات وهو التصديق.\rالقول فى التصورات [امكان المعرفة]\rوعندى ان شيئا منها غير مكتسب لوجهين.\rالأول: ان المطلوب ان لم يكن مشعورا به؛ استحال طلبه، لأن ما لا شعور به البتة؛ لا تصير النفس طالبة له. وان كان مشعورا به استحال طلبه لأن تحصيل الحاصل محال.\rفان قلت: هو مشعور به من وجه دون وجه.\rقلت: فالوجه المشعور به غير ما هو غير مشعور به.\r__________________\r6 ـ هي هي: ا ت ف ق ل لب م ي، هي: ك ج.\r7 ـ لا بالنفي: ا ت ج ف ق ل م ي، بالنفي: لب، ولا: ا ت ج ف ل م لب، و: ق، بنفي او البات: ف ق ل لب م، بنفي او باتباث: ا، بالنفي او الاثبات: ي.\r14 ـ هو: ا م ت، انه: ق، ـ: ك.\r15 ـ فالوجه: ت ق م، فالوجه الاول: ك."], [82, "والأول لا يمكن طلبه لحصوله. والثانى لا يمكن طلبه أيضا لكونه غير مشعور به مطلقا.\rالثانى أن تعريف الماهية اما أن يكون بنفسها، أو بما يكون داخلا فيها؛ أو بما يكون خارجا عنها أو بما يتركب من القسمين الأخيرين. أما تعريفها بنفسها فمحال لأن المعرّف معلوم قبل المعرّف فلو عرّفنا الشيء بنفسه لزم تقدم العلم به على العلم به وهو محال.\rوأما تعريفها بالأمور الداخلة فيها فمحال، لأن تعريفها اما أن يكون بمجموع تلك الأمور الداخلة وهو باطل؛ لأنه نفس ذلك المجموع، فتعريفها بذلك المجموع تعريف الشيء بنفسه وهو محال.\rأو ببعض أجزائها وهو محال لأن تعريف الماهية المركبة لا يمكن الا بواسطة تعريف أجزائها.\rفلو كان جزء من الماهية معرّفا لها، لكان ذلك الجزء معرّفا\r__________________\r1 ـ والاول: ا ت ف ك ق ي، فالاول: لب م. لحصوله ... لا يمكن: ت ق م، لحصول طلبه: ك. طلبه ايضا: م ي، ايضا: ا، مثله: ف لب، ـ: ت ق ك.\r2 ـ لكونه: ت ف ق ك لب م، لانه: ا. به: ت ف ق ك لب ي. ـ: م.\r4 ـ القسمين: 1، ـ: ت ل لب م ف. الاخرين: ا ت ف ي، الامرين: لب، الاخرين: ك.\r5 ـ فمحال: ت ق م، محال: ك.\r7 ـ واما: ت ق ك م، لما: ف لب ي.\r8 ـ الداخلة: ت ق، ـ: ا ف ل لب م. لانه نفس: ت ف ق م، لانها نفس: ا ك ي، لان بنفس: لب.\r9 ـ فتعريفها ... المجموع: ا ت ك م ي، ـ: لب، الشي: م، للشيء: ت.\r12 ـ فلو: ا ت ك لب م، واو: ق ي. جزء من الماهية: ت م، ذلك الجزء: ك."], [83, "لجميع أجزاء الماهية فيكون ذلك الجزء معرفا لنفسه وهو محال، ولسائر الأجزاء. وذلك يقتضي كون الشيء معرفا لما كان خارجا عنه؛ وذلك هو القسم الثالث وهو محال لأن الماهيات المختلفة يجوز اشتراكها فى لازم واحد، واذا كان كذلك فالوصف الخارجى لا يفيد تعريف ماهية الموصوف، الا اذا عرف ان ذلك الموصوف هو الموصوف به دون كل ما عداه؛ لكن العلم بهذا يتوقف على تصور ذلك الموصوف؛ وعلى تصور كل ما عداه؛ وذلك محال.\rأما الأول فلأنه يلزم منه الدور.\rوأما الثانى فلأنه يقتضي تقدم تصور جميع الماهيات التى لا نهاية لها دفعة واحدة على سبيل التفصيل.\rوأما تعريفها بما يتركب من الداخل والخارج؛ فبطلان ما تقدم من الأقسام يقتضي بطلانه.\rولا يقال: فنحن نجد النفس طالبة لتصور ماهية الملك والروح،\r__________________\r1 ـ لجميع: ا ت ف لب ي، لنفسه وبجميع: ك، اجزاء الماهية: ا ت ف ق ك لب ي، اجزائها: م.\r3 ـ كان: ت ك، يكون: ق م. ذلك: ا ت ف ق ك لب ل ي، ـ: م.\r4 ـ واذا كان كذلك: تكرر في: ك.\r5 ـ تعريف: ت ق م، التعريف: ك، ماهية الموصوف: ت به: ق ل لب ي، لماهية الموصوف: ك، الماهية الموصوفة: ف. الماهية الموصوف: م، عرف .. هو هذا: م .. به: ت ق ك لب م ي، عرفت ابن تلك الماهية هي الموصوف به: ف.\r6، 7 ـ كل ما: ت ق م، كلما: ك. عداه: ت ق ك لب م ي، عداها: ف.\r10 ـ تصور: ا ت ف ق ك لب م ي، ـ: ل.\r11 ـ دفعة واجدة: ق، ـ: ت ل.\r14 ـ ولا: ت ك ي، لا: ا ف ق لب م ي. فنحن: ت ك، نحن:"], [84, "فما قولك فيه؟.\rلأنا نقول: ذلك اما طلب تفسير اللفظ؛ أو طلب البرهان على وجود المتصور، وكلاهما تصديق.\rتنبيه:\r[مصدر المعرفة]\rظهر أن الانسان لا يمكنه أن يتصور الا ما أدركه بحسه أو وجده من فطرة النفس: كالألم واللذة أو من بديهة العقل:\rكتصور الوجود والوحدة والكثرة؛ أو ما يركبه العقل أو الخيال من هذه الأقسام. فاما ما عداه، فلا يتصور البتة؛ والاستقراء يحققه.\rتفريع:\rالقائلون بأن التصور قد يكون مكتسبا، اتفقوا على أن كله ليس كذلك، والا لزم الدور أو التسلسل؛ بل لا بد من تصورات غنية عن الاكتساب. ثم الضابط أن كل تصور يتوقف عليه تصديق غير مكتسب\r__________________\r1 ـ قولك: ت ف ك م ي، قولكم: 1 لب.\r2 ـ طلب (ا): ت ف ق لب م ي، لطلب: ك. البرهان: ت، اقامة البرهان: ك.\r6 ـ ظهر: ا ت ف ق ك لب ي، ظهر لك: م. ادركه: ت ف ق م لب، بدركه: ك ي.\r7 ـ وجده: ف ك ق لب م، بجده: ت ي. من (ا): ا ت ف ق ل لب ي، في: م. بديهة: ت ق م، بديهية: ك.\r8 ـ او ما: م، واما: ت. او الخيال: ق ك لب م ي، هو الخيال: ت، والخبال والوهم: ف.\r9 ـ فاما: ت ق ك م ي، واما: ف لب. عدل: ت ق م، عدا ذلك: ك. بتصور: ت ف ق ك ي، بتصوره: لب م.\r11 ـ مكتسبا: ا ت ف ق ك لب ي، كسبيا: م، ان كله ليس: ا ت ف ك ي، ان كله لا يكون: لب، انه ليس كله: م.\r12 ـ الدور او التسلسل: ت ق ك لب ي، التسلسل او الدور: ف م. بل: ت ف ق ك لب ي، وهما محالان بل: م."], [85, "فهو غير مكتسب. أما الّذي يتوقف عليه تصديق مكتسب؛ فقد يكون مكتسبا وقد لا يكون. واتفقوا على أنه لا يمكن أن يكون الكاسب نفس المكتسب، بل ان كان مجموع أجزائه فهو الحد التام، أو بعض أجزائه المساوية فهو الحد الناقص؛ أو الأمر الخارجى وحده وهو الرسم الناقص؛ أو ما يتركب من الداخل والخارج وهو الرسم التام.\rتذنيبات ثلاثة:\r(أ) البسيط الّذي لا يتركب عنه غيره لا يعرّف ولا يعرّف به؛ والمركب الّذي يتركب عنه غيره يعرّف ويعرّف به، والمركب الّذي لا يتركب عنه غيره؛ يعرّف ولا يعرّف به. والبسيط الّذي يتركب عنه غيره، لا يعرف ويعرف به والمراد من هذه الأقسام التعريفات الحدية.\r__________________\r1 ـ فهو: ت ق ك ل لب م ي، فهو اذا: ف، اما: ت ف ق ك لب م ي، و: ا ل.\r2 ـ لا تكون: ت ك ل ي، يكون غير مكتسب: 1 لب، لا يكون مكتسبا: م.\r4 ـ المساوية: ت ك لب م ي، المساوي: فيه. فهو: ت ك لب م ي، وهو: ف، له فهو: ق، الخارجي:: ت ف ق ي، الخارجي عنه: ا ك ل، الخارج: م.\r5 ـ بتركب: ت ف لب م ي، بركب: ك.\r7 ـ تذنبسات ثلاثة: ي، تذنيبات 1: ا م، تذنيبات فا ا: ت، بديهيات: ك، تذنيبات: ف ق ل لب.\r9 ـ به: ا ت ق م، به غيره: ك. المركب: ت ف م، البسيط: ك ي.\r10 ـ لا ـ: ك.\r10، 11 ـ هذان السطران في: لب هكذا: لا يتركب عنه غيره يعرف ولا يعرف بن والمركب الذي بتركب عنه غيره يعرف ويعرف به.\r11 ـ الاقسام: ا ت ف ق ك لب ي، ـ: م، التعريفات: ت ف ق لب م ي، الماهي التعريفات: ك، تعريفات: ا."], [86, "(ب) يجب الاحتراز عن تعريف الشيء بما هو مثله وبالاخفى وعن تعريف الشيء بنفسه وبما لا يعرف الا به اما بمرتبة واحدة أو بمراتب.\r(ج) يجب تقديم الجزء الأعم على الأخص لأن الأعم أعرف وتقديم الأعرف أولى.\rالقول فى التصديقات:\rوهى ليست بأسرها بديهية؛ وهو بديهى ولا نظرية، والا لزم الدور أو التسلسل وهما محالان؛ بل لا بد من الانتهاء الى ما يكون غنيا عن الاكتساب وما هو الا الحسيات: كالعلم بأن الشمس مضيئة والنار حارة، أو الوجدانيات: كعلم كل أحد بجوعه وشبعه وهى قليلة النفع، لأنها غير مشتركة؛ أو البديهيات: كالعلم بأن النفى والاثبات لا يجتمعان ولا يرتفعان. وفى هذا الموقف صار أهل العالم فرقا أربعا:\r__________________\r1 ـ و (1، 2): ت ف ق ك لب م، او: ي.\r1، 2 ـ في: ق هكذا: الاحتراز عن تعريف الشيء بنفسه وعن التعريف بما هو مثله وبالاخفى وبما لا يعرف الا به.\r4 ـ الجزء: ت لب م ي، ـ: ف. تقدم الاعرف: ا ت ف ق ك م ي، تقديمه: لب.\r7 ـ وهو: م، وهي: ت. نظرية: ق ك لب م ي، بنظرية: ت ف لزم ... التسلسل: ا ف م، لدار او سلسل: ت ق ك لب ي.\r9 ـ هو: ت م، هذا: ق.\r10 ـ النار: ت ق م، ان النار: ك. احد: ت ف ك ي، واحد: لب م، شيعة: ا ف ق ك م ي، بشبعة: ت، بعطشه: لب.\r11 ـ النفع: ا ت ف ك لب ي، جدا: م. او: ت م، و: ك. كالعلم ... لا يرتفعان: ت:: ت ف ك م ي، والعلم بان الشيء اما ان يكون او لا يكون: 1، كالعلم: والعلم: ق بان الشيء اما ان يكون واما ان لا يكون: ق لب.\r12 ـ العالم: ت ق ك لب م، العلم: ف ي.\r13 ـ ارربعا: ق لب م، اربعة: ت ف ك ي."], [87, "الفرقة الأولى:\rالمعترفون بالحسيات والبديهيات وهم الأكثرون.\rالفرقة الثانية:\rالقادحون فى الحسيات فقط، فزعم افلاطون وارسطاطاليس وبطلميوس وجالينوس ان اليقينيات هى المعقولات لا المحسوسات.\rواحتجوا عليه بأن حكم الحس: اما أن يعتبر فى الجزئيات، أو فى الكليات.\rأما فى الجزئيات؛ فغير مقبول؛ لأن حكمه فى معرض الغلط. واذا كان كذلك لم يكن مجرد حكمه مقبولا.\rبيان الأول من خمسة أوجه:\rأحدها: أن البصر قد يدرك الصغير كبيرا كما ترى النار البعيدة فى الظلمة عظيمة، وكما ترى العنبة فى الماء كالإجاصة، وكما اذا قربنا حلقة الخاتم الى العين؛ فانا نراها كالسوار. وقد يدرك الكبير صغيرا كالأشياء البعيدة؛ وقد يدرك الواحد اثنين؛ كما اذا غمزنا احدى العينين\r__________________\r4 ـ ارسطاطاليس: ف ق لب م، ارسطو: ت ك ي.\r5 ـ بطلمييوس: ات لب ي، بطليموس: ف ق ك م. فقط ك.\r6 ـ حكم الحس: ا ت ف ق ك م ي، الحكم: لب.\r8 ـ مقبول: ت ف ق ك لب م ي، معتبر: ا. في (2) ـ: ك\r10 ـ من: ا ت ف ق ك لب ي، في: م.\r11، 12 ـ ترى: ت ك ي، نرى: ف ق، نرى: ل تب، يرى: ج م.\r13 ـ قد ... البعيدة: ت ج ق ك لب م ي، ـ: ف. يدرك: ت ج م ل، ندرك: ق.\r14 ـ يدرك: ت ج م ل، تدرك: ق. الواحد اثنين: ا ت ج ف ق ك ل لب ي، الواحدة ننتين: م."], [88, "ونظرنا الى القمر فانا نراه قمرين. وكما فى حق الأحول وكما اذا نظرنا الى الماء عند طلوع القمر؛ فانا نرى فى الماء قمرا، وعلى السماء قمرا آخر.\rوقد نرى الأشياء الكثيرة واحدة، كالرحى اذا أخرجنا من مركزها الى محيطها خطوطا كثيرة متقاربة بألوان مختلفة، فاذا استدارت سريعا، رأينا لها لونا واحدا؛ كأنه ممتزج من كل تلك الألوان.\rوقد نرى المعدوم موجودا كالسراب وكالأشياء التى يريها صاحب خفة اليد والشعبذة وكما نرى القطرة النازلة من السماء الى الأرض كالخط المستقيم؛ والشعلة التى تدار بالسرعة كالدائرة.\rوقد نرى المتحرك ساكنا كالظل، والساكن متحركا كالراكب فى السفينة فانه يشاهد الشط الساكن متحركا والسفينة المتحركة ساكنة.\rوقد نرى المتحرك الى جهة متحركا الى ضد تلك الجهة فان المتحرك الى جهة يرى الكوكب متحركا إليها اذا شاهد غيما تحته\r__________________\r1 ـ نراه: ا ت ج ف ل ك لب ي، نرى: ق م.\r2 ـ علي: ت ج ق لب ل م ي، في: ف ك. قمرا (2) ـ: ت.\r4 ـ نرى: ت ج ق ف ك لب ل م ي، يرى: 1.\r5 ـ فاذا: ت ف ج ق لب ل م ي، ثم: ك.\r6 ـ لها: ت ج ق ك لب ل م ي، ها: ف\r7 ـ نرى: ت ج ف ك لب ل م ي، يرى: ا، كا (1): ت ج م ل، كما في: ك، و (2): ا ت ف ق ك لب ي، او: م، كا (2): ت ق م ا: ك، يريها: ت ج ف ق ك م، نراها: ي.\r8 ـ من السماء الى الارض: ا، ـ: ت ج ف ق ك لب ل م ي.\r9 ـ بالسرعة: ت ف لب ماكولة في: ق، بسرعة: ج ك ل م.\r10 ـ قد: ك ي، ـ: ا ت ج ق ك ل ف لب م. يرى: 1 فقط. كالراكب في: ق ك لب ي، كراكب: ت ج ل ف م.\r12 ـ يرى: ا فقط.\r13 ـ الكوكب: ل ج ف م، الكواكب: ت ق ك ي. منحركا:"], [89, "وان كان الكوكب متحركا الى خلاف تلك الجهة وقد نرى القمر كالسائر الى الغيم. وان كان سائرا الى خلاف تلك الجهة اذا كان الغيم سائرا إليه.\rوقد نرى المستقيم منكسا كالأشجار التى على أطراف الأنهار. واذا نظرنا الى المرآة رأينا الوجه طويلا وعريضا، ومعوجا؛ بحسب اختلاف شكل المرآة وكل ذلك يدل على غلط الحس.\rوثانيها: ان الحس قد يجزم بالاستمرار على الشيء مع أنه لا يكون كذلك، لأن الحس لا يفرق بين الشيء ومثله. ولذلك يحصل الالتباس بين الشيء ومثله. فبتقدير توالى الأمثال يظن الحس وجودا واحدا مستمرا؛ وليس كذلك فان الألوان غير باقية عند أهل السنة؛ بل يحدثها الله تعالى حالا فحالا مع أن البصر يحكم بوجود لون\r__________________\rت ف ق لب ل م، متحركة: ك ي، تحنه: ت ج ل ف ق لب م، تحتها: ك ي.\r1 ـ الكوكب: ج ل م ف، الكواكب: ت ق ك. يرى: ا ي فقط.\r4 ـ نرى: ت ج ف ق م ي، يرى: ا ل ك، ترى: لب المستقيم: ت ج ف ل ك لب م ي، الاشياء: ا. منكسا: ت ج ل ف ق م، متنكسا: ك لب ي، منكسة: ا، منعكسا: ف في الهامش بنفس الخط.\r5 ـ واذا: ت ج ف ق ك لب ل م ي، وكما اذا: ف، و (1، 2): ا ت ف ق ك ج ل م ي، او: لب.\r7 ـ قد ـ: ف فقط. على الشيء: ا ف ل م، ـ: ت ج ق ك لب ي.\r10 ـ وليس كذلك: ت ج ك ي، ولا يكون كذلك: م ل، وكذلك: ف لب، ولذلك: ا، له بين: ل فقط، ـ: ق. عند: ت ج ل م، على مذهب: ق. السنة: ت ف ك لب م ي، الحق: 2.\r11 ـ يحدثها الله تعالى: ت ج ق ك ي، الله تعالى يحدثها: ا،"], [90, "واحد مستمر. واذا احتمل ذلك احتمل أيضا أن يقال: الأجسام لا تبقى، بل الله تعالى يحدثها حالا فحالا، لكنها لما كانت متماثلة متوالية يظنها الحس شيئا واحدا فثبت أن حكم الحس بالبقاء غير مقبول.\rوثالثها: ان النائم قد يرى فى النوم شيئا ويجزم بثبوته، ثم يتبين له فى اليقظة أن ذلك الجزم كان باطلا. فاذا جاز ذلك فلم لا يجوز أن يكون هاهنا حالة ثالثة؛ يظهر لنا فيها كذب ما رأيناه فى اليقظة.\rورابعها: أن صاحب السرسام قد يتصور صورا لا وجود لها فى الخارج ويشاهدها ويجزم بوجودها ويصيح خوفا منها. وهذا يدل على أنه يجوز أن تعرض للانسان حالة لأجلها يرى ما ليس بموجود فى الخارج موجودا. فاذا جاز ذلك؛ فلم لا يجوز أن يكون الأمر كذلك فيما يشاهده الأصحاء.\r__________________\rيحدثها الله: لب، يجددها الله تعالى: ف م ل.\r1 ـ ايضا ـ: ك فقط. الاجسام: ت ج ف ق ل لب م، ان الاجسام: ك ي.\r2 ـ لا تبقى: ج ف ك لب ي، لا يبقى: ت ق، غير باقية: ا لا تبقى مستمرة: م، الله تعالى يحدثها: ق ك لب، الله تعالى يجددها: ف م، يحدثها الله تعالى: ج.\r3 ـ شيئا: ت ف ج ك لب ل م، وجوها: ي، كما ذهب اليه النظام في ظاهر كلامه: ق.\r5 ـ ان: ق لب ج م ي، ـ: ت ف ك. قد: ت ج ل ك ي، ب: ف ق لب م. ويجزم: ت ف ق لب م ل ي، وقد يجزم: ك.\r6 ـ فاذا: ت ج ف ق ك لب ل ي، واذا: ا م.\r7 ـ ههنا: ا ف ل ق ك لب، هنا: ت ج م ي.\r8 ـ السرسام: ا ت ج ل ف ك ي، البرسام: لب م.\r9 ـ بوجودها: ا ت ج ق لب لي بعد النصحيح في: ا، بثبوتها: ك، بثبوتها ووجودها: ف م.\r10 ـ بجور: ا ت ج ف ق ل م ل ي، كون: لب.\r11 ـ فاذا: ت ي، واذا: ف ج ت ل ك لب م. ان يكون الامر: ت م، لا حسن و: ق."], [91, "فان قلت الموجب لتلك الحالة هو المرض فعند الصحة لا يوجد.\rقلت: انتفاء السبب الواحد لا يوجب انتفاء الحكم، بل هذا الاحتمال لا يندفع الا بحصر أسباب ذلك التخيل الكاذب، ثم ببيان انتفائها؛ ثم ببيان ان المسبب لا يجوز حصوله ولا بقاؤه عند انتفاء الأسباب، لكن كل واحدة من هذه المقدمات مما لا يمكن اثباته الا بالنظر الدقيق. لو أمكن فيلزم أن لا يحصل الجزم بوجود شيء من المحسوسات الا بعد العلم بتلك الأدلة، وذلك مما يدل على أن مجرد حكم الحس غير مقبول.\rوخامسها: انا نرى الثلج فى غاية البياض؛ ثم اذا بالغنا فى النظر إليه، رأيناه مركبا من أجزاء جمدية صغار. وكل واحد من تلك الأجزاء شفاف خال عن اللون فالثلج فى نفسه غير ملون، مع انا نراه ملونا بلون البياض.\rوليس لأحد أن يقول: ان ذلك انما كان لانعكاس الشعاع عن سطوح بعض تلك الأجزاء الجمدية الى بعض.\r__________________\r1 ـ فعند: ج ت ق ل م، وفي حال: ك\r2 ـ قلت: ت ج ل م، قلنا: ق ك. هذا: ت ف م، بهذا: ق، فهذا: ج.\r3 ـ بحصر: م ج ف، لحصر: ل. ذلك: ـ: ك فقط. بيان: ت ل ف ج.\r4 ـ ببيان: ا لب، بيان: ت ف ل ق ج ك ي، ـ: م.\r5 ـ واحدة ـ: ك فقط، مما: ت ف ق ك لب م، ـ: ي، انباته: ت ق ك لب ي، اثباتها: ا ف.\r6 ـ يحصل: ا، يجوز: ت ج ف ق ل ك لب م ي. من: ا ت ج ف ق ك لب ل ي، في: م.\r7 ـ بتلك الادلة: ت ف ق ك لب م ي، مشطوب عليه في: 1.\r10 ـ وكل: ت ج ف ق ل ك م، فكل: ي، كل: لب.\r11 ـ ملون: ت ج ف ق ك لب م، ملون بلون البياض: ي، تراه: ت ج ف ق ك ل م ي، رايناه: ا لب.\r13 ـ ن (2) ـ: ك."], [92, "لأنا نقول: هذا لا يقدح فى غرضنا؛ لأن الّذي ذكرته ليس الا بيان العلة التى لأجلها نرى الثلج أبيض مع أنه فى نفسه ليس بأبيض ونحن ما سعينا الا لهذا القدر.\rوأيضا فالزجاج المدقوق نراه أبيض مع أن كل واحد من أجزائه شفاف خال عن اللون ولم يحدث فيما بينها كيفية مزاجية لأن تلك الأجزاء صلبة يابسة لم يحصل فيما بينها فعل وانفعال.\rوأيضا فانا نرى موضع الشق من الزجاج الثخين الشفاف أبيض مع أنه ليس هناك الا الهواء المحتقن فى ذلك الشق والهواء غير ملون؛ والزجاج غير ملون، فعلمنا أنا قد نرى الشيء ملونا مع أنه فى نفسه غير ملون.\rفثبت بهذه الوجوه أن حكم الحس قد يكون باطلا وقد يكون حقا. واذا كان كذلك لم يجز الاعتماد على مجرد حكمه اذ لا شهادة لمتهم؛ بل لا بد من حاكم آخر فوقه، ليميز خطأه عن صوابه. وعلى\r__________________\r1 ـ الذي: ت ج ق ل م، ما: ك.\r2 ـ نرى: ت ج ق م ل، يرى: ك، ابيضا: ك فقط، في نفسه ليس: ت ج ف ق ك م، ليس في نفسه: لب ل ي.\r4 ـ نراه: ق م، نرى: ت ج ل، يرى: ك.\r5 ـ كيفية ... بينها بينهما: ت: ف ت ج ق ل ك لب م، ـ: ي.\r6 ـ ولم يحصل: ج، لم يحصل: ت ف ق لب ل م، لم يحدث: ا ك.\r8 ـ المحتقن: ا ت ج ف ك لب ل ي، المتخنق: ق، المحتبس: م.\r9 ـ قد: ا ت ف ق ل ج لب، ـ: ك م ي. الشيء ملونا: ا ت ف ق ج ك ل لب ي، الهواء: م.\r10 ـ في نفسه غير ملون: ت ج ف ق ل لب، ليس في نفسه ملونا: ك ي، في نفسه غير ملون ملونا: م.\r11، 12 ـ باطلا .. حقا: قد استهدلا في: ك.\r12 ـ مجرد: ا بعد تصحيح ل، ـ: ت ف ق ك لب م ي.\r13 ـ عن: ت ج ق ل م، من: ك، و: ا ت ج ف ل ق ك لب ي، ـ: م."], [93, "هذا التقدير لا يكون الحس هو الحاكم الأول وهو المطلوب.\rوأما الكليات فالحس لا يعطيها البتة. فان الحس لا يشاهد الا هذا الكل وهذا الجزء. فأما وصف الأعظمية فهو غير مدرك بالحس. وبتقدير أن يكون ذلك الوصف مدركا لكن المدرك هو أن هذا الكل أعظم من هذا الجزء. فأما أن كل كل؛ فهو أعظم من جزئه؛ فغير مدرك بالحس. ولو أدرك كل ما فى الوجود من الكلات والأجزاء ولكن لا يدرك كل ما يتصور امكانه لأن قولنا كل كذا كذا، أو ليس. كذا؛ ليس المراد منه كل ما هو فى الوجود الخارجى من تلك الماهية فقط، بل كل ما لو وجد فى الخارج يصدق عليه أنه فرد من أفراد تلك الماهية، وذلك مما لا يمكن وقوع الاحساس به فثبت ان الحس لا معونة له على اعطاء الكليات البتة.\rالفرقة الثالثة:\rالذين يعترفون بالحسيات ويقدحون فى البديهيات.\rقالوا: المعقولات فرع المحسوسات ولذلك: فان من فقد حسا\r__________________\r2 ـ و: ت ف ق ج ك لب م، ـ: ي.\r4 ـ هذا: ت م، ذلك: ك.\r5 ـ فهو: ف ج ق ل م ي، وهو: ت، ـ: ك لب، جزئه: ت ج م ل، كل الجزء: ق.\r6 ـ الكلات: ا ت ج ف ق ل لب ي، الكليات: ك م، ولكن لا يدرك كل ما يتصور امكانه لان: ف ق ل لب، لكن لا يدرك كلها بتصور امكانه لانا: ي، ولكن لا يدرك كلما يتصور امكانه لان: ك.\r7 ـ كل ما: ت ق م، كلما: ك، لان: ا ت م، الا ان: ج.\rقولنا: ت ج ق ك ل لب م ي، قوله: ف. كذا او ليس: ا. ليس كذا: ي، كذا: ج ق لب، ـ: ت ف ك ل م.\r8 ـ كل ما: ت ق م، كلما لك. هو: ا، ـ: ج ت ل ف ق ك لب م ي. الخارجي: ت ج ف ق ك لب ل م، الخارج: ي.\r9 ـ بل: ت ف ك لب م، ـ: ي. كل ما: ت ف م، كلما: ك، يصدق: ا ت ف ق ك لب ي، لصدق: م ج ل.\r14 ـ فرع: م، فروع: ت. المحسوسات: ت ج ق ل ف م، للمحسوسات: ك. فان: ت ج ف ل م، ان: ق لب ي، رابنا: ك."], [94, "فقد فقد علما؛ كالأكمه والعنين والأصل أقوى من الفرع.\rثم الّذي يدل على ضعف البديهيات وجوه خمسة:\rأحدها: أن أجلى البديهيات العلم بأن الشيء اما أن يكون، واما ان لا يكون. ثم ان هذه القضية ليست بقضية يقينية. فاذا لم يكن أقوى الأوليات يقينيا، فما ظنك بأضعفها؟.\rبيان الأول: أنا رأينا المعولين على البديهيات يذكرون لها أمثلة أربعة:\rأحدها: ان النفى والاثبات لا يجتمعان ولا يرتفعان.\rوثانيها: ان الكل أعظم من الجزء.\rوثالثها: أن الأشياء المساوية لشيء واحد متساوية.\rورابعها: أن الجسم الواحد فى الآن الواحد لا يكون فى مكانين معا.\rووجدنا هذه الثلاثة الأخيرة متفرعة على الأول.\r__________________\r1 ـ فقد: ف ل لب، ـ: ت ق ج ك م ي.\r2 ـ خمسة: ت ف ج ل م، ـ: ق ك لب ل ي.\r3 ـ احدها: نسخ، الاول: ل، اجلى: ت ف ق ك لب م، اسل: ي.\r4 ـ ان (2): ت ف ي، ـ: ا ق ج ك لب ل. بقضية: ا، قضية ـ: ت ف ق ك لب م. يقينية: ا ت ج ف ل ق م، بيفينية: ك لب، فاذا: ا ت ق، واذا: ف ج ك لب ل م ي.\r6 ـ انا: ت ج ف ق ك ل لب، وهو انا: م.\r8 ـ احدها: ت ج ف ك لب م ي، ابولها: ا ل، ا: ق.\r9 ـ رتانيها: ت م ج ل، 2: ق.\r10 ـ وثالثها: ت م، 3: ق، الاشياء: ت م، الاجزاء: ق. لشيء واحد: ا ت ج ق ل ك لب ي، للشيء الواحد: ف م.\r11 ـ ورابعها: ت م، 4: ق. في الان اللواحد: ا ت ج ف ق ك لب ي ل الا انه وقع بعد يكون في: ك، ـ: م.\r12 ـ معا: ـ ك فقط.\r13 ـ ووجدنا: ت ف ق ك لب م ي، وجدنا: ا ل."], [95, "اما قولنا: الكل أعظم من الجزء؛ فلأنه لو لم يكن الكل زائدا على الجزء لكان وجود الجزء الآخر وعدمه بمثابة واحدة؛ فحينئذ يجتمع فى ذلك الجزء الآخر كونه موجودا معدوما معا.\rوأما قولنا: الأشياء المساوية لشيء واحد متساوية؛ لأنه لو لم يكن كذلك، لكان الألف المحكوم عليه بأنه يساوى السواد سوادا لا محالة. ومن حيث انه محكوم عليه بأنه يساوى ما ليس بسواد يجب أن لا يكون سوادا. فلو كان الألف مساويا للأمرين للزم أن يكون الألف فى نفسه سوادا. وأن لا يكون سوادا فيجتمع النفى والاثبات.\rوأما قولنا: ان الجسم الواحد فى الآن الواحد لا يكون فى\r__________________\r1 ـ فلانه: ا ت ج ق ك لب ل ي، لانه: ف م.\r1، 2 ـ الكل زائدا على الجزء جزئه: ج: ا ت ق ك لب ل ي، كذلك: ف م.\r2 ـ من (وعمه بمثابة واحدة) الى (بتلك الصفة الزائدة) ص 20 ت نافصة في ل ص 217.\r2، 3 ـ فحينئذ ... الاخر: ت ق لب م ي، فيصدق عليه: ف، فعند ذلك يجتمع في الجزء الاخر: ك.\r3 ـ معدوما: ا ت ج م، وفي: ف تقدم مصدوما على وجودا، ومعدوما: ق لب، وكونه معدوما: ك ي.\r4 ـ الاشياء: ت م ف ج، الاجزاء: ق، لشيء واحد: ت ق ك ل م ي، للشيء الواحد: ف. فلانه: ج ق، لانه: ت ك م ف ي.\r5 ـ كذلك: م ق، فكذلك، ف، كذاك: ي، ـ: ك ت ج، سوادا: ت ف ج ق ك م ي، يجب ان يكون سوادا: لب.\r7 ـ يجب ... سوادا سواد: ق: ق ج ك لب م ي، ليس بسواد: ف، للزم: ق لب ي، لزم: ت ف ج ك م.\r8 ـ لا يكون: ا ف ق ت ك ل ي، لا يكون في نفسه: م.\r10 ـ لا يكون: ق ك لب م ي، لا يحصل: ف."], [96, "مكانين متباينين، فلأنه لو جاز ذلك لما تميز الجسم الواحد الحاصل فى مكانين متباينين عن الجسمين اللذين حصلا كذلك، وحينئذ لا يتميز وجود الجسم الآخر عن عدمه، فيصدق عليه انه موجود ومعدوم معا.\rولا يقال: كل عاقل يعلم بالبديهة حقية هذه القضايا الثلاثة، وان لم يخطر بباله تلك الحجة الدقيقة التى ذكرتها.\rلأنا نقول: لا نسلم أن حكم العقلاء بهذه القضايا غير متوقف على الحجة التى ذكرتها، ولذلك يقولون: لو لم يكن الكل أعظم من الجزء لم يكن للجزء الآخر أثر البتة. ولو كان الشيء الواحد مساويا لمختلفين، لكان ذلك الواحد مخالفا لنفسه وهذه اشارة الى ما ذكرناه من الحجة،\r__________________\r1 ـ متبايينين ت لب، ـ: ف ق ك م ي. فلانه: ا ق ج ك لب ي، معا لانه: ف م، ولانه: ت.\r2 ـ حصلا: ت ج م، يكونان: ق.\r3 ـ الجسم: ت ف ق ك ي م، جسم: لب. انه موجود ومعدوم: ت لب ي، ان موجود ممدوم: ق ك، كونه موجودا معدوما: ف م، انه موجود ومحكوم: ا، انه موجود معدوم معا: ج.\r5 ـ ولا يقال: ك ي ج، لا يقال: ف لب م ت. عاقل: ت ا ف ج ق ك لب ي، عامل: م، في: ق: يعلم كل عاقل. بالبديهة: م ت ج، بالبديهية: ق ك لب ي، بالضرورة: ف، حقبة: ت ج ف ق ك لب، حقيقة: م ي.\r6 ـ تلك الحجة: ا، تلك الحجة الدقيظة: ت ف ج ك لب ي، هذه الحجة: م. ذكرتها: ا ت ق ك ل ي، ذكرتموها: ف ج م.\r7، 8 ـ بهذه ... ذكرتها ذكرناها: م ج: ت ق ك لب م ي، غير متوقف على هذه القضايا: ف.\r8 ـ لو لم يكن: ت م ج ق، ولو لم يكن: ك.\r9 ـ للجزء: ت ف ج ق ك لب ي، للاجزاء: م. ولو: ت ف ج ق ك م، فلو: ي. مختلفين: ت م ج ف، للمختلفين: ا ق ك لب ي.\r10 ـ ذلك الواحد: ق م، ـ: ت ج ف ك ل ي. وهذه: ا ف لب ي، وهذا: ت ك م، ذكرناه: ت ج ف ق ك لب م ي، ذكرناها: ا. من الحجة: ا ق، ـ: ت ف ك لب."], [97, "بل قد لا يمكنهم التعبير عن تلك الحجة على الوجه الّذي لخصناها، ولكن معناها مقرر فى أنفسهم وعقولهم، ولا عبرة بالعبارة.\rفقد لاح أن أجلى البديهيات قولنا: إن النفى والإثبات لا يجتمعان ولا يرتفعان؛ وانما قلنا: انه غير يقينى لوجوه:\rأحدها: ان هذا التصديق موقوف على تصور أصل العدم والناس قد تحيروا فيه، لأن المتصور لا بد وان يتميز عن غيره. والمتميز عن غيره متعين فى نفسه، وكل متعين فى نفسه فهو ثابت فى نفسه، فكل متصور ثابت. فما ليس بثابت فغير متصور فالمعدوم غير متصور، واذا كان ذلك التصديق موقوفا على هذا التصور، وكان هذا التصور\r__________________\r1 ـ بل: ا ق لب، نعم: ف م ي، بلى: ت ج ك. قد: ت ك لب م ي، ـ: ا ف ق. لخصناها: ا ت ج ق ك لب ي، احصيناها: فقه في الهامش، لخصناه: ف م.\r2 ـ معناها: ا ق ت ف ك لب ي ج، معناه: م. مقرر: ت م، مصور: ك. انفسهم و: ت فقط.\r3 ـ ان: ا ج ف ت ك لب ي، بان: م. البديهيات: ج ق ت ك م، البديهيات العلم بان الشيء ان يكون واما ان لا يكون و: ف، ان: ت لب ي، ـ: ف ق ج ك.\r4 ـ وائما قلنا انه: ج ا ف ك لب ي، وانما قولنا انه: ت، وهو: ق م.\r5 ـ ان أت ج ف ك م ي، وهو ان: ا لب ق. العدم الان احد اجزائه النفي وهو العدم ونصور المجموع متوقف على تصور الاجزاء: ق فقط.\r6 ـ لابد و: ت ق ج م، لابد: ك. عن (1): ت م، عن: ق والمتيز: ا ت ج ق ك لب ي، وكل متميز: ف، والتميز: م.\r8 ـ فما ليس: ا ف ج ت ق ك لب ي، في نفسه فما ليس: م. فغير: ت ف ق ك ل م، غير: لب، فالمعدوم غير منصور: ت ا ف ج ق ك ي، فالمعدوم غير ثابت ليس بثابت: لب ... منصورا: لب م.\r9 ـ ذلك: ت ق ك م، كذلك: ف، موقونا: ا، منفرقا: ج ت ق ك لب م ي."], [98, "ممتنعا كان ذلك التصديق ممتنعا.\rلا يقال المعدوم المتصور له ثبوت فى الذهن، ولأن قولنا: المعدوم غير متصور، حكم على المعدوم بأنه غير متصور. والحكم على الشيء يستدعى كون المحكوم عليه متصورا فلو لم يكن المعدوم متصورا لامتنع الحكم عليه بأنه غير متصور.\rلأنا نجيب عن الأول: بأن الثابت فى الذهن أحد أقسام مطلق الثابت، والكلام وقع فى تصور مقابل مطلق الثابت، وذلك المقابل يستحيل أن يكون ثابتا بوجه ما، والا لكان داخلا تحت مطلق الثابت وحينئذ لا يكون قسيما له بل قسما منه.\rوعن الثانى: أن ما ذكرته ليس جوابا عن دليلنا، على أن المعدوم غير متصور، بل هو اقامة دليل ابتداء على أن المعدوم متصور، وذلك يقتضي معارضة دليلين قاطعين فى مسئلة واحدة، وهو أحد الدلائل القادحة فى البديهيات.\rوثانيها: لو سلمنا امكان تصور العدم، لكن قولنا: النفى والاثبات لا يجتمعان، يستدعى امتياز العدم عن الوجود، وامتياز\r__________________\r2 ـ المنصور: ت ف ج ق ك لب م، ـ: ي.\r7 ـ تصور: ا ت ج ف ق ك لب، تصورها: م ي.\r9 ـ وحينئذ: ت ف ج ق ك لب م ي، فحينئذ: ا.\r10 ـ ذكرته: ك م، ذكرتموه: ت ج فقط.\r11 ـ دليل: ت ج ق ك ل م ي، الدليل: ف. المعدوم: ت ق ج ك لب م ي، العدم: ف.\r12 ـ معارضة: ت ج ا ف ك م، تعارض: ق لب ف في الهامش.\r14 ـ لو: ات ج ف م ي، لو ان: ك، ان لو: ق، العدم: ت ف ج لب م، المعدوم: ق ك ي، لكن: ت ج ف ق ك ل م ي، ولكن: ا."], [99, "العدم عن الوجود يستدعى أن يكون لمسمى العدم هوية متميزة عن الوجود، لكن ذلك محال؛ لأن كل هوية يشير العقل إليها، والعقل يمكنه رفعها؛ وإلا لم يكن له مقابل، فكان يلزم أن لا يكون للعدم مقابل؛ فكان يلزم نفى الوجود وهو باطل.\rفثبت أن ارتفاع الهوية المسماة بالعدم معقول، لكن ارتفاع تلك الهوية ارتفاع خاص فيكون داخلا تحت العدم المطلق، فيكون قسيم العدم قسما منه هذا خلف.\rوثالثها لو سلمنا الامتياز لكن الاثبات والنفى؛ قد يكون المراد منهما ثبوت الشيء فى نفسه وعدمه فى نفسه كقولنا: السواد اما ان يكون موجودا، وإما أن لا يكون موجودا، وقد يكون المراد منهما ثبوت شيء لشيء آخر وعدمه عنه؛ كقولنا: الجسم اما أن يكون أسود واما أن لا يكون. أما الأول: فمن المعلوم بالضرورة أن\r__________________\r1 ـ لمسمى: ج ف ق لب م، مسمى: ت ك ي.\r2 ـ لكن: ت م، ولكن: ك. والعقل: م، فالعقل: ا ج ت ق ك لب ي.\r3 ـ فكان: ا ت ف ج ك لب ي، وكان: ق م، للعدم: ق م، العدم: ك.\r4 ـ مقابل: ت ق ج ك لب م ي، مظابلا: ف، وكان يلزم: ق م، فكان يلزم: ت ف ك ي، فيلزم: ا ج لب.\r7 ـ منه: ت ف ج ق ك م، له: ف لب. هذا: ت ف ق ك لب من، وهذا: ي.\r9 ـ و: ا ت ف ق ك ل ي، او: م.\r10 ـ موجودا (1): ت لب م ي، ـ: ف ج ق.\r11 ـ شيء: ت ف ج ق ك ي، الشيء: لب م. وعدمه: ف ج ت ك لب م، او عدمه: ي، له وعدمه: ق.\r12 ـ لا يكون: ت ك م، لا يكون اسود: لب. الاول: ت ج ف ق لب م، القسم الاول: ك ي. فمن: ا ت ج ف ق ك لب ي، من: م."], [100, "قولنا: السواد اما أن يكون موجودا، أو لا يكون، لا يمكن التصديق به إلا بعد تصور مفهوم قولنا: السواد موجود السواد معدوم لكن كل واحد منهما باطل.\rأما الأول: فلأنا اذا قلنا السواد موجود فاما أن يكون كونه سوادا هو نفس كونه موجودا أو مغايرا له.\rفان كان الأول كان قولنا: السواد موجود جاريا مجرى قولنا: السواد سواد، وقولنا: الموجود موجود. ومعلوم انه ليس كذلك، لأن هذا الأخير هذر والأول مفيد.\rوان كان الثانى فهو باطل من وجهين:\rأحدهما: إنه إذا كان الوجود قائما بالسواد فالسواد فى نفسه ليس بموجود، والا لعاد البحث فيه، ولكان الشيء الواحد بالاعتبار الواحد موجودا مرتين.\rواذا كان كذلك كان الوجود قائما بما ليس بموجود، لكن\r__________________\r1 ـ اولا يكون: ا، واما ان لا يكون موجودا: م، او معدوما: ت ف ج ق ك لب ي.\r2 ـ به ـ: ت فقط. لكن: ت ف ج ك لب ي، ولكن: م.\r4 ـ سوادا: ج ف ق ك لب م ي، سواد: ا.\r4، 5 ـ موجود فاما ... كونه ـ: ت فقط.\r5 ـ مغايرا: ج.\r7 ـ وقولنا: ت ف ج ق ك لب م، قولنا: ي.\r8 ـ عذر: ت ق م، هذر اي هذيان: له. مفيد: ت ف ق ج ك لب م، مفيد به: ي.\r9 ـ من وجهين: ت ف ج ق ك لب م، لوجهين: ي.\r10 ـ احدهما: لب م، الاول: ت ف ج ق ك ي. انه اذا: ف ج ق ك م ي.\r11 ـ بالاعشار الواحد: ت ج ك، ـ: م.\r12 ـ واذا كان ... وهي عين السفسطة: تاخرت الى ما بنفسه الثاني في لب."], [101, "الوجود صفة موجودة، وإلا لثبت المتوسط بين الموجود والمعدوم، وأنتم أنكرتموه فحينئذ تكون الصفة الموجودة حالّة فى محل معدوم، وذلك غير معقول. إذ لو جاز ذلك، لجاز أن يكون محل هذه الألوان والحركات غير موجودة، وذلك يوجب الشك فى وجود الأجسام، وهو عين السفسطة.\rالثانى: انه إذا كان الوجود مغايرا للماهية، كان مسمى قولنا: السواد، غير مسمى قولنا: موجود. فاذا قلنا السواد موجود بمعنى أن السواد هو موجود كان ذلك حكما بوحدة الاثنين، وهو محال.\rفان قلت: ليس المراد من قولنا: السواد موجود هو أن مسمى السواد هو مسمى الوجود، بل المراد منه أن السواد موصوف بالموجودية.\r__________________\r1 ـ موجودة: ت ج ف ك م، وجودية: ق ي، وجودية موجودة: لب. المتوسط: ا ت ف ق ك لب، الواسطة: م ي ج.\r2 ـ انكرتموه: ت ج م، لا تقولون به: ق. حالة: ا ت ج ف ق ك لب ي، محالة: م.\r4 ـ غير موجودة موجود: ت ق: ت ق ك م، عني موجود: ي. يوجب: ا ت ف ج ق ك لب ي، وجب: م. الشك: ت ف ج ق ك لب م، الشك والارتياب: ي.\r5 ـ وهو: ت م، وذلك: ك.\r6 ـ الوجود: ك ج م، الموجود: ت.\r6، 8 ـ كان مسمى .. بوحدة الاثنين: ت ف ج ق م ي، ان مسمى الواد اذا كان غير مسمى الموجودية كان قولنا: الواد موجود، بمعنى ان السواد هو الموجود كان حكما ان الاثنين واحد: لب.\r7 ـ موجود (1) ت ف ق م ي، الموجود: ا ك.\r10 ـ موجود هو: ا ت ف ق ك لب ي، موجود وهو: م.\r11 ـ هو مسمى: ت ف ق لب ي، مسمى: ك م. الوجود: ك م، الموجود: ت ج ي. منه: ا ت ك ج ق ي، في قولنا السواد موجود: لب، ـ: ف م."], [102, "قلت: فحينئذ ينقل الكلام إلى مسمى الموصوفية بالوجود فإنه إما أن يكون مسمى السواد هو مسمى الموصوفية بالوجود، فحينئذ يكون قولنا: السواد موصوف بالوجود، جاريا مجرى قولنا: السواد سواد، واما أن يكون مغايرا له، فالحكم على السواد بأنه موصوف بالوجود حكم بوحدة الاثنين، الا أن يقال المراد: من كون السواد موصوفا بالوجود إنه موصوف بتلك الموصوفية، وحينئذ يعود التقسيم فى تلك الموصوفية الثانية؛ فاما أن يتسلسل، وهو محال أو يقتضي رفع الموصوفية، وحينئذ يبطل قولنا: السواد موجود على تقدير كون الماهية غير الموجودية.\rوأما قولنا: السواد معدوم، فإن قلنا: وجود السواد عين كونه سوادا، كان قولنا: السواد ليس بموجود، جاريا مجرى قولنا: السواد ليس بسواد، أو الموجود ليس بموجود. ومعلوم انه\r__________________\r1 ـ قلت، ـ: ك، ينقل: ج ق ك، ننقل: ا م، ينتقل: ت ف ي. بالوجود: ك فقط. فانه اما: فاما: ق ي.\rقلت: فحينئذ ينقل الكلام ... وحينئذ يبطل قولنا: السواد موجود على تقدير كون الماهية غير الموجودية: وقعت في لب هكذا. قلت الموصوفية بالوجود غير مسمى السواد فقولنا مسمى السواد موصوف بالموجودية يعود فيه الاشكال الا ان يقال المراد منه ان مسمى السواد موصوف بتلك الموصوفية لكن البحث عن ذلك كما في الاول فيلزم ان يكون موصوفية الماهية بكل موصوفية مغايرة للاول ويلزم التسلسل او يقتضى.\r2، 3 ـ فحينذ يكون سحال فيكون: م.\r7 ـ وحينئذ يعود التقسيم في تلك الموصوفية: تكرر في: ت.\r8 ـ يبطل: ا ف ت ج ق ك لب ي، بطل: م. وحينئذ: تكرر في: ت.\r10 ـ واما: ت ق ج ك م ي، فان قلت الموصوفية ثابتة في الدهن دون الخارج، قلت الذهن ان طابق الخارج عاد الاشكال والا فلا عبوة به ولان موصوفية الشيء بالشيء نسبة بينهما والنسبة بين الشيئين بستحيل ان يكون حاصلة في غيرهما واما: ف لب. معدوم: ت ف ج ق ك لب م، ليس بموجود: ي، قلنا: ا ت ف ج ق ك لب ي، قولنا.\r12 ـ بسواد: ا ت ف ج ق ك لب ي، سوادا: م، او: ت،"], [103, "متناقض.\rوان قلنا: وجوده زائد عليه، توجه الاشكال من ثلاثة أوجه:\rأحدها: أنه يلزم قيام الوجود الّذي هو صفة موجودة بالماهية المعدومة وهو محال.\rوثانيها: ان سلب الوجود عن ماهية السواد مثلا، لا يمكن ما لم يتميز السواد عن غيره، وكل ما يتميز عن غيره فله تعين فى نفسه، وكل ما له تعين فى نفسه فله ثبوت فى نفسه فالسواد لا يمكن سلب الثبوت عنه، الا اذا كان ثابتا فى نفسه، فيكون حصول الوجود له شرطا فى سلب الوجود عنه، هذا خلف.\rفان قلت: الّذي يسلب عنه الوجود موجود فى الذهن.\rقلت: فاذا كان موجودا فى الذهن استحال سلب مطلق الوجود عنه لأن الموجود فى الذهن بعض من مطلق الموجود؛ فالموجود فى الذهن يصدق عليه انه موجود فلا يصدق عليه حينئذ أنه ليس\r__________________\rو: ك ج م.\r3 ـ انه: ف ق ك م، ان: ت ي، هو ـ: ك فقط.\r5، 6 ـ ما لم يتميز: ت ف ق ك ج م، الا اذا تميز: ي.\r6 ـ كل ما: ت م ج، كلما: ك. بتميز: ت ف ج ق ك م، تميز: لب ي.\r7 ـ له تعين: ك م، لم تعين: ت. نبوت في نفسه، ت ف ج ك م ي، في نفسه ثبوت: لب.\r9 ـ هذا: ت ق ك م، وهذا: ي.\r10 ـ عنه الوجود: ت ق ك م، الوجود عنه: ي. فاذا: ت ج ق م، فان: ك.\r12 ـ الموجود (1): ف ت ج ق ك لب م، الوجود: اي، بعض: ت فقط، اخص: ج نسخ اخرى، الموجود (2): ف ج ك لب، الموجود عنه: ت، الوجود: ق م ي. فالموجود: ف ت م ج، والوجود: ك."], [104, "بموجود، وكلامنا الآن فيما يقابل مطلق الموجود لا فيما يقابل موجودا خاصا.\rوثالثها: انا سنقيم الدلالة فى مسئلة المعدوم: ان المعدوم ليس بشيء على امتناع خلو الماهية عن الوجود، وعلى هذا يستحيل الحكم على الماهية بالعدم. فظهر انه ليس لقولنا: السواد موجود، السواد معدوم، مفهوم محصل. واذا كان كذلك لم يكن لقولنا: السواد إما أن يكون موجودا، واما أن يكون معدوما مفهوم محصل. واذا كان كذلك امتنع التصديق به فضلا عن كون ذلك التصديق بديهيا.\rأما الثانى: وهو قولنا: الجسم اما أن يكون أسود، واما أن لا يكون. فنقول من الظاهر انه لا يمكن التصديق به الا بعد تصور معنى قولنا: الجسم أسود، الجسم ليس بأسود.\rفنقول: اذا قلنا: الجسم أسود، فهو محال من وجهين:\rأحدهما: انه حكم بوحدة الاثنين على ما تقدم تقريره، وهو باطل.\r__________________\r1 ـ الموجود: ا ت ي، الوجود: ف ج ق ك م.\r2 ـ موجودا: ا ف ج ت ق ك لب ي، وجودا: م، لا يقرا في: ت.\r3 ـ المعدوم: ف، ـ: ت ق ك لب م ي.\r4 ـ وعلى: ت ف ج ق ك لب ي، فعلى: ا، هذا: م، هذا التقدير: ق.\r8 ـ كون: ت ف ج ق ك لب م ي، ان يكون: ا ج هامش، به بديهيا: ق فقط.\r9 ـ اما: ت ف ك م ج ي، واما: ق لب.\r11 ـ الجسم (2): ت ق ج ك لب ي، والجسم: ف م.\r12 ـ فهو: ت م ج، وهو: ق. من وجهين: ت ف ج ق ك م، لوجهين: لب ي.\r13 ـ احدهما: ا لب ج م، الاول: ت ف ق ك ي. على ما ... باطل: ت ق ج ك لب م ي، وهو باطل على ما تقدم تقريره: ف."], [105, "الثانى: وهو ان موصوفية الجسم بالسواد، اما أن يكون وصفا عدميا أو ثبوتيا، والأول محال، لأنه نقيض اللاموصوفية وهى وصف سلبى لأنه محمول على العدم ونقيض السلب ايجاب، فالموصوفية لا يمكن أن يكون أمرا عدميا. ومحال أيضا أن يكون أمرا ثبوتيا، لأنه على هذا التقدير إما أن يكون نفس وجود الجسم والسواد، واما أن يكون مغايرا لهما.\rوالأول محال، لأنه ليس كل من عقل وجود الجسم ووجود السواد عقل كون الجسم موصوفا بالسواد.\rوالثانى أيضا محال، لأن موصوفية الجسم بالسواد لو كانت صفة زائدة لكانت موصوفية الجسم بتلك الصفة زائدة عليها وهو محال لأنه يؤدى الى التسلسل فثبت أن موصوفية الشيء بغيره غير معقولة، فان قلت: الموصوفية ثابتة فى الذهن دون الخارج.\rقلت: الذهن ان طابق الخارج، عاد الاشكال، والا فلا عبرة به؛ ولأن موصوفية الشيء بالشيء نسبة بينهما. والنسبة بين الشيئين\r__________________\r1 ـ الثاني: ت ف م ي، والاني: ق ج ك لب. وهو: 1، ـ: ت ف ج ق ك ل م ي.\r2 ـ ثبوتيا: ت ف ج ق ك لب م ي، وجوديا: ا، والاول: ت ا ف ج ك لب، الاول: ق م ي، اللاموصوفية: ت ف ج ك لب م، ان لاموصوفية: ي، وهي: ت ف لب م ي، وهو: ا ق ك.\r3 ـ لانه محمول على العدم: ا، ـ: ت ف ج ق ك لب م ي.\r4 ـ ومحال: نسخ اخرى، وهو محال: ت.\r7 ـ والاول: ت ف ج ق ك لب م، فالاول: ي، كل ـ: ك. عقل: ت ف ق ك لب م، يعقل: ي، ووجود السواد ـ: ق.\r8 ـ كون الجسم موصوفا: ت ف ق ك لب م ي، موصوفية: ا.\r10، 11 ـ وهو محال لانه بودى الى التسلسل: ا، فيلزم الزم: ق، ولزم: ج التسلسل وهو محال: لب ق، وهو محال: ت ف ك م ي.\r12 ـ معقولة: ت ف ك م ي، معقول: ا ج ق لب. فان ... 106 ... في غيرهما: ناقص في لب هنا وقد ذكرت تماما مع: ف في ص 102 سطر 7، 8، وتكررت هنا في: ف."], [106, "يستحيل ألا تكون حاصلة فيهما بل فى غيرهما. واذا كان كذلك. كان الحق من هذه القضية المنفصلة هو الجزء السلبى أبدا، لا الثبوتى. وذلك عندكم باطل.\rالاعتراض الرابع على قولنا: الشيء اما أن يكون، واما أن لا يكون. سلمنا تصور هذه القضية باجزائها لكن لا نسلم عدم الواسطة، وبيانه من وجهين:\rأحدهما: ان مسمى الامتناع إما أن يكون موجودا، أو معدوما، أو لا موجودا ولا معدوما. لا جائز أن يكون موجودا، والا لكان الموصوف به موجودا لاستحالة قيام الموجود بالمعدوم. ولو كان الموصوف به موجودا، لم يكن الممتنع ممتنعا، بل اما واجبا أو ممكنا ولا جائز أن يكون معدوما لأنه نقيض اللاامتناع الّذي يمكن حمله على المعدوم فيكون اللاامتناع عدميا، فلا يكون الامتناع عدميا. ولأن الامتناع ماهية متعينة فى نفسها متميزة عن سائر الماهيات ولو لا\r__________________\r1 ـ الا تكون: ا ت ج ي ل، ان تكون: ف ق ك م. فيهما بل في غيرهما: ا ت ج ف ل ي، في غيرهما: ق م، في نسبة غيرهما: ك.\r2 ـ القضية: ت فقط.\r3 ـ النبوتي: ت ف ق ك لب م ي، ثبوتى: ا.\r5 ـ نسلم عدم: ت م، نساعد: ق.\r7 ـ احسدهما: ا ت ج ف ق لب ي، الاول: ك ل م. ان: ت م، اما: ك، او معدوما: ت ج م، واما ان يكون معدوما: ق.\r8 ـ او لا: ت، ولا: نسخ اخرى.\r9 ـ بالمعدوم: ت ف ك لب م، بما ليس بموجود: ق ي.\r10 ـ او: ت م، واما: ك، اما: ق.\r11 ـ معدوما: ت ق م، عدميا: ك. اللامتناع: ق م، الا امتناع: ت، الامتناع: ك.\r13 ـ منعينة: ك ج م ي، معينة: ت ف ق ل لب. عن سائر: ا ت ف ل ك لب م ي، عما عداها في: ا ق.\r13، 1 ص 107 ـ ولولا ذلك: ا ت ج ف ق ك لب ل ي، اذ لو لم يكن كذلك: م."], [107, "ذلك لاستحال اشارة العقل إليها. واذا كان كذلك، استحال أن يكون نفيا محضا.\rفان قلت: له ثبوت فى الذهن.\rقلت: هذا باطل، لأن الممتنع ممتنع فى نفسه سواء كان هناك عقل أو لم يكن، ولأن الفرض الذهنى ان كان مطابقا للخارج فهو المطلوب، والا لكان كاذبا. وليس كلامنا فيه، بل فيما يطابق الوجود، ولأن الّذي فى الذهن، ان كان موجودا استحال اتصافه بالامتناع، لأن الموجود لا يكون ممتنع الوجود، وان لم يكن موجودا لم يكن الامتناع القائم به موجودا، لاستحالة قيام الموجود بما ليس بموجود.\rفثبت أن مسمى الامتناع ليس بموجود ولا بمعدوم. وذلك هو الواسطة.\rوثانيهما: ان مسمى الحدوث، وهو الخروج من العدم الى\r__________________\r1 ـ اليها: ت ف ق ك لب م ي، الى ذلك: ا. واذا فاذا: كان كذلك استحال: ت ف ق ك م ي، فاستحال: لب.\r4 ـ هذا: ت ق م، هو: ك. في نفسه: ق.\r5 ـ الدهنى: ا ت ج ق، العقلي: ف ك لب ل م ي، للخارج: ف ق ل ك م ي، ـ ت ج لب.\r6 ـ لكان: ف ق ك لب م، كان: ل ت ج ي، كاذبا: ت ق ك لب م ي، كذبا: ف.\r7 ـ استحال: ت ق ك لب م ي، لم يكن اللممتنع ممتنعا لاستحالة: ق.\r8 ـ الموجود: ت م، الوجد: ق، موجودا: ت م، موجود: ك.\r9 ـ لم يكن: ت ق ك لب م ي، استحال ان يكون: ا، لا ستحالة قيام الموجود بما ليس بموجود: ت ج ف ق ك لب م ي، لامتناع قيام الموجود بالمعدوم: ا، لاستحالة قيام الموجود ما ليس بموجود: ك.\r11 ـ ليس بموجود: ت ف ق لب م ي، لا موجود: ا، بمعدوم: ت ج م، معدوم: ك.\r12 ـ ثانيهما: ق لب م، ثانيها: ت ف ك ي ل."], [108, "الوجود، غير مسمى العدم، ومسمى الوجود. والا لكان حيث صدق مسمى العدم، أو مسمى الوجود، صدق مسمى الخروج من العدم الى الوجود، وهو محال.\rواذا ثبت ذلك، فنقول: الآن الّذي يصدق فيه على الماهية مسمى الخروج من العدم الى الوجود إما أن تكون الماهية فى ذلك الآن موجودة، أو معدومة أو لا موجودة ولا معدومة. فان كانت موجودة فقد صدق على الموجود انه يخرج من العدم الى الوجود، فيكون ذلك كأنه يقال: الموجود يخرج الى الوجود، فيكون الشيء موجودا مرتين، وهو محال.\rوان كانت معدومة فهو محال من وجهين:\rأحدهما: ان الماهية متى كانت معدومة كانت باقية على العدم\r__________________\r1 ـ العدم ومسمى الوجود: ت ج ف ق ك لب ل م، الوجود ومسمى العدم: ي.\r2 ـ مسمى بمسمى: ك العدم الغير: في او مسم الوجود: ت ج ف ق ك لب م، مسمى الوجود او مسمى العدم: ي.\r8 ـ الموجود: ك م، الوجود: ت.\r10 ـ من وجهين: ت ج م، لوجهين: ل ط.\r11 ـ احدهما: ان الماهية ... فثبت ص 109: هنا خبط بين النسخ فاحاول ان ابين فروقها بصورة واضحة كما ياتي:\rاحدهما: ان الماهية ... فثبت: ا.\rالاول ان مسمى الحدوث صفة موجودة والا يثبت والا ثبت: ل ك لثبتت: ح ف الواسطة والصفة الموجودة يستحيل قيامها بالمعدوم و: ج ا الثاني انها منى كانت معدومة كان العدم الاصلي باقيا ومتى كان العدم الاصلي باقيا لم يكن التنقل في التغيير: ك، التغير: ل ج، النقل في التغيير: ف من العدم حاصلا فيثبت فثبت: ج ل ف ك: ت ج ف ك ل.\rاحدهما انه اذا كانت معدومة كانت باقية على العدم الاصلي ومع البقاء على العدم الاصلي بستحيل لن يتحقق مسمى التغيير من العدم الى الوجود ولان مسمى الحدوث صفة موجودة الاثبت الواسطة والصغة"], [109, "الأصلي. ومتى كان العدم الأصلي باقيا لم يكن الانتقال من العدم حاصلا.\rوثانيهما: أن مسمى الحدوث صفة موجودة والا ثبت الواسطة والصفة الموجودة يستحيل قيامها بالمعدوم فثبت أن الماهية حالة الحدوث لا موجودة ولا معدومة.\rوله تقرير آخر: وهو أن الماهية اذا انتقلت من العدم الى الوجود.\rفحالة الانتقال لا بد وألا تكون معدومة ولا موجودة، لأنها لو كانت معدومة، فهى بعد لم تأخذ فى الانتقال، بل هى باقية كما كانت قبل ذلك ولو كانت موجودة فقد حصل المنتقل إليه بتمامه، وحين حصول المنتقل إليه بتمامه لا يبقى الانتقال؛ بل ينقطع. فظاهر أنه حال حصول الانتقال لا بد وأن تكون متوسطا بين المنتقل عنه والمنتقل إليه.\r__________________\rالموجودة يستحيل قيامها بالعدم. الثاني منى كانت معدومة كان العدم الاصلي باقيا ومتى كان العدم الاصلي باقيا لم يكن النقل في التغير من العدم حاصلا فثبت: م.\rالاول احدهما: ي ان مسمى الحدوث صفة موجودة والا ثبت الواسطة والصفة الموجودة ستحيل قيامها بالعدوم. ا و: ق الثاني ان الماهية اذا كانت معدومة كانت باقية على العدم الاصلي ومع البقاء على العدم الاصلي يستحيل ان يتحقق التغير من العدم الى الوجود فلا يكون النقل من العدم حاصلا: ي: ق ي.\rاحدهما: ان الماهية اذا كانت معدومة كانت باقية على العدم الاصلي ومع البقاء على العدم الاصلي يستحيل ان يتحقق مسمى التغير من العدم الى الوجود وثانيهما مسمى الحدوث صفة موجودة والا لثبت الواسطة والصفة الموجودة يستحيل قيامها بالعدوم: لب.\r7 ـ الا تكون: ا ت ج ف ك لب، ان تكون لا: م، ان لا تكون لا: ي.\r9 ـ اليه بتمامه بتمامه ـ: ت ل: ا ت ج ف ق ك لب ي، اليها: م.\r10 ـ اليه: ا ت ج ل ف ق ك لب ي، اليها: م. لا يبقى: ت ف ق ك لب ي، لم يبق: ا م. فظاهر: ت ك م ي، فظهر: ف لب ج. انه حال: ت ج ف ك ي، ان حالة: ق م."], [110, "فوجب أن يكون خارجا عن حد العدم الصرف وغير واصل الى حد الوجود الصرف.\rفهذه الاشكالات قطرة من بحار الاشكالات الواردة على قولنا: الشيء اما أن يكون واما أن لا يكون. واذا كان حال أقوى البديهيات كذلك فما ظنك بالأضعف؟\rالحجة الثانية: لمنكرى البديهيات انا نجد العقل جازما بأمور كثيرة كجزمه بالأوليات مع أن الجزم غير جائز فيها. وذلك يوجب تطرق التهمة الى حكم العقل.\rبيان الأول من وجوه:\rأحدها: أنا اذا رأينا زيدا، ثم غمضنا العين لحظة، ثم فتحناها فى الحال، وشاهدنا زيدا مرة أخرى، جزمنا بأن زيدا الّذي شاهدناه ثانيا، هو الّذي شاهدناه أولا. وهذا الجزم غير جائز لاحتمال أن الله تعالى أعدم زيدا الأول فى تلك اللحظة التى غمضنا العين فيها، وخلق فى الحال مثله، هذا على مذهب المسلمين.\r__________________\r1 ـ ان: نسخ، ان لا: ت فقط، واصل: ا ت ف ق ك لب ي، داخل: م.\r5، 6 ـ كذلك .. الحجة الشبهة: ا ف .. البديهيات: ا ت ج ل ف ق ك لب م، ـ: ي.\r6 ـ بامور: ف ف ق ك لب م، لامور: ي.\r10 ـ فتحناها: ا ف ق ل ك ي، فتحنا: ت لب م.\r11 ـ وشاهدنا: ت ف ق ل ك م، شاهدنا: ا ي. مرة: م، تارة: ق. بان: ت ف ج ك ل لب ي، ان: ق م. شاهناه: ت ف ج ق ل ك لب م، شاهدنا: ي.\r12 ـ ثانيا: ت ف ق ك لب م، ثابتا: ي، شاهدناه: ت ف ج ق ل ك لب م، شاهدنا: ي.\r13 ـ تعالى: ق ج ت م، تعالى وتقدس: ك، زيدا: ا ف ج لب، الزيد: ك م ت ل ي. اللحظة: ف ت ج ق ك لب م ي، الحالة: ا.\r14 ـ هذا: ا ت ف ق ج ك ي، وهذا: م. على: ف ت ق ك م،"], [111, "وأما على مذهب الفلاسفة، فلعله حدث شكل غريب فلكى اقتضى هذا النوع من التصرف فى هيولى عالم الكون والفساد. وهو وان كان بعيدا، لكنه جائز عندهم. وعلى هذا التقدير يكون زيد الّذي شاهدناه ثانيا غير زيد الّذي شاهدناه أولا.\rوثانيها: انا اذا شاهدنا انسانا شابا أو شيخا علمنا بالضرورة أنه ما خلق الآن دفعة واحدة من غير أب وأم، بل كان قبل ذلك طفلا، ومترعرعا وشابا حتى صار الآن شيخا.\rوهذا الجزم غير ثابت. أما على قول المسلمين فللفاعل المختار، وأما على قول الفلاسفة فللشكل الغريب.\rوثالثها: انى اذا خرجت من دارى؛ فانى أعلم أن ما فيها من\r__________________\rـ: ي.\r1 ـ واما على مذهب: ت ك م، قاما واما: ل ق على قول: ف ق ج لب ل ي.\r2 ـ من: ا ت ف ج ق ك ل لب ي، في: م. وان: ت ق ج لب م ي، ان: ف ك.\r3 ـ بعيدا: ت ف ج ل ق لب ي، بعيدا جدا: م، يفيد: ك. جائر: ت ق ج لب ل م، غير جائز: ك. زيد: اج ك ف، الزيد: ق ت لب ل م، زيدا: ي.\r4 ـ ثانيا: ا ت م، اولا: ي، زيد الذي شاهدناه اولا: ا، غير الاول: ج، زيد الاول: ف ق، الزيد الاول: لب م ت ل.\r5 ـ الثاني: ا م، وثانيها: ت ف ق ج ك لب ل ي، انا: ف م، انى: ل ت ف ج لب ي. اذا: ك، ـ: ا، شاهدنا: ف م، شاهدت: ت ف ق ج ي، شابا: ا ل ت ق ج ك لب ي، شبابا: ف م، علمنا: ف ك م، علمت: ت ق لب ج ي ل. بالضرورة انه: ت م، انه بالضرورة: ك.\r8 ـ قول: ت ف ج ق ك لب ي، مذهب: م، فللفاعل: ت ف م، فالفاعل هو: ك.\r9 ـ قول: ت ف ج ق ك لب ي، مذهب: م. فللشكل: ت ق لب م ي، فللتشكل: ف ك.\r10 ـ وثالثها: ت ف ج ق ل ك لب ي، الثالث: م. دارى: ت"], [112, "الأوانى لم ينقلب أناسا فضلاء مدققين فى علوم المنطق والهندسة، ولم ينقلب ما فيها من الأحجار ذهبا وياقوتا. وانه ليس تحت رجلى ياقوتة بمقدار مائة ألف منّ. وان مياه البحار والأودية، لم ينقلب دما ودهنا.\rوالاحتمال فى الكل قائم. ولا يندفع ذلك بأنى لما نظرت إليها ثانيا وجدتها كما كانت، لاحتمال أن يقال إنها انقلبت الى هذه الصفات فى زمان غيبتى عنها، ثم عند عودى إليها صارت كما كانت. اما للفاعل المختار أو للشكل الغريب.\rورابعها: أنى اذا خاطبت انسانا فتكلم بكلام منظوم مرتب يوافق خطابى، علمت بالضرورة أنه حي عاقل فاهم. وهذا الجزم غير ثابت\r__________________\rف ق ك لب م ي، الدار: ا، اعلم ان: ت ل م، علمت بالضرورة: ج، اعلم: ف.\r1 ـ لم ينقلب: ا ت ف ق ك ل ي، وغيره لم ينقلب: م، علوم المنطق: ت ف ج لب، علم المنطق: ك ي ل، علوم النطق: م، علوم المنطلق: ف، الهندسة: ت لب م ق، الفلسفة: ج.\r2 ـ رجلى: ف ت ج ق ك لب ا ي، رحلى: م، ياقوته: ت ج ف ق ل ك لب ي، ياقوت: م.\r3 ـ مائة الف: ت ف ق ج ك لب م ل، الف مائة: ا، الف: ي.\r4 ـ دما: ا ت ف ج ق ل ك لب ي، ادما: م، دهنا: ا ق م، ذهبا: ك لب ت ي، دهما: ف، ـ: ج.\r5 ـ ولا يندفع: ت ف ق ج ك م ي، ولم يندفع: لب، لما: ا ت ف ج ق ك ل لب ي، اذا: م.\r6 ـ لاحتمال: نسخ، الاحتمال: ت.\r7 ـ عنها: ق ج م ل، ـ: ت ك.\r8 ـ للشكل: ق ت م، فللتشكل: ك.\r9 ـ ورابعها: ف ت ف ك لب ي، الرابع: م. انى: ا ج ت ف ق ل ك لب ي، ـ: فتكلم: ا ت ج ق ك ل لب ي، يتكلم: ف م، مرتب: ت ف ق ك م، ـ: لب.\r10 ـ خطابى: ا ت ف ج ق ل ك لب ي، الخطابي: م، علمت: ا ج ف ت ق ل ك لب ي، فعلمت: م، فاهم: ت ف ج ق ك م،"], [113, "لأن المقتضى لذلك الجزم، اما أقواله، أو أفعاله.\rأما الأقوال، فلا يوجب، لأنها أصوات مقطعة، وحصولها فى الذات لا يقتضي كون الذات حية عاقلة.\rوأما الأفعال فلا تدل أيضا لاحتمال أن الفاعل المختار أو الشكل الغريب اقتضى حصول تلك الألفاظ المخصوصة الدالة على ما يوافق غرض المخاطب. فثبت أن القول والفعل لا يدلان على كونه حيا فاهما مع انا نضطر الى العلم بذلك.\rوخامسها: انكم رويتم فى الأخبار أن جبريل عليه السلام كان يظهر على النبي صلىلله عليه وآله فى صورة دحية الكلبى، وإذا لم يمتنع ذلك فى بديهة العقل لم يمتنع أن يظهر فى صورة سائر\r__________________\rفهم: ي.\r1 ـ او: ج ف ت م ي، واما: لب، و: ق ل ك.\r2 ـ الاقوال: ا ف ت ج ق ل ك لب، الاول: ي م. مقطعة: ا ت ف ج ق ك لب ي، منقطعة: م. وحصولها: ت ف ك ل لب م ي، فحصولها: ا، وحدوثها: ج.\r3 ـ حبة: ت ج ف ق ل ك لب ي، حيا: ا م. عافلة: ت ف ج ق ك لب ي، عاقلا: م، فاعلا: ا، فاعلة: ل.\r4 ـ تدل: ك ج م، يدل: ا ت ق، بدل: ف ي.\r5 ـ الالفاظ: ت ف ج ك ل، الافعال: ق لب م ي.\r6 ـ بدلان: ت ق لب م، يدل: ف ي. حيا فاهما: ت ف ق ج ك لب، حيا فهما: ي، حيا عالما: ل، فاعلا فاهما حيا: ا، حيا عاقلا فاهما: م.\r7 ـ انا نظعطر: ت ق ج ك لب م ي، انى مضطر: ف ل.\r8 ـ وخامسها: ت ج ق ل ك لب ي، الخامس: ا م، الخامسة: ف. الاخبار: نسخ، الخبر: ت عليه السلام: ت ف ك م ي، صلوات الله عليه: لب.\r9 ـ على النبي .. وآله: ق.\r10 ـ ذلك: ت ج ل ق. بديهة: ت ف ق لب م، بديهة: ك ي."], [114, "الأشخاص. فاذا رأيت ولدى فلعله ليس ولدى، بل هو جبريل عليه السلام، بل الذبابة التى طارت لعلها ليست بذبابة، بل هى ملك من الملائكة.\rفثبت أن هذا التجويز قائم، مع أن العلم الضرورى بعدمه حاصل فثبت بهذه الوجوه أن البديهة جازمة بهذه الأحكام مع أن جزمها باطل. ولما تطرقت التهمة إليها لم يكن مجرد حكمها مقبولا اذ لا شهادة لمتهم.\rلا يقال: جزم العقل بهذه القضايا استدلالى، لا فطرى، لأنا نقول: لو كان كذلك، لوجب أن لا يحصل هذا الجزم، الا لمن عرف ذلك الدليل. ولما لم يكن كذلك، بل هو حاصل للصبيان، والمجانين، ولمن لم يمارس شيئا من الدلائل، علمنا أنه بديهى لا نظرى، على أنا اذا رجعنا الى أنفسنا، وتأملنا أحوالنا علمنا أن علمى بأن زيدا الّذي\r__________________\r1 ـ ولدى: م ت، بي لدى: ق، عليه السلام: ت ف ك، ـ: ق لب م ي.\r2 ـ اثنى: ت ف ق ك ل م ي، الذي: ا، طارت: ا ت ف ج ق ك ل لب ي، طارت في الهواء: م، لعلها: ت ف ج ق ل لب، ولعلها: ا م، ـ: ك م، بذبابة: ا ت ف ج ق ك ل لب ي، ذبابة: م.\r4 ـ التجويز: ت ف ل ق ك م، النجوز: ج ي. قائم: ت ف ج ق ل ك لب ي، ثابت: م. بعدمه حتاسل: ت ق ل م، حاصل بعدمه: ك ج.\r5 ـ بهذه: ت ف ج ق ك لب م ي، بهذا: ا، البديهة: ق ل ت م ج، البديهية: ف ك لب ي.\r6 ـ مجرد: لب، ـ: ت ف ج ك ل م ي، اذ لا شهادة لمتهم: تكررت في: ك.\r8 ـ لا فطرى: ت ج ف ل، لا بديهي: م. لا ضروري: ق لب، نظري لا ضروري: ي، لا نظري ضروري: ك.\r10 ـ كذلك: ق ت م، ذلك ك.\r11 ـ لم يمارس: ا ت ف ج ق لب ي، لا يمارس: ك م.\r12 ـ راجعنا: ج ل. علمى: نسخ، علمنا: ت ج، ان: ت ف ق لب م، بان: ك ي. زيدا: ق ت م، زيد: ك."], [115, "أشاهده الآن هو الّذي شاهدته قبل ذلك بلحظة، وانه لا يجوز أن يقال: عدم الأول، وحدث مثله، ليس أضعف من علمى بأن الشيء اما أن يكون موجودا أو معدوما، أو بأن الواحد نصف الاثنين.\rالحجة الثالثة: مزاولة الصنائع العقلية تدل على أن الانسان قد يتعارض عنده دليلان فى مسألة عقلية بحيث يعجز عن القدح فى كل واحد منهما اما عجزا دائما أو فى بعض الأحوال. والعجز لا يتحقق الا عند كونه مضطرا الى اعتقاد صحة جميع المقدمات التى فى الدليلين، ولا شك أن واحدا منهما خطأ، والا لصدق النقيضان، وهذا يدل على أن البديهة قد تجزم بما لا يجوز الجزم به.\rالحجة الرابعة: قد يكون الانسان جازما بصحة جميع مقدمات دليل معين ثم يتبين له خطأ فى بعض تلك المقدمات. ولأجل ذلك ينتقل الرجل من مذهب الى مذهب. فجزمه بصحة تلك المقدمة الباطلة باطل فظهر أن البديهة متهمة.\r__________________\r2 ـ بغال: ت ق م ي، يقول: ف. يقال احتمال: ك لب.\r3 ـ او بان الواحد نصف الاثننين: ك ج ي تقدمت على وأن الشيء في ق، ـ: ت ف لب م، علمنا بان الواحد نصف الاثنين، علمنا بان الشيء اما ان يكون واما ان لا يكون: نسخ ج.\r4 ـ الحجة: ت ف ج ق لب م ل ي، واما الحجة: ك، اما التبيهة: ا.\r9 ـ فد تجزم: ت ف ق ك لب م ي. جازمة: ا.\r10 ـ و: لب الحجة: ت ف ق لب م ي: الشبهة: ا. بصحة: ت ك لب ج م ل ي، لصحة: ف.\r11 ـ معين: ت ق ل ج ك لب م ي، متعين: ف، يتبين له الخطا خطا: ج ق ك م ل: ا ق ك م، بنسبه بخطاه: ي، ثبتت له خطا: يشبه بخطا: لب، بشبه لخطا: ت ج.\r12 ـ بصغة: نسخ، لصحة: ت. المقدسة: ت ف ق ل م ي، المقدمات: ك ج لب.\r13 ـ فظهر: ج ق ك ل ت لب م ي، فعلم: ا. البديهة: ت م،"], [116, "الحجة الخامسة: انا نرى لاختلاف الأمزجة، والعادات تأثيرا فى الاعتقادات وذلك يقدح فى البديهيات.\rأما الأمزجة، فلأن ضعيف المزاج يستقبح الايلام، وغليظ المزاج قاسى القلب قد يستحسنه. فرب انسان يستحسن شيئا ويستقبحه غيره.\rوأما العادات، فهو أن الانسان الّذي مارس كلمات الفلاسفة وألفها من أول عمره الى آخره، ربما صار بحيث يقطع بصحة كل ما يقولونه، وبفساد كل ما يقوله مخالفوهم.\rومن مارس كلام المتكلمين كان الأمر بالعكس. وكذا القول فى أرباب الملل.\rفان المسلم المقلد يستقبح كلام اليهودى فى أول الوهلة، واليهودى بالعكس. وما ذاك الا بسبب العادات واذا ثبت أن\r__________________\rالبديهية: ك.\r1 ـ الحجة: ق ك لب م ي، الشبهة: ا.\r4 ـ قاسى: ت ق ج ك لب ي، القاسي: م ل، ـ: ف، الطب: ت ق ك لب م ي، ـ: ف، قد ـ: ك، قرب: ت م، ورب: ق.\r5 ـ وبستفبحه غيره: م، وغيره بستقبحة: ت ق ل لب ي ج، وغيره يستحقبه: ف.\r6 ـ الذي: ت ف ج ل، اذا: م، كمات: ا ت ف ج ق لب م، كلام: ك ي.\r7 ـ آخره: ت م، آخر عمره: ك، بصحة: ت ق ك ل لب م ي، لصحة: ف، ـ: ج، كل: ـ ك.\r8 ـ كل: ـ ك، بقوله: ت ف ك لب ي، بقول: ج م.\r12 ـ ذاك: ت ج ك م، ذلك: ق ي. بسبب: نسخ، لسبب: ت.\r12، 1 (ص 117) ـ ان لاختلاف: ف ج ت ل ك لب م، ذلك وهو ان لاختلاف: ي، ان اختلاف: ت."], [117, "لاختلاف الأمزجة والعادات أثرا فى الجزم بما لا يجب الجزم به، فلعل الجزم بهذه البديهيات لمزاج عام أو لألف عام. وعلى هذا التقدير، لا يجب الوثوق به.\rلا يقال: ان الانسان يفرض نفسه خالية عن مقتضيات الأمزجة والعادات فما يجزم العقل به فى تلك الحالة، كان حقا لأن الجازم به فى هذه الحالة هو صريح العقل، لا المزاج ولا العادة.\rلأنا نقول: هب أنا فرضنا خلو النفس عن المزاج والعادة ولكن فرض الخلو لا يوجب حصول الخلو. فلعلنا، وان فرضنا خلو النفس عنهما لكنها ما خلت عنهما وحينئذ يكون الجزم بسببهما لا بسبب العقل.\rسلمنا أن فرض الخلو يوجب الخلو، لكن لعل فى نفوسنا من الهيئات المزاجية والعادية ما لا نعرفه على التفصيل. وحينئذ لا يمكننا\r__________________\r1 ـ يجب الجزم به: ت ف ل ق ك م ي، يجوز به الجزم: ا ج، يجوز الجزم به: ل.\r3 ـ به: ت ق ل ك ج لب ي، بشيء منها: ف، ـ: م.\r4 ـ ان: م، بان: ك، ـ: ت ف لب ي.\r5 ـ فما: ت ك لب ج م ي، مما: ف، فكل: ا. الحالة: ت م، الحال: ك. الجازم به: ت ف ق ج ك لب م ي، الجازم: ا ل.\r6 ـ في هذه الحالة هو فهو: م: ت ف ج ق لب م ي، في تلك الحالة هو: ا ك ج ل، ولا: ا لب ل، و: ت ف ق ك م ي.\r7 ـ ولكن: ق، لكن: ت م.\r7، 8 ـ ولا العادة .. لاما: ت فقط.\r8 ـ فلعلنا: نسخ، فللعنا: ت.\r9 ـ عنهما (1): نسخ، عنها: ت و: ك لكنها: ف ت ق ك لب م ي، لكن النفس: ا، وحينئذ ت ف ق ك لب م ي، فحينئذ: ا. بسببهما: ق ت م، بسببها: ك.\r11 ـ لكن: ت ف ق ك لب م، ولكن: ي.\r12 ـ الهيئات: ف ت ج ك لب م ي، الهيئة: ا."], [118, "فرض خلو النفس عنهما وذلك سبب التهمة.\rفهذا مجموع أدلة الطاعنين فى البديهيات. ثم قالوا لخصومهم: إما أن تشتغلوا بالجواب عما ذكرنا أو لا تشتغلوا به، فان اشتغلتم بالجواب حصل غرضنا لأنكم حينئذ تكونون معترفين بأن الاقرار بالبديهيات لا يصفو عن الشوائب الا بالجواب عن هذه الاشكالات.\rولا شك أن الجواب عنها لا يحصل الا بدقيق النظر والموقوف على النظرى أولى أن يكون نظريا، فكانت البديهيات مفتقرة الى النظريات المفتقرة الى البديهيات، هذا خلف.\rوان لم تشتغلوا بالجواب، بقيت الشبهة المذكورة خالية عن الجواب ومن المعلوم بالبديهة أن مع بقائها لا يحصل الجزم بالبديهيات، فقد توجه القدح فى البديهيات على كل التقديرات.\rالفرقة الرابعة:\rالسوفسطائية الذين قدحوا فى الحسيات والبديهيات، قالوا:\r__________________\r1 ـ عنهما: ق ك ل م ي، عنها: ت ف لب ج.\r2 ـ فهذا: ف ج لب ت م، فهذه: ك ي، هذا: ق.\r3 ـ ان ـ: ك فقط ذكرنا د: ل به: ا م: ا ت لب ل م، ذكرناه لولا: ي، ذكرناه او لا تشتغلوا: ف ق ك.\r4 ـ الافرار ـ: ت فقط.\r6 ـ عنها: ت ف ج ك لب م، عنهما: ي.\r7 ـ لن: ت ف ق ج ك لب ي، بان: م ل، مفتفرة الى: ت ف ق ك لب م ي، موفوفة: ا.\r8 ـ هذا: ت ف ك لب م، وهذا: ق ي.\r10 ـ المعلوم: ق م. العلوم: ك.\r11 ـ كل: ت ف ك ي ل، كلا: ج ق م، لب، التقديرات: ا ي، تقدير: ك، التقدرين: ج ل ت ف ق م.\r13 ـ قالوا: ق ج ت، وقالوا: ك م ل ف."], [119, "ظهر بكلام الفريقين، تطرق التهمة الى الحاكم الحسى، والخيالى، والعقلى. فلا بد وأن يكون فوقها من حاكم آخر. ولا يجوز أن يكون ذلك الحاكم هو الاستدلال، لأنه فرعها، فلو صححناهما به، لزم الدور ولا نجد حاكما آخر. فاذا لا طريق الا التوقف.\rلا يقال هذا الكلام الّذي ذكرته، إن أفادك علما بفساد الحسيات والبديهيات، فقد ناقضت، والا فقد اعترفت بسقوطه.\rلأنا نقول: هذا الكلام الّذي ذكرته أنت يفيد القطع بالثبوت. والّذي ذكرته أنا يفيد التهمة. والشك انما يتولد من هذه المآخذ. فأنا شاك وشاك فى أنى شاك، وهلم جرا.\rواعلم أن الاشتغال بالجواب عن هذه الشبهة يحصل غرضهم على\r__________________\r2 ـ وان يكون: ا لب م،: ت ف ج ق ك ل ي، فوقها من حالم آخر: ا ت ف ج ك لب ل ي، من في: م حاكم اخر فوقها: ق م.\r3 ـ فرعها: ت ق ج ك ل م ي، فرعهما: ا ف ل، سححناهما: ا ف ل ك م، صححناها: ج ق ت لب ي.\r4 ـ اخر: ا ت ف ج ق ك لب ي، اخر فوقها: م، طريق: طر: ل، الا: ت ف ج ك ل لب م، الى: ي.\r5 ـ ذكرته: ت ف ج ق ل ك لب ي، ذكرتم: م، افادك: ت ف ق ج ك ل لب م ي، افادكم: ا.\r5، 6 ـ الحسيات والبديهيات: ت ف لب ل م ج ي. البديهيات والحسيات: ف.\r6 ـ فقد ق: م اعترفت: ت ف ج ق ك لب ل م ي، ففسد نافضلم والا فقد اعترفتم: ا.\r7 ـ انت: ت م، الما: ق.\r8 ـ هذه الماخذ: ت ف م ي، هذا الماخذ: ا ج ق ك ل لب. فانا: ت ف ج ك م، وانا: ي، فانى: لب، وانه: ق.\r10 ـ عن: ت ج لب م ل ي، من: ق، الشبهة .. غرضهم: ت ف ك لب م ي، الاشكالات يفيد غرضهم وبعصل مقصودهم: ا. غرضهم: ل ف م. مقصوده: ج وعلى: ل م ف. اما: ت ج."], [120, "ما قرروه فى كلماتهم. فالصواب أن لا نشتغل بالجواب عنها لأنا نعلم ان علمنا بأن الواحد نصف الاثنين، وان النار حارة والشمس مضيئة لا يزول بما ذكروه، بل الطريق أن يعذبوا حتى يعترفوا بالحسيات، واذا اعترفوا بها، فقد اعترفوا بالبديهيات، أعنى الفرق بين وجود الألم وعدمه. وأما الأجوبة المفصلة عن هذه الأسئلة فيجىء فى الأبواب المستقبلة ان شاء الله تعالى وحده.\r__________________\r1 ـ قرروه: ت ف ك م ي، قرروا: ا، في كلماتهم: ت ف ج ك م، في كلامهم: لب،: ي فقط، فالصواب: ج ف ل ك م، والصواب: ت ي، فالاولى: ا، فالواجب: ق، ان لا تشتغل: ا، انا لا نشتغل: م، ان لا شاغل: ي، ان لا بتشاغل: ت ف، ان لا نتشاغل: ج ك ل لب.\r3 ـ يعذبوا: ف ت ج ق ل لب م، يعذبوهم: ي.\r4 ـ بها: ت ف ق لب ج ل، بالعسبات: م ي، فقد: ت ف ق لب م ل ي، ـ: ا ج.\r5 ـ فيجىء: ت، فسيجيء: ج ف ق ك لب ل م ي، فسياتي: ا. الابواب: ت م، ابواب: ق.\r6 ـ تعالى: ت ك م ي، ان شاء الله تعالى ـ: ج ل، تعالى وحده: ا، تعالى وتعدس وبالله التوفيق: لب، ـ: ف ق ج ل."], [121, "المقدمة الثانية\rفى أحكام النظر\rالمعترفون بالتصديقات البديهية والمحسوسة اختلفوا فى انه: هل يمكن تركيبها بحيث يتأدى ذلك التركيب إلى صيرورة ما ليس بمعلوم معلوما. والجمهور من أهل العالم قالوا به. والكلام فيه وفى تفاريعه يستدعى مسائل.\rمسئلة 1 (1):\rالنظر ترتيب تصديقات يتوصل بها الى تصديقات أخر. فان من صدق بأن العالم متغير، وكل متغير ممكن، حتى لزمه التصديق بأن العالم ممكن فلا معنى لفكره الا ما حضر فى ذهنه من التصديقين المستلزمين للتصديق الثالث.\r__________________\r4 ـ تركيبها: ا ت ق ك ل، تركبها: ف ج م ل ي. ذلك: ف ج ق ك لب م، بذلك: ي ت.\r5 ـ تفاريعه: ا ف ت ق ج ك ل لب ي، تعاريفه: م.\r6 ـ مسائل: ق م، مسائل ههنا: ج، فعولا: ت ف ك ل لب ي.\r7 ـ مسئلة ا: ت: ف ت ق ك لب م ـ: ي. بتوصل: ا ت ف ق ك ل ي، ليوصل: لب م ج.\r8 ـ فان ... بان ص 126: ت ق م، فان صدق اين الناظر بان: ك.\r9 ـ لزمه: ا ج ف ق ك لب ي، حتى لونه: م، حتى لزمه: ج ل ت.\r10 ـ فلا: ت ف ج ك لب م ي. ولا: ا.\r11 ـ للتصديق: م، التصديق: ك، من التصديق: ق."], [122, "ثم المستلزمان إن كانا يقينيين كان اللازم كذلك، وان كانا ظنيين أو أحدهما، كان اللازم كذلك. ومنهم من جعل الفكر أمرا وراء هذه التصديقات المترتبة إما عدميا وهو الّذي يقال: الفكر تجريد العقل عن الغفلات، أو وجوديا، وهو الّذي يقال: الفكر هو تحديق العقل نحو المعقول. وهذا كما أن الرؤية بالعين يتقدمها النظر الى المرئى: وهو تقليب الحدقة نحو المرئى التماسا لرؤيته بالبصر. فكذا الرؤية بالعقل يتقدمها تحديق العقل نحو المطلوب المعقول، التماسا لرؤيته بالبصيرة.\rمسئلة: ب (2):\rالفكر المفيد للعلم موجود. والسمنية أنكروه مطلقا. وجمع من المهندسين اعترفوا به فى العدديات والهندسيات، وأنكروه فى الالهيات. وزعموا أن المقصد الأقصى فيها الأخذ بالأخلق والأولى. وأما الجزم، فلا سبيل إليه.\r__________________\r1 ـ به يشين: ا ج ق ت ك ل، يقينين: م.\r2 ـ كلان اللازم: ا ت ي ج ل، فاللازم، ف ك م، واللازم: ق، ظنى فاللازم: لب، امرا: ت ف ق ك لب م، امرا اخر: ي.\r3 ـ المترتبة: ت ق م، المرتبة: ك ج ل ت. وهو: م ت، فهو: ق.\r4 ـ الفكر: ت م، للفكر: ق.\r5 ـ المعقول: ا ت ف ك لب ي. المعقولات: ق م. النظر: ا ت ف ج ق ك ل لب ي. تحديق النظر: م.\r6 ـ المرلى: ت ف ج ق ك ل لب ي. المرء: م. فكذا: ف ت ك لب ي، وكذا: ق م.\r7 ـ المطلوب المعقول: ا، المعقول: ت ج ف ل ك، المطلوب: ق لب م ي.\r9 ـ مسئلة ب: ت، مسئلة: ف ق ك لب م، ب: ي.\r12 ـ فيها: ت ق ك م، فيها: ي، بالاخلق والاولى: ا ت ج، بالاولى والاخلق: ف ل ق لب م ي، بالاولى والاخلق والاخرى: ك.\r12 ـ و: ا ف ق ي ج، ـ: ت ك لب م."], [123, "لنا أن كل واحدة من مقدمتى المثال المذكور يقينى، وقد يجتمعان فى الذهن اجتماعا مستلزما للنتيجة المذكورة فالنظر المفيد للعلم موجود. واحتج المنكرون للنظر مطلقا بأمور أربعة:\rأولها: العلم بأن الاعتقاد الحاصل عقيب النظر، علم لا يجوز أن يكون ضروريا. لأن كثيرا ما ينكشف الأمر بخلافه، ولا نظريا، والا لزم التسلسل.\rوثانيها: أن المطلوب ان كان معلوما فلا فائدة فى طلبه، وان لم يكن معلوما فاذا وجده كيف يعرف أنه مطلوبه.\rوثالثها: أن الانسان قد يكون مصرا على صحة دليل زمانا مديدا. ثم يظهر له بعد ذلك ضعفه بدليل ثان. وذلك الاحتمال قائم فى ذلك الثانى. ومع قيام الاحتمال لا يحصل اليقين.\r__________________\r1 ـ واحده: ت ف ي. واحد: ك ل لب ج م. مقدمنى: ا ت ج ك ل ف ي، مقدمتين في: قم المذكور: ت ف ق ك لب ل ي. المذكورة: م، يقيني: ت ق ك لب م ي، يلنية: ف، وقد: ت ق م، قد: ك.\r2 ـ فا: نسخ، وا: ت ق.\r3 ـ و: ا ت ك لب ي، ف ج ق ل م، النظر: م، له: ت ج ك ي، ا ف ق لب ل، بامور اربعة: ت ج ف ق ك م ي، باربعة امور: لب.\r4 ـ اولها: ف ج ق ل ك لب م ي، احدنا: ت: العلم: نسخ، ان العلم: ق.\r5 ـ لان: ا ج ق، اذ كثيرا ما: ت ف، اذ كثيرا ما: ي، اذ كثيرا: ك لب ل م.\r7 ـ وثانيها: ل ت ج م ف، وهو محال و: ق ك لب ي فيها: ق ك لب م ي، ت: ا. وان لم يكن معلوما: ا ك، والا: ت ج م ي ل،: ق.\r8 ـ فاذا: ت ك م، واذا: ق، اذا: ي، وجده: نسخ، اوجده: ق، كيف: ت ج ف ق ك لب م، فكيف: ي.\r9 ـ وثالثها أن: ف ق ج لب ل م، وثالثها: ت ك، ج: ا.\r10 ـ مديدا: نسخ، طويلا: ق.\r11 ـ اليقين: ت ج ف ل ق ك لب ي، التعين: م."], [124, "ورابعها: أن العلم بالمقدمتين لا يحصل دفعة فى الذهن بدليل أنا نجد من أنفسنا أنا متى وجهنا الذهن نحو استحضار معلوم يتعذر علينا فى تلك الحالة توجيهه نحو استحضار معلوم آخر. فالحاضر فى الذهن أبدا، ليس الا العلم بمقدمة واحدة وذلك غير منتج بالاتفاق فالفكر لا يفيد العلم.\rواحتج المنكرون للنظر فى الالهيات بوجهين:\rأحدهما: ان امكان طلب التصديق موقوف على تصور الموضوع والمحمول.\rوالحقائق الالهية غير متصورة لنا لما سبق: انا لا نتصور الا ما نجده بحواسنا أو نفوسنا أو عقولنا فاذا فقد التصور الّذي هو شرط التصديق، امتنع التصديق.\r__________________\r1 ـ ورابعها ان: ق ك لب ي، ورابعها: ت ف، رابعها ان: م، د: ا، دفعة: ت ج، دفعة واحدة: ا، معا: ف ق ل ك لب م ي.\r2 ـ نجد من: ت ج ك، نجد في: ق م، انا متى: ج ل ت م، متى: ك ق.\r2، 3 ـ يتعذر علينا: ا ت ج: تعذر علينا: ق ك لب ل ي، تقدر عله: م،: ف.\r3 ـ في تلك الحالة الحال: ق .. معلوم: ت ق ج ك لب ل م ي: ف. توجيهه: ت ق م، توجه: ك.\r4 ـ بمقدمة واحدة: ت ج ف ق ك لب م ي. بالمقدمة الواحدة: ا.\r6 ـ واحتج: ت ج ف ق ك ل لب ي، احتج: م، بوجهين: ت ج ق ك ل لب م ي، لوجهين: ف.\r7 ـ احدهما ان: ف ج ق ل ك لب م ي، الاول: ت،: ا.\r9 ـ الالهية: ا ت ف ج ق ل م ي، سبحانه وتعالى تقدس: لب، سبحانه وتعالى: ك، انا لا: ت ف ج ق ك لب ي، فانا لا: ا، انا: م.\r10 ـ او (1): ت ف ج ل لب م، و: ك ي، فاذا: ا ت ج لب، واذا: ف ق ك م ي، في: ق: في انفسنا وحواسنا وعقولنا."], [125, "وثانيهما: أن أظهر الأشياء للانسان وأقربها منه هويته التى يشير إليها كل أحد بقوله: انا ثم ان العقلاء اختلفوا فيها اختلافا لا يكاد يمكن الجزم بواحد منها.\rفمنهم من قال: هو هذا الهيكل المحسوس.\rومنهم من قال: أجسام سارية فيه.\rومنهم من قال: جزء لا يتجزأ فى القلب.\rومنهم من قال: المزاج.\rومنهم من قال: النفس الناطقة.\rواذا كان علم الإنسان بأظهر الأمور له وأقربها منه كذلك، فكيف يكون حاله فى معرفة أخفى الأمور وأبعدها مناسبة عنه؟.\rوالجواب عن الأول: أنه نظرى والتسلسل غير لازم لأن لزوم النتيجة عن المقدمتين اذا كان ضروريا وكانتا ضروريتين: اما ابتداء أو بواسطة شأنها كذلك وعنده علم ضرورى بأن اللازم عن الضرورى\r__________________\r1 ـ ايضا وثانيهما: ف ل لب م، ايضا: ق وثانيها: ف ج ك ي، الثاني: ت، ت: ا، ان: نسخ،: ت.\r1، 2 ـ يشير اليها كل احد احا ـ: ج: ا ت ي ج، اليها يشير: ف ل ق ك لب م.\r2 ـ فيها: ا ت ج، في تلك الهوية: ف ل ق ك لب م ي.\r3 ـ يكاد: ت ج ق ك م ي، ـ: ا.\r4 ـ هو: ا ت ف، هي: ق ك لب م ي.\r6 ـ الالب: ت ف ق ك لب م ي، القلوب: ا.\r9 ـ الامور: نسخ، الاشياء: ت، له: ت ق ك لب ي، ـ: ف م.\r10 ـ حاله ... عنه: ت ي في ابعدها: ق.\r11 ـ و (1): ت ف ق ك لب ي، ـ: م، غير: ا ج ت ف ق ك ل لب ي، عن: م.\r12 ـ و: ا ت ق ج ك لب ل ي، ـ: ف م.\r13 ـ او: ت ف ق ك لب م، واما: ي، كذلك: نسخ، ذلك: ت، بان: ت ف ق لب م، ان: ك ي."], [126, "ضرورى، علم بالضرورة ان الحاصل علم.\rوعن الثانى: أنه معلوم التصور مجهول التصديق، والمطلوب هو التصديق فاذا وجده ميزه عن غيره بالتصور المعلوم.\rوعن الثالث أنه معارض بأغلاط الحس.\rوعن الرابع: انا قد نعقل القضية الشرطية وهى مركبة من جملتين، والحكم بلزوم احدى الجملتين للأخرى يستدعى حضور العلم بهما حال الحكم بذلك اللزوم، وذلك يدل على امكان اجتماع العلمين دفعة فى الذهن.\rوعن الخامس: هب ان تلك الماهيات غير متصورة بحسب حقائقها، لكنها متصورة بحسب عوارضها المشتركة بينها وبين المحدثات. وذلك كاف فى امكان التصديق.\rوعن السادس: أن ما ذكرتموه يدل على صعوبة تحصيل هذا العلم لا على تعذره.\rمسئلة ج (3):\rلا حاجة فى معرفة الله سبحانه وتعالى وتقدس الى المعلم عندنا،\r__________________\r1 ـ الحاصل: ت م، العلم الحاصل: ق.\r2 ـ وجده: ت ف ق ك لب م، وجد: ي، عن غيره: ف ق ك لب م، من غيره: ي، ـ: ت.\r4 ـ باغلاط: ت ف ق ك م، بفلط: لب ي.\r5 ـ نعقل: نسخ، يعقل: ت، من: ت ك م، عن: ا ل ق ي.\r6 ـ حضور: ت ف ق لب م ي، حصول: ك.\r8 ـ دفعة: ت م، دفعة واحدة: ق، في الذهن ـ: ت فقط، في الذهن دفعة: ج دفعة واحدة: ل.\r9 ـ الماهيات: ت ف ق ك ل لب م، الماهية: ي، الالهيات: ج بينها: ا ت ج ف ك لب ي، بينهما: ق م.\r12 ـ ذكرتم: ف فقط.\r14 ـ مسئلة ج: ت، مسئلة: ف ق ك لب م، ج: ي.\r15 ـ سبحانه وتعالى: ت، تعالى: ا ف ج ق ك لب ي، تعالى وتقدس: م، عندنا: ق، ـ: ت ك م ي."], [127, "خلافا للملاحدة.\rلنا أنه متى حصل العلم بأن العالم ممكن، وكل ممكن فله مؤثر، علمنا أن العالم له مؤثر، سواء كان هناك معلم أو لم يكن.\rواعتمد الجمهور منا، ومن المعتزلة فى ابطال قولهم على وجهين:\rأحدهما: أن حصول العلم بالشيء، لو افتقر الى معلم لافتقر المعلم بكونه معلما الى معلم آخر، ولزم التسلسل.\rوالثانى: أنا لا نعلم كون المعلم صادقا الا بعد العلم بأن الله سبحانه وتعالى صدقه بواسطة اظهار المعجزة على يده فلو توقف العلم بالله تعالى على قوله للزم الدور. وهذان الوجهان ضعيفان عندى.\rأما الأول فلاحتمال أن يكون عقل النبي والامام أكمل من عقول\r__________________\r1 ـ للملاحدة: ت ج ل ف ق ك لب ي، للملاحدة لعنهم الله تعالى: م: ا م.\r2 ـ انه: ت ق ك م، ان نقول: ي، فله: ت م، له: ق ك ي.\r3 ـ العالم له مؤثر: ت ج ق ك م ي، للعالم مؤثرا: ا، او لم يكن: ا ت ج لب ل ي، ام لا: ف ق ك م.\r5 ـ وجهين: ا ت ج، امرين: ف ق ك لب ل م ي.\r6 ـ احدهما: نسخ،: ا.\r7 ـ المعلم: ت ف، علم ذلك المعلم: ا، علمه: ف ق ك لب م ي، لزم: ا ت ف ق ك لب م، لزم منه. ي، يلزم: ا.\r8 ـ والثاني: ت ف ق ك لب م ي، ت: ا. انا: ت م، انه: ق، نعلم: ت م، يعلم: ق.\r9 ـ سبحانه و: ت ق ك، ـ: م ج، المعجزة: ت م، المعجزات: ك.\r10 ـ تعالى: ت ح ف، سبحانه وتعالى: ك م، سبحانه: ق، ـ: ا ي، وهذان: ا ت ف ق ك لب ي، فهذان: م.\r12 ـ النبي والامام: نسخ، الامام والنبي: ت ج، الشيء والامام: ق."], [128, "سائر الخلائق، فلا جرم كان عقله مستقلا بادراك الحقائق، وعقل غيره لا يكون مستقلا، فكان محتاجا إلى التعليم.\rوأما الثانى فلأن ذلك انما يلزم على من يقول: العقل معزول مطلقا، وقول المعلم وحده مفيد للعلم. أما من يقول: العقل لا بد منه لكنه غير كاف، بل لا بدّ معه من معلم يرشدنا إلى الأدلة، ويوقفنا على الجواب عن الشبهات، لا يلزمه ذلك؛ لأنه يقول: عقولنا غير مستقلة بمعرفة الدلائل فى الجواب عن الشبهات. فلا بد من امام يعلمنا تلك الأدلة والأجوبة حتى إن بواسطة تعليمه وقوة عقولنا، نعرف تلك الحقائق. ومن جملة تلك الحقائق هو أن يعلمنا ما يدل على إمامته وعلى هذا التقدير لا يلزم الدور والتسلسل.\rواحتجوا بأنا نرى الاختلاف مستمرا بين أهل العلم ولو كفى العقل لما كان كذلك. ولأنا نرى أن الانسان وحده لا يستقل بتحصيل\r__________________\r1 ـ الخلاق: ا ف ج، الخلق: ق ل ت ك لب ي، الناس: م.\r1، 2 ـ مستقلا ... لا سكون لم يكن: ف ك لب م ي .. فكان وكان: م: ا ف ك لب م ي، كامي وعقل غيره لا يكون كافيا: ت.\r4 ـ وحده مفيد نلعلم: ت ك ج لب م، وحده يفيد العلم: ق ي، مفيد للعلم وحده: ف، منه: نسخ، له منه: ت.\r5 ـ معلم: ت ج ف ق لب ي، معلم آخر: ك م.\r6 ـ عن: ا ت ق ج ك لب ي، في: م، لا يلزمه ذلك فلا يلزم ذلك: ي، لا يلزم ذلك منه: ا، ولا يلزم منه ذلك: م. لانه يقول: ا ت ف ج ق ك لب ي، لانا نقول: م.\r7 ـ في: ت ج، و: ك م.\r8 ـ ان: ا ت ل ي، انا: ف ق ج ك لب م، عقولنا: ت ف ق ك لب ي، عقلنا: م، علمنا: في المتن: ك، ولكن صحح.\r9 ـ جملة ـ: ت، ان: ت م، انه: ق ك.\r11 ـ احتجوا: ا ت ف ق ك ي، واحتجوا: م، فثبت ان لاقوى والمعتمد ما ذكرنا احتجوا: لب، العلم: تي ل، العالم: ف ق ج ك لب م.\r12 ـ لانا: ا ت ق ك لب ي، ـ: م، ان: ت م، ـ: ق ك، وحده ـ: ي فقط."], [129, "أضعف العلوم، بل لا بد له من أستاذ يهديه. وذلك يدل على أن العقل غير كاف.\rوالجواب عن الأول: أن من أتى بالنظر على الوجه المذكور لا يعرض له ما ذكرت.\rوعن الثانى أنه لا نزاع فى العسر لكن الامتناع ممنوع، والا لزم التسلسل ثم انا نطالبهم بتعيين ذلك الامام ونبين أنه من أجهل الناس.\rمسئلة د (4):\rالناظر يجب أن لا يكون عالما بالمطلوب لأن النظر طلب وطلب الحاصل محال.\rلا يقال: ربما علمنا الشيء ثم ننظر فى الاستدلال عليه بدليل ثان.\rلأنا نقول: المطلوب هناك لا المدلول، بل كون الثانى دليلا عليه، وهو غير معلوم، وأن لا يكون جاهلا جهلا مركبا؛ لأن صاحب هذا الجهل جازم بكونه عالما، وذلك يمنعه من الاقدام على الطلب. ثم\r__________________\r1 ـ الحلوم: ت ق م، المعلوم: ك، له: ت ق ج م، ـ: ف ك ي، يهديه: ت ف ج ق ك لب م، يهديه اليه: ي.\r2 ـ و: ت ج م، ـ: ق ك لب ل.\r4 ـ يعرض: ا ت ف ق ك ج لب ل ي، يعرف: م.\r5 ـ لكن: ت ج ك م، ولكن: ف.\r6 ـ انه من: ت ف ق ك م، بانه من: ي، انه: م، انه كان من: لب.\r7 ـ مسئلة د: ت: مسئلة: ف ق ك لب م، د: ي.\r10 ـ ننظر: ق م، ينظر: ت، نظرنا: ك.\r10، 12 ـ بدليل ... دليلا عليه: ت ف ق ك لب م، ـ: ي.\r13 ـ لا: ت ج ف لب ل، ليس: ق ك م.\r14 ـ يمنعه: ت ق ل ك لب م ي، يمنع: ف، من: ت ق ك لب"], [130, "امتناع الاجتماع ذاتى أو للصارف، فيه خلاف.\rمسئلة ه (5):\rالمشهور فى بيان وجوب النظر: أن معرفة الله تعالى واجبة، ولا يمكن تحصيلها الا بالنظر، وما يتوقف عليه الواجب المطلق، وكان مقدورا للمكلف فهو واجب على ما سيأتى بيانه فى أصول الفقه، ان شاء الله تعالى.\rالاعتراض عليه من وجوه:\rالأول: لا نسلم انه يمكن ايجاب العلم، لأن التصديق يتوقف على حصول تصور الطرفين، والتصور غير مكتسب على ما مر. ثم اذا حصلا، فان كان التصديق من لوازمهما كما فى الأوليات، لم يكن التصديق مكتسبا أيضا وان لم يكن ضروريا افتقر فيه الى توسيط\r__________________\rم، عن: ف ي.\r1 ـ الاجتماع: ت ف ج ق ك لب م، الاجماع: ي، او: ت ف ج ك م ي، ام: ا، و: ل، لوجود الصارف: ك، لقيام الصارف: ق، للصارف: ت ج ل لب م، لصارف: ف ي.\r2 ـ مسئلة د: ت، مسئلة: ق ك م،: ي، مشهور مسئلة: ف.\r3 ـ تعالى: نسخ سبحانه وتعالى: ك.\r4 ـ عليه الواجب المطلق: ت ا ج ل، الواجب المطلق عليه: ف ك لب م ي، الوجوب المطلق عليه: ق.\r5 ـ للمكلف: ت م، للعبد: ك، بيانه: ت فقط.\r6 ـ ان شاء الله تعالى: ت م،: ج ق ك.\r7 ـ والاعتراض: ق ل لب ي، الاعتراض: ت ج ف ك م.\r7، 8 ـ من وجوه الاول: ا: ا ت ج،: ف ق ك لب م ي ف.\r8 ـ لان: ا ت ف ق ك لب ي، وهذا لان: م.\r11 ـ مكتسبا ايضا: ت ق ج ك لب م ي، ايضا مكتسبا: ف. ضروريا: ف ك ل م، من لوازمهما: ا ت ج لب ي ف هامش، من لوازمها: ك،: ق، فيه الى توسيط: ا ج ت ق لب، فيه"], [131, "مقدمة أخرى. والحال فيها كما فى الأول، ولا يتسلسل الى غير نهاية، بل ينتهى الى الأوليات، وهى غير مكتسبة لا تصور طرفيها، ولا استلزام ذينك التصورين للتصديق باثبات أحدهما للآخر، أو سلبه عنه. ثم ان لزوم ما يلزم منها أيضا ضرورى.\rوكذا القول فى اللازم الثالث والرابع.\rفظهر أن العلوم غير مقدورة البتة، فكان الأمر بها أمرا بما لا يطاق، وانه غير جائز. ولو صح ذلك بطل أصل الدليل.\rالثانى: سلمنا امكان الأمر بالعلم لكن لا نسلم امكان الأمر بمعرفة الله سبحانه وتعالى؛ لأن معرفة الايجاب موقوفة على معرفة الموجب، فقبل معرفة الموجب لا يمكن معرفة الايجاب فيكون الأمر بمعرفة الموجب تكليفا بالمحال.\rالثالث: سلمناه، لكن لا نسلم ورود الأمر به، بل الأمر انما\r__________________\rالى توسط: ك ل م ي، الى توسط: ف.\r1 ـ والحال: ا ت ف ق ك لب ي، الحال: م، كما: ت ج ق ك م، كالحال: ي. نهاية: ت ج ك ي، النهاية: ل لب م.\r2 ـ طرفيها: ا ج ت ك لب ي، طرفها: م.\r3 ـ بانبات: ا ت ك ج ق لب ي، لاثبات: ف م، احدهما: ت ق م، احداهما: ك.\r4 ـ منها: ت م، عنها: ف ق ك ل ي، منهما: ج، ايضا: ت ق ك ج لب،: م.\r5 ـ كذا: ت ف ج ك لب م، كذلك: ق ي.\r6 ـ فظهر: ت م، فثبت: ق، البته: نسخ اخرى، البته ولا مكتسبة: لب.\r7 ـ ذلك: ا ف ج ق، ـ: ت ك لب م ي، لبطل: ك لب م، بطل: ا ت ق ج ف ي لب.\r8 ـ الثاني: ت ج، ت: ا، ا: نسخ اخرى ل ف م.\r9، 10 ـ سبحانه و: ت ك. موقوفة: ا ت ف ج ق ك لب، تتوقف: م ي. فقبل: ت ف ك لب م، وقبل: ق ي.\r10، 11 ـ الامر ... الموجب: نسخ، التكليف: ت.\r12 ـ الثالث: ت ج، ج: ا: ف ق ك لب م ي، سلمناه:"], [132, "جاء بالاعتقاد المطابق تقليدا كان أو علما؛ لأنه عليه الصلاة والسلام ما كان يكلف أحدا بهذه الأدلة.\rالرابع: سلمنا بأن التقليد غير كاف، لكن لم قلتم أن الظن الغالب غير كاف. والاعتماد على قوله تعالى: (فَاعْلَمْ) (*) ضعيف، لأن الظن الغالب قد يسمى علما؛ ولأن الخطاب خاص، ولأن الأدلة اللفظية غير يقينية، على ما سيأتى، ان شاء الله تعالى. فلا يمكن بناء المطالب اليقينية عليها.\rالخامس: سلمناه لكن ما الدليل على أنه لا طريق الى المعرفة سوى النظر. ثم إنا على سبيل التبرع نذكر طريقا آخر: وهو قول\r__________________\rت ك ج لب م، سلمنا و: ق ي، سلمنا: ف، سلمناه و: ل.\r1 ـ جاء: ت ق ج ك لب م ي، جاءنا: ف، المطابق: ت ك م، الحق المطابق: لب، الصلاة و: م،: ت ف ق ج ك لب ي.\r2 ـ كان يكلف: ت، كلف: نسخ اخرى، احدا: ا ت ج ف ق ك لب، واحدا: م.\r3 ـ الرابع: ت ج، د: ا: ف ك لب م ي، بان: ا، ان: ف ت ك لب م، ان قبل سلمنا في: ت، القالب: ا ت ج ف ك ل لب، ـ: م.\r4 ـ والاعتماد ... ضعيف: ت ف ج ل م، ـ: ك لب ي منسطوب عليه في ك، تعالى ـ: ت ج ل ف فقط، لان: ت ج ف ك ل لب م، ـ: ق ي.\r(*) سورة محمد: 19.\r5 ـ الظن ـ: ت فقط.\r6 ـ تعالى: ت ف ق لب م، ـ: ك ي.\r8 ـ الخامس: ت، ة: ا، ـ: ف ك لب م ي، سلمناه: ت ج ل ق لب، ـ: ف م، لكن: ا ت ف ج ق ك ي، ولكن: لب ل م. ما الدليل على: ت ق م، لا نلم: ك، ـ: لب.\r9 ـ النظر: ت ج ف م، النظر فما الدليل على ذلك: ك لب، طرق: ف ك لب م، طرقا: ي، طريقا: ت، آخر: ت ج ق ل م، اخرى: ك، ـ: لب، وهي: ف ك ل م ي، وهو: ا ج ت."], [133, "الامام المعصوم، أو الالهام، أو تصفية الباطن، كما يقوله أهل التصوف؛ ولأنا لو قلنا: لا طريق إلى المعرفة سوى النظر والاستدلال، لكان المسلم اذا ناظر الدهرى وانقطع فى الحال، وجب أن لا يبقى على الدين. لأن الشك فى مقدمة واحدة من الدليل كاف فى حصول الشك فى المدلول، وذلك يقتضي أن يخرج المسلم عن الدين فى كل لحظة، بسبب كل ما يهجس فى خاطره من الأسئلة.\rالسادس: سلمناه، لكن لم قلتم: إن ما لا يتم الواجب الا به فهو واجب؟.\rفان قلت: لو لم يجب لكان ذلك تكليفا بما لا يطاق.\rقلت: ولم قلت: إنه غير جائز، بل التكاليف بأسرها كذلك؟. لأن ما علم الله تعالى وقوعه وجب، وما علم الله عدمه امتنع.\rالسابع: سلمناه لكن تكليف ما لا يطاق انما يلزم إن لو كان الأمر بالمعرفة ثابتا على الاطلاق، وهو ممنوع. فلم لا يجوز أن تكون\r__________________\r1 ـ تصفية: تصفه: ل، الباطن: ت ف ج ق ك لب م، الخاطر: ي، على ما: ف ق ك ل لب ي، كما: ت ج م.\r2 ـ قلنا: ا ت ج، قلنا انه: ف ق ك ل م ي. الى المعرفة: لب ـ: ق ك م، سوى: ت ف ج ك ل لب م، الا: ى.\r3 ـ اذا: نسخ، اذ: ت.\r4 ـ عن الدين: تاخر في: ت الى بعد لحظة.\r7 ـ السادس: ت ج، و: ا، ـ: ف ق ك لب م ي، سلمناه قال ق ك لب، سلمنا: ت م ي ج، نكن: ت ف ق ك م، ولكن: لب ي، قلتم: ت م ج، قلت: ك، قلت لانه: لب، قلت: ت ج ق ك م ل.\r10 ـ ولم: ت ق م ي، فلم: ف لب، قلتم: ا لب، قلت: ت ف ق ك م ي، انه: نسخ، بانه: ت.\r11 ـ تعالى: ت ق ك لب م ي، ـ: ف ج. وقوعه: ق م ل، وجوده: ت ج ك. علم الله: ا ت، علم: ف ج ق ك ل لب م ي.\r12 ـ السابع: ت ج، ز: 1، ـ: ف ق م ي. سلمناه: ت ج ك ل لب م، سلمنا: ف ق ي، لكن: ت ج ق ك ل م،"], [134, "صيغة الأمر، وان كانت مطلقة فى اللفظ لكن فى المعنى تكون مقيدة، كما فى قوله تعالى: (وَآتُوا الزَّكاةَ) (*).\rوالجواب عن هذه الأسئلة وان كان ممكنا، ولكن الأولى التعويل على ظواهر النصوص كقوله تعالى: (قُلِ انْظُرُوا) (*) والله أعلم.\rمسئلة: و (6):\rوجوب النظر سمعى خلافا للمعتزلة ولبعض الفقهاء من الشافعية والحنفية لنا قوله تعالى: (وَما كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولاً) (*). ولأن فائدة الوجوب الثواب والعقاب. ولا يقبح من الله تعالى شيء فى أفعاله، فلا يمكن القطع بالثواب والعقاب من جهة العقل فلا يمكن القطع بالوجوب.\rاحتجوا بأنه لو لم يثبت الوجوب الا بالسمع الّذي لا يعلم صحته\r__________________\rولكن: لب، ان: ت ج لب، ـ: ق ل ك م ف.\r1 ـ تكون: ا ج ت ك ل ي، ـ: ف م.\r2 ـ كما في قوله: ت ج ف ل ق ك م، كقوله: ي، تعالى: ت ج ق ك ل م، ـ: ا.\r(*) سورة البقرة: 110.\r3 ـ و (1): ا ت ق ج ل ك ي، ـ: ف م، كان: ت ف ق ك م ي، كانت: ا، و (2): ا ف ل ك، ـ: ت ج ق م ي.\r4 ـ ظواهر: ت ف ق ل لب م، ظاهر: ا ج ي، ـ: ك. والله اعلم: ت فقط.\r(*) سورة يونس: 111.\r5 ـ مسئلة و: ت، مسئلة: ف ق ك لب م، و: ق.\r6 ـ لبعض: ت، بعض: نسخ ج، الشافعية: نسخ ل، الشفعوية: ت ج.\r(*) سورة الاسراء: 15.\r8 ـ الثواب: ت ق م، انما هو الثواب: ك. تعالى ـ: ا ج فقط. شيء: تقدم على من في: ت. في: ج ت ل ف ك، من: ق لب ج م ي.\r11 ـ احتجوا: ا ت ف ق ك ل لب ي، واحتجوا: ج م."], [135, "الا بالنظر، فللمخاطب أن يقول: لا أنظر حتى لا أعرف كون السمع صدقا وذلك يفضى الى افحام الأنبياء.\rوالجواب: هذا لازم عليكم أيضا، لأن وجوب النظر، وان كان عندكم عقليا، لكنه غير معلوم بضرورة العقل، لما أن العلم بوجوب النظر يتوقف عند المعتزلة على العلم بوجوب معرفة الله تعالى، وعلى العلم بأن النظر طريق إليها ولا طريق إليها سواه، وان ما لا يتم الواجب الا به، فهو واجب. وكل هذه المقدمات نظرى، والموقوف على النظرى نظرى، فكان العلم بوجوب النظر عندكم نظريا.\rفللمخاطب أن يقول: لا أنظر حتى لا أعرف وجوب النظر. ثم الجواب ان الوجوب لا يتوقف على العلم بالوجوب، وإلا لزم الدور،\r__________________\rلا يعلم: ف ت ك م، لم يعلم: ت، لا نعلم: ي.\r1 ـ لا انظر: نسخ، انى لا انظر: م، لا (2)، ـ: ت ك فاط.\r2 ـ يفضى: ا ج ت ف ق ك لب ي، مفض: م، الانبياء: نسخ، الانبياء عليهم السلام والجنة: ق.\r3، 4 ـ هذا: ا ت ج ف ك لب ي، ان هذا: ق م، هذه: ل. ايضا: ت ف ك لب م ج ل، ـ: ا ي ق، عندكم: ا ت ق م، ـ: ك.\r4 ـ بضرورة: ت ق لب ك م، لضرورة: ف، لما: ت ج ف ل ق لب م، كما: ك ي.\r4، 5 ـ بوجوب النظر: ت م، بالوجوب: ق.\r5 ـ يتوقف عند المعتزلة: نسخ، عندكم بتوقف: ت ج.\r5، 6 ـ وعلى العلم بان: ا ت ج، وان: ف ق ك ل لب م ي.\r6 ـ ولا طريق اليها سواه: ت ج ف ق م، لا طريق سواه: ك، ولا طريق اليها لا سوله: ي، وان ما لا: ت ق لب م ي، ان لا ما: ف، انما لا: ك.\r7 ـ كل: ا ت ف ج ق ك لب ل ي، كل واحد من: م. نظرى: ت ج ف لب م، نظرية: ق ك ي ل.\r8 ـ عندكم: ا ت ج ك، عندهم: م ل، ـ: ف ق ي.\r9 ـ يقول: ت ج ق ك لب م ي، يقول ان: ف، لا اعرف: ت ق م، اعرف: ك.\r10، (1/ 136) ـ والا .. بالوجوب ـ: ق."], [136, "بل يكفى فيه امكان العلم بالوجوب والامكان هنا حاصل فى الجملة.\rمسئلة ز (7):\rاختلفوا فى أول الواجبات فمنهم من قال: هو المعرفة، ومنهم من قال: هو النظر المقيد للمعرفة، ومنهم من قال: هو القصد الى ذلك النظر. وهو خلاف لفظى، لأنه ان كان المراد به أول الواجبات المقصودة بالقصد الأول، فلا شك أنه هو المعرفة عند من يجعلها مقدورة والنظر عند من لا يجعلها مقدورة وان كان المراد به أول الواجبات كيف كان، فلا شك انه القصد.\rمسئلة ح (8):\rحصول العلم عقيب النظر الصحيح بالعادة عند الأشعرى، وبالتولد عند المعتزلة والأصح الوجوب لا على سبيل التولد. أما الوجوب، فلأن كل من علم أن العالم متغير، وكل متغير ممكن، فمع حضور هذين العلمين فى الذهن يستحيل أن لا يعلم أن العالم ممكن. والعلم بهذا\r__________________\r1 ـ فيه: ت ج ف ك لب م ي، ـ: ا، هنا: ت ف ك لب ي، ههنا: ا ق.\r2 ـ مسئلة ز: ت، مسئلة: ف ق ك لب م، ز: ي.\r3 ـ فمنهم: ا، منهم: ت ج ف ق ك لب م ي.\r4 ـ ذلك: ت ج ف ق ك ب ي، هذا: م.\r5 ـ وهو: ت ج ف ل ق ك لب ي، وهذا: م، به: ت ف لب، منه: م، ـ: ق ك ل ي ج، اول: بلول: ج.\r6 ـ المقصودة: المقصود: ج.\r7 ـ لا يجعلهنا لم يجعلها: ت مقدورة: ا ت ج، لا يجعل العلم ما تدورا: ف ق ك ل لب م ي، به: ت ج ف، ـ: ق ك ل م ي.\r8 ـ كان: ا ت لب ي، كانت: ف ق ك م.\r9 ـ مسئلة ح: ت، مسئلة: ف ق ك م، ح: ي.\r10 ـ وبالتولد: ت ج ف م ي، رضي الله عنه رحمه الله: ق وبالتولد: ق ل ك، وبالتولد: لب، ومتولدا: ا، متولد: ل.\r13 ـ يعلم: ت ف ق ك لب م، نعلم: ي."], [137, "الامتناع ضرورى. وأما إبطال التولد فلأن العلم فى نفسه ممكن فيكون مقدورا لله تعالى، فيمتنع وقوعه بغير قدرته. والقياس على التذكر لا يفيد اليقين، ولا الالزام، لأنهم انما لم يقولوا به فى التذكر لعلة لا توجد فى النظر فان صحت تلك العلة ظهر الفرق، والا منعوا الحكم فى الأصل.\rمسئلة: ط (9):\rالنظر الفاسد لا يولد الجهل ولا يستلزمه عند الجمهور منا ومن المعتزلة. وقيل: انه قد يستلزمه، وهو الحق عندى، لما ان كل من اعتقد أن العالم قديم، وكل قديم مستغن عن المؤثر، فمع حضور هذين الجهلين استحال أن لا يعتقد أن العالم غنى عن المؤثر وهو جهل.\rاحتجوا بأن النظر فى الشبهة لو استلزم الجهل، لكان نظر المحق فى شبهة المبطل يفيد الجهل.\r__________________\r1 ـ الامتناع: ت ق ك لب م ي ف هامش، الانتاج: ف، ابطال: ا ت ج ق ل ك لب ي، بطلان: ف م.\r2 ـ تعالى ـ: لب، فيمتنع ـ: ي، بغير قدرته: ف ق ك لب م: بغير قدرة الله تعالى: ج ت ج، من غير قدرة: ي، بغير فدرة: ل.\r3 ـ لم يقولوا به: ا ف ق لب، لم يقولوا: م ل، يقولون به: ت، يقولونه: ك ي.\r4 ـ في النظر: في غيره: ج.\r6 ـ مسئلة ط: ت، مسئلة: ف ق ك لب م، ط: ي.\r8 ـ انه: ـ: ف فقط، يستلزمه: ا ت ج ك لب ي، استلزمه: ق، يستلزم: م. لما، ت ف ج ق م، كما: ك، لنا: ي.\r9 ـ وكل قديم: ت ف ق ك م ي، القديم: ا. مستغن: ت ق ك لب م ي، يستغنى: ف.\r10 ـ يعتقد: ت ف ق ك لب م، معتقد: ي.\r11 ـ جهل: ت ق ج ك لب م ي، الجهل: ف.\r12 ـ يفيد: ا لب ي، يفيده: ت ف ج ق ك ل م."], [138, "جوابه أنه معارض بأن النظر فى الدليل، لو أفاد العلم لكان نظر المبطل فى دليل المحق يفيده العلم. فان جعلت هناك شرط الافادة اعتقاد حقية تلك المقدمات، فهو جوابنا عما قالوه.\rمسئلة ى (10):\rقد عرفت أن الفكر: ترتيب تصديقات يتوصل بها الى تصديقات أخر. ثم التصديقات المستلزمة إن كانت مطابقة لمتعلقاتها، فهو الفكر الصحيح، والا فهو الفكر الفاسد.\rمسئلة يا (11):\rذكر ابن سينا أن حضور المقدمتين فى الذهن لا يكفى لحصول النتيجة. فان الانسان قد يعلم أن هذا الحيوان بغلة، وأن كل بغلة عاقر. ومع هذين العلمين، ربما رأى بغلة منتفخة البطن، فيظن أنها غير عاقر، بل لا بد مع حضور المقدمتين من التفطن لكيفية اندراج المقدمة الجزئية تحت الكلية، وهذا ضعيف؛ لأن اندراج احدى المقدمتين تحت الأخرى:\r__________________\r2 ـ المحقق: ك فقط. شرطا لا فادة: ق فقط.\r4 ـ مسئلة ي: ت، مسئلة: نسخ، ي: ي.\r5 ـ الفكر: ا ت ج ك، الفكر هو: ق لب م ل ي، الفكر وهو: ف ك م ي، باعتقاده: ا. يتوصل: ا ت ج ف ق ل لب ي. يتوسل: ك م.\r8 ـ مسئلة يا: ت، مسئلة: ف ق ك لب م، يا: ي.\r9 ـ ذكر: نسخ، ذهب: ي. ان حضور: ت ج ق ل م، ان حصول: ف ك لب، الى ان حصول: ي. في الذهن ـ: فقط، لحصول: ت ف م، في حصول: ك.\r11 ـ هذين العلمين: ت ق م، هذا العلم: ك. فيظن: ت ج ف ق ل لب ي، فظن: ك م.\r12 ـ غير عاقر: ت ج م، حامل: ف ق ك لب، حبلى: ي لب، بل لا: ت ك لب م ي، فلا: ف."], [139, "اما أن يكون معلوما مغايرا لتينك المقدمتين، واما أن لا يكون. فأن كان مغايرا كان ذلك مقدمة أخرى لا بد منها فى الانتاج ويكون الكلام فى كيفية التئامها مع الأوليين كالكلام فى كيفية التئام الأوليين ويفضى ذلك إلى اعتبار ما لا نهاية له من المقدمات، وان لم يكن ذلك معلوما مغايرا للمقدمتين، استحال أن يكون شرطا فى الانتاج، لأن الشرط مغاير للمشروط. وهنا لا مغايرة فلا يكون شرطا.\rوأما حديث البغلة فذلك انما يمكن، اذا كان الحاضر فى الذهن احدى المقدمتين فقط. اما الصغرى أو الكبرى أما عند اجتماعهما فى الذهن فلا نسلم أنه يمكن الشك فى النتيجة.\rمسئلة: يب (12):\rاختلفوا فى أن العلم بوجه دلالة الدليل على المدلول هل هو عين العلم بالمدلول أم لا؟. والحق أن هاهنا أمورا ثلاثة:\r__________________\r1 ـ لتينك: ت ج ف ق لب، لتيك: ا ي ل، لتلك: ك م.\r2 ـ الاوليين (1) ـ ا ف ج ق لب ي، الاولتين: ت، الاولين: م. الاوليين (2): ق ك، الاولتين: ت، الاولين: م، الاولسن (1، 2): ك.\r6 ـ مغاير: ا ت ف ق لب، مغايرا: ق ك م ي. هنا: ا ت ج ف، ههنا: ك ل م، هذا لب ي، ـ: ق، فلا: نسخ ج ل، فيه فلا: ي. لا مغايرة ... شرطا: نسخ، ـ: ق.\r7 ـ فذلك ... يمكن: ا ت ج ف ق ل ك ي، فذلك انها يكون: ك، فكذلك انما يكون: م.\r8 ـ الكبرى: نسخ، الكبرى و: ي.\r9 ـ في الذهن: ا ت ف ج ق ك لب ل ي، ـ: م، نسلم انه: ـ: ك فقط.\r10 ـ مسئلة يب: ت، مسئلة: ف ج ق ك لب م، يب: ي.\r12 ـ ام لا: ف ق لب م، ام غيره ت ج، ـ: ا ك ل ي. والحق: ت ج ق ك م، فالحق: ي. ان: ت ق م، ـ: ك. ههنا امورا: ا ق لب، هنا امورا: ج ي، ههنا امور: ف ل ك، هنا امور: ت م."], [140, "العلم بذات الدليل، كالعلم بامكان العالم، والعلم بذات المدلول، كالعلم بأنه لا بد له من مؤثر، والعلم يكون الدليل دليلا على المدلول.\rاما العلم بذات الدليل فهو مغاير للعلم بذات المدلول. ومستلزم له.\rوأما العلم بكون الدليل دليلا على المدلول، فهو أيضا مغاير للعلم بذات الدليل والعلم بذات المدلول؛ لأنه علم باضافة أمر إلى أمر. والاضافة بين الشيئين مغايرة لهما. فالعلم بها مغاير للعلم بهما ولا يجوز أن يكون المستلزم للعلم بالمدلول هو العلم بكون الدليل دليلا عليه لأن العلم بإضافة أمر إلى أمر يتوقف على العلم بالمضافين. فالعلم بكون الدليل دليلا على المدلول متوقف على العلم بوجود الدليل والمدلول. فلو كان العلم بوجود المدلول مستفادا من العلم بكون الدليل دليلا على المدلول لزم الدور، وهو محال.\r__________________\r2 ـ له ـ: ك فقط.\r6 ـ ايضا مغاير: ا ت ق ج ك لب ل ي، مغاير ايضا: ف م.\r7 ـ العلم بذات: ت ج، ذات: ف ق ك لب ي، ـ: م.\r10 ـ عليه: نسخ، عليه لانه علم باضافة ام الى امر: ق. بالمضافين: ت ف ج ق ك لب ي، المتضافين ا، المتضايفين: م.\r11 ـ المدلول: نسخ، ـ: ا، متوقف: ت ك، يتوقف: م، الدليل و: ا، ـ: ت ف ق ك لب م.\r13 ـ على المداول: ا، عليه: ف ق ك لب م ي، ـ: ت، وهو: ا ت ج ف ق ك ي، وانه: ف م، محال: ا ج ت ف ق لب ي، محال وبالله التوفيق: ك م."], [141, "المقدمة الثالثة\rفى الدليل وأقسامه\rوفيها أربع مسائل:\rمسئلة: ا (1):\rالدليل هو الّذي يلزم من العلم به العلم بوجود المدلول. والامارة هى التى يلزم من العلم بها ظن وجود المدلول. وكل واحد منهما إما أن يكون عقليا محضا أو سمعيا محضا أو مركبا منهما.\rاما العقلى، فلا بد وأن يكون بحيث يلزم من وجوده وجود المدلول. فاللزوم حاصل لا محالة من هذا الطرف، فان لم يحصل من الطرف الآخر فهو الاستدلال بالمشروط على الشرط، كالاستدلال بالعلم على الحياة. وان حصل من الطرف الآخر، فهو الاستدلال بالعلة المعينة على المعلول المعين، وبالمعلول المعين على العلة المطلقة أو المعينة، ان ثبت التساوى بدليل منفصل، أو بأحد المعلولين على الآخر،\r__________________\r3 ـ وفيها اربع مسائل: ت ق، وفيه اربع مسائل: ا ي. ـ: ف ك لب م.\r4 ـ مسئلة ا: ت، مسئلة: نسخ.\r6 ـ هي التي: ا ج ت ل ف ق لب، التي: ك، هو الذي: م ي، بها: ت ك لب م ي، به: ف، وكل: ت ج ف ك لب م، فكل: ي.\r8 ـ العقلي: ت ج ف ق ك م، العقل: ي، وان: ت ف ج ق ك م، من ان: ا ي، بحيث: ت ج م، بحال: ف ق ك ي.\r12 ـ بالمعلول: ا ج ت ف ق ك ي، المعلول: م، او: ك فقط، المطلقة بعد المعينة في: ت.\r13 ـ الآخر: ا ج ت، الثاني: ف ق ك لب م ي."], [142, "وهو مركب من الأولين أو بأحد المتلازمين على الآخر كالمضافين.\rأما السمعى المحض، فمحال، لأن خبر الغير ما لم يعرف صدقه لم يفد. واما المركب فظاهر.\rمسئلة ب (2):\rالدليل اللفظى لا يفيد اليقين الا عند تيقن أمور عشرة:\rعصمة رواة مفردات تلك الألفاظ وصحة اعرابها، وتصريفها، وعدم الاشتراك، والمجاز، والتخصيص بالأشخاص، والأزمنة، وعدم الاضمار، والتقديم، والتأخير. وعدم المعارض العقلى الّذي لو كان لرجح. اذ ترجيح النقل على العقل يقتضي القدح فى العقل المستلزم للقدح فى النقل، لافتقاره إليه واذا كان المنتج ظنيا فما ظنك بالنتيجة؟\rمسئلة: ج (3):\r__________________\r1 ـ الاولين: ت ج ق ك لب م ي، الاوليين: ف، كالمضافين: ت ج ق ل ك، كالمتضايعين: لب م ي، كالمتنافيين: ف.\r2 ـ يعرف صدقة: ت ج ك لب ل ي، يعلم صدقة: ف، يعرف بالعقل صدقة: م، يعرف صدقة بالعقل: ق.\r4 ـ مسئلة ب: ت، مسئلة: نسخ اخرى.\r5 ـ تيقن: ق ج م، يقين: ت، معين: ل، ـ: ك.\r6 ـ صحة: ف ك ي، ـ: ت ج ق لب م.\r7 ـ المجار: ا ت ج ف ق ك لب ي، المجاز والنقل: م.\r8 ـ التقديم والتاخير والنسخ: ي والنقل: ج: ا ت ج ف ق ك ل لب ي، التاخير والتقديم والنسخ: م.\r9 ـ لرجح: ا ت ج ق ك م ي، لترجح: ف لب، اذ: ا ت ج ق ك ي. عليه اذ: ف م ترجيح: نسخ ج، ترجح: ت ل، النقل: ت ج ف ق ك ل لب م، العقل: ي.\r10 ـ ظنك ت ج ف ق ك م ي، قولك: ي.\r11 ـ بافتتيجة: ت ج ف ق ك لب م، بالمنتج: ي ل.\r12 ـ مسئلة ج: ت، مسئلة: نسخ."], [143, "النقليات بأسرها مستندة الى صدق الرسول فكل ما يتوقف العلم بصدق الرسول على العلم به لا يمكن اثباته بالنقل، والا لزم الدور. واما الّذي لا يكون كذلك، فكل ما كان جزما بوقوع ما لا يجب عقلا وقوعه كان الطريق إليه النقل، وهو اما العام كالعاديات، أو الخاص كالكتاب والسنة والخارج عن القسمين يمكن اثباته فى الجملة بالعقل والنقل معا.\rمسئلة د (4):\rاذا استدللنا بشيء على شيء، فاما أن يكون أحدهما أخص من الثانى أو لا يكون.\rولأول على قسمين لأنه إما أن يستدل بالعام على الخاص، وهو القياس فى عرف المنطقيين، وإما بالعكس وهو الاستقراء.\rوأما الثانى فلا يمكن الاستدلال بأحدهما على الآخر، الا اذا اندرجا تحت وصف مشترك بينهما، فيستدل بثبوت الحكم فى احدى\r__________________\r1 ـ باسرها: ا ج ف ق ك ل لب ي، كلها: ت، بالرها: م، الرسول: ت ج ف م، عليه السلام: ق ك، صلى الله عليه وسلم: ي ل. فكل: ت ج ف ق ي، وكل: ا ك ل.\r2 ـ الرسول: ا عليه الصلاة والسلام: ل.\r3 ـ و: ا ج ت ف ق ك ي، ـ: م. جزما: ت ج ف ل ق ك، خيرا: ا م. يوقوع: بوقع: ل. مالا: ا ج ت ف ل ق ك. بما لا: م.\r4 ـ النقل: ا ج ت ف، ليس الا ذلك: ك ي ل: ق ك م ل ي. وهو: ا ت ج ل ف م، ـ: ق ك ي. كالعاديات: ت ج ف ق لب ل م ي، كالعادات: ك.\r5 ـ كالكتاب: ا ت ف ك م، كالايات: ي.\r5، 6 ـ في الجملة ـ: ا فقط.\r6 ـ بالعقل والنقل معا: ت ق ك م ي، بالنقل والعقل: ف، بالعقل والنقل: ج.\r7 ـ مسئلة د: ت، مسئلة: نسخ اخرى، ـ: ل.\r11 ـ اما: ا ت ف ج ق ل ك لب ي، او: م."], [144, "الصورتين على ان المناط، هو المشترك، ثم يستدل بذلك على ثبوته فى الصورة الأخرى، وهو القياس فى عرف الفقهاء (*) وهو بالحقيقة مركب من القسمين الأولين ثم القياس بالمعنى الأول على خمسة أقسام:\rأحدها: أن يحكم بلزوم شيء لشيء فيلزم من وجود الملزوم وجود اللازم، ومن عدم اللازم عدم الملزوم تحقيقا للزوم. ولا يلزم من عدم الملزوم عدم اللازم ولا من وجود اللازم وجود الملزوم تصحيحا للعموم.\rوثانيها: التقسيم المنحصر الى قسمين فانه يلزم من رفع أيهما. كان ثبوت الآخر، ومن اثبات أيهما كان ارتفاع الاخر.\rوثالثها: اذا حكمنا بثبوت الألف (ا) لكل ما ثبت له الباء (ب)\r__________________\r1 ـ تم ـ: ف فقط.\r(*) الاقسام اربعة ونقول: اما ان يستدل بنبوت الحكم في كل افراد العام على نبوته في كل افراد الخاص او بالعكس او ليستدل بثبوت الحكم في كل افراد احد متساويين على ثبوته في كل افرد الاخر ويستدل بثبوت الحكم في بعض الافراد على نبوته في البعض الاخر. والابول القياس والثاني الاستقراء والثالث قياس المساواة والرابع التمثيل. الكاتب القزويني. المفصل شرح المحصل 26 ـ 1.\r2 ـ بالحقيقة: ا ت ج ق ل لب، على الحقيقة: ك ي، في الحقيقة: ف م.\r3 ـ قسمين: ف فقط.\r5 ـ الحكم: ا ت ك، بحكم: ف لب ي، نحكم: ق م.\r9 ـ الى: ت ك ج ل لب م، على: ق، بين: ف. رفع: ا ت ف ج ق ك لب ي، دفع: م.\r10 ـ ابيات: ت ج ف ق ل ك لب ي، نبوت: م، ارتفاع: ت ج ل ف ق ي، رفع: ا ك لب.\r11 ـ الباء: ت ف ج ق ك م ي، ب: ا."], [145, "أو بانتفاء الألف (ا) عن كل ما ثبت له الباء (ب) ثم رأينا الباء (ب) ثابتا لكل الجيم (ج) أو لبعضه، حكمنا بثبوت الألف (ا) أو بانتفائه لكل الجيم (ج) أو لبعضه.\rورابعها: اذا حكمنا بأن الألف (ا) ثابت للباء (ب)، مسلوب عن الجيم (ج) فان كان وقت السلب والايجاب واحدا، كفى ذلك فى مباينة الطرفين. فأما اذا لم يتعين الوقت، لم ينتج الا عند اعتبار الدوام فى أحد الطرفين لأن دوام أحد النقيضين يوجب كذب الآخر، كيف كان.\rوخامسها: اذا حصل وصفان فى محل واحد، فقد التقيا فيه اما فى الخارج عنه فربما يحصل ذلك الالتقاء، وربما لا يحصل. فلا جرم،\r__________________\r1 ـ الالف: ت ف ج ق ك ي، ا: ا، الباء (2): ت ف ج ق ك م ي، ب: ا.\r2 ـ الجيم: ت ف ق ج م ي ل، ج: ا. لبعضه: ا ت ق ك لب ج ل م ي، بعضه: ف، الالف: ت ف ج ق ك ل م ي،: ا.\r2، 3 ـ او بانتفاله انتفائه: ق لكل الجيم ج: ا او لبعضه: ا ت ج ل ف ق ك لب، ـ: م.\r4 ـ بان الالف ثابت: ف ق ك لب ل ي، بلن ا ثابت: ا، ان الالف ثابت: ت ج، بالالف ثابتا: م.\r4، 5 ـ مسلوب عن الجيم، ج: ا: ا ت ج ف ل ق ك لب، مسلوت عن الجيم: ي، ومسلوبا عن الجيم: م.\r5 ـ فان: ت ج م، وان: ك.\r6 ـ فاما اذا لم يتعين بعين: ف ق ك م: ت ج ف ق ك لب، فان لم بتعين: ي، فان لم يعين: ل، ينتج: ت ج ق ك لب م ي، يصح: ف، اعتبار: نسخ، اعتقاد: ت.\r7 ـ احد (1): ا ت ج ل ف ق ك لب ي، احدى: م، لان: ت ف ق ك لب م، اذ: ي، احد (2): ت ج ل ك، احدى: م. النفيضين: ت ج ف ل ق ك لب ي، الفضبتين: م، كذب: ا ت ج ف ك ق ل لب ي، ـ: م.\r10 ـ عنه: م ل ف، منه: ق، ـ: ت ج ك، فرنما: ت ف ق ج"], [146, "كان اللازم منه هو الحكم الجزئى وتفاصيل هذه المناهج مذكورة فى كتبنا المنطقية. وبالله التوفيق.\r__________________\rك لب م ي، ربما: ا.\r1 ـ هو: ت ف ج ق ل ك لب م ي. ـ: ا، تفاصيل: ا ت ف ج ق ل ك لب م، تفصيل: ي، المناهج مذكورة: ا ت ج ف ل ق ك لب ي، المناهج مذكور: م.\r2 ـ وبالله التوفيق: ت ق:، والله اعلم: ج ـ: نسخ ل م."], [147, "الركن الثانى\rفى تقسيم المعلومات\rالمعلوم إما ان يكون موجودا أو معدوما فهنا ثلاث مسائل:\rالمسألة الأولى فى أحكام الموجودات:\r("]], "pg": [79, 147]}, "687.4": {"x": [[147, "ا) تصور الوجود والعدم بديهى، لأن ذلك التصديق موقوف على هذين التصورين وما يتوقف عليه البديهى أولى أن يكون كذلك ولأن علمى بالوجود جزء من علمى بأنى موجود واذا كان العلم المركب بديهيا كان العلم بمفرداته كذلك.\r(ب) ذهب جمهور الفلاسفة والمعتزلة وجمع منا الى أن الوجود وصف مشترك فيه بين الموجودات. والأقرب أنه ليس كذلك.\rلنا أنه لو كان كذلك، لكان مغايرا للماهية، فيكون الوجود قائما\r__________________\r2 ـ او معدوما: ت ج ف ق ل م، واما ان يكون معدوما: ك هامش: اولا موجودا، فهنا: ت ج ف لب م ي، وههنا: ا، فههنا: ق ل ك.\r4 ـ المسئلة: نسخ، ـ: ت، الموجود فا: ت، الموجود ا: ف ل لب ي، الوجود ا: ق، الموجودات: ا ج ك م.\r5 ـ موقوف: ا ج ت، متوقف: ف ق ك ل لب ي، يتوقف: م.\r7 ـ علمى (1، 2): ف ق ك ل لب ي، العلم: ت م. باني: ا ت ج ف ق ك لب ي، بانه: م.\r9 ـ ب: ا ت ف ق ل ك لب ي، الثانية: م، الثاني: ج. المعتزلة: نسخ، المعتزلة خدللهم الله: ت، الى: نسخ، على: ت.\r10 ـ بين: نسخ، بين سائر: ت."], [148, "بما ليس بموجود. وتجويزه يفضى الى الشك فى وجود الأجسام.\rاحتجوا بأن المقابل للنفى واحد، والا لبطل الحصر العقلى، فيجب أن يكون الاثبات الّذي هو المقابل للنفى واحدا، ولأنه يمكن تقسيم الموجود الى الواجب والممكن. ومورد التقسيم مشترك بين القسمين.\rولأنا اذا علمنا وجود الشيء فلا يتغير ذلك الاعتقاد بتغير اعتقاد كونه جوهرا أو عرضا وذلك يقتضي أن يكون الوجود أمرا مشتركا بينهما.\rوالجواب عن الأول: ان مقابل ارتفاع كل ماهية تحقق تلك الماهية ولا واسطة بين هذين القسمين. وهذا لا يدل على ثبوت أمر عام.\rوعن الثانى أن مورد التقسيم بالوجوب والامكان هو الماهية. والمعنى به أن بقاء تلك الماهية إما أن يكون واجبا، أو لا يكون.\r__________________\r1 ـ الاجسام: نسخ، الاجسام وهو عين السفسطة: لب.\r2 ـ المقابل للتقي: ا ت ف ج ق ك لب ل ي، مقابل النقي: م، لبطل: ا ت ج لب م، بطل: ف ق ك ي.\r3 ـ فيجب: ت ق م، فوجب: ك. المقابل للتقى: ا ت ج ف ق ل ك لب ي، مقابل النفي: م.\r6 ـ اذا: ت ق ك لب م ي، اذ: ف، الشيء: ا ت ج ك، شيء: ف ق م ي، بتغير .. بتغير: ت ج ف ك لب م، بتعين: بتعين: ي، الاعتقاد ـ: ف فقط.\r7 ـ ان يكون: ا ق ي، ام مشترك: ف ك لب ل م، مشتركا: ت.\r8 ـ بينهما: ت ج ف م، فيه: ق، ـ: ل.\r9 ـ مقابل ارتفاع: ا ت ج ف ق ك لب، تقابل ارتفاع: ي، ارتفاع مقابل: م. تحقق: ا ت ج ق، محقق: ك ل، يحقق: ف لب م ي.\r10 ـ لا بدل: ا ت ج ف ق ك لب ل ي، بدل: م.\r13 ـ به: ا ت ج ل ك لب ي، ـ: ف ق م. بقاء: ت ق ج ل"], [149, "وعن الثالث: أنه يقتضي أن يكون للوجود وجود آخر، ويلزم التسلسل.\rالمسألة الثانية:\r"]], "pg": [147, 149]}, "687.5": {"x": [[149, "المعدوم اما أن يكون ممتنع الثبوت أو ممكن الثبوت المعدوم اما أن يكون ممتنع الثبوت، ولا نزاع فى انه نفى محض، واما أن يكون ممكن الثبوت وهو عندنا، وعند أبى الهذيل، وابى الحسين البصرى من المعتزلة، نفى محض، خلافا للباقين من المعتزلة ومحل الخلاف أنهم زعموا أن وجود السواد زائد على كونه سوادا. ثم زعموا أنه يجوز خلو تلك الماهية عن صفة الوجود.\rلنا أن وجود السواد عين كونه سوادا على ما مر، فيمتنع أن يكون السواد سوادا عند عدم الوجود ولأن الذوات المعدومة مشتركة فى الثبوت المقابل للانتفاء المحض ومتباينة بخصوصياتها النوعية وما به الاشتراك غير ما به الامتياز فثبوت تلك الذوات زائد على ماهياتها المخصوصة، فهى حال ما فرضناها خالية عن صفة الثبوت،\r__________________\rلب م، يقال: ف ك ي. واجبا: ت ج م، واجبة: ق ي ل.\r1 ـ ويلزم: ت ج ق ك لب م ي، فيلزم: ا، ولزم: ف.\r4 ـ المعدوم: ا ت ج ف ق ك لب ل ي، في المعدوم المعدوم: م.\r5 ـ وهو: نسخ، وهذا: ك، ابي هذبل: تاخر في: ل بعد البصرى.\r6 ـ نفى: نسخ، انه نفي: ف. للباقين من المعتزلة: ت ج ف ق ك ل لب م، للمتعزلة: ي.\r7 ـ زائد: ت ج ف ق ك ل لب م، زائدا: ي.\r8 ـ عن: ا ت ج ف ق ك لب ل ي، من: م.\r10 ـ السواد: ا، ـ: نسخ ج ل. عند: ا ت ف ج ق ل ك لب ي، من: م، الدوات: ا ت ج ف ق لب ل ي، الذات: ك، السوادية: م.\r11 ـ بخصوصياتها: ا ف ق ك ل لب، لخصوصياتها: ي، بخصوصيتها: م، بماهياتها: ت ج.\r13 ـ خالية: ت ج ق م، عاربة: ف ك لب ي، عارية خالية: ا."], [150, "موصوفة بها، هذا خلف.\rولأن عدد الذوات المعدومة قابل للزيادة والنقصان فيكون متناهيا، والخصم لا يقول به.\rولأن الذات أزلية فلا تكون مقدورة والوجود حال عندهم، فلا يكون مقدورا عندهم واذا لم يقع الذات ولا الوجود بالفاعل كانت الذات الموجودة غنية عن الفاعل.\rولأن السواد المعدوم اما أن يكون واحدا أو كثيرا فان كان واحدا فالوحدة إن كانت لازمة للماهية امتنع زوالها، فوجب أن لا يتعدد فى الوجود، وان لم تكن لازمة، فليفرض ارتفاعها، لأن كل ما كان ممكنا لا يلزم من فرض ارتفاعه محال، واذا زالت الوحدة حصل التعدد، والتعدد لا يتحقق الا اذا تباين الشيئان بالهوية.\rثم ما به التباين ان كان من لوازم الماهية وكل شيئين مختلفان بالماهية، هذا خلف وان لم يكن من لوازمها كان الشيء حال عدمه\r__________________\rعرية: ل.\r1 ـ موصوفة: ت ج ق ل م، موصوف: ك.\r2 ـ المعدومة: ا ت ج ف ل ق ك لب ي، المعدودة: م.\r4 ـ الذات: ا ت ك، الذوات: ف م ج ي ا. عندهم ـ: ي ومنسطوب عليه في: ا.\r5 ـ مقدورا: ا ق ك لب م، مقدور: ي، مقدورة: ف، عندهم ـ: ت فقط.\r6 ـ الذات: ا ج ل ك ق لب م، الذوات: ف ق ي.\r9 ـ فليفرض: ت ج ف ك ل لب ي، فتفرض: ا، فلتنفرض: ق، فمفرض: م.\r10 ـ واذا: ت ج ف ق ي ل، فاذا: ك لب م.\r11 ـ التعدد: ا ت ج ف ق ك لب ل ي، هو: م.\r12 ـ وكل: ا ت ج ق، فكل: ج ف ك لب ل م. مختلفان: ت ج ف ل ي، فهما مختلفان: ق ك لب م."], [151, "موردا للصفات المتزايلة، ولو جاز ذلك لجاز أن يكون محل هذه الحركات والسكنات المتعاقبة معدوما محضا. وذلك عين السفسطة.\rاحتجوا بأمرين:\rأحدهما: أن المعدوم متميز وكل متميز ثابت فالمعدوم ثابت، اما أن المعدوم متميز فبيانه من ثلاثة أوجه:\rأحدها: أن المعدوم معلوم، وكل معلوم متميز. اما أن المعدوم معلوم، فلأن طلوع الشمس غدا معلوم الآن وهو معدوم، والحركة التى يمكننى أن أفعلها كالحركة الى اليمين والشمال، والتى لا يمكننى أن أفعلها كالطيران الى السماء معلومة، مع أنها معدومة. واما أن المعلوم متميز فلانى أميز بين الحركة التى أقدر عليها،\r__________________\r1 ـ جار: ت ج فقط. محل: ت ج ق م، محال: ك، هذه ا ج ت ف ق، ـ: ك لب ل م ي.\r2 ـ معدوما: ا ف ق ج ك لب ل ي. عدما: م. ذلك: ت ق م، هذا: ك.\r4 ـ احتجوا: ت ف ق لب ج م، واحتجوا: ا ي.\r5 ـ احدهما: ف ق، الاول: ل لب ي، ا: ا، الحجة الاولى: ف ك م، الاولى ج، ان: ت ج ق ك لب ي، ـ: ا ف م.\r5، 6 ـ اما ان المعدوم من: ا، اما ان المعدوم متميز فمن: ي، اما ان المعدوم متميز فبيانه في: لب فلثلاثة اوجه: ل لب فالمعدوم ثابت: ق بيان الاول من: ت ج ف ك م.\r7 ـ احدها: ف ك ج لب م، اولها: ت ق ي، ا: ا\r8 ـ معلوم (1): نسخ، فمعلوم: ت، فلان: ت ج ق لب ل م ي، لان: ف، فان: ك، الان معلوم: ك فقط.\r9 ـ الشمال: نسخ، اليسار: ت ج.\r10 ـ ان افعلها: ـ ا فقط. الى: ت ف ق ك م، في: ا ي. معلومه مع: ت ج ق م، معلوم مع: ف ل، معلوم: ك ي.\r11 ـ ان ـ: ت فقط. فلاني: ت ف ق ك لب م، فانى: ي."], [152, "والتى لا أقدر عليها وأميز بين طلوع الشمس من مشرقها ومن مغربها. وكذلك أحكم على احدى الحركتين بأنها توجد غدا، وعلى الأخرى بأنها لا توجد، ولا معنى للتميز الا ذلك.\rوثانيها: أعلم انى قادر على الحركة يمنة ويسرة، وغير قادر على خلق السماء والأرض وهذا الامتياز حاصل قبل دخول هذه الأشياء فى الوجود. فلولا تميز بعض هذه المعدومات عن البعض، والا لاستحال أن يقال انه يصح منى فعل هذا ولا يصح منى فعل ذلك.\rوثالثها: أن الواحد منا قد يريد شيئا ويكره شيئا آخر. وان كان المراد والمكروه بعد معدومين. ولو لا امتياز المراد عن المكروه قبل الوجود، والا لاستحال أن يكون أحدهما مرادا والآخر مكروها، فثبت بهذه الوجوه الثلاثة ان المعدومات متمايزة واما أن كل متميز ثابت فلأنا لا نعنى بالثابت الا كون هذه الماهيات فى أنفسها متحققة متعينة.\r__________________\r1 ـ واميز بين ... لا اقدر عليها: تكرر في: ي.\r1، 2 ـ مشرقها ومن مغربها: ت ل ق، مشرقها ومغربها: ا ي، مشرقها او مغربها: ك، مشرقها وبين طلوعها من مغربها: لب، مغربها ومن مشرقها: م، مشرقها وبين عدم طلوعها من مغربها: ج.\r2 ـ وكذلك: نسخ، ولذلك: ت ك.\r4 ـ وثانيها: ت ج ق ك لب ل ي، ت: ا، ثانيها: ف م، اعلم: ت ج فقط، قادر (1): ت ج ف ق ك ل لب م، اقدر: ي.\r6 ـ البعض: ت م ي، بعض: ف ج ق ل ك لب.\r8 ـ وثالثها: ت ف ج ق ل ك لب م ي، ج: ا، قد ـ: ا فقط.\r9 ـ فلولا: ف فقط.\r10 ـ لاستحال: نسخ، لاستحلال: ل.\r11 ـ الثلاثة: ـ: لب ل ي فقط. المعدوم: ف فقط. متمايزة: ت ج، متميزة: ك ق ل ي، متميز: ف، الممكنة متميزة: م.\r12 ـ فلانا: ت ف ق لب م ي، لانا: ا، فانا: ك.\r13 ـ متعينة ومتحققة: ف ق ل ك م ي، متحققة متعينة: ا ت"], [153, "ومن المعلوم بالضرورة أن امتياز هذه الماهية عن تلك، لا يحصل إلا بعد تحقق هذه الماهية وتحقق تلك الأخرى فعلمنا أن هذه الماهيات متحققة حال العدم.\rوثانيها: أن المعدوم الممكن متميز عن الممتنع، ولا يجوز أن يكون الامتناع وصفا ثبوتيا، وإلا لكان الموصوف به ثابتا، فيكون الممتنع الثبوت واجبا، هذا خلف وإذا لم يكن الامتناع وصفا ثبوتيا، كان الامكان ثبوتيا ضرورة لأنه لا بدّ فى المتناقضين من كون أحدهما ثبوتيا، والموصوف بالوصف الثبوتى ثابت. فالمعدوم الممكن ثابت.\rوالجواب عن الأول انا لا نسلم أن كل معدوم ثابت، والّذي احتجوا به، فهو معارض بأمور أربعة:\r__________________\rج، معينة ومتحققة: لب.\r1 ـ الماهية: م ق ت ل ج، الماهيات في النفسها: ك، تلك: ا ت ف ج لب ي، تلك الماهية: ك ق م.\r2 ـ تحقق ـ: ت ج فقط، الاخرى: ت ج ف ك لب ق م ي، الماهية: ا، ـ: ل، الماهيات: ت ف ج ك ق ل لب، الماهيات: ي.\r4 ـ وثانيها: ت ج، الحجة الثانية ان: ف ك لب م ي، ب: ا، عن: ف ت ك ج ل لب ق م، من: ي.\r5 ـ له: ت ف ج ك ل لب م ي، ـ: الممتنع: ت ك ق م ل ي، ممتنع: ا ف ج.\r6 ـ واجبا: ج ت، النبوت: ف ل، اذا: ت ج م، لما: ف ك ل ق لب ي، وصفا: لب ق ي ل، ـ: ت ف ك ج م.\r7 ـ الانه: م، انه: ت ف ج ك ل لب ق ي، في: ف ت ج ك لب م ي ل، من: ا، المتناقضين: ي ف م ج، المتنافيين: لب ي ق ل، المتنافين: ك، من: ف ج ت ك ل لب ق م، عن: ي.\r8 ـ ثبوتيا: ا ت ف ق ك ل لب ج ي، ثبوتيا والاخر سلبيا: م، الممكن: ف ت ك ق لب م ي، للممكن: ا.\r9 ـ انا: ك ل ق ي لب، ـ: ت ف ج م، لا نسلم ان: ت ف ك م ق ي، لا نسلم: لب ل، معدوم: ت ج ق م، معلوم: ك ي ل.\r10 ـ به عليه: ف ق ي: ات ج ف ق ك لب، عليه: م، فهو: لب ل م ي، ـ: ت ف ج ق ك."], [154, "أولها: أنا نحكم على شريك الله تعالى بالامتناع. فلو لا أن نتصوره ونميزه عما عداه وإلا لاستحال الحكم عليه بالامتناع، لأن ما لا يتصور لا يمكن الحكم عليه.\rوثانيها: أنا نتصور بحرا من زئبق وجبلا من ياقوت، ونحكم بامتياز بعض هذه المتخيلات عن بعض، مع أنها غير ثابتة فى العدم لأن الجبل من الياقوت عبارة عن أجسام قامت بها أعراض وعندكم ماهيات الجواهر والأعراض، وإن كانت ثابتة فى العدم، لكن الجواهر غير موصوفة بالأعراض حال العدم، فلا يمكن تقرير ماهية الجبل، من حيث إنه جبل حال العدم.\r__________________\r1 ـ اولها: نسخ، ا: ا، تحكم على: ت ج ق، نتصور: ف ل ك لب ي. الله: ت ج ف ق م، الباري: لب ل ي، لله سبحانه و: ك، ولحكم عليه بالامتناع: ي ل، بالامتناع: ت ج ف ق م، ـ: ك لب. فلولا: ا ت ق، ولولا: ق ك ل لب م ي، فلولا انا: ج ف، ان: ت، انا: نسخ ج ف.\r2 ـ نتصوره متميزا: م، نتصوره فنميزه: ا، تصور تميزه: ي، بتصوره ونميزه: ق ك لب ف، يتصور ونميزه: ت، نصوره ونميزه: ل، والا: ا ف ك لب ي ق، ـ: م، لان: ف ج ك ق م ل، بان: ي، ان: ت.\r4 ـ وثانيهما: ت ف ج ك ل ق لب م ي، ب: ا، نتصور: ك لب ق م ل ي، نتخيل: ت ف ج.\r5 ـ المتخيلات .. انها: ت ج ف ل ك، المخيلات .. انها: ل ق م ج، المستحيلات .. البعض ... انه: ي، ثابتة: ت ف ق م، ثابت: ا ي.\r6 ـ الجبل ... الياقوت ت ف ج ك ق م، جبلا ... ياقوت: ي، بها: ت م، به: ق، اعراض: ت م ق، الاعراض: ك.\r8 ـ فلا: ت ف ك لب ق م، ولا: ي، تقرير: ت م ق، تقرر: ف ج ك لب ي، تقدير: ل، ماهية: ف ج ل ق ك لب ت م ي، ماهيات: ا، انجل: ت ف ق م، جبل: ك ي ل، جبل: ت ج ك ق لب م ي، نصل: ف."], [155, "وثالثها: أنا نتصور وجودات هذه الماهيات قبل دخولها فى الوجود ونحكم بامتياز بعض تلك الوجودات عن بعض فأتى كما أعقل امتياز ماهية الحركة يمنة عن ماهية الحركة يسرة قبل دخولهما فى الوجود. كذلك اعقل امتياز وجود احدى الحركتين عن وجود الأخرى، قبل دخولهما فى الوجود.\rفلو اقتضى العلم بامتياز الماهيات تحققها فى العدم، لاقتضى العلم بامتياز هذه الوجودات تحققها فى العدم. وذلك باطل بالاتفاق. ولأن الوجود مناقض للعدم، والجمع بينهما محال.\rورابعها: انا نعقل ماهية التركيب والتأليف قبل دخولهما فى الوجود وهذه الماهية يمتنع تقررها فى العدم، لأن التأليف عبارة عن اجتماع الأجزاء، وتماسها على وجه مخصوص. وذلك لا يتقرر حال العدم بالاتفاق.\rوإذا كان كذلك، استحال أن يتقرر ماهية التأليف والتركيب\r__________________\r1 ـ وثالثها: ت ف ج ك لب م ي، ج: ا، الماهيات: ت ك لب م ق ج ل ي، الماهية: ف.\r2 ـ ونحكم: ت ف ق ك لب م، فنحكم: ا، عن: ا ت ف ك ج ق، من: م، بعض: نسخ، البعض: ت، فانى كما اعقل: نسخ، فانا كما نحكم نعقل: ت.\r3 ـ دخر ايما: ت ف ق لب م ي، دخولها: ا.\r4 ـ كذلك: ف ت ك م ق، وكذا: ي، اعقل: نسخ، نعقل: ت ج امتياز وجود: ت م ق ل ج: وجود امتياز: ك.\r5 ـ دخولهما: ت ف ك ق م ي، دخولها: ا.\r9 ـ ورابعها: ت ف ق ك م ي، د: ا، دخولهما: ت ك ج، دخولها: م ق.\r10 ـ تقررها: ت ف ج ك لب ي ق، تقريرها: م.\r11 ـ لا يتقرر: ا ت ف ق ك لب ي، يمتنع تقريره: م.\r13 ـ استحال: ت ف ق ك م ي، استحال تاليف الاجزاء وتماسها استحال: لب، والتركيب: ا، ـ: ت ف ج ك لب م ي ق ل."], [156, "حال العدم. ثم إنا نتصورها قبل وجودها ونميز بينها وبين سائر الماهيات المعلومات وكذلك نعقل المتحركية، والساكنية قبل حصولهما مع أنهما من قبيل الأحوال ولا حصول لهما فى العدم.\rفثبت بهذه الوجوه أن التميز الذهنى لا يستدعى تحقق الماهيات خارج الذهن، ثم إنك ان أردت تضييق الكلام على الخصم فقل: ما الّذي تعنى بقولك المعدوم معلوم؟ ان عنيت به ذلك القدر من الامتياز الّذي تجده فى تصور الممتنعات، والمركبات، والاضافيات فذلك مسلم لكنه لا يقتضي تقرر الماهيات فى العدم بالاتفاق.\rوان عنيت به أمرا آخر وراء ذلك فلا بد من افادة تصوره، ثم من اقامة الحجة عليه. فانا من وراء المنع فى المقامين.\rوأما قوله المعدوم مقدور والمقدور متميز فضعيف، لأن المقدور إما أن يكون ثابتا فى العدم، وإما أن لا يكون فإن كان ثابتا، لم\r__________________\r1 ـ وجودها .. بينها: ت م ف ج ك ي، وجودهما .. بينهما: لب، وجودها وبيرها بينها: ق.\r2 ـ المعلومات: ا، ـ: ت ف ك ل م ي ق ج، كذلك: لذلك: ت.\r3 ـ لهما: ت م ق ي ك، لها: ف.\r4 ـ التميز: ف ق ك ج م ل ي، التمييز: ت لب.\r5 ـ الماهيات: م ق ف ت، الماهية: ك ي.\r6 ـ بقولك ... معلوم: ت ج ف، يكون ... معلوما: م ق ل ك لب، القدر: ا ت ج ف ق ك لب ي، الضرب: م.\r7 ـ تجده: م، نجده: ا ت ف ق ك لب ي.\r8 ـ لكنه: ج لب م ت ك، لكنها: ف، لكن: ي ق، القرر الماهيات: ت ك ج ف ق م، تقرير الماهية: ي.\r9 ـ عنيتم: ك فقط. اخر: ت ج، ـ: ف ك لب ق م ي من: ا، ـ: ف ق ك م ي ت.\r10 ـ الحجة: ك ت لب م ق ي، البرهان والحجة: ف، فاننا فانا: ت ج ل.\r11 ـ فضعيف: ت ج ك لب ق م ي، ضعيف: ف.\r12 ـ واما لن: ا، او: ت ج ف ل ق لب م."], [157, "يكن للقدرة فيه أثر، لأن اثبات الثابت محال وإذا كان كذلك استحال أن يكون مقدورا. وإن لم يكن ثابتا كان ذلك اعترافا بأن المقدور غير ثابت وحينئذ لا يمكنهم الاستدلال بكونه مقدورا على كونه ثابتا.\rوهذا هو الجواب عن قولهم المعدوم مراد وكل مراد ثابت.\rوالجواب عن الحجة الثانية أن المحكوم عليه بكونه ممكنا، اما أن يكون ثابتا فى العدم أو لا يكون.\rوالأول باطل، لأن عندكم الذوات المعدومة، يمتنع عليها التغير. والخروج عن الذاتية. فلا يمكن جعل الإمكان صفة لها، وان كان الثانى كان الامكان وصفا لما ليس بثابت فى العدم. وحينئذ لا يمكنكم الاستدلال بالإمكان على كون الممكن ثابتا فى العدم وبالله التوفيق.\rتفصيل قول الفلاسفة والمعتزلة فى المعدومات.\rزعم أبو يعقوب الشحام، وأبو على الجبائى، وابنه أبو هاشم. وأبو الحسين الخياط وأبو القاسم يعقوب البلخى وأبو عبد الله البصرى، وأبو إسحاق ابن عياش، والقاضى عبد الجبار بن أحمد\r__________________\r1 ـ اثر: ا ت ف ج ق لب، تاثير البتة: م، ـ: ل.\r2 ـ يمكنكم: ت ج فقط.\r5 ـ هذا: ت ج م ا ف، هو: لب، ـ: ف ق ل.\r6 ـ الثانية: ا ت ق لب، الثالثة: م.\r8 ـ عندكم: ت م ق ل ا، عندهم: ف، يمتنع: نسخ، فيستحيل: ت.\r10 ـ يمكنكم: م، يمكن: ا ت ج ق لب ل.\r11 ـ وبالله التوفيق: ا ت ق م، ـ: ل ف لب ج.\r14 ـ ابو ان: ت يعقوب: ت ف ق لب م، ابو اسحق يعقوب:، وابو القاسم يعقوب البلخى: ا، ابو القاسم البخي: ت ف ج ق لب، ـ: م.\r15 ـ ابن احمد: ت م ق ا ف، ـ: لب."], [158, "الهمدانى وتلامذته، أن المعدومات الممكنة قبل دخولها فى الوجود ذوات، وأعيان وحقائق. وان تأثير الفاعل ليس فى جعلها ذوات بل فى جعل تلك الذوات موجودة. واتفقوا على أن تلك الذوات متباينة بأشخاصها. واتفقوا على أن الثابت من كل نوع من تلك المعدومات عدد غير متناه.\rأما الفلاسفة، فقد اتفقوا على أن الممكنات ماهياتها غير وجوداتها. واتفقوا على أنه يجوز تعرى تلك الماهيات عن الوجود الخارجى فإنا قد نعقل المثلث وإن لم يكن له وجود فى الخارج وهل يجوز تعريها عن الوجودين معا الخارجى والذهنى.\rنص ابن سينا فى المقالة الأولى من إلهيات الشفاء على أنه لا يجوز ومنهم من يجوزه واتفقوا على أن تلك الماهيات لا توصف بأنها واحدة، أو كثيرة، لأن المفهوم من الوحدة والكثرة مغاير للمفهوم من السواد. فإذا اعتبرنا السواد فقط، ففى هذه الحالة لا يمكن الحكم عليه بالوحدة والكثرة، وإلا فقد اعتبرنا مع السواد غيره وذلك يناقض قولنا إنا لم نعتبر إلا السواد، بل الماهية لا تنفك عن الوحدة والكثرة.\r__________________\r1 ـ الهمداني: ق، ـ: ت م لب.\r2 ـ ان: نسخ، انا: ت.\r6 ـ اما: ت م ف، واما: ق لب.\r10 ـ ابن سينا: ت م لب ا ف، بو علي بن سينا: ق، لا: ت ق لب ف ا ج ل، ـ: م.\r12 ـ بجوزه: ت ج ل ق لب ا ف، لم يجوز: م.\r13 ـ الوحدة والكثرة: ف ج ا، الكثرة والوحدة: ق لب، الواحدة والكثرة: ت.\r14 ـ عليه: ق ج لب ا ت ل، عليها: م، و (1): ا ت ف ق م، او: لب.\r15 ـ بل: ا ف ق، بلى: ت ج لب ل، فقط بل: م."], [159, "واتفقوا على أن الماهيات غير مجعولة قالوا: لأن كل ما بالغير يجب ارتفاعه عند ارتفاع ذلك الغير. فلو كان كون السواد سوادا بالغير، لزم عند ارتفاع ذلك الغير أن لا يبقى السواد سوادا لكن القول بأن السواد لا يبقى سوادا محال، لأن المحكوم عليه هو السواد، والمحكوم به أنه ليس بسواد، والمحكوم عليه لا بد من تقرره عند حصول المحكوم به، فيلزم أن يكون سوادا، لا محالة، حال ما لا يكون سوادا، وهو محال.\rوأما المعتزلة فقد اتفق القائلون منهم بالذوات المعدومة على أنها بأسرها متساوية فى كونها ذوات وأن الاختلاف بينها ليس إلا بالصفات ثم اختلفوا:\rفذهب الجمهور منهم إلى أنها موصوفة بصفات الأجناس. ومرادهم منها ان ذات الجوهر موصوفة بصفة الجوهرية وذات السواد موصوفة بصفة السوادية وهلم جرا وزعم ابن عياش ان تلك الذوات عارية عن جميع الصفات والصفات لا تحصل إلا زمان الوجود. ثم القائلون بالصفات زعموا ان صفات الجواهر، إما أن تكون عائدة إلى الجملة وهى الحيية. وكل ما يكون مشروطا بها\r__________________\r1 ـ لان: ا ت ج ق ل لب، ان: ف م، كل ما: ا ت ل ق ج لب، كل ما يجب: ف م ج هامش.\r6 ـ لا محالة: ت ف، ـ: ق لب.\r8 ـ واما: ق لب ا، اما: ت م ف.\r9 ـ في كونها ذوات: نسخ، في الذاتية: ت ج، بينها: م، بينهما: ت.\r12 ـ منها ـ: ت فقط. ذات الجوهر: ا ت ج ف ق لب، ذوات الجواهر: م.\r15 ـ ان (1) ت م، بان: ف، الجواهر: ت م ج لب ق، الجوهر: ا.\r16 ـ الحيبة: ا ت ج ف ل لب، الحياة: م، ـ الحبوبة: ق، يكون: ك ف لب ا ج ق، كان: م."], [160, "أو إلى الأفراد، وهى اما فى الجواهر أو فى الأعراض. أما الجواهر فقد أثبتوا لها صفات أربعة.\rأحدها: الصفة الحاصلة لها حالتى العدم والوجود وهى الجوهرية.\rوالثانية: الوجود وهو الصفة الحاصلة بالفاعل.\rوالثالثة: التحيز وهى الصفة التابعة للحدوث الصادرة عن صفة الجوهرية بشرط الوجود.\rوالرابعة: الحصول فى الحيز وهو الصفة المعللة بالمعنى. قالوا وليس للجوهر الفرد صفة زائدة على هذه الأربعة، فليس له بكونه أسود وأبيض صفة. وكذا القول فى كل عرض غير مشروط بالحياة.\rوأما الأعراض فالصفات العائدة إلى الجملة غير معقولة فيها.\r__________________\r1 ـ الجواهر: ت ف لب م، الجوهر: ا ق.\r2 ـ اثبتوا: نسخ، ثبتوا: ت، لها: ت م لب، له: ق ا ف.\r3 ـ احدها: م ف ق ت ل، احديها: لب ج ا: ا، لها: ا ت لب، له: ج ق ف، ـ: م، العدم والوجود: ف ل ق لب م، الوجود والعدم: ا ت ج، هي: نسخ، هو: ت.\r5 ـ والثانية: ت ف ق ك لب م، الثانية: ي، ب: ا، و (2) ـ: ك.\r6 ـ والثالثة: ت ف لب م، الثانية: ق ي، ج: ا، وهي: ا ك ج، وهو: ق لب ل م ي، ـ: ت. الصفة: ا ف ج ق لب م ي، ـ: ت ك، التابعة: نسخ، التابع: ت، الصادرة: ا ف ق لب ك ي، الصادر: ت ج، والصادرة: م.\r8 ـ والرابعة: ت ف ك م، الرابعة: ق لب ج ي، د: ا، وهو: ت ج ف ق لب ك ي، وهي: ا، بالمعنى: نسخ، فالمعنى: ت.\r9 ـ الاربعة: ل ت ج، الاربع: ق.\r10 ـ اسود وبيض: م ل، ابيض واسود: ق، سوادا وبياضة: ك، اسودا وابيضا: ت، كذا: نسخ، كذلك: ي.\r11 ـ فالصفات: ت ف ق لب م، بالصفات: ي، والصفات:"], [161, "وأما العائدة إلى الآحاد فثلاثة: الصفة الحاصلة لها حالتى العدم والوجود والصفة الصادرة عنها عند الوجود. وصفة الوجود. فهذا هو المذهب الّذي استقر جمهورهم عليه وهو قول أبى على وأبى هاشم والقاضى عبد الجبار وأبى رشيد وابن متويه. ومنهم من خالف هذا التفصيل فى مواضع.\rأحدها: إن أبا يعقوب الشحام وأبا عبد الله البصرى وأبا إسحاق ابن عياش زعموا أن الجوهرية هى التحيز. ثم اختلفوا بعد ذلك، فزعم الشحام، وأبو عبد الله أن ذات الجوهر كما أنها موصوفة بالجوهرية، فهى موصوفة بالتحيز. ثم اختلفا.\rفذهب الشحام إلى أن الجوهر حال عدمه حاصل فى الحيز.\r__________________\rك.\r1 ـ فثلاثة: ت، فثلثة: ا ف ك لب ج ل ي، فثلث: ق، فعلته: م، لها: ا، ـ: نسخ اخرى.\r1، 2 ـ الوجود تقدم على العدم في: ت ي.\r2 ـ و ـ: م صفة الوجود فهذا: ا ف ق ك لب ي م، فهذا: ت.\r3 ـ جمهورهم عليه: نسخ، عليه جمهورهم: ق ج، على جمهورهم: ت.\r3، 4 ـ ابي هاشم تقدم علي ابي علي في: ا ت ج.\r4 ـ منوية: ت ف ج ك لب ي، مثوبة: م، ابن سونة: ل.\r6 ـ احدها: نسخ: ا: ا. البصري ـ: فقط. ابا اسحق: ـ: ق فقط.\r7 ـ هي: نسخ، هو: لب.\r8 ـ ذوات الجواهر: لب فقط.\r9 ـ الحيز: لب فقط. اختلفا: م نسخ، اختلفوا: ت.\r10 ـ فذهب: ت ف ج ق ك لب م، فزعم: ي، الحيز: ت ف ق ك لب ج ي ل، الحيز قبل الوجود: م."], [162, "وذهب أبو عبد الله إلى أن الشرط فى كون المتحيز حاصلا فى الحيز هو الوجود. فالجوهر قبل الوجود موصوف بالتحيز، لكنه غير حاصل فى الحيز.\rوزعم ابن عياش ان الجوهر حال العدم كما يمتنع اتصافه بالتحيز يمتنع اتصافه بالجوهرية فلهذا أثبت الذوات خالية عن الصفات.\rوثانيها: اختلفوا فى أن المعدوم هل له بكونه معدوما صفة أم لا؟ فالكل أنكروه إلا أبا عبد الله البصرى فإنه قال به.\rوثالثها: اتفقوا على أن الجواهر المعدومة لا توصف بأنها أجسام حال العدم إلا أبا الحسين الخياط فإنه قال به.\rورابعها: اتفقوا على أن بعد العلم بأن للعالم صانعا عالما قادرا حيا حكيما مرسلا للرسل، يمكننا الشك فى أنه هل هو موجود أم لا\r__________________\r1 ـ المشروط: ف فقط.\r2 ـ الوجود (1): نسخ، الوجود: لب، فالجوهر: نسخ، فان الجوهر: م، الوجود (2): ا ت ف ق ك، وجوده: لب م ي، لكنه: ا ت ف ق ك لب ي، ولكنه: م.\r4 ـ ان: نسخ، الى: ت.\r5 ـ امتنع (2): ي فقط. بالجوهرية: ت ج ق ل م، بالجوهر: ك، اثبت: ا ق ك ج ي، ثبت: ت ف ل لب م.\r6 ـ وثانيها: نسخ، ب: ا.\r7 ـ ام لا: ت ف ج ل ق لب ي، ـ: ك م، ابا عبدالله: ق ف ل لب م، ابو عبد الله: ا ت ج ك ي، فانه قال به ـ: ق فقط.\r8 ـ وثالثها: نسخ، ج: ا.\r9 ـ ابا: ف ق ك لب ل م، ابو: ا ج ت ي.\r10 ـ ورابعها: نسخ، د: ا، ان: ا ب ف ك لب ي، انه: م.\r10، 11 ـ حيا تقدم على قادرا في: ي.\r11 ـ يمكننا: نسخ، ممكن: ي، ام: ا ت ف ج ق ل ك لب"], [163, "إلى أن يعرف ذلك بالدليل لأنهم لما جوزوا اتصاف المعدوم بالصفة، لم يلزم من اتصاف ذات الله تعالى بصفة العالمية والقادرية كونه موجودا، فلا بد من دلالة منفصلة. واتفق الباقون من العقلاء على أن ذلك جهالة، وإلا لزم أن لا يعرف وجود الأجسام المتحركة والساكنة إلا بالدليل وبالله التوفيق.\rالمسألة الثالثة:\r"]], "pg": [149, 163]}, "687.6": {"x": [[163, "الّذي نقول به أنه لا واسطة بين الموجود والمعدوم، خلافا للقاضى وإمام الحرمين منا، وأبى هاشم وأتباعه من المعتزلة. فانهم أثبتوا واسطة سموها بالحال وحدوها بأنها صفة لموجود لا يوصف بالوجود ولا بالعدم.\rلنا أن البديهة حاكمة بأن كل ما يشير العقل إليه، فاما أن يكون له تحقق بوجه ما من الوجوه، وإما أن لا يكون.\r__________________\rي، او: م.\r1 ـ يعرف: ت م، نعرف: ا ق، نعرف: ف ك لب ي، بالصفة: ت م ج ف ل، بصفة الثبوت: ق.\r2 ـ بصفة المالمية والقادرية: نسخ، بهذه الصفات: ت ج.\r3 ـ دلاته منفصلة: ت ف ج ق ل ك م ي، دليل منفصل: لب.\r4 ـ يعرف: ت م، نعرف: ا ق، نعرف: ف لب ي.\r5 ـ بالدليل: نسخ، بدليل: ت ق، وبالله التوفيق: ت ك م، ـ: ا ف ق لب ي ج ل.\r8 ـ «اعلى درجته في الدارين» زيادة في لب بعد الحرمين، منا: ي ج، اولا منا: ف ق ك ل م، ـ: ت.\r9 ـ سموها بالحال: ت ف ق ك لب م، تمى الحال: ي.\r10 ـ ولا بالعدم: ت ف ق م، والعدم: ك ي ل.\r11 ـ حاكمة: نسخ، جازمة: ت ج، بان: ت ف ق ك م، فان: ي، فاما: ق ك لب م ي ل، اما: ت ج ف.\r12 ـ ما: ا ت ج ف ق ك ل لب ي، ـ: م، من الوجوه:"], [164, "والأول: هو الموجود. والثانى: هو المعدوم. وعلى هذا لا واسطة بين القسمين إلا أن يفسروا الموجود والمعدوم بغير ما ذكرناه فحينئذ ربما حصلت الواسطة على ذلك التأويل ويصير البحث لفظيا.\rاحتجوا بأمرين:\rالحجة الأولى: قد دللنا على أن الوجود وصف مشترك فيه بين الموجودات ولا شك أن الموجودات متخالفة بماهياتها. وما به الاشتراك غير ما به الامتياز بوجود الأشياء غير ماهياتها. ثم ذلك الوجود، إما أن يكون معدوما أو موجودا أو لا معدوما ولا موجودا والأول محال، لأن الموجودية مناقضة للمعدومية. والشيء لا يكون عين نقيضه.\rوالثانى: محال، إذ لو كان الوجود موجودا لكان مساويا فى الموجودية لسائر الموجودات.\r__________________\rم ـ: نسخ، واما ان: ك ف م، او: ت ج ل ا ـ لا.\r1 ـ والاول: ا ت ج ف ق ل ك لب ي، فالاول: م.\r2 ـ يفسروا: ت ق لب م ل، يفسر: ي ك، ذكرناه: ت ج ي، ذكرنا: ف ق ل ك لب م. فحينئذ: ا ت ف ق ك لب ي، وحينئذ: م.\r3 ـ فيصير: لب فقط.\r5 ـ احدهما: ت، الاول: ك، الاولى ـ: ج، ا: م، الحجة الاولى: نسخ اخرى، قد: نسخ، وقد: م، هو انا قد: ف، وصف: ا ت ف ق ك لب م، لفظ: ي.\r7 ـ غير ماهياتها: ات ج، مغاير لماهياتها: ف ق ك لب م ي.\r8 ـ موجودا (2) تقدم على معدوما في: ج ق ك.\r9 ـ منافصة: ت ف ق ك م، بناقض: لب ي، فالشيء: ف فقط.\r12 ـ الموجودية لسائر لماهية: ي، للماهيات الموجودة: ف ق ك لب الموجودات: ا ت ج، الوجودية للماهيات الموجودة: م."], [165, "ولا شك فى أنه مخالف لها بوجه ما وما به الاشتراك غير ما به الامتياز فالموجودية المشتركة بين الوجود وبين الماهيات الموجودة مغايرة لخصوص ماهية الوجود الّذي به الامتياز، فيكون للوجود وجود آخر ويلزم التسلسل، وذلك محال، فثبت أن الوجود لا موجود ولا معدوم.\rالحجة الثانية: الماهيات النوعية مشتركة فى الأجناس. وذلك يوجب القول بالحال.\rبيان الأول من وجوه ثلاثة:\rأحدها: إن السواد والبياض اشتركا فى اللونية. وليس الاشتراك فى مجرد الاسم. لأنا لو سمينا السواد والحركة باسم واحد، ولم نضع للسواد والبياض اسما واحدا لكنا نعلم بالضرورة، ان بين السواد والبياض من المجانسة ما ليس بين السواد\r__________________\r1 ـ في ـ: ا فقط.\r2 ـ الامتياز: نسخ، الاختلاف: ك، الوجود: ت ج ف ك لب ل م، الموجود: ا، الماهيات: نسخ، الماهية: لب. مغايرة: ت م. مغاير: ك.\r3 ـ اماهية: نسخ، ماهيات: ف، الذي به: ا ت ج، التي بها: ف ك لب م ل ي.\r4 ـ فيلزم: ك فقط، ذلك: ت ج ف ق ك لب م ي، هو: ا، فثبت: ا ت ف ق ك بما ذكرنا: ك لب ي، وثبت: م.\r6 ـ ب: ا، الحجة الثانية: ف ج ق ك ل لب م ي. الماهيات: نسخ، الماهية: ت.\r8، 9 ـ من وجوه ثلاثة: ق احدها ا: ا: ا ف ق ك م ي، هو: ت.\r9 ـ اشتركا: ت ف ق ك م، يشتركان: لب ي.\r10 ـ السواد والحركة: ا ت ق لب م ي، الحركة والسواد: ك، السواد والبياض والحركة: ق.\r12 ـ المجانسة: نسخ ج، المشاركة: ي."], [166, "والحركة. ولذلك فإن الاشتراك اللفظى لا يكون مطردا فى اللغات بأسرها وهذا النوع من الاشتراك معلوم لكل العقلاء.\rوثانيها: إن العلوم المتعلقة بالمعلومات المتغايرة مختلفة ثم إنا نحد العلم بحد واحد، يندرج فيه العلم القديم، والعلم المحدث، والعلم بالجوهر، والعلم بالعرض والمحدود ليس هو اللفظ بل المعنى فعلمنا أن العالمية وصف مشترك فيه بين هذه الماهيات المختلفة.\rوثالثها: إنا نقول الممكن إما جوهر وإما عرض فلولا أن العرضية وصف واحد، وإلا لم يكن التقسيم منحصرا، كما أن قولنا الممكن إما جوهر وإما سواد وإما بياض ليس تقسيما منحصرا. بيان الثانى: أنه إذا ثبت ان هذه الماهيات مشتركة من بعض الوجوه، ومختلفة من وجوه أخر فالوجهان اما أن يكونا موجودين، أو معدومين، أو لا موجودين، ولا معدومين.\rفالأول باطل، وإلا لزم قيام العرض بالعرض. والثانى باطل،\r__________________\r1 ـ ولذلك فان: نسخ، ولان: ق.\r2 ـ لكل: ت ج ف ق ل ك لب م، عند: ي.\r3 ـ وثانيها: ت ج ق ل ك م، ب: ا.\r4 ـ نحد: ت ف ق ك لب ي، نحدد: م، القديم والمسلم الحادث: ل لب ي، القديم والمحدث: ت، بالقديم والعلم بالمحدث: م.\r6 ـ العالمية: ت ج ف ق م، العلمية: ا ك لب ل ي.\r7 ـ وثالثها: ت ج ف ق ل ك لب م ي، ج: ا، واما: نسخ ف، او: ت ج.\r8 ـ منحصرا: ت ف ج ق لب م، ينحصر: ك، حاصرا: ي، وصف حاصرا: ل.\r9 ـ اما (2، 3) ـ ك فقط.\r11 ـ و ـ: ا ف ك. والوجهان: ف فقط.\r12 ـ فالاول: ت م، والاول: ف ج ق ل ك لب ي."], [167, "لأنا نعلم بالضرورة أن هذه الأمور ليست إعداما صرفة، فبقى الثالث وهو المطلوب.\rوالجواب عن الأول أن الكلام فى ان الوجود هل هو وصف مشترك أم لا؟ قد مر. والآن نساعد عليه، ونقول:\rلم لا يجوز أن يكون الوجود موجودا؟ قوله:\rلأنه لو كان موجودا لكان مساويا للماهيات الموجودة فى الموجودية ومخالفا لها فى خصوصياتها ولو كان كذلك يلزم التسلسل.\rقلنا التسلسل إنما يلزم إن لو اشتركا فى وصف ثبوتى، واختلفا فى وجه آخر ثبوتى. أما إذا كان الاختلاف فى أمر عدمى، فلا يلزم التسلسل بيانه: هو أن الوجود يشارك الماهية الموجودة فى الموجودية ويخالفها بقيد عدمى وهو أن الوجود وحده وإن كان موجودا لكن\r__________________\r1 ـ صرفة فبقي: ا ت ج ف ق ك ي، صرفا فيبقى: م.\r4 ـ مشترك: ا ت ج لب ل ي، مشترك فيه: ف ق ك م. ام لا: ـ ت فقط، قد مر: ت، قد تقدم: ف ج ق ك لب ي، فقد تقدم: ل، فقد تقدم ذكره: م، نساعد: ت ج ف ل ق ك م، نساعده: لب ي، فالان: ق فقط.\r6 ـ للماهيات: ت م، للماهية: ف ق ك لب ل ي، الموجودية ـ: ت فقط.\r7 ـ خصوصباتها: ف ق ك ل م، خصوصاتها: ت، خصوصيتها: ا، خصوصياتها ولو كان كذلك: لب يلزم التسلسل: ج ي.\r8 ـ يلزم: ا ت ج ف ق ك لب ل ي، يلزمه: م، ان ـ: ك فقط، وصف: ل لب، وجه: نسخ.\r9 ـ فلا يلزم: ا ت ج ف ق ل لب، لم يلزم: م، لا يكن: ك.\r10 ـ هو: ت ج م، وهو: ا، ـ: ف ق ك لب ي، الماهية: ا ت ج ف ق ك ل لب ي، الماهيات: م.\r11 ـ ويخالفها: نسخ، مخالفا: ا، الوجود وحده: ا ت ف لب م، للوجود وحدة: ق، الوجود: ك، لكن: ت ج ف ق ك لب م، ولكن: ي."], [168, "ليس معه شيء آخر والماهية الموجودة وإن كانت موجودة لكن لها مع مسمى الموجودية أمر آخر وهو الماهية. وإذا كان الأمر كذلك، لا يلزم أن يكون الوجود موجودا بوجود آخر، بل تكون موجوديته عين ماهيته. وعلى هذا التقدير ينقطع التسلسل.\rثم قالت النفاة رأينا حاصل أدلة مثبتى الأحوال على اختلافها راجعا إلى حرف واحد، وهو أن الحقائق مختلفة بخصوصياتها، ومشتركة فى عموماتها وما به الاشتراك غير ما به الامتياز.\rثم بينوا ان ذلك ليس بموجود ولا معدوم، فاثبتوا الواسطة. قالوا: وهذا يقتضي أن يكون للحال حال آخر إلى غير النهاية، لأن هذه الأحوال التى يثبتونها لا شك أنها متخالفة فى خصوصياتها، ومتساوية فى عموم كونها حالا. وما به المشاركة غير ما به الممايزة، فيلزم أن يكون للحال حال الى غير النهاية.\r__________________\r1 ـ ولكن: ي فقط.\r2 ـ امر: نسخ، شيء: ت ج، هو: نسخ، هي: ا.\r3 ـ لا: ت ف ك م، فلا: ج لب ي، ـ: ق.\r5 ـ النفاة: ت ف ق ك لب م، التقات: ي.\r7 ـ عموماتها: ت ج ف ق ك لب ل ي، عمومياتها: م، الامتياز: ا ت ج، الاختلاف: ف ق ك ل لب م ي.\r8 ـ بينوا: ت ف ق لب م ي، اثبتوا: ا ك، معدوم: نسخ، بمعدوم: ت.\r9 ـ وهذا: ت ف ج ق ك لب م ي، هذا: ا. اخر: ت ج ق م ي، ـ: ف لب ك، النهاية: ت ف ق ج لب م ي، نهاية: ا ك.\r10 ـ يثبتوثها: ا ت ف ق ج ك لب ي، بينوها: م، متخالفة: نسخ ج، مختلفة: ق.\r11 ـ متساويه: نسخ ج، مشتركة: ق، الممايزة: ا ت ج ف ق ك لب ي، التمايز: م.\r12 ـ حال: فسخ، حال اخر: ك ج لب ي."], [169, "أجاب المثبتون من وجهين.\rأحدهما: وهو الّذي عليه تعويل الجمهور. ان الحال لا يوصف بالتماثل والاختلاف.\rوالثانى: التزام التسلسل.\rفقالت النفاة أما الأول فضعيف جدا لأن كل أمرين يشير العقل إليهما. فإما أن يكون المتصور من أحدهما هو المتصور من الآخر أو لا يكون. والأول: هو المثل. والثانى هو المخالف فعلمنا أن القول بإثبات أمرين لا يوصفان بالتماثل والاختلاف جهالة.\rوأما الثانى وهو التزام التسلسل، فباطل. لأنا متى جوزناه، انسد علينا باب ابطال حوادث لا أول لها، وانسد علينا باب اثبات الصانع القديم وكل ذلك جهالة. هذا محصل كلام الفريقين.\r__________________\r2 ـ احدهما: ت ج، ا: ا، الاول: ق ك لب م ي.\r4 ـ والثاني: ت ف ج ك ل لب م ي، الثاني: ق، ب: ا.\r5 ـ فقالت النفاة: نسخ، وتمالت النقاة: ي، ضعيف: ف فقط.\r6 ـ اليها: ي فقط. المتصور (1): نسخ، التصور: ي.\r6، 7 ـ الاخر او: ت ف ق ك لب م، الاجزاء: ي.\r7 ـ و ـ: ي فقط. المخالف: ت ف ق ك لب م، الخلاف: ي ل.\r8 ـ جمالة نسخ ل ف م، محال: ت ج.\r9 ـ واما: ا ت ج ف ق ك لب ي، اما: م، التسلسل فباطل: ت ف ق ك ج ي، التسلسل محال: لب، ايضا ضعيف: ا، منى: ت ج ف ك م، لو: ق لب ي، جورناه: ت ج ف ق ك لب م ي، جوزناها: ا.\r10 ـ باب: ا ت ج ف ق ك لب ي، ـ: م. علينا (2): ت ج فقط.\r11 ـ القديم: نسخ، القديم سبحانه وتعالى: ك، فكل: ا فقط."], [170, "والّذي أقوله: إن ذلك الإلزام غير وارد على القائلين بالحال لأنا لما بينا أن السواد والبياض مثلا يشتركان فى الموجودية، ويختلفان فى السوادية والبياضية، وعلمنا أن ما به الاشتراك وما به الامتياز، لا يجوز أن يكونا شيئا واحدا ولا يجوز أن يكونا سلبيين. لا جرم أثبتنا أمرين ثابتين: أحدهما كونه سوادا والآخر وجوده.\rأما الوجودية والسوادية، فهما مختلفان بحقيقتهما ويشتركان فى الحالية، لكن الحالية ليست صفة ثبوتية لأنا لا نعنى بالحال، إلا ما لا يكون موجودا ولا معدوما. وإذا كان الاشتراك واقعا فى وصفى سلبى، لم يلزم أن تكون الحالية صفة قائمة بالوجود، فلم يلزم أن يكون للحال حال آخر. فقد ظهر اندفاع هذا الإلزام عنهم، مع أن\r__________________\r1 ـ وارد: ت ج ك لب م ف هامش، واقع: ف.\r2 ـ يشتركان: نسخ، يستويات: ف. يختلفان: ت ف ج ق ك لب م ي، مختلفان: ا.\r4 ـ لا يجوز: نسخ، لا يجوز ان يكونا شيئا واحدا ولا يجوز: لب.\r4، 5 ـ لا جرم ... وجوده ـ: ي فقط.\r6 ـ الوجودية: ا ج ت ق ل، الوجود: ف ك، الموجودية: لب م، مختلفان: ا ت ج ف ق ل لب، يختلفان: ك م ي. يشتركان: ف ل م، مشتركان: ج ت.\r7 ـ توتية: ت ق م، ثابتة: ك، لانا: ت، لانه: نسخ ل، نعنى: ت ج م، معنى: ف ق ك لب ل ي، بالحال: ت ج م، للحال: ا ل ف ك ق لب ي.\r8 ـ موجودا ... معدوما: ت ج ق ل ك م، موجودة ... معدومة: لب ي.\r8، 9 ـ وصفى سلبي: م، وصف سلبي: ت ج ف ق ك ل ي، الوصف السلبي: لب.\r9 ـ الحالية: ا ت ج ف ق ك لب ي، الحال: م، قائمة بالوجود: ا ل ف، تامة بالوجود: ت، ثبوتية: ج.\r10 ـ اخر: ا ت ج م، ـ: ف ق ك لب ي، هذا: ا ت ج ف ق ك لب ي، ـ: م."], [171, "الأولين والآخرين من مثبتى الأحوال، كانوا عاجزين عن دفعه فالحمد لله الّذي هدانا لهذا وما كنا لنهتدى لو لا أن هدانا الله.\rوأما الجواب عن الحجة الثانية أن نقول: لم لا يجوز أن يكون ما به الاشتراك وما به الامتياز موجودين.\rقوله: يلزم قيام العرض بالعرض.\rقلنا هذا أقرب إلى العقل من إثبات الواسطة بين الموجود والمعدوم وتعويل النفاة فى دفع هذه الحجة على إلزام أن يكون للحال حال آخر وقد عرفت ضعفه.\rوللفلاسفة فى هذا الباب طريق آخر، وهو أنهم قالوا الأجناس والفصول التى بها تتقوم الأنواع البسيطة فى الخارج، موجودات فى الأذهان، لا فى الأعيان.\r__________________\r1 ـ فالحمد: ت ف ق ج لب م، والحمد: ك، والله: ا ي، الحمد: ل.\r3 ـ واما: ت ف ق لب م ي، اما: ج ك، ـ:. ان نقول: ت ج، ان يقول: ف لب م، انا نقول: ق ل ي، ـ: ك.\r4 ـ الامتياز: نسخ، الامتياز امرين: لب.\r5 ـ قوله يلزم: ت ف ج ق ك لب ي، قولهم يلزم: ا، قوله يلزم منه: م.\r6 ـ الموجود والمعدوم: ت ف م، الوجود والعدم: ج ل.\r7 ـ النقاة: ي فقط. في: ت ف ق ج ك لب م ي، على: هذه ـ: ت فقط. الزام: ت ق ك م ي، التزام: ا، الالزام: لب، ـ: ج.\r8 ـ اخر: ت م، ـ: نسخ اخرى ج ل، وقد: ت ف ق، فقد: ا ج ك لب ي، قد: م.\r9 ـ وهو: نسخ، وهمو: ي.\r10 ـ بها تنقوم ينقوم: ت ا: ف ق لب م ي، ينقوم بها: ا ج ك، موجودات: ت ج ف ق ك لب م ي، موجودة: ا."], [172, "فقيل لهم الحكم الذهنى، إن كان مطابقا للخارج عاد كلام مثبتى الحال، وإلا فهو جهل ولا عبرة به وبالله التوفيق.\rالتفريع على القول بالحال:\rقالوا ثبوت الحال للشىء، اما أن يكون معللا بموجود قائم بذلك الشيء كالعالمية المعللة بالعلم أو لا يكون كذلك كسوادية السواد والأول هو الحال المعلل، والثانى هو الحال الغير المعلل. واتفقوا على أن الموجودات متساوية فى الذوات مختلفة بهذه الأحوال.\rوأما الوجود، فزعم مثبتو الحال منا أنه نفس الذات. وزعمت المعتزلة أنه صفة والقول بإثبات كون المعدوم شيئا بناء على هذا، والّذي أختاره تفريعا على القول بالحال أن ذلك باطل، لأن الذوات لو كانت مشتركة، سواء قلنا: ان الوجود هو الذات على ما يقوله أصحابنا، أو غيره على ما يقوله المعتزلة، لصح على كل واحد منهما،\r__________________\r1 ـ لهم: نسخ، له: ك.\r2 ـ الحال: ت ف ك م، الاحوال: ق لب ي، وبالله التوفيق: ت ق ك م، ـ: ا ف ج ل لب ي.\r4 ـ الحال: ا ت ف ج ق ك لب ل ي، الحانية: م، بموجود: نسخ، موجود: ت، بمعنى: ج، بوجود: ل.\r5 ـ العالمية: نسخ، العاملية: ت، كعالمية العالم: ل.\r6 ـ هو: ا ت ك ج لب، ـ: ف ق م ي. الغير: ت ج ق ك م، غير: ف ل لب ي.\r7 ـ متساوية: ل ف م، متفقة: ت ج ل، في اللوات و: ج ف لب ل م ي، بالدوات و: ا، في الذوات: ت، بهذه: ا ت ج ف ك لب ي، في هذه: ق م.\r8 ـ واما: ت ج م، اما: ق ك ي ل، فزعم: نسخ، فقد زعم: ك.\r9، 11 ـ على هذا ـ: ك ... مشتركة: نسخ اخرى ا ل ق ان ذلك باطل ـ: ج، على ان كانت مشتركة: ت.\r11 ـ ان: ا، ـ: ت ج ل م ف.\r12 ـ لصح: ت ف ج ق ل ك لب م، يصح: ا ي، منهما:"], [173, "ما يصح على الآخر ضرورة استواء المتماثلات فى كل اللوازم، فكان يلزم صحة انقلاب القديم محدثا، والجوهر عرضا وبالعكس، وهو محال.\rولأن اختصاص الذات المعينة بالصفة المعينة أن كان لا لأمر، فقد ترجح أحد طرفى الممكن على الآخر لا لمرجح، وهو محال. وان كان لأمر، فذلك الأمر ان كان ذاتا، عاد البحث فى اختصاصها من بين سائر الذوات بصفة المرجحية، وإن لم يكن ذاتا كان صفة لذات، فيعود البحث فى اختصاص تلك الذات بها.\rأما إذا جعلنا الخصوصية ذاتا، وما به الاشتراك، صفة اندفع الإشكال، لأن الأشياء المختلفة يجوز اشتراكها فى لازم واحد، وأما الأشياء المتساوية فلا يجوز اختلافها فى اللوازم وبالله التوفيق.\rتقسيم الموجودات على رأى الحكماء\rالموجود إما أن يكون واجب الثبوت لذاته وهو الله سبحانه\r__________________\rا ت ج ف ك لب، منها: ق ي، ـ: م.\r1 ـ يصح: نسخ ج ف، صبح: ت ق ك ل، استواء: ت ج ف، سواد اسر: ل، المتماثلات: نسخ، المتماثلين: ل ي. اللوازم: نسخ ا ل، الاحكام اللازمة: ت.\r2 ـ فكان: نسخ، وكان: ت.\r4 ـ لام ر: ت ف ق ك م، امر: ا.\r6 ـ لامر: ت ف لب م ي، للامر: ا، الامر: ق، فذلك: ا ت ف ق لب ي، فذاك: م، اختصاصها: ت ج ق ل م، اختصائها: ك، من بين: ا ت ج ف ل ق ك لب ي، دون: م.\r7 ـ بصفة المرجحية: ا م ج، بالمرجحية: ت ل.\r8 ـ الذات: ت ق م، الذوات: ك.\r10 ـ و: ت ك لب ي.\r11 ـ اللوازم وبالله التوفيق: ت ق ك، اللوازم: ف ج ق ل لب م، لوازم: ي.\r12 ـ على راى الحكماء: ف ي، ـ: ا ت ج لب ك م ق ل.\r13 ـ سبحانه و: ك، ـ: نسخ."], [174, "وتعالى، وإما أن يكون ممكن الثبوت لذاته وهو كل ما عداه.\rفإن قيل الواجب لذاته يساوى سائر الموجودات فى أصل الوجود ويخالفها فى الوجوب، وما به الاشتراك غير ما به الامتياز، فالوجود غير الوجوب ولأنا ندرك التفرقة بين قولنا: موجود واجب، وبين قولنا: موجود موجود. ولو كان الوجود هو الوجوب لما بقى الفرق، وإذا ثبت ان الوجود غير الوجوب.\rفنقول إما أن لا يكون بينهما ملازمة أو يكون والأول محال، وإلا لصح انفكاك كل واحد منهما عن الآخر، فيمكن انفكاك ذلك الوجود عن الوجوب. وكل ما كان كذلك استحال أن يكون واجبا لذاته.\rوأيضا يمكن انفكاك الوجوب عن الوجود، وذلك محال، لأن الوجوب نعت الوجود، ويستحيل حصول النعت دون المنعوت.\rوأما الثانى وهو أن يكون بينهما ملازمة فن المحال أن يكون كل واحد منهما مفتقرا إلى الآخر لاستحالة الدور. ومحال أن يكون الوجود مستلزما للوجوب، وإلا فكل موجود واجب هذا خلف.\r__________________\r1 ـ الثبوت: ت ج ق ك ل، الوجود: م. كل: ـ ك فقط.\r2 ـ فان ـ: ت ق ك. اصل ـ: ك.\r3 ـ بخالفها: ت ف ق ك لب م ي، مخالفها: ا.\r4 ـ قولنا موجود: ل م ت ج ف ق ك، فول الموجود: ا.\r6 ـ بقى: ت ج ف ق ك لب ل م ي، اتضح: ا. الوجود غير الوجوب: ت ج م، الوجوب غير الوجود: ف ق ل لب ي، الوجوب غير الوجوب: ك.\r8 ـ لصح: ت ج ف ق ك لب ي، يصح: م.\r11 ـ ايضا: ت ق ك م، كذلك: ي، وذلك محال لان: ا ت ف ق ك لب ي، وذلك لان الوجود محال ان: م.\r12 ـ ويستحيل: ت ج ف ق ك م ي، فيستحيل: لب.\r14 ـ مفتقرا الى الاخر: نسح ا ل، مستلزما للاخر: ت ج."], [175, "ولأنه يلزم كون الوجوب معلولا، وكل معلول ممكن لذاته، وكل ممكن لذاته واجب بعلته فقبل هذا الوجوب وجوب آخر، إلى غير النهاية، وهو محال.\rومحال أن يكون الوجوب مستلزما للوجود. لأن الوجوب نعت الوجود، وكيفيته، فيكون مفتقرا إليه. فلو كان الوجود مفتقرا إليه يلزم الدور.\rومحال أن يكونا معلولى علة. لأن تلك العلة، اما أن تكون موصوفة بهما، أو صفة لهما أو لا موصوفة ولا صفة. والأول محال وإلا لكان ما ليس بموجود ولا واجب علة للوجوب والوجود، لكن ما ليس بموجود معدوم. فالمعدوم علة الموجود والوجوب، هذا\r__________________\r1 ـ معلولا: نسخ، معلولا لافتقاره الى المستلزم: ك، فكل واجب: نسخ، لكان كل واجبا: لي.\r1، 2 ـ وكل ممكن لذاته: ا ف ق لب ل ي، وكل ممكن: ت ج، ـ: ك م.\r2 ـ واجب بعلنه: نسخ، واجب بعلة: ل، فانما يجب لوجوب علته: ت ج، الى غير النهاية: ت ج ق م، لا الى بداية: ي، مستلزما للاخر لا الى نهاية: لب، لا انى نهاية: العدل.\r3 ـ وهو محال: ـ لب فقط.\r5 ـ وكيفيته: نسخ ا ل م، ـ: ت، الوجود: نسخ ل، الوجوب: ت.\r5، 6 ـ الوجود مفتقرا اليه ـ: ك.\r6 ـ يلزم: ت م، لزم: ف ق ك لب ي ل.\r7 ـ ومحال: ا ت ل، «هو» مشطوب في: ا، وانه محال ومحال: ف م، وهو محال ومحال: ج ق ك، يكونا: ت ق لب م ي، يكون: ف ك.\r8 ـ موصوفا (1، 2): ف فقط. لا صفة ولا موصوفة: ي فقط.\r9 ـ للوجوب والوجود: ت ج ف ق م، للوجود والوجوب: لب، لهما: ك، الوجوب والوجود: ل، لكن: ف ق ك ل م، ولكن: لب ي، ـ: ت ج.\r10 ـ ما ليس بموجود معدوم فالمعدوم علة للوجود والوجوب:"], [176, "خلف. ولأنه يلزم كون الوجوب معللا وهو محال، على ما تقدم.\rوالثانى محال، وإلا لعاد الإشكال فى كيفية ذلك اللزوم.\rوالثالث محال، وإلا يلزم أن يكون الموجود الواجب لذاته مفتقرا إلى علة منفصلة، هذا خلف.\rلا يقال الوجوب سلبى، لأنا نقول: إنه تأكد الوجود. والشيء لا يتأكد بنقيضه، ولأنه نقيض اللاوجوب الّذي هو عدمى لكونه محمولا على العدم، فيكون الوجوب وجوديا.\rسلمنا كونه سلبيا لكن يستحيل أن يكون المقتضى للوجود هو الوجوب لامتناع كون العدم مقتضيا للوجود، ولا بالعكس، وإلا لكان كل موجود واجبا.\rوالجواب أنه بناء على كون الوجود مشتركا بين الواجب والممكن\r__________________\rا ف ق ك لب ل ي الوجود والوجوب: ف، كون ما ليس بموجود ولا واجب علة للوجوب والوجود محال لابن ماليس بموجود فهو معدوم فكون المعدوم علة للوجود والوجوب: م، ـ: ت ج.\r1 ـ معللا: ا ت ق، معلولا: ف ج ك ل م ي.\r2 ـ لعاد: ت ف ج ك ي، عاد: ق لب م.\r3 ـ والا: ت ج، لانه: م ل ف، الموجود: ـ ف فقط.\r4 ـ هذا: ا ت ج ف ق ك ل لب ي، وهذا: م.\r5 ـ تاكد: ت ج ك لب ي، تاكيد: ف، توكد: ق، يتاكد: م، الوجود: نسخ، الوجود به: م فقط.\r6 ـ نقيض اللاوجوب: ت ج ف ك لب، نقيض ان لا وجوب: ق ي، يقتضى اللا وجوب: م. الذي: ا ت ف ج ق ك لب، للذي: ي، بالذي: م.\r7 ـ الوجوب: ي، ـ ا ف ت ق ك لب م ج ل.\r8 ـ لكن: لكنه: ج للوجود: ا ت ج م، الوجود: ل، للثبوت: ف ق ك لب ي.\r10 ـ لكان: ت ج ف ك لب ي، كان: ق م.\r11 ـ و (1): ت ج ق ك لب م ي، ـ: ا ف. كون: نسخ"], [177, "وهو باطل على ما تقدم.\rخواص الواجب لذاته وهى عشرة:\rمسئلة (أ):\rالشيء الواحد لا يكون واجبا لذاته ولغيره معا لأن ما بالغير يرتفع بارتفاع الغير، وما بالذات لا يرتفع بارتفاع الغير والجمع بينهما محال.\rمسئلة (ب):\rالواجب لذاته لا يتركب عن غيره، لأن كل مركب محتاج إلى جزئه، وجزؤه غيره، فكل مركب محتاج إلى غيره وكل محتاج إلى الغير ممكن لذاته، ولا شيء من الممكن لذاته واجب لذاته.\r__________________\rف لب م، ان: ت ج، مشتركا: نسخ ف ل م، مشترك: ت ج ك.\r1 ـ تقدم: نسخ، تقدم وبالله التوفيق: ك.\r2 ـ وهي: ف ج ق ك لب م ي، هي: ا، وهو: ت.\r3 ـ مسئلة: ج ق ك لب م، ا: ا ي، المسئلة الاولى: ف، مسائل: ل، ـ: ت.\r7 ـ مسئلة: ج ف ق ك لب م، ب: ا ل ي، فا: ت.\r8 ـ محتاج: نسخ، يحتاج: ت.\r8، 9 ـ الى جزئه ... الى غيره: نسخ، الى غيره: ك.\r9 ـ وجزؤه: ت ق لب ج م ي، والى جزء: ف، فكل: ا ت ج ف ي، وكل: ق م.\r9، 10 ـ وكل محتاج الى الغير: ا ت ف ج ق ك لب ل ي، م.\r10 ـ لذاته (1): ت ج ك م، بالذات: ف لب ل ي. الممكن لذاته واجب واجبا: ل لذاته: نسخ ل ف، الواجب لذاته ممكن لذاته: ت ج لذاته (2): ت ق م، بالذات: ف، بذاته: ك لب ي. لذاته (3): ت ف ق ك م، بذاته: لب ي."], [178, "مسئلة (ج):\rالواجب لذاته لا يتركب عنه غيره، وإلا لكان بينه وبين الجزء الآخر من المركب علاقة، والواجب لذاته لا علاقة له بالغير.\rمسئلة (د):\rالواجب لذاته لا يكون وجوده زائدا على ماهيته، لأن ذلك الوجود إن كان مستغنيا عن تلك الماهية لم يكن صفة لها، وإن لم يكن مستغنيا، كان ممكنا لذاته مفتقرا إلى مؤثر. وذلك المؤثر، إن كان غير تلك الماهية كان الواجب لذاته واجبا بغيره وإن كان تلك الماهية فهى حال ايجابها ذلك الوجود، إما أن تكون موجودة أو لا تكون.\rوالأول محال، لأنها إن كانت موجودة بهذا الوجود كان الوجود الواحد شرط نفسه، وإن كانت موجودة بغيره كانت الماهية موجودة مرتين. ثم الكلام فى ذلك الوجود كالكلام فى الأول فيلزم التسلسل\r__________________\r1 ـ مسئلة: ج ف ق لب م، ج: ا ي ق ل، ب: ت.\r2 ـ بواجب: ك.\r3 ـ الجزء الاخر من المركب: ت ف ك لب م ي، غيره.\r4 ـ مسئلة: ج ف ق ك لب م، د: ا ت ق ل ي.\r5 ـ على ماهيته: ت ج لب م، عليه: ف ق ك ي، لم يكن: لا يكون: ج.\r7 ـ مستغنيا: نسخ، مستغنيا عن تلك الماهية: ك، مفتقرا: نسخ، ومفتقرا: ف.\r8 ـ لذاته: نسخ ج، بذاته: ت، بغيره: ت ق ي، لغيره: ف ج ك لب ل م.\r9 ـ الوجود: ا ت ج ف ق ك لب ل ي، الوجوب: م. تكون (2) ت ق ج ك م، تكون موجودة: لب ي.\r10 ـ و ـ: ك لب. ان: ت ج ف ق ل ك لب ي، لو: م.\r11 ـ شرط نفسه: ا ت ج ق ل ك لب م ي، شرطا لنفسه: ف. كانت موجودة بغيره: ا، كانت بغيره: ت ج لب م، نان غيره: ف ك ي، كان بغيره: ق ل.\r12 ـ فيلزم: ا ج ف م، فلزم: ق فقط، يلزم: ل."], [179, "وإن لم تكن موجودة فهو محال أيضا لأنا لو جوزنا كون المعدوم مؤثرا فى الموجود لم يمكنا الاستدلال بفاعلية الله تعالى على وجوده، ولأن تأثير المعدوم فى الموجود باطل بالبديهة.\rالاعتراض عليه لم لا يجوز أن يكون المؤثر فيه هو الماهية لا بشرط الوجود، ثم لا يلزم من حذف الوجود عن درجة الاعتبار دخول العدم فيها، لأن الماهية من حيث هى هى لا موجودة ولا معدومة وهذا كما قالوا فى الممكن فإن ماهيته قابلة للوجود لا بشرط وجود آخر، وإلا وقع التسلسل، ولم يلزم أيضا أن يكون القابل للوجود معدوما، وإلا لزم كون الشيء الواحد فى الوقت الواحد موجودا معدوما معا ثم الّذي يدل على أن واجب الوجود وجوده زائد على ماهيته، ان وجوده معلوم، وماهيته غير معلومة، والمعلوم غير ما ليس بمعلوم.\r__________________\r1 ـ يكن: ا ت ك، تكن: ق ج م ي، يكن: ف لب ل، موجودة: ا ج م ت، موجودا: ل، ايضا: ت ف لب، ـ: ا ج ق ك ل م ي.\r2 ـ الموجود: ت ج ق، الوجود: ا م ل ف، يمكنا: ل م، يمكننا: ا ت ج ف ق ك لب ي، تعالى: نسخ، سبحانه وتعالى: ف.\r3 ـ و: ت ج ف ك لب م ي، ـ: ا.\r4 ـ الاعتراض عليه: ا ج ف ق ك لب ل ي، الاعتراض: ت، لاعتراض: م، فيه: ـ ف.\r5 ـ حدف: ت ج ف ق ك لب م ي، حدث: ا.\r6 ـ هي هي: ا ت ف ج ق ك ل ي، ـ: م، وهذا: نسخ، هذا: ا.\r7 ـ فان: ت ف ق ك لب م، ان: ي.\r8 ـ ايضا: مشطوب في: ي.\r9 ـ موجودا معدوما معا: ا ت م ل. موجودا معدوما: ت ج، معدوما موجودا: ك.\r10 ـ واجب الوجود وجوده، ا ت ج ف ق ك لب ل ي، وجوب واجب الوجود: م.\r11 ـ معلومة: نسخ، معلوم: ا."], [180, "مسئلة (ه):\rالواجب لذاته لا يجوز أن يكون وجوبه زائدا عليه، إذ لو كان الوجوب مستتبعا للوجود، لكان الفرع أصلا للأصل، وهو محال وإن كان تابعا يلزم أن يكون ممكنا لذاته، واجبا بغيره، فيكون الواجب بالذات ممكنا بالذات، فيكون الواجب بالذات أولى أن يكون ممكنا بالذات.\rوأيضا فوجب ذلك الوجوب، لوجوب مؤثره فقبل هذا الوجوب وجوب آخر لا إلى غاية ولزم التسلسل وهو محال.\rفعورض بأن الوجوب والامتناع كيفيات لانتساب المحمولات إلى\r__________________\r1 ـ مسئلة: ف ج ق ك لب م، ة: ا ق ي ل، ـ: ت.\r2 ـ لوكان: ت ج ف ق ك ل ي، لو كان زائدا فان كان: م.\r3 ـ لكان: نسخ، كان: ت ج، وهو محال: ـ ل ت ج ي.\r4 ـ يلزم: ا ت ج، لزم: ف ق ك لب م ي، لغيره: ك فقط.\r5 ـ الواجب: ف ي، الوجوب: ق ك لب ل م، بالذات (1): ف ق ك لب ي، لذاته: م.\r4، 6 ـ واجبا بغيره ... يكون ممكنا بالذات ـ: ت ج.\r6 ـ بالذات: لب، لذاته: ج م، ـ: ف ق ك ي ل.\r7 ـ وايضا ـ: ج، فوجب: ت، لو وجب: ف ك، فوجوب. لب م ي ج، فلو وجب: ل، الوجوب: نسخ، الوجود: ي، او جزب مؤتره: ت ي ل، لوجوب مؤثر: ج ك، بوجوب مؤثر: ف، لوجوب مؤثره انما يكون على هذا التقدير: لب، يكون لوجوب مؤثره على هذا التقدير: ا م.\r8 ـ لا الى غاية: ا ت لب م ي، لا الى نهاية: ف ك ل، ـ: ت ج، وهو: ا ت ف ق م، هذا: ك، وهذا: ل.\r9 ـ فعورض: ت ج ق ك لب م ي، عورض: ف، بعد الامتناع راد: ي «والامكان»، لانتساب: ت ق ج ك لب ل م. انتساب: ف.\r9، ا (181) ـ المحمولات الى الموضوعات: ا ت ف ل، الموضوعات الى"], [181, "الموضوعات فهى لا محالة مغايرة للموضوعات والمحمولات وتابعة لهما.\rمسئلة (و):\rالوجوب بالذات لا يكون مشتركا بين اثنين، وإلا لكان هو مغايرا لما به يمتاز كل واحد منهما عن الآخر، فيكون كل واحد منهما مركبا عن ما به الاشتراك وما به الامتياز. فإن لم يكن بين الجزءين ملازمة كان اجتماعهما معلول علة منفصلة هذا خلف. وإن كان بينهما ملازمة فإن استلزمت الهوية الوجوب كان الوجوب معلول الغير هذا خلف وإن كان الوجوب مستلزما لتلك الهوية، فكل واجب هو هو، فما ليس هو، لم يكن واجبا.\rفقيل عليه هذا بناء على كون الوجوب وصفا ثبوتيا، وهو باطل وإلا لكان إما داخلا فى الماهية أو خارجا عنها وكلاهما باطلان على ما تقدم.\r__________________\rالمحمولات: ف ج ق ك م ي.\r1 ـ لا محالة ـ: لب.\r2 ـ لهما: نسخ ل، لها: ج ك.\r3 ـ مسئلة: ف ج ق ك لب م، و: ا ت ق ي.\r4 ـ مغاير: ك فقط، ـ: ل.\r5 ـ عن: ت ج ف ق ك م ي، من: لب، على: ا.\r8 ـ الوجوب: ت ج ف ق ك ل لب، للوجوب: ا ي.\r9 ـ فما، ت ج ف ق ك لب ل ي، مما: م.\r10 ـ ليس هو: ت ج ف ق ك ل لب م ي، ليس هو هو: لم يكن واجبا: نسخ، ليس بواجب: ت.\r11 ـ هذا: ا ت ج ف ق ك لب ل ي، ـ: م. الوجوب: ت ج ف ق لب ل ك ي، الوجود: م.\r12 ـ لما: ا ت ج ل ف ق ك لب ي، ـ، م، فعلوا، ب ج."], [182, "ولأنه لو كان ثبوتيا لكان مساويا فى الثبوت لسائر الماهيات ومخالفا لها فى الخصوصية، فوجوده غير ماهيته. فاتصاف ماهيته بوجوده إن كان واجبا كان للوجوب وجوب آخر إلى غير النهاية، وإن لم يكن واجبا كان ممكنا. فالواجب لذاته أولى أن يكون ممكنا لذاته هذا خلف.\rوأيضا فهو بناء على كون التعين وصفا ثبوتيا زائدا، وهو باطل على ما سيأتى إن شاء الله تعالى.\rوأيضا فهو معارض بما أن واجب الوجود مساو للممكن فى الموجودية ومخالف له فى الوجوب، فوجوده ووجوبه متغايران، ويعود التقسيم المذكور فى أول الباب وقد عرفت ان هناك لا جواب إلا قولنا: الموجود مقول على الواجب والممكن بالاشتراك اللفظى فقط. وإذا كان كذلك، فلم لا يجوز أن يكون الوجوب بالذات مقولا على\r__________________\r1 ـ لسائر: ت ج ف ق ك لب ي، كسائر: م.\r2 ـ لها ـ: ت فقط. الخصوصية: ت ج ف ق ك لب ل ي، خصوصيته: ا م.\r2، 3 ـ فاتصاف ... بوجوده: ت ج ف ق ك لب م ي، فوجوده: ا.\r4 ـ فالواجب: ت ج ق ك لب ل ي، والواجب: م. لذاته: ا ج، بذاته: ك، ممكنا (2): ت فقط.\r5 ـ لذاته: لب، ـ: نسخ ا ل ج.\r6 ـ التعين وصفا: نسخ ا ل ف، التعيين امرا: ت، المتعين امرا: ج.\r8 ـ للممكن: نسخ، لممكن الوجود: ل.\r9 ـ الموجودية: ت ج ف ق لب م ي، الوجودية: ا ك ل. مخالفا لها: ك فقط. فوجوده ووجوبه: ا ت ف ك م ي، فوجوبه ووجوده: ج ق لب.\r10 ـ ان هناك ت ج، هناك انه: ف ق ك لب ل م ي.\r10، 11 ـ جواب ... الموجود الوجود: ت ج ف ل: ف ق ك لب م واجب الا قولنا الوجود: ي."], [183, "الواجبين بالاشتراك اللفظى فقط.\rمسئلة (ز):\rوقوع لفظ الواجب على الواجب بالذات والواجب بالغير بالاشتراك اللفظى، وإلا فالوجوب بالذات مركب، فيكون ممكنا، ولأن القدر المشترك، إن كان غنيا عن الغير، لم يكن تمام ماهية الوجوب بالغير عارضا للغير، هذا خلف وإن كان مفتقرا لم يكن تمام ماهية الوجوب بالذات غنيا عن الغير.\rفعورض بأن مسمى الوجوب يمكن تقسيمه إلى الواجب بالذات والواجب بالغير. ومورد التقسيم مشترك بين القسمين لا محالة. ولقائل أن يستدل على أن الوجوب ليس وصفا ثبوتيا بأنه لو كان ثبوتيا لكان إما أن يكون مقولا على الواجب بالذات والواجب بالغير بالاشتراك المعنوى، أو بالاشتراك اللفظى. وهما باطلان على\r__________________\r1 ـ اللفظي فقط: ت ج ف ك لب م ي، في اللفظ: ا، اللفظي: ق.\r2 ـ مسئلة: ج ف ق ك لب، ز: ا ت ي.\r3 ـ لفظ: ت ج ق ك ل لب م ي، اللفظ: ف، بالذات ... بالغير: ت ج م، لذاته ... لغيره: ف لب ل ي، لذاته .. بغيره: ق ك.\r4 ـ اللفظي: ج ق لب م ي، ـ: ت ف ك ل. فالوجوب: ت ح لب ل م، فالواجب: ق ك.\r7 ـ بالذات: ت ف ج ل لب م ي، لذاته: ف. عن الغير ـ: ا فقط.\r8 ـ الوجوب: ت ف ج ق ل م ي، الواجب: لب.\r7، 8 ـ غنيا ... بالذات ـ: ت فقط.\r9 ـ وبالواجب: ا ت ج ف ق ك لب ي، والى الواجب: م.\r10 ـ الوجوب: ت ج ق ك لب م ي، كون الوجوب: ف، كان: ا ت ف ك لب ل ي، كان وصفا: ق م ج.\r12 ـ بالاشتراك اللفظي: ا ف ج ك لب م، لا بالاشتراك المعنوي:"], [184, "ما تقدم فالوجوب ليس وصفا ثبوتيا.\rمسئلة (ح):\rالواجب لذاته واجب من جميع جهاته إذ لو فرضنا اتصافه بأمر ثبوتى، أو سلبى، لا يكفى فى تحققه ذاته، لتوقف حصول ذلك الأمر له، أو انتفائه عنه، على حضور أمر خارجى أو عدمه. وذاته موقوفة على حضور ذلك الحصول، أو الانتفاء. والموقوف على الموقوف على الغير موقوف على الغير. فالواجب لذاته موقوف على الغير، فيكون ممكنا لذاته، هذا خلف وهذه الحجة لا تتمشى إلا بنفى كون الإضافات أمورا وجودية فى الأعيان.\rمسئلة (ط):\rالواجب لذاته لا يصح عليه العدم، إذ لو صح لكان وجوده متوقفا على عدم سبب عدمه. والمتوقف على الغير ممكن بالذات.\rمسئلة (ى):\rالواجب لذاته يجوز أن تعرض له صفات تستلزمها ذاته فيكون\r__________________\rي ت ل، باللفظي: ق، باطلان: نسخ ج، محالان: ت.\r2 ـ مسئلتة: ج ف ق ك لب م، ح: ا ت ل ي.\r5 ـ اوب: ق فقط، له ـ: ل، انتقائه: نسخ، سلبه: ج، حضور: ت ج ف ق لب م، حصول: ك ي ل، امر: ا لب م، غير: ج ت ف ق ك ل ي، عدمه: نسخ، على عدمه: لب، وذاته: ا ت ج ل ق ك ي، فذاته: ف م.\r6 ـ موقوفة: ا ت ج ك م، متوقفة: ق لب ي، يتوقف: ل.\r7 ـ على (1): ت ف ق ك لب ي، على حضور ذلك: م، على ذلك: ج.\r8 ـ تمشي: ك م ي، تمثى: ا ت ق، تمشي: ف لب.\r9 ـ الاشافات: نسخ، الاشافيات: ق. امور: ك فقط.\r10 ـ مسئلة: ف ج ق ك لب م، ط: ا ت ق ل ي.\r12 ـ متوقف: ك فقط.\r13 ـ مسئلة: ج ك ق لب م، ي: ا ت ق ل ي."], [185, "الوجوب الذاتى حصة لتلك الهوية فقط، وسائر النعوت واجبة لوجوب تلك الهوية وتكون الوحدة حصة لتلك الهوية من حيث هى هى، وإن كانت إذا أخذت مع الوحدة لم يبق واحدة.\rخواص الممكن لذاته وهى ست\rمسئلة: (أ)\rالممكن: هو الّذي لا يلزم من فرض وجوده، ولا من فرض عدمه من حيث هو هو محال. فان قيل القول بالامكان ممتنع من وجوه.\rأحدها: إن وجود السواد مثلا، اما أن يكون عين كونه سوادا أو غيره. فإن كان الأول، كان قولك: السواد يصح أن يكون موجودا وأن يكون معدوما جاريا مجرى قولنا: الموجود يصح أن يكون موجودا وأن يكون معدوما، لكن قولنا: الموجود يصح أن\r__________________\r1 ـ الوجوب: نسخ، الواجب: ت، حصة: ا ت ج لب م، خاصة: ق.\r2 ـ وتكون: ا ت ف ق ك لب، فتكون: ي، الوحدة: نسخ، الواحدة: ت ل.\r3 ـ واحدة: ق م ج، وحدة وحدة: ت: ت ك.\r4 ـ وهي ست: ق ك ي ستة: ل، ـ: ت ف لب م.\r5 ـ مسئلة: ت ج ف ك م، ا: ق ل، ـ: ا.\r6 ـ الممكن: ا ت ج ف ك لب ي، الممكن لذاته: م ل.\r7 ـ هو (1): ا ت ف ج ق ك لب ي ل، ـ: م.\r8 ـ احدها: ت ج ق ك ل ي، ا: ا، الاول: ف لب م.\r9 ـ او غيره: ت ج ف ق لب م ي، او غير كونه سوادا: ا، واما ان يكون غيره: ك.\r10 ـ وان: ت ق ك لب ي، ويصح ان: م، او: ف، جار: ف فقط، قولنا: ت ج ف لب ي، قولك: ا ق ك، الموجود: ا ت ج ف ق ل ك لب ي، الوجود: م.\r11 ـ الموجود: ا ت ج ف ق ك ل لب ي، ـ: م."], [186, "يكون موجودا باطل، لأن الموجود الّذي جعلناه موضوعا، والّذي جعلناه محمولا، إن كان واحدا، كان ذلك إضافة الشيء إلى نفسه بالإمكان، وهو محال وإن لم يكن واحدا يلزم كون الشيء الواحد موجودا مرتين.\rواما قولنا: الموجود يصح أن يكون معدوما، فباطل أيضا، لأنه متى حكم على أمر بأنه يصح اتصافه بأمر آخر، فذلك يستدعى امكان تقرر الموصوف مع الوصف. والموجودية لا يعقل تقررها مع المعدومية، فيستحيل أن يكون المحكوم عليه بصحة العدم نفس الموجود.\rواما إن كان الحق هو الثانى، كان قولنا: السواد يمكن أن يكون موجودا، يرجع حاصله إلى أن المعدوم يمكن أن يصير موصوفا\r__________________\r1 ـ الموجود الذي جعلناه موضوعا و ـ: ت فقط. الذي (2): نسخ، الموجود الذي: ل.\r2 ـ الشيء: ا ت ج ف ق ك لب ل ي، للشيء: م.\r3 ـ وان لم يكن واحدا: نسخ ج ف ق، وان كان غيره: ق ك ل، الواحد: نسخ، ـ: ت.\r5 ـ و: ت ج ق ك لب م ي، ـ: ف، فباطل: ت م، باطل: ف.\r6 ـ مني: ت ج ق ك، اذا: م، على امر: ت ج قل ك لب م ي، بامر: ف.\r7 ـ تقرير: ك فقط.\r8 ـ الممدومية: ت م، العدم: ق. بصحة: ت ج ف ق ك ل لب م، لصحة: ا ي.\r9 ـ الوجود: ل.\r10 ـ يمكن: ت ق ك لب م ي، ممكن: ب، يكون: نسخ ف ل، بصير: ت ج.\r11 ـ حاصلة: ل ف م، ـ: ت فقط.\r1/ 187 ـ بالوجود: ت ج ل ق م، بالوجوجية: ك. مقرر: ا ت ف ك"], [187, "بالوجود وذلك محال على ما تقرر. ولأنه، إذا كان الوجود غير الماهية، فالموصوف بالإمكان، إما الوجود واما الماهية.\rواما موصوفية الماهية بالوجود. وأى واحد من هذه الثلاثة، فرض الإمكان وصفا له، فذلك الموصوف بالامكان اما أن يكون مفردا أو مركبا فإن كان مفردا كان الحكم عليه بالامكان يرجع إلى أن تلك الماهية المفردة يمكن أن تكون تلك الماهية، ويمكن أن لا يكون فيعود إلى التقسيم الأول الّذي أبطلناه.\rوان كان مركبا عاد الكلام فى أن الإمكان صفة لكل واحد من أجزائه أو لبعض أجزائه على ما تقدم.\rوثانيها: أن المحكوم عليه بالإمكان اما أن يكون موجودا، أو معدوما. فان كان موجودا فهو حال الوجود لا يقبل العدم، لاستحالة الجمع بين الوجود والعدم وإذا امتنع حصول العدم، امتنع حصول\r__________________\rلب ل ي، تقدم: ق ج م، اذا: نسخ، ان: ت ج.\r1، 9 ـ ولانه ... اجزائه على ما تقدم ـ: ج: ا ج ت م، ـ: لب ي ل.\r4 ـ فرض الامكان وصفا له: ت ج ك م، فالامكان صفة له: ف، للامكان وصفا له: ق. الموصوف بالامكان: نسخ، ـ: ت ج.\r5 ـ فان كان مفردا: ا ت ج ف ق ك، ـ م.\r6 ـ ان (1): ا ج ف ق، ـ: ت ك م، يمكن ان تكون: ا ف ج ق ك، يمكن ان: ت، لكان معنى الحكم عليها بالامكان ان تلك الماهية المفردة يمكن ان تكون: م، لا ـ: ك فقط.\r7 ـ فيميد: في ك فقط، التقسيم: ت م، القسم: ا ق ف. ابطلناه: ت ج ق ك م، احصيناه: ا ف.\r8 ـ في ان م ج، هل: ت، هل هو: ج.\r9 ـ على ما تقدم: م، الى ان: ك،: ا ت ج.\r10 ـ وثانيها: ت ج ق ك لب م ي، ب: ا، الثاني: ف. عليه: ف فقط.\r10، 11 ـ او معدوما ... موجودا: ف فقط.\r12 ـ في: ا ف: العدم والوجود."], [188, "إمكان العدم والوجود. وإن كان معدوما، فهو حال العدم لا يقبل الوجود، فلا يحصل إمكان الوجود والعدم. وإذا استحال الخلو عن العدم والوجود، وكان كل واحد منهما منافيا للإمكان كان القول بالإمكان محالا.\rويمكن تقرير هذا السؤال من وجه آخر: وهو أن الممكن إما أن يكون قد حضر معه سبب وجوده، أو لم يحضر. وبالتقدير الأول يجب، وبالتقدير الثانى يمتنع، فيكون القول بالامكان ممتنعا.\rوثالثها: وهو أن الشيء لو كان ممكنا، لكان إمكانه إما أن يكون وصفا عدميا أو وجوديا.\rوالأول باطل، لأنه نقيض اللاإمكان الّذي يصح حمله على المعدوم. والمحمول على المعدوم معدوم، فيكون اللاإمكان عدميا، فيكون الإمكان ثبوتيا ضرورة كون أحد النقيضين وجوديا.\r__________________\r1 ـ العدم والوجود: ا ت ج ف، الوجود والعدم: ق لب ل م ي.\r2 ـ الوجود والعدم: ت م، العدم والوجود معا: لب: ا ج ف ق ك لب ل ي.\r3 ـ العدم والوجود معا: لب: ا ت ف ق ك لب ل ي. الوجود والعدم: م، كان (2): فكان: ف فقط.\r5 ـ ويمكن: ت ف ق ك لب م ي، فيمكن: ا.\r8 ـ وثالثها: ت ج ق ك لب م ي. الثالث: ف، ج: ا.\r8، 9 ـ ان يكون وصفا عدميا او وجوديا: نسخ، وسفا نيوبسا او عدميا: ت ج.\r10 ـ الاول: ا ل م، الثاني: ت ج، الامكان: ت ج ق ك لب ج، للامكان: م، الامكان: ت ج ق ك لب ج للامكان: م، اللامكان: ل ف، الا امكان: ي، يصح: نسخ، يمكن: ت ج.\r11 ـ المعدوم (1): نسخ، العدم: ك، فيكون اللاامكان امتناع الامكان: ك، اللامكان: ف لب ي عدميا معدوما: ت لب: ا ت ف ق ك لب ج ي، ـ: ل م."], [189, "والثانى: باطل لأنه لو كان ثبوتيا لزم المحال من وجهين:\rأحدهما هو إنه إذا كان ثبوتيا كان مساويا لسائر الموجودات فى أصل الثبوت، ومخالفا لها فى خصوصية ماهيته المسماة بالإمكان، فيكون ثبوته زائدا على ماهيته، فاتصاف ماهيته بوجوده إن كان واجبا لذاته، كان الإمكان موجودا واجبا لذاته وهو صفة للممكن. والموصوف بالوجود موجود، فالممكن موجود، ووجوده شرط لقيام ذلك الإمكان به. وما كان شرطا لوجود ما، كان واجبا لذاته، كان أولى بأن يكون واجبا لذاته. فالممكن لذاته واجب لذاته، هذا خلف.\rوأما إن كان اتصاف ماهيته بوجوده على سبيل الإمكان، كان للامكان إمكان آخر ولزم أن يكون إمكان الامكان زائدا عليه، ولزم التسلسل.\rوثانيهما: ان المحدث قبل وجوده ممكن لذاته، فلو كان الإمكان صفة موجودة، لكان الشيء حال عدمه موصوفا بصفة موجودة،\r__________________\r1 ـ الثاني: ا ل م، الاول: ت ج، نيوتيا: ت ج لب ل م ن، وجود يا: ا ف ق ك.\r2 ـ احدهما: ت ق ك لب ل ي، الاول: ف م، ا: ا، هو: ت،: نسخ.\r3 ـ ماهينه: ق ك م ي، ماهية: ت ف، الماهية: لب.\r5 ـ موجودا واجبا لذاته: ا ف ل، فسفة موجودة واجبة لذاتها. ت ج. للممكن: ا ق لب ي، الممكن: ت ج ك م.\r6 ـ بالوجود: ا ف م، بالموجود: ت ج ق ك لب ي ل.\r8 ـ بان: ت ك، ان: ل م.\r11 ـ امكان اخر ولزم ان يكون: ا لب م، امنان زائدا زائد ج ل: ت ج ف ك ي، امكان اخر زائدا: ف، يلزم: ت ج. امكان الامكان: ا ق لب م، ولزم (2): ويلزم: ج فقط.\r12 ـ وثانيهما: ق ج لب ل، وثانيها: ت ي ك، والثاني: م، الثاني: ف، ب: ا.\r14 ـ موصوفا: نسخ، موصوف: ت."], [190, "وذلك محال.\rلا يقال: الجواب عن الإشكال الأول ان ذلك إنما يتوجه على من يقول الشيء حال وجوده ممكن الوجود، أو حال عدمه ممكن العدم. أما من يقول: الشيء حال وجوده يمكن أن يصير معدوما فى الزمان الثانى، لا يلزمه ذلك الإشكال.\rوعن الثانى أنه لا يلزم من صدق قولنا: الماهية بشرط كونها موجودة غير قابلة للعدم، صدق قولنا: الماهية التى هى أحد أجزاء ذلك المجموع غير قابلة للعدم.\rوعن الثالث أن الإمكان وصف ثابت فى الذهن لا تحقق له فى الخارج. وعلى هذا التقدير لا يلزم ما ذكرتموه لأنا نجيب عن الأول من وجهين:\rأحدهما أن القول بالإمكان الاستقبالى محال، لأنا إذا حكمنا على الموجود فى الحال، بأنه يمكن أن يعدم فى الاستقبال فإما أن يقال إمكان العدم الاستقبالى حاصل فى الحال، أو يقال إمكان العدم\r__________________\r4 ـ الشيء: ا ت ف ق ك لب ج ل ي،: م، يمكن: نسخ، ممكن: ت.\r5 ـ لا يلزمه: ج ف ك م، منه لا يلزمه: ق ي، عنه لا يلزم: ت، يلزم: لب، منه لا يلزم منه: ل. ذلك: ت ج ق لب ل ي، هذا: م، ـ: ف.\r8 ـ قابلة: ت ج ق ك لب م ي، قابل: ا ف ل.\r10 ـ لا يلزمه: ق فقط. ما: ت ق ج م، منه ما: ف لب ي، فيه ما: ك، ذكرتموه: ت ك ج لب ل ي، ذكرت: ا ف ق، ذكرتم: م.\r12 ـ احدهما: ت ج ف ق ك ل لب، الابول: م، ا: ا.\r13 ـ يعدم: نسخ، ينعدم: ت ج.\r14 ـ امكان العدم الاستقبالي (2): ت ل ج ك م ي ق لب، انه: ا ف."], [191, "الاستقبالى، لا يحصل إلا عند حضور الاستقبال. أما الأول فمحال، لأن العدم فى الاستقبال من حيث أنه فى الاستقبال موقوف على حصول الاستقبال، وحصول الاستقبال محال فى الحال. فحصول العدم الاستقبالى من حيث إنه عدم استقبالى موقوف على حضور شرط محال. والموقوف على المحال محال، فالعدم الاستقبالى ممتنع الحضور فى الحال وإذا استحال حصول العدم الاستقبالى فى الحال، بل لا يمكن حصوله إلا فى الاستقبال، كان إمكان حصوله حاصلا فى الاستقبال لا فى الحال.\rفإن قلت: إنه، وإن كان بهذا الشرط ممتنع الحصول فى الحال، لكنه غير ممتنع فى الاستقبال. ونحن إنما أثبتنا هذا الإمكان بالنسبة إلى الاستقبال.\rقلت: الإمكان ماهيته نسبية إضافية. والأمور النسبية لا يتحقق إلا عند تحقق المنتسبين فإذا استحال اجتماع هذين المنتسبين استحال تحقق هذه النسبة.\r__________________\r1 ـ عند حضور: ت ج ل، عند: ف (ق هامش)، في: ا ق ك لب م ي، اما ... فمحال: ت ج، و ... محال: ا ق ل م.\r4 ـ الاستقبالي: ت ف ل ك م ق، للاستقبال: ي، حضور: ت ج م ل، حصول: ف.\r5 ـ فالعدم: ت م ق، والعدم: ك، ممتنع: نسخ، محال: ت ج.\r6 ـ الحضور: ت ف ج ك ل لب، حضورة: م، الحصول: ق ي، حصول: ا م ف، حضور: ت ك ي ج ل لب.\r7 ـ بل: ا ت ف ج ق ك لب ي ل، ـ: م، امكان حصوله: ف ق م ت ي، فكان امكانه: ل.\r9 ـ بهذا: ت ق م ج ا ف، هذا: ك.\r12 ـ قلت: ف ت م ك ي ق، قلنا: ل.\r12، 14 ـ ماهينة نسبية .. تحقق هذه النسبة: ا ف ك، نسبة والنسبة لا توجد الا بعد وجود المننسبين فالامكان بالنسبة الى الاستقبال لا يوجد لا محصل: ل ق ي الا عند وجود: ج م ت، حصول:"], [192, "وأما الثانى: وهو أن يقال: إمكان العدم الاستقبالى لا يحصل إلا عند حضور الاستقبال، كان ذلك حكما بالامكان على الشيء بالنسبة إلى زمانه الحاضر، لأن الاستقبال عند حضوره يصير حالا وحينئذ يعود أول الإشكال.\rسلمنا الإمكان الاستقبالى لكن الإشكال المذكور لا يندفع لأن قولنا إنه فى الحال يمكن أن يصير معدوما فى الاستقبال يقتضي إمكان صيرورة هويته محكوما عليها بالعدم. فلو كانت هويته، عين الوجود، لكان ذلك حكما باتصاف الوجود بالعدم فيعود الإشكال المذكور.\rوعن السؤال الثانى أن شرط كون الشيء قابلا للشىء كون القابل خاليا عما ينافى المقبول. فإذا كان وجود الماهية وعدمها ينافيان الإمكان، والماهية لا تخلو عنهما فقد امتنع خلوها عما ينافى الامكان فيمتنع اتصافها بالإمكان.\rوعن السؤال الثالث أن حكم الذهن بالإمكان اما أن يكون\r__________________\rل الاستقبال كان ذلك: لب محصوله: محصوره: ل في الحال بالحال: م محال: ت ق لب م ي ج ل.\r1 ـ وهو: ت ج م، وهو اما: ك.\r2 ـ كان فكان: ل، فيكون: ق ذلك حكما: ا ل ف ق ك لب ي، فذلك حكم: ت ج: فهو محال ايضا اذ كان ذلك حكما: م.\r3 ـ زمانه: ت ق م، زمان: ك.\r5 ـ سلمنا: ا ف، وان سلمنا: ل، الثاني وان سلمنا: ك ل م ي، الثاني ان سلمنا: ت ج ق.\r7 ـ صبرورة: ت ف ج ق لب م ك ي، صبرورية: ا. فلو: ت ج ل ق ك، ولو: م.\r8 ـ باتصاف: ت ك ل ا ج ق، باتصال: م.\r9 ـ الشيء ا ت ج ل، لشيء: ق ك لب م ي.\r10 ـ اذا نسخ، واذا: ت ج.\r11 ـ منهما: ت لب ك م ق، عنها: ا ف ي، فقد امتنع: ا م ت، فالماهية يمتنع: ق.\r13 ـ السؤال الثالث: ت ف ل ق ي ج ك ل، الثالث: م."], [193, "مطابقا للمحكوم عليه، أو لا يكون. فإن لم يكن مطابقا، كان جهلا. وكان حاصله أن الذهن حكم بالإمكان على ما ليس فى نفسه ممكنا، وإن كان مطابقا كان الشيء فى نفسه ممكنا فيعود الإشكال المذكور فى انه ثبوتى أو عدمى.\rولأن إمكان الشيء وصف للشىء والذهنى شيء آخر مغاير للشىء المحكوم عليه بالإمكان، ووصف الشيء يستحيل قيامه بغير ذلك الشيء إلا أن يقال: المراد من قولنا: إمكان الشيء أمر حاصل فى الذهن. ان العلم بالإمكان حاصل فى الذهن. وهذا حق، ولكنه لا يندفع السؤال لأن البحث واقع عن نفس الإمكان لا عن العلم بالإمكان.\rوالجواب إن كون الماهيات المتغيرة ممكنا أمر ضرورى، والتشكيك فى الضروريات لا يستحق الجواب كما فى شبه السوفسطائية.\rمسئلة (ب):\rالممكن لا يوجد ولا يعدم إلا بسبب منفصل، لأنهما لما استويا\r__________________\r1 ـ للمحكوم عليه: نسخ، الخارج: ج، او: و: ت.\r2 ـ وكان: ا م، اذا كان: ت، اذا: ج.\r3 ـ في: م، من: ق ت ج.\r4 ـ في: م، من: ق ت ج.\r5 ـ للشيء (1): ف ل م، الشيء: ا ق. الدهني: م، الذهن: ا ف ق ل، للشيء (2): م، الشيء: ق.\r5، 6 ـ ولا امكان ... بالامكان: ا ف ل ق ج في الهامش، ـ: ت ي ك ل.\r7 ـ ان: م، ـ: ا ج ف ل ت.\r8 ـ و (2): ف، ـ: ل م ق، يندفع: ا ف م، بدفع: ل ق.\r10 ـ ممكنا: ا ت، ممكن: ف، ممنة: ج م ل، امر: ا ت ف ج ق ك لب ل ي، لامر: م.\r11 ـ النسبة: نسخ، الشبهة: ت.\rمسئلة: ت م، ب: ا ق ك ل ي، في مسئلة الثانية ان: ف.\r13 ـ الممكن: نسخ، انه: ت."], [194, "بالنسبة إليه، استحال الترجيح من غير مرجح.\rفإن قيل قولك: لما استويا امتنع الترجيح، إلا لمرجح ان ادعيت أنه بديهى فهو ممنوع. فإنا لما عرضنا هذه القضية على العقل، مع قولنا: الواحد نصف الاثنين، وجدنا الثانية أظهر. والتفاوت يدل على تطرق الاحتمال بوجه ما، إلى الأول وعند قيام احتمال النقيض لا يبقى اليقين التام.\rفإن ادعيت أنه برهانى فأين البرهان؟.\rسلمنا صحة ما ذكرته لكنه معارض بأمور:\rأولها: لو افتقر الممكن إلى المؤثر لكانت مؤثرية المؤثر فى ذلك الأثر، إما أن تكون وصفا ثبوتيا أو لا تكون. والقسمان باطلان. فالقول بالمؤثرية باطل.\rوإنما قلنا إنه يستحيل أن يكون وصفا ثبوتيا لأن ثبوته اما فى\r__________________\r1 ـ اليه: ت م، الى الماهية: ق. الترجيح: ت ف ق لب م، الترجح: ك ي، من غير مرجح: ت ج، الا بسبب لسبب: ل لب منفصل: ف ل، الا لمنفصل: ق م، بمنفصل: لب ي، بالمنفصل: ك.\r2 ـ فان: ت ج م ف ل، او ان: ك. قولك: ت ج ل ق ك، قولكم: م ف. لما: ت ج ق ك لب م ي، لو: ف، امتنع نسخ، بمتنع: ت ج، الترجيح: ت ج ف ق م، الترجيح: ا ك ي.\r3 ـ انه: ت ف ج ق ك لب ي، انه امر: م.\r5 ـ تطرق: ت ج م، طريق: ف.\r7 ـ فان: نسخ، وان: ت ف ك ج ل.\r8 ـ ذكرته: ف ق ك ل م ي، ذكرتم و: لب: ت لب ج.\r9 ـ المؤثر (1): نسخ، مؤثر: ك.\r12 ـ و: ج ل ت فقط. انه: ت ج ق ك لب م، انها: ا ف، وصغا: ا ف ك لب ي، ـ: ت ق م."], [195, "الذهن فقط، أو فيه وفى الخارج. والأول باطل، لأن الّذي وجد فى الذهن، و. لا يكون مطابقا للخارج فهو جهل، كمن أعتقد أن العالم قديم مع أنه لا يكون فى نفسه كذلك. فلو كان حكم الذهن بالمؤثرية غير مطابق للخارج، كان ذلك الحكم جهلا. فلا يكون الشيء مؤثرا فى نفسه. ولأن كون الشيء مؤثرا فى غيره صفة لذلك الشيء، فكانت حاصلة قبل الأذهان، وصفة الشيء يستحيل قيامه بغيره، إلا أن يقال: الموجود فى الذهن، هو العلم بالمؤثرية، لكن ذلك لا يفيد، كما تقدم.\rأما الثانى وهو أن يكون له ثبوت فى الخارج، فهو اما أن يكون نفس المؤثر أو الاثر، أو أمرا مغايرا لهما. والأول باطل. لأنا قد نعلم ذات المؤثر، وذات الأثر مع الشك فى كون ذلك المؤثر مؤثرا فى ذلك الأثر.\rكما إذا علمنا العالم، وعلمنا قدرة الله تعالى، ولكن لا نعلم أن\r__________________\r1 ـ فيه و: نسخ، في: ت. و (1): ـ ت ك، و (2): ف.\r2 ـ فهو: ت ج فقط، ان: ت ج ف م،: ق لب ل ي.\r3 ـ قديم: ت ج ف م، قديما: ق لب ل م، في نفسه: نقدم على لا يكون في: ت ج.\r4 ـ مؤثرا: تقدم على في نفسه في: ا ق ك.\r5 ـ لان كون: م، لا يكون: ق، غيره: ق م، غير: ك الشيء (2): ك، فكانت: ا ف، وكانت: ق ك م.\r6 ـ الاذهان: ق م، في الاذهان: ك، قيامه: م، قيامها: ت ج، بغيرها: ف، الا ان: م ج، الان: ك.\r7 ـ الموجود: ف ج ق م، الموجودية: ا، المؤثرية: ا ف ق ج ك لب، المؤثر: م، ذلك: ي.\r5، 7 ـ ولان ... كما تقدم: ت ل لب ي.\r8 ـ اما: ا ت ف ق ك لب، واما: ج م ي.\r9 ـ لو: ك، و: ت م. امرا مغايرا لهما: ك، امرا زائدا عليها: ي، امرا اخر: ت ج، امرا زائدا: ق ل لب، اما مغايرا لهما: ا ف.\r10 ـ ذات (2): ت فقط، ذلك: ت ج فقط.\r12 ـ كما: نسخ، كما انا: ق، علمنا (2) ك، وعلمنا قدره"], [196, "المؤثر فيه قدرة الله تعالى إلا ببرهان منفصل على نفى الواسطة والمعلوم مغاير للمجهول. فإذن مؤثرية قدرة الله تعالى فى العالم ليست نفس قدرته، ولأن مؤثرية القدرة فى الأثر نسبة بينهما والنسبة بين الشيئين متوقفة على وجود المنتسبين. والمتوقف على الشيء مغاير له.\rوأما إن كانت المؤثرية أمرا زائدا، فهو إما أن يكون من العوارض العارضة لذات المؤثر، وإما أن لا يكون كذلك، بل يكون موجودا قائما بنفسه.\rوإن كان الأول، كان ممكنا لذاته مفتقرا إلى المؤثر فمؤثرية المؤثر فيه زائدة عليه، ولزم التسلسل، وهو محال.\rوبتقدير تسليمه، فالمحال لازم من وجه آخر، لأن التسلسل إنما يعقل إن لو فرضنا أمورا متتالية إلى غير النهاية. وذلك يستدعى\r__________________\rالله: ت، تعالى: ا ج ق ف ل لب ت، سبحانه وتعالى: ك. و (2): ت م،: ا ف ق ك لب، لكن لا: نسخ، لكنا: ل ف، لكنا لا: ق، لكنا لا يمكنا: ك.\r1 ـ تعالى: ت ف ق لب ي، سبحانه وتعالى: ك،: م. على نفى الواسطة: ا ف ك لب،: ت ق ي م.\r2 ـ ولان: ا ت ج ف ق ك لب ي، ولان: م، تعالى: ا فقط.\r3 ـ و (1): ك، مؤثر به الصدرة: ت ق لب ل ي، مؤثرية الشيء ج م، مؤثر الشيء: ف.\r4 ـ متوقفة: ا ج ت ف ق ل لب ي، تتوقف: م، وجود المنتسبين: ت ج ق لب م ي، وجودهما: ا ف ك.\r5 ـ اما: ت ج فقط، ان (1): ت ق م، اذا: ك.\r6 ـ واما ان: نسخ، او: ت كذا: ك موجودا: ت ق ك، موجود: م.\r7 ـ بعد «فانما بنفسه» لان كونه عارضا لشيء آخر غمسير معقول: ت ج ف لب ل ي.\r8 ـ فان: ا ت ج ف ق لب ل، وان: م ي."], [197, "كون كل واحد منها متلوا بصاحبه وإنما يكون متلوا بصاحبه لو لم تكن بينه وبين متلوه غيره لكن ذلك محال. لأن تأثير المتلو فى التالى متوسط بينهما، وقد كان لا متوسط، هذا خلف.\rوإن كانت المؤثرية جوهرا قائما بذاته، فهو محال. لأن مؤثرية الشيء فى الأثر نسبه بين المؤثر والأثر، والنسبة بين الشيئين لا يعقل أن يكون جوهرا قائما بنفسه ثم على تقدير التسليم، فالمؤثر فى وجود هذا الممكن اما هذا الجوهر، أو ذلك، أو هما.\rوعلى التقديرات يكون مؤثرية الذات المؤثرة فى وجود الممكن زائدة عليه ولزم التسلسل. وإنما قلنا إنه لا يجوز أن يكون المؤثرية صفة عدمية، لأنها نقيض اللامؤثرية التى يصح حملها على العدم والمحمول على العدم عدم، ونقيض العدم ثبوت فالمؤثرية أمر ثبوتى، ولأن الشيء\r__________________\r1 ـ منها: ت، منهما: ك، نسخ. وانما يكون متلوا بصاحبه لصاحبه: ت ج: ا ت ج ف ك لب ل ي،: ق م.\r3 ـ متوسط: ا ت ف ج ق ك لب ي، متوسط: ل، متوسطا: م، هذا: نسخ، وهذا: ي.\r4 ـ بذاته: ل ق م، بنفسه: ت ك ج.\r5 ـ الاثر (1): م، الشيء: ت. بين المؤثر والاثر: ا ف ق ك لب ل، بين الاثر والمؤثر: م، بينهما: ت ج.\r6 ـ بنفسه ثم: ت ف ج ق ك ي بين السطور في ف. بالنفس: ف لب م، على تقدير: نسخ، بتقير: ت ج. التسليم: نسخ، تسليمه: ت ج فالمؤثر: ت ج ف ق ك م، المؤثر: ا ل.\r6، 7 ـ وجود هذا: ت ج فقط.\r7 ـ اما: ت ج ف ق،: ك لب م ي، اذ ذلك: ا ت ج ل، او ذاك: ف ك م، وذلك: ق.\rالذات: ا ت ج ف ق لب ي، ذات: ك م، المؤثر: ك فقط. زائدة: ت ف ج م ي، زائدا: ا ق ك لب ل.\rللمؤثر به: ك، حملها: جاء بعد العدم في: ك.\r10، 11 ـ والمحمول على .. عدم: نسخ، معدوم: ت.\r11 ـ العدم (1): ق م، المعدوم: ك."], [198, "الّذي لم يكن مؤثرا فصار مؤثرا فالمؤثرية حصلت بعد أن لم تكن فهى صفة وجودية، وإلا فليجوز فيما إذا صارت الذات عالمة بعد أن لم تكن، أن لا يكون العلم أمرا وجوديا، وذلك نهاية الجهل. فظهر بما ذكرنا فساد كون المؤثرية صفة ثبوتية، وكونها صفة عدمية، فإذن القول بالمؤثرية باطل.\rوثانيها: أن المؤثر إما أن يؤثر فى الأثر حال وجود الأثر، أو حال عدمه. والأول باطل لاستحالة إيجاد الموجود.\rوالثانى باطل، لأن حال العدم لا أثر، ولا فلا تأثير. لأن التأثير ان كان عين حصول الأثر عن المؤثر، فحيث لا أثر فلا تأثير.\rوان كان مغايرا، فالكلام فيه، كالكلام فى الأول.\rوثالثها: أن المؤثر اما أن يكون تأثيره فى الماهية أو فى الوجود أو فى اتصاف الماهية بالوجود.\rوالأول محال، لأن كل ما بالغير يلزم عدمه عند عدم ذلك الغير. فلو كان كون السواد سوادا بالغير لزم أن لا يكون السواد سوادا\r__________________\r1 ـ الذي: ت م، اذا: ق. لم يكن: ا ت ج ف ق ك لب ي، لا يكون: م.\r2 ـ فهي: ت ي ج ك لب ل م ي، وهي: ا ف، فليجوز: ف ك م ي، فلنجوز: ت ج لب، فلنجو: ق.\r3 ـ امرا: ت فقط. الجهل له: نسخ، الجهل: ت ج، الجهالة: ل ف.\r6 ـ وثانيها: ت ج ق ك لب ل م ي، ب: ا ف.\r8 ـ اثر .. فلا تاثير: ا ت ج ف ق لب ل ي، اثر له ولا تاثير له: م.\r10 ـ فيه: ا ت ف ق ك لب، في ذلك: ي، فيها: م.\r11 ـ وثالثها: ت ج ق ك ل لب م ي، ج: ا ف، تاثيره: ـ ف فقط. الوجود: نسخ، الموجود: ت.\r14 ـ يلزم: ف."], [199, "عند عدم ذلك الغير، وهذا محال. لأن السواد يستحيل أن يصير غير سواد.\rلا يقال نحن لا نقول: السواد مع كونه سوادا يصير موصوفا بأنه ليس بسواد، بل نقول: يفنى السواد ولا يبقى. لأنا نقول: إذا قلنا: يفنى السواد. فهذه قضية، ولكل قضية موضوع ومحمول، لا محالة. والموضوع لا بد من تقرره حال الحكم بحصول ذلك المحمول له أو سلبه عنه.\rفإذا قلنا السواد فنى، فالموضوع هو السواد، والمحمول هو الفناء فلا بد وأن يكون السواد متقررا حال ذلك الفناء، وإن كان الفانى هو السواد لزم أن لا يكون السواد متقررا فى هذه الحالة، فيلزم عند صدق قولنا السواد معدوم، كون السواد متقررا وغير متقرر\r__________________\r1 ـ هذا نسخ، هو: ك، ان يصير: ق.\r2 ـ سواد: ا ت ف ق ج ك لب ي، السواد: م.\r3 ـ يصير: ت ل فقط.\r4 ـ يبقى: ا ت ج ف ق ك لب ل ي، ينفى: م.\r5 ـ لكل ... محمول: نسخ ج ل ف م، كل قضية محمول وموضع: ت.\r6 ـ تقريره: ل ي فقط.\r7 ـ له: ت ف ج ق ك لب ل ي،: م.\r8 ـ فالموضوع: نسخ، بالموضوع: ت، والمحمول هو الفناء: لب.\r9 ـ فلابد و: ت ج ق ك لب ل، ولا بد: ا ف، فلا بد: ل م ي، وان: ف لب م، فان: ت ج، فاذا: ي، فان: ق ك، الغاني: نسخ ج ف، القائي: ت.\r10 ـ لزم: ت ج ك ي، ايضا لزم: ف ق لب م، لا: م ق فقط، السواد (2): ك فقط. في هذه الحالة: ت ف ق ك لب م، حال ذلك الفناء: ي.\r9، 10 ـ حال ذلك الفناء ... منقررا: ل."], [200, "وذلك محال.\rوأما إن قيل: المؤثر أثر فى الوجود، فذلك محال، وإلا لزم أن لا يبقى الوجود وجودا عند فرض عدم ذلك التأثير وهو محال على ما مر.\rوأما الثالث: وهو أن يقال: المؤثر أثر فى موصوفية الماهية بالوجود، فنقول: أولا لا يجوز أن تكون موصوفية الماهية بالوجود أمرا وجوديا، لأنها بتقدير أن تكون أمرا وجوديا لم تكن جوهرا قائما بذاته بل تكون صفة للماهية فتكون موصوفية الماهية بها زائدة عليها، ولزم التسلسل.\rوإذا لم تكن الموصوفية أمرا ثبوتيا، استحال جعلها أثرا للمؤثر أصلا. ثم بتقدير أن تكون أمرا ثبوتيا استحال اسنادها إلى المؤثر. لأن المؤثر إما أن يؤثر فى ماهيته أو فى وجوده، ويعود التقسيم المقدم.\r__________________\r1 ـ وذلك محال: ت ج ف ق ل ك لب ي: م.\r2 ـ قيل: ف ق ك لب م: قبل: ا ت. اثرا: ا فقط. فذلك ت ق ك لب م ي، وذلك: ف.\r3 ـ فرض: ك.\r6 ـ لا: ق، فنقول ... بالوجود: ـ ا فقط.\r7 ـ امرا وجوديا: نسخ، موجودا: ت، وجوديا: ج، موجوده: ل.\r8 ـ بذاته: نسخ، بنفسه: ت ج، فتكون: ا ت ج ف ق ك لب ل ي، فيلزم: م. زائدا: ف، عليها: ا ت ج ف ق ك لب، عليه: م.\r10 ـ امرا: ت ف ق ك لب م، صفة: ج، امرا زائدا: ي. للمؤثر: ا ت ف لب ل ي، لمؤثر: ق ك، للمؤثر: م.\r11 ـ اصلا: ت ج ل فقط. اسنادها: ت ج ل ق ك، استنادها: م.\r12 ـ ان: لب، ماهيته .. وجوده: نسخ: ماهياتها .. وجودها او اتصاف الماهية بالوجود: ف.\r13 ـ المقدم: ا ت ق ك لب ي، المعدم: ف، المتقدم: ج م."], [201, "وإذا ثبت أنه لا يجوز إسناد الماهية والوجود، وانتساب أحدهما إلى الآخر، إلى المؤثر كانت الماهية الموصوفة بالوجود غنية عن المؤثر. فثبت أن القول بالتأثير باطل.\rورابعها: أنه لو افتقر ترجح أحد طرفى الممكن على الآخر إلى المرجح، لافتقر رجحان العدم على الوجود إلى مرجح، لكن ذلك محال. لأن المرجح مؤثر فى الترجيح، والمؤثر لا بد له من أثر. والعدم نفى محض، فيستحيل إسناده إلى المؤثر.\rفإن قلت علة العدم عدم العلة.\rقلت هذا خطأ لأن العلية مناقضة اللاعلية التى هى عدم والعلية ثبوتية فالموصوف بها ثابت. وإلا فالنفى المحض موصوف بالصفة الموجودة، وهو محال. ولأن العدم لا تميز فيه ولا تعدد ولا هوية فيستحيل جعل بعضه علة والبعض معلولا.\r__________________\r1 ـ اسناد: ت ج ل ف ق ك لب ي، استناد: م.\r2 ـ الماهية الموصوفة: ت ج ف ق ك ل لب ي، الموصوفية.\r4 ـ ورابعها: ت ج ق ك لب م ي، د: ا ف. ترجح: نسخ ل، ترجيح: ت ج.\r5 ـ مرجح: ا ت ج ف ك، المرجح: ق لب م ي.\r6 ـ محال: ت ق لب ج م ل ي، باطل: ا ف ك.\r7 ـ اسناده: ت ف ق لب م ي، اتناده: ا.\r9 ـ لان: ت ق ج ل، لانه: م. اللاعليه: ا ت لب، للا عليه: ف ق ج ك ل م ي. والعلية: ا ف ك، فالعلية: ت ج ق لب م ل ي.\r10 ـ فالموصوف: ت ج ق ك لب ل م ي، والموصوف: ا ف.\r10، 11 ـ فالتقى ... الموجود: ا ف ق ك، فالمعدوم موصوف بالموجود الموجود: لب ي: ت لب ج م ي، المعدوم موصوف بالوجود: ل.\r11 ـ تميز: ف ج ق ك لب م ي، يميز: ا ت. تعدد: ت ج ف ق ك لب ل م ي، يعدد: ا."], [202, "والجواب أن تلك القضية بديهية، والتفاوت بينها، وبين سائر البديهيات. فى العقل محال. وان حاولنا البرهان قلنا: الممكن ما لم يجب لم يوجد. وذلك الوجوب لما حصل بعد أن لم يكن كان وصفا وجوديا، فيستدعى موصوفا موجودا وليس هو ذلك الممكن، لأنه قبل وجوده معدوم. فلا بد من شيء آخر يعرض له الوجوب بالنسبة إلى هذا الممكن وذلك هو المؤثر.\rأما المعارضة الأولى، فمدفوعة لأن ذلك التقسيم قد يتوجه فيما يعلم وجوده بالضرورة، كما إذا قيل: لو كنت أنا موجودا فى هذه الساعة، لكان كونى فيها اما أن يكون عدميا وهو محال، لأنه نقيض اللاكون فيها، وهو عدمى ونقيض العدم ثبوت، أو يكون ثبوتيا وهو إما عين الذات، فيلزم أن لا تبقى الذات عند ما لا يبقى حصوله فى تلك الساعة، أو زائدا عليه، فيكون ذلك الزائد حاصلا فى تلك الساعة، ولزم التسلسل.\r__________________\r1 ـ بينها: ت ج ف ق ك لب م ي، بينهما: ا، سائر: ق.\r2 ـ في العقل محال: ا ت ج ف ق ك لب ي، محال في العقل: م.\r4 ـ فيندعي: ا ت ف ق ك ج لب ل ي، ويستدعى: م. موصوفا: ت ف ج ك لب م ي، وصفا: ف، موجودا: ا فقط، هو ذلك: نسخ ل ف، ذلك هو: ت ج.\r5 ـ له الوجوب: ا ت ج ف ق ك ل ي، ذلك الوجوب له: لب م.\r6 ـ هذا: ا ت ج ف ق ك ل، ذلك: م. المؤثر: ت ج ف ق ل، الاثر: م.\r7 ـ فمندفعة: ي.\r8 ـ اذا قيل: ا ف ق ك ل لب ي، يقول: ت، تقول: ج، او قيل: م.\r9 ـ فيها اما ان يكون: نسخ ف م، في هذه الساعة اما ان يكون: ل: ت ج ل.\r10 ـ نقيض اللاكون: نسخ ف ج ل، اللاكون: ف."], [203, "ولما كان حصوله فى هذه الساعة يفضى إلى هذه الأقسام الباطلة، وجب أن لا يكون له حصول فى هذه الساعة، فظهر أن هذا التقسيم مبطل للبديهيات.\rأما المعارضة الثانية، فهى كذلك أيضا لأن الاحداث، وإن كان فى محل البحث، ولكن لا نزاع فى الحدوث. والتقسيم الّذي ذكرتموه يدفعه، لأنه يقال إن حدث هذا الصوت مثلا، فاما أن يكون حدوثه حال وجوده أو حال عدمه فإن حدث حال وجوده، فقد وجد الموجود. وان حدث حال عدمه، فقد وجد عند عدمه، فظهر أن هذا التقسيم مبطل للضروريات.\rأما المعارضة الثالثة، فهى أيضا كذلك، لأنه يقال: لو حدث هذا الصوت لكان الحادث، إما الماهية، أو الوجود أو موصوفية الماهية بالوجود. فإن كان الأول فقد انقلب ما ليس بصوت صوتا.\rوإن كان الثانى فقد انقلب ما ليس بوجود وجودا، وكذا الثالث\r__________________\r1 ـ يقضى: ت ج ق ك لب م ي، يقتضي: في، هذه (2): ت جمع: تلك: ف.\r4 ـ اما: ا ت ف ق ك ج، واما: لب م ي. لان الاحداث وان: ا ت ج ف ق ك ل لب ي، لانه احداث فان: م.\r5 ـ في: ف فقط. و (1): ت ج ل. الحدوث: ت م، الحدث: ق.\r6 ـ بدفعه: ق م ج ل، يرفعه: ت، يندفع: ك.\r7 ـ وجوده او حال عدمه: نسخ ل ف م، عدمه او حال وجوده: ت ج فان حدث: ا ف ق ك لب ي، فان كان حدوثه: ت ج، فانه حدث: م وجوده (2): ا ت ج ف ق ك لب ي، عدمه ووجوده: م.\r9 ـ للضروريات: ا ت ف ج ق ك لب ي، لضروريات: م.\r10 ـ اما: ا ت ج ف ق ك، واما: لب ل م ي. فهو: ق، لو: ا ت ج ف ق ك لب ي، له ان: م.\r11 ـ موصوفيه: نسخ ل ف ك، موصوفة: ي، اتصافه: ج.\r12 ـ ماليس بصوت صوتا ... انقلب: ف فقط.\r13 ـ بوجود وجودا: ج ت ق لب ل م ي، بموجود موجودا: ا"], [204, "فثبت بطلان هذه الأقسام الثلاثة فظهر أن هذا التقسيم مبطل للبديهيات.\rوهنا إشكال: وهو أن للقادحين فى البديهيات أن يقولوا لما عجزتم عن القدح فى مقدمات هذا التقسيم، مع انكم علمتم أن نتيجته باطلة لزم منه تطرق القدح إلى البديهيات.\rوأما المعارضة الرابعة، فمدفوعة لأن العدم نفى محض، فيستحيل وصفه بالرجحان فلا جرم لا يفتقر إلى المرجح.\rمسئلة (ج):\rالممكن لذاته لا يجوز أن يكون أحد الطرفين أولى به. لأنه مع تلك الأولوية، اما أن يمكن طريان الطرف الآخر، أو لا يمكن فإن أمكن فإما أن يكون طريانه لسبب، أو لا لسبب فإن كان لسبب، لم تكن تلك الأولوية كافية فى بقاء الطرف الراجح، بل لا بد معها\r__________________\rف ك.\r1 ـ فثبت بطلان هذه الانسام الثلاثة فظهر: ج، باطل بعين ما ذكرتم من الانسام: ق، فظهر والثلاثة باطلة بعين ما ذكرتم من الاقسام فظهر: ت.\r3 ـ .. هنا: ت ج ف لب م ي، ههنا: ا ق ك. الفادحين: ف.\r4 ـ النتيجة: ي.\r5 ـ الى: ت ق م، في: ك.\r6 ـ اما: ا ت ج ق ك لب، واما: ف م.\r7 ـ المرجح: ت ج ف ق ك لب، مرجح: م ي.\r8 ـ مسئلة: ت ج ف ك لب م، ج: ق ي ل.\r9 ـ الطرفين اللازمين: ق اولى به من الاخر: ق: ت ق ج ي، طرفيه اولى: به: ك من الاخر: م: لب م، الطرفين طرفين: ا به اولى: ا ف ك.\r11 ـ فاما: نسخ، واما: ت.\r12 ـ الاولوية: ت ج ف ق ك لب م ي، الاولية: ا، بقاء: ت ج ف ك ل لب م ي،: ا ف."], [205, "من عدم سبب الطرف المرجوح.\rوإن كان لا لسبب، فقد وقع الممكن المرجوح لا لعلة، وهذا محال. لأن أحد المتساوى أقوى من المرجوح. فلما امتنع الوقوع حال التساوى، فلأن يمتنع حال المرجوحية كان أولى وإن لم يمكن طريان المرجوح كان الراجح واجبا والمرجوح ممتنعا.\rمسئلة (د):\rرجحان الممكن لذاته مسبوق بوجوب، وملحوق بوجوب أما السابق، فلأنه ما لم يترجح صدوره عن المؤثر، على لا صدوره عنه، لم يوجد. وقد دللنا على أن الرجحان لا يحصل إلا مع الوجوب.\rوأما اللاحق، فلأن وجوده ينافى عدمه، فكان منافيا لإمكان عدمه، وكان مستلزما للوجوب. واعلم ان شيئا من الممكنات لا ينفك عن هذين الوجوبين لكنهما خارجان لا داخلان.\rمسئلة (ه):\r__________________\r2 ـ فان: ك فقط. المرجوح: ا ت ج ف ق ك ل لب ي، الموجود: م.\r3 ـ احد: ج ل. المتساوي: ا ت ف ك، المساوى: ق لب ج ل ي، التساويين: م.\r4 ـ فلان: ت ج م ي، فان: ا ق، فان: لب، يمنع: ا ق فقط.\r6 ـ مسئلة: ت ج ف ك لب م، د: ق ي ل.\r7 ـ بوجوب (1): ت ق ج ك لب م ي، لوجوب: ف.\r8 ـ لم: ت ج ف ق ك م ي، لا: لب.\r9 ـ الرجحان: ا ت ف ج ق ك ل لب ي، الراجح: م.\r12 ـ وكان: ا ت ق لب، فكان: ف ك م ج ي.\r14 ـ مسئلة: ت ف ق ك لب م، ة: ي."], [206, "علة الحاجة إلى المؤثر الامكان لما سبق لا الحدوث، لأن الحدوث كيفية لوجود الحادث فيكون متأخرا عنه، والوجود متأخر عن تأثير القادر فيه، المتأخر عن احتياج الممكن إليه، المتأخر عن علة الحاجة.\rفلو كانت العلة هى الحدوث لزم تأخر الشيء عن نفسه بمراتب احتجوا بأن علة الحاجة، لو كانت هى الإمكان، لزم احتياج العدم الممكن إلى المؤثر، وهو محال، لأن التأثير يستدعى حصول الأثر. والعدم نفى محض فلا يكون أثرا. جوابه: ما قيل أن علة العدم عدم العلة وفيه ما فيه.\rمسئلة (و):\rالممكن، حال بقائه لا يستغنى عن المؤثر، لأن علة الحاجة الإمكان والإمكان ضرورى اللزوم لماهية الممكن فهى أبدا محتاجة.\rلا يقال انه صار الوجود أولى به حال البقاء. لأنا نقول\r__________________\r1 ـ لما سبق: ا ف، على ما سبق: ق، منطوب في: ك،: ت ج لب ل م ي.\r2 ـ لوجود: ت ج ق لب، في وجود: ف ك ل م ي.\r3 ـ الحاجة: ت ج، احتياجه اليه: م ل، احتياجه: ف.\r4 ـ فلو: ت ك ل لب ج م ي، ولو: ا ف، تاخر: ا ت ج ف ق ك لب ي، تاخير: م.\r7 ـ محض ت ف ق ك م ي،: لب. جوابه: ا ت ج ف ق ك لب ي، والجواب: م.\r9 ـ مسئلة: ت ج ف ق ك لب ل م،: ي.\r11 ـ اللزوم: نسخ، يلزم: ق لماهية الممكن: ت ج ق لب ل م ي، للماهية الممكنة: ا ف ك، فهي: ت ج ق ك ل، وهي: نسخ ف.\r12 ـ صار ... البقاء: ت ج، حال البقاء صار اولى بالوجود: ا ف ق ك ل ي، حال البقاء اولى بالوجود: لب، حال البقاء اولى بالوجود وتبك الاولوية مانعه من احتياجه الى المؤثر: م."], [207, "هذه الأولوية المغنية عن المرجح، ان كانت حاصلة حالة الحدوث، وجب الاستغناء عن المؤثر، حال الحدوث، وان لم تكن حاصلة حالة الحدوث فهو أمر حدث حال البقاء، ولو لاه لما حصل الاستمرار. فالشيء حال استمراره، مفتقر إلى المرجح.\rاحتجوا بأن المؤثر حال بقاء الأثر، اما أن يكون له فيه تأثير أو لا يكون فإن كان له فيه تأثير، فذلك الأثر أما الوجود الّذي كان حاصلا، وهو محال. لأن تحصيل الحاصل محال. وان كان أمرا جديدا كان المؤثر مؤثرا فى الجديد، لا فى الباقى. وان لم يكن له فيه تأثير أصلا استحال أن يكون مؤثرا.\rوالجواب: أنا لا نعنى بالتأثير تحصيل أمر جديد، بل بقاء الأثر لبقاء المؤثر. وبالله التوفيق.\r__________________\r1 ـ المغنية: ت ج ل لب م ي، المستغنية: ا ف ك.\r2 ـ حالة حال: ف لب ل ج ي الحدوث وجب الاستغنا عن: ا ج ف ك لب ل ي، حال الحدوث لزم استفناء الممكن من: م، حال الحدويث: ق.\r2، 3 ـ ولن لم تكن .. حالة حال: ت ج ف لب ي الحدوث: ا ت ق ك لب ي، والا: م،: ق.\r3 ـ حدث: ا ج ت ق ك ل لب ي، حادث: م، احدث: ف.\r4 ـ فالشيء: ا ت ف ج ق ك ل لب، والشيء: م. استمراره: ت ف ق ك لب ي، استمرار: م. مفتقرا: ك فقط.\r5 ـ له فيه تاثير: ا ت ج ف ق ك لب ل ي، له اثر: م.\r6 ـ له اثر: م، له فيه فيه: ق تاثير: ت ج ل.\r7 ـ وان كان ذات ج ف ق ك لب ي، او: م.\r8 ـ كان: ا ت ف ق ك لب ي، فكان: م.\r9 ـ فيه تاثير: ا ج ت ف ق ك لب ل، اثر: م مؤثرا: ت ج، له فيه تاثير: م، له فيه اثر: ق ك لب ي ل.\r10 ـ و: ت ج ف فقط، انا: ت ج ق ك، انى: م،: ا ف لب ي.\r11 ـ وبالله التوفيق: ت،: نسخ."], [208, "تقسيم الموجودات على رأى المتكلمين\rالموجود إما أن يكون قديما، أو محدثا. أما القديم فهو الّذي لا أول لوجوده، وهو الله سبحانه وتعالى. والمحدث ما لوجوده أول، وهو ما عداه تعالى.\rقالت الفلاسفة مفهوم قولنا: كان الله تعالى موجودا فى الأزل. اما أن يكون عدميا، أو وجوديا. والأول باطل، وإلا لكان قولنا: ما كان موجودا فى الأزل ثبوتيا، فيكون المعدوم موصوفا بالوصف الوجودى، وهو محال فثبت أن ذلك المفهوم وجودى. وهو إما أن يكون عين ذات الله تعالى أو غيره. والأول محال، لأن كونه فى الأزل غير حاصل الآن، وإلا لكان الآن هو الأزل. فكل ما وجد الآن وجد فى الأزل، هذا خلف. وذاته حاصلة الآن فكونه فى الأزل أمر زائد على ذاته وذلك الأمر كان موجودا فى الأزل فقد كان فى الأزل مع الله تعالى غيره .. ثم ذلك الغير هو الّذي\r__________________\r2 ـ محدثا: ت ج ف لب ل ي، حادها: ق ك، حديث: م، الذي: ا ت ج ف ق ك لب ل ي،: م.\r3 ـ سبحانه و: م ك فقط.\r4 ـ تعالى: ا ت ق ج ي، تعالى كان و: ف: ك ل لب م.\r5 ـ تعالى: ت فقط. موجودا في الازل: ا ت ف ق ك لب ل ي، في الازل موجودا: م ج.\r6 ـ عدميا: ق، فالاول: ك فقط.\r9 ـ ذات: ا ت ف ج ق ك لب ي،: م، فالاول: ك فقط.\r10 ـ محال: ت ك لب ج م ي، باطل: ا ف ق، و: ت فقط، هو: نسخ، وهو: ت.\r11 ـ فكل: ا ت ج ف لب ك ي، وكل: ق ل م. و: ت ج ل، لكن: م ف، الان: ت م، في الحالين: ق.\r12 ـ امر زائد: ت ج ف ق ل لب م، امرا زائدا: ك ي.\r13 ـ فقد: ا ت ف ج ق ك لب ي، وقد: م، تعالى: ق ك م،: ا ت ف لب."], [209, "يلحقه معنى: كان ويكون لذاته وذلك هو الزمان، فالزمان موجود فى الأزل.\rقال المتكلمون: معنى كون الله تعالى قديما أنا لو قدرنا أزمنة لا أول لها، لكان الله تعالى موجودا معها بأسرها.\rومما تقرر ذلك إنه لو اعتبر الزمان فى ماهية الحدوث والقدم، لكان ذلك الزمان، إما أن يكون قديما أو حادثا. فان كان قديما مع إنه ليس له زمان آخر، فقد صار القدم معقولا من غير اعتبار الزمان وإذا عقل ذلك فى موضع، فليعقل ذلك فى كل موضع. وإن كان حادثا لم يعتبر فى حدوثه زمان آخر لاستحالة أن يكون للزمان زمان آخر.\rوإذا عقل الحدوث فى نفس الزمان من غير اعتبار زمان فليعقل مثله فى سائر المواضع.\rخواص القديم والمحدث:\r__________________\r1 ـ فالزمان: ت ج ف ق ك لب ي، والزمان: م ل.\r2 ـ الازل: ا ت ف ق ك لب ي، الاول: م.\r3 ـ تعالى: ت ق ك م ي،: ف.\r4 ـ اول: ت لب م، نهاية: ا ف ل ق ك ي، لا نهاية ولا اول: ج.\r5 ـ مما تقرر: ا ت ج ف ق لب ل، مما يقرر: ك، بما يقرر: م، بما يحقق: ي، انه: ا ت ج ك ل ف ي، انا: م، اعتبر: ا ت ج ف ل ك ي، اعتبرنا: م.\r6 ـ لكان: ا ت ج ف ك لب ي، لكن: م، فان: وان: ا فقط.\r7 ـ له: نسخ، في: ت ج.\r8 ـ واذا: ت ج م، فاذا: ف، ولن: لب ي.\r8 ـ واذا: ت ج م، فاذا: ف، وان: لب ي.\r8، 9 ـ واذا عقل .. زمان آخر: ت فقط.\r9 ـ للزمان زمان آخر: ك.\r10 ـ واذا: ت م، فاذا: ك، فليعقل: ت ف ك لب م، آخر فليعقل: ي.\r12 ـ المحدث: نسخ، الحادث: ت."], [210, "مسئلة (ا):\rاتفق المتكلمون على أن القديم يستحيل إسناده إلى الفاعل.\rوانفقت الفلاسفة على إنه غير ممتنع. فإن العالم قديم عندهم زمانا، مع إنه فعل الله سبحانه وتعالى. وعندى أن الخلاف فى هذا المقام لفظى. لأن المتكلمين لم يمتنعوا من إسناد القديم إلى المؤثر الموجب بالذات.\rولذلك زعم مثبتو الحال منا أن عالمية الله تعالى وقادريته قديمان، مع أن العالمية والقادرية معللة بالعلم والقدرة، وزعم أبو هاشم ان العالمية والقادرية والحبية والموجودية معللة بحالة خامسة، مع أن الكل قديم. وزعم أبو الحسين ان العالمية حالة معللة بالذات. وهؤلاء وإن كانوا يمتنعون عن اطلاق لفظ القديم على هذه الأحوال ولكنهم\r__________________\r1 ـ مسئلة: ت ق ج ك لب م، ا: ف ي.\r2 ـ اسناده: م ج، استناده: ت ل.\r3 ـ اتفق: ك فقط. ممتنع: ت ك ج ل، ممتنع زمانا: ق م.\r4 ـ سبحانه و: ك.\r5 ـ لم لا ت يمتنعوا من اسناد استناد: ا: ا ج ت ف ك لب ي، لم يمعوا اسناده: م، لم يمنعوا من اسناد: ق.\r7 ـ زعم: ت ف ق ك لب ج ي، زعموا: م، وقادرينه: ف، وعلمه: ت ك لب ج م ي، في علمه: ل، ق.\r8 ـ والقادرية: ا ف ك، مع العالمية: ف، ت لب م ي ج ل، والقدرة: ا ف: لب م ي، فزعم: ك فقط.\r9 ـ والقادرية: ا، الموجودية: ف ج ل ك م، الموجودية ا.\r8، 9 ـ بالعلم ... معللة: ت ق.\r10 ـ الحسين: ت ج ف ق ك ل م ي، الحسن: لب، هؤلا: ت ج ف ق ل ك لب م ي، هو الاول: ا.\r11 ـ يمتحزن: ف فقط. هذه: ف ت لب ك م، هاولا: ي، و: ا ف ق،: ت ك لب ل م ي."], [211, "يعطون المعنى فى الحقيقة.\rوأما الفلاسفة فإنهم إنما جوزوا إسناد العالم القديم إلى البارى تعالى، لكونه عندهم موجبا بالذات، حتى لو اعتقدوا فيه كونه فاعلا بالاختيار، لما جوزوا ذلك، فظهر من هذا اتفاق الكل على جواز استناد القديم إلى الموجب القديم، وامتناع استناده إلى المختار.\rمسئلة (ب):\rأهل السنة أثبتوا القدماء: وهى ذات الله تعالى، وصفاته. والمعتزلة وان بالغوا فى إنكاره، ولكنهم قالوا به فى المعنى، لأنهم قالوا: الأحوال الخمسة المذكورة ثابتة فى الأزل مع الذات. فالثابت فى الأزل على هذا القول أمور كثيرة، ولا معنى للقديم إلا\r__________________\r1 ـ الحقيقية: في ك.\r2 ـ اسناد: نسخ، استناد: ت، القديم: ا ت ف ج ق ك لب ل ي،: م.\r3 ـ لكونه: ا ت ج ف ق ك لب ل ي، لكنه: م، موجبا: ا ت ج ف ق ك لب ل ي، موجب: م.\r4 ـ ذلك: ا ت ج ف، كونه موجبا للعالم القديم: ق ك لب ل م ي. الكل: ت ف ق ك لب ل م ي، ا، استناد: ا ل، الساحل استناد: ت، اسناد: ج ف ق ك لب م ي.\r5 ـ استناده: ا ت ل، اسناده: ف ج ق ك لب م ي، المختار الغالب المختار: ق.\r6 ـ مسئلة: ت ج ق ك لب ل ي، ب: ا ف ي.\r7 ـ اثبتوا: ا ت ف ق ج ل لب ي، رضي الله عنهم اثبتوا: م، اتفقوا على اثبات: ك، القدماء: ت م، قدماء: ق، تعالى: ا ت ف ق ك لب ي، سبحانه و: م،: ج.\r8 ـ ولن: ا ت ف ق ك لب: م ي ج ل، و (2): ا ت ف ق ك لب ي، م.\r9 ـ الازل: ا ت ج ف ق ل ك لب ي، الاول: م، الذات: نسخ: ذات الله تعالى: ق.\rفالثابت: ا ف ق، والثابت: ك، فعلى هذا الثابت: ت"], [212, "ذلك. وأما القول بقديم سوى ذات الله تعالى وصفاته. فقد اتفق المسلمون على إنكاره، لكنهم عولوا فيه على السمع، لأن دليل التمانع لا يدل إلا على نفى الإلهين. فأما على نفى قديم غير قادر، ولا حي، فلا.\rوأما الحرانيون فقد أثبتوا خمسة من القدماء اثنان حيان فاعلان، وهما البارى والنفس. وعنوا بالنفس ما يكون مبدأ للحياة، وهى الأرواح البشرية والسماوية. وواحد منفعل غير حي وهو الهيولى. واثنان لا حيان، ولا فاعلان، ولا منفعلان، وهما الدهر والفضاء.\rأما قدم البارى تعالى فالدليل عليه مشهور.\rوأما قدم النفس والهيولى فهو بناء على أن كل محدث مسبوق بمادة\r__________________\rج لب ل م ي، على هذا القول: ا ف ق ك، ت لب م ي، للقديم: ت ق ك، القديم: م.\r1 ـ واما: ت ج ق لب ل م ي، اما: ا ف ك، بقديم: ق ج ك ل م ي، يقدم: ت ف لب، تعالى: ت.\r2 ـ لكنهم: ت م، ولكنهم: ق.\r3 ـ الالهين فاما على نفي: ا ت ج ف ق ك ل لب ي: م، غير: ا ت ج ف ق ك لب ل ي، م.\r5 ـ الحرانيون: ا ي، لحرنانيون: ج ق ل، الحرنانيون: ت ق ك، الحربانيون: م، الحربانيون: لب، خمسة: ا ت ف ق ك لب ي، خمسا: م، اثنان: ت ج ق ك ل.\r5، 6 ـ حيان ... ما يكون: ق.\r6 ـ وهما: ا ت ج ف ك لب ل ي، م، الحياة: ك فقط.\r7 ـ غير حي: ا ت ج ف ق ك لب ل ي: م.\r8 ـ انقضاء: ت لب م، الخلاء: ا ف ك ل ي، القضاء: ق.\r9 ـ تعالى: ت فقط. مشهورة: ق فقط.\r10 ـ والهبولي: ت ج فقط، فهو: ت ج ق ك لب ل م ي، وهو: ا ف."], [213, "فقالوا: لو كانت النفس حادثة لكانت مادية، ومادتها إن كانت حادثة افتقرت إلى مادة أخرى، لا إلى نهاية. وان كانت قديمة، فهو المطلوب.\rوأما الهيولى فإن كانت حادثة لزم التسلسل، وإن كانت قديمة فهو المطلوب.\rوأما الدهر فهو الزمان وهو غير قابل للعدم، لأن كل ما صح عليه العدم، كان عدمه بعد وجوده، بعدية زمانية، فيكون الزمان موجودا حال ما فرض معدوما وهذا محال، فإذا قد لزم من فرض عدم الزمان محال لذاته، فيكون واجبا لذاته.\rوأما الفضاء فهو أيضا واجب لذاته، لأن الواجب لذاته هو الّذي يشهد صريح الفطرة بامتناع ارتفاعه.\rوالفضاء كذلك، لأنه لو ارتفع، لما بقيت الجهات متميزة بحسب الإشارات وذلك غير معقول.\r__________________\r1 ـ مادية: ت ج ف ق لب ل ي، لها مادة: م، لها مادية: ا ك.\r2 ـ وان: ا ت ج ف ق ك لب ي، ولزم التسلسل وان: م.\r4 ـ فان: ت م، ان: ك.\r5 ـ فهو: ا ت ج ف ق ل، وهو: لب م ي.\r6 ـ وهو: ات ج ف ق، فقير: ك لب ي، فلانه: م، صح: ا ت ج ف ق ك لب ي، يصح: م.\r8 ـ وهذا محال: ا ف ق ك لب ل ي، فهذا محال: م، هذا خلف: ت ج.\r9 ـ عدم الرمان محال: ت ج، عدمه لذاته محال: م ل.\r10 ـ القضاء: ت ج ق ك لب م ل ي، الخلاء: ا ف. هو الذي: ت فقط.\r11 ـ الفطرة: ت ج ف ل ك لب م ي، العقل: ا ق.\r12 ـ ارتفع: ت ج ف ق ك ل ي، ارتفعت: لب م. متحيزة: ف فقط."], [214, "مسئلة (ج):\rزعم عبد الله بن سعيد منا أن القدم صفة، وزعمت الكرامية أن الحدوث صفة، وهما باطلان. لأن القدم لو كان صفة، لكانت قديمة. والحدوث لو كان صفة، لكانت حادثة، فيلزم التسلسل.\rمسئلة (د):\rزعمت الفلاسفة: إن كل محدث فهو مسبوق بمادة، ومدة. أما المادة، فلأن المحدث مسبوق بالإمكان، وهو صفة وجودية مغايرة لصحة اقتدار القادر عليه، لأن صحة اقتدار القادر عليه موقوفة على كون الشيء ممكنا فى نفسه ولو كان إمكانه، نفس صحة اقتدار القادر عليه، لزم توقف الشيء على نفسه فثبت ان الإمكان صفة موجودة، وهى سابقة على وجود الممكن، فيستدعى محلا وهو المادة والجواب عنها ما مر فى مسئلة المعدوم.\rوأما المدة فقالوا: كل محدث فعدمه قبل وجوده. فتلك القبلية\r__________________\r1 ـ مسئلة: ت ك لب م، ج: ا ف ق ي.\r4 ـ كان: ت لب م ي، كانت: ف ج ك، فيلزم: ا ف ق ك لب ي، ولزم: ت م.\r8 ـ عليه: ي فقط. لان صحة .. اقدار: ك .. عليه: ا ت ف ق ك لب ي، م.\r9 ـ كون الشيء: ت ج ق، كونها: م ل، ممكنا في نفسه: ت ج ق، ممكنة في نفسها: م ل ولو: ا ف لب، فلو: ت ج ق ك م ي، امكانه: ج ك ي، امكانها: ت ف ل لب م.\r10 ـ عليه: ا ف ج ق ك ي، عليها: ت م ل.\r11 ـ موجودة: ت ك لب م ي، وجودية: ف، و (2): ف.\r12 ـ مسئلة المعدوم: ت ق ك م ي، المسئلة المتقدمة: لب، مسئلة ان المعدوم شيء: ف.\r13 ـ تلك: ت ج ق لب م ي، وتلك: ا ف. القبلية: ت ف ق ك لب م، القبيلة: ا، و: ك."], [215, "ليست نفس العدم فإن العدم قبل، كالعدم بعد. وليس القبل بعد، فهى صفة وجودية فتستدعى موصوفا موجودا. فقبل ذلك الحادث شيء موصوف بالقبلية لا إلى أول.\rفههنا قبليات لا أول لها. والّذي يلحقه القبلية لذاته هو الزمان. فهنا أزمنة لا أول لها.\rوالجواب: إن تقدم عدم الحادث على وجوده، لو وجب أن يكون بالزمان، لكان تقدم عدم كل واحد من أجزاء الزمان على وجوده بالزمان. ولكان تقدم البارى تعالى على هذا الجزء من الزمان بالزمان فيلزم أن يكون الله تعالى زمانيا، وأن يكون الزمان زمانيا وهما محالان.\rمسئلة (ه):\rالعدم لا يصح على القديم. ولما كانت هذه المسألة احدى مقدمات مسئلة الحدوث لا جرم رأينا أن نذكر برهانها هناك.\r__________________\r1 ـ بعد (2): بعدا: ق.\r2 ـ فهي: ا ت ج ف ق ك لب ي، وهي: م.\r4 ـ فههنا: ا ق ك لب، فهنا: ت ج م ي.\r5 ـ فهنا: ت ج م، فههنا: ف ق ك، وههنا: ا، لب ل ي، ازمنة: ا ف ج ق، زمان: ك م، فالزمان: لب ي، لزمنه: ت، لها: ا ت ف ق، له: ك لب م ي.\r6 ـ و: ف فقط.\r7 ـ تقدم عدم: ت ج ف ك لب ي، تقدم: م، لعدم: ا، عدم: ق.\r8 ـ ولكان: ج م ل، ولو كان: ت.\r9 ـ وهما: ا ف ت ق ج ل ك لب ي، فهما: م.\r11 ـ مسئلة: ف ك لب م، ة: ف.\r12 ـ لا: ا، ج ت ل. المسئلة: م، المقدمة: ك.\r12، 13 ـ العدم ... هناك: ف ق م، ت ي ج ل.\r13 ـ لا جرم: ا ف ك لب، ق م، نذكر: ق ك لب م،"], [216, "تقسيم الممكنات على رأى الحكماء\rإن الحال قد يكون سببا لقوام المحل، إما بأن يقتضي حلول نفسه فى المحل بشرط وجود المحل بالحال ثم أن يصير نفسه حالة فيه، أو بأن يقتضي الأثر حلول مؤثره فيه. وعلى التقديرين لا يلزم الدور.\rفالمحل المتقوم بنفسه المقوم لما يحل فيه يسمى بالهيولى. والمحل الّذي لا يتقوم بما يحل فيه يسمى بالموضوع، فهو أخص من المحل، فيكون عدمه أعم من عدم المحل.\rإذا عرفت ذلك فنقول: الممكن، إما أن يكون فى الموضوع وهو العرض، أو لا يكون، وهو الجوهر. والجوهر إما أن يكون فى محل وهو الصورة، أو يكون محلا وهو الهيولى أو مركبا من\r__________________\rيكون: ف، برهانها: م، برهانا: ك، برهاننا: ق.\r2 ـ ان: ا، بان: ق لب ي، فتقول: ك م، ت ج ل ف، بان: ت ج ل ف.\r3 ـ الحال وجود المحل: نسخ، حلول نفسه في المحل بشرط وجود المحل بالحال: ت: ت ج، ان: ا ف ق،: ت ل ج نسخ امرى، بصير: ت ج ف ق لب، نصير: م ي.\r4 ـ فيه: نسخ، فيه بشرط وجود المحل: ق، على: ا ت ج ف ل ق ك لب ي، على هذين: م، يلزم: ا ت ف ج ق ك لب ل ي، يلزم منه: م.\r6 ـ فالمحل ... بالهيولى: ي، فالمحل المتقوم بما يحل فيه نهي بالهيولى: لب، فالمحل المتقوم بنفسه بما يحل فيه: ك: ك ج م ل، فالمحل المتقوم: ق، فالمحمل: ا ق.\r6، 7 ـ والمحل فالمحل: ا ف، ا ت ق ك م الذي لا يتقوم بما يحل فيه فالمحل: ا: ت ف ق، والمحل المتقوم بنفسه القوم لما يحل فيه: لب، الذي لا يتقوم: ق: ك ج ل.\r7 ـ فهو: ا ت ف ق ك لب ي، وهو: م.\r9 ـ ذلك: ا ت ج ف ق ك، هذا: م.\r11 ـ محل: ا ت ف ج ق ك لب ل، المحل: م، محل غير متقوم بنفسه: ي."], [217, "الصورة والهيولى وهو الجسم فقط، بالاستقراء، أو لا حالا ولا محلا ولا مركبا منهما، وهو إما أن يكون متعلقا بالجسم تعلق التدبير، وهو النفس، أو لا يكون وهو العقل.\rوأما العرض، فهو إما أن يقتضي نسبة أو قسمة، أو لا نسبة، ولا قسمة.\rأما النسبة فسبعة أقسام: الأين وهو الحصول فى المكان. والمتى وهو الحصول فى الزمان، أو فى طرفه والمضاف وهو النسبة المتكررة والملك، وهو كون الشيء محاطا بغيره الّذي ينتقل بانتقاله. وان يفعل وهو التأثير، وان ينفعل وهو التأثر. والوضع وهو الهيئة الحاصلة للجسم بسبب ما بين أجزائه من النسب وما بين تلك الأجزاء وبين الأمور الخارجية عنها من النسب.\rأما العرض الّذي يقتضي القسمة: فإما أن يكون بحيث ينقسم إلى\r__________________\r(11/ 216)، 1 ـ من الصورة والهيولى: نسخ، منهما: ت ج.\r1 ـ «حالا» استبدل ب «محلا» ق: ت ج.\r2 ـ متعلقا بالجسم: ا ف ك، له تعلق بالجسم: ت ج ق، متعلقا بالاجسام: لب ل م ي تعلق التدبير: نسخ، بالتدبير: ت ج.\r3 ـ او نسخ، و: ت.\r4 ـ واما: لب ل م ي، اما: ت ج ف ق ك، فهو: ا ت ج ف ق ك لب ل، وهو: م.\r6 ـ النسب: ف ت ل ك، النسبة: ق م، الاعراض النسبية: ج.\r7 ـ طرفة: ا ت لب، طرفه وهو الان: ف، ظرفه: ت ك م ي.\r8 ـ الملك: ا ت ف ج ق ك لب ل ي، الملك ويقال له الجدة ايضا: م.\r9 ـ التاثر: م، التاخير: ت.\r11 ـ عنها من النسب النسبة: ل: ج: ت فقط.\r12 ـ فاما: ت م، واما: ق."], [218, "أجزاء مشتركة فى حد واحد، وهو الكم المتصل أو لا يشترك فى حد واحد، وهو الكم المنفصل.\rأما المتصل، فإما أن تكون الأجزاء المفترضة فيه، بحيث توجد معا. وإما أن لا يكون كذلك.\rفالأول هو الكم المتصل القار الذات، وهو إما أن يكون ذا بعد واحد، وهو الخط أو ذا بعدين، وهو السطح أو ذا ثلاثة أبعاد وهو الجسم التعليمى.\rوأما الّذي لا يكون قار الذات فهو الزمان فقط.\rوأما الكم المنفصل فهو العدد.\rوأما العرض الّذي لا يقتضي قسمة ولا نسبة فهو الكيف وأقسامه أربعة:\r__________________\r1 ـ مشتركة: ت م، تشترك: ف ق ك لب ل ي، المتصل: ك.\r2 ـ المتفصلة: ك.\r3 ـ المعترضة: ا ت ج ف ك ل ي، المفروضة: ق لب، المعترضة: م.\r5 ـ فالاول: ت ج ق لب م ي، والاول: ا ف ك، القار: نسخ كلها، العار: ا.\r5، 6 ـ ذا بعد واحد: ت م، بعدا واحدا: ق.\r8 ـ واما الذي ... فار: م، والذي ... قار: ف، واما الثاني وهو ان لا يكون فار: ج ل ق ك لب، واما الثاني فهو الغير الفار: ي: ت. الذات فهو الزمان فقط: ت.\r9 ـ واما الكم: ا ت ف ج ق ك لب ل، واما المنفصل: م، والكم المنفصل: ي.\r10 ـ واما: نسخ ف، اما: ت ج، و: ل، التي: ف، قسمة ولا نسبة: ت م، نسبة ولا قسمة: ا ف ج ق ك لب ي، فهو: ت ق ك لب م ي، وهو: ا ف."], [219, "أحدها ـ المحسوسات بالحواس الخمسة.\rوثانيها ـ الكيفيات النفسانية.\rوثالثها ـ التهيؤ، إما للدفع وهو القوة أو التأثر وهو اللاقوة\rورابعها ـ الكيفيات المختصة بالكميات.\rأما المتصلة، كالاستقامة، والانحناء.\rوأما المنفصلة كالأولية والتركيب.\rأما المتكلمون فقد أنكروا وجود الأعراض النسبية. أما الإضافة، فلأنها لو كانت موجودة، لكانت فى محل، وحلولها فى محلها نسبة بين ذاتها وبين ذلك المحل، فكانت غير ذاتها. وذلك الغير أيضا يكون حالا فى المحل فيكون حلوله زائدا عليه ولزم التسلسل ولأن كل حادث يحدث فإن الله تعالى يكون موجودا معه فى ذلك الزمان فلو كانت تلك المعية صفة وجودية لزم حدوث الصفة فى ذات الله تعالى وهو محال. ولأن الإضافة لو كانت صفة موجودة، لكان وجودها غير ماهيتها\r__________________\r1 ـ الخمسة: ت ج ل م ف، الخمس: ق ك.\r2 ـ التاثر: ا، للتاثر: ف ق ج ك لب م ي، التاثير: ت.\r6 ـ التركيب: ا ت ف ق ك ج ي ل، التركب: لب، التركب والتقدم والتاخر: م.\r7 ـ انكروا: ت ف ق ك لب م ي، انكروه: ا الاضافة: ت ف ق م، الاضافات: ك لب، الاضافيات: ي.\r9، 10 ـ وذلك ... فيكون يكون: ا ف ق لب ي عيلة: ق: ا ف ق ك لب م ي، وتلك النسبة ايضا يكون في المحل فيكون حلولها في المحل ايضا زائدا عليها: ت ج.\r11 ـ موجود معه في: ق، معه موجود في: ا.\r12 ـ وجودية: نسخ، موجودة: ت ج، لزم .. تعالى: نسخ، لزم ان يكون الله لله: ج تعالى صفات محدثة وهو محال: ت ج.\r13 ـ صفة: ـ ت.\r12، 13 ـ لزم ... موجودة: ا فقط."], [220, "بناء على أن الوجود وصف مشترك فيه بين كل الموجودات، فحصول وجودها لماهيتها إضافة بين وجودها وماهيتها وتلك الإضافة سابقة على تحقق الإضافة الموجودة، فيكون الشيء موجودا قبل نفسه، هذا خلف.\rوأما نسبة الشيء إلى الزمان، فلو كانت صفة وجودية، لكان لها نسبة أخرى إلى ذلك الزمان، ولزم التسلسل.\rوكذا التأثير، لو كان صفة زائدة، لكانت تلك الصفة ممكنة بذاتها مفتقرة إلى مؤثر، فكان تأثير المؤثر فيها صفة أخرى، ولزم التسلسل.\rوكذا القبول لو كان صفة زائدة لكانت موصوفية الذات بها صفة أخرى ولزم التسلسل.\rأما الحكماء فقد احتجوا على ثبوت هذه النسب بأن كون السماء فوق الأرض مثلا أمر حاصل سواء وجد الفرض والاعتبار أو لم يوجد، وهو ليس أمرا عدميا، لأن الشيء قد لا يكون فوقا، ثم يصير\r__________________\r1 ـ فيه: ب ج، كل ـ: ت ج.\r3 ـ على: ت.\r5 ـ لكانت: ك.\r6 ـ لزم: م، يلزم: ت ج، لزمه: ق.\r7 ـ كان (1): كانت: ق ك فقط.\r8 ـ بذاتها: نسخ، لذاتها: ت ج، فكان: ا ت ج ف ق ك ي، وكان: لب م.\r10 ـ لكانت موصوفية: ت ج ق ك م، لكان موصوفية: ف لب ي، لكان موصوفة: ا.\r11 ـ لزم: نسخ، يلزم: ت.\r12 ـ فقد: ت م، ا ك، النسب: نسخ، النسبة: ت ق.\r13 ـ فوق الارض: نسخ، فوقنا: ت ج، الفرض: ت م، العرض: ك."], [221, "فوقا. فالفوقية التى حصلت بعد العدم، لا تكون عدمية وإلا لكان نفى النفى نفيا، وهو محال. فالفوقية أمر ثبوتى، وليست هى نفس الذات، لأن الجسم من حيث إنه جسم غير مقول بالقياس إلى الغير ومن حيث انه فوق مقول بالقياس إلى الغير، ولأن الشيء قد لا يكون فوقا ثم يصير فوقا والذات باقية فى الحالتين والفوقية غير حاصلة فى الحالتين. ثم أن معمرا من قدماء المتكلمين، أثبت لقوة هذه الحجة هذه الأعراض النسبية، ولم يجد دافعا للتسلسلات المذكورة فالتزمها وأثبت أعراضا لا نهاية لها، يقوم كل واحد منها بالآخر.\rقال المتكلمون: هذا باطل، لأن كل عدد موجود، فله نصف، ونصفه أقل من كله وكل ما كان أقل من غيره، فهو متناه فنصفه متناه فى العدد. وكل ما نصفه متناه فى العدد فكله متناه، لأنه ضعف المتناهى.\r__________________\r1 ـ فا: م، وا: ك، ت، لا: نسخ، فلا: ت.\r2 ـ تفيا وهو محال: ت ف لب ج ي، عدميا وهو محال: ك م، ملينا: ا، والفوقية: ك.\r3 ـ مقول: ف ج ق ك لب م، معلول: ت ي.\r3، 4 ـ الجسم ... ولان: ل.\r4 ـ مقول: ت ج ف ق ك لب م، معقول: ي الغير: ت م، الآخر: ق.\r5 ـ فوقا (1): ا ت ف ج ق ك لب ي فوق: م. والذات: ا ت ج ف ق لب ي، فالذات: ك م. الحالتين: ا ت لب ج ي، الخالين: ف ق ك م.\r6 ـ الحالين: ت، الحالين: م.\r7 ـ يجد: نسخ، يجدوا: ق.\r8 ـ فالتزمها: نسخ، فالزمها: ت، منها بالآخر: ت، منها .. و، م، منهما: ا ك لب ي، منها: ف ق.\r10 ـ كل ما: ت ف ج ق لب ي، كلما: ك م.\r11 ـ في العدد (1): ي فقط. وكل ما: ت ق م، فكلما: ل ي، في العدد (2): ا ف،: ت ج ق ك لب م ي، فكله: ف ج ق م ي، وكله: ت، كله: لب."], [222, "قال معمر لا نسلم أن كل عدد، فله نصف، بل ذلك من خواص العدد المتناهى. سلمناه لكن لم قلتم: أن كل ما كان أقل من غيره فهو متناه، أليس أن مقدورات الله تعالى أقل من معلوماته، وتضعيف الألف مرارا لا نهاية لها أقل من تضعيف الألفين مرارا لا نهاية لها.\rونحن نقول حجة الفلاسفة على إثبات النسب يقتضي كون التقدم والتأخر صفتين موجودتين، وذلك محال. لأن الاضافتين توجدان معا فالقبلية والبعدية لا يوجدان إلا معا فمحلاهما يوجدان معا فالقبل موجود مع البعد، هذا خلف. ولأنا نحكم على اليوم الماضى فى اليوم الحاضر، بكونه ماضيا. والمفهوم من كونه ماضيا، ليس أمرا سلبيا لأنه صار ماضيا بعد ما لم يكن ماضيا فهو إذن ثبوتى وليس ثبوته فى الذهن فقط.\r__________________\r1 ـ فله: نسخ، له: ت ج.\r2 ـ سلمناه: ا ت ج ف ق ك لب ي، سلمنا: م، ولكن: ف فقط. فلتم ان: ا ت ج ف ق بان: ت ج، قلت ان: لب ي، قلت بان: م، لا نسلم ان: ك. من غيره: ت ج ق ك لب م ي، في عدد: ا ف.\r4 ـ نهاية لها ت ق ك لب م ي، نهاية غيره: ا، نهاية له: ج، نهاية، ف، الالفين: ت ج ف ق لب م، الاثنين: ي، الغين: ك لا نهاية لها: كذلك: ت ج.\r4، 5 ـ القدم والتاخر: ا ج ت ف ق لب، المتقدم والمتاخر: م.\r7 ـ فالقبلية .. لا يوجد ان لا معا الا ـ: ق: ا ت ف ق لد لب ي. موجود ان: ل، يوجدان معا: ج، م، فمحلاهما: ا ق ك لب ي، ومحلاهما: م، فمحالهما: ف، فكلاهما: ت.\r8 ـ موجود: ت ج، على: نسخ، عن: ت، اليوم (1): نسخ، النوم: ا.\r9 ـ وبالمفهوم من كونه ماضيا: تكرر في: ا.\r10 ـ مالم: نسخ، ان لم: ت ج ك، ماضيا (2): ت ق، فهو اذن: ا ت ج ف ق ك لب ي، فاذا هو: م."], [223, "فإنا لو فرضنا عدم الفرض والاعتبار فذلك اليوم ماض فى نفسه، وليس عبارة عن نفس ذلك اليوم، لأنه حين كان حاضرا، لم يكن ماضيا، فيلزم أن يكون وصف كونه ماضيا، عرضا حقيقيا قائما به، حال عدمه، فيكون الموجود قائما بالمعدوم وهو محال.\rوأما الوضع فهو كهيئة الجلوس مثلا فإن أريد به ما لكل واحد من أجزاء الجسم من الأين ومماسة الغير، فلا نزاع فى ثبوته وإن عنى به أمرا وراء ذلك قائما بمجموع الأجزاء، فهو محال، لاستحالة حلول الواحد فى المحال الكثيرة.\rلا يقال لم لا يجوز أن يقال: إنه عرضت لمجموع تلك الأجزاء وحدة باعتبارها صارت واحدة. وحينئذ لا يلزم من قيام هيئة الوضع بها قيام الواحد بالمحال الكثيرة.\rلأنا نقول الإشكال فى كيفية قيام تلك الوحدة بها كالإشكال فى قيام هيئة الوضع بها. فإن كان ذلك بسبب وحدة أخرى سابقة، لزم التسلسل.\r__________________\r1 ـ الفرض: ت ج ف ل م، العرض: ك.\r5 ـ اما: فقط. فهو: ت ج، وهو: ل م، اريد ت ج ف ق ك لب م ي، ارتد: ا.\r6 ـ اجزاء: ت ج ف ق ك لب ي ل، آخر: م، من الابن ومماسبة ماسة: لب الغير: ف ق ك لب م ي ل، والمماسة: ج، من المماسة والابن: ت ج، في بيوته: نسخ، فيه: ت ج.\r7 ـ امرا اخر: ي ... قائما: ا ت ج ي، امرا اخر .. قائم: ك لب، امر .. قائما: ف قائم: ف ل م، فهو: نسخ، وهو: ت.\r9 ـ لجموع: ت ق لب م ج ي، المجموع: ا ف ج ك.\r10 ـ وحدة: نسخ، وحده: ت.\r11 ـ بالمجال الكثيرة: ت ق ج، باكثر من الواحد: ف ل م.\r12 ـ كيفية ... بها: ت فقط.\r13 ـ ذلك: ا ت ج ف ق ك لب ي، م."], [224, "وكذا القول فى الملك.\rوأما الكميات المتصلة فقيل لا معنى للسطح إلا نهاية الجسم. ونهاية الشيء هى أن يفنى ذلك الشيء وفناء الشيء لا يكون أمرا وجوديا.\rوكذا القول فى الخط والنقطة. وأيضا السطح لو كان عرضا حالا فى الجسم المنقسم فى الجهات الثلاث. والحال فى الشيء الّذي يكون كذلك، منقسم فى الجهات الثلاث فالسطح منقسم فى الجهات الثلاث فكان جسما، هذا خلف.\rأما الزمان: وهو مقدار الحركة عند أرسطاطاليس، فقد احتجوا على أنه لا يجوز أن يكون موجودا بأمور.\rأولها: أنه لو كان موجودا، لكان إما أن يكون موجودا قار\r__________________\r1 ـ كذا: م، كذلك: ق ك.\r2 ـ واما: ا ف، اما: ق لب م ي. الا: ف ك لب م ي، لا: ا.\r1، 4 ـ ... كذا القول في الملك ... وجوديا: ت.\r4 ـ فناء الشيء: ا ف ج ق ك لب ل ي، هذا: م.\r5 ـ الخط والنقطة: ا ت ج ف ك لب ل ي، في النقطة والخط: ق م. السطح: وقع بعد كان في: ك.\r6 ـ في: ت ف ق لب م، الى: ي الثلاث: ا ت ج ف ق ك لب ي، الثلاثة: م، الشيء: ت ج.\r8 ـ منقسم: ا ت ج ف ق لب، ينقسم: ك م، الثلاث: من ج ب ق لب ي، الثلاثة: م.\r7، 8 ـ فاسطح منقسم المتقسم: ف لب في الجهات الثلاث مكان: ت ج ف لب، فكان: ل ا ك ي، فيكون: ق م.\r9 ـ اما: ا ت ك لب ج ي، واما: ف ق م، وهو: ا ت ج ف ق ك لب ل ي، فهو: م ارسطو: ت ج ق ك.\r11 ـ موجودا: ب ج ق ل، م."], [225, "الذات، فيكون الحاضر عين الماضى فيكون الحادث اليوم حادثا زمان الطوفان، هذا خلف؛ أو لا يكون قار الذات. وحينئذ يقضى العقل بأن جزأ منه كان موجودا، ولم يبق الآن وإن جزأ منه حصل الآن والماضى والآن هو الزمان، فيلزم منه وقوع الزمان فى الزمان. فلو كان الزمان أمرا وجوديا، لزم التسلسل وهو محال.\rوثانيها: أن الزمان إما الماضى أو المستقبل أو الحال ولا شك فى أن الماضى والمستقبل معدومان إما الحال فهو الآن، وهو اما أن يكون منقسما، أو لا يكون. فان كان منقسما لم توجد أجزاؤه معا. فلا يكون الّذي فرضناه موجودا موجودا، هذا خلف وإن لم يكن منقسما كان عدمه دفعة، لا محالة. وعند فنائه يحدث أمر آخر دفعة، فيلزم منه تتالى الآنات، ويلزم منه تركب الجسم من النقط المتتابعة، هذا خلف.\rوثالثها: الزمان، لو كان موجودا لكان واجب الوجود لذاته.\r__________________\r1 ـ الحدث: ت ج ق ك لب م، حادث: ا ف. اليوم: ا ت ف ك م، اليومي: لب، في اليوم: ق، حادثا: ت ج ف ك ل م، حادث: ا ي، حادثنا في: لب.\r2 ـ يقتضي: في فقط.\r3، 4 ـ كان .. والماضي و: ت ف ج ق ك لب م، حصل الان وجزءا منه في الماض ي والماضي: ي.\r3 ـ وان: ا ت ج ف ق ك لب، فان: م.\r5 ـ الزمان: ت ك ل ج. وهو: نسخ، وهما: ت.\r6 ـ ان: ت ج.\r7 ـ في: ا ت ف ج ق ك ل لب ي، م، اما: نسخ، واما: ك.\r8 ـ لم توجد اجزاؤه: ت ج ف ق ك لب م ي، لم يوجد جزؤه: ا ف في الداخل.\r9 ـ موجودا (1): ق.\r11 ـ تركيب: ك فقط. النقط المتابعة: ا ف، النقط المتشافعة: ت ق لب ج ي هامش ف، النقط المتتابعة: ك، نقط متتابعة: م."], [226, "وفساد التالى يدل على فساد المقدم.\rبيان الشرطية أنه لو كان موجودا وفرضناه قابلا للعدم. فلنفرض أنه عدم فيكون عدمه بعد وجوده بعدية لا توجد مع القبل. وهذه البعدية لا تتحقق إلا عند تحقق الزمان، فإذا يلزم من فرض عدم الزمان وجوده، وذلك محال. فإذا مجرد فرض عدمه يستلزم المحال فإذا فرض عدمه محال، فهو واجب لذاته. وإنما قلنا إنه يستحيل أن يكون واجبا لذاته، لأن كل جزء منه حادث ممكن والمجموع متقوم بالأجزاء، والمتقوم بالممكن المحدث يستحيل أن يكون واجبا لذاته.\rورابعها: لو كان الزمان موجودا لكان مقدارا لمطلق الوجود. فإنا كما نعلم بالضرورة أن من الحركات ما كانت موجودة أمس ومنها موجود الآن، ومنها ما يوجد غدا، كذلك نعلم بالضرورة أن الله تعالى كان موجودا بالأمس، وانه موجود الآن، وسيبقى موجودا\r__________________\r2 ـ بيان: ا ت ج ف ق ك، وبيان: م، فللنفرض: ت ق لب: فلنفرض: ف ج ك ي، فليفرض: م.\r3 ـ بعدية: نسخ، بعدية بعد: ت، بعدية وبعد: ل، لا توجد م، لا يوجد: ا م، موجد: ق.\r5، 6 ـ فاذا مجرد 1000 كان: م محال: ت ق ك لب م،: ف ي.\r6 ـ فهو واجب: ت ق ك لب م ي، فيكون واجبا: ف.\r7 ـ حادث و: م، حادث: ت ج ل.\r8 ـ متقوم: ا ت ج ف هامش ق ك لب ل ي، يتقوم: م، معدم: فيه المتقوم: ت ق ك لب ي، المعدم: ف.\r9 ـ لذاته: ف ج م، ت ق ك لب ل ي.\r10 ـ الوجود: ج م، الموجود: ت ل.\r11 ـ فانا كما نعلم: ت ف ق ك م ي، فان كل واحد يعلم: لب.\r11، 12 ـ ومنها موجود الان: ق فقط.\r12 ـ و: ت ف ق ك لب م ي، ا: يعلم: لب فقط.\r13 ـ موجود: م ج ل، موجودا: ت."], [227, "غدا. فإذا جاز إنكار أحدهما جاز إنكار الآخر، لكن يستحيل أن يكون مقدارا لمطلق الوجود. لأنه فى نفسه إن كان متغيرا استحال انطباقه على الثابت. وإن كان ثابتا استحال انطباقه على المتغير.\rفإن قلت: نسبة المتغير إلى المتغير هو الزمان، ونسبة المتغير إلى الثابت هو الدهر ونسبة الثابت إلى الثابت هو السرمد.\rقلت هذا التهويل خال عن التحصيل. لأنى قد دللت على أن مفهوم كان ويكون لو كان أمرا موجودا فى الأعيان، لكان اما أن يكون قار الذات، فيلزم أن لا يوجد فى المتغيرات. وان كان متغيرا استحال وجوده فى الثابت. وهذا التقسيم لا يندفع بالعبارات.\rوخامسها: وهو فى ابطال قول أرسطاطاليس خاصة: ان الزمان: مقدار امتداد الحركة وامتداد الحركة لا وجود له فى الأعيان، لأن\r__________________\r1 ـ فاذا: ت ج ل، فان: م.\r2 ـ الوجود: ج م، الموجود: ت ل، ان كان: تقدم على: في نفسه: في: ت ج، متغيرا: ا ت ج ف ق ك لب ي، متجددا: م.\r4 ـ المتغير (1): ا ت ف ق ج لب ك ي، التغيير: م، نسبة المتغير: ا ت ج ف ق ك لب ي، نسبته: م.\r6 ـ قلت: ت ف ق ك م ي، قلنا: لب.\r7 ـ موجودا: ت ج ق ك لب م ي، وجوديا: ف، وجودا: ا.\r8 ـ وان: ت ق ك م، واذا: ا.\r8، 9 ـ كان في ـ: ا الثالث: ا ف ج ك لب م، لم يكن قار الذات لم يوجد في الثابت: ي، غير قار الذات استحال وجوده في الثابت: ق، كان ثابتا استحال وجوده في المتغيرات: ت ل.\r9 ـ يندفع: ت ف ق ك لب م ي، يندرج: ا، العبارة: ي فقط.\r10 ـ و (1): ف، وهو في: ت ج، وهو: م، في ك. ارسطو: ت ج ق ل ك.\r11 ـ مقدار: ت ف ق ك، لو كان مقدار: م، الحركة وامتداد الحركة: ت ف ق ك لب م ي، الحركة: ا."], [228, "الامتداد لا يحصل إلا عند حصول جزءين والجزء ان لا يحصلان دفعة، بل عند حصول الأول، فالثانى غير حاصل. وعند حصول الثانى، فالأول فائت. وإذا لم يكن لامتداد الحركة وجود فى الأعيان، لم يكن لمقدار هذا الامتداد وجود، لاستحالة قيام الموجود بالمعدوم. وهذا الوجه لخصه الامام الكبير أفضل الدين الغيلانى أطال الله بقاءه.\rوأما الكميات المنفصلة فليست أمورا وجودية، لأنه لا معنى للعدد إلا مجموع الوحدات. والوحدة لا يجوز أن تكون صفة وجودية زائدة على الذات، وإلا لكان كل واحد من أشخاص تلك الماهية، أعنى ماهية الوحدة واحدا، فيلزم التسلسل ولأن الاثنينية لو كانت\r__________________\r1 ـ دفعة: ت م، دفعة واحدة: ف.\r2 ـ فالثاني: ف ج ق ك لب م ي، والثاني: ا، بالناس: ت.\r3 ـ فابت: ت ج ف ك لب ي، فابته: ق، ثابت: م، واذا: ا ت ف ك ي، فاذا: ق لب، واذ: م.\r4 ـ في ت: المعدوم بالوجود.\r5 ـ وهذا: ت ج لب م ي، فهذا: ا ف، الكبير: ت ج ق لب ل ي، ف ك م.\r5، 6 ـ الغيلاني اطال الله بقاءه: ت لب، الغيلاني قدس الله روحه الله العزيز: ل: فريد الغيلاني نور الله فبره: ق، الغيلاني رحمه الله: م ج، فريد الصيادي: ف الغيلاني: هامش، الغيلاني: ك ي.\r6 ـ فيلزم ان يكون وصف كونه هذا خلف تكرر هنا في ك من 128 الى 28 ب سطر 12 وهو موافق لما في ص 222 سطر 2 الى ص 225 سطر 2، حيث ان كله مكثوب هناك في الهامش في نفس المخطوط.\r7 ـ فليست: م، ليست ت.\r8 ـ مجموع: ت ف ق ك لب م ي، مجموع في: ا الواحدات: ت م، الواحدات: ق.\r10 ـ اعنى واحدا وحدة: م ل: ت ج م ل، واحدة: ا ف ك، اعنى ماهية الوحدة مشاركة لجميع الوحدات في الواحديه ومخالفه لها في الخصوصية فيلزم افتعار كل وحدة الى وحدة اخرى: لب، وحدة: ق ي."], [229, "صفة واحدة وهى قائمة بالوحدتين. فإما أن تكون بتمامها قائمة بكل واحدة من الوحدتين، فيلزم قيام الواحد بالاثنين، فيلزم أن يكون كل واحدة وحدها اثنين، وهو محال.\rوإن توزعت على الوحدتين كان القائم بكل واحدة من الوحدتين، غير القائم بالأخرى، فلم تكن الاثنينية صفة واحدة، بل مجموع أمرين. وإن جاز ذلك فلتجعل الاثنينية نفس تينك الوحدتين.\rأما الفلاسفة، فقد احتجوا على كون الوحدة صفة ثبوتية. بأن الإنسان الواحد يخالف العشرة فى مسمى الواحدية ويشاركها فى مسمى الإنسانية. فالواحدية زائدة على الماهية، وليست أمرا عدميا، لأنها لو كانت عدمية لكانت عدم الكثرة. فالكثرة إن كانت عدمية كانت الوحدة عدم العدم، فتكون ثبوتية، وإن كانت وجودية، فلا معنى للكثرة إلا مجموع الوحدات. فإذا كانت الوحدة عدمية، لزم أن\r__________________\r1 ـ صفة واحدة: ت ق م ي، صفة: ا ف لب.\r2 ـ واحدة: ت ق م، واحد: ا ف ج ك لب ي، الواحد بالاثنين: ت ف ق لب م ي، الاثنين بالواحد: هامش ف وبعد التصحيح في: ك فيلزم (2): ت ف ق، ويلزم: لب ج م ي.\r3 ـ واحدة: ا ت ف ق لب ي، وحدة: م.\r4 ـ واحدة: ت ف ق ك لب م، واحد: ج ي، وحدة: ا.\r6 ـ امرين: ا ت ق ج ك لب ي، الامرين: ف م، فلتجعل: م: فليجعل: ت، فليكن: ك، بينك: م ل، تلك: ك: ت ج.\r7 ـ اما: ا ت ج ف ق ك لب ي، واما: م، اما: م، اما الفلاسفة: تكرر في: ك.\r8 ـ يخالف: ت ف ك م ي، مخالف: لب، الواحدية: ت ف ج ك لب م ي، فالواحدية: ق، الوحدية: ا.\r9 ـ زائدة: ا ت ق ج ك لب ي، صفة زائدة: ف م.\r10 ـ عدمية: ا ت ج ق، مرا عدميا: ك لب ل ي، عدميا: م، الوحدة عدمية: ف فالكثرة: ت ج ك ل م، والكثرة: ا ف ق.\r11 ـ فلا: ا ف ق ك لب، ولا: ت ج م.\r12 ـ الوحدات: ج ل م، الواحدات: ت، فاذا: ا ت ج ف ق"], [230, "يكون مجموع العدمات أمرا وجوديا، وهو محال. فثبت بهذه الدلالة كون الوحدة والكثرة وصفين وجوديين قائمين بالذات.\rوأما الكيفيات، فالمختصة منها بالكميات غير موجودة، لأن ما دل على بطلان وجود الكم دل على بطلان ما يقوم به.\rوأما الصلابة، فهى عبارة عن التأليف بناء على القول بالجوهر الفرد واللين عبارة عن عدم الممانعة فيكون عدميا. والله أعلم.\rتقسيم المحدثات على رأى المتكلمين\rالمحدث اما أن يكون متحيزا أو قائما بالمتحيز أو لا متحيزا ولا قائما به.\rأما القسم الثالث، فقد أنكره الجمهور من المتكلمين. وأقوى ما لهم فيه أنا لو فرضنا موجودا غير متحيز ولا حالا فيه، لكان\r__________________\rك ي، واذا: لب م، لزم: ت ج ق لب م ي، يلزم: ا ف ك.\r2 ـ وجوديين: ت ف ج ك م، موجودين: ق لب ل ي.\r3 ـ و: ت ج ف ق ك لب ل ي،: م غير موجودة: ت فقط.\r4 ـ وجود: ت الكم دل على بطلان: ا ت ج ف ق ك لب ل ي،: م.\r5 ـ واما: ا ت ف ج ق ك لب ل ي، يدل على بطلانها اما: م، فهي: ا ت ف ق ك، وهي: م.\r6 ـ اللبن: ت ف ج ق ك لب ل ي، واما اللبن فهو: م، والله اعلم: ت، فصل: لب، ف ق ل م ي.\r8 ـ بالمتحيز: م، به: ت.\r8، 9 ـ لا متحيزا ولا قائما به: ا ت ج ق ك لب ل ي، ولا قائما ولا متحيزا بها: ف، اولا متحيزا ولا قائما بالمتحيز: م.\r10 ـ اما ... فقد: ا ت ج ف ق ك لب ل ي، و ... قد: م.\r11 ـ حالا ا ف، حال، ت ج ق ك لب م ي."], [231, "مساويا لذات الله تعالى فيه. ويلزم من الاستواء فيه الاستواء فى تمام الماهية. وهذا ضعيف، لأن الاشتراك فى السلوب لا يقتضي التماثل. وإلا لزم تماثل المختلفات، لأن كل مختلفين، فلا بد وأن يشتركا فى سلب كل ما عداهما عنهما.\rوأما المتحيز، فقد قال المتكلمون: إنه إما أن يكون قابلا للانقسام أو لا يكون قابلا والأول هو الجسم والثانى هو الجوهر الفرد. وعند المعتزلة اسم الجسم لا يقع إلا على الطويل العريض العميق. وعلى التفسير الّذي قلنا: الجسم ما فيه التأليف. وأقله جوهران، وهذا بحث لغوى.\rوأما الحال فى المتحيز فهو العرض. وهو اما أن يجوز اتصاف غير الحى به، أو لا يجوز.\r[ا] اما الأول (*) فهو المحسوس بأحد الحواس الخمسة\r__________________\r1 ـ فيه (1): ك فقط.\r2 ـ فلا: ت ج لب م ي، لا: ف ق ك، يشتركا: م، يشتركان: ت فقط.\r4 ـ عنهما: ي فقط.\r5 ـ و: ا ف ك، ت ج ق لب م ي، التميز: ف فقط.\r6 ـ قابلا: ت ج فقط.\r7 ـ الجسم: ت ج ف ك م، الجنس: ا ق، والعريض والعميق: ف فقط.\r7، 8 ـ على التفسير الذي: ا ف ق ك، على ما: ت ج لب م ي.\r8 ـ قلنا: ا ف ق ك، قلناه: ت ج م ل، وهذا: ا ت ف ق ك لب ي، فهذا: م.\r10 ـ واما: ت ج ق ل، اما: م.\r12 ـ اما .. فهو: ا ت ج ف ق ك لب ي، و ... هو: م. باحد: ا ت ف ك ل ي، باحدى: ق لب م،: ج، الخمسة: ا ت ف ج لب، الخمس: ق ك: م ي.\r(*) واما ب يعني الثاني الذي يشير اليه: او لا يجوز سياتي"], [232, "والأكوان.\rأما المحسوسات.\rفمنها المحسوسة بالبصر احساسا أوليا، وهى الألوان والأضواء.\rفأما الألوان فالقدماء قالوا الخالص هو السواد. وأما البياض فهو إنما يتخيل من اختلاط الهوى بالأجسام الصغار الشفافة كما فى الثلج والزجاج المدقوق، ومنهم من اعترف بالبياض كما فى بياض البيض المسلوق.\rوالمعتزلة قالوا: الخالص هو السواد والبياض والحمرة والصفرة والخضرة.\rأما الضوء فقيل إنه جسم وهو خطأ لأن الأجسام متساوية فى الجسمية، ومختلفة فى كونها مضيئة ومظلمة وعند أبى على سينا: الضوء شرط وجود اللون، وعندنا شرط صحة كونه مرئيا. أما الظلمة فمنا من قطع بكونها ثبوتية. والأقرب أنها عدم الضوء عما من شأنه\r__________________\rفي ص (240) سطر (1).\r1 ـ الاكوان في ق: الالوان.\r2 ـ اما المحسوسات: ا ت ج ف ق، اما المحسوسة: لب ل ي، واما المحسوس: م، لما المحسوس: ك.\r3 ـ المحسوسة: ا ت ج ف ق، المحسوس: ل لب م ي، وهي: ا ت ج ف ك لب ل ي، وهو: م، والاضواء اما الالوان: ا فقط.\r4 ـ فاما: ت ج، اما: م، واما: لب، اما: ا ف ق ك، و: ت م ج ي ل، فهو: ا ف ق ك، ت م ي ل ج.\r5 ـ الصغار: تاخر الى بعد الشفافة في: ت ج.\r8 ـ و (1): ت ج ق م، اما: ك.\r11 ـ ومظلمة: ت فقط، سينا: ت فقط.\r12 ـ صحة: ت ج ل م، لصحة: ق ك.\r13 ـ ثبوتية: ت ج ف ق لب م ك ي، ثبوتيا: ا."], [233, "أن يصير مضيئا، لأن فى الليل إذا جلس إنسان عند النار وآخر بعيدا عنها. فالبعيد يرى من كان قريبا من النار، ويرى الهواء المتوسط بينهما مضيئا، والقريب لا يرى البعيد، ويرى ذلك الهواء مظلما.\rولو كانت الظلمة صفة ثبوتية قائمة بالهواء لما اختلف الحال.\rومنها المحسوسة بالسمع وهى الأصوات والحروف وهى كيفيات إما عارضة للأصوات كالسين والشين أو حادثة فى آخر زمان حبس النفس، وأول زمان إطلاقه كالباء، والطاء. ومنه يظهر أن الحروف غير الأصوات.\rومنها المحسوسة بالذوق وهى الحرافة والمرارة والملوحة والحلاوة والدسومة والحموضة والعفوصة والقبض والتفاهة.\rتنبيه:\r__________________\r1 ـ مضيئا: ت م، مغيبا: ف، انسان: ت ج ق ك م، احد: لب، اواحد: ي: ف، بعيدا: ت: ق ك ج م ي، بعيد: ا ف لب.\r2 ـ عنها: ت ق ك لب م ي، ف، ويرى: ت ج ق ك لب م ي، فيرى: ا ف.\r4 ـ ولو: ت ج ف ق ك لب ل ي، فلو: م.\r6 ـ اما عارضة للاصوات: ت ج ك لب م، عارضة اما للاصوات: ي، عارضة اما الاصوات: ا ف ق ل. كالسين والشين: ت ج م، ما مستمرة باستمرارها: ق. حبس: ف ق ج ك لب م ي، جنس: ا ت.\r7 ـ و (2): ي، يظهر: ت ج م ق، يفهم: ك، الحروف: ت لب ج م، الحرف: ا ف ق ي ل.\r8 ـ الاصوات: ت ج، الصوت: ف م ل.\r9 ـ المحسوسة: ا ت ف ق ج ك لب ل ي، المحسوسات: م.\r10 ـ المفوصة: ت ج ق ك لب ل م ي، المصوفة: ف. النفاهة: م، النقاهة: ت، السفاهة: ج ل ف.\r11 ـ تنبيه: نسخ، نبينه: ا."], [234, "لا شك أن الحرافة تفعل تفريقا والعفوصة قبضا فالمدرك بحس الذوق كله طعم محض، أو أمر مركب من الطعم، ومن تفريق الحاسة هذا يتوقف فيه.\rومنها المحسوسة باللمس وهى الحرارة والبرودة والرطوبة واليبوسة والثقل والخفة والصلابة واللين.\rمسئلة (أ):\rمنهم من جعل البرودة عدم الحرارة وهو خطأ لأنا نحس من البارد بكيفية مخصوصة، فذلك المحسوس ليس بعدم الحرارة لأن العدم لا يحس به، ولا الجسم، وإلا لكان الإحساس بالجسم حال حرارته إحساسا بالبرودة.\rمسئلة (ب):\rالرطوبة، ان كانت عبارة عن اللاممانعة، على ما يقوله الفلاسفة كانت عدمية، وان كانت عبارة عن سهولة الالتصاق، كانت وجودية،\r__________________\r1 ـ تفريقا: نسخ، تعريفا: ا.\r2 ـ طعم: ا ت ف ج ق ك لب، طعم محض: م، امر: ف فقط.\r3 ـ وهذا: ف، يتوقف: ت، متوقف: م.\r6 ـ مسئلة: ت ج ف ك لب ل م، ا: ي، ا مسئلة: ق.\r8 ـ بكيفية: ت ج ق لب ل م ي، كيفية: ف. وذلك: ق فقط. المحسوس: ت م، بالمحسوس: ق، بعدم: ا ت ج ف، هو عدم: ق لب ل، عدم: م ي.\r11 ـ مسئلة: ت ج لب ل م، 2 مسئلة: ق، تنبيه: ا ف ك، ب: ي.\r12 ـ ان: ت م، لو: ك، اللاممانعة: ت ف ج ق ك ل م، اللامائعة: ي، عد ممانعة: لب.\r13 ـ الالتصاق: ا ت ج ف ق ك لب ل ي، الالصاق: م."], [235, "واليبوسة فى مقابلتها.\rمسئلة (ج):\rالثقل أمر زائد على الحركة. لأن الثقيل المسكن فى الجو قسرا نحس بثقله. والزق المنفوخ المسكن تحت الماء قسرا نحس بخفته مع عدم حركتهما.\rمسئلة (د):\rاللين معناه عدم ممانعة الغامز فلا يكون وجوديا.\rمسئلة (ه):\rالملاسة عبارة عن استواء وضع الأجزاء، والخشونة عبارة عن كون بعضها أرفع وبعضها اخفض.\rمسئلة (و):\rمن القدماء، من زعم أن هذه المحسوسات، قد تبقى بعد مفارقة محالها قائمة بأنفسها، وابطالها بابطال انتقال الأعراض.\rوأما الأكوان فقد اتفقوا على أن حصول الجوهر فى الحيز أمر\r__________________\r2 ـ مسئلة: ت ج ف ك ل لب م، ج: ي، 3 مسئلة: ق.\r6 ـ مسئلة: ت ج ف ك م لب ل، د: ي، مسئلة: ق.\r7 ـ الغامز: ق ج ك لب م، الغامزة: ت، العامر: ف ي،: ل.\r8 ـ مسئلة: هدف ك لب م، ت: ي، 5 مسئلة: ق.\r9 ـ الملاسة: ت ج ق ك لب ل م ي، الملامسة: ف.\r10 ـ وبعضها: ت ق ك لب م ي، وكون بعضها: ف.\r11 ـ مسئلة: ت ج ف ك لب ل م، و: ي، 6 مسئلة: ق.\r13 ـ ابطالها: ا ف، ابطاله: ت ج ك لب م ي، انتقال: ت ج ف ك لب م ي، انفعال: ا، بانتقال: ل.\r14 ـ و: ت ج، م ك ل ف."], [236, "ثبوتى، فقيل هذا الحيز ان كان معدوما فكيف يعقل حصول الجوهر فى المعدوم، وإن كان موجودا، فلا شك أنه أمر يشار إليه، فهو اما جوهر، أو عرض فان كان جوهرا، كان الجوهر حاصلا فى الجوهر، وهو قول بالتداخل، وهو محال. اللهم إلا أن يفسر ذلك بالمماسة. ولا نزاع فيها. وإن كان عرضا فهو حاصل فى الجوهر، فكيف يعقل حصول الجوهر فيه.\rمسئلة (ز):\rاختلفوا فى أن ذلك الحصول هل هو معلل بمعنى آخر؟ والحق عدمه لأن المعنى الّذي يوجب حصوله فى ذلك الحيز، إما أن يصح وجوده قبل حصوله فى ذلك الحيز، أو لا يصح. فإن صح: فاما أن يقتضي اندفاع ذلك الجوهر إلى ذلك الحيز، أو لا يقتضي. فإن كان الأول كان ذلك هو الاعتماد، ولا نزاع فيه. وان كان الثانى لم يكن بأن يحصل بسبب ذلك المعنى فى حيز أولى من حصوله فى غيره اللهم إلا بسبب منفصل. ثم يعود الكلام الأول فيه.\r__________________\r1 ـ يعقل: ت م، يعمل: ك.\r2 ـ بشار: ا ت ج ف، مشار: ق ك لب ل م ي. امر: ف فقط.\r3 ـ او: ت ج ق لب م ي، واما: ف ك.\r4 ـ اللهم: ك فقط. يغسر: ا ت ج ف ق لب ي يغسروا: ك م.\r5 ـ بالمعاسة: ت ج ف ق ك لب م، المماسة: ل، بالمهاسة: ي، فيها: ف ق ك م، فيه: ت ج لب ل ي، حاصل: ت ج ق ك لب م ي، حال: ف.\r7 ـ مسئلة: ت م ك، 7 مسئلة: ق، ز: ي.\r8 ـ ان: ت ف ق ك لب م، ي. هل: ت ج ف ق لب م ي، اهل: اخر: ق فقط.\r9 ـ اما: ت ق ك لب م ي، فاما: ف.\r12 ـ غيره: ا ت ج ف ق ك ل لب ي، حيز آخر: م.\r14 ـ الكلام: ا ت ج ف ق ك لب ي، البحث: م. الاول: ف."], [237, "وأما إن لم يصح وجوده إلا بعد حصول الجوهر فى ذلك الحيز، كان وجوده متوقفا على حصول الجوهر فيه. فلو كان حصول الجوهر فيه محتاجا إلى ذلك المعنى لزم الدور.\rمسئلة:\rالحركة عبارة عن حصول الجوهر فى حيز بعد أن كان فى حيز آخر والسكون عبارة عن حصوله فى الحيز الواحد أكثر من زمان واحد. فعلى هذا حصوله فى الحيز حال حدوثه، لا يكون حركة ولا سكونا. وقيل هو سكون، وهو إنما يصح، إذا قلنا الحركة عين السكون، والبحث لفظى.\rوالاجتماع هو حصول الجوهرين فى حيزين بحيث لا يمكن أن يتخللهما ثالث، والافتراق كونهما بحيث يمكن أن يتخللهما ثالث. والدليل على وجود هذه المعانى ان الجوهر تحرك بعد أن لم يكن\r__________________\r1 ـ لم: ا ت ج ف ق ك لب ي، لا: م.\r1، 2 ـ ان لم فيه: تكرر في ف ثم شطب عليه.\r2 ـ = فيه: ف ك ل م، في الخير: ت ج، فلن: ت ج ق ك لب م ي، ولو: ف.\r3 ـ فيه: ف ك ل م، في الحيز: ت ج، محتاجا الى ذلك المعنى: ك م، متوقفا عليه: ت ج.\r4 ـ مسئلة: ت ك م، 8 مسئلة: ق.\r6 ـ حصوله: ك م، حصول الجوهر: ت.\r7 ـ سكون: ت ج ك ل م ي، السكون: ا ف ق لب، قلنا: ت ج ك لب م ي، قيل: ا ف ق، عين السكون: ا ك، عين السكونات: ت ج ق م، عين السكونين: لب، غير السكونات: ف.\r10 ـ هو: ا ف ق ك، ت ج لب م ي، حيزين: الف ج ق لب ل ي، حيز واحد: م، حيز واحد لا في حيزين: ك، في الحيز: ت.\r11 ـ يمكن: ت ج ف ق ك لب م ي، الممكن: ا.\r12 ـ هذه: ت ج ف ق ك لب م ي، هذا: ا، ان (1): ا ت ج ف ق ك لب م، م، تحرك: ت ج ي، محرك: ا ف لب، ينحرك: ق، يحرك: م."], [238, "متحركا. والتغير من أمر إلى أمر يستدعى وجود الصفة.\rلا يقال هذا متقوض بما أن البارى تعالى كان عالما. بأن العالم سيوجد، ثم صار عالما بأنه موجود. وكذا لم يكن رائيا للعالم لاستحالة رؤية المعدوم، ثم صار رائيا والأقوى أنه لم يكن فاعلا للعالم، ثم صار فاعلا. والفاعلية يمتنع أن تكون وصفا حادثا، وإلا لافتقر إلى احداث آخر، ويلزم التسلسل.\rوأيضا فالتغير يكفى فى تحققه كون احدى الحالتين ثبوتية، وأنتم ادعيتم أن الحركة والسكون كلاهما ثبوتيان. لأنا نجيب عن الأول بأن التغير فى الاضافات، لا يوجب التغير فى الذات، والصفات. وعن الثانى ان الحركة والسكون نوع واحد، لأن المرجع بهما إلى الحصول فى الحيز، إلا أن الحصول ان كان مسبوقا بالحصول فى حيز آخر، كان حركة، وإن كان مسبوقا بالحصول فى ذلك الحيز كان سكونا وإذا كان كل واحد منهما من نوع واحد، وثبت كون أحدهما ثبوتيا، لزم أن يكون الآخر كذلك. وبهذا الطريق ثبت أن\r__________________\r1 ـ وجود: ت ج ف ك لب م ي، وجوده: ا، وجود هذه: ق، صفة: ك فقط.\r3 ـ لم يكن: ا فقط.\r4 ـ للعالم: ا ت ف ق ك لب ل ي، ج م.\r5 ـ يمتنع: م ك، ممتنع: ت، وصفا حادثا: ت ج لب ل م ي، صفة حادثة: ا ف ق ك، لا عتقر: ت ج ل م، لا فتقرت: ا ف ك، افتقرت: ق.\r6 ـ بلرم: ا ت ج ف ق لب ي، لزم: م.\r8 ـ عن الاول: ق فقط.\r9 ـ التغير في: ت ج ك لب م، تغير: ا ف ق ي.\r11 ـ في حيز آخر: ت ج ف ق ك ل م، في الحيز الاخر: لب.\r12 ـ حركة: نسخ، قوله: ق، ذلك: ا ت ف ج ق ك لب ي، نفس ذلك: م، الحيز الثاني: لب فقط.\r13 ـ كان كل واحد منهما: ق ك ج لب ل م، كان واحد منهما: ف، كانا: ق، كان: ت.\r14 ـ كذلك: ك م، ثبوتيا: ت ج، وبهذا: ت ق ك لب م ي،"], [239, "حصول الجوهر فى الحيز حال حدوثه أمر ثبوتى.\rمسئلة:\rزعم قدماء الأصحاب أن الاجتماع والافتراق أمران مغايران للكون المخصص للجوهر بالحيز، وهو ضعيف لأنا متى عقلنا الجوهرين حاصلين فى الحيزين، بحيث لا يمكن أن يتخللهما ثالث، فقد عقلناهما مجتمعين، فلا حاجة إلى الزائد.\rمسئلة:\rاختلفوا فى أن المحوى حال استقراره فى الحاوى المتحرك هل يكون متحركا أم لا؟ والأقرب أنه متحرك بالعرض لا بالذات.\rمسئلة:\rالأكوان بأسرها متضادة لأنها إن اقتضت الحصول فى حيز واحد، كانت متماثلة، فكانت متضادة، وإن اقتضت الحصول لا فى حيز واحد فلا شك فى تضادها، لكنها قد تكون بحيث لا يصح تعاقبها، كالكون الّذي يقتضي الحصول فى الحيز الأول، مع ما يقتضي الحصول فى الحيز الثانى والثالث فما فوقه.\r__________________\rفبهذا: ا ف.\r3 ـ متغايران: ق.\r5 ـ الجوهرين: ا ت ج ف ك لب ي، جوهرين: م، الحيزين: نسخ، الجوهرين: ك.\r5، 6 ـ الجوهرين .. فقد عقلنا: ق.\r8 ـ المحوى: ت م، المحرك: ق.\r9 ـ ام لا: ت، ك م.\r11 ـ اقتبضت ... وان: ف فقط.\r12 ـ فكانت: ت ج ك م، وكانت: ق وان: نسخ، لاستحالة اجتماع المثلين وان: لب، لا: نسخ، الا: ي.\r13 ـ تعافيها: ت ك م، تعافيهما: ق.\r14 ـ الاول مع ما: ت ج ق م، معما: ف، معا: ا.\r15 ـ الثاني و: لب فقط. الثالث: الثاني: ل، فما: ا ف ك لب ل ي، وما: ت ج م."], [240, "[ب] وأما الاعراض التى لا يتصف بها غير الحى فأجناس:\rمنها الحياة. واعلم أن المراد منها ان كان اعتدال المزاج، أو قوة الحسى والحركة، فهو معقول، وإن كان شيئا ثالثا، فلا بد من إفادة تصوره، ثم إقامة الدليل على ثبوته.\rوالجمهور زعموا أنها صفة لأجلها يصح على الذات ان يعلم وان يقدر. واحتجوا بأنه لو لا امتياز الحى عن الجماد بصفة، وإلا لم يكن اتصاف الحى، ويقدر أولى من الجماد.\rواحتج ابن سينا فى القانون بأن العضو المفلوج حي فحياته اما أن تكون قوة الحس والحركة أو قوة التغذية أو نوعا ثالثا. والأول باطل لأن العضو المفلوج ليس له الحس والحركة. والثانى أيضا باطل لأن قوة التغذية قد تبطل مع بقاء العضو المفلوج حيا، ولأن القوة الغاذية حاصلة للنبات، ولا حياة له، فثبت أن الحياة أمر ثالث.\r__________________\r1 ـ واما: ت ج م، اما: ا ف ك ي، فاما: لب ل.\r2 ـ و: ا ت ف ق ك لب ي، م.\r3 ـ معقول: ا ت ج ف ق ك لب ي، امر معقول: م. ثالثا: ك م، تاليا: ت.\r4 ـ الدليل: ا ك ف، الدلالة: ت ق ج ل.\r5 ـ و (1): ت.\r6 ـ ان: لب م، ت ج ف ق ل ك عن: ت ج م ل. من: ا ف ك.\r6، 7 ـ بهذه الصفة ... اولى من الجهاد: ا ف، بصفة بحجة: ك ان يعلم وان يقدر اولى من الجهاد: ك م، بصحة: ق ل لب ي بان: ت ان يعلم ويقدر اولى من العكس: ت ق لب ي، بان يعلم ويقدر اولىى من العكس: ج.\r8 ـ واحتج: ت ج م، فاحتج: ق.\r10 ـ الحسن والحركة: ا ت ف ج ق ك لب ي، قوة الحركة والحس: م، قوة الحسن والحركة: ل، ايضا: ف نقط.\r11 ـ المفلوج: ت ج ل فقط."], [241, "والجواب عن الأول: إنه معارض بأنه لو لا امتياز الذات الحية بما لأجله صح أن يصير حيا، وإلا لم يكن بأن يصير حيا أولى من غيره. وهذا يقتضي اشتراط الحياة بحياة أخرى. وكل ما هو جوابهم هناك فهو جوابنا هاهنا.\rوعن الثانى أن معنى كون العضو المفلوج بقاء قوة التغذية.\rقوله تبطل هذه القوة مع بقاء الحياة قلنا لا نسلم. فلم لا يجوز أن يقال: إن القوة باقية ولكنها عاجزة عن الفعل.\rقوله الغاذية حاصلة فى النبات قلنا: أنت تساعدنا على أن غاذية النبات والحيوان مختلفان بالنوعية والماهية. والمختلفان لا يجب اشتراكهما فى الأحكام.\rمسئلة:\rالقائلون بهذه الصفة منهم من أثبت ان الموت صفة وجودية محتجا بقوله تعالى الّذي خلق الموت والحياة ومنهم من لم يقل به، وزعم أنه عبارة عن عدم الحياة عما من شأنه أن يكون حيا، وأجاب عن التمسك بالآية بأن الخلق هو التقدير، ولا يجب كون المقدور\r__________________\r1 ـ و: ي فقط، انه: ا ت ج ف ك لب ي، ق م، بانه: ك م، بان: ت.\r2 ـ اولى: ت ك م، باولى: ق.\r7 ـ ان (2): ت فقط، و: ا فقط.\r8 ـ نساعدنا: ت ق م، نساعد: ك.\r10 ـ الاحكام: ت ج ف ق ك لب م ي، الحكم: ا.\r11 ـ مسئلة 2: ق فقط لم تذكر (1) في (مسئلة) سابقة.\r12 ـ ان: م: ت ج ق ك ل.\r13 ـ الذي: ا ق ك لب ل ي، ت ج ف م، لم يقل: ك ل ف م، لا يقول، ت ج.\r14 ـ وزعم: ك ل ف م، فزعم: ت ج ق، ان يكون: ت فقط."], [242, "وجوديا والله أعلم.\rمسئلة:\rالبنية ليست شرطا لوجود الحياة خلافا للمعتزلة والفلاسفة. لنا أن القائم بمجموع الأجزاء إما أن يكون حياة واحدة، أو القائم بكل جزء حياة على حدة. والأول يقتضي حلول العرض الواحد فى المحال الكثيرة، وهو محال. أما الثانى فمحال، لأن الأجزاء متماثلة، فلو توقف جواز قيام الحياة بجزء واحد على جواز قيام الحياة بجزء آخر، لكان الأمر من الجانب الآخر كذلك ويلزم منه الدور وهو محال.\rومنها الاعتقادات وهى أمور يجدها الحى من نفسه، ويدرك التفرقة بينها وبين غيرها بالضرورة وهى: اما أن تكون جازمة، أو مترددة. أما الجازمة، فان لم تكن مطابقة فهى الجهل. وان كانت مطابقة، فاما أن لا يكون عن سبب، وهو اعتقاد المقلد أو عن سبب، وهو اما نفس تصور طرفى الموضوع والمحمول، وهو البديهيات أو الإحساس، وهو الضروريات أو الاستدلال: وهو النظريات.\r__________________\r1 ـ والله اعلم: ت.\r2 ـ مسئلة 3: ق فقط.\r4 ـ القائم: ت ف ق ك لب ج ل ي، العالم: م، يكون: ا ت ج ف ق ك لب ل ي، يكون له: م.\r6 ـ وهو: ا فقط، اما: ت ق لب ي، واما: ف ج ك م، فمحال: ت ج ف ك م، محال: ق لب ي.\r7 ـ بجزء: ا ت ف ق ج ك لب ل ي، لجزء: م، جوار (2): ت فقط. الحياء بجزء: ا ت ج ف، حياة اخرى لجزء بجزء: ك ل: ك لب ل م ي، بجزء آخر: ق.\r8 ـ الامر: ت ل ف ق ك لب م، الاخر: ج ي، من: ت ف ق ك م ي، في: لب، منه: ا ف ق ك لب ل ي، ت ج م.\r10 ـ بالضرورة: ف ك ل م، بضرورة: ت ج.\r11، 12 ـ فهي فهو: ت ج ف ... مطاقة: ق معابقة: ت ف ق ك لب م ي، ا."], [243, "وأما الّذي لا يكون جازما، فإن كان التردد على السوية: فهو الشك، وإن كان أحدهما راجحا، فالراجح: هو الظن، والمرجوح: هو الوهم.\rتنبيه:\rلما كانت مراتب القوة والضعف غير محدودة كانت مراتب الظن والوهم كذلك.\rمسئلة:\rاختلفوا فى حد العلم. وعندى أن تصوره بديهى، لأن ما عدا العلم لا ينكشف إلا به، فيستحيل ان يكون غيره كاشفا له. ولأنى أعلم بالضرورة كونى عالما بوجودى. وتصور العلم جزء منه، وجزء البديهى بديهى، فتصور العلم بديهى.\rمسئلة:\rقيل العلم سلبى، وهو باطل لأنه لو كان كذلك، لكان سلب ما ينافيه. والمنافى ان كان عدما كان هو عدم العدم فيكون ثبوتيا وان كان وجوديا فعدمه يصدق على العدم، فيكون العدم موصوفا\r__________________\r1 ـ فهو: ت ف ج ق ك لب م ي، وهو: ا.\r2 ـ راجحا: ت ك ق، راجحا من الاخر: م.\r5 ـ و: ا ت ج ف ك لب ي، او: م، محدود: ا فقط.\r5، 6 ـ الوهم والظن: في: ا ك.\r6 ـ كذلك: نسخ، كذلك والله اعلم: ف ج.\r9 ـ غيره: ت ج ق ك لب ل ي، ف م، له: ا فقط.\r14 ـ المنافي: ت ج ق ك لب م ي، الثاني: ف، عدما: ا ت ف ق ك ل ي، عدميا: ح لب م، العدم: ا ت ج ف ق ل ك لب ي، العلم: م، وان: ك م، ولو: ت ج، ا.\r15 ـ وجوديا: ت ق ك لب م، وجودا: ا ف ي، العدم: ا ت ج"], [244, "بالعالمية، هذا خلف.\rوقيل انه انطباع صورة مساوية للمعلوم فى العالم، وهو باطل، وإلا لزم أن يكون العالم بالحرارة والبرودة حارا باردا. لا يقال، المنطبع صورته، ومثاله. لأنا نقول: الصورة والمثال ان كان مساويا فى تمام الماهية للمعلوم، لزم المحذور، وإلا بطل قولهم.\rنكتة أخرى:\rيلزم أن يكون الجدار الموصوف بالحرارة والبرودة عالما بهما. لا يقال حصول الماهية للشىء إنما يكون إدراكا إذا كان ذلك الشيء مما من شأنه أن يدرك.\rلأنا نقول: إن كان الإدراك هو نفس الحصول، فالمدرك هو الّذي له الحصول فكان الجدار من شأنه أن يدرك لا من شأنه أن يكون له الحصول.\rاحتجوا بأنا نميز بعض المعلومات عن بعض فوجب أن يكون ثابتا لأن العدم المحض، لا تميز فيه وإذ قد لا يكون المعلوم ثابتا فى\r__________________\rف ق ل ك لب ي، العلم: م.\r7 ـ بهما: ا ت ج ف ق ك ل لب ي، م.\r8 ـ انما: ت ج ف ق ك لب ي، اما ان: م، اذا كان ذلك الشيء مما: ك ي، اذا كان مما: ا، اذا كان ذلك الشيء عما: ف لب. اذا كان ذلك الشيء: ت ج ق، كما اذا كان الشيء عما: م، اذا كان ذلك الشيء فيما: ل.\r9 ـ بدرك: ا ت ج ل ف ق ك لب ي، يكون مدركا: م.\r11 ـ له: ج ل ك م، هو: ت، لا: ك م، لان: ت ف ج ل.\r13 ـ عن بعض: ج ك م، عن البعض: ت.\r13، 14 ـ فوجب .. المحض الصرف: م فيه: ت ج ق م، ف: ا التميز في النفي الصرف محال: ا ك ف لب ل ي.\r14 ـ لا يكون المعلوم ثابتا: ف لب ل م ي، واذا لم يكن المعلوم ثابتا: ك، واذ ليس: ت، واذا لم يكن المعدوم ثابتا: هامش ف،"], [245, "الخارج فهو إذن فى الذهن.\rجوابه هذا يقتضي أن يكون المعلوم بتمام ماهيته حاضرا فى الذهن فمن تخيل البحر فقد حضر فى خياله تمام ماهية البحر وذلك باطل بالبديهة.\rوقيل إنه أمر إضافى وهو حق لما إنه لا يمكننا أن نعقل كون الشيء عالما، إلا إذا وضعنا فى مقابلته معلوما، ثم القائلون به منهم من سمى هذه الإضافة بالتعلق وأثبت أمرا آخر يقتضي هذا التعلق.\rومنهم من قال العلم عرض يوجب العالمية، والعالمية حالة لها تعلق بالمعلوم فهؤلاء أثبتوا أمورا ثلاثة. وأما نحن فلا نقول إلا بهذا التعلق. فاما العالمية والعلم فهما لم يثبتا بدليل.\r__________________\rولا تعدد واذ ليس: ج.\r1 ـ اذن: ف، اذن هي: ا، اذ: ت م.\r4 (244)، 1 ـ واذ قد .. في الذهن: ف.\r2 ـ البحر (1): ت ج ق لب م ي، الحبل: ا ف ك، خيالة: ت ج ق ك لب م ي، زهنه: ا ف. البحر (2): ت ج ق ل لب م ي، الحبل: ف ك، ا.\r5 ـ انه امر: ل ت م ف، انه عبارة عن امر: ج، حق: ا ت ج ف ق ك، الحق: لب م ل ي، لما انه لا: ج ت ك لب ل، لانه: ا ف، بما انه لا: م، لا انه لا: ي، مانه: ق، نعقل: ا ت ج ف ق ل لب ك ي، معرفة: م.\r6 ـ الا: ت ق ك لب م ي، ف، ثم القائلون: ت ج ق ك لب ل ي، ثم القائلين: ا ف، والقائلون: م.\r7 ـ الاضافات: ف، بالتعلق و: ا ت ف ق ك لب ي، بالتعليق: م، التعلق: ا ت ف ق ج ل ك لب ي، التعليق: م.\r8، 9 ـ لها تغلق: ت ج ك ل، تعلق: ا، بما تعلق: ق، تتعلق: م.\r9 ـ واما: ا ف ج ك ل ي، فاما: ت ق لب م، فلا: ت ف ق ك لب م، لا: ي.\r10 ـ فهما: ا ت ف، فمها: ق ك لب م: ي، لم بثبتا بدليل: ت، لم لا: ك بثبت بالدليل: ف ق ك لب م، فعها: ي."], [246, "مسئلة:\rاختلفوا فى أن العلم الواحد هل يكون علما بمعلومين.\rوعندى أنا إن فسرنا العلم بنفس التعلق لم يصح ذلك، لأنه يصح أن يعقل كون الشيء عالما باحد المعلومين مع الذهول عن كونه عالما بالآخر، ولو لا التغاير لما صح ذلك.\rوإن فسرناه بما يوجب التعلق لم يمتنع ذلك لأن العلم المتعلق بكون السواد مضادا للبياض، إن لم يكن هو بعينه متعلقا بهما لم يكن متعلقا بالمضادة التى بينهما، بل بمطلق المضادة. وليس كلامنا فى ذلك العلم، بل فى العلم المتعلق بالمضادة المخصوصة، وإن كان متعلقا بهما، فهو المطلوب.\rثم المجوزون منهم من فصل، فقال كل معلومين يصح ان يعلم أحدهما مع الذهول عن الآخر امتنع تعلق العلم الواحد بهما وكل معلومين لا يصح العلم بأحدهما مع الذهول عن الآخر، يجب أن يعلما\r__________________\r2 ـ وعندي: ا ق ت ك لب ج ل م ي، قال مولانا رضي الله عنه: ف، ان: ت ك لب م، لو: ف ق ل ي.\r4 ـ يعقل: ك م، العقل: ت، باحد: ت ف ق ك لب م ي، باحدى: ا.\r6 ـ ذلك: ا ت ج لب: ف ق ك م ي.\r7 ـ يضاد البياض: ف فقط.\r8 ـ بمطلق: ت ف ق ك لب م ي، مطلق: ا.\r8، 9 ـ في ذلك العلم: ك ف م ل، فيه: ا ج ت.\r11 ـ فقال: ت ق م ي، وقال: ف لب.\r11، 12 ـ يصح ... احدهما: ت ج ق لب م ي، يصح العلم باحدهما: ف.\r12 ـ امتنع ... بهما: ت ج ق ك لب م ي، لم يجب ان يعلما بعلم واحد: ف.\r13 ـ يجب: ت ج ف م، يمتنع: ا ك لب ل ي."], [247, "بعلم واحد.\rوهذا التفصيل عندى باطل، لأن العلم بمضادة السواد والبياض، لما ثبت أنه متعلق بالسواد والبياض مع أنه يصح ان يعلم السواد وحده مع الجهل بالبياض. فقد تعلق ذلك العلم بأمرين يصح العلم بأحدهما مع الجهل بالآخر.\rمسئلة:\rالمعلوم على سبيل الجملة معلوم من وجه ومجهول من وجه والوجهان متغايران فالوجه المعلوم لا إجمال فيه، والوجه المجهول غير معلوم البتة، لكن لما اجتمعا فى شيء واحد، ظن ان العلم الجملى نوع مغاير للعلم التفصيلى.\rمسئلة:\rالعلوم المتعلقة بالمعلومات المتغايرة مختلفة خلافا لشيخى ووالدى رحمه الله.\r__________________\r1 ـ بعلم: ت ف لب م، مما بعلم: ق ك ي.\r2 ـ و (1): ف فقط، عندي باطل: ا ت ج ف ق ك لب ي، باطل عندي: م، و (2): ت ف لب م، ق ك ي.\r3 ـ لما ثبت .. مع انه: ك م، و: ت، مع انه: ك ق م، و: ت ف ج لب ل ي.\rالجهل بالبياض ... مع: ق.\r7 ـ و: ا ق ك لب: ت ج ف م ي.\r8 ـ فالوجه: ت ف م ي، والوجه: ا ك ق ي.\r9، 10 ـ مقاير للعلم: ت ج ف ل ك، يغاير العلم: م، مغاير: لب ي.\r10 ـ للتفصيلي: لب ي فقط.\r12 ـ رحمه الله: ا ت ج ق لب ل ي، رحمة الله عليه: ك، ف م."], [248, "لنا أن النظر فى الدليل ينافى العلم بالمدلول، ومشروط بالعلم بالدليل. ولأن اعتقاد قدم الجسم يضاد اعتقاد حدوثه، ومشروط بالعلم بماهية الجسم، وماهية القدم والحدوث.\rمسئلة:\rالعلوم كلها ضرورية لأنها إما ضرورية ابتداء أو لازمة عنها لزوما ضروريا فإنه إن بقى احتمال عدم اللزوم، ولو على أبعد الوجوه، لم يكن علما، وإذا كان كذلك، كانت بأسرها ضرورية.\rتنبيه:\rاتفقوا على أنه لا يجوز أن يكون العلم بالأصل كسبيا وبالفرع ضروريا، وإلا فعند وقوع الشك فى الأصل يحصل الشك فى الفرع، فيصير الضرورى غير ضرورى، هذا خلف.\rمسئلة:\rاختلفوا فى أن اعتقاد الضدين يمتنع اجتماعهما لنفسهما، أو لأمر يرجع إلى الصارف والأقرب أن المنافاة ذاتية، لأن الجزم بالثبوت،\r__________________\r1 ـ في الدليل: ك فقط، ينافى العلم: ك لب ل، في العلم: ا، مناف للعلم: ا ت ج ف م ي، و: ق فقط.\r2 ـ اعتقاد: ت ج ف ق ك لب م ي، الاعتقاد: ا، و (2): ت فقط.\r3 ـ القدم: ا ت ج ف ق ك ل ي، العدم: لب م.\r5 ـ لازمه: ق ك لب م ي، لازم: ت ف.\r6 ـ ان بقى: ق ك لب ل م ي، لو تطرق اليها: ت ج ف.\r7 ـ علما: ا ت ف ق ك لب ي، علم: م، باسرها: ا ت ج ف ق ك لب ي، ياثرها: م.\r8 ـ تنبيه: نسخ، مسئلة: ا.\r10 ـ في الاصل: ا ت ج ف ق ك لب ل ي، م، فحصل: ي فقط.\r13 ـ لنفسيهما: ح ف ك فقط.\r14 ـ بالثبوت: ت ق ك لب م ي، بثبوته: ف."], [249, "شرطه أن لا يكون لنقيضه احتمال ثبوت فيستحيل تحققه دون هذا الشرط.\rمسئلة:\rمنهم من قال: المعدوم غير معلوم، لأن كل معلوم متميز، وكل متميز ثابت، فكل معلوم ثابت. فما ليس بثابت لا يكون معلوما.\rفعورض بأن تخصيصه باللامعلومية يستدعى تصوره، لأن ما لا يتصور، لا يصح الحكم عليه.\rثم أجابوا عما ذكروه بأن المعدوم فى الخارج ثابت فى الذهن.\rفقيل عليه الثابت فى الذهن أخص من الثابت فيكون العدم هاهنا ثابتا وليس كلامنا فيه. وإنما الكلام فى العلم بغير الثابت، ولأن الثبوت الذهنى مشكل لأنا إذا علمنا أن شريك الله تعالى معدوم. فحضور الشريك فى الذهن محال، لأن الشريك هو الّذي يمتنع\r__________________\r1 ـ شرطه: ت ك م، شرط و: ق، ثبوت: ا ت ق، الثبوت: ف، ك لب م ي، بدون: ف فقط.\r4 ـ المعدوم: ت ك م، ان المعدوم: ق.\r5 ـ ثابت: ا ت ف ج ق ك لب ي، ثابتا: م.\r6 ـ فهورض: ك م، وعورض: ت.\r7 ـ يصح: ك ل م ف، يمكن: ت ج.\r8 ـ عما ذكروه: ت ج، عن الكلام الاولين: ك لب ل م ي، عن الكلام الاول: ف، عن الكلام الاولين: ق.\r9 ـ عليه: ت ج م، له: ك، العدم: ت ج، المعدوم: لب، المعلوم: ق ك ل م ي.\r10 ـ ثابتا: نسخ، ثابت: ا، انما: ا ت ج ف ق ك لب ي، وانما: م.\r10، 11 ـ ولان الثبوت الذهني: تكرر في.\r11 ـ الله تعالى: ج ق ك لب م ي، الله سبحانه وتعالى: ت، الاله: ف.\r12 ـ فحضور: ت ج ق ك لب م ي، فحصول: ف، يمتنع:"], [250, "وجوده لذاته. والحاضر فى الذهن لا يكون كذلك.\rفإن قلت الحاضر فى الذهن تصور الشريك لا نفس الشريك.\rقلت فقد عاد الإشكال. لأن البحث إنما وقع عن متعلق هذا التصور، فإنه ان كان نفيا محضا فكيف يحصل التمييز؟ وان كان ثابتا فثبوته، إما فى الذهن أو فى الخارج. وفيه ما مر.\rمسئلة:\rالمشهور أن العقل الّذي هو مناط التكليف هو العلم بوجوب الواجبات، واستحالة المستحيلات. لأن العقل لو لم يكن من قبيل العلوم لصح انفكاك أحدهما عن الآخر، لكنه يستحيل أن يوجد عاقل لا يعلم شيئا البتة أو عالم بجميع الأشياء، ولا يكون عاقلا ثم ليس هو علما بالمحسوسات، لحصوله فى البهائم، والمجانين، فهو إذا علم بالأمور الكلية، وليس ذلك من العلوم النظرية، لأنها مشروطة بالعقل، فلو كان العقل عبارة عنها لزم اشتراط الشيء لنفسه، وهو محال،\r__________________\rت ق ك، امتنع: ج، يجب: م ل.\r1 ـ لا يكون: ت ف لب ج م ي، ليس: ا ك.\r2 ـ فقد: ت م، قد: ك.\r4 ـ فكيف يحصل التمييز: ا، فكيف حصل التمييز: ت ج ق ك لب ق، فقد حصل التمييز عنه: ف، فكيف التحيز: م.\r5 ـ او: ت ج ق ك م، واما: ف لب ي، وفيه: ا ت ج ق ك لب ي، والكلام فيه: ف م.\r8 ـ استحالة: ت ج ك م، استحال: ق.\r9 ـ لصح: ت ج ف ق ك لب ي، يصح: م، لكنه: ا ت ف ق ك لب ي، لكن: م يستحيل: ت ج، محال لاستحالة: ل ك م.\r10، 11 ـ ثم ليس هو علما العلم: ت ق: ا ت ج ف ق، ثم هو ليس علما: ك، ليس هو علما: م.\r0، 12 ـ مستحيل ... بالامور: ت ق ك م، محال عقلا ثم ليس ه علما بالامور: ف.\r12 ـ وليس: ا فقط.\r13 ـ لنفسه: ت، بنفسه: ج م ك ل."], [251, "فهو إذا عبارة عن علوم كلية بديهية، وهو المطلوب.\rفقيل عليه لم قلت أن التغاير يقتضي جواز الانفكاك. فإن الجوهر والعرض يتلازمان. وكذا العلة والمعلول.\rسلمناه لكن العقل قد ينفك عن العلم كما فى حق النائم واليقظان الّذي لا يكون مستحضرا لشيء من وجوب الواجبات، واستحالة المستحيلات. وعند هذا ظهر أن العقل غريزة يلزمها هذه العلوم البديهية عند سلامة الحواس.\rومنها القدر والمرجع بها فى حقنا إن كان إلى سلامة الأعضاء فهو معقول وإن كان إلى أمر ورائها ففيه النزاع.\rاحتج أصحابنا بأن حركة المختار متميزة عن حركة المرتعش وليس الامتياز إلا بهذه الصفة.\rفيقال لهم متى يثبت هذا الامتياز قبل الاتصاف بالفعل أو حال\r__________________\r1 ـ فهو اذن: ت ق ك لب م، فاذن هو: ف، فاذن: ي.\r2 ـ لم: فلم: ل، قلت: ت ق ك م، قلتم: ف لب ج ل ي.\r3 ـ يتلازمان: ت ق، متلازمان: ك ج م.\r4 ـ و: ت ف ج ق ك لب ي، او: م.\r5 ـ لا يكون مستحضرا لشيء: ت ف ق لب ل م ي، لا يستحضر شيئا: ا ك.\r7 ـ البديهية: ت ف ق لب ج م ي، البديهة: ا، الحواس: ت ج ف ق لب ي، الالات: ا في الهامش: صحة الحواس: ا ك ا ف ك: الحواس نسخة، صحة الحواس: م.\r8 ـ القدر: ا ت ي، القدرة: ف ج ق لب م، ان كان: تقدم على «في حقنا»: في ت.\r9 ـ امر ورائها: ت ج ف ق لب م، امر وراء هذا: ا ك، شيء ورائها: ي.\r12 ـ يثبت: ت ج ك لب، تثبت: ق، ثبت: م ف، او: ك ف م، و: ت."], [252, "الاتصاف بالفعل والأول باطل على قولك لأن القدرة لا تثبت عندك قبل الفعل. والثانى ممنوع، لأن المرتعش كما لا يتمكن من ترك الحركة حال وجودها فالمختار لا يتمكن أيضا من تركها حال وجودها لاستحالة أن يكون الشيء معدوما موجودا فى زمان واحد.\rويقال أيضا متى يثبت هذا الامتياز حال ما خلق الله تعالى الحركة أو قبلها؟ والأول باطل لأن حصول الفعل حال ما خلق الله تعالى ضرورى والثانى باطل لأن حصولها قبل أن خلقها الله تعالى محال. وعلى التقديرين لا يثبت الاختيار.\rويقال للمعتزلة متى يثبت هذا الاختيار عند استواء الدواعى أو عند رجحان أحدهما على الآخر.\r__________________\r1 ـ بالفصل: ا ت ج، به: ف ق ك لب ي، م، باطل: ك ف ك ل م، محال: ت ج.\r2، 3 ـ على قولك لان القدر لا يثبت عندك قبل الفعل: ا، على قولكم لانكم: ق لا: ل ثبتون القدرة قيل الفعل: ف ق لب ل ي، على قولكم لان القدرة لا تثبت قبل الفعل عندكم: ك، لان الفعل قبل الاتصاف معدوم: ت ج، لانك لا تثبت القدرة قبل الفعل: م.\r2 ـ ممنوع: ت ج ف ق لب ي، محال: ا ك، كذلك: م.\r3 ـ ايضا: تقدم على «لا يتمكن» في: ت ج ق، من: ت.\r4 ـ موجودا تقدم على ممدوما في: ت ج.\r5 ـ يثبت: ا ت ج ك ل، ثبت: ف ق لب م ي، هذا: نسخ، هذه: ت، تعالى: ف ي.\r6 ـ باطل: ك ل م ق، محال: ت ج، الفعل: ك م، ها: ت. تعالى: ف.\r7 ـ ضروري: ت ك م، الفعل ضروري: ق، خلقها: خلق: ت ف فقط.\r9 ـ يثبت: ا ت ج ف ك، يثبت: ق لب م ي، هذا: ت. الاختيار: ك ل ف م، الامتياز ت ج ق، الدواعي: ق لب م ل ي، الداعي: ت ف ك، الداعيين: ج، او: ت ج ف لب م ي، و: ق ل، ا م: ا ك."], [253, "والأول محال لأن عند الاستواء يمتنع الفعل، وعند الامتناع لا تثبت المكنة.\rوالثانى محال لأن عند حصول الترجيح يجب الراجح ويمتنع المرجوح. وعلى هذا التقدير لا تثبت المكنة.\rمسئلة:\rالقدرة مع الفعل خلافا للمعتزلة لنا ان القدرة عرض فلا تكون باقية، فلو تقدمت على الفعل لاستحال أن يكون قادرا على الفعل. لأن حال وجود القدرة، ليس إلا عدم الفعل. والعدم المستمر يستحيل أن يكون مقدورا، وخال حصول الفعل لا قدرة.\rواحتجوا بأن الكافر حال كفره مكلف بالإيمان فلو لم يكن قادرا على الإيمان حال كونه كافرا، كان ذلك تكليف ما لا يطاق. ولأن الحاجة إلى القدرة لأجل أن يدخل الفعل من العدم إلى الوجود وحال حدوث الفعل قد صار الفعل موجودا فلا حاجة به إلى القدرة.\rولأنه لو وجب أن تكون القدرة مع المقدور، لزم: إما قدم العالم أو حدوث قدرة الله تعالى.\rوالجواب عن الأول: أنه وارد عليكم أيضا لأنه حال حصول القدرة لا يمكنه الفعل، وحال حصول الفعل لا قدرة عليه.\r__________________\r1 ـ و: م فقط. محال: ا ت ج ف ك لب ي، باطل: ق م.\r3 ـ الترجيح: ا ت ج ق ك لب ي، المرجح: ف م.\r10 ـ و: ت ج فقط. فلو: ت ج ق ك لب م ي، فان: ف.\r11 ـ على الايمان .. كافرا: ك م، حال كفره: ت ج تكليف ما: ت ج ف لب ي، تكليفا بما: ق ك م.\r13 ـ قد: ت ج ق ك لب م، فلو: ي، ف، به: ت ج ق ك م،: ف لب ي.\r14 ـ المقدور: ت ج م، الفعل: ق.\r15 ـ قدرة الله تعالى: ت ج ك ل لب م ي، الباري: ف."], [254, "فإن قلت إنه فى الحال ليس مأمورا بأن يأتى بالفعل فى الحال بل بأن يأتى به فى ثانى الحال.\rقلت: هذا مغالطة لأن كونه فاعلا للفعل: اما أن يكون هو نفس صدور الفعل عنه، واما أن يكون أمرا زائدا عليه. فان كان الأول استحال أن يصير فاعلا قبل دخول الفعل فى الوجود. وإذا كان كذلك، استحال أن يقال: إنه مأمور بأن يفعل فى الحال فعلا لا يوجد إلا فى ثانى الحال وان كان الثانى كانت تلك الفاعلية أمرا حادثا، فيفتقر إلى الفاعل. والكلام فى كيفية فعلها كالكلام فى الأول، فيلزم التسلسل.\rوعن الثانى إنه منقوض بالعلة والمعلول، والشرط والمشروط.\rوعن الثالث أن المؤثر فى وجود أفعال الله تعالى هو تعلق قدرته بها، زمان حدوثها وأما التعلقات السابقة، فلا أثر لها البتة وهذا لا يمكن تحقيقه فى قدرة العبد لأنها غير باقية.\rمسئلة:\rالقدرة لا تصلح للضدين عندنا خلافا للمعتزلة. لنا أن القدرة\r__________________\r1 ـ ليس مامورا: ا ف لب ي، مامور لا: ت ج ق ك م، ليس في الحال مامورا: ل.\r2 ـ هو: ا ف ق ك لب ي، ت ج م.\r4 ـ عنه: ك ل م، فيه: ت ج، فان: ا ت ج ف ق ك لب ل ي، فلو: م.\r5 ـ استحال ان يصير .. واذا كان كذلك: تكرر في: ا.\r6 ـ بانه: ك فقط. مامورا: ف فقط.\r6، 7 ـ فعلا لا يوجد الا في ثاني الحال: ا ف ق ك لب ل ي، فعلا لا يوجد في الحال بل في ثلني الحال: ت ج، م.\r10 ـ و (2): ا ف ت ق ك لب ج ي ل، او: م.\r11 ـ تعالى: ل، هو: ت ف ج ق ك لب ي، وهو ا،: م ل.\r12 ـ تحقيقه: ا ت ج ف ق ك لب ي، تحققه: م.\r15 ـ عندنا: ت ج ف: ق ك لب م ل ي."], [255, "عبارة عن التمكن. ومفهوم التمكن من هذا غير مفهوم التمكن من ذلك ولأن نسبة القدرة إلى الطرفين، ان كانت على السوية، استحال أن تصير مصدرا للأثر، إلا عند مرجح، فلا يكون مصدرا لأثر إلا المجموع، فقبل هذا المرجح لم يكن ذلك قدرة على الفعل وإن لم تكن القدرة على السوية لم تكن القدرة قدرة إلا على الراجح والله أعلم.\rمسئلة:\rعند أصحابنا العجز صفة وجودية، وهو مشكل لعدم الدليل. والّذي يقال ليس جعل العجز عبارة عن عدم القدرة أولى من العكس ضعيف، لانا نساعد على أن كليهما محتمل. وإنه لو لا الدليل لبقى ذلك الاحتمال.\rومنها الإرادة والكراهة. ومن الناس من زعم أن الإرادة عبارة\r__________________\r1، 2 ـ عن التمكن .. هذا ذلك: ت ج .. ذلك هذا: ت ج ولان ذلك واذن: ا .. الى على: ج الطرفين: ت ج ق ك لب ل ي، عن المكنة فهذه المكنة ان كانت كليه من الطرفين: ف، عن الممكنة والمفهوم الممكنة من ذلك ولان نسبه القدرة الى الطرفين: م.\r3 ـ مصدرا للاثر لذلك الاثر: ت ج: ت ج ق ك لب ل ي م، اثرا للمصدر: ف، فلا .. لاثر للاثر ق .. الا: ت ج ف ق ك م، فيكون مصدرا لاثر: لب ل ي.\r4 ـ فقيل هذا المرجح وقبيل هذه الضميمة: ف ك علي الفعل: ا ف ك لب ل، فقيل هذه الضميمة لم يكن ذلك الذي فرضناه قدرة مصدرا للاثر فلا يكون تدرة على الفعل: ق، فلا يكون الذي فرضناه قدرة مصدرا لاثر فلا يكون قدرة: ت ج م.\r5 ـ القدرة (1): ت ج فقط القدرة (2): ت فقط.\r6 ـ والله اعلم: ت.\r8 ـ اصحابنا: ت ج ق ك ل، الاصحاب: ف لب ي، بعض الاصحاب: م، مشكل: ا ت ف ج ك لب ل ي، مشكك: ق، ضعيف: م."], [256, "عن علم الحى واعتقاده، أو ظنه بأن له فيه منفعة، وهو باطل. لانا نجد من أنفسنا ميلا مرتبا على هذا العلم فيتغايران. والفرق بين الإرادة والشهوة أن الإنسان ينفر طبعه عن شرب الدواء ثم يريده.\rمسئلة:\rمنهم من قال: ان إرادة الشيء كراهة ضده، وهو باطل. لأنه قد يراد الشيء حالة الغفلة عن ضده.\rمسئلة:\rالعزم عبارة عن إرادة جازمة حصلت بعد التردد فيه. والمحبة عبارة عن الإرادة لكنها من الله تعالى فى حق العبد إرادة الثواب، ومن العبد فى حق الله تعالى إرادة الطاعة، وأما الرضا فقد قيل إنه الإرادة، وقيل:\rإنه ترك الاعتراض.\rمسئلة:\rالمنافاة بين إرادتى الضدين ذاتية، والصارف فيه ما تقدم فى باب الاعتقادات.\r__________________\r1 ـ و (1): ا ت، او: ج ق ك لب م ي، وهو: ت ف ق ك لب م ي، فهو: ا.\r2 ـ ميلا: ت ف ق ك لب م ي، مثلا: ا.\r3 ـ «والكراهة» بعد الشهوة في: ك، ان: ت ك م، لان: ق.\r5 ـ ان: ك فقط. كراهية: ك.\r6 ـ يراد: ق ك لب م ي، يريد: ت ج ف، حالة: نسخ، حال: ت ج.\r10 ـ تعالى: ت ج ك ل م ي، ف لب، واما و: ت ج ق ل لب م ي .. فقد: ف: ت ف ق ك لب م ي.\r13 ـ ارادتي: ت ج ق ك لب م ي، ارادة: ف، والصارف: ت او و: ق ف للصارف: ج ف م ق ك لب م ي.\r14 ـ الاعتقادات: ت ج ق ك ل لب ي، الاعتقاد: ف م."], [257, "مسئلة:\rالإرادات تنتهى إلى إرادة ضرورية دفعا للتسلسل. وذلك يوجب الاعتراف باستناد الكل إلى قضاء الله تعالى وقدره.\rومنها كلام النفس، ولم يقل به أحد إلا أصحابنا. قالوا: الأمر والنهى والخبر أمور معقولة يعبر عن كل واحد منها فى كل لغة بلفظة أخرى فهى معان مغايرة لهذه اللغات، وليست عبارة عن تخيل الحروف. لأن تخيلها تابع لها، ويختلف باختلافها. وهذه الماهيات لا تختلف البتة. وليس الأمر عبارة عن الإرادة، لأن الله تعالى قد يأمر بما لا يريد، ويريد ما لا يأمر به. وظاهر أنه ليس عبارة عن العلم والقدرة والحياة، فلا بد من نوع آخر.\rومنها الألم واللذة. أما الألم فلا نزاع فى كونه وجوديا، ثم قال محمد بن زكريا: اللذة عبارة عن الخلاص عن الألم، وهو باطل، بما إذا وقع بصر الإنسان على صورة مليحة، فإنه يلتذ بإبصارها، مع أنه لم يكن له شعور بتلك الصورة قبل ذلك، حتى تجعل تلك اللذة\r__________________\r2 ـ الارادات: ك لب م ي، الارادة: ت ف.\r3 ـ الاعتراف: ف فقط، باستناد: ت ف ق لب ل م ي، باسناد: ك ج، تعالى: ت ق ك لب م ي، ف، وقدرة: م، وقدرة: ت، ق ك.\r6 ـ مغايرة لهذه اللغات: ا ث ج ف ق ك ل لب ي، متغايرة: م، ليست: ت ج ف لب ي، ليس: ك م.\r7 ـ يختلف: ت ج ك، مختلف: ق م، الماهيات: ت ق لب ج ل م، الهيئات: ف.\r8 ـ قد: ك، بما: ت ج ق ك لب م ي، ما: ف.\r9 ـ يريده: ق فقط.\r10 ـ آخر: ت ج ف ق ك ل لب ي، واحد: م.\r12 ـ عن (2): ق ك لب م ي، من: ت ج ف.\r13 ـ الانسان: ت ج ق ك لب م ي، انسان: ف، مليحة: ت ج ق ك م، جميلة: ف لب ي.\rيكن: ت ف ق ك لب م ي، يمكن: ا، اللذة: ت ق"], [258, "حاصلة خلاصا عن ألم الشوق إليها.\rوزعم ابن سينا أن اللذة إدراك الموافق، والألم إدراك المنافى.\rويقرب قول المعتزلة منه قالوا: لأن المدرك ان كان متعلق الشهوة كالحكة فى حق الأجرب كان إدراكه لذة وإن كان متعلق النفرة، كما فى حق السليم كان إدراكه ألما. ومثل هذا الكلام لا يفيد القطع بأن الألم ليس إلا الإدراك.\rواتفقت الفلاسفة على أن تفرق الاتصال موجب للألم فى الحى وخالفتهم. لأن التفرق عدمى، فلا يكون علة للأمر الوجودى.\rوزاد ابن سينا سببا ثانيا، وهو سوء المزاج. قال: لأن حد الألم إدراك المنافى. والحد ينعكس، فكل إدراك المنافى ألم. وهذه الحجة لفظية.\r__________________\rم، القدرة: ك.\r1 ـ حاصلة: ت فقط. خلاصا عن: ق ك لب م ي، عبارة عن الخلاص من: ف، خلاصا من قبل: ت، اليها: ف ق ك لب ل م ي، ا ج ت.\r3 ـ قالوا لان: ا ت ف ق ك لب ي، قالوا: ج، فانهم قالوا ان: م.\r4 ـ حق: ك فقط. الاجرب: ك ج م ف، صاحب الجرب: ت ل، ان: ت ج ك م، اذا: ق.\r7 ـ موجب: ت ج ف ك لب م، يوجب: ق ي، للالم: ك م، الالم: ت ق.\r7، 8 ـ الحي وخالفتهم: ت ج لب ل ي، حق الحي وخالفتهم: ك م، الحي وانا اذا خالفتهم: ت، الحي قال مولان ا انا خالفتهم فيه: ف.\r8 ـ للامر: ت ج ق م، للالم: ك.\r9 ـ ابن سينا: ت ك ج م، الشيخ ابو علي رحمه الله: ق، ابن سينا عليه: لب، ثانيا: ت ج ف ق ك لب م ي، ثابتا: ا، نباتا: ل.\r10 ـ فكل: ا ف ج ك لب ل ي، وكل: ت م، هذه: ت ج ق.\r11 ـ لفظيه: ا ت ج ف ق ك لب ي، لفظية لانه اخذ من"], [259, "ومنها الإدراكات وهى غير العلم لأنا نبصر الشيء ثم نغيب عنه فندرك تفرقة بين الحالتين مع حصول العلم فيهما فالابصار غير العلم، لكن الفلاسفة والكعبى وأبا الحسين زعموا أنه عائد إلى تأثر الحدقة بصورة المرئى والمتكلمون محتاجون إلى القدح فى هذا الاحتمال ليمكنهم بيان أنه تعالى سميع بصير.\rمسئلة:\rاختلفوا فى الإبصار منهم من قال: إنه خروج الشعاع عن العين، وهو باطل، وإلا لوجب تشوش الأبصار عند هبوب الرياح، ولامتنع أن نرى نصف السماء الامتناع أن يخرج من حدقتنا ما يتصل بكل هذه الأشياء، أو يؤثر فى جميع الأجسام المتصلة بين حدقتنا وبينها.\r__________________\rالعكس: م.\r1 ـ نغيب عنه: ف لب ل م، يغيب عنا: ك لب، غيب: ت ج، ق.\r2 ـ فندرك: ا ج ت ف ق ك لب ل ي، فيفرق: م، بين: ت ج ل، في: ك ف م، الحالتين: ت ق ج ك لب م ي، الحالين: ف، حصول: ت ل ق ج م، ك، فيهما: ت ج ق ك لب م ي، فيها: ف.\r3 ـ والكعبي: تاخر الى ما بعد «ابا الحسين» في: ق، ابا الحسين: ا ت ج ف ق ك لب، ابو الحسين: م ي، تاثر: ت ج لب ل م، تاثير: ف ق ك ي.\r4 ـ لصورة: ف فقط. محتاجون: ت ك م، يحتاجون: ق. هذه: ق فقط.\r5 ـ انه: ان الله تعالى: ل، تعالى: ت ف ق لب م ي، سبحانه وتعالى: م،: ك ج.\r7 ـ خروج: ا ق ك لب، الخروج: ي، بخروج: ت ج ل ف م، عن: ت ف ق م، من: ك ج ل.\r8 ـ لوجب: ج ك م، وجب: ت ل، لامتنع: ت ج ق ك لب م ي، الا لامتنع: ف.\r9 ـ ترى: ج لب، يرى: ت ق م، يرى: ف ك ل ي.\r10 ـ بين: ا ت ج ف ق ك لب ي، في: م، وبينها: ات ج ف ق ك لب ي، م."], [260, "ومنهم من قال بالانطباع، وهو باطل. وإلا لما أدركنا العظيم لامتناع انطباع العظيم فى الصغير. ولما رأينا القريب على قربه والبعيد على بعده وهذان الوجهان، إنما يلزمان على من قال المرئى هو الصورة المنطبعة فقط.\rأما من جعل انطباع الصورة الصغيرة فى الحدقة شرطا لإدراك المرئى الكبير فى الخارج فلا يرد عليه ذلك.\rمسئلة:\rالإدراك عند سلامة الحاسة وحضور المبصر، وسائر الشرائط المشهورة غير واجب عندنا، خلافا للمعتزلة والفلاسفة.\rلنا إنا نرى الكبير من البعيد صغيرا. وما ذاك إلا لأنا نرى بعض أجزائه دون البعض مع استوائها بأسرها فى كل الشرائط. ولأنا لما رأينا الجسم الكبير، فقد رأينا كل واحد من أجزائه، ويستحيل أن تكون رؤية كل واحد من تلك الأجزاء مشروطة برؤية الجزء\r__________________\r1 ـ القريب: نسخ، القريب بعيدا: ا.\r3 ـ وهذان: ا ف ق لب ل ك ي ج ت، فهذان: م، على: ا ت ج ف ك لب، ق م ي.\r3، 4 ـ هو الصورة: ا ت ف ج ق ك لب ي ل، هذه: م.\r5 ـ اما: ا ت ج ف ق ك لب ي، واما: م.\r6 ـ فلا يرد: ق، لا يرد: ف ج ك ل م، لا يريد: ت.\r8 ـ الحاسة: ت ج ف ق لب م ي، الالة: ا، الالة والحاسة ك. حضور: ا ج ت ف ق ك لب ل ي، حصول: م.\r9 ـ المشهورة: المذكورة في: ف.\r10 ـ انا: ت ج ف ك ل ي، الا: ا، البعيد: ت ق م، البعد: ك، لانا: ف لب ج م ي، لا: ا ت ق، انا: ك.\r11 ـ بمش: ت ج ك م، بعد: ق، باسرها: ا ت ج ف ق ك لب ي، باثرها: م.\r12 ـ اجزائه: ا تج ف ق ك لب ي، تلك الاجزاء: م.\r12، 13 ـ ويستحيل ان تكون: ا ت ج ف ق ك ل لب ي، وليست: م.\r13 ـ واحد من تلك الاجزاء: ا ت ف ج ق ك لب ل ي، جزء"], [261, "الآخر، وإلا وقع الدور. فرؤية كل واحد منها، غنية عن رؤية الآخر.\rواحتجوا بأنه لو لم يجب ذلك، لجاز أن يكون بحضرتنا شموس وجبال، ونحن لا نراها.\rوالجواب أنه معارض بجميع العاديات.\rمسئلة:\rاختلفوا فى أنه هل يعتبر فى السمع وصول الهواء الحامل للصوت إلى الصماخ فعندنا إنه غير واجب خلافا للفلاسفة والنظام.\rلنا. لو كان كما قالوه، لما سمعنا كلام من يحول بيننا وبينه جدار صلب، لأن الهواء النافذ فى مسام ذلك الجدار، لا يبقى على الشكل الأول، الّذي باعتباره كان حاملا للحروف، ولأنه كان يجب أن لا ندرك جهات الصوت، كما انا لما لم نلمس الشيء إلا حال وصوله\r__________________\rم. مشروطة: ت ج ل م، مشروطا: ا ف ق ك لب ي.\r1 ـ ورؤية: ف فقط. غنية: ت فقط، الاخر: نسخ، الاخرى: ا.\r3 ـ احتجوا: ت ج ف ق لب ي، واحتجوا: ك م.\r4 ـ شموس: تاخر بعد جبال في: ت ج.\r5 ـ و: ا ت ف ق ك لب ل ي، ج م، لجميع: ك، العاديات: ت ج ق ل لب مم، الحادثات: ف، العادات: ك ي.\r7 ـ الحامل: ج ك ف ل م، الحاصل: ت ق.\r8 ـ خلافا للفلاسفة: ت ج ق ف ك لب م ي، وعند الفلاسفة ... واجب: ا.\r9 ـ لو: ت ف ق ك ل لب ي، ان لو: ج م، قالوه: ت ج ق لب ي، قالوا: ق ك ل م، يحول: ت ف ج ق ك ل لب ي، يجول: م.\r11 ـ حاملا: ك م، حاصلا: ت ج، كان: ك ف ل م، ت ج.\r12 ـ ندرك: ت ج، تدرك: ك، يدرك: م، لما لم: ا ت ج"], [262, "إلينا، لا جرم لا ندرك بمجرد اللمس جهة وصوله إلينا.\rمسئلة:\rإدراك الشم قد يكون لتكيف الهواء المتصل بالخيشوم من الجسم ذى الرائحة وقد يكون لانفصال أجزاء لطيفة منه ووصولها إلى خيشومنا كما فى المتبخرات. وقد يكون لتعلق القوة المدركة بالرائحة، وهى هناك. وهذا أضعف الاحتمالات. وأما إدراك الذوق فقد تقدم الكلام فيه فهذه إشارة مختصرة إلى أقسام الأعراض.\rفصل فى احكام الأعراض، وهى اقسام:\r"]], "pg": [163, 262]}, "687.7": {"x": [[262, "مسئلة:\rاتفق المتكلمون والفلاسفة على امتناع الانتقال عليها، لأن الانتقال عبارة عن الحصول فى حيز بعد الحصول فى حيز آخر. وذلك إنما يعقل فى المتحيز.\r__________________\rق ف ك لب، لم: ي، لا: م.\r1 ـ الينا (2): ت ج ق، ك ل م ف.\r3 ـ لتكيف: ا ت ج ف ق ك لب ي، بتكيف: م، مسن الجسم: ت ج ل، بكيفية: ك ف م.\r4 ـ لانفصال: ت ج ك م، انفصال: ف ق لب، انفعال: ي، لاتصال: ل، الاجزاء اللطيفة: ف ك، منه: ا ت ف ج ق ي، منها: ك م، ق (2): ا ف ق ي.\r5 ـ المتبخرات: ت، المبحرات: ا ف ج ي، التبخرات: م، التبخيرات: ك لب، التتجيزات: ق. لتعلق: ا ت ج ف ق ك لب ي، تعلق: م، بالرائحة: ت ج ف ق ك لب ل م ي، بدى الرائحة: ا.\r6 ـ وهي: ت ج ف ق ك لب م ي، وهو: ا، نقد: ت ف ق ك لب ي، وقد: م.\r8 ـ فصل في: ك، واما: ت ج ف ل، و: لب م ي،: ق، اقسام: لب: ت ف ق ك لب م.\r10 ـ اتفق: ت ك م، ق."], [263, "والعمدة المشهورة انا لو قدرنا العرض خاليا عن جميع الأوصاف الغير اللازمة فاما أن لا يحتاج حينئذ إلى المحل أو يحتاج. والأول باطل لأنه حينئذ يكون غنيا بذاته عن المحل.\rوالغنى بذاته عن المحل يستحيل أن يعرض له ما يحوجه إلى المحل لأن ما بالذات لا يزول لأجل ما بالعرض، وإن احتاج، فاما أن يحتاج إلى محل مبهم، وهو محال، لأن مقتضى الموجود فى الخارج موجود فى الخارج والمبهم من حيث هو كذلك غير موجود فى الخارج أو إلى محل معين فيلزم استحالة مفارقته عنه وهو المطلوب.\rولقائل أن يقول: لم لا يجوز أن لا يحتاج إليه.\rقوله لأن الغنى بذاته عن المحل لا يعرض له ما يحوجه إليه.\rقلنا الغرض عندنا لا يصدق عليه أنه يجب أن لا يكون فى المحل، حتى يكون ذلك منافيا لحصوله فى المحل، بل يصدق عليه انه نظرا إلى ذاته لا يجب أن يكون فى المحل. وهذا لا ينافيه الحصول فى\r__________________\r1 ـ قدرنا: ت ق ج ك لب ل م ي، فرضنا: ف.\r2 ـ الغير: ت ف ج ك، غير: ا ق لب ل ي، م، به: بعد اللازمة في: ق، نحتاج (1): ك.\r3 ـ حينئذ: تاخر بعد يكون في: ق.\r4 ـ الى المحل: ت ج ل، اليه: ك ف م.\r5 ـ لاجل ما ت ج، لما: ك ي، بما: ف ق م، مما: لب، فاما ان يحتاج: ت ج ق ل م، فان احتاج: ك.\r6 ـ الموجود: ت ج ف ق لب ل ي، الوجود: ك م.\r7 ـ في الخارج (1): ا فقط. هو كذلك: ك ف م، هو مبهم: ت، انه مبهم: ج، هو كذلك والمبهم: ل.\r9 ـ لقائل: ج ك م ل، القائل: ت، لا يحتاج ك ل ج م، يحتاج: ت.\r10 ـ قوله ... ما بحوجة اليه: ي فقط: لان: ف ق ك لب م، ا ت ج ل، لذاته: ف فقط، ما: ك م، حالة: ت.\r11 ـ لا (1): ت ق م، ان لا: ك.\r12 ـ نظرا: ق ك ج لب م، بالنر: ف، نظر: ت ق.\r13 ـ ينافيه: ت ف ق ك لب ل م ي، ينافى: ا ج."], [264, "المحل لسبب منفصل.\rسلمنا أنه يحتاج إلى المحل لكن لم يحتاج إلى محل معين وما ذكروه منقوض باحتياج الجسم المعين إلى مكان غير معين ولأن الواحد بالنوع معين، فاحتياج الواحد بالشخص إلى المحل الواحد بالنوع لا يوجب تعين المحل الواحد بالشخص.\rمسئلة:\rاتفق المتكلمون على امتناع قيام العرض بالعرض، خلافا للفلاسفة ومعمر لنا أنه لا بد من الانتهاء بالآخرة إلى الجوهر. وحينئذ يكون الكل فى حيز الجوهر تبعا له وهو الأصل. فالكل قائم به.\rاحتجوا بأن السواد يشارك البياض فى اللونية، ويخالفه فى السوادية والبياضية وما به الاشتراك غير ما به الامتياز. فاللونية صفة مغايرة للسوادية قائمة بها وهما موجودان، لأنه لا واسطة بين الوجود والعدم فاللونية عرض قائم بالسوادية وأيضا كون العرض حالا فى المحل ليس نفس العرض وليس نفس المحل، لصحة أن يعقلا مع الذهول عن ذلك الحلول وليس الحلول أمرا عدميا،\r__________________\r1 ـ المحل بسبب: ك ق ل م، محل لسبب: ت ج.\r2 ـ لكن لم: ت ج ق ك م، ولكن لم قلتم انه: ف، ولكن لم: لب ي، محل: ا تج ف ق ك لب ي، المحل: ل، م.\r3 ـ ذكرتموه: ك فقط، الجسم: ف.\r5 ـ تعين: ت ج ق ك لب م ي، تعين: ا ف.\r8 ـ معمر لنا: ا ت ج ق ك لب ي، معولنا: ف م.\r9 ـ تبعا له: ت ج فقط.\r10 ـ يشارك: ت م، شارك: ك.\r12 ـ للسوادية: ا ت ج ل ق ك لب ي، للسواد: ف م. بها وهما نفت ج ق ك ل ي، به وهما: ف ل م.\r13 ـ بالسوادية: ت ج ق ك لب ل م، بالسواد: ف، كون: ا ت ج ف، فكون: ق ك لب م ي.\r14 ـ ليس (2): ا ت ج، لا: ف ك ي، ق لب م.\r15 ـ الحلول (2): ف ق، ايضا: ت ج ل ك م، لب ي."], [265, "لأنه نقيض اللاحلول فيه فهو صفة قائمة بذلك العرض. ثم الكلام فيه كما فى الأول فههنا اعراض لا نهاية لها، يقوم كل واحد منها بالآخر.\rوالجواب عنها بمقدمات تقدم تقريرها. والله أعلم.\rمسئلة:\rاتفقت الأشاعرة على امتناع بقاء العرض، لأن البقاء صفة، فلو بقى العرض لزم قيام العرض بالعرض، ولأنه لو صح بقاء العرض، لامتنع عدمه، لأن عدمه بعد البقاء لا يجوز أن يكون واجبا، وإلا فقد انقلب الشيء من الإمكان الذاتى إلى الامتناع الذاتى، بل يكون جائزا فله سبب: وهو إما وجودى وإما عدمى.\rأما الوجودى فأما الموجب كما يقال إنه يفنى لطريان الضد، وهو محال لأن طريان الضد على المحل مشروط بعدم الضد الأول عنه، فلو علل ذلك العدم به لزم الدور.\rوأما المختار كما يقال: الله تعالى يعدمه، وهو محال لأن المعدم\r__________________\r1 ـ فيه (1): ج.\r2 ـ كما في الاول: ت ج ق م، كالكلام في الاول: ك، فههنا: ت ق م، فها هي: ك.\r3 ـ عنها: نسخ، عنهما: ق، بمقدمات تقدم من: ت، مر: ج: ت ف ج ق ك لب ل م ي، المقدمات قد مر: ا والله اعلم: ا فقط.\r5 ـ العرض: ت ق م، الاعراضا: ك، قالوا العرض: ف.\r7 ـ البقاء: ك ل م، بقائه: ت ج، بجوز ان: ف فقط.\r8 ـ فقد انقلب: ا ت ج، لانقلب: ف ق ك لب م ي.\r9 ـ الذاتي: ا ت ج ف ق ك لب ل ي، م، فله: ا ت ج ف ل ق ك لب ي، وله: م، فهو: ق فقط، واما: ت ج، او: م ل.\r10 ـ فاما: ت ج ق ك لب م ي، فهو اما: اف، لطريان: ك ف م، بطريان: ت ل ج.\r11 ـ طريان: ت ق م، للطريان: ك.\r12 ـ بعدمه: ت ج ف ك م، اعدمه: لب ي، محال: ك م،"], [266, "عند الاعدام، اما أن يكون قد صدر عنه أمر، أو لم يصدر. فإن صدر عنه أمر فتأثيره فى تحصيل أمر وجودى. فهذا يكون إيجادا، لا اعداما. وان لم يصدر عنه أثر، فهو محال، لأن القادر لا بد له من أثر.\rوأما العدمى فإن ينتفى لانتفاء شرطه لكن شرطه الجوهر وهو باق والكلام فى كيفية عدمه كالكلام فى كيفية عدم العرض.\rفثبت انه لو صح بقاؤه لامتنع عدمه، لكنه قد يعدم، فيمتنع بقاؤه. فقيل على الأول: لا نسلم أن البقاء عرض سلمناه ولكن لم لا يجوز قيام مثل هذا العرض بالعرض وعلى الثانى لم لا يجوز أن يجب عدمه بعد بقائه فى زمان معين. وهذا لأن العرض عندكم كان جائز الوجود فى الزمان الأول، ثم انقلب ممتنعا فى الزمان الثانى.\rفلم لا يجوز أن يبقى أزمنة كثيرة، ثم ينتهى إلى زمان يصير فيه ممتنع الوجود لعينه، وحينئذ ينتفى لا لسبب.\r__________________\rالمحال: ت، المعدم: ت ج ك لب م ي، المعدوم: ا ف ق.\r1 ـ عنه: ك ف ل م، منه: ت ج، فان: تكرر في: ق.\r2 ـ فتاثيره: ت ج ق ف ك لب ي، فتاثير: م، فتاثره: ا. فهذا: ت ك ج م،، وهذا: ق، يكون ايجادا: ت ق ك لب م ي، لا يكون هذا ايجاد: ف.\r3 ـ اثر: ا ت ج ق لب ل ي، امر: ك م، الاثر: ف.\r5 ـ فاما: في ك، فان: ت ق لب، فان: ف، فانه: م، فهو ان: ك، شرطه (1): ت ج ق ك لب م ي، الشرط: ف، لكن شرطه: ق.\r6 ـ كيفية (2): ف ك م، ت ج لب ل ي.\r7 ـ فيمتنع: ا ت ج ف ق ك لب، فامتنع: ي، لامتنع: م.\r8 ـ و: ف فقط.\r8، 9 ـ لم لا يجوز ان يجب: ت ق م، لم يجوز: ك.\r10 ـ العرض: ك.\r11 ـ الاول: ك. في (2): ا ت ج ف ق ك لب ي، ثم: م. الزمان (2): ف ج ك لب م، ت ق ل ي.\r13 ـ لعينه: ا ت ج ق ك لب ي، بعينه: ف م، ينتفى لا لسبب"], [267, "سلمنا أنه لا بد له من سبب، لكن لم لا يجوز أن ينتفى لانتفاء الشرط: وهو أن تكون الأعراض الباقية مشروطة بأعراض لا تبقى. فعند انقطاعها يفنى الباقى ولا يبقى فى دفع هذا الاحتمال إلا الاستقراء الّذي لا يفيد إلا الظن.\rثم احتجوا على جواز بقائها بأنها لما كانت ممكنة الوجود فى الزمان الأول فتكون كذلك فى الزمان الثانى، إذ لو جاز أن ينقلب الشيء الممكن لذاته فى زمان، ممتنعا فى زمان آخر، لجاز أن ينقلب الممتنع فى زمان، واجبا فى زمان آخر.\rوعلى هذا يجوز أن يكون العالم قبل وجوده ممتنع الوجود لعينه، ثم انقلب واجبا لعينه. وعلى هذا التقدير يلزم نفى الصانع، تعالى عنه علوا كبيرا.\rمسئلة:\rاتفقوا على أن العرض الواحد لا يحل فى محلين، إلا أبا هاشم: فإنه قال: التأليف عرض واحد حال فى محلين ووافقنا على أنه يستحيل قيامه بأكثر من محلين وجمع من قدماء الفلاسفة زعموا\r__________________\rت ج ف ق ك ل ي، ينتفى السبب: ا، ينتفى لا بسبب: لب، يفنى لا لسبب: م.\r1 ـ سلمنا: ت ج ق لب م ي، سلمنا ه و: ف ك.\r2 ـ لا تبقى: ا ت ك لب م ي، لا فنعى: ي.\r5 ـ لماذا ا، لو: لب م: ت ج ف ق ك ل ي، الوجود: ت فقط.\r6 ـ فتكون: ا ف ت ج ق ك ل ي، وتكون: م، في الزمان: ك م، في: ت ج ق لب ي، و: ف، الشيء: ا ت فقط.\r7 ـ لجاز: ف ق لب م ي، جاز: ا ت ك ج.\r9 ـ وعلى: ك ف م، فعلى: ت ق ج ل، ممتنع: ا ف ت ج ق ك لب ي، ممتنعا: م.\r11 ـ تعالى عنه عن ذلك: ق لب ي علوا علموا ت كبيرا: ت ق لب م ي، تعالى وتقدس: ك، وهو محال: ف."], [268, "أن الإضافة عرض واحد قائم بمحلين، كالجوار والقرب.\rلنا لو جاز فى العقل أن يكون الحال فى هذا المحل عين الحال فى ذلك المحل لجاز أن يكون الحاصل فى هذا المكان هو الحاصل فى ذلك المكان فيكون الجسم الواحد حاصلا فى مكانين. ولأنه وافق على امتناع الحلول فى الثلاثة فيطالبه بالفرق، وإحالة صعوبة التفكيك على الفاعل المختار أولى من التزام هذا المحال ..\rوأما الأجسام فالنظر فى مقوماتها وعوارضها.\rأما المقومات ففيها مسائل:\rمسئلة:\rلا شك فى تركب الأجسام المركبة عن الأجزاء، أما البسيط المحسوس فلا شك فى أنه قابل للانقسام. فالانقسام الممكن وهو إما أن يكون حاصلا بالفعل أو لا يكون كذلك وعلى التقديرين، فاما\r__________________\r3 ـ ذلك: ب ك م، ذاك: ق، المحل: ا ت ج ق لب: ف ك م ي، هو: ت ج ف ق ك لب م ي، وهو: ا.\r4 ـ المكان: ل لب فقط. المكانين: في ك.\r5 ـ فيطالبه: ا ت ق، فنطالبه: ك ج م ي، بالفرق: ل احالة: ت ج ف ق ك لب ل م ي، ان حالة: ا.\r7 ـ و: م، بالله التوفيق: ك .. اما الاجسام فالنظر: ف ق ج لب ك ي م: ت.\r8 ـ المعلومات: ت ج ق ك لب م ي، المتفومات: ف.\r10 ـ تركب: ج ك ل م، تركيب: ت، المركبة عن: ت ف ق ك لب م ي، عين: ا. الاجزاء: ت ك م، الاجرام: ق.\r11 ـ في: ا ت ج لب، ف ق ل ك م ي، للاقسام: ت ف ق ك لب م ي، للاقسام: ا فالانقسام: ق ك م ي، والانقسام: ف لب: ت، فالانقسام الممكن: ج وهو: ت، فيه: ف، فهو ج، نسخ.\r12 ـ كذلك: ت ج، وعلى: ا ت ف ق ك لب ي، فعلى: م."], [269, "أن يكون متناهيا أو غير متناه، فخرج من هذا التقسيم أربعة أقسام:\rأحدها: أن الجسم مركب من أجزاء متناهية. كل واحد منها لا يقبل القسمة أصلا، وهو قول جمهور المتكلمين.\rوثانيها: أنه مركب من أجزاء غير متناهية بالفعل، وهو قول النظام.\rوثالثها: انه غير مركب، لكنه قابل لانقسامات متناهية، وهو قول مردود.\rورابعها: إنه غير مركب لكنه لا ينتهى فى الصغر إلى حد الا وبعد ذلك يكون قابلا للتقسيم، وهو قول جمهور الفلاسفة.\rلنا وجوه:\rالأول أن النقطة بالاتفاق أمر وجودى، ولأن الخط يماس بها خطا آخر. وما يقع به التماس لا بد وأن يكون أمرا وجوديا ثم إنها\r__________________\r1، 2 ـ اربعة اقسام: ا ت، اقسام اربعة: ف ق ك لب ج م ي.\r3 ـ احدها: ت ف ق ك لب م ي، ا: ا.\r5 ـ وثانيها: ت ف ق ك لب م ي، الثاني: ج، وب: ا. بالفعل: ت ك م، بالفعل كل واحد منها لا يقبل القسمة: ق.\r7 ـ وثالثها: ت ف ق ك لب م ي، الثالث: ج، وج: ا. لاتقسامات متناهية: ك ل م، للانقسامات المتناهية: ت ج، لانقسامات المتناهية: ق.\r9 ـ رابعها: ت ف ق ك لب م ي، د: ا، الرابع: ج، الا: ت ك م، الى: ف، وبعد: ا ج ف ق ك لب ي، وهو بعد: م، بعد: ت.\r12 ـ الاول: ت ف ق ك لب م ي، ا: ا.\r12، 13 ـ بها خطا آخر: ت ج م، بانقطة غيره بها: ا، الخط بانقطه غيره: ف، بالنقطه غيره: ك لب ي، غيره: ق.\r13 ـ وما يقع ... لم انها: ا ت ج، وما به يماس الشيء غيره"], [270, "غير منقسمة بالاتفاق، ولأنها طرف الخط. فلو كانت منقسمة لكان طرف الخط أحد نصفيها، فلا يكون الطرف طرفا هذا خلف ولأن موضع الملاقات من الكرة الحقيقية المماسة للسطح المستوى الحقيقى غير منقسم، وإلا لكان المنطبق منها على المستوى مستويا فكانت الكرة مضلعة هذا خلف.\rثم هذه النقطة إن كانت متحيزة فقد ثبت الجوهر الفرد وان كانت عرضا، فمحلها إن كان منقسما لزم انقسامها بانقسام محلها وان لم يكن منقسما فهو المطلوب.\rالثانى: الحركة لها وجود فى الحاضر، وإلا لم تكن ماضية ولا مستقبلة، لأن الماضى: هو الّذي كان موجودا فى زمان حاضر. والمستقبل: هو الّذي يتوقع صيرورته كذلك وما يمتنع حضوره لا يصير ماضيا ولا مستقبلا. ثم ذلك الحاضر غير منقسم، وإلا لكان بعض أجزائه قبل البعض، فعند حضور أحد البعضين لا يكون البعض الآخر موجودا فلا يكون الموجود موجودا هذا خلف. فإذا\r__________________\rلا يكون منهما محضا وهي: ف ق ك لب ل م ي.\r1 ـ طرف الخط: ق ك لب م ي، الطرف: ت ج ف، نصفيها: ت ج ف ق ك م، نصفها: لب ي ل، هذا خلف: ا ت ج ل،: ف ق ك لب م ي.\r4 ـ فكانت: نسخ، وكانت: ت.\r5 ـ الكرة مضلعة: ت ج ف ق ك لب م ي، انكريه مضلع: ا. هذا خلف: ا ت ج ق لب، نسخ اخرى.\r6 ـ نقد: ا ج ل، ت ف ق ك لب م ي.\r9 ـ الثاني: ت ج ك لب ي، ب: ا، الثاني أن: ق ف م.\r10 ـ مستقبلا: ف فقط. الزمان الحاضر: ف لب فقط.\r11 ـ و (1) ا ت ف ك لب ي، ابو: م، وما: ك ل م، فما: ت ج.\r12 ـ غير: ت ج ف ق ك لب ي، عن: م.\r13 ـ لكان بعض: ف ق ك لب م ي، كان بعض: ا، فبعض: ت ج ل، البعضين: ت ج، النصفين: ك ل م.\r14 ـ البعض الآخر الاخير: ا: ا ت ج، النصف الاخر: ف"], [271, "الجزء الحاضر من الحركة غير منقسم، وعند فنائه يحصل جزء آخر، غير منقسم. فالحركة مركبة من أمور، كل واحد منها غير قابل للقسمة.\rثم نقول القدر المقطوع من المسافة بكل واحد من تلك الأجزاء التى لا تتجزى ان كانت منقسمة كانت الحركة إلى نصف تلك الحركة فتلك الحركة منقسمة، هذا خلف وان لم يكن منقسما فهو الجوهر الفرد.\rالثالث: لو تركب الجسم من أجزاء غير متناهية لامتنع الوصول من أوله إلى آخره بالحركة إلا بعد الوصول إلى نصفه، ولامتنع الوصول إلى نصفه إلا بعد الوصول إلى ربعه. فإذا كانت المفاصل غير متناهية، وجب أن لا يصل المتحرك إلى آخر المسافة، إلا فى زمان غير متناه وفساد اللازم يدل على فساد الملزوم لا يقال هذا إنما يلزم على قول من يقول الأجزاء التى لا نهاية لها حاصلة بالفعل.\r__________________\rق ل لب م، الاخر: ك.\r1 ـ فنائه: ا ت ج ف ق لب ك، قيامه: م ي.\r1، 2 ـ جزء آخر: ف ق ك لب م ي، اجزاء: ا، جزء: ت ج.\r2 ـ غير: ا ت ق ج ك لب ل ي، لا يقبل: ف، م.\r3 ـ للقسمه: ا ت ج ق ك لب ل م ي، القسمة: ف.\r4 ـ بكل: ت ف ج ق ك لب ي ل.\r5 ـ كانت (1): ت، كان: ك م، منقسمة: ت، منقسما: ك م، الى: ت، الى نصفه: ك م.\r7 ـ الجوهر الفرد: ت ق ج ك لب م ي، المطلوب: ف.\r8 ـ الثالث: ت ج ق م، ج: ا.\r9 ـ بالحركة: ت ج ق لب م ي، ا ف، ولا: ت ج ق لب م ي، وا: ف.\r10 ـ فاذا: ق ك ل م، واذا: ت ف ج.\r12 ـ اللازم: لب م، 5: ت ف ج ك ق ي، يدل على: ا ت ج ك ف ق لب ي، م.\r13 ـ قول: ا لب: ت ج ق ك م ي."], [272, "ونحن لا نقول به، بل الجسم عندنا شيء واحد قابل لانقسامات غير متناهية.\rلأنا نقول القول بوجود واحد يقبل القسمة باطل لوجوه:\rأحدها أن وحدته ان كانت نفس الذات أو من لوازمها امتنعت ازالتها، إلا عند عدم الذات، وإن كان من العوارض الزائلة، فهو محال. لأن القائم بما يقبل الانقسام، قابل للانقسام. فالوحدة فى نفسها قابلة للانقسام فإن قامت بها وحدة أخرى لزم التسلسل.\rوان لم تقم بها وحدة أخرى، كانت تلك الوحدة منقسمة بالفعل. فالموصوف بها كذلك فالجسم منقسم بالفعل.\rوثانيها: إنا إذا جعلنا الماء الواحد ماءين. فالماء آن الحاصلان، ان قلنا إنهما كانا موجودين قبل ذلك. فمن المعلوم بالضرورة أن أحدهما ما كان عين الثانى، فكان مغايرا له فالجز آن كانا موجودين بالفعل. وإن قلنا إنهما ما كانا موجودين قبل ذلك. كان ذلك إحداثا لهذين الماءين، واعداما للماء الأول، وهو باطل بالبديهة.\r__________________\r1 ـ شيء: ت ج ف ق ك لب ي: م.\r2 ـ بوجود واحد: ت، بوحده ما: ف ج ق ل ك لب م، وحدة ما: ي، بوحدة ما يتجزى: ج، يقبل القسمه: ت ف ل م.\r4 ـ احدها: ت، ان (1): ت ف ج ق ل م ي، وهو: ك لب، امتنعت: ت م، امتنع: ل ج ق ك.\r5 ـ ازالتها: ت ف ل ق لب ك م ي، زولها: ج، ان الهيا: ا، ازائلة: ت ف ك لب ج م ي، الزائدة: م.\r9 ـ فالموسوف: ت ق ج ك لب م ي، والموصوف: ف، منقسم: ت ج ف ق ك لب م ي، منقسمة: ا.\r10 ـ وثانيها انا: ف ق ك لب م ي، الثاني انا: ج، وب انا: ا، وثانيها: ت، فالماءاني: ك ج ل م ف: ت.\r12 ـ الثاني: ا ت ج ف ق ك لب، الذات: م، فكان: ك ج ل م ف، وكان: ت فالجزءان: ج ك ل ف م، فالجواب: ت.\r13، 14 ـ انهما .. الاول: ت ج ف ق ل ك م، ان المائين ما كانا"], [273, "وثالثها: ان كل جزء يمكن فرضه فى الجسم فهو موصوف بخاصية غير حاصلة فى الجزء الآخر لأن مقطع النصف موصوف بالنصفية، ولا يتصف بها إلا هو وكذا مقطع الثلث والربع، إذا كان لكل واحد من المقاطع الممكنة خاصية بالفعل. وعندهم أن الاختصاص بالخواص المختلفة، يوجب حصول الانقسام بالفعل، فلزم حصول الانقسامات بأسرها بالفعل.\rاحتجوا بأمور:\rأحدها: ان كل متحيز يفرض، فإن الوجه الّذي منه يلاقى ما على يمينه غير الّذي منه يلاقى ما على يساره، فيكون منقسما.\rوثانيها: إنا إذا ركبنا سطحا من أجزاء لا يتجزأ، ثم نظرنا إليه\r__________________\rموجودين فقد حدث الماءان وانهدم الماء الاول: لب، انهما كانا موجودين قبل ذلك كان احداثا لهذين الماثين واعداما للماء الاول: ي.\r1 ـ وثالثها: ت ف ق ك لب م ي، الثالث: ج، وج: ا.\r1، 2 ـ موصوف .. مقطع النصف: ت ج ق لب ل م، موضع النصف: ي، ف.\r2 ـ بخاصية: ت ق ج ك لب م، بخاصة: ا، الخاصة: ي.\r3 ـ هو وا ت ج ق لب ل ي، هو: ف ك، مورد القسمة و: م، هكذا في: ك، اذا: ت، واذا: ك ج ل م.\r4 ـ خاصية: ت ج ف ل ك، خاصيته: ا ق، خاصة: م. وعندهم: ا فقط.\r5 ـ فلزم: ت لب ي، فيلزم: ج ف، لزم: ق ك م.\r7، 8 ـ بامور احدها ا: ا: ا ت ج ف ك لب ي، بوجوه احدها: ق م.\r8 ـ فان ا: ت م، فا: ك، منه: تاخر في (1) بعده يلاقي.\r9 ـ منه: ا فقط، يلاقي: ق.\r10 ـ ثانيها: ف ق ك لب م ي، الثاني: ج، ب: ا، ثالثها: ت، سطحا: في ت ج: خطا من اجزاء: ا ت ف ج ق ك لب ي، فوق آخر: م."], [274, "أبصرنا أحد وجهيه دون الثانى. فالوجه المرئى غير الوجه الّذي ليس بمرئى فيكون منقسما.\rوثالثها: إنا إذا ركبنا خطا من ستة أجزاء، ووضعنا فوق طرفه الأيمن جزأ، وتحت طرفه الأيسر جزأ، ثم تحركا إلى أن يصل كل واحد منهما إلى آخر المسافة، فلا بد وأن يمر كل واحد منهما بالآخر. ولا يمكن ذلك إلا بعد أن يتحاذيا، وموضع التحاذى متصل الثالث والرابع. وإذا وقع الجزء على ذلك الموضع، فقد ماس بكل واحد من نصفيه نصف كل واحد منهما، فيلزم التجزئة.\rالجواب عن الكل أن ما ذكرتموه يدل على تغاير جهات الجزء، وذلك لا يوجب القسمة فى الذات، فإن مركز الدائرة يحاذى جملة أجزاء الدائرة، مع أن المركز نقطة غير منقسمة.\rمسئلة:\rزعم ابن سينا أن الجسم مركب من الهيولى والصورة. ومعناه:\r__________________\r1 ـ اليه ابصرنا: ا ت ج ف ق لب ي، اليه رايتا: ك، راينا: م.\r1 ـ فالوجه: ا ت ج، واالوجه: ف ق ك لب م ي، الوجه ك فقط.\r3 ـ ثالثها: ت ف ق ك لب م ي، ج: ا، اذا: ا ت ج ل، لو: ف ق ك لب م.\r4 ـ تحركا: ت ج ف ق لب م ي، حركتا: ا، تحرك: ك.\r5 ـ و: ا ت ج ف ق ك ل لب ي، م، في مكان يمن ثم في: ق.\r6 ـ وموضع: ك م، وضع: ت.\r7 ـ واذا: ف ك لب ل م ي، فاذا: ا ق، اذا: ت ج. بكل: ا ت ج ف ق ك لب، لكل: م، كل: ي ل.\r8 ـ نصفيه: ت ج ف ق ك لب ل م ي، نصفه: ا، منهما: ت ج ك لب م ي، منها: ف ق.\r9 ـ عن الكل: ا ت ج ف ق ك ل لب ي،: م، والجواب: ق، ان ما: ك م، انما: ت.\r12 ـ و (2): ف."], [275, "إن التحيز صفة حالة فى الشيء فالتحيز هو الصورة، ومحله هو الهيولى. واحتج عليه بناء على نفى الجوهر الفرد بأن الجسم فى نفسه واحد، وهو قابل للانفصال. والقابل للشىء موجود مع المقبول لا محالة والاتصال لا يبقى مع الانفصال. فالقابل للانفصال شيء مغاير للاتصال.\rجوابه لم لا يجوز أن يقال الانفصال هو التعدد والاتصال هو الوحدة. فالجسم إذا انفصل بعد اتصاله، كان معناه: إنه صار متعددا بعد أن كان واحدا فالطارى والزائل هو الوحدة والتعدد، وهما عرضان والمورد هو الجسم.\rمسئلة:\rزعم ضرار والنجار: أن ماهية الجسم مركبة من لون، وطعم، ورائحة، وحرارة، وبرودة، ورطوبة، ويبوسة، وهو باطل. لأن المتحيزات متساوية فى ماهية التحيز، ومتباينة بألوانها، وطعومها، وروائحها، وما به الاشتراك غير ما به الامتياز. فالتحيز ماهية مغايرة لهذه الصفات.\r__________________\r1 ـ الشيء: ا ف ك، شيء: ت ج ق لب ل م ي، فالتحيز: ت ق ك لب م ي، فالمتحيز: ف، هو (2): ا ت ف ك لب ل ي، ق م.\r2 ـ نفي: ك، بان: ت ك لب م ي، فان: ف.\r4 ـ المقبول: ا ت ج ف ق ك لب ي، الهيولي: م.\r5 ـ شيء: ت ك م، شيء فيه: ق.\r4، 6 ـ القابل للانفصال ... الانفصال: ق.\r9 ـ عرضان: ت ج ق ك مشطوب لب م، عارضان: ف ي هامش ك.\r12 ـ او رطوبة او: في: ا، لو برودة ورطوبة او: لب.\r13 ـ متنانية: في: ا.\r14 ـ «وروائحها» قبل «وطعومها» في: ك م، طعومها وروائحها: ا ت ج ف ق ل لب ي، فالتحيز: ت ج م، فالتحيز: ف ق ك لب ل ي."], [276, "النظر الثانى فى العوارض:\rمسئلة:\rاختلف أهل العالم فى حدوث الأجسام. والوجوه الممكنة فيه لا تزيد على أربعة: فإنه إما أن يكون محدث الذات والصفات، أو قديم الذات والصفات، أو قديم الذات محدث الصفات، أو بالعكس.\rأما الأول فهو قول الجمهور من المسلمين، والنصارى، واليهود، والمجوس.\rوأما الثانى فهو قول ارسطو، وثاوفرسطس، وثامسطيوس وبرقلس. ومن المتأخرين أبى نصر الفارابى وأبى على ابن سينا. وعندهم ان السموات قديمة بذواتها وصفاتها المعينة، لا الحركات والأوضاع فإن كل واحد منها حادث ومسبوق بآخر لا إلى أول.\rوأما العناصر فالهيولى منها قديمة بشخصها، والجسمية قديمة\r__________________\r1 ـ النظر الثاني في العوارض: ت فقط، في العوارض فقيه مسائل: ج.\r4 ـ فانه اما: ت ج ق ف ل م، فاما: ك.\r5 ـ والصفات .. محدث: ت ق ك لب م ي، محدث: ف.\r7 ـ الاول: ت ج ف ق ك لب م ي، ا: ا، جمهور: ف فقط.\r9 ـ الثاني: ت ق ك م، ب: ا، ارسطو: ا ت ج ك ل ف، ارسطاطاليس: ق م، في: ف ل: الا وفوسطس.\r10 ـ في: ك زاد: وابند فلس بعد «برفلس». الفاريابي: ا، ي.\r11 ـ فعندهم: ا فقط. بذواتها: ا ت ج ف ق ك لب، بذاتها: م ي، وانها: ل، لا: ق ك، الا: م.\r11، 12 ـ لا الحركات .. الى اول ـ: ت ج ل فقط.\r12 ـ باخر: ق لب م، بالاخر: ف ك، بالاخرى: ا، ي. لا الى اول: ي.\r13 ـ فالهيولي منها: ا ت ج ف ق ل ي، فهيولي منها: لب،"], [277, "بنوعها، وسائر الصور قديمة بجنسها، أى كان قبل كل صورة صورة أخرى إلى غير بداية.\rوأما الثالث فهو قول الفلاسفة الذين كانوا قبل ارسطو بالزمان كثاليس، وانكساغورس، وفيثاغورس وسقراط، وقول جميع الثنوية كالمانوية، والديصانية، والمرقيونية، والماهانية ثم هؤلاء فريقان:\rالفرقة الأولى: زعموا أن تلك المادة جسم. ثم زعم ثاليس: انه الماء، لأنه قابل لكل صورة، وزعم إنه إذا انجمد صار أرضا. وإذا لطف صار هواء ومن صفوة الهواء تكونت النار، ومن الدخان تكونت السموات.\rويقال إنه أخذه من التوراة، لأنه جاء فى السفر الأول منه أن الله تعالى خلق جوهرا، فنظر إليه نظر الهيبة، فذابت أجزاؤه،\r__________________\rفالهيولي فيها: ك، والهيولي فهي: م.\r1 ـ كان: ا ت ج ف ق ك لب ي، كانت: م.\r2 ـ الى غير: ا ت ج، لا الى: ف ق لب م ي، البداية: ف فقط.\r3 ـ الثالث: ت ج ف ق ك لب ل م ي، ج ا، ارسطو ا ت ل، ارسطاطاليس: ف ج ق ك لب م، بالزمان: ت فقط.\r4 ـ وفيثاغورس: ا ت ج ف ق ك لب ل: م.\r5 ـ المرقيونيسة: ا ت ق، المرقونية: ف ج ك لب ل م المرقيون المتوفى حوالى مائة وخمسين ميلادية.\r7 ـ الفرقة: ت، الاولى: ت ج ف ق ك لب ل ي، ا، الاولى الذين: م ثم: ا ي.\r8 ـ صورة: ت ج ك، الصور: م ل ف.\r9 ـ صفوة: ف ق ك ل لب م ي، صفو: ت ج، صفة: ا.\r11 ـ يقال: ت ج ق ل ك م، قيل: ف لب ي، اخذه: ت ف ك م، اخذ: ي منه: ا ت ج لب ل، منها: ف ق ك م ي.\r12 ـ فنظر: ت ق ك لب م ي، ثم نظر: ف، نظر: ا ت ج ف ق ك لب ي، بنظر: م."], [278, "فصارت ماء. ثم ارتفع منه بخار كالدخان، فخلق منه السموات، وظهر على وجه الماء زبد، فخلق منه الأرض. ثم أرساها بالجبال.\rوزعم انكسيمانس أنه الهواء، وكون النار من لطافته، والماء والأرض من كثافته.\rوزعم ابريليطس أنه النار، وكون الأشياء عنها بالتكاثف.\rوآخرون قالوا: إنه الأرض، وكون الأشياء عنه بالتلطيف.\rوقال آخرون إنه البخار، وكون الهواء والنار عنه بالتلطيف والماء والأرض بالتكثيف.\rوعن انكساغورس أنه الخليط الّذي لا نهاية له، وهو أجسام غير متناهية. وفيه من كل نوع أجزاء صغيرة، مثلا منه أجزاء على طبيعة اللحم. وأجزاء على طبيعة الخبز.\r__________________\r1 ـ بخار: ت م، بخار: ك.\r2 ـ وظهر: ا ت ج ك، فظهر: م.\r3 ـ انكسيمانس: ف، انكسيمايس: ت ج ق، انكسمانيس: م، انكسيمايس: ك ي، انكساوس: ل، انكسيايس: لب، انكيايس: ا.\r5 ـ ابريليطس ابر قليطس: ص: ق ك لب م، فرطس ل، ابروطيطس: ت، افرسطيس: ف، فاقروسطس: ي هامش ك، ابتذقلس: ج.\r5، 6 ـ بالتكاتف ... عنه: ق.\r6 ـ بالتلطيف: ت ك لب م ي، بالتلطف: ا ج ف ق ل.\r7 ـ قال اخرون: تكرر في ك، اخرون قالوا: ق، اخرون: ت ج ف م، عنه: ك م، تحته: ت بالتلطيف: ت ق ك لب م ي، بالتلطف: ا ج ف.\r8 ـ بالتكثيف: ت ف ق ك لب م ي، بالتكثف: ا ج.\r10 ـ فيه: ا ت ج ف ق ك لب ي، منه م، مثلا منه: ت ف، مثلا فيه: ا، مثلا قبة: ج لب ي، مثلا فيه: ق ك، متلا لقيه: م.\r11 ـ اللحم: ا ف ق لب ل ي، الخبر: ج ك م، اللحم"], [279, "فإذا اجتمع من تلك الأجزاء شيء كثير وصار بحيث يحس ويرى ظن أنه حدث. وهذا القائل بنى هذا المذهب على انكار المزاج، والاستحالة. وقال بالكمون والظهور، وزعم بعض هؤلاء: ان ذلك الخليط كان ساكنا فى الأزل، ثم ان الله تعالى حركه، فتكون منه هذا العالم.\rوزعم ديمقراطيس أن أصل العالم أجزاء صغيرة كرية الشكل، قابلة للقسمة الوهمية، دون القسمة الانفكاكية، متحركة لذواتها حركات دائمة. ثم اتفق فى تلك الأجزاء إن تصادمت على وجه خاص، فحصل من تصادمها على ذلك الوجه هذا العالم على هذا الشكل، فحدثت السموات والعناصر، ثم حدث من الحركات السماوية امتزاجات هذه العناصر. ومنها هذه المركبات.\rوزعمت الثنوية أن أصل العالم هو النور والظلمة.\r__________________\rواجزاء على طبيعة: ت، الخبز: ا ف ق ل لب ي، اللحم: ج ك م.\r1 ـ تلك: ت لب ك م ي، ذلك: ف، كثير: ت ج ق ك ل لب م ي، كثيرة: ف، و (1): م فقط.\r2 ـ هذا المذهب على: ت ج ق ك ي، هذا على: ف، على هذا المذهب: لب م، على المذهب في: ل.\r4 ـ فتكون: ت ج ق، فكون: ك لب م ي، وكون: ف، مته: ك فقط.\r6 ـ وزعم: ت ج ف ق ك لب ي، فزعم: م، ديمقراطيس ت ج ك ل لب م، ديمقراطاس: ف، دي متراطيس: ي، ان اصل: ت ج ف ق ك لب ل م ي، اهل: ا، صغيرة: ت ق ك لب م، صغيرة و: ف، ي، كربة: ج ك ل م، كريهة: ت.\r7 ـ قابلة: ت ج ف ق ك لب م ي، قابل: ا، لذواتها: ت ج ق ك ل لب، لذواتها وانها: ا ف، لذاتها: م ي.\r8 ـ تصادمت: ا ت ج ف ق ك لب ي، تصادفت: م.\r9 ـ تصادمها: ا ت ج ف ق ك لب ي، تصادفها: م.\r10 ـ و: ت ج ك م، ثم: ق، ثم: ت ك م، و: ق.\r12 ـ و: ت ج ف ك لب م، ووجد: ق ي.\r13 ـ وزعمت: ت ج ف ق لب م ي، فزعمت: ا، زعمت: ك"], [280, "الفرقة الثانية: الذين قالوا: أصل العالم ليس بجسم. وهم فريقان:\rالفرقة الأولى: الحرنانية. وهم الذين أثبتوا القدماء الخمسة: البارى، والنفس، والهيولى والدهر، والخلاء.\rفقالوا: البارى تعالى تام العلم والحكمة لا يعرض له سهو، ولا غفلة، ويفيض عنه العقل كفيض النور عن القرص، وهو الله تعالى يعرف الأشياء معرفة تامة.\rوأما النفس، فإنه يفيض عنها الحياة فيض النور عن القرص لكنها جاهلة لا تعلم الأشياء ما لم تمارسها. وكان البارى تعالى عالما بأن النفس ستميل إلى التعلق بالهيولى، وتعشقها، وتطلب اللذة الجسمية، وتكره مفارقة الأجسام، وتنسى نفسها.\r__________________\rوزعم: ل، في ك: الظلمة والنور.\r1 ـ الثانية: ت ف ك لب م ي، ب: ا.\r2 ـ الفرقة الاولى: ف ق لب م ي، الفرقة: ا، احدهما: ت ج، الحرنانية: ا ت ج ف ك لب ي، الحرانيون: ل، ا والنسبة الى حران، الحرنانيون: ق، الجرمانية: م.\r4 ـ الباري: ا ت ف ك لب ي، الباري تعالى: م.\r4، 5 ـ الباري ... فقالوا: ق.\r5 ـ نام: ا ت ج ف ق ك لب ل ي، باب: م، والحكمة: ت ج ق ك لب م ي، والقدرة والحكمة: ف، العلم بعد الحكمة في ك.\r6 ـ تعالى: ت ج لب م، الله: ف، تعالى وتقدس: ق نام العلم: ق ي ل، ك.\r8 ـ و: ف، فانه: ت ف ق ك لب م ي، فانها: م.\r10 ـ ستمبل: ت ج ف ق ك ل، تميل: م ي، تحميل: م، مستميل: لب.\r11 ـ الجسمية: ت ج ف ل لب ي، الجسمانية: ك، الحسبة: ق م."], [281, "ولما كان من شأن البارى تعالى الحكمة التامة، عمد إلى الهيولى بعد تعلق النفس بها فركبها ضروبا من التركيب، مثل السموات والعناصر. وركب أجسام الحيوانات على الوجه الأكمل. والّذي بقى فيها من الفساد، فذلك لأنه لا يمكن ازالته. ثم إنه سبحانه وتعالى أفاض على النفس عقلا وإدراكا، وصار ذلك سببا لتذكر عالمها وسببا لعلمها بأنها ما دامت فى العالم الهيولانى لم تنفك عن الآلام وإذا عرفت النفس ذلك، وعرفت أن لها فى عالمها اللذات الخالية عن الآلام، اشتاقت إلى ذلك العالم، وعرجت بعد المفارقة، وبقيت هناك أبد الآباد فى نهاية البهجة والسعادة.\rقالوا وبهذا الطريق زالت الشبهات الدائرة بين القائلين بالقدم والحدوث. فإن أصحاب القدم قالوا: لو كان العالم محدثا، فلم أحدثه الله تعالى فى هذا الوقت المعين، وما أحدثه قبل ذلك ولا بعده.\r__________________\r1 ـ و: ا ت ف ق ك لب ي، ف: م، شان: ت، سس: ا لب، سبوس: ف، وصف: ق ك ي، شئون: م، عمدا: ا ق فقط.\r2 ـ التركيب: ت ف لب، التراكيب: ق ك ج لب م ي.\r4 ـ فذلك: ك م، بذلك: ت، لانه: ف فقط، يمكن: ت ج ف ق ك م، يمكنه: لب ي، ازالتها: ف فقط، سبحانه و: ا ت ف ق لب ي، ج ك ل م.\r5 ـ لتذكر: ت ج ك ل، لتذكرها: م، ليذكرها: ق ف.\r6 ـ العالم الهيولاني لم: ا ت ج ف ق ك لب ي، في عنا الهيولاني لم: ل، عالم الهيوني لا: م.\r7 ـ عرفت النفس ذلك و: ا فقط.\r8 ـ الالام: ت ج ف ق ل م، الالم: ا ك. عرجت: ت ج ق لب ي، عرجت عليه: م، عرجت اليه: ل، جرعت: ا، عوجه: ف، عجزت: ك.\r9 ـ ابد: ا ت ج ف ق ك لب ل ي، الى ابد: م، الهجة: ف فقط.\r11 ـ القدم: ت ج ف ق ك لب م ي، القديم: ا، محدثا: ت ج ك ل م، حادثا: ف ق لب ي.\r12 ـ احدثه: ل ج نسخ، احدث: ت، الله تعالى: ت ج ل."], [282, "وان كان خالق العالم حكيما، فلم ملأ الدنيا من الآفات.\rوأصحاب الحدوث قالوا: لو كان العالم قديما لكان غنيا عن الفاعل. وهذا باطل قطعا، لما نرى أن آثار الحكمة ظاهرة فى العالم. وتحير الفريقان فى ذلك.\rوأما على هذا الطريق، فالإشكالات زائلة لانا لما اعترفنا بالصانع الحكيم، لا جرم قلنا بحدوث العالم. فإذا قيل: ولم أحدث العالم فى هذا الوقت؟.\rقلنا: لأن النفس إنما تعلقت بالهيولى فى ذلك الوقت، وعلم البارى تعالى ان ذلك التعلق سبب الفساد، إلا أنه بعد وقوع المحذور، صرفه إلى الوجه الأكمل بحسب الامكان وأما الشرور الباقية، فإنما بقيت، لأنه لا يمكن تجريد هذا التركيب عنها، بقى هاهنا سؤالان:\r__________________\rف ق، الله: ك، تعالى: م، و (2): ا ت ج ف ق ك ل لب ي، م.\r2 ـ الفاعل: ت ج ف ق ك لب م ل، العاجل: ي، لما نرى: ت ج ف ق ل، الا ترى: ا ي، كما نرى: ك.\r5 ـ فالاشكالات زائلة: ت ج ك م، فلا اشكال: ف ق لب ل ي.\r6 ـ فلا جرم: ف: ك، فاذا: ت ق م، فان: ك.\r7 ـ احدث العالم: ت م، احدث الله العالم: ج، حدث العالم: ل، احدث: ف، العالم في هذا الوقت: ت ق لب م ي، في هذا الوقت: ك، في هذا الوقت المعين وما احدثه قبل ولا بعد ا: ف.\r8 ـ انما: ت ج ق ك، بما: ا ف لب ي، لما: م.\r9 ـ الباري: ت ق م، الله: ك، تعالى: ت ك لب م، ف ي.\r10 ـ المحذور: ت ق ك لب م ي، المحضور: ف، الشرورن انما ف ج ق ك لب م ي، السرور: ا ت.\r11 ـ فانما: ت ق ك لب م ي، قهى انما: ف تجريد: ا ت ج ف ق ك لب ل ي، تحديد: م.\r12 ـ و: ل بقى ههنا: ف ج ك ل م، يقى هنا: ت، بقى"], [283, "أحدهما: ان يقال لم تعلقت النفس بالهيولى، بعد أن كانت غير متعلقة بها. فإن حدث ذلك التعلق لا عن سبب فجوز حدوث العالم بكليته لا عن سبب.\rوالثانى أن يقال: فهلا منع البارى تعالى النفس من التعلق بالهيولى؟ أجابوا عن الأول بأن هذا السؤال غير مقبول من المتكلمين. لأنهم يقولون القادر المختار، قد يرجح أحد مقدوريه على الآخر من غير مرجح. فهلا جوزوا ذلك فى النفس.\rوغير مقبول أيضا من الفلاسفة. لأنهم جوزوا فى السابق أن يكون علة معدة للاحق فهلا جوزوا أن يقال: النفس قديمة ولها تصورات متجددة، غير متناهية. ولم يزل كل سابق علة للاحق، حتى انتهت إلى ذلك التصور الموجب لذلك التعلق.\rوأجابوا عن السؤال الثانى بأن البارى تعالى علم بأن الأصلح\r__________________\rعليها: لب مي، فبقى عليها: ف.\r1 ـ بها: ف ق م، به: ا ك لب ل: ت ج ي، فان حدث: ت ج ق ك م، فان ثبت: ا لب ي، واذا جوزت حدوث: ف، فجوز حدوث: ج ك م، تجوز حدوث: ت، وجوز حدوث: ق.\r4 ـ و: ف، تعالى: ت ج ف ق ك م، ا لب ي.\r5 ـ من: ا ت ج ف ق ك لب ل ي، في: م.\r6 ـ القادر: ق، مقدورية: ج ك ف م، مقدورانه: ت ل.\r7 ـ الاخر: ج ك ف م، الباقي و: ت ل. مرجح: ت ج ق م، ترجح: ك.\r8 ـ ايضا: ق.\r9 ـ معدة: ا ت ج ف ق ك لب ل ي،: م.\r10 ـ تصورات: ا ت ج ف ق ك لب ل ي، تصويرات: م. علة: ت ج ف ق ك لب م ي، عليه: ا.\r11 ـ تعلق في: ق.\r12 ـ بان (1): ت م ج ي ل، ان: ا ف ق ك لب، بان (2)"], [284, "للنفس أن تصير عالمة بمضار هذا التعلق حتى انها بنفسها تمتنع عن تلك المخالطة.\rوأيضا فالنفس بمخالطتها الهيولى تكسب من الفضائل العقلية ما لم تكن موجودة لها. فلهذين الغرضين لم يمنع البارى تعالى النفس من التعلق بالهيولى.\rالفرقة الثانية: أصحاب فيثاغورس، وهم الذين قالوا: المبادي هى الأعداد المتولدة عن الوحدات. قالوا: لأن قوام المركبات بالبسائط، وهى أمور كل واحد منها فى نفسه واحد. ثم تلك الأمور إما أن تكون لها ماهيات وراء كونها وحدات أو لا تكون. فإن كان الأول كانت مركبة لأن هناك تلك الماهية مع تلك الوحدة. وكلامنا ليس فى المركبات، بل فى مباديها.\r__________________\rت م، ان: ك.\r1 ـ تصير شالة: ا ت ج ف ق ك لب ي، تتصور عالمها: م. بمضار: ت ج ق ك لب ي، بمضاد: ف م، عن ا ت ج ف ك ل لب ي، من: م، ق.\r3 ـ فالتعس بخالطتها .. تكب: ك ف م، بمخالطة الهيولي تكتسب: ج، فالنفس لمخالطة .. تكتسب: ت، فان النفس بمخالفتها بالهيولي: ل.\r4 ـ تكن موجودة: ا ت ف ج ق ك لب ل ي، يكن موجودا: م، الترضين: ا ت ج ف ق ك لب ل ي، الغرضين: م، تعالى ا ت ج ق لب ي، ك ف م.\r6 ـ الثانية: ت ج ف ق ك لب ل ي، الثانية هم: م، ج، ا ب: مشطوب في ا. فيثاغورس ت ج ك ف ل ق، فيثاغورث: م، المبادي: ت ج ق ك لب ل م ي، بان الباري: ف.\r7 ـ هي: ت ق ج ك لب م ل ي، من: ج ل، عن: ا ت ج ف ق ل ك لب ي، في: م، فوام: ت ق ج ك لب م ي، قوى ف.\r8 ـ واحد تقدم في: ك على في نفسه.\r9، 10 ـ فان كان الاول: ج ك م، فلو كانت الاولى: ت:"], [285, "وان كان الثانى كانت مجرد وحدات، وهى لا بد وأن تكون مستقلة بأنفسها، وإلا لكانت مفتقرة إلى الغير، فيكون ذلك الغير أقدم منها وكلامنا فى المبادي المطلقة، هذا خلف. فإذا الوحدات أمور قائمة بأنفسها، فإن عرض الوضع للوحدة صارت نقطة، فإن اجتمعت نقطتان حصل الخط، فإن اجتمع خطان حصل السطح. وإن اجتمع سطحان حصل الجسم، فظهر أن مبدأ الأجسام الوحدات.\rوأما القسم الرابع: وهو أن يقال: العالم قديم الصفات محدث الذات، فذلك مما لا يقول به عاقل. وأما جالينوس فإنه كان متوقفا فى الكل. لنا إن كانت الأجسام أزلية لكانت فى الأزل اما متحركة أو ساكنة. والقسمان باطلان. فالقول بأزليتها باطل.\r__________________\r1 ـ كانت: ت م، كان: ف ق ك لب ل ي.\r2 ـ لكانت: ت ج ف قق ك لب م ي، كانت: ا.\r3 ـ اقدم: ت ج ف ق ك لب ل م ي، اقدام: ا. وهذا في: ا. الوحدة في: ا.\r4 ـ فان: ك م ل ف، وان: ق، فاذا: ج.\r5 ـ فان (1): ك لب م ي، وان: ت ج ف ل ق، خطان: ت ج ق ك، الخطان: م ل.\r6 ـ وان: ت ج ف ق لب ل، فان: ك م ي سطحان: ا ت ج ك ي، السطحان: ف ق لب ل م.\r7 ـ الواحدات: في ك.\r8 ـ و (1): ك، الرابع: ت ج ف ق ك لب ل م ي، ا: العالم: ف فقط.\r9 ـ وذلك في: ق ك، مما: ك م، ما: ت، لا يقول به عاقل: ت ج ق ك ل لب ي، لم يقل به عاقل: فم، لا يقوله عاقل: م، لا يقول به: ا، فانه: ت ج ف ق ك لب ي، فقد: م، كان: ي فقط.\r10 ـ الكل: ت ج ق ل م، ذلك: ك، ان لو: ج ك لب ل ي: كانت ... ازلية: ا ت ف ق ك لب ي، ان الاجسام لو كانت ازلية: م.\r11 ـ ساكنة او متحركة: في: ف."], [286, "بيان الحصر: أن الجسم ان كان مستقرا فى مكان واحد أكثر من زمان واحد، فهو الساكن. وإن لم يستقر كذلك كان متحركا. وإنما قلنا: أنه لا يجوز أن يكون متحركا لوجهين:\rالأول: إن ماهية الحركة حصول أمر بعد فناء غيره فماهيتها تقتضى المسبوقية بالغير. والأزلية ماهيتها تقتضى اللامسبوقية بالغير. فالجمع بينهما متناقض.\rالثانى: وهو أن كل واحد من الحركات محدث، فهو مفتقر إلى موجد فكل واحد منها مفتقر إلى الموجد فإذن لكل الحركات موجد مختار. وكل ما كان فعلا لفاعل مختار فلا بد له من أول. فلكل الحركات أول، وهو المطلوب وإنما قلنا إنها ليست ساكنة لوجهين:\rالأول: أنها لو كانت ساكنة لكان اما أن يصح عليها الحركة أو\r__________________\r2 ـ كان متحركا: ت ق ك م ي، فهو المتحرك: ج ف، بل كان منتقلا من حيز الى حيز فهو المتحرك: لب.\r3 ـ لوجهين: ك م، كالوجهين: ت.\r4 ـ الاول: ف ق ك لب م ي، احدهما: ت ج ل، ا: ا.\r5 ـ مسبوقية: ا ت ج ف ق ك لب، مسبوقيته: م.\r5، 6 ـ والازلية ... بالغير: ي.\r6 ـ فالجمع: ا ت ج ف ق ي، والجمع: ك م.\r7 ـ والثاني: ت ف ق ك م، وب: ا، الثاني: ج.\r8 ـ موجد: ج ك م، موجده: ت، الى الموجد: ف ق لب ل ي، فكل واحد ... فاذن لكل: ت ج، فكل واحد وكل ما كان واحد: ي منها مفتقر الى الموجد فكلها مفتقر الى الموجد فلكل فكل: ي: لب ي، وكل ما كان كان: ك كل واحد منها منه: ك م مفتقر الى الموجد فكله مفتقر الى الموجد: ف ق ك فلكل: ف ق ك م، فلكل: ل.\r9 ـ وكل: ا ت ج ف ق ك لب ي، فكل: م، فعلا لفاعل ج ك م، فعل فاعل: ت. له: ف فقط.\r10 ـ وهو المطلوب: ت ج ق ل، ليست: ا ت ف ق ك لب ج ي، لا يجوز ان تكون: م.\r11 ـ الاول: ت ج ف ك لب م ي، ا: ا، احدها: ق."], [287, "لا يصح والأول محال. لأن صحة الحركة عليها يتوقف على صحة وجود الحركة فى نفسها. وقد دللنا على أن وجود الحركة الأزلية محال. فثبت أنه لا تصح الحركة عليها، فذلك الامتناع ان كان لازما للماهية، وجب أن لا يزول البتة، فوجب أن لا تصح الحركة على الأجسام فيما لا يزال. هذا خلف.\rوإن لم يكن من لوازم الماهية أمكن زواله فيكون الحركة عليه جائزة وقد أبطلناه.\rالثانى: أن السكون أمر ثبوتى على ما دللنا عليه فنقول: لو كان ذلك السكون قديما لامتنع زواله، لكنه يزول، فليس بقديم.\rبيان الملازمة أن القديم إن كان واجبا لذاته امتنع عدمه وإن لم يكن واجبا لذاته، افتقر إلى مؤثر ولا بد من الانتهاء إلى الواجب لذاته قطعا للتسلسل على ما سيأتى.\r__________________\rلكان: ك م، لكانت: ت.\r1 ـ يتوقف: ا ت ج ف ق ك لب ي، متوقف: م.\r2 ـ على: ا ت ف ق ك لب ي،: م، وجود (2): ي.\r3 ـ انه: ا ت ج ف ق ك لب ي، ان: م.\r5 ـ على الاجسام: ت ج ق ك لب م ي، عليها: ف.\r6 ـ زواله فيكون: ا ت ج ف ق ك لب ل ي، زوالها ويكون: م.\r7 ـ عليه: ت ج ق لب م ي، عليها: ف ك.\r8 ـ الثاني: ت ف ق ك لب م ي، ب: ا، فنقول: ك م، فيقول: ت.\r11 ـ الملازمة: ت ج ق ك ل م، التلازم: ف لب ي، ان (2): ك ل ف م، لو: ت ج، امتنع: ك ل ف م، لامتنع: ت ج، عدمه: ت ق ك لب م ي، زوانه: ف.\r12 ـ ولا: ا ت ج ف ق لب ي، فلا: م.\r13 ـ على ما سياتي: ق ل م ج هامش، على ما سياتي ان شاء الله تعالى: ك، ت."], [288, "وذلك الواجب اما أن يكون مختارا أو موجبا لا جائز أن يكون مختارا لأن فعل المختار محدث لاستحالة إيجاد الموجود. والقديم ليس بمحدث، فتعين أن يكون موجبا. فإن لم يتوقف تأثيره فيه على شرط لزم من وجوب ذلك المؤثر وجوب ذلك الأثر.\rوإن توقف على شرط، فذلك الشرط ان كان ممكنا، عاد التقسيم فى الحاجة، وإن كان واجبا لزم من وجوب العلة والشرط امتناع زوال ذلك القديم. واما أنه يمكن عدم السكون فهو مشاهد فى الفلكيات والعنصريات. ولا جسم الا هذين عند الخصم. ومن أراد تعميم الدلالة، فلا بد له من بيان تماثل الأجسام.\rولما ثبت فساد كون الجسم متحركا أو ساكنا فى الأزل فقد ثبت أن الجسم يستحيل أن يكون أزليا فإن قيل الدعوى متناقضة لوجهين:\r__________________\r1 ـ وذلك: ا ت ج ف ق ك لب ل ي، فذلك: م، في: ك: مرحبا ومختارا.\r1، 2 ـ او موجبا لا جائز ان يكون مختارا: ت.\r2 ـ الموجود: ا ت ج ف ق ك لب ل ي، الموحد: م.\r4 ـ ذلك (2): ت ج ف ق لب، ك م.\r3، 5 ـ فان لم يتوقف ... من: ك ... وان فان: ك على شرط: ت ج ف ق ك، فان لم يتوقف ... وان كان يتوقف تاثيره فانه على شرط: لب، فان كان يتوقف تاثيره فيه على شرط: ي.\r6 ـ من: ا ت ج ف ق ك لب، في: م، العلة: ت ج ف ك لب م ي، العلم: ا.\r8 ـ له: ت ق ك م، ف لب ج ي، بيان: نسخ، بيان دلائله: ف.\r10، 11 ـ فقد: اف ق ك لب ي ثبت .. يستحيل: ا ت ج ف ق ك لب ل ي، صار الجسم مستحيلا: م.\r11 ـ اوليا: ت ج ق ك م، الجسم ازليا: ا ف لب ي، فان: ا ت ف ق ك ج لب ل ي، م، مشتاقضة: ت ف ج ق ك لب م ي، متناقض: ا."], [289, "الأول: ان امكان وجود العالم ليس له أول، وإلا فقد كان قبل ذلك محالا لذاته، ثم انقلب ممكنا لذاته لكن ذلك باطل، لأن الإمكان للممكن ضرورى فيكون العالم قبل ذلك الوقت ممتنع الاتصاف بالامكان لذاته ثم صار واجب الاتصاف به لذاته.\rوإذا جوزتم ذلك فجوزوا أنه كان ممتنع الاتصاف بالوجود لذاته، ثم صار واجب الاتصاف به لذاته، ويلزمكم نفى الصانع وهو محال. ولأنه لو جاز أن ينقلب الممتنع لذاته ممكنا لذاته لجاز ذلك فى شريك الإله وفى الجمع بين الضدين، وهو يرفع الأمان عن القضايا العقلية.\rوإذا ثبت أنه لا أول لإمكان وجود العالم، كان القول بأنه ممتنع\r__________________\r1 ـ الاول: ت ف ق ك لب ل م ي، ا: ا، احدهما: ج، ان: ك، له اول: ا ت ج ف ق ك لب ي، للاول: م، فقد: ك.\r2 ـ قبل: ت فقط، لذاته (2): ف ك، ت ج ق لب م ي، باطل: ك ف م، محال: ت ج ل.\r3 ـ للممكن: ت ج ف ك ل، للمكن: م، قيل: ا ت ج ف ق ك لب ل ي، مثل: م. الوقت: ف فقط.\r4 ـ بالامكان لذاته: ت ج، لذاته بالامكان: ف ق ك لب ي، بالوجود لذاته بالاماكان: م.\r5، 6 ـ بالوجود لذاته: ت ج ف ق ك لب م ي، لذاته بالامكان.\r6 ـ ويلزمكم: ك ف م، فيلزمكم: ت ج ل.\r7 ـ وهو محال: ا ف ق لب ي، سبحانه وهو محال: ك، وهذا محال: م، تعالى الله عنه ج، عن ذلك: ل علوا كبيرا: ت ج ل، لجاز: ت ج ل ك، جاز: ق م.\r8 ـ الاله: ت ج ف ك م، الله تعالى: ق لب، الله: ي، و (1): ك فقط، في (2): ف: نسخ، يرفع الامان: ت ج ق ك م، رفع الامان: ف ل، يرفع الامكان: لب ي.\r10 ـ انه لا اول ... العالم: ك م، ان العالم لا اول لامكان وجوده: ت ج ل."], [290, "الوجود فى الأزل منافيا له، فكان باطلا.\rوثانيهما انكم اما أن تفسروا المحدث بأنه الّذي يكون مسبوقا بعدم نفسه، أو بأنه الّذي يكون مسبوقا بوجود الله تعالى أو بتفسير ثالث.\rفإن كان الأول، فاما أن تريدوا به ان العدم سابق عليه بالعلية، أو بالشرف أو بالمكان. والكل باطل بالاتفاق. أو تريدوا به أن العدم سابق عليه بالطبع وهو مسلم لأن الممكن يستحق العدم من ذاته، والوجود من غيره. وما بالذات أسبق مما بالغير أو تريدوا به السبق بالزمان، وهذا يوجب قدم الزمان، لأنه إذا لم يكن لمفهوم ذلك السبق أول وكان ذلك المفهوم يقتضي تحقق الزمان، لزم أن لا يكون للزمان أول، ثم يلزم من قدم الزمان قدم الحركة، والجسم على ما هو معلوم.\r__________________\r1 ـ له فكان: ت ق ج ك لب ل م، لذلك وكان: ا لب، لذلك فكان: ي.\r2 ـ وثانيهما: ت ف ق لب م ي، الثاني: ج، وب: ا، ثانيها: ك، اما: ت ك م،: ف.\r3 ـ بعدم: ت ج ف ق ك لب م ي، بعد: ا مسبوقا: ا ت ج ف ق ك لب ي،: م.\r6 ـ بالعلية: ت ج ك لب م ي، بالعلة: ف.\r7 ـ به ان: ا ت ج ف ق لب ي، بان: ك م، وهو مسلم: ت ج ف ق ك لب ي، م، يستحق: ا ت ج ف ق ك لب، مستحق: ي، المستحق: م.\r8 ـ لذاته: ج معا: ا ت ج ف ق ك لب ي، ما: م، فما: ا.\r9 ـ وهذا ا ت ج ف ق ك لب ي، فهذا: م، اذا: ت ق ك لب م ي، ان: ف، لمفهوم: ت ج ق ك لب م ي، مفهوم: ف، المفهوم: ا.\r10 ـ يقتضي: ا ت ج ف ق ك ل لب ي، مقتضي: م، لزم: ت ق ك لب م ي، ويلزم: ف."], [291, "فالقول بالحدوث على هذا الوجه يوجب القدم.\rوأما إن فسرتم الحدوث بكونه مسبوقا بوجود الله تعالى. فإن أردتم به السبق بالعلية أو بالطبع أو بالشرف فالكل مسلم. والسبق بالمكان باطل بالاتفاق.\rوأما بالزمان، فإنه يوجب قدم الزمان على ما تقدم. وان أردتم بالحدوث معنى ثالثا فاذكروه لنتكلم عليه.\rنزلنا عن هذا المقام لكن لا نسلم أن الجسم لو كان قديما لكان اما أن يكون متحركا أو ساكنا. بيانه إن الحركة عبارة عن الانتقال من مكان إلى مكان والسكون هو الاستقرار فى المكان الواحد. وهذان القسمان فرع الحصول فى المكان.\rوعندنا العالم ليس فى مكان فيستحيل وصفه بكونه متحركا أو ساكنا. وتحقيقه أنه لو كان للعالم مكان، لكان مكانه اما أن\r__________________\r1 ـ بالحدوث: ا ت ف ج ق ك لب ل ي، م، القدم ت ق لب ل ي، القول بالعدم: ك ف، قدم الزمان: م، القدم فيكون متناقضا: ج.\r3 ـ به: ت ج ق ك ل، م، بالعلية ... بالشرف: ت ج ل م، بالعلية او الطبع او الشرف: ق ك ي، بالعلية بالصلة: ف الطبع والشرف: ف لب.\r4 ـ باطل: ف فقط.\r5 ـ واما بالزمان: ت ف ج ك لب م ي، وزمانا بزمان: ا.\r6 ـ معنى: لب فقط، فاذكروه لنتكلم: ا ت ج ل ف ق ك لب، فاذكروه شكله: ا، فليذكروه لنتكلم: م، فاذكروه تتكلم: ي.\r8 ـ الانتقال: ك م، انتقال: ت.\r9 ـ مكان (2): ك م، آخر: ت، هو: ت ج ق ك لب م ي، عبارة عن: ف.\r11 ـ ليس: تقدم على: العالم في: ك، في مكان: ت ف ق ك لب م ي، في المكان: ا.\r12 ـ او: ت ف، ولا يكونه: ك لب م، ويكونه: ق، وكونه:"], [292, "يكون معدوما أو موجودا والأول محال لأن حصول الموجود فى المعدوم محال. وإن كان موجودا، فإما أن يكون مشارا إليه بالحس أو لا يكون مشارا إليه بالحس فإن كان مشارا إليه بالحس. فاما أن يكون متحيزا أو حالا فى المتحيز، فلو كان متحيزا وحصل العالم فيه، لكان مكان الجسم جسما. وكل جسم تصح عليه الحركة والسكون فإذا تصح الحركة على مكان العالم، فلذلك المكان مكان آخر فيفضى إلى وجود أجسام لا نهاية لها، وهو محال.\rوبتقدير تسليمه، فالمقصود حاصل. لأن كلها أجسام فهى قابلة للحركة. وكل ما يتحرك فإنما يتحرك من مكان إلى مكان. فإذا\r__________________\rي، و: ف: نسخ، انه: ك فقط، لكان مسكاته: ك ف م، لكان: ل، فمكانه: ت ج.\r1 ـ موجودا: تقدم على معمدوما في: ت، والاول: ك م، الثاني: ت.\r2 ـ وان واما ان: ا كان موجودا فاما: ا ت ج ق ك لب م ي، واما: ف.\r3 ـ مشارا اليه بالحس فان كان .. اليه بالحس: ت ج، او لا يكون فان كان مشار اليه: ف ك لب م ي ق، اليه بالحس: ا ت ك لب ي، اليه: م: ف ق.\r3، 4 ـ فامام ان يكون: ت، كان اما: ك م.\r4 ـ ق المتحير: ت، فيه: ك م.\r4، 5 ـ فلو .. حصل العالم فيه او حالا فيه: ق م ي: ت ج ق م، فلو ولو: ك ي، فان: لب كان متحيزا متحركا: ي: ك واو: ك ي: لب حصل فيه حالا فيه: ي الجسم ا: ك لب ي: ف ك لب ي، فلو حصل فيه: ا.\r5 ـ جسما: ت ك لب م ي، جسم: ا: ف، والسكون: ت، ك ل ج م.\r6 ـ العالم: ت ج لب ل، المتحرك: ف ق ك م ي، مكان آخر: ت ج ق ك لب م ي، الآخر: ف.\r8، 9 ـ لان لانها: م ... هي: ك، فهي: ف لب، وهي: م دالة للحركة: ا ف ك لب م، لان ما بقى ما هي: ق فهي قابلة للحركة: ق ي، لان كل تلك الاجسام يصح عليها الحركة: ت ل ج.\r9 ـ وكل: ت ج ك لب م ي، ذلك: ف، فانما: ت م،"], [293, "لكل الأجسام مكان. وذلك المكان لا يكون جسما، لأن الخارج عن كل الأجسام لا يكون جسما وإن لم يكن مشارا إليه استحال أن يكون مكانا للجسم، لأن مكان الجسم هو الّذي يصح أن يتحرك منه وإليه. وذلك لا محالة مشار إليه.\rسلمنا الحصر، لكن لم لا يجوز أن يقال انها كانت متحركة قوله: الحركة تقتضى المسبوقية بالغير، والأزلية تنافيها.\rقلنا الأزلية تنافى وجود حركة معينة، لكن لم قلتم إنها تنافى وجود حركة قبل حركة لا إلى أول.\rأما الوجه الثانى وهو أن المجموع فعل فاعل مختار. فله أول.\rقلنا لا نسلم إنه فعل فاعل مختار بيانه أن الموجب قد يتخلف عنه\r__________________\rفانها: ق. من: ت ج ك م، عن: ا ف ل لب ي.\r2 ـ كل: ت لب م ي: ا ف، جسما وان: ت ج ف ق ك م ي، جسما وان كان هو العرض فهو محال لان العرض حال في الجسم، فلو كان الجسم حالا فيه لزم الدور وان: لب.\r3 ـ للجسم: ك م، الجسم: ت ل ف، يصح ان يتحرك: ج ك ل م، يتحرك: ت.\r4 ـ مشار: ا ت ف ق ك لب ي، مشارا: م.\r6 ـ الازلية: ا ت ف ج ق ك لب ل ي، الاولية: م.\r8 ـ الازلية: ا ت ف ج ق ك لب ل ي، الاولية: م. لكن: ق ك م لب ي، ولكن: ف، اما: ت، قلتم: ت ج ف ق ك لب ي، قلت: م.\r8 ـ قبل حركة لا الى اول: ا ت ج ق ك لب ل ي، لا اول لها: ف، قبل حركة الثاني في اول: م، لا.\r9 ـ اما: ك ق م ي، واما: ت ج ف الثاني: ت ف ق ك لب م ي، ب: ا، مختار: ت فقط، فله: ت ج ق ك ل، وله: م ف.\r11 ـ قلنا: ت ج ق ك ب، قلت: م، فاعل مختار: ت ق ك لب م ي، المختار: ف."], [294, "الأثر، إما لفوات شرط أو لحضور مانع. فلم لا يجوز أن يقال المؤثر فى وجود هذه الحوادث موجب بالذات إلا أن كل حادث يتقدمه شرط، لأن يصدر عن العلة الموجبة حادث آخر بعده.\rسلمنا أنه فعل المختار لكن لم قلت: أن فعل المختار محدث. وذلك لأن وجود الحادث وصحة تأثير المؤثر فيه، ممكن أزلا وأبدا، وإلا فقد كان ممتنعا لذاته، ثم انقلب ممكنا، وذلك محال.\rوإذا كان كل واحد منهما ممكنا أزلا كان تأثير القادر فى وجود الأثر جائزا أزلا.\rسلمنا أن الأجسام ما كانت متحركة. فلم لا يجوز كونها ساكنة.\rقوله: امتناع الحركة اما أن يكون لازما للماهية أو لا يكون.\r__________________\r1 ـ لحضور: ت ج ق ل، حضور: ك، لحصول: م.\r2 ـ يتقدمه: ا ك، متقدم: ت ج ق ل ي، تتقدم يتقدمه: ف، متقدم فتقدمه: م.\r3 ـ لان: نسخ، لان كل ما: ف، عن: نسخ، من: ت.\r4 ـ سلمنا انه ه: ا ك ي فعل المختار لكن: ا ت ك لب، و: ف لم قلت قلتم: ك، لا نسلم: ت: ا ت ف ق ك لب ي، بواسطه سلمنا انه فعل المختار لكن لا نسلم: م.\r5 ـ ازلا و: ت ج ف لب ل: ق ك م ي.\r6 ـ فقد: ك م ل ف، قد: ت ج، ولا لك: ت ج ق ك لب م ي ل، لذاته وهو: ف.\r7 ـ منهما: ت ف ك لب م ي، منها: ا، ممكنا ازلا: ت ج ك ي ل، ممكن ازلا: ا ف لب، ممكنا لذاته ازلا: ق، ممكنا اولا: م.\r8 ـ جائزا ازلا: ا ج ف ك لب، جائز اولا: م، جائزا اولا: ي، جائز اذ لا: ت.\r9 ـ ما: ت ق ك لب م ي: ف. كونها: ك ف م، ان يكون: ت ج ل."], [295, "قلنا الامتناع عدم، فلا يعلل. سلمنا كونه معللا، لكنه وارد عليكم أيضا فإن العالم يمتنع أن يكون أزليا فهذا الامتناع، ان كان لازما للماهية، وجب أن يبقى ممتنعا أبدا، وإن لم يكن لازما، كان هذا اعترافا بجواز كون العالم أزليا. وذلك يبطل قولكم.\rأما الوجه الثانى، فنقول لا نسلم كون السكون وصفا ثبوتيا، سلمناه لكن لا نسلم افتقاره إلى المؤثر. لأن علة الحاجة عندكم الحدوث فلا يمكنكم بيان افتقار هذا السكون إلى المؤثر، إلا إذا بينتم حدوثه، وأنتم فرعتم حدوثه على هذه المقدمة، فيصير دورا، سلمناه، لكن لا نسلم أن القديم لا يعدم. فإن الله تعالى. قادر من الأزل إلى الأبد على ايجاد العالم. فبعد أن أوجده، ما بقيت تلك القادرية. لأن ايجاد الموجود محال: فقد عدم ذلك التعلق القديم.\rلا يقال: الله تعالى قادر على إيجاده بواسطة أن يعدمه، ثم يعيده\r__________________\r1 ـ فلا: ت ق ك لب م ي، لا: ف، وارد: ت ج ق ك لب ي، واردا: ف، لازم ووارد: م.\r2 ـ يمتنع: ا ت ج ف ق ك لب ل ي، ممتنع: م.\r3 ـ وجب فوجب: ك .. ابدا: ت ج ق ك لب ل م ي، وجب ان لا يزول فوجب ان سقى الماهية ممتنعة ابدا: ف.\r4 ـ بجواز: ت ق ك لب م ي، لجواز: ف.\r5 ـ اما: ت ق ك ل م ي، واما: ف ج لب، الثاني: ت ف ق ك لب م ي، ب: ا.\r6 ـ علة: ت ج ف ق ك لب م ي، عليه: ا، عندكم: ت ك م، عندنا: ق.\r8 ـ فرعتم: ف ج ق ك لب م ي، فرغتم: ا، فزعتم: ت، بينتم: ل.\r9 ـ يعدم: ا ت ف ق، ينعدم: ك لب ج ل م ي.\r9، 10 ـ فان ... قادر: ك م، لان الله تعالى كان قادرا: ت ج ل.\r13 ـ الله تعالى قادر: ت ل، انه بانه: ك تعالى قادر: ا ف ك لب ي، انه سبحانه وتعالى قادر: م، انه تعالى كان قادرا: ق، الله قادر: ج."], [296, "مرة أخرى.\rلأنا نقول كلامنا فى ذلك التعلق المخصوص، أعنى تعلق قدرته بإيجاد العالم ابتداء. وهذا الّذي ذكرتموه تعلق آخر. وأيضا ينتقض بأن الله تعالى كان عالما فى الأزل بأن العالم معدوم. فإذا أوجده فقد زال ذلك العلم القديم.\rوالجواب عن الأول إنه لا بداية لامكان حدوث العالم، لكن لا يلزم منه صحة كون العالم أزليا، كما إنا إذا أخذنا هذا الحادث، بشرط كونه مسبوقا بالعدم سبقا زمانيا، فإنه لا أول لصحة وجوده مع هذا الشرط. والا فينتهى فى فرض التقدم إلى حيث، لو وجد قبله بلحظة لصار أزليا، وذلك محال. ثم مع إنه لا بداية لهذه الصحة، لم يلزم صحة كونه أزليا لما أن الأزلية وسبق العدم بالزمان لا يجتمعان فكذا هاهنا.\rوعن الثانى ان تقدم عدم العالم على وجوده، وتقدم وجود الله تعالى على وجود العالم عندنا، كتقدم بعض أجزاء الزمان على\r__________________\r2 ـ ذلك: ا ت ج ف ق ك لب ي، اثبات ذلك: م.\r3 ـ وهذا الذي ذكرتموه: ك ل م، والذي ذكرتم: ت ج، وهو الذي ذكرتموه: ف.\r4 ـ بان: ك م، باذن: ت، اوحده: ت ق ك لب م ي، وجده: ف.\r6 ـ الجواب: في: ك.\r9 ـ فينتهى: ت ج ك، فينتهى: م، حيث: ت ج ف ك لب م ي، حين: ا.\r10 ـ لصار: ا ت ج ف ق ك لب ي، صار: ل م، ثم مع: ا ت ج ف ق ك لب ل ي، ثم على فرض: م.\r11 ـ لما ان: ت ج ف م، كما ان: ا ي، وكما ان: ك ق، لان: لب.\r12 ـ فكذا ههنا: ا ت ج ق ك لب، كذا ههنا: ف، فكذا هنا: ي، فكذلك، م."], [297, "البعض عندكم. فكما ان ذلك التقدم ليس بالزمان، وإلا لزم التسلسل. فكذا هاهنا.\rوعن الثالث إنا إذا فرضنا متحيزين متماسين فنعنى بالسكون بقاءهما على ذلك الوجه وبالحركة ان لا تبقى تلك المماسة، بل يصير كل واحد منهما مماسا لشيء آخر. وعلى هذا التفسير لا حاجة إلى بيان ماهية المكان.\rلا يقال لم لا يجوز أن يقال العالم كان فى الأزل جسما واحدا والحركة والسكون بالتفسير الّذي ذكرتموه لا يوجد إلا عند حصول الجزءين. لأنا نقول بينا أن الواحد يستحيل أن ينقسم. فلما صار العالم منقسما الآن، علمنا أنه لم يكن واحدا.\rقوله: الأزلى ينافى الحركة المعينة اما لا ينافى نوع الحركة\r__________________\r1 ـ فكما: ت ج، وكما: ك م ل، بالزمان: ت ق م، الزمان: ك.\r2 ـ فكذا ههنا: ت ج ل ف ك، فكذا هذا: لب م ي، وكذا هذا: ق.\r3 ـ اذا: ك ل م، لو: ت ج، متحيزين: ا ت ج ف ل ق ك لب ي، جوهرين متحيزين: م، يتماسان في: ق.\r4 ـ ذلك: ا ت ج ف ق ك لب ي، هذا: م، تلك: نسخ، على تلك: ق.\r5 ـ كل واحد منهما: ف: ت ج ق ك ل لب م ي. مماسا: ل ك ف ت ج م، مسامتا: ق.\r7 ـ كان: ت ج ف لب ي، لم كان: ك م، واحدا: ت ف ق ك لب م ي، واحد: ا.\r8 ـ بالتفسير: ك ف م، على تفسير: ت ج ل، يوجد: ت ج ل، يفرض: ف م، يعرض: ك، تتعوض: ق.\r10 ـ واحدا: ت ج ق ك لب ل م ي، واحد: ف.\r11 ـ ينافى الحركة المعينة حركة معينة: ا اما لا ينافى: ا ت ج: ف ق ك لب م ي، نوع الحركة: ا ف ق ك لب ل ي م، نوعها: ت ج."], [298, "لا شخصها قلنا هذا باطل. لأن الحركة ماهيتها بحسب نوعها مركبة من أمر يقضى، ومن أمر حصل. فاذا ماهيتها المتعلقة بالمسبوقية بالغير. وماهية الأزلية منافية لهذا المعنى فالجمع بينهما محال.\rقوله: لم لا يجوز أن يكون المؤثر فى الحادث موجبا لا مختارا، ويكون كل سابق شرطا لحصول اللاحق عن ذلك الموجب.\rقلنا سنقيم الدلالة على فساده فى باب اثبات القادرية إن شاء الله تعالى.\rقوله لم لا يجوز أن يكون القديم فعلا لفاعل مختار.\rقلنا قد تقدم ابطاله.\rقوله: لم لا يجوز أن يكون ساكنا.\rقلنا لما تقدم.\rقوله: على الوجه الأول، الامتناع عدم فلا يعلل.\rقلنا مماسة الجسم أو مباينته لجسم آخر وصف وجودى لأنه نقيض اللامماسة التى هى وصف عدمى.\r__________________\r1 ـ لا شخصها: ف ق ك لب ل م ي، ا ت ج، بحسب نوعها: ت فقط، ج موجود في الهامش.\r2 ـ بعضي: ت، ينقضي: ج ق ك م ي، مضى: ف ل، منقضي: لب.\r5 ـ الموجب: ت فقط.\r6 ـ قلنا: ت فقط، القادرية: ت ج م، القادر: ا ف ق ك لب ي ل.\r6، 7 ـ ان شاء الله تعالى: ج.\r10 ـ يكون: نسخ، يكون القديم: لب.\r13 ـ او مباينته: ت ج، لجسم او مباينته: ك فقط، لجسم: ت ج ك ل م، بجسم: ق، اخرى: في: ا، وصف: نسخ، امر: ت ج.\r14 ـ نقيض: ا ت ج ك ل ك ق، يقتضي: ف م ي."], [299, "قوله: يلزمكم هذا فى صحة العالم.\rقلنا امتناع صحة العالم فى الأزل معدوم محض، فلا يصح الحكم عليه بالصفة الثبوتية، أما هاهنا السكون وصف ثبوتى، فيصح التقسيم الّذي ذكرناه.\rقوله علة الحاجة الحدوث.\rقلنا: بل الإمكان وقد تقدم بيانه.\rقوله تعلق قادرية الله تعالى بايجاد العالم، وتعلق علمه بأن العالم سيوجد قديم وقد عدم بعد وجود العالم.\rقلنا الموجود هو القدرة، والعالم، وهما باقيان أزلا وأبدا.\rأما الفلاسفة فقد قالوا: كل محدث فلا بد له من علل أربعة:\r__________________\r(13، 14/ 298) قلنا .. عدمى: ت ف ج ق ك ل م ي، قلنا معنى بامتناع الحركة وجوب السكون وذلك لازم لانه اذا امتنع على الجسم المماس ان يصير مماسا لجسم آخر وجب ان يبقى ممما سا للاول وهو قوله لم قلتم بان المماسة امر وجودي قلنا مماسة الجسم لجسم آخر وصف وجودي لانه نقيض اللامماسة التي هوي وصف عدمى: لب.\r1 ـ يلزمكم: ا ق ك لب ل، يلزمك: ت ج ف، يلزم: م ي.\r2 ـ امتناع صحة: ت فقط. في الازل: فقط.\r3 ـ بالصفة الثبوتية: م، بالصفات الثبوتية: ك، بصفة ثبوتية: ت ج ههنا هنا: ف ك .. وصف: ت م ثبوتي: ت ف ق ك لب م ي.\r4 ـ ذكرناه: ت ك م، ذكرنا: ف ق لب ي.\r6 ـ وقد: ت ج ف ق ك لب ي ل، وهو: م.\r7 ـ قادرية الله: ا ف ك لب ج ي، قادرية الباري: ق، قدرة الله: ل، تعالى قادرية الله: ت، قادريته: م، تعالى: ف فقط.\r8 ـ سيوجد: ت ج ف ق ك لب م ي، سبق حد: ا.، قديم واقد عدم: ت ق ك لب ل م، قديمان وقد عدما: ج ف، قديما وقد عدم: ي.\r9 ـ اما: ا ت ك لب ل ي، واما: ف ج ق م. اربعة: ت ك"], [300, "الفاعل، والمادة والصورة، والغاية. قالوا ونحن نبين من هذه الجهات، امتناع حدوث العالم بالنظر إلى هذه الأربعة.\rاما بالنظر إلى الفاعل فلأن العالم، لو كان محدثا لكان له مؤثر قديم، فتخصيص احداثه بالوقت الّذي أحدثه فيه اما أن يكون لمرجح أو لا لمرجح. والأول باطل لأن النفى المحض لا يعقل فيه الامتياز.\rوالثانى باطل لما سبق أن ترجيح أحد طرفى الممكن على الآخر من غير مرجح محال.\rوأما بالنظر إلى المادة، فلأن كل محدث فقد كان قبل حدوثه ممكنا، والإمكان وصف ثبوتى فى الممكن، فيستدعى موصوفا ثابتا. وذلك هو المادة. ثم هى أن كانت حادثة افتقرت إلى مادة أخرى ولزم اما التسلسل أو قدم المادة.\rواما بالنظر إلى الصورة، فلأن الزمان لا يقبل العدم الزمانى،\r__________________\rم، اربع: ق.\r1 ـ قالوا و: ت ج ق ل م، وقالو: ك، من: ت ج ك ق، في: م.\r2 ـ بالنظر الى هذه الاربعة: ت ج فقط.\r3 ـ فلان: ت ك م، فان: ق.\r4 ـ الذي: ت م، المعين الذي: ك.\r5 ـ والاوا: ك م، فالاول: ت.\r6 ـ ترجيح: ت ج ق ك ل، ترجح: م.\r7 ـ من غير مرجح: ك م، لا لمرجح: ت ج ل، محال: ت ق م، باطل: ك.\r10 ـ ثابتا: ت ف ق ج ك لب م ي، ثبوتيا: ا، مادة: ت ف ج ك لب م ي، محل: ا.\r11 ـ ولزم ... او اما: ج المادة: ت ج ل، ولزم التسلسل والا لزم قدم المادة: م، قدم المادة والا لزم التسلسل: ف، ولزم التسلسل فلزم قدم المادة: لب ي، يلزم قدم المادة: ق."], [301, "لأن كل محدث فعدمه سابق على وجوده. ومفهوم ذلك السبق أمر مغاير للعدم. لأن العدم قد يكون قبل وبعد. والقبل لا يكون بعد. فتلك القبلية صفة ثبوتية. فقبل أول الحادث حادث آخر. والكلام فيه كما فى الأول. فقبل كل حادث حادث آخر لا إلى أول.\rوأما بالنظر إلى الغاية: فهو أن موجد العالم، إن كان مختارا فلا بد له من غاية فى الايجاد، فكان مستكملا بذلك الايجاد، فكان ناقصا لذاته وإن لم يكن مختارا كان موجبا لذاته، فيلزم من قدمه قدم الأثر.\rوالجواب عن الأول ان ما ذكرتم منقوض باختصاص الكوكب بالموضع المعين من الفلك، مع كونه بسيطا واختصاص أحد جانبى المتمم بالثخن المخصوص، والجانب الآخر بالرقة.\r__________________\r1 ـ ومفهوم: ا ت ج ف ق ك لب ي، فمفهوم: م.\r2 ـ بعد (2): ت ق م، بعد ا: ك.\r3 ـ فتلك: ا ت ج ف ق ك ي، وتلك: م الحادث: ت ج ف ك، الحوادث: ق لب م ي.\r4 ـ كما في الاول: ت ك م، كالكلام في الاول: ق، مقبل: ت ق ك م، فقيل: ا، فقل: ف لب ي، اخر: ت ف ج لب ل ي: ق ك م.\r6 ـ ف (1، 2، 3): ك م، كلها: وفي: ت.\r7 ـ فان: ا ت ج ف ق ك لب ي، لكان: م.\r9 ـ ان ما ذكرتم انه: ج ... باختصاص الكوكب: ا ت ج ك لب، ان اختصاص حدوث العالم بوقنه المعين كاختصاص الكواكب الكوكب: ف: ل ف م، ان اختصاص الاحداث في الوقت المعين كاختصاص الكوكب: ي، انه كاختصاص الكوكب: ق.\r10 ـ و: ف.\r11 ـ المنخم بالنفس: ت ج ق ك لب ل م، المتحجم بالتحيز: ي، المتحجم بالشخن: ف في الهامش: الجانين من المستحجم بالشحن: ف، بالرقة: ف ك لب ج م ي، وبالرد: ت، بالدقة ا، بالوقة ترجيح للجائز من غير مرجح: ف."], [302, "ثم الجواب الحقيقى أن المقتضى لذلك الاختصاص تعلق إرادة الله تعالى باحداثه فى ذلك الوقت. وذلك التعلق عندنا واجب فيستغنى عن المرجح.\rلا يقال تخصيص الاحداث بالوقت المعين يستدعى امتياز ذلك الوقت عن سائر الأوقات. وهذا يقتضي كون الأوقات موجودة قبل ذلك الحادث.\rلأنا نقول كما أنه يجوز امتياز وقت عن وقت، وان لم يكن للوقت وقت آخر. فلم لا يجوز امتياز العدم عن الوجود من غير وجود الوقت.\rوعن الثانى أن الإمكان ليس وصفا وجوديا على ما مر وأيضا فالمادة ممكنة، فيلزم أن يقوم امكانها بمادة أخرى، وهو محال.\rفإن قلت المادة قديمة، فامكانها قائم بها أما امكان الحادث فلا يمكن قيامه به، لاستحالة قيام الموجود بالمعدوم.\rقلت لو قام امكان المادة بها لكان وجود المادة شرطا فى امكانها،\r__________________\r1 ـ الحقيقي: ت.\r2 ـ الوقت: لب، فيستغنى: ك م، مستفن: ت.\r7 ـ لانا: ت ج ق ك، ولانا: م، انه: ف.\r8، 9 ـ اخر ... الوقت: ك ل م، قالم بها فكذلك بجوز امتياز حادث عن حادث وان لم يكن هناك وقت موجود قائم به: ت ج.\r10 ـ ان: ا ت ف ق ك لب ي، ان يكون: م.\r12 ـ فامكانها: ق ك ل م، وامكانها: ت ج ف لب ي، فلا: ت، لا: ك م.\r13 ـ به: ف.\r14 ـ لو ... شرطا: ف ك ل م، امكان المادة لو كان قديما بها لكان وجودها شرطا: ت، امكانها: ت م ج، امكانه: ك ق ل."], [303, "لأن وجود المحل شرط فى وجود الحال فلو كان امكان المادة قائما بها، لكان امكانها مشروطا بوجودها. لكن وجودها عرضى مفارق والموقوف على العرض المفارق مفارق. فالامكان عرضى مفارق، هذا خلف.\rوعن الثالث أنك لما قلت: كل محدث فعدمه سابق على وجوده، فقد اعترفت بكون العدم موصوفا بالسابقية والعدم لا يجوز أن يكون موصوفا بوصف وجودى لاستحالة قيام الموجود بالمعدوم فيلزم أن لا تكون السابقية وصفا وجوديا فبطل كلامكم بالكلية.\rوعن الرابع إنا سنبين أنه تعالى فاعل مختار.\rمسئلة:\rالأجسام بأسرها متماثلة خلافا للنظام. واحتج أصحابنا بثلاثة\r__________________\r1 ـ المادة قائما: ج ك ل م، المقالة قائمة: ت.\r2 ـ لكن: ت، وجودها عرضي: ك، ووجودها عرضي: ت ج، بوجودها عرضي: ا، وجودها عرض: ف ق لب م ي.\r3 ـ المرض: ك ف ل م، العرضي: ا ت ج، عرضي: ا ك لب، فالامكان ... مفارق: ك م ف فكان: ج لكان امكانها عرضيا مفارقا: ت ج، مغارق: ل.\r5 ـ لما: ا ت ج ق ك لب ل ي، اذا: ف م، قلت ان: ف.\r6، 8 ـ اعترفت اعترف: ت ... العدم المعدوم: ك م ... فوصف العدم: ك م .. موصوفا موجودا: ك م .. فيلزم ان لا تكون فثبت ان: ك م .. موصوفا موجودا: ك م .. فيلزم ان لا تكون فثبت ان: ك م .. وصفا وجوديا ليست صفة وجودية: ثبوتية: ك م: ت ج ك م، اعترفت يكون العدم موصوفا بالوصف الوجودي فيلزم ان لا تكون السابقية صفة وجودية: ل.\r8 ـ فبطل: ا ت ج ف ك لب ل ي، فيبطل: ق م، كلامهم في: ف.\r9 ـ انه تعالى: ت ج ف ق ك ل لب م ي، ان شاء الله تعالى انه: ا. مختار: ا ت ج ف ق ل لب ي، مختار ان اشاء الله وبالله التوفيق: ك، ان شاء الله العزيز: م.\r11 ـ باسرها: ا ت ج ف ق ك لب ل ي، بالرها: م."], [304, "أوجه:\rأحدها أن الأجسام بتقدير استوائها فى الأعراض تلتبس بعضها بالبعض. ولو لا تماثلها، لما كان كذلك.\rوالاعتراض أن هذه الدلالة إنما يتم وتصح فى حق من تصفح جميع الأجسام وشاهد التباس كل واحد منها بكل ما عداها. فأما قبل ذلك فليس إلا الرجم بالظن.\rوثانيها: إنها بأسرها متساوية فى قبول جميع الأعراض فتكون متساوية فى الماهية.\rوالاعتراض أنه لم يصح عندنا أن جرم النار قابل للكثافة الأرضية، وإن جرم الفلك قابل للصفات المزاجية وقصة إبراهيم عليه السلام جزئية، فلا تدل على الحكم الكلى.\rوأيضا فلم لا يجوز أن يقال ان الله تعالى خلق فى بدن إبراهيم عليه السلام كيفية عندها يستلذ مماسة النار كما فى النعامة وغيرها ثم\r__________________\r2 ـ احدها: ت ج ف ق ك لب م ي، ا: ا. العرض: في: ف، ملتبس: ت ف ج ق ك لب ل ي، تلبس: م.\r4 ـ و (1): ا ت ج ق ك لب ل ي: ف م، يتم و: ت فقط.\r5 ـ فاما: ا ت ج ف ق ك ل، واما: م.\r6 ـ الرجم: ت ج ق م، الاخذ، ك.\r7 ـ ثانيها: ت ف ق ك لب م ي، ب: ا، الثاني: ج، انها: ت ج ف ق ك لب ل ي، م، مشاوية ... فتكون: ت ج ك ق ك لب م ي، ا.\r9 ـ و: ا ت ف ق ج ك لب ل ي، م، يصح: ت ج ك لب م ي، يتضح: ف.\r12 ـ ان (1): ت ف ك لب م ي، ا، ان يقال: ق ي.\r13 ـ عليه السلام: ا ت ف ق ك لب ي، م، عندها: ا فقط، مماسة: ت ق ك لب م ي، بمناسبة: ف، وغيرها: ا ت ف ك لب ج ي ل: م."], [305, "بتقدير تسليم استواء الكل فى قبول الاعراض، فلا يلزم منه استوائها فى تمام الماهية، لأن الاشتراك فى اللوازم لا يدل على الاشتراك فى الملزومات.\rوثالثها: أن الجسم لا معنى له إلا الحاصل فى الحيز والأجسام بأسرها متساوية فيه، فتكون متساوية فى الماهية.\rوالاعتراض أن الحصول فى الحيز ليس ذات الجسم، بل حكما من أحكامها وقد ذكرنا أن التساوى فى اللوازم لا يدل على التساوى فى الملزومات.\rمسئلة:\rالأجسام باقية خلافا للنظام. لنا أنه يصح وجودها فى الزمان الأول، فيصح فى الزمان الثانى لامتناع الانقلاب من الإمكان الذاتى إلى الامتناع الذاتى وهو منقوض على قول أصحابنا بالاعراض ولا يمكن الاعتماد فيه على الاستمرار فى الحس، لما عرفت أن عند تعاقب الأمثال، يظنها الحس واحدا مستمرا، ولأنه منقوض بالأكوان وعلى\r__________________\r1 ـ تسليم: ا ف ج ف ق ك لب: م ل ي، منه: ك.\r2 ـ في (2): ك م، من: ت.\r3 ـ الملزومات: نسخ، الملزوم: ج.\r4 ـ ثالثها: ت ف ق ك م ي، ج: ا، الثالث: ج.\r6 ـ الاعتراض: ت ق م، الاعراض: ك، حكما: ت ج ك لب م ي، حكم: ف ق ل.\r11 ـ فيصح: ت ف ك لب م، فصح: ي، الزمان: ا، ت ج ف ق ك ل لب م ي.\r12 ـ بالاعراض: ت ج ف ق ك لب م، بالاعتراض: ي.\r13 ـ عند: ك.\r14 ـ الحس: ت ج ق ك لب م ي، الاحس: ف، واحد: في: ت، بالاكوان: ا ت ف ك ي، بالالوان: ج ق لب ل م، و (2): ت ك: ج ق م ل."], [306, "قول أصحابنا بالاعراض وما يقال أنا أعلم بالضرورة انى أنا الّذي كنت بالبكرة فهو بناء على نفى النفس الناطقة، ولأن هوية الحيوان المعين، ليست عبارة عن الجسم فقط، بل لا بد فيه من اعراض مخصوصة وهى غير باقية. وإذا كان أحد أجزاء الهوية غير باق كانت الهوية غير باقية.\rمسئلة:\rالتداخل محال فى الأجسام خلافا للنظام. لأنها متماثلة فلو تداخلت لارتفع الامتياز بالذاتيات واللوازم والعوارض، فيفضى إلى اتحاد الاثنين.\rمسئلة:\rالأجسام يجوز خلوها عن الألوان والطعوم والروائح خلافا لأصحابنا. لنا أن الهواء لا لون له ولا طعم له احتجوا بقياس اللون على الكون وبقياس ما قبل الاتصاف على ما بعده.\rوالأول خال عن الجامع.\r__________________\r1 ـ قول بعض: ل فقط، بالاعراض: ق، انى انا الذي: ج ق ل م، اثنى انا الذي: ت، ان الذي: ك.\r2 ـ بالبكرة: ت ج ف ق م ي، موجودا في الامس: لب، نفي: ا ت ج ف ل ق ك، م، النفس: ت ج لب ل م ي، نفسى: ك، ف.\r4 ـ باق: ت ج ف ك لب م، باقية: ا.\r4، 5 ـ وهي ... غير باقية: ت ج ف ق ك لب م، وهي غير نافية: ك.\r7 ـ محال بعد في الاجسام في: ا ت ج، لانها: ق ك لب م ي، لنا انها: ت ج ف ل، تداخل في: ك.\r8 ـ بالذاتيات: ف ج ق ك لب ل ي، بالذات: ت م.\r12 ـ ان: ت، لا لون له ولا طعم له: ت ج ك م، و: ف: ت ج ك ف م، لا طعم له ولا لون له: ق لب: ق لب ي.\r13 ـ الكون: ت ق لب م ي، اللون: ف."], [307, "وأما الثانى، فعندنا يجوز خلوها عما لا يبقى بعد الاتصاف بها.\rوأما الباقى فهو لا ينتفى عن المحل، إلا بضد يزيله عنه فإن صح هذا ظهر الفرق وإلا منعنا الحكم فى الأصل.\rمسئلة:\rالأجسام مرئية خلافا للفلاسفة. لنا أنا نرى الطويل العريض والطول لا يجوز أن يكون عرضا، لأنه ثبت كون الجسم مركبا من الأجزاء التى لا تتجزأ فلو كان الطول عرضا لكان محله الجزء الواحد، لاستحالة قيام العرض الواحد بأكثر من محل واحد فالجزء الموصوف بالطول يكون أكبر مقدارا مما ليس موصوفا به فيكون الطويل قابلا للقسمة، وهو محال وإذا كان الطويل نفس الجوهر، والطويل مرئى فالجوهر مرئى والاعتراض أنا ساعدنا\r__________________\r1 ـ خلوها: ت ج، خلوه: ك م.\r2 ـ الباقي: ت ج ف ق ك لب م ي، الثاني: ا، عنه: ا ت ج ف ق ك لب ي: م.\r3 ـ الاصل: ت ج ك م، الاصل وقلنا يجوز خلو الاجسام عنها وحدها للاتصاف بها: ق.\r5 ـ مرثية: ت ج ف ق ك لب م ي، يدنية: ا، العويض: ا ت ك ل ي، والعريض: ج ف ق لب م.\r6، 7 ـ يجوز ان: ا ت ف ج ق ك لب ل ي: م، الاجزاء التي: ك م، اجزاء: ت ج ل ف.\r8 ـ باكثر من محل واحد محلين: م: ا ف ق ك لب م ي، بالمحال الكثيرة: ت ج ل.\r9 ـ بالطول: ت ف ق ج ك لب ل م ي، بالطويل: ا ك. اكبر: ت ج ل ق، اكثر: ك م، به: ا ت ف ج ق ك لب ل ي، م.\r10 ـ واذا: ت ف ق لب م، فاذا: ي، الطويل (2): ا ت ج ق ل ي، الطول: ك ف لب م.\r11 ـ وا (1): ت ف ق لب م ي، فا: ا ك، في: لب: الطول. فا و: ا لجوهر مرثى وو: ف: ا ت ق ج ك لب ل ي ف،"], [308, "على اثبات الجوهر الفرد. ولكن لا نسلم أن الطول نفس الجوهر، وإلا لكان الجوهر الفرد طويلا، فيعود الانقسام، بل هو عبارة عن تأليف الجواهر فى سمت مخصوص والتأليف عرض. فلم لا يجوز أن يكون المرئى هو التأليف.\rوأجيب عنه بأنا نرى الطويل حاصلا فى الحيز. وذلك لا يعقل فى العرض. فعلمنا أن المرئى هو الجوهر ويشبه أن يكون ذلك كلاما غير الأول.\rمسئلة:\rالخلاء جائز عندنا، وعند كثير من قدماء الفلاسفة خلافا لارسطاطاليس، واتباعه. والمراد من الخلاء كون الجسمين، بحيث لا يتماسان ولا يكون بينهما ما يماسانه.\rلنا إذا رفعنا صفحة ملساء عن مثلها ارتفع جميع جوانبها دفعة\r__________________\rفيكون الجوهر مرثيا: م، ساعدنا: ا ت ل ف ج، نساعد: ق لب ي، تباعدنا: م.\r1 ـ و: ا فقط، الطول: ت ج ق ل م، الطويل: ك.\r2 ـ الانقسام: ت ق ك لب م ي، الاقسام: ف.\r3 ـ تاليف: ا ف ق ك لب، تالف: ت ج ل م، الجواهر: ف ك م، الجوهرين: ق لب ي، الجوهر: ت ج ل، التاليف: ك ف م، التالف: ت ج ل.\r4 ـ المرثى هو التاليف التالف: ت ج ل: ت ج ق ك ل م، التاليف هو المرثي: ف لب ي.\r5 ـ لا: ا ت ج ف ق ك لب ل، م.\r6 ـ ويشبه: ا ت ف ج ق ك لب ل ي، فشبه: م.\r9 ـ قدماء: ا ت ف ج ق ك لب ل ي: م.\r10 ـ لارسطو: ف ج ك ل لب ي، الجسمين: ت ق ك لب م، جسمين: ج ف ي.\r11 ـ يماسانه: ت ج ك لب ل م ي، يماسها: ف، يماسهما: ق.\r12 ـ لنا: ت ك ل م، لنا انا: ج ق، ملساء: ا ت ج ق"], [309, "واحدة، وإلا وقع التفكك فيها. وفى أول زمان الارتفاع خلا وسطها لأن حصول الجسم هناك لا يكون إلا بعد مروره بالطرف فحال كونه فى الطرف لم يكن فى الوسط فيكون الوسط خاليا. ولأن الجسم إذا انتقل إلى مكان فالمكان المنتقل إليه، إن كان خاليا قبل ذلك، فقد حصل الغرض، وإن كان مملوءا، فالذى كان فيه ان لم ينتقل عنه، لزم التداخل، وإن انتقل عنه، فإما ان ينتقل إلى مكان الجسم الأول. ويلزم منه الدور، لأنه يتوقف حركة كل واحد منهما عن مكانه على حركة الآخر عن مكانه، أو إلى مكان آخر والكلام فيه كما فى الأول، فيلزم أن البقة إذا تحركت أن يتدافع جملة كرة العالم، وهو باطل قطعا.\rاحتجوا بأن الخلاء يحتمل التقدير، فيكون مقدارا.\r__________________\rك لب ي، املساء: ف: م.\r1 ـ واحدة: ج ف، خلا: ت ج ف ق ك لب ي، حال: م.\r2 ـ الجسم: ت ج ك م، الهواء: ق، الا: ت ج ك: م، بالطرف: ا ت ف ق لب ي، في الطرف: م، فحال: ف ك لب م، فمحال: ي، فحاصل: ق.\r2، 3 ـ فحال كونه في الطرف: ت، فعند مروره بالطرف: ج.\r3 ـ الوسط (2): ت ج م،: ا ف ق ك لب ي.\r4 ـ الى: ا ت ج ف ك لب ي، من مكان الى: ق، من مكانه الى: م.\r5 ـ ان لم: ت ف ق ك لب م ي، وان لم: ا.\r6 ـ فاما ان ينتقل: ف.\r7 ـ الاول: ا ت ج ل، المنتقل اليه اليه: ف ق: ف ق ك م، ويلزم: ا ت ل ق ك لب ي، فيلزم: ج م، يلزم: ف، لان ه: ا ت ق ج ك، ولانه: مف، منهما: ت ق م، منها: ك.\r8 ـ عن (1): ا ت ج ف ق لب ي، على: ك م.\r9 ـ كما: نسخ، كالكلام: ت ج، ان البقة: ا ت ج ف ق ك ل ي، ان البقعة: م: لب، جملة: ت ف ق ل م، جميع: ك،: ج.\r10 ـ قطعا: ا ت ج ف ق ك لب ي: م.\r11 ـ مقدارا: ت ج ق لب م ي، مقدرا: ف ك."], [310, "وجوابه أنا لا نسلم أنه يحتمل التقدير على التحقيق بل على سبيل التقدير كما أنا نقول: لو كان نصف قطر العالم ضعف ما هو الآن، لكان ذلك المحيط واقعا خارج العالم، لكن لما كان ذلك على سبيل التقدير لم يلزم ثبوت مقدار خارج العالم. كذا هاهنا.\rتنبيه:\rالحركة فى الملأ الّذي نسبة رقته إلى رقة الماء، كنسبة زمان الحركة فى الخلاء إلى زمانها فى الماء إنما يقع لا فى زمان، إذا لم يكن استحقاقها للزمان لذاتها بل للعائق، لكن ذلك معلوم الفساد.\rمسئلة:\rالأجسام متناهية خلافا للهند.\rلنا إنا إذا فرضنا خطا غير متناه، وخطا آخر متناهيا موازيا للأول. فإذا مال المتناهى من الموازاة إلى المسامتة، فلا بد من نقطة هى أول نقطة المسامتة لكن ذلك محال، إذ لا نقطة يفرض الا وفوقها\r__________________\r1 ـ و: ا ت ج، ف ق ك لب م ي، انا: ق: ت ف التحقيق: ا ت ج ف ق ك لب ي، سبيل التحقيق: م.\r2 ـ انا: ف فقط.\r4 ـ فكذا: في ف، هنا: في: لب ف.\r6 ـ الحركة: ت ق ك لب م ي، حركة: ف، الملا الذي: ت ف ق ك لب م، الخلاء الذي هنو: ي، نسبة: ت ج ق م، يشبه: ا ف ك، نسبه: ل.\r8 ـ للزمان: ا ت ج ف ق ك لب ي، الزمان: م.\r10 ـ للهند: ت ج ف ل م (هامش ك)، للهندسيين: ك.\r11 ـ و: ا ت ج، وفرضنا: ف ق ك لب ل م ي.\r12 ـ للاول: ت ج ف ق ك لب ل م ي، الاول: ا، فاذا: ت ج ف ق ك لب ل ي، فاما اذا: م، من: ا ت ج ف ق ك لب ل ي، عن: م.\r13 ـ يفرض: ا، ف ق ك لب م ي."], [311, "نقطة أخرى فتكون المسامتة مع الفوقانية قبل المسامتة مع التحتانية. فإذن فرض خط غير متناه يفضى إلى هذا المحال، فيكون محالا.\rواحتج الخصم بأن الأجسام، لو كانت متناهية لكان الخارج عنها بأسرها: إما أن يتميز فيه جانب عن جانب، وإما أن لا يتميز فان كان الأول، لم يكن ذلك عدما محضا، لأن النفى المحض لا خصوصية فيه ولا تحقق، فكيف يحصل الامتياز، بل لا بد وأن يكون أمرا وجوديا ولا شك فى أنه أن يكون مشارا إليه فيكون مقدارا فيكون جسما فالخارج عن كل الأجسام جسم هذا خلف.\rواما أن لا يتميز فيه جانب عن جانب، فهذا محال ببداهة العقل.\r__________________\r(13/ 310)، 1 ـ هي اول ... فتكون: ت فقط.\r1 ـ نقطة: ا ك: ف لب م ي، فتكون وتكون ج ق لب ي المسامنة: ق ك لب م ي، وتكون مسامته: ف، المسامتة: ت.\r2 ـ فاذن: ا ت ج ف ق ك لب ل ي، فلان: م، متناه: ا ت ف ج ق ك لب ل ي، متناهية: م، فيكون محالا: ا ت ج ف ق ك لب ل ي: م.\r3 ـ و: ت ل: نسخ، بان: ت ج ف ق ك لب ل م ي، ان: ا.\r4 ـ جانب (2): ا ت ج ف ق ك لب ل ي، جانب فيكون محالا: م. واما ان لا: ت ج ق ك لب م ي، لو لم: ف.\r4، 5 ـ فان كان الاول: ا ت ج ل، فان تميز: ف ق ك لب م ي.\r5، 6 ـ لا خصوصية .. يحصل: ت ج ف ك لب م ي، لا يفعل فيه: ف.\r6، 7 ـ امرا وجوديا ت ج ق ك لب ل م ي، موجودا: ف.\r7 ـ انه: ا ت ج ف ق ك لب ي، انه اما: م، ان: ق ك ج ل ف ت، مشارا: ت ج ف ق ك لب ي، مشار: م فيكون: ا ت ج ف ل، ويكون: ق ك لب ي، او يكون: م.\r9 ـ واما الا ... فيه جانب: ت ج، واما ان لم .. جانب فيه: ا ف ك ج هامش، اما .. جانب منه: لب ي، واما الا .. عنه: ق، وان لم .. فيه: م. ببداهة: ا ت ج ف ق ك لب ي، عن بداهة: م."], [312, "لأن العقل الصريح يشهد بأن الطرف الّذي يلى القطب الشمالى مثلا غير الّذي يلى القطب الجنوبى. فإنكار ذلك مكابرة فى البديهيات.\rالجواب، أما المتكلمون فقد سلموا أحيازا متميزة خارج العالم غير متناهية وزعموا أنها أمور تقديرية غير موجودة. وهذا ضعيف، لأن المقدر هو الّذي لا وجود له، إلا فى الذهن والّذي لا وجود له إلا فى الذهن، إن لم يكن مطابقا للخارج، كان ذلك فرضا كاذبا، وإن كان مطابقا، لزم منه وجود الاحياز فى نفس الأمر. وحينئذ يعود الالزام.\rوأما الحكماء فإنهم أصروا على أن خارج العالم لا يتميز فيه جانب عن جانب وإن الحاكم بهذا التميز هو الوهم لا العقل، وحكم الوهم غير مقبول.\rمسئلة:\rالعالم لا يجب أن يكون أبديا خلافا للفلاسفة والكرامية لنا إنه لما\r__________________\r1 ـ العقل الصريح: ت ق ك لب م ي، صريح العقل: ف.\r1، 2 ـ الشمالي مثلا: ا ج ت ف ق ك ي مثلا: ج لب ي، اليمين: م.\r2 ـ الجنوبي: ا ت ج ف ق ك ل ي، الشمالي: م، فانكار ذلك: ك لب ي، وانكار ذلك: ت ج ل ف، فانكارها: ف.\r4 ـ الجواب: ت ق م، والجواب عنه: ق: ج ق ك ل.\r6 ـ المقدر: ف ج ك لب م ي، المقدور: ت، المقدار: ا، الا: ت ج ك ل لب م ي، بل: ف.\r7 ـ كاذبا: ف فقط.\r10 ـ واما: ق ل م، فاما: ك، اما: ت ج فاتهم: ت ج ف ق ك لب ل م ي، فهم: ا، فيه: ت ج ق ك م، منه: لب ي، ف.\r11 ـ عن جانب: ي التميز: ك ج م، التمييز: ت ل.\r14 ـ ابديا: ف ج ق ك ل م ي، ابدا: ا ت ك، انه كما: ا ت"], [313, "لم يكن أزليا وجب أن لا يكون أبديا، لأن ما لا يكون أزليا كانت ماهيته قابلة للعدم أبدا. وذلك القبول من لوازم تلك الماهية فتكون الماهية قابلة للعدم أبدا.\rأما الفلاسفة فقد احتجوا بأمور:\rأحدها: ان المؤثر فى العالم موجب بالذات، فيلزم من دوامه دوام العالم.\rوثانيها أنه لو عدم الزمان، لكان عدمه بعد وجوده بعدية بالزمان، فيكون الزمان موجودا حال ما فرض معدوما، هذا خلف.\rوثالثها: ان كل ما يقبل العدم، فإن إمكان عدمه حاصل قبل عدمه. وذلك الإمكان لا بد له من محل، أى لا بد من شيء محكوم عليه بأنه ممكن الاتصاف بذلك العدم. وليس هو وجود ذلك الشيء، لأن الّذي يمكن اتصافه بالشيء، لا بد وأن يكون باقيا مع ذلك الشيء. ووجود ذلك الشيء لا يتقرر مع عدمه. فاذا لا بد من شيء آخر يقوم به امكان عدمه وذلك هو الهيولى. فاذا كل ما صح\r__________________\rج ف ق ك لب ي، ان ما: م، انه: ل.\r1 ـ يكن: ف ك ل م، بجب: ت ج.\r2 ـ ابدا: ا، ت ج ف ق ك لب م ي.\r2، 3 ـ فتكون تلك: ج الماهية: ج ل ك م: ت.\r5 ـ احدها: ت ج ف ق ك لب م ي، ا: ا.\r7 ـ وثانيها: ت ف ق ك لب م ي، وب: ا، الثاني: ج.\r8 ـ حال ما: ت ف م، حالما: ك.\r9 ـ وثالثها: ت ف ق ك لب ل م ي، وج: ا، الثالث: ج، فان امكان: ا ت ج ف ق لب ي، فامكان: ك ل م.\r11 ـ ممكن: ا ت ج ف ق ك لب ل ي: م، و: ا ت ج ف ق ك لب ل ي، وذلك: م، ذلك: ا ت ج ف ق ك لب ل ي، م.\r12 ـ باقيا: ا ت ج ف ق ك لب ل ي، ثابتا: م.\r13 ـ ذلك: ت ق ك م: ف، يتقرر: ت ج ف ق ك لب ل م ي، يتقدر: ا، لا (2): ا ت ج ف ق ك لب ل، فلا: م.\r14 ـ به: ا ت ف ق ك لب: م، كل ما، ت ق م، كلما:"], [314, "عليه العدم، فله هيولى فلو صح العدم على الهيولى، لافتقر إلى هيولى أخرى، لا إلى نهاية وهو محال فإذا الهيولى لا تقبل العدم، ثم قد ثبت أن الهيولى لا تخلو عن الصورة الجسمية، فإذا عدم الجسم محال.\rواحتج المسلمون على وجوب أبدية العالم بأن عدم العالم بعد وجوده: إما ان يكون باعدام معدم، أو بطريان ضد، أو بانتفاء شرط والثلاثة باطلة. فالقول بعدم العالم بعد وجوده محال.\rوإنما قلنا إنه لا يجوز أن يعدم باعدام معدم. لأن الاعدام إن كان أمرا وجوديا، لم يكن ذلك الوجود عين عدم العالم. وإلا لكان الوجود عين العدم، بل غايته أنه يقتضي عدم الجوهر، فيكون ذلك إعداما بالضد. وليس هذا هو القسم الأول، بل هو القسم\r__________________\rك. صح: ت ج ك ل م، يصح: ف ق لب ي.\r2 ـ اخرى: ت م، اخر: ق ج ك ل، وهو محال: ا ت ف ق ك لب ي، م.\r3 ـ ثم: ت ج ق ك ل، و: ف لب م: ا ي.\r5 ـ و: ا ت ج ف ق ك لب ل ي، م، المسلمون: ت ف ق ك ل م ي ص مشطوب عليه في: ا، الكرامية: ا، المليون: ج لب، بان ق م، فان: ك.\r6 ـ ممدم: ت ف ك لب م ي، معدوم: ا ق.\r7 ـ و: ا ت ق ك ي، والاقسام: ج لب ل م، ف. الثلاثة باطلة: ف، في ك: وبعد، محال: ا ت ق ك لب ي، باطل: ف تقدم على بعد في: م.\r8 ـ و: ا ت ف ق لب: ك م ي، باعدام معدم: ت ج ف ل، باعدام معدوم: ا، بالاعدام: ك م ي، بعد وجوده بالاعدام: لب.\r9 ـ ان: ك ل م ج هامش، اذا: ت ج، عين: ت ج ف ق ك لب م ي، غير: ا ل.\r10 ـ انه: ا ت ج ف ق لب ل ي، ان: ك م.\r11 ـ هذا: ي، هو (1) ت ف ق لب ي، هو هذا ذلك: ا ل: ا ك الاول: ت ج ل فقط. هو (2): ت ج ق."], [315, "الثانى. وإن لم يكن وجوديا كان عدما محضا، فيمتنع اسناده إلى المؤثر، لأنه لا فرق فى العقل بين أن يقال لم يفعل شيئا البتة وبين أن يقال فعل العدم، وإلا فيكون أحد العدمين مخالفا للثانى. فيكون لكل واحد من العدمين تعين وثبوت، فيكون العدم ثبوتيا، هذا خلف.\rوإنما قلنا إنه لا يجوز أن يعدم بحدوث الضد لوجهين:\rالأول أن حدوث الضد يتوقف على انتفاء الضد الآخر فلو كان انتفاء ذلك الضد معللا بحدوث هذا الضد لزم الدور. وهو محال.\rالثانى وهو أن التضاد حاصل من الجانبين، فليس انتفاء أحدهما بالآخر أولى من العكس فاما أن ينتفى كل واحد منهما بالآخر\r__________________\r(11/ 314، 1) ـ هو القسم الثاني: ل.\r1 ـ عدما: ت ج ق ل م، عدميا: ك، اسناده: ت م، استناده: ق ك.\r2 ـ لم يفعل (استبدل ب) فعل المعدم: في: ت ج، شيئا: ت ج فقط.\r3 ـ فيكون: ف فقط، مخالفا للثاني: ت ج ق ك لب ل م ي، بخالف الآخر: ف.\r4 ـ تعين: ت ج ك لب ل، معين: ي، تغير: ف ق م. ثبوتيا: ك م، ثبوتا: ت ج ل.\r6 ـ بحدوث: ت ج ق لب ي، لحدوث: ف م، الحدوث: ا.\r7 ـ الاول: ت لب ل، ا، ا، الاول هو: ف ق ي ل، احدهما: ج م، الاول وهو: ك.\r8 ـ ذلك الضد: ا ت ج ل، الضد الآخر: ف ق لب ك م ي.\r9 ـ الثاني و: ت ف ك لب ل م ي، ب: ا، والثاني: ق ج، من: ا ت ق ج ك لب ل ي، بين: ف، في: م، فليس: ا ت ج ف ق ك لب ي، وليس: م، احدهما: ت ج ف ك ل م، واحد منهما: ق لب ي.\r10 ـ بالاخر: ا ت ج ف ق ك لب ل ي، م، من العكس: ت ك م، من العكس فاما ان ينتفى كل واحد منهما بالاخر اولى من العكس: ق."], [316, "وهو محال. لأن المؤثر فى عدم كل واحد منهما وجود الآخر والمؤثر حاصل مع وجود الأثر. فلو حصل العدمان معا، لحصل الوجودان معا، فيكونان موجودين معدومين دفعة واحدة، وهو محال. أو لا ينتفى واحد منهما بالآخر، فيلزم اجتماع الضدين.\rلا يقال الحادث أقوى من الباقى، لأن الحادث حال حدوثه متعلق السبب والباقى ليس كذلك، ولأن الحادث حال حدوثه، لو عدم، لزم اجتماع الوجود والعدم بخلاف الباقى. ولأنه يجوز أن يكون عدد الحادث أكثر فيكون أقوى.\rلأنا نجيب عن الأول بانا بينا أن الباقى حال بقائه أيضا متعلق السبب.\rوعن الثانى أنا لا نقول الحادث يوجد ويعدم معا، بل نقول الباقى يمنع الحادث من الدخول فى الوجود.\rوعن الثالث أنه بناء على جواز اجتماع المثلين، وهو محال.\r__________________\r2 ـ حاصل: ت ج ف ق ك لب ل م ي، في حاصل: ا. وجود الاثر: ا ت ج ل، الاثر: ف ق ك لب ي، المؤثر: م، العدمان ... الوجودات ت ج ق ك لب ل م ي، الوجودان ... العدمان: ف.\r3 ـ واحدة: ق، وهو محال: ت ج ق ك لب ل م ي، فيلزم المحال: ف.\r4 ـ منهما: ا ت ج ف ق ك ل لب ي: م، الضدين: ت ج ق ك ل لب م ي، الضدين وهو محال: ف.\r5، 6 ـ متعلق السبب ... حدوثه: ف فقط.\r7 ـ بخلاف الباقي ولانه: ت ق ك لب م ي، وحال حدوثه تعللق السبب والباقي ليس كذلك ولان الحادث: ف.\r9 ـ ايضا: ا ت ج ل، ق ك لب م ي.\r10 ـ السب: ت ق م، بالسبب: ك.\r9، 11 ـ بينا سنبين: ت ج ل ... وعن الثاني انا: ت ج ق ك لب ل م ي،: ف.\r11 ـ نقول (2): ق.\r13 ـ وعن الثالث: ت ق ك م، الثاني انا بينا ان الباقي حال"], [317, "وإنما قلنا أنه لا يجوز أن يكون لقطع الشرط، لأن ذلك الشرط، لا يكون إلا العرض فيكون الجوهر محتاجا إلى العرض، وكان العرض محتاجا إلى الجوهر، فيلزم الدور، وهو محال.\rوالجواب عن الثلاثة الأولى ما تقدم فى مسئلة الحدوث.\rوعن الرابع أن نقول: لم لا يجوز أن يعدم باعدام الفاعل.\rقوله: الاعدام اما أن يكون أمرا وجوديا أو لا يكون.\rقلنا هذا يقتضي أن لا يعدم الشيء البتة، لأنه يقال إذا عدم الشيء فهل يتجدد أمر أو لم يتجدد. فإن لم يتجدد أمر، فهو لم يعدم. وإن تجدد، فالمتجدد وجود أو عدم. لا جائز أن يكون عدما، لأنه لا فرق بين أن يقال: لم يتجدد، وبين أن يقال تجدد العدم. وإلا فأحد العدمين يخالف الآخر، وهو محال.\r__________________\rبقائه ايضا متعلق للسبب وعن الثالث: ف.\r1 ـ لقطع: ا ت ق ك ل ي، لفوات: ف، بصدم: لب، لانتفاء: ج م، الشرط (2): ك.\r2، 3 ـ فيكون ... الى الجوهر: ج ل ك ص، فيكون الجوهر محتاجا الى الجوهر: ت، لان الشرط هو الخارج عن ماهية الشيء فيكون عرضا فيكون الجوهر محتاجا الى العرض وكان العرض محتاجا الى الجوهر: م.\r3 ـ فيلزم: ت ق ك م، يلزم: ا.\rالاولى: ا ت لب، الاول: ف ق ك م: ي.\r5 ـ الرابع: ت ق ف لب م ي، الرابعة: ي، الشرايع: ا، ان نقول: ج ق ك لب م ي، ان يقول: ت، ف.\r6 ـ قوله: ت ج ف ل ك م، قولكم: ق، وجوديا: ت ج ف ك لب م ي، لا يتجدد: ا.\r7 ـ هذا: ا ت ج ف ق ك لب ي، م، الشيء (1): ا ت ج ف ك لب ل ي، شيء: م.\r8 ـ او لم يتجدد: ا ج ق ك ي، او لم يتحد: ت، ام لا يتجدد: م، او ما تجدد امر: ف.\r9 ـ وجود او عدم: ا ت ج، عدم او وجود: ل ف ق ك لب م ي.\r11 ـ العدمين: ت ج ق ك لب ل م ي، المعدومين: ف."], [318, "وإن كان وجودا كان ذلك حدوثا لوجود آخر، لا عدما للوجود الأول.\rسلمنا فساد هذا القسم. فلم لا يجوز أن يفنى بحدوث الضد.\rقوله: فى الوجه الأول حدوث الضد يتوقف على عدم الباقى قلنا لا نسلم. فإن عندنا عدم الباقى معلول الحادث، والعلة، وإن امتنع انفكاكها عن المعلول ولكن لا حاجة بها إلى المعلول.\rقوله فى الوجه الثانى المضادة مشتركة بين الجانبين.\rقلنا لم لا يجوز أن يكون الحادث أقوى لحدوثه، وإن كنا لا نعرف لمية كون الحدوث سببا للقوة.\r__________________\rيخالف الاخر: ف ق ك لب م ي، مخالف الاخر: ا، مخالف للاخر: ت ج ل، وهو: ت ج ق ك لب ل م ي، فيكون لكل واحد من القدمين تفير وثبوت وهو: ف.\r1 ـ وجودا: ا ت ج ف ك لب م، موجودا: ي، وجوديا: ق م، ذلك: ت ج ق ف ك لب ل ي، م، حدوثا: ت ج ف ك لب ل م ي، حددنا: ا، لوجود .. لوجود للوجود: ج ل ا: ت ج، لوجود لوجود: ك .. للموجود: ف ق ك لب م ي، الموجد .. للموجد: ا.\r3 ـ يفنى: ت ج ق ك لب م ي، يصدم الجسم: ف، بنظر: ت ف ق ك لب م ي، لحدوث: ا.\r4 ـ الضد يتوقف: ق ك لب ي: ف ق ك لب م ي.\r6 ـ و (2): ت ج ل: ك م، بها: ت ج م، لها: ف ل ك لب ي، المعلول: ت ج ف ق ك لب م ل م ي، المعلوم: ا.\r7 ـ في المضادة: في: ف، المضادة مشتركة: ا ف ق ك ل لب ي، امضادة حاصلة: م، التضاد مشترك: ت ج، بين: ت ج ل ق لب ي، من: ك م.\r8 ـ لحدوثه: ت ج ق لب م، بحدوثه: ف ي.\r9 ـ لمدة: ص ك لب ل م ي، كمية: ت ج ف ق، سببا:"], [319, "سلمنا فساد هذا القسم، لكن لم لا يجوز أن يعدم الجسم لانتفاء الشرط. وبيانه: أن العرض لا يبقى، والجوهر ممتنع الخلو عنه. فإذا لم يخلق الله تعالى العرض، انتفى الجوهر.\rقوله يلزم منه الدور قلنا لا نسلم ولم لا يجوز أن يقال الجوهر والعرض متلازمان، وإن لم يكن لأحدهما حاجة إلى الآخر كما فى المضافين، ومعلولى العلة الواحدة، فإذا لم يوجد أحد المتلازمين وجب عدم الآخر وبالله التوفيق.\rتقسيم الأجسام:\rالجسم اما بسيط وهو الّذي يشابه كل واحد من أجزائه كله فى تمام الماهية. وإما مركب وهو الّذي لا يكون كذلك.\rوأما البسيط فاما فلكى وإما عنصرى.\rأما الأجسام الفلكية فقد زعمت الفلاسفة انها لا ثقيلة ولا خفيفة\r__________________\rت ج ف ق ك لب ي، سلبا: م.\r2 ـ وبيانه: ا ت ف ق ك لب ي، بيانه هو: م، عنه: ا ت ف ق ك لب ي، عندنا: م.\r3 ـ تعالى: ف.\r4 ـ منه: ا ت ج ل، ف ق ك لب م ي، لا نسلم و: ا، ت ج ف ق ك لب م ي.\r5 ـ متلازمان: ا ت ج ل، يتلازمان: ف ق ك لب م ي. لاحدهما: ت ج ق ل م، باحدهما: ا ف ك لب ي.\r6 ـ المضافين: ا ت ج ف ق ك لب ي، المتضادين: م، فاذا: ت ف ق ج ك لب م ي، وان: ا.\r7 ـ وجب عدم: ت ج ق م، لم يوجد: ف لب ي، وبالله التوفيق: ا ك ل: ت ف ق لب م ي.\r9 ـ الجسم: ك فقط، اما بسيط: ا ف ج ك لب ي، اما البسيط: ت، اما ان يكون بسيطا: م، يشابه، ت ج ق لب م ي، يساوي: ف: ك، كل واحد: ت ج ق ل م، احد: ك.\r11 ـ و (9): ت ف، ق لب م ي ك، فاما: ت ف ق ك"], [320, "ولا حارة ولا باردة ولا رطبة ولا يابسة ولا يقبل الخرق والالتئام والكون والفساد.\rواحتجوا بأن الجهة مقصد المتحرك، ومتعلق الإشارة، فتكون موجودة، لأن النفى المحض لا تميز فيه، وهى غير منقسمة، وإلا لكان المتحرك، إذا وصل إلى أحد نصفيها، وبقى متحركا. فاما أن يقال إنه الآن متحرك عن الجهة فتكون الجهة ذلك الحد لا ما ورائه، أو إليها فحينئذ لا يكون ذلك الحد من الجهة بل الجهة ما وراءه فثبت أن الجهة حد غير منقسم.\rثم بينوا أنه لا بد من محدد كرى يحدد الفوق والتحت بمحيطه وبمركزه ثم قالوا وهذا المحدد غير قابل للحركة المستقيمة، وإلا\r__________________\rلب م ي، اما: ف.\r1 ـ يقبل: ا ت ج، يصح عليها (عليهما: ي): ف ق ك لب م ي.\r2 ـ الفساد: ا ت ج ك ل، الفساد عليها: ف ق م ي.\r4 ـ المحض: ا ت ج ف ق ك لب ي، م، وهي: ك م، وهو: ت.\r5 ـ نصفيها: ت ج ف ق لب م، نصفيه: ك ي، نصفها: ل. بقى متحركا: ت ج ق ك م، هو متحرك: ف لب ل ي.\r6 ـ الان: ج ل ف ت، لا: م، متحرك: ت ج ف ل ق ي، يتحرك: ك لب ي، لا ما: ج ك م ص، لما: ت، وراءها: في: ف فقط.\r7 ـ فحينئذ لا: ك م ف، فلا: ت ج ل.\r8 ـ الجهة حد: ت ج ق ك لب ل م، الحد جهة: ا، الجهة: ف ي، غير منقسم: ت ج ق لب م ي، غير منقسمة: ف، منقسم: ك.\r9 ـ كرى: ت ج ف ق ك لب م ي، كذا: ا. يحدد: ت ج، يتحدد: ك ل م.\r10 ـ بمركزة: ت، مركة: ك م ج ل، المحدد: ت ج ق م، المحدث: ك، المستقيمة: ت ج ف ق ك لب م ي، المتقسمة: ا."], [321, "لكانت الجهتان، أعنى ما عنه وما إليه، حاصلتين له لا به وإذا لم يكن قابلا للحركة المستقيمة لزم أن لا يكون ثقيلا ولا خفيفا، لأن الثقيل هو الّذي ينزل إلى الوسط والخفيف هو الّذي يصعد عنه وذلك حركة مستقيمة وأن لا يقبل الخرق والالتئام. لأن ذلك حركة مستقيمة. وإذا لم يقبل الخرق والالتئام كان بسيطا، لأن كل مركب قابل للانحلال البسيط، وكل جزء يفرض فيه يمكن أن يحصل على الوضع الّذي حصل عليه الجزء الآخر. وكل ما كان كذلك كان قابلا للحركة. وكل ما كان كذلك، ففيه ميل بحركة. وكل\r__________________\r1 ـ لكانت: ا ت ج ف ق ك لب ي، كانت: م، حاصلتين: ق، حاصلتان: ت ج ك م، له: ا ت ج ف ق ك لب ي، م.\r2 ـ قابلا: ا ت ج ف ق ك لب ي، قابل: م، المستقيمة: ت ق ج ك م ص، المتقسمة: ا.\r3 ـ الثقيل: ت ف ق ك لب م، الهفيل: ي: ا، ينزل .. هو الذي: ا ت ج ف ق ك لب ي: م، يصعد: ك ل م، يتصعد: ت ج.\r4 ـ حركة: ك م ت، بحركة: ق، مستقيمة: ت ج ف ق ك لب م ي، منقسمة: ا، ان لا: ا ت ج ل، لم: ك لب م ي.\r5 ـ حركة: ت ج لب م، بحركة: م ي، منقسمة: في: ا، الالتثام: ا ف،: ت ك ج ق م.\r4، 5 ـ وان لا يقبل ... مستقيمة: ف ق.\r6 ـ قابل: ك م، قابلا: ت، وكل بسيط فكل جزء منه: ت ج، وكل بسيط فكل جزء يفرض فيه: ك لب ل م ي، وكل بسيط بكل وكل بسيط: ق، الى البسيط وكل: ا جزء: ق يفرض فيه: ا ف ق.\r7 ـ يحصل على: ت ج ل ف ق ك لب ي، يحصل في ا، يتحصل على: م، حصل: ت ج ق لب م، حصلت: ي: ف، وكل: ت ج ف ك م ي، فكل: ا، وكل .. كان: لب.\r7، 8 ـ كذلك كان: ف.\r8 ـ وكل ما ... يحركه محركه: لب، محرك: ت ج ل، يحرك: ك: ت ج ق ك لب م، المستدبرة وكل ما .. محركة: ف،: ا."], [322, "ما كان كذلك، فهو متحرك بالاستدارة وكل متحرك بالاستدارة فحركته ليست طبيعية، وإلا لتحرك بالطبع إلى ما هرب عنه بالطبع فيكون الطبيعة الواحدة طالبة للشيء الواحد، وهاربة عنه، وهو محال ولا قصرية، لأن القصر ما يكون على خلاف الطبع. وهناك لا طبع، فلا قصر، فتلك الحركة إرادية، فالسماء حيوان متحرك بالإرادة.\rوالجواب عن هذه الكلمات مستقصى فى كتبنا الكلامية والحكمية.\rوأما العناصر فزعموا أن الأرض محفوفة بالماء، والماء بالهواء والهواء بالنار. وانها كرات منطو بعضها على البعض إلا الماء، وزعموا أن الحركة مسخنة فالجرم الملاصق للفلك يجب أن يكون فى غاية السخونة واللطافة، وهو النار. والّذي يكون فى غاية البعد يجب أن يكون فى غاية البرودة، والكثافة، وهو الأرض والّذي يلاصق النار وهو الهواء يكون تاليا لها فى اللطافة. والّذي يلاصق الأرض وهو الماء يتلوها فى الكثافة. فهذا هو الوصف المحكم فى ترتيب العناصر، إلا أن هذا الكلام يقتضي أن يكون الأرض أبرد من الهواء،\r__________________\r1 ـ وكل متحرك بالاسندارة: ا ت ج ف ق ك لب ي: م.\r2 ـ طبيعية: ا ت ج ف ق ك لب ي، بطبيعية: م، الى ما هرب عنه: ا ت ج، الى ما تحرك منه عنه: ق لب ل ي: ف ق لب ي، عما عنه يتحرك: م، الى ما عنه يتحرك: ك.\r3 ـ الطبيعة: ت ج ف ق لب م، الطبع: ا، الطبيعية: ك.\r4 ـ الطبع: ك ل م، الطبيعة: ت ج.\r7 ـ الجواب في: لب ج، الكلمات: ا ت ج ف ق ك لب ي، الكليات: م، مستقصى: ج ك م، مستقضى: ت، كتبنا: ا ت ج ف ك لب ي، كتب ق م.\r9 ـ و (1): ت ج ف ك: م، فزعموا: ت ق ك لب م ي، فزعم: ف.\r10 ـ منطو: ج ك م، منطبق: ت ل، البعض: ج ك م، بعض: ت ل، زعموا: ت ج ق ك لب م ي، زعم: ف.\r16 ـ هذا: ق ك ل م ي: ف، الهواء: م، الماء: ت ج"], [323, "وهو على خلاف قولهم. وأن يكون النار فى غاية الرطوبة، لأن الرطوبة عندهم مفسرة بسهولة قبول الأشكال، لا بسهولة الالتصاق بالغير، وإلا لم يكن الهواء رطبا.\rثم زعموا أن هذه الأربعة قابلة للكون والفساد. ولأن النار عند انطفائها تنقلب هواء، والهواء إذا برد صار ماء. ولذلك تجتمع قطرات الماء على طرف الكوز المبرد بالجمد. والماء ينقلب أرضا والأرض ماء، كما يفعله أصحاب الاكسير.\rوأما المركبات فزعموا أن هذه العناصر إذا اختلطت انكسرت سورة كيفية كل واحد منها بسورة كيفية الآخر، فتحصل كيفية متوسطة وهى المزاج.\rوالمتكلمون قالوا: العلة مقارنة للمعلول. فإذا كان الكاسر لسورة كل واحد منهما هو سورة الآخر فإن حصل الانكساران\r__________________\rف ق ل.\r2 ـ قبول الاشكال: ت ج ف ق ك لب ي، القبول للاشكال: م. الالتصاق: ج ق م، الانصاف: ت ك ل ف.\r3 ـ بالغير: ا ت ج ف ق ك لب ي، بالتحيز: م.\r5 ـ انطفائها: ت ج ق لب م ي، انطباقها: ف، هواء: ت ق لب م ي، ف، تجتمع: ا ت ج ف ق ك لب، تجمع: م.\r6 ـ فطرات: ت ق ك لب م ي، ف، على: ا ت ف ق ك لب ي، في: م.\r7 ـ والارض ماء: ا، ت ج ف ق ك لب م ي.\r8 ـ واما: ت ك م، اما: ق.\r9 ـ سورة (1، 2): ق ك ل م ي، صورة: ف، منها: ت ج ف ق م، منهما: ك ل.\r10 ـ و: ف: ت ق ك لب م ي.\r11 ـ مقارنة للمعلول: ت ج ف ق ل لب ي، مقاومة للمعلول: م.\r12 ـ منهما: ج ق م، منها: ت ك، سورة الآخر: ت ج ق ك لب م ي، صورة الاخرى: ف."], [324, "معا دفعة واحدة لزم حصول الكاسرين فى ذلك الزمان فيكون كل واحدة من تينك الكيفيتين فى ذلك الآن منكسرة وغير منكسرة، هذا خلف. وإن لم يوجد معا فهو محال، لأن المغلوب لا يعود غالبا.\rلا يقال الكاسر هو الصورة المقومة، وهى باقية من غير انكسار، والمنكسر: هو الكيفية، وهى قابلة للأشد والأضعف.\rلأنا نقول الصورة إنما تكسر بواسطة الكيفية الفائضة عنها فيعود المحذور المذكور فهذا تمام القول فى الجواهر الجسمانية.\rالجواهر الروحانية\rوهى التى لا تكون متحيزة ولا حالة فى المتحيزة.\rوقد عرفت أن الفلاسفة هم القائلون بها. وعرفت أقسامها، فنقول اما الهيولى فقد سبق الكلام فيها. وأما الأرواح البشرية، فسيأتى القول فيها ان شاء الله تعالى. وأما النفوس السماوية\r__________________\r1 ـ معا: ت ج ف ل: ق ك م ي.\r1، 2 ـ فيكون ... غير منكسر: ف ق ك ل م، كاسرا منكسرا: ي.\r2 ـ نبنك: تلك: ك، الان: ت ج ف ك ل لب م، الزمان: ا ق، منكسرا: ق ك م، منكسرين: ا.\r3 ـ ان: ت ج ق م، اذا: ك، بجدا: ك م، يوجد: ت ج المغلوب لا يكون غالبا: ا، المعلول لا يعود علة، ق ك ي، المعلول يعود غالبا: م.\r6 ـ عنها: ت ج ف ل: م.\r7 ـ الجسمانية: ت ج ق م، الجسمانيات: ك.\r9 ـ المتحيزة: ت، المتحير: ج ك ل م.\r10 ـ وقد: ك ل م، فقد: ت ج، هم القائلون: ت ج ق، يقولون: ك.\r11 ـ فقد: ا ت ج ف ق ك لب ي، وقد: م، فيها: ق م ج هامش، عليها: ك، فيه: ت ج."], [325, "والعقول، فهى الملائكة، وقد تكلمنا على أدلتهم فى اثباتها.\rالقول فى الملائكة والجن والشياطين:\rقال المتكلمون: إنها أجسام لطيفة قادرة على التشكل بأشكال مختلفة. والفلاسفة وأوائل المعتزلة أنكروها. قالوا: لأنها إن كانت لطيفة بمنزلة الهواء وجب أن لا تكون قوية على شيء من الأفعال وأن يفسد تراكيبها بأدنى سبب. وإن كانت كثيفة، وجب أن تشاهدها، وإلا لجاز أن يكون بحضرتنا جبال شاهقة ولا نراها.\rوالجواب لم لا يجوز أن تكون لطيفة بمعنى عدم اللون، لا بمعنى رقة القوام.\rسلمنا أنها كثيفة، لكن بينا أن أبصار الكثيف عند الحضور غير واجب.\rأما الفلاسفة فقد زعموا أنها لا متحيزة ولا قائمة بالمتحيز. ثم\r__________________\r1 ـ اثباتها: ت ج ق ك لب م ي، اثبات القول: ف.\r2 ـ اما: ج القول في الملائكة و: ت ج ل م، على ما سياتي واما: ك، واما: ق، في الملائكة و: ف.\r3 ـ لطيفة: ت ج ف ك لب م ي، لطبع: ا.\r4 ـ وقالوا: في: ف.\r5 ـ لا تكون قوية: ت ج ك ل ي، لا تكونوا قوية: ف ل، لا يكون قوته: ق، لا يكون لها قوة قوية: ا: ا م.\r6 ـ تراكيبها: ا ت ج ق ل ي، تراكبها: ف لب م، تركيبها: ك، كثيفة: ت ج لب ل م، كيفية: ف.\r7 ـ نشاهدها: ج لب م، يشاهدها: ي، شاهدها: ت ف ق ك ل ي، شاهقة: ا ت ج ل: ف ق ك لب م ي، ولا: ت ق ك ل م، ونحو لا: ج، لا: ف لب ي.\r9 ـ القوام: ت ج ف ق ك ل لب م ي، للقيام: ا.\r10 ـ كثيفية: لب م ي، كثيفة: ت ج ق ل ك، كيفية: ف. الحضور: حضور الشرائط: ج.\r12 ـ اما: واما: م، انها: ت ج ل م، لن الشياطين: ق."], [326, "اختلفوا فالأكثرون قالوا: انها ماهيات مخالفة بالنوع للأرواح البشرية. ومنهم من يقول الأرواح التى فارقت الأبدان إن كانت شريرة كانت شديدة الانجذاب إلى ما يشاكلها من النفوس البشرية فتتعلق ضربا من التعلق بأبدانها وتعاونها على أفعال الشر، فذلك هو الشيطان. وإن كانت خيرة كان الأمر بالعكس. والله أعلم بحقائق الأمور.\rخاتمة فى أحكام الموجودات\r"]], "pg": [262, 326]}, "687.8": {"x": [[326, "والنظر فيها من وجهين:\rالأول فى بيان الوحدة والكثرة:\rمسئلة:\rكل موجودين فلا بد وأن يتباينا بتعينهما. ثم المتكلمون أنكروا كون التعين أمرا ثبوتيا واحتجوا بأمور:\r__________________\r1 ـ فالاكثرون قالوا انها ماهيات: ف م، فالاكثرون على انها: ت ج، فقال الاكثرون انها ماهيات: ل.\r2 ـ يقول: ت ج ف ق لب ل م ي، قال: ا، قالوا: ك، التي فارقت: ت ج ف ق ك لب ل ي، الذي فارقت: ا، البشرية التي كانت: م، الابدان: ت ج ل، ابداتها: ك م، ان: ت.\r3 ـ شديدة: ف، النفوس: النفس: ا.\r4 ـ النشر: ت ج ق ك م ي، البشر: ق ل لب.\r5 ـ بالعكس: على العكس: ف.\r5، 6 ـ والله اعلم بحقائق الامور الاشياء: ت ق ك لب ي: ت ق ك لب ل ي، والله اعلم: ا، ف م.\r8 ـ فيها: ت ج ف ل لب: ق ك م ي.\r9 ـ النظر الاول في الوحدة: ق ل لب م ي، ا: ا الاول في بيان: ا الوحدة: ا ت ج ف ك.\r11 ـ تابينا بتعينهما بتعيينهما: ا ف ق لب ي: ا ت ج ل د ف ق لب ي، يكون متباييتين بنفسه: م، ثم: و: ف، انكروا انكر: ل وتقدم على المتكلمون.\r12 ـ التعين: التعيين: ا، المتعين: ي."], [327, "الأول أنه لو كان التعين أمرا ثبوتيا، لكان مساويا لسائر التعينات فى الماهية المسماة بالتعين، ويمتاز كل واحد منهما عن صاحبه بخصوصية، فيلزم أن يكون للتعين تعين آخر إلى غير النهاية.\rالثانى وهو أنه لو كان التعين أمرا ثبوتيا لاستحال انضمامه إلى الماهية إلا بعد وجود الماهية، لكن الماهية لا توجد إلا بعد التعين. فإن كان هذا التعين، هو الأول لزم الدور، وإن كان غيره، لزم أن يكون الشيء الواحد متعينا مرتين وهو محال.\rالثالث وهو أن التعين لو كان أمرا مغايرا للماهية لاستحال أن يكون الوجود القائم بأحدهما هو الوجود القائم بالآخر لاستحالة قيام الصفة الواحدة بمحلين بل يكون وجود كل واحد منهما غير وجود الآخر، فيكون الشيء الواحد ليس بواحد بل اثنين. ثم الكلام\r__________________\r1 ـ الاول: ت ق لب ل م ي، احدها: ف ك، اولها: ج، ا، التعين: التعيين: ا.\r1، 2 ـ لسائر اتعينات: ف ك ل م، لسائريه معا في ج للتعينات: ت ج.\r2 ـ منهما: ف ق ك ل م، منها: ت ج لب ي، ا.\r3 ـ بخصوصية: بخصوصينه: ا.\r4 ـ النهاية: م ف ل، نهاية: ت ج ف.\r5 ـ الثاني: ت ق ك لب م ي، ب: ا، والثاني: ف ل، وثانيها: ج انه لو كان التعين: ا ت ج ف ق ك لب ل ي، ان التبين او كان: م.\r6 ـ الا: م فقط.\r7 ـ فان: فلو: ت ج.\r7، 8 ـ لزم ان يكون: ت ج ل، كان: ك م.\r8 ـ متعينا: معينا: في: ت ف ل م.\r9 ـ الثالث و: ف هو: ت ف ق ك لب ل م ي، ثالثها وهو: ج، ج: ا، لو: ف ت ج ل، اذا: ق ك لب م ي. لاستحال: ف ج، استحال: ت ق ك ل لب م ي.\r11 ـ كل واحد منهما: ا ت ج ف لب ي، احدهما: م."], [328, "فيهما كما فى الأول فالشيء الواحد ليس بواحد بل موجودات غير متناهية.\rواحتج القائلون بكون التعين أمرا ثبوتيا بأن هذا الإنسان يشارك الإنسان الآخر فى كونه إنسانا، ويخالفه فى هويته، فهويته مغايرة للإنسانية. وتلك الهوية صفة ثبوتية، لأن هذا الإنسان موجود، والمفهوم من هذا جزء المفهوم من هذا الإنسان. وجزء الموجود موجود فالمفهوم من هذا موجود.\rمسئلة:\rالغيران إما أن يكونا مثلين، أو مختلفين. والمختلفان اما أن يكونا ضدين، وهما الوصفان الوجوديان اللذان يمتنع اجتماعهما لذاتيهما كالسواد والبياض، واما أن لا يكونا كذلك، كالسواد والحركة.\rواختلف المتكلمون فى الغيرين. فالمعتزلة قالوا: هما الشيئان وأصحابنا قالوا: هما اللذان يمكن أن يفارق أحدهما الآخر، إما بمكان، أو بزمان أو وجود أو عدم. والخلاف لفظى محض.\r__________________\r1 ـ فالشيء الواحد: ا ت ج ف ق ك لب، ولا شيء من الواحد: م، فالشيء: ي، بواحد بل موجودات: ل، امور: ك م، واحدا بل موجودات: ت ج.\r3 ـ امرا: ج، بان: ت ج ف ق ك ل ي، زائدا بان لب م.\r5 ـ للانسانية: ت ج ف ق ك لب م، للانسان: ي.\r9 ـ او مختلفين: ت ج ف ق ك ل لب م، ا.\r11 ـ كالسواد (1): ج ف ق ل م، كسواد: ت.\r12 ـ هما: ا ت ف ق ل لب ي، م.\r14 ـ هما: ت ج ك م ي: ق لب، يمكن: ت ج لب م ي، يكون: ف ق.\r15 ـ بمكان: ت ج ف لب م، المكان: ا، يزمان: م، زمان: ت ج ك، او عدم: ا ج ف ك ي، وعدم: ت ق لب م موجودا وعدما: هامش لب، محض: ج."], [329, "أما المثلان فحدوهما بأنهما اللذان يشتركان فى الصفات الذاتية أو أنهما اللذان يقوم كل واحد منهما مقام الآخر، أو يسد مسده، وهذه العبارات مختلفة لأن الاشتراك مرادف للتماثل. والقيام مقام الآخر لفظة مستعارة حقيقتها التماثل، فيكون ذلك تعريفا للشىء بنفسه. وهو محال. والحق أن هذه الماهيات متصورة تصورا أوليا، لأن كل واحد منا يعلم بالضرورة أن السواد يماثل السواد، ويخالف البياض وتصور المماثلة والمخالفة جزء ماهية هذا التصديق. وجزء البديهى أولى أن يكون بديهيا والله أعلم.\rمسئلة:\rيستحيل الجمع بين المثلين عندنا، وعند الفلاسفة خلافا للمعتزلة.\rلنا أن بتقدير الاجتماع لا يحصل الامتياز بالذاتيات واللوازم. وإلا لما كانا مثلين. ولا بالعوارض، لأن نسبة جميع العوارض إلى كل واحد منهما على السواء، فلا يكون كونه عارضا لأحدهما أولى من كونه عارضا للآخر، فيكون عارضا لكل واحد منهما. وحينئذ\r__________________\r1 ـ فحدوهما: ت ج ق ك م، فحددهما: ف، فحدهما: لب.\r2 ـ او (1): ت ج ق ك لب م، و: ف، منهما: ق. او (2): ت ج ق ك م، و: ف ل ي.\r3 ـ للتماثل: ت ك م، التماثل: ق، القيام: ت ج ق ك لب م ي، القائم: ا.\r5 ـ وهو محال: ا، ت ج ف ق ك لب م ي.\r6 ـ منا: ف، ت ق ك لب م ي.\r7 ـ هذا: ت ج ف ق ك لب م ي، ا.\r8 ـ بديهيا والله اعلم: ج.\r11 ـ ان: ف ق ك م،: ل.\r12 ـ كانا: ت ج ق ك لب م ي، كان: ف، بالعوارض: ا ت ج ف ق ك لب ي، بالعرض: م.\r13 ـ بالسواء: ت ج ل، السوية: ك م."], [330, "لا يبقى الامتياز بينهما البتة فيكون الاثنان واحدا، وهو محال. احتج الخصم بأن حكم الشيء حكم مثله فإذا كانت الذات قابلة لأحد المثلين كانت قابلة للآخر.\rجوابه أن الاجتماع يوجب انقلاب الاثنين واحدا وهو محال.\rمسئلة:\rزعم بعضهم أن الغيرين يتغايران لمعنى، وكذا المثلان والضدان والمختلفان.\rواحتجوا عليه بأن المفهوم من كون السواد والبياض سوادا، وبياضا، مغاير للمفهوم من كونهما غيرين، ومختلفين؛ وضدين ولذلك كان التغاير، والاختلاف، والتضاد، حاصلا فى غير السواد،\r__________________\r1 ـ الا ان منهما: ت ج ق ك لب م ي، بينهما الامتياز: ا. وهو الانسان: تيميز الانيان: ا. وهو محال: ت ج ق ك لب م ي، يوما الى: ا ي.\r2 ـ احتج: ب ج م، واحتج: ق ك ل، فاذا: ت ج ق م، اذا: لب ك لب ي.\r2، 3 ـ الحود المعلين لاحدهما: ي كانت قابلة: ا ت ج ف ق ك الى ب.\r4 ـ وجود الى: ك، وهو محال: ف فقط.\r9 ـ بنظرتين لمشي: ا ت ف، لمعنى زائد: ل، بمعنى: ك، مسنى: ي، لمعنى: ج. المثلان: ت ولكن الى لب ك لب ي ج ف ق ك الى ب.\r8 ـ و ... ت ج ل ق ك لب ي: م، عليه: ا: ت ل ك لب ج.\r10 ـ الثاني: ت م ل، كذلك فان: ف لب، كذلك بان: ت ج ل ك م الائتلاف تاخر الى بعد انتضاد في: ف، حاصلا: ت ج ل، ك م ق، امر لب ي، حاصلة: م، غير: ت ج ق ك."], [331, "والبياض. وظاهره أنه ليس أمرا سلبيا فهو أمر ثبوتى، فثبت أن المتغايرين يتغايران لمعنى. وكذا المثلان يتماثلان لمعنى: وكذا المختلفان والضدان، ثم قالوا: وذلك المعنى لا بد وأن يغاير غيره. فمغايرته لغيره معنى قائم به، وهو لا بد وأن يكون إما مثلا لغيره أو مخالفا فمماثلته ومخالفته لغيره معنى قائم به ثم الكلام فيه كما فى الأول وهو يوجب القول بمعان لا نهاية لها. فالتزموا ذلك وكلامنا فى هذا الباب فقد تقدم والله أعلم.\rالنظر الثانى فى العلة والمعلول:\rمسئلة:\rكون الشيء مؤثرا فى غيره متصور تصورا بديهيا لانا ببداية\r__________________\r1 ـ وظاهره: ك م، فظاهر: ت، وظاهر: ج ل، امرا: ي، امر: ي.\r2 ـ يتغايران لمعنى: ا ت ج ف ق، يتغايران بمعنى: ك، متغايران بمعنى: لب م ي، وكذا المثلان المتماثلان: ق يتماثلان مقابلان: م: ا ت ج ل ق ك م، ف لب ي، لمعنى وبدا (2) ... والغيران: ا، المتماثلان متماثلان بمعنى: ي، المثلان والمثلان: لب، وكذا الضدان: لب، لمعنى بمعنى: ك.\r3 ـ ثم: ت ك م، ثم ذلك المعنى: ج، ثم اعترض عليهم: ف، وذلك: ت ك م، ذلك: ق ل، ج، المعنى: ت ق ك م ي، ف.\r4 ـ هو: ا ت ج ف ق ك ي، هو انه: م، او: ا ت ج ق ك لب ل ي، او مخالفا له: ف، او مغايرا له ومخالفا: م.\r5 ـ فمماثلته: ت ج ف ق ك ل لب ي، ومماثلته: م: مع يره: ت ك لب م ي، بغيره: ف، ا ت. لغيره: ا ج، مع غيره: ت ل: له: ف ق ك لب م ي.\r6 ـ وهو: ت ج ف ق لب م ي، وهذا: ا، فاتزموا: ق ف ل ك لب م، والتزموا: ت ج ي، فالزموا: ا.\r7 ـ الباب: ك ج م، الكتاب: ت ل، فقد تقدم: ت، قد تقدم: ج ق ف ك ي، قد مر: لب، والله اعلم: ا، ف ج ق ك لب م ي.\r10 ـ غيره: ت ج ل م، الغير: ك، منصور: ت ج"], [332, "العقول نعلم معنى قولنا قطعت اللحم، وكسرت القلم، والتقطيع، والتكسير تأثير مخصوص. فلما كان تصور التأثير المخصوص بديهيا، كان تصور مسمى التأثير الّذي هو جزء ماهية التأثير المخصوص أولى أن يكون بديهيا.\rمسئلة:\rالعدم لا يعلل، ولا يعلل به. لانا إن جعلنا العلية والمعلولية وصفين ثبوتيين، استحال كون العدم علة ومعلولا لاستحالة قيام الموجود بالمعدوم. وان لم نقل به، كان التأثير عبارة عن حصول الأثر عن المؤثر. وذلك يستدعى أصل الحصول.\rوقالت الفلاسفة: علة العدم عدم العلة. لأن الممكن دائر بين الوجود والعدم. فكما يستدعى رجحان الوجود علة وجودية فكذا يستدعى رجحان العدم علة عدمية.\rوالجواب أن العدم نفى محض فيستحيل وصفه بالرجحان.\rمسئلة:\r__________________\rمنصورة: ق، بديهيا: ت ق ك لب ج ل م ي، اولا: ف.\r1 ـ العقول: ت ج ق ل م، عقولنا: ك، القلم: ت ك م، العظم: ق.\r6 ـ لانا: ت ج ق ك م ي، فانا: ف لب، ان: ك.\r7 ـ استحال: ت ج ف ق ك م ي، فاستحال: لب، كون: تكرر في: ق، العدم: ا ت ج ل، المعدوم: ف ق ك لب م ي.\r9 ـ مر: ت ق ك لب م ي، من: ف.\r11 ـ فنكما: ا ف ك لب، وكما: ق م ي، فلما: ت ج، يستدعى: ت ق م، استدعى: ج ك، فكذا: ف، ت ج ك لب م ي.\r12 ـ يستدعى: ف ق ك لب ي، استدعى: ت ج م.\r13 ـ انعدم: ت ق م، المعدوم: ك."], [333, "المعلول الواحد بالشخص يستحيل أن يجتمع عليه علتان مستقلتان، وإلا لكان مع كل واحدة منهما واجب الوقوع فيمتنع اسناده إلى الآخر فيستغنى بكل واحد منهما عن كل واحد منهما وهو محال.\rمسئلة:\rالمعلولان المتماثلان يجوز تعليلهما بعلتين مختلفتين عندنا خلافا لأكثر أصحابنا. لنا أن السواد والبياض مع اختلافهما يشتركان فى المخالفة والمضادة. احتجوا بأن افتقار المعلول إلى العلة المعينة ان كان لماهيته، أو لشيء من لوازمها فإن كان لشيء من لوازمها وجب فى كل ما يساوى ذلك المعلول أن يفتقر إلى مثل تلك العلة. وإن لم يكن لماهيته ولا لشيء من لوازمها، كانت تلك الماهية غنية عن تلك العلة. والغنى عن الشيء يستحيل تعليله به.\r__________________\r1 ـ الواحد: ك ج م، واحد: ت.\r2 ـ مع كل: ت ج ق م، كل: ك، واحدة: ت، واحد: ك ج م.\r3 ـ اسناده: ت ج ف ك لب، استناده: ق م ي، الاخرى: في: ف ق ي. فيستغنى: ا ت ج ف ق ك، فيستغن: م واحد (1، 2): ت ج م، واحدة: ف ق ك ل، عن كل واحد منهما: ت.\r4 ـ وهو: وهما: ل.\r6 ـ عندنا: ت ق ج لب ل: م ي مشطوب في: ك.\r8 ـ احتجوا: ت ك م، واحتجوا: ف لب ج ي.\r8، 9 ـ ان كان الماهيته: ت ج ف ك لب م ي، اما ان كان لماهية: ا، ان كان لماهية: ق.\r9 ـ لشيء: ت ك ق لب م ي، لشيء آخر: ف، فان كان ... لوازمها: ا، ت ج ف ق ك م.\r11 ـ لماهيته ... لوازمها: ج، لشيء ل لوازم تلك الماهية: ل م ف ق، كانت تلك الماهية: ت ج ف ق لب ل م ي، كانت الماهية: ك، ا.\r12 ـ تعليله به: ت ج ق ل ك م، ان يعلل به: ف لب ي."], [334, "والجواب أن المعلول لماهيته مفتقر إلى مطلق العلة. وتعين العلة إنما جاء من جانب العلة لا من جانب المعلول.\rمسئلة:\rالعلة الواحدة يجوز أن يصدر عنها أكثر من معلول واحد عندنا، خلافا للفلاسفة والمعتزلة. لنا أن الجسمية تقتضى الحصول فى المكان وقبول الأعراض.\rاحتجوا بأن مفهوم كونه مصدرا لأحد المعلولين غير مفهوم كونه مصدرا للآخر، فالمفهومان المتغايران إن كانا داخلين فى ماهية المصدر لم يكن المصدر مفردا، بل كان مركبا، وإن كانا خارجين كانا معلولين، فيكون الكلام فى كيفية صدورهما عنه كالكلام فى الأول، فيفضى إلى التسلسل وإن كان أحدهما داخلا، والآخر خارجا، كانت الماهية مركبة، لأن الداخل هو جزء الماهية وماله جزء فهو مركب وكان المعلول أيضا واحدا، لأن الداخل لا يكون معلولا.\rوالجواب ان مؤثرية الشيء فى الشيء ليست صفة ثبوتية على\r__________________\r1 ـ والجواب: ف، تحين: ف ق ك لب م، يعين: ت، تعيين: ل ي، معنى: ا.\r2 ـ جاء: ت ج ف ق ك ل لب م، جاز: ي.\r3 ـ يجوز: ا فقط.\r6 ـ المكان: ت ج ق م، العيز: ك المكان في: ك بين اسطور.\r8 ـ تلاخر: ت ج ف ق ك لب ي، للاخرى: م.\r9 ـ مفردا: ت ج ق م، فردا: ا ف ك لب ي، كان: ا ت ف ق لب ي، يكون: م، ك ج.\r12 ـ فهو مركب: ا ت ج، كان مركبا: ف ق ك لب م ي، كان: ت ج ل.\r13 ـ واحد: في: ت.\r14 ـ في: ت ف ق ك لب م ي، من: ا، منطقة ثوتية: ت ج ق ك م، امرا ثبوتيا: ك،"], [335, "ما بيناه. وإذا كان كذلك بطل أن يقال إنه جزء الماهية أو خارج عنها.\rوالّذي يدل عليه، وهو أن مفهوم كون النقطة محاذية لهذه النقطة من الدائرة غير مفهوم كونها محاذية للنقطة الأخرى، ولم يلزم من تغاير هذه المفهومات كون النقطة مركبة. وكذا مفهوم كون الألف «آ» ليس «ب» مغايرا لمفهوم إنه ليس «ج». ولم يلزم من تغاير هذه السلوب وقوع الكثرة فى الماهية فكذا هاهنا. والله أعلم.\rمسئلة:\rالعلة العقلية يجوز أن يتوقف إيجابها لأثرها على شرط منفصل خلافا لأصحابنا لنا أن الجوهرية توجب قبول الاعراض بأسرها لكن صحة كل عرض مشروط بانتفاء ضده عن المحل.\rمسئلة:\rالعلة العقلية يجوز أن تكون مركبة عندنا، خلافا لأصحابنا.\r__________________\r1 ـ خارج، ت ج ق م، خارجا: ك.\r3 ـ الذي يدل عليه: ت ج ق ك م، الدليل: ف لب ي، و (2): ق.\r5 ـ هذه المفهومات: ت ج ق ك لب م ي، الذين الموحين: ف.\r6 ـ مغايرا لمفهوم انه: ا، مغاير المفهوم انه: ت ج ف ك لب ي، كونه انه: ق: ت ج ف ك لب م ي.\r7 ـ تغيير: ا ت ج ف ق ل ك لب ي، تغير: م، هذه: ت ق ك لب م ي، هذا: ف، هنا: في كي.\r7، 8 ـ وانه اعلم: ا فقط.\r10 ـ لاثرها: ك م، للاثر: ت ج الاثر: ل.\r11 ـ لنا ان البتوهرية الجوهر: ا ... قلنا: ك .. لاصحابنا: ت: ف ق ك ل لب م ي،: ا.\r12 ـ مسقة: ت ج، صحة وجود: ل."], [336, "لنا أن العلم بكل واحدة من المقدمتين لا يستلزم العلم بالنتيجة. والعلم بهما يوجب العلم بالنتيجة. وكذا كل واحد من آحاد العشرة لا يوجب صفة العشرية. ومجموع تلك الآحاد يوجب هذه الصفة. احتجوا بأن كل واحد لما لم يوجب، فالمجموع أيضا لا يوجب لأن الماهية باقية كما كانت.\rوالجواب النقض بما مر وبالله التوفيق.\r__________________\r1 ـ واحدة: ت ج ق ك، واحد: م.\r2 ـ والعلم بهما يوجب ... بالنتيجة: ت ج ق ك لب ل م ي، ف، وكذا: ت ج ك م، وكذلك: ف ق لب ي.\r3 ـ هذه الصفة: ا ت ج ف ق ك ل ي، العشرية: ق لب م.\r4 ـ احتجوا: واحتجوا عليه: م، كل واحد: واحدا: م. ايضا لا يوجب: ت ج ك، لا يوجب ايضا: ق ل م.\r5 ـ لان: ق ل م، فان: ت ج ك.\r6 ـ والجواب: ت ج ق ك ل م ي، وجواب: ف، الجواب: لب، بما مر: ا ت ج ف ق ك ل ي، لما مر: لب: م، وبالله التوفيق: ق ك م، والله اعلم بحقائق الامور: ج: ت ج، والله تعالى اعلم بالصواب، ثم الركنين الاولين من هذا الكتاب .. انفراغ من كتابته .. من شهر الله .. سنة احدى وخمسين وستمائة: ل."], [337, "الركن الثالث\rفى الالهيات\rوالنظر فى الذات والصفات والأفعال والأسماء\rالقسم الأول\r"]], "pg": [326, 337]}, "687.9": {"x": [[337, "فى الذات\rقد عرفت أن العالم اما جواهر واما أعراض. وقد يستدل بكل واحد منهما على وجود الصانع اما بامكانه أو حدوثه فهذه وجوه أربعة:\rالأول الاستدلال بحدوث الأجسام: وهو طريقة الخليل عليه السلام فى قوله تعالى: (لا أُحِبُّ الْآفِلِينَ). وتحريره: إن العالم محدث، وكل محدث فله محدث أما الأول فقد مر.\rوأما الثانى فالدليل عليه أن المحدث ممكن، وكل ممكن فله\r__________________\r3 ـ الذات: ت ج ق ك ل م ي، الذوات: ف لب.\r4 ـ الاول: ا: ا.\r5 ـ الذات: الذوات: ف لب.\r6 ـ جواهر .. اعراض: جوهر .. عرض: ف لب، الجوهر .. الاعراض: ل.\r7 ـ امكانه او حدوثه: بحدوثه او امكانه: ف.\r9 ـ الاول: ت ج ف ق لب م ي، الطريق الاول: ل، ا: ا.\r10 ـ تعالى: ت ج، تعالى انى: ف، ق ك ل لب م ي، تحريره: ف ك ل م، تقريره: ت ج.\r11 ـ فله: ك ل ف م، له: ت ج، اما: م، فقد مر: ا ت ج ف ك ل لب، فقد تقدم: ق، فتقدم: ي، تقدم: م.\r12 ـ اما: ت."], [338, "مؤثر. اما أن المحدث ممكن فلأن المحدث هو الّذي كان معدوما، ثم صار موجودا، وما هذا شأنه كانت ماهيته قابلة للعدم والوجود. ولا تعنى بالممكن إلا هذا. وأما أن الممكن لا بد له من مؤثر، فقد تقدم.\rفإن قيل الكلام على هذه المقدمات قد تقدم، إلا على قولنا: كل محدث ممكن.\rوقوله:\rالمحدث كان معدوما، ثم صار موجودا، فيكون قابلا للوجود والعدم لا محالة.\rقلنا من مذهبكم ان المعدوم ليس بشيء، ولا عين، ولا ذات، بل كان نفيا محضا. وإذا كان كذلك استحال الحكم عليه بالقبول، واللاقبول.\rسلمنا صحة الحكم عليه، لكن لم لا يجوز أن يقال أنها حين كانت معدومة كانت واجبة العدم لعينها. ثم فى زمان وجودها، صارت واجبة الوجود لعينها تقريره أن الشيء بشرط كونه مسبوقا\r__________________\r1 ـ ان: ت ج لب ل م ي، ف ك.\r3 ـ نعنى: ت ج ك ف ل، معنى: م، بالممكن: ت ج ف ل، للمكن: م.\r4 ـ تقدم: معدم: ا، تقدم ذكره: ق، سبق: ف لب ي.\r5 ـ قولنا: قولنا ان: م.\r6 ـ محدث ممكن: ممكن محدث: ا.\r8، 9 ـ للوجود والعدم للعدم: ف: للعدم والوجود: ك ل م.\r10 ـ ان: ا، و (1): م.\r11 ـ كان نفيا محضا: ت ج ف م، هو نفي محض: ل.\r12 ـ انها: ماهيته: ف.\r14 ـ لعينها: ف ك م، لذاتها: ت ج ق ل.\r15 ـ لعينها: ف ك م، لذاتها: ج ق ل، لذاته: ت، تقريره: وتقريره: ق لب، بشرط: شرط: ي."], [339, "بالعدم، لا يجوز فى العقل فرض تقدمه، لا إلى أول. وإلا لزم صحة كون الشيء مع كونه مسبوقا بالعدم ازليا، وذلك محال. فاذا لصحة وجوده بداية فقبل تلك الصحة، كان ممتنعا لذاته ثم انقلب ممكنا لذاته وإذا جاز ذلك، فلم لا يجوز أن يقال: كان ممتنعا لذاته، ثم انقلب واجبا لذاته.\rوالجواب: قولنا الممكن قابل للوجود والعدم، لا نعنى به ان تلك الماهية متقررة حالتى الوجود والعدم بل نعنى به أن الماهية لا يمتنع فى العقل بقاؤها، كما كانت، ولا يمتنع فى العقل بطلانها.\rقوله:\rلم لا يجوز أن تكون الماهية ممتنعة لذاتها فى وقت، ثم تنقلب واجبة لذاتها فى وقت آخر.\rقلنا: هب أن الأمر كذلك، لكن حصول الامتناع يتوقف على حضور وقته المخصوص، وحصول الوجوب يتوقف على حضور الوقت الآخر والماهية من حيث هى هى مع قطع النظر عن الوقتين لا يبقى لها إلا القبول.\r__________________\r1 ـ تقدمه: ت ج ف ك ل م، تقديمه: ا لب ي، وجوده: ق، اول: الاول: م.\r3 ـ فقبل: وقبل: لب ي.\r3، 4 ـ لذاته: ق ج ... لذاته: ف.\r4 ـ واذا: فاذا: ف ي.\r5 ـ ثم انقلب ... لذاته و: قولنا ثم انقلب ممكنا لذاته: ف.\r6 ـ قولنا: ان قولنا: ج ل م، قلنا: ق ك، العدم: ت.\r7 ـ حالتي: حالة: م، ان: ان تلك: ج ف.\r10 ـ الماهية: تلك الماهية: ف ك، في وقت: ت ج ق ك لب ل م ي،: ف، تنقلب: ت ج ق ك ل لب م ي، انقلبت: ا ف.\r11 ـ في وقت: ت ج ك لب ل م ي، ف، آخر: ق.\r13 ـ المخصوص: ت ق ك لب ج م ي، المخصوصة: ا.\r13، 14 ـ المخصوص ... الوقت: ف.\r14 ـ هي (1): ت."], [340, "قوله:\rالممكن المأخوذ بشرط كونه مسبوقا بالعدم لصحة وجوده أول.\rقلنا لا نسلم، وإلا لزم أن يكون فرض دخوله فى الوجود قبل ذلك الأول بمقدار لحظة يوجب صيرورته أزليا وذلك محال بالبديهة.\rالطريق الثانى: الاستدلال بالامكان وتقريره أن يقيم الدلالة على أن واجب الوجود يستحيل أن يكون أكثر من واحد، ثم يشاهد فى الأجسام كثرة فهى ممكنة. وكل ممكن، فله مؤثر على ما مر.\rالطريق الثالث: حدوث الاعراض مثل ما نشاهده من انقلاب النطفة علقة، ثم مضغة ثم لحما، ودما. فلا بد من مؤثر فيه، وليس المؤثر هو الإنسان، ولا أبواه. فلا بد من شيء آخر.\r__________________\r2 ـ وجوده: ت ج ف ق ك لب م ي، وجود: ا.\r3 ـ اول: ت ج ك لب م ي، بداية: ف، اولى: ق.\r5 ـ الاول بمقدار .. يواجب: ت ج ق ك لب ي، الاول بمقدار لحظة فوجب: ف، الوقت بلحظة يوجب: م.\r6 ـ الطريق الثاني ب: ا: ا ت ج ف ك، الطريقة الثانية: ق لب ي، النظر الثاني: م، بامكان الاجسام: في: ف، يقيم: ت م، نقيم: ف ج ك، سمم: ل.\r8 ـ يشاهد: ت ك م، نشاهد: ف ج، كثرة فهي: ت ج ف ق ك لب ل ي، كثيرة فهي: ا، كثرة: م.\r10 ـ الطريق الثالث: ت ف ج ك م، الطريقة الثالثة: ق لب ي، ج: ا، حدوث: ت ج ق ك لب م ي، الاستدلال بحدوث: ف، مثل: ك ل م، على: ت ج، نشاهده: ت م، تشاهد: ا ف ج ق ك لب ي.\r11 ـ فيه: ت ج فقط.\r11، 12 ـ من مؤثر .. ولا بد: ق.\r12 ـ فلا: ا ت ج ف ك لب ي، ولا: م، شيء: ت ج ف ل لب م، مؤثر: ك ي."], [341, "لا يقال لم لا يجوز أن يكون المؤثر هو القوة المولدة المركوزة فى النطفة.\rلأنا نقول: تلك القوة اما أن يكون لها شعور واختيار فى التكوين، وإما أن لا يكون والأول باطل، وإلا لكانت النطفة موصوفة بكمال القدرة، والحكمة، وهو معلوم الفساد بالبديهة.\rوالثانى أيضا باطل. لأن النطفة إما أن تكون جسما متشابه الأجزاء فى الحقيقة، وإما أن لا تكون كذلك. فإن كان الأول، لزم أن تخلق النطفة كرة لأن القوة البسيطة، إذا أثرت فى المادة البسيطة، لا بد وأن تفعل فعلا متشابها، وهو الكرة. وهذا هو الّذي عليه تعويل الفلاسفة فى كرية البسائط. وإن كان الثانى كانت النطفة مركبة من البسائط. وكل واحد من تلك البسائط، يكون القائم بها قوة بسيطة وذلك يقتضي الكرية. فيلزم أن تتخلق النطفة كرات مضمومة بعضها إلى البعض ولما بطل ذلك، علمنا أن المؤثر فى خلق أبدان الحيوانات، والنبات مؤثر حكيم.\r__________________\r1 ـ المتولدة في: ف، المذكورة في: ك ي.\r4 ـ التكون: في: ف.\r5 ـ القدرة: تكرر في: ت، القدرة والعلم: ج.\r6 ـ ايضا: تاخر الى ما بعد باطل في: ت ج.\r8 ـ لزم: ت ج ق لب م ي ك، يلزم: ف، تخلق: ت ج ل م، تتخلق: ف ق ك لب ي.\r9 ـ كرة: ت ق م، وهي الكرة: ك.\r11 ـ وكل: ت م، فكل: ق ك، بها: ق م، به: ك ج، فيه: ت.\r12 ـ الكرية: ا ت ج ف ق ك ل، الكروية: م.\r13 ـ مضمومة: ا ت ج ف ق ك لب ي، مضموم: م، البعض: ت ج م، بعض: ف ق ك لب ل ي، خلق: ك م، تخليق: ت ج ف ق ل لب ي، تعليق: ا.\r14 ـ مؤثر: مدبر: ل ج."], [342, "الطريق الرابع: امكان الاعراض وتقريره أن يقال الأجسام متساوية فى الجسمية، فاختصاص كل واحد منها بما له من الصفات ممكن لأن كل ما صح على الشيء صح على مثله والإمكان محوج إلى المؤثر على ما تقدم والله أعلم.\rمسئلة:\rمدبر العالم إن كان واجب الوجود، فهو المطلوب وإن كان جائز الوجود افتقر إلى مؤثر آخر. فاما أن يدور أو يتسلسل وهما باطلان، أو ينتهى إلى واجب الوجود وهو المطلوب.\rأما بطلان الدور فلأن الشيء، إذا احتاج إلى غيره، كان المحتاج إليه متقدما فى الوجود على المحتاج. فلو افتقر كل واحد منهما إلى الآخر، لكان كل واحد منهما متقدما فى الوجود على الآخر، فيلزم\r__________________\r1 ـ الطريق الرابع د: ا: ا ت ج ف ك م، الطريقة الرابعة: ف لب ي، امكان: ت ج ق ك لب م ي، الاستدلال بالامكان: ف، يقال: ت ج ك ل، تقول: ق م، الاجسام: ت ج ك م، ان الاجسام: ق لب ي، ان الاجسام باسرها: ف.\r2 ـ متساوية: ت ج ف ق ك م، متشابهة: لب ي ل.\r3 ـ ممكن: ت ج، يكون جائزا: ف ك ل م، على الشيء: ت ج ق لب م، على شيء: ف، من الشيء: ي، فالامكان: في: ي.\r4 ـ محوج: ت ج ق ك م ي، يحوج: ا ف لب ي، والله اعلم: ا، ت ج ف ق ك لب ل م ي.\r6 ـ المطلوب: المقصود في: ج.\r7، 8 ـ وهما باطلان: ا ت ج ف ق ك لب ي، م.\r8 ـ الوجود: نسخ، الوجود لذاته: ق.\r9 ـ غيره: ت ق م، الغير: ك.\r10 ـ متقدما: ت ق ك لب ج م، مقدما: ف ي.\r11 ـ لكان ... الاخر: ت ج ف ك ل م، ا، منهما: ت، متقدما: تج ك لب م، متقدما على المتقدم: ي: ف، في الوجود: تاخر عن: الاخر: في ج، فيلزم: ت ج ف ق ك لب م ي، يلزم: ا."], [343, "أن يكون كل واحد منهما متقدما على المتقدم على نفسه. والمتقدم على المتقدم على الشيء متقدم على ذلك الشيء فالشيء متقدم على نفسه هذا خلف.\rوأما بطلان التسلسل، فلان مجموع تلك الأمور التى لا نهاية لها مفتقر إلى كل واحد منها، وكل واحد منها ممكن، والمفتقر إلى الممكن ممكن فالمجموع ممكن وكل ممكن فله مؤثر. فالمجموع له مؤثر. والمؤثر: اما نفس ذلك المجموع أو أمر داخل فيه أو أمر خارج عنه.\rوالأول باطل لأن المؤثر متقدم على الأثر. فلو كان المجموع مؤثرا فى نفسه، يلزم كونه متقدما على نفسه، وهو محال.\rوالثانى باطل لأن كل واحد من آحاد ذلك المجموع، لا يكون علة لنفسه، ولا لعلته وإلا لزم تقدم الشيء على نفسه. وإذا لم يكن علة لنفسه ولا لعلته، لم يكن علة لذلك المجموع.\rفثبت أنه لا بد لذلك المجموع من علة خارجة عنه والخارج عن\r__________________\r1 ـ متقدما: ت ق ك ج لب م ي، مقدما: ف، على المتقدم: ق.\r1، 2 ـ والمتقدم ... فالشيء: ف ج، والمتقدم على المتقدم متقدم فالشيء: ت ق ل، ومتقدم المتقدم متقدم فالشيء: ك لب م ي.\r5 ـ مفتقر: ج لب م ي، مفتقرا: ل، مغتقرة: ت ف، واحد: تكرر في: ق.\r5، 6 ـ منها .. ممكن: ت ف ق لب م ي، منهما .. منهما ممكن: ك ل، منهما ممكن: ا.\r7 ـ فالمؤثر: في: ا ج فقط. ذلك: ك م، تلك: ت.\r7، 8 ـ امر داخل .. امر خارج: ا ت ج ف ق ك لب ي خارجا ق لب ي، فانه لا يكون: ك م.\r10 ـ متقدما: ت ج ف ك لب م ي، مقدما: ا.\r11 ـ ذلك: ت ف ق ك لب م ي، تلك: ا، لا يكون: ت ج ف: ك، امرا داخلا .. امرا خارجا: م."], [344, "جميع الممكنات لا يكون ممكنا، بل يكون واجبا لذاته فثبت وجوب انتهاء الممكنات بأسرها إلى الواجب. ومتى ثبت كونه واجبا لذاته، ثبت أنه قديم أزلى باق أبدى.\rفإن قيل لم لا يجوز أن يقال إن مدبر العالم ممكن الوجود ولكن الوجود به أولى فلأجل هذه الأولوية يستغنى عن المؤثر.\rسلمنا أن الوجود بالنسبة إليه كالعدم ولكن لم قلتم: إنه يفتقر إلى السبب بيانه: إن علة الحاجة إلى المؤثر هو الحدوث لا الإمكان. فإذا كان ذلك المدبر قديما لم يحتج إلى المؤثر.\rسلمنا أنه لا بد من سبب فلم قلت إن الدور باطل؟.\rقوله:\rلأن العلة قبل المعلول، فيلزم أن يكون كل واحد منهما قبل\r__________________\r1 ـ لذاته: ت ج، ك ل م، وجوب: ت ق ج ل م، وجود: ك.\r3 ـ فديم ازني: ا ت ج ف ق ك لب ل ي، ازلى قديم: م. ابدى: ت ج ف ق لب م ي، سرمدى: ا، سرمدى ابدى: ك.\r4 ـ ان (2): ك ل، بان: ق، ت ج م، و: ا ف ق ك لب ي: ت ج م.\r6 ـ الوجود: ا ت ج ف ق ك لب ي، الوجوب: م، و: ت ف: ق ك لب م ي، قلتم: ت ج ف ق لب م ي، قلت ك م.\r7 ـ مفتقر: في: ق فقط.\r8 ـ فاذا: ت ج ق ك لب م ي، واذا: ف، المدبر: ت ج ف ك لب ي، المؤثر الممكن: ق، المؤثر: م، المؤثر: ت ق م، السبب: ك.\r9 ـ قلت: ت ق ك ل م، قلتم: ج ف ي.\r11 ـ لان: ا ف ق ك لب ي، ولان: م، ان: ت ج، منهما ت ج ق م، منهم: ك."], [345, "نفسه.\rقلنا تدعى القبلية بالزمان أو بالذات أو بمعنى آخر. فإن عنيت به الأول، فهو باطل. لأنه لا معنى لكون الشيء مؤثرا فى الغير إلا صدور الأثر عنه على ما تقدم. فقبل صدور الأثر عنه يستحيل أن يكون مؤثرا وإذا كان كذلك استحال تقدم العلة على المعلول بالزمان.\rوإن عنيت به التقدم بالذات، فنقول تعنى بالتقدم بالذات كونه مؤثرا فيه، أو تعنى به أمرا آخر. فإن عنيت به المؤثرية كان قولك: لو كان كل واحد منهما مؤثرا فى الآخر لكان كل واحد منهما متقدما على الآخر لزاما للشىء على نفسه.\rوإن عنيت به أمرا آخر، فلا بد من بيان ماهية ذلك التقدم، ثم من إقامة الدلالة على أن العلة متقدمة على المعلول بذلك المعنى، ثم\r__________________\r1 ـ نفسه: ت ج ف ق ك لب م ي: ا.\r2 ـ بمعنى: ت ج ق ك لب ل م ي، لمعنى: ف.\r3 ـ به: ت ج ل م، ف ق ك لب ي، معنى لكون: ج ت ك م، نعنى يكون: ق، الغير: ت ج ق م، غيره: ك.\r4 ـ فقبل: ت ج ق ك لب م ي، وقيل: ف، عنه (2): لب فقط.\r5 ـ مؤثرا: ك م، علة: ت ج ل.\r7 ـ تعنى: ف ج ق ك لب م، نعنى: ت، معنى: ا.\r8 ـ او: ج ف ق ك ل م، ام: لب، و: ا ت. المؤثرية: ا ق ك لب ي، المؤثر: ت ج ل ف ك م، كان: ت ج ق ك م، لكان: ف لب ي.\r9 ـ منهما (2): ت ج ف ق ل ك لب م، ي.\r10 ـ للشيء: ت ج ق ل م، لشيء: ك.\r11 ـ امرا آخر: ت ج ق ك لب م ي، الاول: ف.\r11، 12 ـ ثم من اقامة الدلالة: ت ج، ثم على أن العلة متقدمة على المطلوب بذلك المعنى اقامة الدليل: ا، ثم من: ف اقامة: الدلالة على ان العلة متقدمة 42 ـ 1: لب على المعلول بذلك المعنى ثم من: ق اقامة الدلالة: ق ك ل الدليل: ف ق ك لب ي، ايمكن"], [346, "من إقامة الدلالة على أن الشيء يستحيل أن يكون متقدما على نفسه بذلك المعنى.\rسلمنا فساد الدور، فلم قلت أن التسلسل محال.\rقوله:\rذلك المجموع مفتقر إلى كل واحد من تلك الآحاد.\rقلنا: لا نسلم أنه يصح وصف تلك الأسباب والمسببات بأنه مجموع، وكل لأن هذه الألفاظ مشعرة بالتناهى، فلا يصح اطلاقها إلا بعد ثبوت التناهى، وهو أول المسألة.\rسلمنا أنه يصح وصفها بذلك، لكنا نقول: إن دل ما ذكرته على فساد التسلسل، فههنا ما يدل على صحته.\rوبيانه: وهو أن هذه الحوادث المحسوسة لا بد لها من مؤثر. فالمؤثر فيها، اما أن يكون محدثا أو قديما، فإن كان محدثا فالكلام\r__________________\rمن اقامة الدللالة: م.\r3 ـ فلم: ك ل م، لم: ت، لكن: ج، قلت ان: ت ج ق ك ل م، قلت بان: لب ي، قلتم بان: ف محال: ت ل ف ج ق لب ي، باطل: ك م.\r6 ـ وصف .. المسببات بانه: ت ج ق ك لب م ل ي، وصفه ... السببيات بانها: ف.\r9 ـ بذلك: ت ج ق ك لب م ي، لذلك: ف، لكنا: ك م، لكن: ت ج ل، ان دل ماذكرته: ق ك لب م ي، ما ذكرت وان دل: ت ج، ما ذكرتم ان دل: ف.\r10 ـ فههنا: ت ج ق لب م ي، فههنى: ك، فهنا: ف.\r11 ـ و (1): ا ت ق لب ي: ج ف ك م، وهو: ت ك لب م، هو: ق ي: ف.\r12 ـ فالمؤثر: ج ك لب م ي، والمؤثر: ت ف."], [347, "فيه، كالكلام فى الأول. فاما أن يتسلسل فيكون ذلك اعترافا بصحة التسلسل.\rأو ينتهى إلى قديم. وذلك هو القسم الثانى من القسمين المذكورين.\rفنقول تأثير ذلك القديم فى ذلك الحادث، إما أن يتوقف على شرط حادث، أو لا يتوقف. فإن لم يتوقف وجب من قدم المؤثر قدم هذا الحادث. وإلا لكان نسبة صدور الأثر عن المؤثر، كنسبة لا صدوره عنه. فإن لم يفتقر صدوره عنه إلى مرجح منفصل، فقد ترجح الممكن لا عن سبب وذلك يسد باب اثبات الصانع. وإن افتقر، لم يكن المؤثر التام قبل حصول ذلك المرجح المنفصل مؤثرا تاما، هذا خلف.\rوإما أن يتوقف على شرط، فذلك الشرط، ان كان قديما عاد الإشكال. وان كان محدثا. فإما أن يكون مقارنا لذلك الحادث، أو سابقا عليه. فإن كان مقارنا، فالكلام فى حدوثه كالكلام فى الأول.\r__________________\r1 ـ فيه كالكلام: ت ج ق ك لب ي، فيها كالكلام: م، كما: ف، فيكون: ت ك لب م ي، ويكون: ف.\r5 ـ ذلك القديم: ك م، 5: ت.\r6 ـ وجب: ا ف ق ك لب ي، على شرط: ت ج لزم: ت ج م، يلزم: ل، المؤثر: ك ل م، 5: ت ج.\r8 ـ فان: ا ت ف ق ك، وان: م.\r9 ـ فقد ترجح: تكرر في: ف، الصانع: ت م، الصانع سبحانه وتعالى: ك.\r10 ـ المرجح المنفصل: ا ت ج ف ك ل، المنفصل المرجح: ق لب م ي.\r12 ـ واما ان يتوقف: ك ل م، واما ان توقف: ق، وان توقف: ت ج.\r13 ـ حدثا: ت ج ق ك لب م ي، ف.\r14 ـ فالكلام: ت ج ق ك لب م ي، كان الكلام: ف، في حدوثه: ت ق م، فيه: ك."], [348, "فإن كان شرط حدوثه هو الحادث الأول، لزم الدور. وإن كان شرط حدوثه حادثا آخر، لزم التسلسل. وأما إن كان شرط حدوث ذلك الحادث حادثا سابقا عليه.\rفنقول: حال حصول ذلك السابق لم يكن القديم مؤثرا بالفعل فى الحادث اللاحق. وعند فنائه يصير مؤثرا فيه بالفعل. فتلك المؤثرية حكم حادث، فلا بد لها من مؤثر فإن كان هو الحادث الّذي عدم الآن لزم تعليل الوجود بالعدم، وهو محال. وإن كان هو الحادث الّذي حدث به، لزم الدور. وإن كان حادثا آخر، لزم التسلسل. فظهر أنه لا بد من التزام القول بالتسلسل.\rسلمنا صحة دليلكم على وجود واجب الوجود، لكنه معارض بوجهين آخرين.\rالأول: إنا لو فرضنا موجودا واجب الوجود لكان وجوده، اما أن يكون مساويا لوجود الممكنات، واما أن لا يكون. والقسم الثانى باطل لما تقدم من الدلائل على كون الوجود مفهوما واحدا.\r__________________\r1 ـ فمن: ت ج ق ك لب م ي، وان: ف.\r1، 2 ـ شرط مقدوته: ق ك لب م، شرط حدوث ذلك حادث آخر: ي، ت ج ل ف.\r2 ـ اما: ت.\r4 ـ حصول: ت ج ق ك، حدوث: م.\r5 ـ فنائرهم: ت برق ك لب م، فنامه: ف ي.\r6 ـ فلا ت ج ف ق ك لب ي، لا: م.\r6، 7 ـ فان كان .. عدم الان: ك م، فلن كان عدم الحادث الاول: ت ج.\r7، 8 ـ وان كان .. الذي: ك م، فان كان هو عدم الحادث الذي ف.\r9 ـ القول ب: ت ج ف ق ك لب ي، م.\r11 ـ يرجهين يرجهين: ف اخرين الاول احدهما: ج: ت ج ف ق ك لب م ي، بوجهين ا: ا.\r13 ـ واما ان: ك م، او: ت ج ل، القسم: ت ج ل."], [349, "والأول أيضا باطل، لأن ذلك الوجود اما أن يكون عارضا لماهيته أو لا يكون. فإن كان الأول كان ذلك الوجود ممكنا، وله علة والعلة ان كانت هى تلك الماهية: كان المعدوم علة للوجود، وهو محال. وان كان غيرها كان واجب الوجود مفتقرا فى وجوده إلى سبب منفصل، هذا خلف. وإن لم يكن ذلك الوجود عارضا لماهية، فهو محال، لأن على هذا التقدير يكون تمام حقيقته مساويا للوجود الّذي هو وصف عارض لماهيتها وكل ما صح على الشيء صح على مثله. فيلزم أن يصح على ماهيته كل ما يصح على وجودها، فيكون وجوده ممكنا محدثا وهو محال، والثانى انه لو كان واجب الوجود لكان قديما والمعقول من القديم هو الّذي لا زمان يفرض هو موجودا فيه، إلا وقد كان موجودا قبل ذلك. وتلك القبلية قبلية زمانية على ما تقدم بيانه فى باب القديم والمحدث.\r__________________\r1 ـ لماهيته: ت ق م، للماهية: ك.\r2 ـ وله: ت ج ف م ي، فله: ف ك لب، والعلة: ت ج ق ك، فالعلة: م.\r3 ـ هي: ا ت ج ق ك لب ي ل، ف م، للوجود: ا ف، للموجود: ج ق ك لب م ي.\r3، 4 ـ الموجود .. واجب: ت.\r5 ـ ذلك: ا فقط. لماهية: ا ت، لماهيته: ف ج ق ك لب م ي، للماهية: ل، فهو: ا ت ج ف ق ك لب ي: ر ه و.\r6 ـ لان: ا ت ج، لانه: ف ك لب ل م.\r7 ـ لماهيتها: ا ي، لماهيتتا: ت ج، لماهياتنا: ف لب م، لماهياتها: ق ك ل.\r8 ـ وجودها: ق ك ل، وجودنا: ت ج م.\r9 ـ محدثا: ت ج ف ق لب ل ي، ومحدثا: ك م، والثاني وهو: ت، الثاني: ف ج ق ك لب م ي، ب: ا.\r10 ـ موجودا في: ف بعد: الوجود، هو: ا ت ج ف ق ك لب ي، م.\r11 ـ موجودا (1): ت ج ف لب م ي، موجود: ا ك، الا وقد فقد: ل: ك لب ل م ي، الا و: ت ج والا ما: ق وقد: ف ق.\r11، 12 ـ ذلك و: ت ج ف ق ل لب ي، ذلك ف: ك،: م."], [350, "فيلزم من قدم الله تعالى قدم الزمان، وذلك محال.\rلا يقال تقدم البارى تعالى على العالم تقدما بزمان مقدر لا بزمان محقق.\rتقريره: ان الله تعالى تقدم على وجود العالم بمعنى أنه لو كان هناك زمان، لما كان لذلك الزمان أول. لأنا نقول: تقدم البارى تعالى على العالم، إذا كان حاصلا فى نفس الأمر محققا، وذلك التقدم لا يتحقق إلا بواسطة الزمان، استحال كون الزمان مقدرا، بل لا بد وأن يكون محققا.\rوالجواب قوله:\rلم لا يجوز أن يكون العالم جائز الوجود لكن الوجود به أولى قلنا قد تقدم إبطاله.\rقوله:\rجائز الوجود والعدم على التساوى ولكن إنما يحتاج إلى المؤثر، لو كان محدثا.\r__________________\r(12/ 349) القبلية: ت ج ف ك ل م، العلية: ا.\r1 ـ وذلك: ت ج ل م، وهو: ك.\r2 ـ تقدما: ا، تقدم: ت ف ق ك لب ي، م.\r4 ـ تقريره: ت، وتقريره: ل، وتفسيره: ك ج م ف، تقدم: ك ل ف م، مقدم: ت ج ق، وجود: ا ت ج ف ك: م. بمعنى انه: ق ج ل، بمعنى: ت، بما: ك م.\r10 ـ يكون: ا ت ج ف ق ك لب ي، مدير: م، العالم: ت ج فقط. ولكن: في ف.\r11 ـ ابطاله: ا ت ج ف ق ك لب ي، م.\r13 ـ جائز: ا ت ج، هب انه: ك م، انه: ق، والعدم: ا ف ق ك لب ي: ت ج م، ولكن: ا، لكن: ف ق ك لب م ي، ت ج لب."], [351, "قلنا: قد بينا أن علة الحاجة إلى المؤثر هى الإمكان فقط.\rقوله:\rما الّذي عنيت بتقدم العلة على المعلول:\rقلنا العقل ما لم يفرض للمؤثر وجودا استحال أن يحكم عليه بكونه مؤثرا فى الغير ومرادنا من التقدم هذا القدر.\rقوله:\rلا يمكن وصفه بكونه كلا ومجموعا إلا إذا ثبت كونه متناهيا.\rقلنا مرادنا من الكل والمجموع، تلك الأسباب والمسببات بحيث لا يبقى واحد منها خارجا عنها.\rقوله:\rالمؤثر فى حدوث الحوادث اليومية اما القديم، أو المحدث.\rقلنا قد بينا أن المؤثر هو الصانع القديم المختار. وإن المختار\r__________________\r1 ـ قلنا: ت، قد: ق ك ل فقط، الى المؤثر: ت ج ف، ف،: ك م.\r3 ـ عنيت: ت ج ف ق ك لب م، معنى: ا ي.\r4 ـ للمؤثر: ت ج ف ق ك لب م، المؤثر: ا ي، واجودا: ت ج ف ق لب م، موجودا: ا ي، وجود: ك.\r5 ـ بكونه: ت ج ق ك لب ل م ي، لكونه: ف، من: ت ج ف ق ل ك م، ب: ا لب ي، القدر: ت ج ق ك لب م ي، التقدم: ف.\r7 ـ وصفه .. اذا: ق ك لب م ي، الوصف .. اذا: ت ج، وصف تلك الاسباب والمسببات بانها مجموع وكل اذا: ف.\r8 ـ مرادنا: ت ج ق ك لب ل م ي، المراد: ف.\r9 ـ واحد: ت ج ق لب م ي، واحدا: ف ك.\r11 ـ او: ك ف م، واما: ت ج ل، المحدث: ت ج ف ق ك لب م ي، الحادث: ا."], [352, "يصح منه ترجيح أحد الجائزين على الآخر لا لمرجح.\rقوله:\rواجب الوجود إما أن يكون وجوده عين ماهيته أو غيرها.\rقلنا بل عين ماهيته. وقد تقدم الجواب عن أدلتهم على أن الوجود وصف مشترك فيه.\rقوله:\rيلزم من قدم الله تعالى قدم الزمان.\rقلنا: إذا جاز أن يكون تقدم بعض أجزاء الزمان على البعض لا بالزمان. فلم لا يجوز أن يكون تقدم ذات الله تعالى على العالم لا بالزمان وبالله التوفيق.\rمسئلة:\rصانع العالم موجود خلافا للملاحدة، لنا إنه لو لم يكن موجودا\r__________________\r1 ـ اتجائزين: ت ف ق ك لب م ي، الطرفين: ا، الجانيين: مصال، لا لمرحح: ت ج ق ك لب م ل ي، من غير مرجح: ف، الاربعين.\r3 ـ ماهيته: ت ف ق ك لب م ي، ماهية: ا، او غيرها: او غيرها ماهيته: ج ف ق ي: لب.\r4 ـ ماهيته: ت ف ق ك لب م ي، ماهية: ا، قد: ف فقط.\r5 ـ وسف: ا، ت ج ف ق ك لب ل م ي.\r9 ـ ان يكون: ا ت ف ق ك لب ي،: م الله: ت ق م، الاولين ك.\r10 ـ وبالله التوفيق: ت ق ك ل.\r12 ـ للملاحدة: ا ت ف ج ق ك ل، للملاحدة لعنهم الله تعالى: م: لب م ي، انه: ا ت ج ف ل، ان تقول: ق ك لب ي"], [353, "لكان معدوما. والمعدوم نفى محض، لا خصوصية فيه ولا امتياز، فلا يصلح للالهية.\rفإن قيل لا نسلم إنه لا واسطة بين الوجود والعدم وبيانه ما تقدم فى مسئلة الحال.\rسلمنا الملازمة لكن فلم قلتم إنه لا يجوز أن يكون معدوما.\rقوله: لأن العدم نفى محض لا امتياز فيه.\rقلنا لا نسلم. فإن عدم السواد عن المحل مصحح لحلول البياض فيه، وعدم الحركة لا يصحح ذلك وكذلك عدم اللازم يقتضي عدم الملزوم، وعدم غيره لا يقتضي ذلك. وكذلك عدم المعارض معتبر فى دلالة المعجزة على الصدق. وسائر العدمات ليس كذلك.\rسلمنا صحة دليلكم لكنه معارض بأنه لو كان موجودا لكان مساويا\r__________________\r1 ـ فيه: ب ق ك ل م لب ي، فيه ولا تحقق: ف: ت.\r3 ـ بين الوجود والعدم و: ف ق ك لب ي، و: ت ج، م، ما: ت ف ج ق ك لب ي، قد: ل: م.\r5 ـ الملازمة: ا ت ج ف ق ك لب ي: م، فلم قلتم: ا ت ج ف لب ي، لم قلتم: ق، لم قلت: ك م، فلم قلت: ل.\r6 ـ لان: ت ج ق لب ك م ي، ان: ف: ا، العدم نفي محض: ا ت ج ق ل، العدم: ف ك لب ي، المعدوم: م.\r7 ـ عن المحل: ت ف ج ق ك لب م ي، ا، مصحح لحلول: ا ت ج، يصحح حلول: ق ك لب م، يصح: ف، يصحح: لب ك م ج ي ت.\r8 ـ ذلك: ج ق فقط.\r9 ـ كذلك: ف، ت ق ك لب م ي.\r10 ـ العدمات: ت ج ف ق م، المعدومات: ك لب ي.\r11 ـ صحة دليلكم: ت ج ف ق لب ل ي، دليلكم: ا، ما ذكرتموه: ك، م، بانه: ا ت ج ل، بما انه: ف ك لب م ي."], [354, "لغيره فى الوجود. فإن لم يخالف غيره فى وجه آخر، كان مثلا للممكن مطلقا، فيكون ممكنا مطلقا. وإن خالفه، كانت حقيقته مركبة. وكل مركب فهو مفتقر إلى أجزائه، وجزؤه غيره. فكل مركب فهو مفتقر إلى غيره، وكل مفتقر إلى الغير فهو ممكن، فالواجب ممكن، هذا خلف.\rوالجواب: بينا أن نفى الواسطة معلوم بالضرورة، وبالبرهان على ما تقدم.\rقوله:\rالعدمات قد تكون متميزة متعينة.\rقلنا: لو كفى ذلك فى أن يكون خالقا، فليجوز أن يكون الإنسان\r__________________\r1 ـ فان: ت ج ف ق لب م ي، فاذا: ك، غيره في وجه: ت ج ق لب ك م، عن غيره من وجه: ف، غيره بوجه: ي، مثلا: ت ج ف ق ل لب م، مماثلا: ك ي.\r2 ـ فيكون: ت ج ق ك لب م ي، فهي: ف، خالفه: ت ج ق ك لب م ي، خالفه من وجه آخر: ف.\r3 ـ فهو: ا ف ق ك لب ي: ت ج م، جزؤه: ا ت ج ق ك لب ي، اجزاؤه: ف: م، فكل: ا ف ج ق ك ي، وكل: ت لب م، فهو مفتقر: ت ج ف ق م، مفتقر: ك ي، يفتقر: لب.\r4 ـ الغير: ت ق ك لب م ي، غيره: ف، فهو: ت: ك م.\r6 ـ و (1): ت ج ف ق م: ا ك لب ي، بينا: ت ج ك لب م ل ي، قد بينا: ق، قلنا: ف، و (2): ا فقط. بالبرهان: ت ج ق م، البرهان: ك.\r9 ـ العدمات: ت لب ج م، المعدومات: ا ف ك ل ي، لم لا يجوز ان معدوما فان العدمات: ق، قد يكون: ا ت ج ل ف ك لب ي: م، متميزة معتبرة: ق ك ي، متعينة: لب: ت ج ف ق ك ل لب م ي، مستمرة معتبرة: ا.\r10 ـ فليجوز: ت ق ك لب ل م ي، فليجز: ج ف."], [355, "المتحرك معدوما. وان كانت الصفات القائمة به موجودة وذلك عين السفسطة.\rأما المعارضة، فجوابها إنا لا نسلم كون الوجود وصفا مشتركا فيه بين الموجودات وبالله التوفيق.\r__________________\r1 ـ المتحرك: ا ت ج ف ق ك لب ي: م.\r3 ـ انا: ا ت ج ف ق ك لب ي: م، الوجود: ا ت ف ج ك لب ي، الموجود: ق، الشيء: م.\r4 ـ الموجودات: ك م، الوجودات: ت، وبالله التوفيق: ا ك ل، ت ف ج ق لب م ي."], [357, "القسم الثانى\r"]], "pg": [337, 357]}, "687.10": {"x": [[357, "فى الصفات\rوهى اما سلبية أو ثبوتية.\rالقول فى السلوب:\rمسئلة:\rماهية الله تعالى مخالفة لسائر الماهيات لعينها خلافا لأبى هاشم. فإنه قال ذاته مساوية لسائر الذوات فى الذاتية. وإنما تخالفها بحالة توجب الأحوال الأربعة: وهى الحيية، والعالمية، والقادرية والموجودية، وخلافا لأبى على بن سينا. فإنه زعم أن ماهيته نفس الوجود. والوجود مسمى مشترك فيه بين كل الموجودات. وزعم إنه إنما امتاز عن الممكنات بقيد سلبى وهو أن وجوده غير عارض لشيء من الماهيات. وسائر الوجودات عارضة لها.\r__________________\r7 ـ ذاته: ك.\r8 ـ الاحوال الاربعة: ا ت ف لب ج ي، احوالا اربعة: ف، احوال اربعة: ك م، و (1): ف ج ق ك لب ل ي، ت م، الحبيبة: ت ف ق ك لب ي، الحية: ج م.\r8، 9 ـ القادرية والموجودية: ا ت ق ك لب ل ي، القادرية والوجودية: ف، الموجودية والقادرية: م، الوجودية والعالمية والقادرية: ج.\r9 ـ وخلافا: ا ت ج ك ي، خلافا: ف ق لب م، ان: ك ت ج م ل، انه: ق، ماهيته: ت ج ك لب م ي، ماهية الله تعالى: ف ق.\r10 ـ مسمى: ت ج ف ق ك ل م ي، امر: لب، فيه: ت ج ل.\r11 ـ انه انما امتاز: ك م، ان امتيازه: ت ج ل.\r12 ـ لها: ج لب، ت ف ق ك ل م."], [358, "لنا أن مخالفته لغيره لو كانت لصفة لحصلت المساواة فى الذات. ولو كان كذلك، لكان اختصاص ذاته بما به خالفت غيرها، إن لم يكن لأمر كان الجائز غنيا عن السبب، وهو محال أو كان لأمر فيلزم التسلسل.\rمسئلة:\rماهية الله تعالى غير مركبة، لأنها لو تركبت لافتقرت إلى كل واحد من أجزائها، وكانت الماهية ممكنة على ما تقدم.\rمسئلة:\rالله تعالى ليس بمتحيز خلافا للمجسمة. لنا لو كان متحيزا، لكان مساويا لسائر الأجسام ويلزم اما حدوثه، أو قدمها. وهذه الدلالة مبنية على تماثل الأجسام وقد تقدم القول فيه.\r__________________\r1 ـ لصفة: ت ج ف ك لب ي، بصفة: ق م، لحصلت: ت ج ف ك لب م ي، حصلت: ف.\r1، 2 ـ في الذات: ا ت ج ك لب ي، في الذوات: ف ق، بالذات: م.\r2 ـ به خالفت: ا ت ج ف ق لب، خالفت به: ي، به يخالف: م.\r3 ـ لامر: ا ت ج ف ق ك لب ي، الامر: م.\r3، 4 ـ كان لامر: لب، لامر: ا ت ج ف ق ك ي، الامر: م.\r6 ـ تركبت: ت م، فكانت: ف ج ل ك ي ق.\r7 ـ وكانت: ت م، فكانت: ف ج ل ك ي ق.\r9 ـ الله: ت ج، انه: ك ل م ف، للمجسمة: ا ج ف ق لب ك ي ل، للجسمية: ت م، لو: ت ج ك م ف، انه لو: ف ل. متحيزا: ت ج ف ق لب م ك ي، متحيزا: ا.\r10 ـ مساويا: ا ج ل ت، مثلا: ف ق لب م ك، ويلزم: ت ج، فليلزم: ف ق ك ل م ي. حدوثه: ج ف ق لب ت ي ك، حدوثها: م.\r11 ـ مبنية: ت ف ج ق ك لب م ي، مثبتة: ا."], [359, "وربما احتجوا به من وجه آخر وهو إنه تعالى لو كان متحيزا، لكان مساويا لسائر المتحيزات فى أصل التحيز. فإن لم يخالفها من وجه آخر لزم المماثلة، مطلقا، فيلزم إما حدوثه، أو قدمها. وان خالفها من وجه آخر، لزم وقوع التركيب فى ذاته.\rويمكن أن يقال لم لا يجوز أن تكون ماهيته مخالفة لماهية سائر الأجسام، وإن كانت مساوية لها فى الحصول فى الحيز فإن الأشياء المختلفة يجوز اشتراكها فى لازم واحد.\rوالأولى: أن يقال لو كان متحيزا لكان اما أن يكون منقسما أو غير منقسم. والأول يقتضي التركيب، وهو محال. والثانى باطل بناء على القول بنفى الجوهر الفرد. وعلى القول باثباته، يلزم أن يكون الله تعالى أصغر الأشياء، تعالى الله عنه علوا كبيرا.\r__________________\r1 ـ ربما: ا ت ف ج ق ك ل ي، م، به: ا ت ف ق لب ي ك، م ج، انه: م، ان الله: ك، تعالى: ف ك ل م، انه: ا ت ج.\r3 ـ آخر: لب م ك ي، ف، المسائلة: ت ج ل م، التماثل: ف ل ي ك، وقوع التماثل: ق مطلقا: ف لب م ك ي ق ل، ت ج، فيلزم: ت ف ق لب ك م، فلزم: ي، حدونه: ا ف ت لب ي ك ق، حدوثها: م، ان: ا ت ف ق لب ي ك، لئن: م.\r4 ـ لزم وقوع: ت ج ف ق ك لب م، وقع: ي، ذاته: ت ج ق ك لب م ي، ذاته سبحانه وتعالى وهو محال: ف.\r5 ـ تكون ... مخالفة: ت لب م ك ج ي ق، ماهية الله تعالى مختلفة: ف.\r6 ـ الحصول في: ت فقط، فلن: ت ف لب م ج ك ي، فان كان: ا.\r8 ـ لكان: ت لب م ك ق ي، ف.\r9، 10 ـ باطل بناء: ق ج، باطل: ت ك م.\r10 ـ الفرد: ت ف ق لب م ك ي ج ل: ا.\r11 ـ عنه: ت ف ج ق لب ك م: ا ي."], [360, "وقد يستدل على نفى الجسمية خاصة، بأن كل جسم مركب فالعالمية الحاصلة لأحد الجزءين غير الحاصلة للجزء الآخر. وكل واحد من تلك الأجزاء يكون حيا قادرا عالما على الاستقلال، فيفضى إلى تكثير الآلهة، وهو محال. وهذا المستدل يلتزم أن الإنسان الواحد ليس حيا عالما قادرا واحدا، بل أحياء علماء قادرين.\rمسئلة:\rماهية الله تعالى لا يتحد بغيره لأنه حال الاتحاد، إن بقيا موجودين فهما اثنان لا واحد. وان صارا معدومين فلم يتحدا، بل عدما، وحدث ثالث. وان عدم أحدهما، وبقى الآخر فلم يتحدا، لأن المعدوم لا يتحد بالموجود.\rمسئلة: أنه تعالى لا يحل فى شيء.\r__________________\r1 ـ الجسمية: ت لب م ج ك ي ق، الجسم: ف، ان: ج ك م، بل: ت، فالعالمية: ت م ج، والعالمية: ف لب ك ل ق.\r2 ـ الحاصلة (2): ت ج م ق، حاصلة: ك، وكل: ت م ي، فكل: ا ج ف ق ل ك.\r3 ـ تلك: ت ج فقط، قادرا هالما: ا ت ج، عالما قادرا: ف ق م ك ل، فيقضى: ت ف ج لب م ك ي ق ل، فيقتضي، ا.\r4 ـ الالهة: لب م ق ي ت، الالهية: ا ف، تكثر الالها ج، تكثير: ف ل ك م ت، تكثر: ج ل ي ق، وهذا: وعلى هذا التقدير: ل.\r5 ـ حيا عالما قادرا: ك ل م ت ج، عالما قادرا حيا: ف ل ق في، احياء علماء قادرين: ا ت ج ك، احياء وعلماء وقادرين: م علماء قادرين احياء: ف ل ق ي.\r7 ـ ماهية الله: م ت ج، انه: ف ك م ي ق، لانه تعالى: م، لان: ا ت ج، لانهما: ف لب، لانه: ي ل ك ق. الاتحاد: ك ف م، اتحاده: ت ج.\r8 ـ اثنان: ت ف ق لب ك م ي، اتيان: ا.\r8، 9 ـ بل: ف لب ي ك ق، بل عدما و: م.\r10 ـ يتحدا: ت لب ق م ك ج ي، يتحد: ف ل."], [361, "واحتج أصحابنا بأنه تعالى لو حل فى شيء لحل اما مع وجوب أن يحل، أو مع جواز أن يحل والأول باطل لوجهين:\rالأول إنه يلزم احتياجه إلى ذلك الغير. وكل محتاج ممكن، فيكون الواجب لذاته ممكنا لذاته هذا خلف.\rالثانى إن غير الله تعالى اما الجسم أو العرض، فيلزم من وجوب حلوله تعالى فى الغير إما حدوثه أو قدم الجسم والعرض وهما محالان.\rوالثانى أيضا باطل، لأنه إذا لم يجب حلوله فى المحل، كان غنيا عن المحل. والغنى عن المحل لا يحل فى المحل. وهذا الدليل ضعيف، لأنه يقال لم لا يجوز أن يجب حلوله فى المحل.\rقوله: لو وجب ذلك لكان مفتقرا إلى ذلك المحل.\rقلنا لا نسلم. ولم لا يجوز أن يقال إنه تعالى لذاته يوجب لنفسه\r__________________\r1 ـ و: ا ت ف ج ق لب ك ي: م، تعالى: ا ت ف ق لب ي: ك م، لحل: ا ف ق ك لب: ت م.\r2 ـ مع جواز ان يحل: ف، الاول: ت ج ف ق ك لب م ي، ا: ا. لوجهين: ت ج ف ق ك م ي، بالوجهين: لب.\r4 ـ لذاته (1): ت ف ق ك م ي، بذاته: لب، لذاته (2): ا ت ج ف ق ل، بذاته: لب ي: ك م.\r5 ـ الثاني: ت ف ج ك لب م ي، والثاني: ق، ب: ا، تعالى: ف ك لب ي: ت ج ق م ي، او: ت ج ف ق م، و: ا، واما: ك لب، وجوب: ق فقط.\r6 ـ تعالى: ا فقط، الجسم والعرض: ك م، احدهما: ت ج.\r8 ـ و: لب فقط.\r9 ـ لا: ا ت ج ل، يستحيل أن: ف ك لب م ي، المحل (2): ت ق ك لب ج م ل ي، فيه: ف.\r10 ـ لانه: ت ج ك ف م، فانه: لب ق ي.\r12 ـ تعالى: ف فقط، يوجب: ت ق ج ك ل م، اوجب: ف."], [362, "صفة وهى الحالية فى ذلك المحل. ولا يلزم من كونه موجبا لتلك الصفة احتياجه إليها، ألا يرى أنه يجب اتصافه تعالى بكونه عالما قادرا وإن لم يلزم احتياجه إلى شيء منها فكذا هاهنا.\rقوله ثانيا: بأن غيره اما الجسم أو العرض.\rقلنا لا نسلم. فإنكم ما أقمتم دليلا قاطعا على ذلك، فلم لا يجوز أن يقال إنه تعالى اوجب لذاته تعالى عقلا، أو نفسا إنه لذاته اقتضى صيرورة ذاته حالة فى ذلك المحل.\rسلمنا الحصر لكن لم لا يجوز أن يقال: إنه لا يجب حلوله فى المحل مطلقا. لكن ذاته تقتضى الحلول فى المحل عند حدوث المحل. وعلى هذا التقدير لا يلزم حدوث ذاته تعالى ولا قدم المحل. وهذا\r__________________\r1 ـ وهي: ا ت ف ق ك لب ي، هي: م، الحالية: ت ج ق ك لب م ي، حالة: ف.\r2 ـ احتياجه: ت ج ف ق ك لب م، واحتياجه: ا، احتياجا: ي، تعالى: ا ت ج ف ق ك لب ي: م.\r2، 3 ـ عالما قادرا: ت م، قادرا عالما: ك، قادرا: ق.\r3 ـ ان: ف، منها: ا ت ج ف ق ك ي: م، فكذا: ت ف ق ك م، وكذا: ي، كذا: لب.\r4 ـ ثانيا بان: ا ف ك، ثانيا: ف ج لب ل ت، بان: م، ي، الجسم: الجوهر: ج، او: ت ك م، و: ا.\r5 ـ فلم: ت ل م، ولم: ج.\r6 ـ تعالى (1): ك، اوجب: ت ف ج ق لب م ي، يوجب: ك، واجب: ا، تعالى (2): ا فقط، وانه: ا ت ج، ثم انه: ف ق ك لب ل م ي.\r8 ـ لكن: ت.\r9 ـ عند: ا ت ف ق ك لب ي، لكن بشرط: م، الحلول في المحل: حالا فيه: ل.\r7، 9 ـ صبرورة ... حدوث: ت ج ق ك لب م ي، الحلوق في المحل عند حدوث: ف.\r10 ـ التقدير: ج ك ل م، التغسير: ت، حدوث ذاته: ت"], [363, "كما تقول أن كونه تعالى عالما بوجود العالم واجب، لكن بشرط وجود العالم. فلا جرم، لم يحصل هذا العلم قبل وجود العالم.\rسلمنا ذلك فلم لا يجوز أن يحل فى المحل مع جواز أن لا يحل.\rقوله:\rالغنى عن المحل لا يحل فى المحل.\rقلنا هذا مجرد الدعوى. فأين الدليل والمعتمد فى ابطال الحلول، ان المعقول من الحلول هو حصول العرض فى الحيز تبعا لحصول محله فيه. وهذا إنما يعقل فى حق من يصح عليه الحلول فى الحيز. ولما كان ذلك فى حق الله تعالى محالا، كان الحلول عليه محالا.\rمسئلة:\rإنه تعالى ليس فى شيء من الجهات خلافا للكرامية.\rلنا إنه تعالى ليس بمتحيز ولا حال فى المتحيز. وكل ما كان\r__________________\rج ق ك لب م، حدوثه: ف، تعالى: ك: ت ق م.\r1 ـ تقول نقوله: م ان: ف ق ك م ي، يقول: ا ت لب، ونقول: ج، كونه: ت ف ج ق م ي، يكونه: لب.\r1، 2 ـ واجب .. سلمنا: ت ج ف ق ك م ي، سلمنا: لب.\r3 ـ يحل (1، 2): ا ت ج لب، يحصل: ف ك ل م، مع جواز ان لا يحل: ف.\r5 ـ لا يحل في المحل: ا ت ج، لا يحل فيه: ف ل، لا يحل المحل: لب، لا يحل: ك ي، لا يحطه: ق، لا يحصل: م.\r6 ـ الدعوى: ت ج ك م، دعوى: ق.\r7 ـ ان المعقول من الحلول: ق.\r8 ـ فيه: ك، الحلول: ا ت ج، الحصول: ف ق ك لب م ي.\r9 ـ محالا (2): ا ت ج ف ق ك لب ي، محال: م.\r11 ـ انه تعالى: ك م، الله تعالى: ت، للكرامية والحنابلة: ك فقط.\r12 ـ تعالى: ا: ت ف ق ك لب م ي، في التحيز: ت"], [364, "كذلك، لم يكن فى شيء من الجهات وهذا معلوم بالضرورة. ولأن مكانه تعالى، إن ساوى سائر الأمكنة، كان اختصاصه به دون سائر الأمكنة، يستدعى مخصصا. وذلك المخصص لا بد وأن يكون مختارا وكل ما كان فعلا لفاعل مختار فهو محدث، فكونه فى المكان محدث، هذا خلف. وان خالف سائر الأمكنة، كان ذلك المكان موجودا، لأن الاختلاف فى النفى المحض محال. وذلك الموجود إن لم يكن مشارا إليه، لم يكن الموجود فيه مشارا إليه فلم يكن الله تعالى فى المكان وان كان مشارا إليه، فإن كان كونه كذلك بالذات، كان جسما. فإذا فرض الله تعالى موجودا فيه، كان البارئ تعالى حالا فى\r__________________\rج ق ك لب م ي، فيه: ف، كل: ا: نسخ اخرى.\r1 ـ بني، من الجهات وهذا: ا ت، جهة اصلا وذلك: م وهذا: ف ك لب م ي.\r2 ـ تعالى: ا.\r1، 2 ـ شرح الطب المصري ينتهى في شرح: ولان مكانه تعالى ان ساوى سائر الامكنة كان اختصاصه به دون سائر الامكنة الى آخره .. وآخر الشرح: فيلزم ان يكون حصول الاله في المكان حادثا وهو محال والله اعلم بالصواب. ثم الكتاب بحمد الله وحسن توفيقه والصلاة على محمد خير خلقه وقع الفراغ من تحريره يوم الجمعة عشرة شهر ربيع الاخر سنة خمس وعشرين وستمائه في المدرسة العلاحية بمدينة دمشق حرسها الله عن كل سوء على يد العبد الفقير الى رحمة ربه القدير على بن عمر بن علي القزويني وزقه الله تعالى بما فيه.\r3 ـ و (2): ا ت ف لب: ك م، وذلك .. مختارا: ق ك.\r4 ـ فعلا لفاعل مختار: ف ق ك ل لب م ي، فعل الفاعل المختار: ت، فعل فاعل المختار: ا.\r5 ـ خالف: ف ك لب م ي، خالفت: ا ت ج ل.\r6 ـ مشارا: ت ق ك، مشار: م.\r7 ـ مشارا: ت ق ك، مشار: م.\r7، 8 ـ فلم يكن الله .. وان كان مشارا اليه: ا ج ف ق ك لب ل ي، وتقدم على لم يكن موجودا في: ت،: م.\r8 ـ مشارا: ت ق ك، مشار: م، فان كان .. بالذات: فكونه كذلك ان كان بالذات: ج.\r9 ـ فرض: ا ت ج ل، فرضتا: ف ق ك لب م ي."], [365, "الجسم، وهو محال: وان كان بالعرض، كان ذلك عرضا حالا فى الجسم والبارى تعالى لما كان حالا فيه كان حالا فى الحال فى لجسم، فكان حالا فى الجسم، هذا خلف.\rتنبيه:\rالظواهر المقتضية للجسمية والجهة لا تكون معارضة للأدلة العقلية القطعية التى لا تقبل التأويل. وحينئذ اما أن يفوض علمها إلى الله تعالى على ما هو مذهب السلف.\rوقول من أوجب الوقف على قوله تعالى: (وَما يَعْلَمُ تَاوِيلَهُ إِلَّا اللهُ) واما أن يشتغل بتأويلها على ما هو قول أكثر المتكلمين وتلك التأويلات مستقصاة فى المطولات.\rمسئلة:\rلا يجوز قيام الحوادث بذات الله تعالى خلافا للكرامية.\rلنا لو صح اتصافه بها لكانت تلك الصحة من لوازم ماهيته،\r__________________\rالباري تعالى: ف فقط.\r1 ـ وان كان بالعرض: ك.\r2 ـ والباري: ا ت ج، فالباري: ف ق ك لب م ي، لما: ت ك م، لو: ق.\r3 ـ فكان حالا في الجسم: ي فقط.\r6 ـ يغوض: ت ق ك لب م ي، يفرض: ف.\r7 ـ على ما: ت ج ف ق ك لب م ي، كما: ا ل.\r8 ـ قول: ت ق ك لب م ي، قوله: ف، تعالى: ف ق، ت لب م ي ك.\r9 ـ يشتغل: ا ت ج ف ق ك ي، يستقل: لب م، على ما هو قول: ت ج ك، وهو قول: ف لب ي، على التفصيل على ما هو مذهب: ق ل م.\r10 ـ مستقصاة: ت ج ق م، مستقصيات: ك.\r12 ـ انه: في ق بعد: لنا، لكانت: ت ج ف ق ك م ي، لكان: ا لب، تلك: ف."], [366, "فيلزم حصول تلك الصحة أزلا، لكن ذلك محال، لأن صحة اتصافه بها ازلا يتوقف على صحة وجودها أزلا، وذلك محال، لأن الأزل عبارة عن نفى الأولية. والحدوث عبارة عن ثبوتها، والجمع بينهما محال.\rفإن قيل هذا يشكل بما أن العالم جائز الوجود لذاته ثم لم يلزم جواز وجوده أزلا. فكذا هاهنا.\rثم نقول صحة اتصاف الذات بالصفة غير صحة وجود الصفة فى نفسها. ولا يلزم من ثبوت أحدهما ثبوت الآخر.\rفانا نقول يصح اتصاف الذات أزلا بهذه الصفة على معنى أن هذه الصفة لو كانت فى نفسها ممكنة كانت الذات قابلة لها. وهذا\r__________________\r1 ـ الصحة: ت، لكن ذلك: ت ك م، لكنه: ق.\r2 ـ بها: ا فقط، ازلا (1): ت ج ف لب م، ان لا: ا ي، ق ك، ذلك: ت ج ك م، هو: ق.\r2، 3 ـ على صحة .. عبارة: ت ج ف ق ك لب م ي، ا.\r5 ـ بشكل: ك م، مشكل: ت، ثم لم: ت ج لب ي، ولم ق ك م، ثم: ف، من: ف ي، منه: ك: بعد لم يلزم.\r6 ـ ازلا: ك لب، في الازل: ت، لذلك ازلا: م، ازلا ان يوجد: ف ق ي.\r7 ـ غير: ا ت ف ق ك لب ي، مد: م.\r8 ـ ولا: ك م، فلا: ت ج ل، احدهما .. الاخر: ت ج ف، احدهما .. الاخرى، لب ل، احدبهما .. الاخرى: ق ك م ي.\r9 ـ يصح: ت ج ق ك لب م، صحة: ف ل، بهذه: ت ج ق ك لب م ي، فلزم: ف.\r9، 10 ـ على معنى ان هذه الصفة: ا ت ج ف ق ك لب ل ي، ت م.\r10 ـ لها: ا ت ج ق ك ي، لهذا: لب م.\r10، (367/ 1) كانت .. صحيحة ممكنة: ت ج ل: ت ق ك ل م ي، كانت .. صحيحة الوجود: لب، لكانت صحيفة: ف."], [367, "لا يستدعى كون الصفة فى نفسها ممكنة. ثم نقول ما ذكرته، ان دل على قولك، فههنا ما يدل على قولنا من وجوه.\rالأول: وهو أن العالم محدث. فالله تعالى لم يكن فاعلا للعالم أزلا. لأن الفاعل، ولا فعل محال. ثم صار فاعلا له والفاعلية صفة ثبوتية. فهذا يقتضي حدوث هذه الصفة فى ذات الله تعالى.\rالثانى وهو أن الله تعالى فى الأزل لم يكن عالما بأن العالم موجود فإن ذلك جهل وهو على الله تعالى محال. ثم صار عند وجود العالم عالما بوجوده.\rالثالث وهو أنه تعالى فى الأزل لم يكن رائيا لوجود العالم،\r__________________\r1 ـ ذكرته: ف ل ك م، ذكرتم: ت ج.\r2 ـ قولك: ك ل م ف، قولكم: ت ج، فههنا: ت ج م، فهنا: ا، فمعنا: ف ق ك لب ل ي، من وجوه: وبيانه من وجوه: ج.\r3 ـ الاول: ت ق ك لب م ي، احدها: ج ف، ا: ا. و: ق، فالله: ت ج ك م، والله، ق، تعالى: ا ت ج ف ق ك لب ي: م.\r4 ـ ازلا: ت ج ك لب م ي، في الازل: ف ق، ا، ولا فعل: ت ف م ك، بدون الفعل: ق، بلا فعل: ج لب، والافعال: ي، فاعلا له: ت ج ف ق ك لب ل ي، فاعلا: م، فعلا له: ا.\r5 ـ وهذا: ق ك لب م ي، وهذا: ت ج ل، فهذه: ف. هذه: ت ج ل، تعالى: ت ق ك ل م ي: ج ف لب.\r6 ـ الثاني: ت ج ف ق ك لب م ي، ب: ا، هو: ق ي، ان الله: ت ق ك لب م ي، انه: ف، في الازل: ا ت ج، وفي: ف ق ك لب ل م ي، بعد: لم يكن.\r7 ـ تعالى: ت ك م، سبحانه: ق: ي.\r8 ـ بوجوده: ت ج ف ك ل م، بانه موجود: ف.\r9 ـ الثالث: ت ج ف ق ك ل م، ج: ا، و: ف ق ي. في الازل: ا ت ج ق ك لب ي: ف م، لوجود: ت ق ك لب م ي، ف ج."], [368, "ولا سامعا لوجود الأصوات. لأن رؤيته موجودا مع إنه ليس بموجود، خطأ. وهو على الله تعالى محال. ثم عند وجود العالم والأصوات صار رائيا وسامعا لها.\rالرابع وهو إنه تعالى لا يجوز أن يخبر فى الأزل بقوله: إنا أرسلنا نوحا إلى قومه. لأن ذلك إخبار عن أمر مضى. وذلك فى الأزل كذب، وهو على الله تعالى محال. ثم صار بعد إرسال نوح، عليه السلام، مخبرا عن ذلك.\rالخامس وهو أن الله تعالى لم يكن ملزما فى الأزل زيدا وعمرا بقوله: أقيموا الصلاة وآتوا الزكاة. لأن خطاب المعدوم على سبيل الإلزام سفه. وهو على الحكيم غير جائز. ثم صار ملزما للمكلفين عند حدوثهم، وحدوث الشرائط.\r__________________\r1 ـ لوجود: ف ج ايضا: موجودا: ت ج ق ك لب م ي، موجودا: ف ل.\r2 ـ خطاب: ت فقط، تعالى: ي، عند: ا ت ج ف ق ك لب ل ي، ثم من: م، ثم صار: ف، ثم: ك لب ي.\r3 ـ و (2): ي، لها: ت ج ف ق ك لب ي، له: في ف بعد: رانيا.\r4 ـ الرابع: ت ج ف ق ك لب م ي، د: ا، وهو انه تعالى: ت.\r5 ـ نوحا: ك م،: ت ف ق لب ي ك، شاهدا ومبشرا: ق، الى قومه: ا: ت ف ق ك لب م ي، مضى: ت ج ق ل م، مد مضى: ك.\r6 ـ تعالى: ت ج فقط.\r7 ـ عليه السلام: ت ف ق ك لب ل م ي، ا.\r8 ـ الخامس: ت ج ف ق ك لب م ي، وة: ا، و (1): ق، في الازل: ا لب ل ي، وتقدم على: ملزما: ف ق ك، وتاخر من زيدا وعمرا في: ت ج: م، زيدا: تاخر الى ما بعد: عمرا في: ت.\r9 ـ بقوله: ت ق ك لب م ي، لقوله: ف، اقيموا ا ت ج ف ق ك ل لب ي، واقيموا: م.\r11 ـ حدوثهم وحدوث: ت ج ف ك لب م ق ل، حلولهم وحلول"], [369, "والجواب أما صحة العالم فغير واردة، لأن العالم قبل حدوثه كان نفيا محضا، فلا يمكن الحكم عليه لا بالصحة ولا بالامتناع.\rقوله صحة الاتصاف بالصفة غير صحة وجود الصفة.\rقلنا: لا نزاع فيه، لكن الصحة الأولى متوقفة على الصحة الثانية، لأن صحة الاتصاف به متوقفة على تحققه وتحققه متوقف على صحة وجوده.\rأما المعارضات فالضابط فيها شيء واحد، وهو أن المتغير إضافة الصفات إلى الأشياء لا نفس الصفات.\rوقد دللنا فيما تقدم على أن الاضافات لا وجود لها فى الأعيان وبالله التوفيق.\r__________________\r: ي.\r1 ـ و: ت ف م، ا ج ف ك لب ي، صحة: ت ج ك م، صحة وجود: ف، صحة جواز: ل فقير واردة: ت ج ك م، غير وارد: ف، فقير وارد: لب ي.\r2 ـ ولا بالامتناع: ت ج ق م، والامتناع: ك.\r3 ـ بالصفة غير صحة وجود: ت ج ف ق لب ي ك، بالوصف غير صحة وجود: م، بالصفة غير صحة: ا.\r4 ـ الصحة (1): ا ت ج ف ق ك ل: م، الصحة (2): ا: ت ف ق لب م ي.\r5 ـ به: ت لب م ك ي، بها: ف، متوقفة: ف ج ق ك لب م ي ت، موقوفة: ا، تحققه وتحققه: ت لب م ك ي ق، تحققها وتحققها: ف، متوقف: ت ج ف ق لب ك م ي، موقوف: ا.\r7 ـ صحة: ت ج ل فقط.\r6 ـ واما: م ق، اما: ا ت ج ف ك لب ي، المعارضة: ت فقط، المتغير: ت لب ك م ج ق ل، التغير: ا ف، المعتبر: ي، باضافة: ف ج لب ت ك م ي ق، اضافة في: ا.\r9 ـ ان: ك ج ل م، كون: ت، الاضافات: ت ف ج لب ي ل ق، الاضافة: ك م.\r9، 10 ـ الاعيان وبالله التوفيق: ت، الاعيان: ج ل، الخارج: ك م."], [370, "مسئلة:\rاتفق الكل على استحالة الألم على الله تعالى.\rأما اللذات العقلية فقد اثبتها الفلاسفة، والباقون ينكرونها. لنا أن اللذة، والألم من توابع اعتداد المزاج وتنافره وذلك لا يعقل إلا فى الجسم، وهو ضعيف لأنه يقال: هب أن اعتدال المزاج يوجب اللذة، لكن لا يلزم من انتفاء السبب الواحد انتفاء المسبب. والمعتمد أن تلك اللذة إن كانت قديمة، وهى داعية إلى فعل الملتذ به، وجب أن يكون موجدا للملتذ به قبل أن أوجده لأن الداعى إلى إيجاده قبل ذلك موجود، ولا مانع لكن إيجاد الشيء قبل ايجاده محال، وإن كانت حادثة كان محل الحوادث.\rقالت الفلاسفة هذه الدلالة لا تبطل الألم.\rوأما اللذة فنحن لا نقول إنه يلتذ بخلق شيء آخر، لكنا ندعى\r__________________\r2 ـ على الله تعالى: ت فقط.\r3 ـ واما: م، اما: ا ت ج ف ق لب ك ي، اللذات: ف ق م، اللذة: ت ج ك لب ل ي، لنا: ت ج ل م ك لب ي، اما ف.\r4 ـ المزاج: ت ج لب م ك ي ق، الاجسام: ف.\r5 ـ وهو: ك لب م ق ي، فهو: ف.\r6 ـ لا: ك ل م، لم: ت ج، المعتمد: ت ج ف ق ك م ي، المعتمد لنا: لب.\r8 ـ موجدا: ك ج م، موجودا: ت، اوجده: ت ج ك م، يوجد: ق.\r10 ـ كان: ك م، فهو: ق، لكان: ت ج، محل الحوادث: ت ج لب م ق ك ي، محلا للحوادث: ف.\r11 ـ لا: ت ف ج ق ص ل م: ا ك لب ي.\r12 ـ و: ت ج ك م: ف ق لب ي، لا: ت لب ك م ي،: ف، آخر: ت ج م: ف لب ي ك."], [371, "أن علمه بكماله المطلق يوجب اللذة. والدلالة التى ذكرتموها لا تدفع ما قلناه. وتقريره وهو أن كل من تصور فى نفسه كمالا فرح، ومن تصور فى نفسه نقصانا تألم قلبه. فإذا كان كماله سبحانه وتعالى أعظم الكمالات وعلمه بكماله أجل العلوم، فلم لا يجوز أن يستلزم ذلك أعظم اللذات.\rوالجواب إنه باطل بإجماع الأمة وكذلك الألم.\rمسئلة:\rاتفق الكل على أنه غير موصوف بالألوان والطعوم والروائح والمعتمد الإجماع.\rوالأصحاب قالوا: اللون جنس، تحته أنواع، وليس بعضها بالنسبة إلى بعض صفة كمال. وبالنسبة إلى بعض صفة نقصان. وأيضا الفاعلية لا تتوقف على تحقق شيء منها. وإذا كان كذلك،\r__________________\r1 ـ بكماله: ا ف ل ي ك، لكماله: م، بالكمال: ق ت ج ل.\r2 ـ قلناه: م ف، ذكرناه: ت ك، ذكرنا: ج، قلنا: ق ل، وهو: ت، هو: ج.\r3 ـ في نفسه: ت ف ج ق ك لب ل م ي، ا، نقصانا: ت ج لب ق ك م ي، نقصا: ف، قلبه: ت ج ق لب، في قلبه: ا،: ف ك م ي، فاذا: ا ت ج ك ق ي، واذا: ف م، فاذن: لب، سبحانه و: ت ج ك ل م: ف ق ي.\r4 ـ الكمالات: ت ف ج ق ك ل م ي، كمالات: ا، العلم: ق.\r6 ـ والجواب: ت ج ق ك ل م ي، الجواب: ف، والجواب عن الاول: ا، انه: ت ج ف ق لب ك م، بانه: ي، وكذلك الالم: ت ف ق ك م ي، والالم كذلك: لب.\r8 ـ على: ل، غير موصوف: ت ج ف ق لب ك ل ي، غير غير موصوف: ا، تعالى ليس موصوفا: م.\r10 ـ تحته: ت ج ف ق ك ل، وتحته: لب م ي.\r11 ـ بعض (2): ي، نقصان: ت ق ك لب م، نقص: ف، نقص اولى من العكس: ج."], [372, "لم يكن الحكم بثبوت البعض أولى من الباقى، فوجب أن لا يثبت شيء منها.\rولقائل ان يقول تدعى إنه ليس البعض أولى من البعض فى نفس الأمر، أو فى عقلك وذهنك. والأول لا بد فيه من الدلالة. فلم لا يجوز أن يكون ماهية ذاته تستلزم لونا معينا من غير أن تعرف لمية ذلك الاستلزام.\rوالثانى مسلم لكن لا يلزم منه إلا عدم علمنا بذلك المعنى، فاما عدمه فى نفسه فلا والله أعلم.\rالقول فى الصفات الثبوتية:\rمسئلة:\rإنه تعالى قادر خلافا لجمهور الفلاسفة.\rلنا إنه ثبت افتقار العالم إلى مؤثر. فذلك المؤثر: اما أن يقال\r__________________\r1 ـ الباقي: ا ب ق ك ف لب ي، البعض: ت ل، الثاني: م.\r3 ـ لقائل: ج ك ف ل م، القائل: ت، تدعى: ج ق ك لب م، ندعى: ا ت ف، البعض (1): ا ت ج ف ق ك لب ي، بعض: م.\r4 ـ و (2): ج ك م،: ت ق ل.\r5 ـ ان: ت فقط. تعرف: ت ف لب م، نعرف: ا ج، يعرف: ق ك ي.\r6 ـ لمبة: ف ك ل م، كمية: ت ج ق، كيفية: ج.\r7 ـ مسلم: ج ك ل م، نسلم: ت، منه: ا فقط، المعنى ا ف ق ص ل، المعين: ت ك لب م ي، ج.\r8 ـ والله اعلم: ا، وبالله التوفيق: ت ج ل: ف ج ق ك لب م ي.\r11 ـ انه: ا ت ج ف ق ك لب ي، اتفق الكل على انه: م. جمهور الفلاسفة: ت ج ف ق ك لب م ي، للفلاسفة: ا.\r12 ـ فذلك: ت ج ف ك لب م ي، فذلك اما: ا، مؤثر: ت ج"], [373, "صدر الأثر عنه مع امتناع أن لا يصدر، أو صدر مع جواز أن لا يصدر.\rوالأول باطل لأن تأثيره فى وجود العالم ان لم يتوقف على شرط لزم من قدمه قدم العالم، وقد أبطلناه. وإن توقف على شرط، فذلك الشرط إن كان قديما عاد الالزام وان كان محدثا كان الكلام فى حدوثه كالكلام فى الأول، فلزم التسلسل إما معا، وهو محال، أو لا إلى أول. فيلزم منه حوادث لا أول لها، وهو محال ولما بطل هذا القسم، ثبت القسم الثانى ولا معنى للقادر إلا ذلك.\rفإن قيل: لم لا يجوز أن يكون المؤثر موجبا.\rقوله يلزم من قدمه قدم العالم.\rقلنا اما أن يكون صحيح الوجود فى الأزل أو لا يكون. فإن كان الأول لم يكن قدم العالم محالا، فنحن نلتزمه وإن كان الثانى\r__________________\rل م، المؤثر: ك.\r1 ـ صدر (2): ت ج.\r3 ـ و: ت.\r4 ـ فدمه: ا فقط. لزم ... على شرط: ت ج ف ق ك لب م: ي.\r5 ـ وان: ا ت ف ج ق ك لب ي، فان: م، محدثا: ت ج ق ل م، حادثا: ك.\r6 ـ فلزم: ت ق، ولزم: ك ج م ل، معا: ت ف ق ك لب ج م، دفعة: لب، لا: ك.\r8 ـ ثبت: ك ل م ف، تعين: ت ج القسم (2): ت ج فقط، معنى: ت ج ف ق ك لب ي، نعنى: م، للقادر: ا ت ج ف ق ك لب ي، بالقدار: م.\r12 ـ لم يكن: ت ج ق ك لب م ي، لزم ان لا يكون: ف، فنحن: ك ل ف م، ونحن: ت ج تلتزمه: ت ج ق ك لب م ل ي، تلزمه: ف."], [374, "كان لصحة وجوده بداية. وإذا كان كذلك، لم يلزم من قدم المؤثر قدم العالم لأن صدور الأثر عن المؤثر، كما يعتبر فيه وجود المؤثر يعتبر فيه إمكان الأثر. والّذي يزيده تقريرا وهو أن القادر عندكم هو الّذي يصح منه الإيجاد والله تعالى كان قادرا فى الأزل، ولم يلزم من أزلية قدرته صحة الإيجاد أزلا فلما لم يلزم من القدرة الأزلية حصول الصحة فى الأزل، فلم لا يجوز أن لا يلزم من وجود المؤثر وجود العالم فى الأزل.\rسلمنا أنه إن لم يتوقف تأثيره فى العالم على شرط لزم من قدمه قدم العالم. فلم لا يجوز أن يقال تأثيره فى وجود العالم كان موقوفا على شرط حادث، وذلك الشرط على شرط آخر، لا إلى أول. والكلام فيه يرجع إلى مسئلة حوادث لا أول لها.\rسلمنا أنه لا بد من القادر، ولكن لم قلت: إنه واجب الوجود؟ ولم لا يجوز أن يقال واجب الوجود اقتضى لذاته موجودا قديما، ليس بجسم ولا بجسمانى. وذلك المعلول كان قادرا، وهو الّذي خلق العالم.\r__________________\r1 ـ بداية: ا ج ق ك لب ل ي، بذاته: ت ف م، واذا: ت ك م، وان: ق.\r3 ـ يزيده تقريرا: ف ك لب ي، يؤيد تقريره: ت، نزيده تقريرا: ج، يؤيده: ق م، يزيد: ا، و (2): ت ق.\r4 ـ عندكم: ت ج ف ك لب ي، عندك: ق م، كان: ت.\r8 ـ قدرته: ت ق م، قدرة الله تعالى: ك.\r5 ـ انه: ف، ان: ت ج ف لب ي، لو: ق ك م، شرط: ا ت ق ك لب ج ي، الشرط: ف، شرطه: م.\r9 ـ فلم: ت ج ك لب م ي، لكن لم: ف ق.\r10 ـ وذلك: ت ج ف ك لب ل ي، وحدوث ذلك: ق م، الى اول ت ك لب م، الى نهاية: ف، اوله له: ق ي.\r12 ـ و: ت ج: م، قلت: ت ج ك م، قلتم: ف ق لب ي.\r13 ـ يقال: ت ج ق م، يقال ان: ك.\r14 ـ بجسماني: ا ت ك، جسماني: ج ف ق لب م ي."], [375, "سلمنا أن ما ذكرتموه يدل على القادرية لكنه معارض بنوعين من الكلام.\rالأول أن نبين أن حقيقة القادر على الوجه الّذي قلتموه محال. وبيانه من وجوه.\rالأول أن المصدر إن استجمع جميع ما لا بد منه فى المصدرية سلبا كان أو إيجابا امتنع الترك وان اختل قيد من القيود المعتبرة امتنع الفعل. إلا إذا قيل الشيء الواحد يكون مصدرا للفعل تارة وللترك أخرى من غير تغير حال البتة فى الحالتين، لكنه يكون ترجيحا لأحد طرفى الممكن على الآخر من غير مرجح، وهو محال. وأيضا فالمصدرية على هذا التقدير تصير اتفاقية. لأن فيضان الأثر عن المصدر إن توقف على انضياف قيد جديد إليه، لم يكن الحاصل أولا مصدرا تاما. وإن لم يتوقف عليه كان صدور الأثر عن ذلك\r__________________\r1 ـ ذكرتموه: ك م، ذكرتم: ف ل ق، ذكروه: ت ج، ذكرته: ا ف لب، القادرية: ت ج ف ق لب ي، القادر: ك م.\r3 ـ يبين: ت ف ك م، تبين: ي، تبين: ج ل ق لب، بين: ا.\r5 ـ الاول: ت ف ق ك لب م ي، احدهما: ج، ا: ا. ان (2): ك ل م، اذا: ت ج، جميع: ج ك ل م، جملة: ت، منه: ت ج ف ق ك لب ل ي، م.\r6 ـ كان: ت ج ف ق ك ل: م، وان: ا ت ف ج ق ك، فان: م، فاذا: لب ي.\r7 ـ الشيء: ت ج ف ك لب ل ي، ان الشيء: م.\r7، 8 ـ مصدرا .. تارة كرة: لب ي .. اخرى: ت ج ق ك لب م ي، تارة للمصدر واخرى: ف.\r8 ـ للشرك: ا ت ج ف ق ك لب، الترك: م ي، تغير: ا ت ج ف ل ق لب ي، تغيير: ك، م، الحالتين: ا ت ف ل ي، الحالين: ج ق ك لب م.\r10 ـ فيضان: ت ج ف ق ك ل م، حصول: ا.\r11 ـ انضياف قيد: ج ك م، انصاف قيد: ت، انضاف قصد: ف لب، انضياف قصد: في هامش ق، اتصاف قصد: ل."], [376, "المصدر فى زمان بعينه دون آخر، مجرد اتفاق وتجويزه يقتضي تجويز انقلاب الممكن لذاته فى وقت، واجبا لذاته فى وقت آخر فينسد باب اثبات المصدر فثبت ان المكنة من الفعل والترك غير معتبر فى حقيقة القادر.\rومما يؤكد ذلك ان مذهب المعتزلة ان الاخلال بالثواب، والعوض يقتضي الجهل والحاجة المحالين على القديم. ومستلزم الممتنع ممتنع. فالاخلال بهما ممتنع فصدورهما عنه واجب.\rومن مذهب أهل السنة ان إرادة الله تعالى وقدرته متعلقتان بايجاد أشياء معينة. والتغير على صفاته ممتنع فتكون المؤثرية لصفاته واجبة، ونقيضها ممتنع، وامكان التردد مردود.\rومن مذهب الكل: ان الله تعالى عالم فى الأزل بأن أى الجزئيات\r__________________\r1 ـ بعينه: ك ل م ف، يعين: ت ج، الاخر: ك فقط، مجرد اتفاق: ق ل لب ي، بمجرد اتفاق: ف، مجرد الانفاق: ج ك م، مجرد الانفاق: ت، تجويزه: ت ج ف ق لب م، تجوزه: ي.\r3 ـ المصدر: ت ج ق ك لب م ي، الصانع: ف، فثبت فظهر: ت ج لب ي المكنة الممكنة: ي: ت ج ك لب ف ق ي، ينظر: ل.\r4 ـ معتبر: ا ت ج ق ي، معتبرة: ف ك لب ل م.\r5 ـ و (2): ت ج ف لب ك م ي، او: ا ق.\r6 ـ المحالين على القديم العديم: ل: ت ج ق ك ل م ي، وهما محالان على الله تعالى: ف، وهما محالان على القديم: لب.\r7 ـ فصدورهما: ك ف م، وصدورهما: ت ج ق ل، عنه: ت ج ق لب ل م ي، غير: ف.\r8 ـ من: ا ت ج ق ف ك ل ي، لب م، السنة: ك ل م، السنة والجماعة: ت ج، تعالى ف، متعلقتان: ت ج ق ك، متعلقان: ل م.\r9 ـ معينة: ا ت ج ف ق ك لب ل ي، متعينة: م، لصفاته: ت ج، بصفاته: لب: ف ق ك م ي، ممتنع: ت ق ك لب م، ممتنعا: ا ف ي، ممتنعة: ج.\r10 ـ وامكان: ا ت ف ق ك لب ي، فامكان: م.\r11 ـ الجزئيات: ت ج ف ك لب ل م ي، الحركات: ا."], [377, "توجد، وأيها لا توجد. وامتناع تغير العلم يستلزم امتناع تغير المعلوم، والقدرة على الممتنع ممتنعة، فالمكنة من الطرفين غير معتبرة على جميع المقالات.\rالثانى أن المكنة من الطرفين اما أن تثبت حال حصول أحدهما أو قبل ذلك. والأول باطل، لأن حال حصول أحدهما، فذلك الحاصل واجب ونقيضه محال. وامكان التردد بين الواجب والمحال محال.\rوالثانى كذلك، لأن شرط الحصول فى الاستقبال حصول الاستقبال الممتنع الحصول فى الحال. والموقوف على المحال محال. فحصوله بقيد كونه فى الاستقبال ممتنع فى الحال. والممتنع لا يمكن منه.\rالثالث قولنا: القادر يجب أن يكون مترددا بين الفعل والترك، إنما يصح أن لو كان الفعل والترك مقدورين له لكن الترك محال\r__________________\r2 ـ فالمكنة: ج ك ل م ف، فالممكنة: ت، من: ا ت ج ف ل ك لب ي، في: م.\r3 ـ معتبرة: معتبر: ل.\r4 ـ الثاني: ت ج لب ي، ب: ا، الثاني ان: ق ك م، تثبت: ت ج ك ل م، يحصل: ق.\r3، 4 ـ غير .. الثاني: ف فقط.\r5 ـ فذلك: ف ج ك م ي، ذلك، ق لب، بذلك: ت.\r6 ـ بين: ت ف ك ق لب م ي، ين: ا.\r8 ـ كذلك: ت ج ك لب ل ي، ايضا كذلك: ف م، ا ق.\r9 ـ الممتنع: ت ج ف ق ك م ي، وحصول الاستقبال ممتنع: لب.\r10 ـ والممتنع لا يمكن منه: ا ت ج ف منه: ا، والممتنع لا تمكن فيه: ق ك م ي: ق: منه، فالمكنة لا يمكن فيه: لب.\r11 ـ الثالث: ت ف ج ق ك لب ل م ي، ج، ا، قولنا: ت ج ق لب م ك ي، قلنا: ف.\r12 ـ ان: ا، له: ج ك ل م، ت."], [378, "أن يكون مقدورا، لأن الترك عدم، والعدم نفى محض. ولا فرق بين قولنا: لم يؤثر أثرا وبين قولنا أثر فيه تأثيرا عدميا ولأن قولنا ما أوجده معناه انه بقى على العدم الأصلي. فإذا كان العدم الحالى هو العدم الّذي كان استحال استناده إلى القادر، لأن تحصيل الحاصل محال، فثبت أن الترك غير مقدور أصلا، وإذا كان كذلك، استحال أن يقال: القادر هو الّذي يكون مترددا بين الفعل والترك.\rفإن قلت الترك هو فعل الضد، فالقادر متردد بين فعل الشيء وفعل ضده.\rقلت فيلزمك أن لا يخلو القادر عن فعل أحد الضدين، فيلزمك اما قدم العالم أو قدم ضده وأنت لا تقول به.\rالنوع الثانى: سلمنا ان القادر فى الجملة معقول لكن تعذر اثبات"]], "pg": [357, 378]}, "687.11": {"x": [[378, "ه هاهنا لوجوه:\rالأول: وهو انه تعالى لو كان قادرا لكانت قادريته اما أن تكون\r__________________\r1 ـ مقدورا: ك ق م ت، مقدورا له: ف.\r2 ـ لم يؤثر ثرا: ت ج ف لب ي، لم يكن مؤثرا: ك م، ق، وبين قولنا: ق فقط، اثر: ت ف ق ك لب م ي، اثرا: ا. فيها: ق، لان: ت ج ق ك لب م ي، لا: ف.\r3 ـ لوجده: ت ج ل ق ك ل، اوجد: م.\r4 ـ هو العدم الذي: ت ج ق لب ل ي، عين ما: ق ك م.\r5 ـ اصلا: ف: ت ق ك لب م ي.\r8 ـ الترك: ا فقط، فالقادر: ت ج م، والقادر: ق.\r9 ـ وفعل: ا ت ج ف ق ك لب ي، وبين فعل: م.\r10 ـ فيلزمك (1): ج ق ك لب م ي، فيلزمكم: ا ل ف، يلزمك: ت، فيلزمك (2): ق ك لب م ي، فيلزم: ت ج ف، فيلزمكم: ا، فلزمكم: ل.\r12 ـ الثاني: ت ج ف ق ك لب م ي، ب: ا.\r13 ـ ههنا: ت ل ك، هنا: ج ق م.\r14 ـ الاول: ت ف ق ك لب ل م ي، احدها: ج ا: ا."], [379, "أزلية أو لا تكون. والأول محال، لأن التمكن من التأثير يستدعى صحة الأثر لكن صحة العالم فى الأزل محال. لأن الأزل عبارة عن نفى الأولية والحادث ما يكون مسبوقا بالأول والجمع بينهما متناقض.\rوالثانى أيضا: محال لأن قادريته تعالى إذا لم تكن أزلية كانت حادثة فافتقرت إلى مؤثر. فإن كان المؤثر مختارا عاد البحث كما كان وان كان موجبا كان المبدأ الأول موجبا.\rفان قلت انه فى الأزل يمكنه الإيجاد فيما لا يزال. وحاصله ان امتناع الأثر عند قيام المقتضى قد يكون لحصول المانع.\rقلت المانع ان كان ممكن الزوال لذاته، فيفرض ارتفاعه؛ وحينئذ يصح الفعل الأزلى هذا خلف. وان كان ممتنع الزوال لذاته وجب أن يكون كذلك أبدا. إذ لو جاز أن ينقلب ممكنا لجاز أن يقال:\r__________________\rوهو: ك، انه: ت ج ق ك م، ان الله: ف لب ي، لكانت: ت ف ق ك م ي، لكان: لب.\r2 ـ صحة .. محال: ت ج ل، لا صحة في الازل: ك ف م.\r3 ـ والجمع: ت ق ك لب م ي، فالجمع: ف.\r4 ـ محال: بعد متناقض: ا ف ك، متناقض: ف.\r5 ـ الثاني: ت ف ق ك لب م ي، ب: ا، ايضا: ف ق، تعالى: ف ك.\r6 ـ المؤثر: ق، البحث: ت ج ك م، الاشكال: ق.\r7 ـ موجبا (2): ت ج ف ق ك م ي، الموجب: لب.\r8 ـ ان: ت ج ق م، يرجع ان: ك.\r9 ـ لحصول: ا ت ج ل ف، لحضور: ق ك لب م، بحضور: ي: مانع: ك.\r10 ـ فيفرض: ت ج ف لب ي، فليفرض: ق ك م.\r11 ـ ممتنع الزوال: ت ف ق ج ك م ي، ممتنعا: لب، الممتنع: ق: وجب: ا ت ج ف ق ك لب ي، فليفرض وجب: م.\r12 ـ ممكنا: ا ك ي."], [380, "العالم كان ممتنعا لذاته، ثم انقلب واجبا لذاته.\rالثانى أن مقدور القادر لا بد وأن يتميز عن غيره لأن اقتدار القادر عليه نسبة بين القادر وبينه. وما لم يتميز المنسوب إليه عن غيره، استحال اختصاصه بتلك النسبة دون غيره. ولأن تمكن القادر من الجمع بين الحركة والسواد، بدلا عن الجمع بين السواد والبياض، يستدعى امتياز أحدهما عن الآخر. ولأن كونه قادرا على إيجاد الحركة بدلا عن السكون، وبالعكس. يستدعى امتياز كل واحد منهما عن الآخر. ولأن التردد بين الشيئين يتوقف على مغايرتهما. فثبت انه لا بد من التميز. وكل متميز ثابت فإذن تعلق القدرة به يتوقف على ثبوته فى نفسه. فلو كان ثبوته لأجل القدرة لزم الدور، ولزم اثبات الثابت، وهو محال.\rفإن قلت شرط التعلق تحقق الماهية والحاصل من التعلق هو الوجود.\rقلت فالذات لما كانت متقررة قبل التعلق، لم تكن مقدورة. لأن\r__________________\r1 ـ لذاته (1): لب، لذاته (2): ا ت ج ق لب: ك ل م ي.\r2 ـ الثاني: ت ج ف ق ك لب م ي، ب: ا، ان مقدور: ا ج ق ك لب ي، مقدور: ت، ان المقدور: م.\r4 ـ ولان: ا ف ج ك لب ي، لان: ق، ولا: ت م.\r7 ـ ولان: ف ج ي، لان: ك لب، فان: ق ل م، ولكن: ت.\r9 ـ يتوقف .. متمميز: ي، التميز: ج ف ق ك م، التمييز: ت ل.\r10 ـ القدرة: ت ج ق ك لب م، الارادة: ف.\r11 ـ وهو: ت ج ق لب، وان ذلك: ك، وانه: ف م ي.\r12 ـ تحقق: ت ج ف ق ك لب ي، تحقيق: م، من: ا ت ج ف ق ك لب ي، عن: م.\r13 ـ قلت: ت ج ق م، قلنا: ك، لما كانت: ك ل م، ان كان: ت ج، متقررة: ت ج ق ك لب م ي، مفتقرة: ف."], [381, "اثبات الثابت محال: فالمتعلق به هو الّذي ليس بثابت، وهو اما الوجود أو موصوفية الذات بالوجود، لكن ذلك محال. لأنا بينا أن المتعلق به متميز، والمتميز ثابت؛ فإذن ما ليس بثابت فهو ثابت، هذا خلف.\rالثالث لو كان قادرا من الأزل إلى الأبد، ثم إذا أوجده لم يبق مقدورا، لاستحالة ايجاد الموجود، فذلك التعلق القديم قد فنى وعدم والقديم محال.\rالرابع: إذا قلنا القادر يمكنه أن يوجد. فالموجدية ليست عبارة عن نفس الأثر. أما أولا فلأن الموجدية صفة للموجد. والأثر قد لا يكون صفة له. فإن العالم ليست صفة لله تعالى.\r__________________\r1 ـ به: ت ج ف لب ي: ق ل ك م.\r2 ـ لانا: ت ج ف ق ك ل م ي، لا: ا.\r3 ـ به: ف: ت ج ق ك لب م ي، المتميز ثابت: ك م، المتميزات ثوابت: ت، ما: ا ت ج ف ق ك لب ي، م.\r3، 4 ـ فهو .. خلف: ت ج ف ق ك م، ثابت وهو ممال: لب ي.\r5 ـ الثالث: ت ج ف ق ك ل لب م ي، ج: ا، ثم اذا اوجده: ك م، اذا وجد المقدور: ت، فاذا وجد المندور: ج ل.\r6 ـ مقدورا: ت ج ق ك لب م ي، قادرا: ف، فذلك: ا ت ج ف ك لب ي تكرر في: ق، وذلك: م، قد فنى: ك ل م، عدم: ت ج.\r8 ـ الرابع: ت ج ف ق ك لب م ي، د: ا، اذا قلنا القادر: ت ج ف ك لب م ي، القادر اذا قلنا: ا، اذا قلنا ان القادر: ق، يمكنه: ت ف ق ك لب م ي، تمكنه: ا. فالموجدية: ت ك لب ج م، الموجودية: ا ف ل ق ي.\r9 ـ الموجدية: ت ج ك لب، الموجودية: ف ق م ي، للموجد: ا ت ف ك لب ي، للموجود: ق م، الاثر: ت ج ف لب م، الاثر ولا عن وجوده: ق ك ي.\r9، 10 ـ قد لا يكون: ت ق م، فلا: ك.\r10 ـ له: ت ق ج ك م ي، ا ف لب."], [382, "وأما ثانيا، فلأنا إذا قلنا الأثر انما وجد بالقادر، لأن القادر أوجده. فلو كان المفهوم من قولنا: أوجده نفس وجود الأثر لكنا قد قلنا: إنما وجد الأثر لأنه وجد الأثر. فيكون الحاصل إنه وجد الأثر بنفسه، وذلك محال. فظهر أن الموجدية صفة للموجد، فهى إن كانت ممكنة الوجود واقعة بالقادر المختار، عاد التقسيم فيه، وإن كانت واجبة، وجب وجود الأثر فى الأزل، لأن الموجدية بدون وجود الأثر، البتة محال عقلا. فثبت أن المؤثر لا يعقل إلا على سبيل الإيجاب.\rوالجواب قوله: إنما لم يوجد العالم فى الأزل لاستحالة وجوده أزلا. قلنا وقوع العالم بالقدرة والاختيار فى الأزل محال. اما اسناده إلى العلة الموجبة غير محال. فلم يصلح هذا مانعا عن صدوره عن العلة القديمة فى الأزل.\rسلمنا كونه محالا فى الأزل ولكن لو وجد قبل أن يوجد بمقدار\r__________________\r1 ـ ثانيا: ت ف ق ك لب م، الثاني: ي.\r2 ـ الامر: ق.\r3 ـ وجد: ت ج ق ك لب م ي، اوجد: ف، الاثر (1): ت ج ك، بالاثر: ق، لانه: ج ك ل م، انه وجد الاثر لانه: ت.\r4 ـ وذلك: ق ك لب م ي، وهو: ت ج ف، الموجدية: ت ج ك لب ي، الموجودية: ف ل ق م، للموجد: ف ج ق م، الموجد: ت ك ي، الموجود: ا، فهي اذن: لب.\r5 ـ واقعة، ت ج ف ك لب ل م، وقعت: ق ي، فيه: ت ج ق ك لب م ي، فيها: ف.\r6 ـ وجود: ي، في الازل: ف، الموجدية: الموجودية: ق.\r7 ـ البته محال: ت ف ق ك لب م ي، محال البتة: ا ج. يعقل: ا ت ج ف ق لب ل، يفعل: ك م.\r8 ـ الايجاب: ا ت ج ف ق ل ك لب ي، الايجاد: م.\r9 ـ و (1): ت ج ق ك.\r11 ـ اسناده: ت، استناده: ج ك ل م، يصلح: ت ج ق م، يصح: ك، عن صدوره: ج ك م، ما لم يفرض صدوره: ب.\r12 ـ و: ت، يوجد: ت، وجد: ك م."], [383, "يوم لم يصر بسبب ذلك أزليا، وكان يجب أن يوجد قبل أن وجد، ولأن العلة قائمة، والمانع المذكور مفقود.\rأما حوادث لا أول لها فقد تقدم ابطالها، وأما الواسطة فقد أجمع المسلمون على إبطالها.\rوأما المعارضة الأولى فجوابها أنه لم لا يجوز أن يكون المؤثر المستجمع بجميع جهات المؤثرية تارة يكون مصدرا للأثر وتارة لا يكون ونحن قد بينا أن المختار هو الّذي يمكنه الترجيح لا لمرجح.\rوأما الثانية فجوابها أن التمكن ثابت بالنسبة إلى المقدور قبل دخوله فى الوجود.\rقوله لا مكنة له فى الحال على الشيء الّذي سيوجد فى الاستقبال. قلنا لا نسلم. ولم لا يجوز أن يقال حصل فى الحال التمكن من إيجاده فى المستقبل.\rوأما الثالثة فجوابها أن القادر هو الّذي يصح أن يصدر عنه ما يكون فى نفسه ممكنا. والفعل إنما يصح فيما بعده. فلا جرم\r__________________\r1 ـ و: ت ج ك، ف: ق ل م.\r2 ـ اما: ا ت ك لب ي، واما: ف ق م، ابطالها: ت ف ق ك م، ابطاله: ا لب ج ي.\r5 ـ و: ت ج ل ف: ق ك لب م ي، لم: ف، المؤثر: ا ف.\r6 ـ بجميع: ت ف ق ل م، لجميع: ك ج لب ي، فجميع: ا، للاثر: ت ج ف ق ك لب ل م ي، الاثر: ا.\r7 ـ نحن: ا، يمكنه: ت ج ق ك لب م ي، يصح منه: ف.\r8 ـ و: ا ف، ان: ا ت ج ف ك، اما: م.\r10 ـ له: ا.\r12 ـ المستقبل: ت ج م، الاستقبال: ف ق ك لب ل ي.\r14 ـ فيما: ت ج ف ق ك لب م ي، في: ا، فيما لا يزل: ج."], [384, "كان الله تعالى قادرا فى الأزل على التكوين فيما لا يزال.\rوأما الرابعة: فجوابها أن النسبة التى قد ادعيتموها وبنيتم عليها الامتياز ممنوعة فليس فى الوجود إلا القدرة والمقدور.\rوأما الخامسة: فجوابها أن التعلق اضافة ولا وجود لها فى الأعيان فلا يلزم من عدمها عدم القديم.\rوأما السادسة: فجوابها أن الموجدية إضافة الذات إلى الأثر وقد بينا أن الإضافات لا وجود لها فى الأعيان.\rمسئلة:\rاتفق جمهور العقلاء على أنه تعالى عالم إلا قدماء الفلاسفة.\rلنا أن أفعال الله تعالى محكمة متقنة. وكل من كان أفعاله\r__________________\r1 ـ تعالى م، تكوين: ف.\r2 ـ الرابعة: ت ج ف م، الرابع: ك، الوجه الرابع: ت لب ي، فجوابها: ت ج ق م، فجوابه: ك، قد: ك.\r7 ـ ممنوعة: ت ج ق لب م ي، فممنوعة: ف ك.\r6 ـ الاضافة: ي، ولا: ت ف ق م ي، لا: ك.\r5 ـ الاعيان: ت ج قق ك لب م ي، الخارج: ف، من عدمها: ك.\r4 ـ الموجدية: ك لب م ي، الموجودية: ف ق، الموصوفية: ت ج، اضافة: ت ج ف ق لب ك م، اضافته: ي، الذات: ت ج ف ق ك لب م، للذات: ا ي.\r7 ـ وقد بينا أن: ت ج الاضافة: ف، الاعيان: ت م ج لب ل ي، الاعيان فلا يلزم عدم القديم ف، الاعيان وبالله التوفيق: ق ك.\r8 ـ تعالى: ت.\r9 ـ ان: ا ت ج ك: ف ق لب ل م ي، افعال الله تعالى: ا، اضافة تعالى وتقدس: ت: ت ج ف ك، افعاله: ق لب م ي، ونل من: ا ت ج ف ق ك، وكل ما: لب ل ي، فكل ما: م."], [385, "كذلك فهو عالم. والمقدمة الأولى حسية. والثانية بديهية.\rفإن قيل لا نسلم أن هذا العالم فعله. ولم لا يجوز أن يكون فعل الواسطة سلمناه، لكن المراد من الفعل المحكم هو الّذي يكون مطابقا للمنفعة، أو ما يكون مستحسنا فى العرف، أو أمرا ثالثا.\rفإن أردتم به الأول، فاما أن تريدوا به كون الفعل مطابقا للمنفعة من كل الوجوه، أو من بعض الوجوه.\rفإن أردتم به الأول فهو ممنوع. فإن قلتم أن المخلوقات مطابقة للمنفعة من كل الوجوه، فظاهر أنها ليست كذلك، لكثرة ما نشاهد فى العالم من الآفات.\rوإن أردتم به الثانى فمسلم، لكن كون الفعل مشتملا على النفع\r__________________\r(10/ 384، 1) افعاله كذلك فهو عالم: ت ج، كذلك فهو عالم: ق ك م، افعال ذلك كان عالما: ف، كذلك كان عالما: لب ي، كذلك عالما: ل.\r3 ـ سلمنا ه: ت ج ق م، سلمنا: ي، من: ت ق م، ب: ي.\r6 ـ فان ارتم به: ت ج ق ك ل م، ان كان المراد هو: ف، تريدوا: ق ك م، يريدوا: ا ت، كون الفعل: ق ك م، كوفه: ت ف ج لب ل ي.\r7 ـ بعض الوجوه: ت ج ل م، وجه دون وجه: ك.\r8 ـ اردتم: ات ك لب ج ي ل، اردت: ق م، فان (2): ت، فلم: ا ف ج ق ك لب ل ي، ولم: م.\r9 ـ الوجوه: ت ج م، وجه: ق ل، فظاهر: ت ق م ي، وظاهر: ا ج ف ك ل، والظاهر: لب، نشاهد: ت ق ج ك لب م ي ل، نشاهده: ف.\r7، 9 ـ او من بعض .. الوجوه: ف.\r10 ـ من الافات: ت ج ف ق ك ل لب م، من كل وجه وظاهر انها ليست كذلك الافات: ي.\r11 ـ وان اردتم: ا ف لب ل ي، وت ق ك ان اردت: ت ق"], [386, "من بعض الوجوه لا يدل على كونه فاعله عالما. لأن فعل الساعى والنائم، بل الحركات الصادرة عن الجمادات قد تكون نافعة من بعض الوجوه.\rوإن أردتم بالمحكم ما يكون مستحسنا فى العرف فاما أن تريدوا به ما يكون مستحسنا على وجه لا يمكن تصور ما هو أحسن منه أو تريدوا به كونه مستحسنا فى الجملة.\rفإن أردتم به الأول، فلا نسلم ان العالم كذلك. فإنا لا ندرى أن ترتيب الكواكب فى السموات، وترتيب أبدان الحيوانات على وجه أكمل مما هو الآن عليه، ممكن أم لا؟.\rوإن أردتم به الثانى فمسلم أن العالم كذلك، لكنه لا يدل على علم الفاعل فان فعل الساهى والنائم قد يستحسن من بعض الوجوه.\r__________________\rك م، لكن: ت ج ق م، ولكن: ف.\r1 ـ الوجوه: ت ك م، وجه: لب ي.\r4 ـ وان: ق ك، واما ان: ت ج م، بالحكم: ت ج ق لب م ي، بالحكمة: ف، بالمحكوم: ل.\r5 ـ به: ت.\r4، 6 ـ في العرف .. مستحسنا: ق.\r5، 6 ـ به ما .. تريدوا: ف.\r7 ـ اردتم: ا ف ق ك ي، اردت: ت ج لب م، فانا لا ا ت ج ق ك لب م ي، فانا: ف.\r8 ـ ترتيب (1): ف ق ك م، تركيب: ت ج ل لب ي، و: ا ت ف ق ك لب ي، او: م، ترتيب (2): ت ج ق ل لب ك م، تركيب ف ي، الحيوانات: ت ج ق ك لب ل م ي، الجسمانيات: ف.\r9 ـ مما: ا ت ق ج ك لب ل ي، فيما: م، ما: ف، ام لا: ف.\r10 ـ وان اردتم: ا ف، وان اردت: ت ق ج ك لب، فان اردت: م.\r9، 10 ـ ممكن .. كذلك: ي.\r11 ـ علم: ا ت ج ف ق ك لب ي: م."], [387, "وأما إن أردتم بالاحكام والاتقان معنى ثالثا فاذكروه لنتكلم عليه.\rولئن نزلنا عن الاستفسار، فلم قلتم أن الفعل المحكم يدل على علم الفاعل وبيانه من وجوه:\rأحدها: أن الجاهل قد يتفق منه الفعل المحكم نادرا. واتفق العقلاء على أن حكم الشيء حكم مثله: فلما جاز ذلك مرة واحدة، جاز أيضا مرتين وثلاثا وأربعا.\rوثانيها أن فعل النحلة فى غاية الإحكام، وهو بناء البيوت المسدسة مع كثرة ما فيها من الحكم التى لا يعرفها إلا المهندسون. وكذا العنكبوت تبنى بيتها فى غاية الاحكام. وكذا نرى كل واحد\r__________________\r1 ـ واما: ا ت ج ف ق ك لب ي، فاما: م، اردتم: ا ف ل ق ك ي، اردت: ت لب ج م، فاذكروه: ج ك م، فاذكره: ت، لنتكلم: ت ج ف ق ك لب م، حتى نتكلم: ي.\r3 ـ و: ت، قلتم: ا ف، قلت: ت ق ك ج لب ل م، ان الفعل المحكم: ت ج ق ل لب ك ي، ان الفعل المحكم المتقن: ا، بان الفعل المحكم: ف، ان فعل المحكم: م.\r5 ـ احدها: ت ج ف ق ك لب م ي، ا: ا، قد: ت ج م ك لب ي، فقد: ف.\r7 ـ ايضا: ت ج ق ل م، ذلك ايضا: ك، ثالثا ورابعا: ا.\r8 ـ ثانيها: ت ف ق ك لب م ي، ب: ا، محكم: بعد النحلة في: ك ي والاتقان: بعد الاحكام في ك ق.\r8، 9 ـ البيوت المسدسة: ق ج ك م، البيت المسدس: ي، بين المسدسة: ف، البيت المسدسة: ت لب.\r9 ـ مع: ت ج ك لب م ي، من: ف، الحكم: ا ت ج ف ق ك لب، الحكمة: م ي، المهندسون: ق ك ل م، الهندس: ت ج ف لب ي.\r10 ـ بينها: ت ك لب م ي، بينا: ف، كذا (2)، ا ت ج ك، كذلك: ف ق م، نرى: ت ج."], [388, "من الحيوانات تأتى بالأفعال الموافقة لها بحيث يعجز عن تحصيلها أكثر الأذكياء، مع أنه ليس لشيء منها علم ولا حكمة.\rولئن سلمنا أن ما ذكرته يدل على كونه تعالى عالما، لكنه معارض بأمرين.\rالأول: أن كونه عالما بالشيء نسبة بينه وبين ذلك الشيء فتلك النسبة غير ذاته لا محالة، والموصوف بها والمقتضى لها هو ذاته تعالى، فيكون الشيء الواحد قابلا وفاعلا معا وهو محال. أما أولا فلأن البسيط لا يصدر عنه إلا أثر واحد. وأما ثانيا فلأن نسبة القبول بالإمكان ونسبة التأثير بالوجوب، والنسبة الواحدة لا تكون بالامكان والوجوب معا.\rالثانى أن العلم ان لم يكن صفة كمال وجب تنزيه الله تعالى عنه. وان كان صفة كمال كان الله تعالى محتاجا فى استفادة الكمال\r__________________\r2 ـ اللاذكياء: ق ج ل ك، اذ لاكياء: ت، الازكياء: م. لشيء: ا ت ج ك ي، بشيء: ف ق ل م، علم ولا حكمة: ك م، حكمة ولا علم: ف ج لب ل ي، لا علم ولا حكمة: ق، حكمة ولا نحكم علما: ت.\r3 ـ ولئن: ت ف ك م، وان: ق ي، ان: ت ف ج ك ق م، لان: ا، ذكرته: ت ق لب ك م، ذكرتم: ف، ذكرتموه: ي ج، كونه: ت ج ف ك م، ان الله: ق ي، عالما، ت ج ك م، عالم: ق.\r5 ـ الاول: ت ف ق ك لب م ي، ا: ا، احدهما: ج، بالشيء: ت ج ك ل م، شيء: ف ق لب ي.\r6 ـ لها: ف.\r7 ـ وفاعلا: ج ق م، فاعلا: ت ل ك، معا: ا ج ف ق ل ك، ت لب م ي.\r8 ـ عنه: ت ج ف ق ك لب م ي، منه: ا، فلان: ت ج ف ق ك لب ي، فان: م.\r11 ـ الثاني: ت ف ج ق ك لب م ي، ب: ا، فنزه: لب ي.\r12 ـ كان (2): ت ج ق ك لب م ي، لكان: ف، استفادة: ت ج ف ق ك لب م، اسعادة: ي."], [389, "إلى تلك الصفة. والكامل بغيره ناقص بذاته، والمحتاج إلى الغير ناقص أيضا لذاته. وذلك على الله تعالى محال.\rوالجواب أما الكلام فى الواسطة فقد تقدم، وأما الاحكام، فالمراد منه الترتيب العجيب، والتأليف اللطيف. ولا شك ان العالم كذلك.\rقوله: إذا جاز صدور الفعل المحكم عن الجاهل مرة واحدة فليجز مرارا كثيرة.\rقلنا بديهة العقل بعد الاستقراء شاهدة بالفرق.\rوأما الحيوانات فكل من فعل منها فعلا محكما فهو عالم بذلك الفعل فقط.\rوأما المعارضة الأولى فجوابها لم لا يجوز كون الشيء الواحد قابلا ومؤثرا؟.\rوقوله: الواحد لا يكون مصدرا لأثرين قلنا قد تقدم ابطاله.\r__________________\r1 ـ بغيره: ج ك م، بغير: ت، بذاته: ت ج ق ك لب م ي، لذاته: ا ل ف.\r2 ـ ايضا لذاته: ا ت ج ق ك لب ي، لذاته ايضا: م، ايضا: ف.\r3 ـ الجواب: ف.\r4 ـ شك: ا ت ج ف ك لب ي، يشك: ق م.\r6 ـ المحكم: ف.\r7 ـ فليجز: ج ف ق ل م، فلنجوز: ك لب ي، فليجر: ت، مرات: ك.\r9 ـ الحيوانيات: ق، من: ت ج ف ك لب م، ما: ق ي، منها: ت ج ف ق ك لب ي: م.\r11 ـ كون: ت ق ك لب م ي، ان يكون: ج ف.\r12 ـ ومؤثرا: ت ك لب ل م ي، ومؤثر: ا، مؤثرا: ق، فاعلا معا: ج ف.\r13 ـ وقوله: ت لب، قوله: ج ف ق ك م ي، الواحد .. قد: ق ك ابطاله: ت ج ق ك لب م، قد تقدم ابطاله: ف."], [390, "قوله: النسبة الواحدة لا تكون بالإمكان والوجوب معا. قلنا نسبة القبول بالامكان العام وهو لا ينافى نسبة الوجوب.\rوأما حديث الكمال والنقصان فخطابى، وهو معارض بما تقرر فى بداية العقول أن صفة العلم صفة كمال، والجهل صفة نقصان وتعالى الله عن النقصان وهو الموفق.\rمسئلة:\rاتفق العقلاء على أنه تعالى حي لكنهم اختلفوا فى معنى كونه حيا فذهب الجمهور من الفلاسفة، ومن المعتزلة أبو الحسين البصرى إلى أن معناه هو أنه لا يستحيل أن يكون عالما قادرا، فليس هناك إلا الذات المستلزمة لانتفاء الامتناع.\rوذهب الجمهور من أصحابنا ومن المعتزلة إلى أنه صفة. احتج أصحابنا بأنه لو لا اختصاص ذاته بما لأجله صح أن يعلم ويقدر،\r__________________\rلاترين: ك م، الاثر: ت ل.\r2 ـ فخطابي: ت ج ق ك لب م ي، فخطا: ف، وهو: ت ق م، وهي: ا ك ل: ج ف لب ي.\r4 ـ بداية العقول: ج، البداية: ت ل م، صفة (1): ف ج، صفة الجهل: ق.\r5 ـ تعالى الله عن النقصان: ت ج ق ك ل م ي، تعالى الله علوا كبيرا: ف، الله تعالى منزه: لب، وهو الموفق: ا، ت ج ف ق ك لب م ي.\r7 ـ اتفق: ت ج ق ك لب ل م ي، انتهوا: ف، تعالى: ا ف، ت ق ك لب م ي.\r8 ـ من: ق.\r9 ـ انه: ت م، الذي: ق، قادرا عالما: ك.\r8، 10 ـ ومن المعتزلة .. الامتناع: ت ج ف ق ك لب م، اني انه انتفاء للامتناع: ي.\r10 ـ الذات المتستلزمة: ك م، ذات مستلزمة: ت ج.\r11 ـ من اصحابنا: ت ج ل ف ق، منا: ك م.\r12 ـ بما لاجله: ا ت ف ج ق ك لب ي، لاصله: م."], [391, "وإلا لم يكن حصول هذه الصحة له أولى من لا حصولها.\rولقائل أن يقول لم لا يجوز أن تكون حقيقته المخصوصة كافية فى هذه الصحة؟ والأقوى أن يقال الامتناع أمر عدمى لما تقدم بيانه مرارا. فعدم الامتناع يكون عدما للعدم فيكون ثبوتيا.\rمسئلة:\rاتفق المسلمون على أنه تعالى مريد لكنهم اختلفوا فى معناه، فذهب أبو الحسين البصرى إلى أن معناه: علمه بما فى الفعل من المصلحة الداعية إلى الإيجاد. وعن النجار ان معناه أنه تعالى غير مغلوب ولا مستكره. وعن الكعبى أن معناه فى أفعال نفسه. كونه عالما بها، وفى أفعال غيره كونه آمرا بها.\rوعندنا وعند أبى على وأبى هاشم انه صفة زائدة على العلم. لنا أن حصول أفعاله تعالى فى أوقات معينة مع جواز حصولها قبلها. وبعدها يستدعى مخصصا. وليس هو القدرة لأن شأنها الايجاد الّذي نسبته إلى كل الأوقات على السواء، ولا العلم لأنه تابع\r__________________\r1 ـ له: ت ق ل لب، لها: ج، ف ك م ي.\r2 ـ حقيقته: ج ق ك لب م ي، حقيقة: ا ت ف، الخصوصية ف.\r3 ـ لما: ت ج ف ل م، كما: ق ي.\r4 ـ فعدم: ت ج ق ك لب م ي، لعدم: ف، ثبوتا: ت.\r8 ـ الى الايجاد: ت ج ف ق ك لب ل م ي، للايجاد: ا. النجار: ا تج ف ق ك ل لب ي، البخاري: م، تعالى: ف.\r9 ـ و (1): ا.\r10 ـ بها (1): ي، بهما: ي.\r11 ـ وعندنا: ت ج ق ك لب م ي: ا ف، انه: ت ف ج ق ك لب ي، انها: ل: م.\r12 ـ ان: ت ج ف م ل،: ا.\r13 ـ و (1): ا ت ج ق ك لب ل ي، الو: م، لان: ت ج ق ك لب ل م ي، الان من: ف.\r14 ـ السوية: ف، لانه: ت ف ج ق ك لب ل م ي، فانه: ا."], [392, "للمعلوم. فلا يكون مستتبعا له لامتناع الدور. وظاهر ان سائر الصفات لا يصلح لذلك سوى الإرادة. فلا بد من اثباتها.\rفإن قيل لا نسلم جواز حصول أفعال الله تعالى قبل أن حصل وبعده. ولم لا يجوز أن يقال لا امكان لها إلا فى ذلك الزمان المعين والدليل عليه وهو أن المفهوم من حصوله فى ذلك الزمان ليس أمرا سلبيا لأنه نقيض اللاحصول فيه ولا نفس الذات وإلا لكان متى بطل حصوله فى ذلك الزمان، وجب أن يبطل الذات فهو إذن صفة زائدة على الذات لكن هذه الصفة يستحيل حصولها إلا فى ذلك الزمان، لأن الصفة المسماة بالحصول فى ذلك الزمان لو حصلت فى زمان آخر، لم يكن الحصول فى ذلك الزمان حصولا فى ذلك الزمان، فاذن امكان حدوث هذه الصفة مختص بهذا الوقت، فاذا عقل هاهنا، فلم لا يعقل فى غيره؟.\rلا يقال الإمكان من لوازم الماهية فيدوم بدوام الماهية لأنا نقول\r__________________\r2 ـ لذلك: ج ك ل م، كذلك: ت.\r3 ـ افعال: ا ت ج ف ق ك لب ل ي، م. تعالى: ت لب، حصل: ت ج ف ك لب ل م، حصلت: ق ي.\r4 ـ لم: ق، الا في: ت ج ف ق ك لب ل م ي، في الافي: ا.\r5 ـ وهو: ك ل م، هو: ق.\r5، 6 ـ ليس امرا .. فيه: ق ل لب .. متى: ف ق لب ك ل: ا ف ق ك لب ل: م.\r7 ـ وجب .. الذات: بطلت: ل، تمو اذن: ف ك لب ل م، فاذن هو: ا.\r8، 9 ـ لان .. بالحصول في: فيه .. حصولا في ذلك الزمان: ا ف ق ك لب ل، م.\r11 ـ ههنا: ف ق ك، هنا: م، فلم: لا: م، لم: ك.\r5، 12 ـ الدليل عليه ... في غيره: ت ج ي.\r13 ـ لا يقال: ت ف ل لب ج هامش، فان قلت: ق ج ك م، فيدوم فيلزم دوامه: ف لب ... لان: ت ف لب ل ي،"], [393, "هذا إنما يصح لو كانت الماهية متقررة قبل وجودها، لكن ذلك باطل، لأنه بناء على أن الماهية متقررة حال عدمها، وهو قول بأن المعدوم شيء، وهو باطل.\rسلمنا ذلك لكن لم لا يجوز أن يقال الماهية بشرط حصولها فى هذا الوقت، يقتضي الإمكان، وبشرط حصولها فى وقت آخر، يقتضي الامتناع، كما أن الطبيعة الأرضية بشرط حصولها فى المركز يقتضي السكون وبشرط حصولها فى الهواء يقتضي الحركة.\rسلمنا الإمكان، لكن لم لا يجوز أن يقال الله تعالى خلق الأفلاك، وخلق فيها طباعا محركة لها لذواتها. ثم ان بسببها تتولد هذه الحوادث فى عالمنا هذا.\rوإذا كانت الحوادث العنصرية مرتبطة بالاتصالات الفلكية ثم للاتصالات الفلكية مناهج معينة يمتنع فيها تقدم المتأخر وتأخر المتقدم، كانت الحوادث العنصرية كذلك وحينئذ لا حاجة لها إلى\r__________________\rفيدوم بدوامها قلت ينتقض بما ذكرنا لم: ق ك م، فيدوم بدوام الماهية قلت تم: ج.\r1 ـ لو: ت ج ق لب ك م ل ي، ان لو: ف، متقررة: ت ج ف ق ك لب ل م، مقررة: ا، قد تقررت: ي.\r4 ـ لكن: ت ج م، ولكن: ق: ك بشرط: ا ت ج ق، شرط: ك ي.\r5 ـ هذا: ت ج م، ذلك: ق ك، بشرط: ا ت ج ق ل، وشرط: ك م.\r5، 6 ـ في وقت آخر ... حصولها (1): ف.\r6، 7 ـ في المركز .. حصولها (2): ي.\r8 ـ لكن لم: ت ج ف ق لب ي، فلم: ك م.\r10 ـ عالمنا: ك م، علمنا: ت، هذا: ا.\r11 ـ واذا: ت ق م، وان: ك.\r11، 12 ـ ثم للاتصالات الفلكية: ا ق ج لب، ثم الاتصالات الفلكية: ت ل ف ك، ثم للاتصالات: ي، لها: ك م.\r13 ـ كانت: ت ق م، فكانت: ك."], [394, "المخصص.\rفإن قلت فلم خلق العالم فى الوقت المعين وما خلقه قبل ذلك ولا بعده.\rقلت هذا إنما يصح لو كان قبل خلق الفلك وقت وزمان، وذلك محال بالاتفاق. أما عند الفلاسفة فلأن الزمان مقدار حركة معدل النهار، فقبل وجودها لا يمكن وجود الزمان.\rوأما عند المسلمين، فلأن الزمان محدث وإذا كان كذلك، فقبل الخلق لا زمان، فيستحيل أن يقال لم لم يخلقه فى زمان آخر.\rسلمنا أنه لا بد من مخصص فلم لا تكفى القدرة.\rقوله: نسبتها إلى الكل على السواء.\rقلنا والإرادة أيضا نسبتها إلى الكل على السواء فلتفتقر الإرادة إلى إرادة أخرى، لا إلى نهاية.\rفإن قلت الإرادة القديمة كانت على صفة لأجلها يجب تعلقها بإحداث الحادث المعين فى الوقت المعين، ويستحيل تعلقها باحداث ذلك الحادث فى وقت آخر، قلت لو كان الأمر كذلك لم يكن الله\r__________________\r(13/ 393، ا) لها الى المخصص: ج ك ف، لها الى المخصوص: ت، بها الى المخصص: ق ل م.\r2 ـ خلقة: ت ق ك لب ج م ي، خلق: ف، ذلك: ف.\r3 ـ خلق: ت.\r8 ـ الخلق: ت ج ق ك لب م ي، خلق الزمان: ف، لم (1): ت، لم يخلقه: ت ج ق ك لب م ي، لا يجعله: ف.\r9 ـ سلمنا انه ... القدرة: ف.\r10 ـ الكل: ت ج ق ك لب م ي، كل الاوقات: ف.\r14 ـ الارادة (2): ت ج ك ل م، المادة: ق.\r11 ـ الحادث: ت ج ف ق ك لب م ي، الحوادث: ا، و: ق.\r15 ـ الامر: ت ج ف ي."], [395, "تعالى بالحقيقة مختارا بل كان موجبا بالذات وهو قول الفلاسفة وأيضا فإن جاز ذلك فلم لا يجوز أن يقال قدرة الله تعالى كانت على صفة لأجلها يجب تعلقها بايجاد الحادث المعين فى الوقت المعين ويستحيل تعلقها بايجاده فى وقت آخر. وعلى هذا التقدير تستغنى القدرة عن الإرادة.\rسلمنا أن القدرة غير صالحة لذلك، فلم لا يكفى العلم.\rبيانه من وجهين:\rالأول: ان الله تعالى عالم بجميع المعلومات فيكون عالما بما فيها من المصالح والمفاسد. والعلم باشتمال الفعل على المصلحة، أو المفسدة مستقل بالدعاء إلى الإيجاد والترك بدليل أنا متى علمنا فى الفعل مصلحة خالية عن المضار، دعانا ذلك العلم إلى العمل، بل اسناد الترجيح إلى هذا العلم أولى من اسناده إلى الإرادة. فإن الله تعالى لو أوقف المكلف على شفير جهنم وخلق فيه علما بما فى دخول النار من\r__________________\r(15/ 394 ـ 1) سلم يكن .. مختار: ت .. بالذات: ت ج ق ك ل م، لكان الله تعالى موجبا بالذات لا فاعلا مختارا: ف، لكان موجبا بالذات: ي، كان موجبا بالذات: لب.\r2 ـ وايضا فان: ت ق م، وان: ك، تعالى: ا ت ف ق ك لب ي، م.\r4 ـ هذا التقدير: ت ج ق ل م، هذين التقديرين: ك.\r5 ـ الارادة: ت ج ق ك ف لب م ي، الازل: م.\r6 ـ لا يكفى: ت ج ق م، لا يجوز ان يكفى: ك.\r8 ـ الاول: ت ف ق ك لب ي، احدهما: ج م، ا: ا.\r9 ـ او: ت، و: ك م ج ل.\r10 ـ الى الايجاد: ت ج ف ق ك لب م، للايجاد: ا، ان الايجاد: ي.\r11 ـ بل اسناد: ت ج ف ك ل م، بل استنادا: لب ي، استناد: ف.\r12 ـ العلم: ت ج ف ق ك لب ل ي، الفعل م.\r13 ـ لو: ا ت ج ف ق ك لب ل ي: م، الكلف: ت ف ك ج لب ل ي، تكرر في: ق: م، علما: ت ج ق ك لب م ي."], [396, "المضار، وخلق فيه إرادة دخول النار فانه لا يدخل النار ولأجل ذلك قد نريد الشيء إرادة قوية وتتركه لعلمنا بما فيه من المفسدة.\rالثانى: وهو أن الله تعالى عالم بجميع الأشياء، فيعلم أيها يقع وأيها لا يقع. ووجود ما علم الله تعالى عدمه محال، وبالعكس. فلا جرم يوجد ما علم الله تعالى وجوده، فكان ذلك كافيا فى التخصيص.\rسلمنا أن ما ذكرتم يدل على قولك، فمعنا ما يبطله، وهو أن المريد اما أن يريد لغرض أو لا لغرض. فان كان لغرض كان مستكملا بذلك الغرض والمستكمل بالغير ناقص بالذات، وهو على\r__________________\rارادة دخول النار وخلق فيه علما: ف.\r1 ـ فيه: ا ت ج ق ك لب ي، منهم: م، دخول: ا ت ج ق ك لب م ي، وصول: م، فانه لا: ا ت ج ق ك لب ل ي، فلا: م، وثلق .. انار: ف لب، ولاجل: ت ف ق ج ك لب ي، فلاجل: ل م.\r2 ـ نريد .. نتركه: ق ك لب ج م ي، نريد .. نتركه: ا، يريد ... يتركه: ت.\r3 ـ الثاني: ت ج ف ق ك لب م ي، ب: ا، ان الله تعالى: ت ج ق ك لب م ي، انه ف. فيعلم: ت ج ق ك ي، فعلم: ا، فيعلم، ان: لب م، فيكون عالما بان: ف، ايها: ت ج ف لب م، انها: ا، انها: ق، ما: ك ي.\r3، 4 ـ يقع وايها: ت.\r4 ـ ايها: م، ما: ك، انها: ق، منها: ف.\r5 ـ الله تعالى: ف: ت ج ق ا م، فكان: ت ج ق ك م ي، وكان: ا ل، لكان: ف.\r7 ـ ذكرتم: ف ق، ذكرتموه: ل، ما: ت ج، ما ذكرته: ك لب م، معك ما: ي: قولك: ا ت ج ك لب ي، قولكم: ف ل ق، ذلك: م، فمعنا: ت ج ف لب ي، لكن معنا: ق ك ل م.\r8 ـ المريد للشيء: ف، يريده: ف، لغرض (1): ت ج ف ك لب م، الغرض: ا.\r9 ـ ناقص: ت ج ق ك لب ي، ناقض: م، بالذات: ت ج ف ك لب م، الذات: ي."], [397, "الله تعالى محال. وان كان لا لغرض كان ذلك عبثا، والعبث على الله تعالى محال.\rوالجواب أن الجسم الموصوف بالحركة، كان يمكن أن يصير موصوفا بها قبل ذلك الوقت والمحكوم عليه بهذا الإمكان ليس هو المعدوم، بل الجسم الموجود.\rقوله: يجوز أن يكون ممكنا فى وقت وممتنعا فى وقت آخر.\rقلنا: الوقت إن لم يكن موجودا استحال أن يكون له أثر. وإن كان موجودا كان الكلام فيه كما فى الأول.\rقوله هذه الحوادث مستندة إلى الاتصالات الفلكية.\rقلنا سنقيم الدلالة على أن جميع الممكنات واقع بقدرة الله تعالى.\rأما المعارضة بنفس الإرادة فقوية وجوابها أن مفهوم كون الشيء\r__________________\r1 ـ ان: ا ت ج ل ف ق ك لب، اذا: م، العبث: ت ج ف ك ل لب، هو: ق م.\r1، 2 ـ وان .. محال: ي.\r2 ـ تعالى: ت ج محال: ا ..\r3 ـ والجواب: ت ج ف ك ي، ولانه يقتض ترجيح احد طرفى الممكن وهو محال والجواب: ق لب ل م مشطوب في: ك.\r4 ـ بها: ت ج، الوقت: ف، بهذا: ت ج ق ك لب ل م ي، لهذا: ف، هو: ق.\r5 ـ بل، ت ج ف لب ي، بل هو: ق ك م.\r6 ـ و: ت ق ك ل، م ج.\r7 ـ قلنا: ا ت ج ف ق ك لب ي، قلت: م، الوقت: ا، ان (1، 2): ت ج ق ك لب م ي، ف: ف.\r8 ـ فيه: ا ت ف ق ك لب ي: م.\r10 ـ مستقيم: ا ت ج ف ق ك لب ي، تستقيم: م، واقع: ت ج ق م، واقعة: ك.\r11 ـ واما: في: ق، كون: ف."], [398, "مرجحا غير مفهوم كونه مؤثرا، وذلك يوجب الفرق بين القدرة والإرادة ويتوجه عليه أن المفهوم من كونه عالما بهذا السواد غير المفهوم من كونه عالما بذلك السواد. فيلزم أن يكون له بحسب كل معلوم علم. وقد التزمه الأستاذ أبو سهل الصعلوكى منا وهذا الوجه ليس ببعيد.\rقوله: لم لا يكفى علمه تعالى بما فى الأفعال من المصالح والمفاسد.\rقلنا سنقيم الدلالة على أن أفعال الله تعالى لا يجوز تعليلها بالمصالح.\rقوله: إنما يوجد ما علم الله تعالى أنه يوجد.\rقلنا العلم بأن الشيء سيوجد تابع لكونه بحيث سيوجد فكونه بحيث: سيوجد، لو كان لأجل ذلك العلم، لزم الدور، بل لا بد من\r__________________\r1 ـ الارادة والقدرة: في: ك.\r2 ـ بذلك: ت ك م، بذاك: ق، السواد: ت ج ف ق ك لب ق: م.\r3 ـ ضم وفقد: ت ج ف ق ك ي، علم وقدرة وقد: ا، علما فقل: ل، علما وقد: م.\r4 ـ وهذا: ا ت ج ف ق ك لب ي، وهو: م.\r5 ـ ببعيد: ا ق لب ي، بعيدا: ق ج، بعيد: ف ك، الا بعيد: ل.\r6 ـ تولهم: في: ي.\r8 ـ سنقيم: ا ت ج ف ق ك لب ي، نستقيم: م، افعال الله: ا ت ج ف ق ك لب ي، افعاله: م، تعليلها: ا ت ج ف ق ك لب ي، تعليقها: م.\r10 ـ يوجد ما: ف ق م، وجد ما: ت، تكرر في: ل، وجدها ك، وجدنا: ا، وجد الشيء لان ما: ج، انه يوجد: ت ج ك لب ل م ي، وجوده: ف.\r11 ـ الشيء: ك ج م، الذي: ت ل.\r11، 12 ـ فكونه وكونه: ي، لكونه: ل يوجد: ت ج ف ق لب ل م ي، فكونه بحيث يوجد: ك: ا.\r12 ـ بد فيه: في: ق."], [399, "صفة أخرى.\rقوله: المريد إما أن يرجح لغرض أو لا لغرض.\rقلنا إرادة الله تعالى منزهة عن الأغراض، بل هى واجبة التعلق بايجاد ذلك الشيء فى ذلك الوقت لذاتها. وبالله التوفيق.\rمسئلة:\rاتفق المسلمون على أنه تعالى سميع بصير لعلمهم اختلفوا فى معناه. فقالت الفلاسفة، والكعبى، وأبو الحسين البصرى: ذلك عبارة عن علمه تعالى بالمسموعات والمبصرات. وقال الجمهور منا، ومن المعتزلة، والكرامية انهما صفتان زائدتان على العلم.\rلنا أنه تعالى حي والحى يصح اتصافه بالسمع والبصر. وكل من صح اتصافه بصفة، فلو لم يتصف بها اتصف بضدها، فلو لم يكن الله تعالى سميعا بصيرا، كان موصوفا بضدهما وضدهما نقص\r__________________\r2 ـ المريد: ت ج ك لب م ي، المدبر: ف، اما ان: ت ج ك م، ان: ق ل.\r2 ـ منزهة: ق ف ل لب ي، صفة منزهة: ك، متنزهة: ت ج، منزه: م، واجبة: ا ت ج ف ل ق ك لب ي، واجب به: م.\r4 ـ الشيء: ا ت ق ك لب ج ل ي، ف م، وبالله التوفيق: ا ق ل ك: ت ف لب م ي.\r6 ـ المسلمون: ت ف ق لب ك ج ل م، المتكلمون: ا، العقلاء: ي تعالى: ا ت ف ق ج ك لب ي: م.\r7 ـ فقالت: ق ك لب ل م ي، وقالت: ت ج، قالت: ف، ان ذلك: في ف.\r8 ـ علمه تعالى: ت ل ف ق ك م، علم الله تعالى: لب، علمه: ج ي، بالمبصرات والمسموعات: في ك، وقال: ت ج ك ل م، ففال: ق.\r9 ـ من: ا لب. على: ت ج ف ق ك لب م ي، علم: ا.\r10 ـ يصح: ت ج ل م، يصلح: ك، والبصر: ت ج.\r11 ـ وكل: ت ج ف ق لب ل م ي، فكل: ا ك.\r12 ـ كان الله تعالى: في ك."], [400, "والنقص على الله تعالى محال.\rفإن قيل: حياة الله تعالى مخالفة لحياتنا. والمختلفان لا يجب اشتراكهما فى جميع الأحكام، فلا يلزم من كون حياتنا مصححة للسمع والبصر، كون حياته كذلك.\rسلمنا ذلك، لكن لم لا يجوز أن يقال حياته تعالى وان صححت السمع والبصر، لكن ماهيته تعالى غير قابلة لهما، فامتنع ثبوتهما كما أن الحياة وان صححت الشهوة والنفرة ولكن ماهيته تعالى غير قابلة لهما فامتنع ثبوتهما فكذلك هاهنا.\rسلمنا ان ذاته تعالى قابلة لهما، لكن لم لا يجوز أن يكون حصولها موقوفا على شرط ممتنع التحقق فى ذات الله تعالى. وهذا هو قول الفلاسفة. فإن عندهم إبصار الشيء مشروط بانطباع صورة صغيرة مشابهة لذلك المرئى فى الرطوبة الجليدية. وإذا كان\r__________________\r1 ـ والنقص: ت ج ق ك لب ل م ي، وهو: ف.\r2 ـ فان قيل: ا ت ج ف ق ك لب ل ي، فلقائل ان يقول: م، نقلى: ا، المختلفان: ت ق ك ل ف، المختلفات: ج م، ان يجب: ت ج ك ل ف، لا يجوز: م.\r3 ـ اعتراكهما: ا ت ف ق ك ل لب ي، اشتراكها: ج م.\r5 ـ تعالى: ت ج ف ق لب ل ي، ك م.\r6 ـ ماهيته: ت ج ل م، ذاته: ق، تعالى: ا ق: ت ج ك ب ل م ي، لهما: ج ك ل م، لها: ت، فامتنع ثبوتهما: لب، ف ت ف ك م ي.\r7 ـ ولكن: ج ف ق لب، لكن: ك ل م ي، ماهيته: ت ج ك ل م، ماهية ذاته: ق ل.\r8 ـ فامتنع ثبوتهما: ف: ق ك لب م ي، فكذالك: ق ب ن وكذلك: ت لب، فكذا: ج ك، ههنا: ا ت ق ك لب ي، ج ف ل، لهما: م.\r5، 8 ـ كما ان ... فامتنع ثبوتهما: ت.\r10 ـ التحقق: ت ج ق ك ل ي، التحقيق: لب م، ف.\r11 ـ هو: ت ج ف ق ك لب ل ي، م.\r12 ـ مشابهة: ت ج ق ك لب م ي، متساوية: ف."], [401, "ذلك فى حق الله تعالى ممتنعا لا جرم لم تثبت الصحة.\rسلمنا حصول الصحة. لكن لم قلت أن القابل للصفة يستحيل خلوه عنها وعن ضدها معا. وقد تقدم تقريره.\rسلمنا ذلك لكن ما المعنى بالنقص. ثم لم قلت أن النقص على الله تعالى محال فإن رجعوا فيه إلى الإجماع صارت الدلالة سمعية وإذا كان الدليل على حقيقة الإجماع هو الآية والآيات الدالة على السمعية والبصرية، أظهر دلالة من الآيات الدالة على صحة الاجماع، كان الرجوع فى هذه المسألة إلى التمسك بالآية أولى. فالمعتمد التمسك بالآيات.\rولا شك أن لفظ السمع والبصر ليس حقيقة فى العلم بل مجاز\r__________________\r1 ـ تعالى ممتنعا: ا ت ج ق ك لب ل ي، تعالى محال: ف، محالا: م، لم تثبت: ت ج ك ل م، لا تثبت: ق.\r2 ـ قلت: ت ج ك م، قلتم: ق ل.\r3 ـ خلوه: ت ج ف ك لب ل م، خلعه: ي، تقدم: ج ق ك ل م، سبق: ف ت لب ي.\r4 ـ قلتم: في ق.\r4، 5 ـ على الله تعالى: ف ق: ت ج ك لب ل م ي.\r5 ـ رجعوا: ت ف ق م، كان الرجوع: ك، راجعوا: ج، رجعت: ل، سمعية: ا ت ج ف ك لب ي، السمعية: ق، فيسمه سمعية: م.\r6 ـ واذا: ت ج ف ك ل م، فاذا: لب، وان: ي، كان كذلك وكان: في ف، حقيقة: ت ق ك لب ل م، حقبة: ج ف، صحة: ك ي: هامش، هو الاية و: ت ج ف ك لب ي، هو الاية والخبر و: ق ل، وهو: م، ا.\r7 ـ دلالة: ت ف ق لب ج ي ل: ك م.\r8 ـ كان: ت ج ف ق ك لب ي، فكان: م، بالاية: ت ف ج ق ل ك م، بالايات: لب.\r8، 9 ـ فالمعتمد التمسك بالايات بالاية: ل: ت ج ق ك ل م ي، من التمسك بالايات: ف: لب.\r10 ـ ان: ت ج ق ل م، بان: ك، مجاز: ت ج ف ل م،"], [402, "فيه. وصرف اللفظ عن الحقيقة إلى المجاز لا يجوز إلا عند قيام المعارض. وحينئذ يصير الخصم محتاجا إلى إقامة الدلالة على امتناع اتصافه تعالى بالسمع والبصر.\rومن الأصحاب من قال السميع والبصير أكمل ممن ليس بسميع ولا بصير. والواحد منا سميع بصير، فلو لم يكن الله تعالى كذلك، لكان الواحد منا أكمل من الله تعالى، وهو محال.\rوهذا ضعيف لأن لقائل أن يقول الماشى أكمل ممن لا يمشى، والحسن الوجه أكمل من قبيح الوجه. والواحد منا موصوف به فلو لم يكن الله تعالى موصوفا به لزم أن يكون الواحد منا أكمل من الله تعالى.\rفإن قلت المشى صفة كمال فى الأجسام، والله تعالى ليس بجسم فلا يتصور ثبوته فى حقه.\rقلت فلم قلت ان السمع والبصر ليسا من صفات الأجسام وحينئذ\r__________________\rمجازا: ق ك.\r1 ـ قيام: ت ج ف ل ق لب ي، ك م.\r2 ـ الدلالة: ا ت ق ك لب ج ي، الدليل: م.\r3 ـ تعالى: ا.\r(10/ 401)، 3 ـ ليس حقيقة ... والبصر: تكرر في ك.\r2، 3 ـ الخصم .. البصر: ف.\r5 ـ الله تعالى: ج ك.\r5، 6 ـ سميع بصير .. الواحد منا: ق.\r7 ـ لقائل: ت ج ف ق ك لب ل م ي، القائل: ا.\r8 ـ قبيح الوجه: ت ق ج ك لب ي، ممن هو قبيح الوجه: ف، من القبيح: م، من وجه القبيح: ل.\r11 ـ المشى: ت ج لب ل ي، حسن الوجه والمشي: ق، حسن الوجه وفبحه والمشى: ف، هذا: ك م، صفة: ق.\r13 ـ قامت (1): ت ج ف لب ل م ي، قلنا: ك، ولم: في ق ج، لم: ل، ان: ت ج ك ل، بان: ف م، ليسا: ق م، ليس: ت ج ك ل لب ي، ليستا: ف."], [403, "يعود البحث المذكور.\rمسئلة:\rاتفق المسلمون على اطلاق لفظ المتكلم على الله تعالى لكنهم اختلفوا فى معناه فزعمت المعتزلة ان معناه كونه تعالى موجد الأصوات دالة على معان مخصوصة فى أجسام مخصوصة. واعلم أنا لا ننازعهم فى المعنى لأنا نعتقد أن جميع الحوادث واقعة بقدرة الله تعالى. ونسلم أن خلق الأصوات فى الأجسام الجمادية والحيوانية جائز. وإذا ثبت ذلك فقد ساعدناهم على المعنى وبقى هاهنا النزاع فى أن اسم المتكلم هل وضع فى اللغة لهذا المعنى أم لا. وهذا بحث لغوى لا حظ للعقل فيه البتة والمتكلمون من الفريقين قد طولوا فيه ولا فائدة فيه.\rأما أصحابنا فقد اتفقوا على أنه تعالى ليس بمتكلم بالكلام الّذي هو الحروف والأصوات بل زعموا أنه متكلم بكلام النفس.\rوالمعتزلة ينكرون هذه الماهية وبتقدير الاعتراف بها ينكرون\r__________________\r1 ـ المذكور: ا ت ج ف ق ك لب ي: م.\r3 ـ ولكنهم: في م.\r7 ـ خلق: ت ج ق م، لخلق: ك.\r8 ـ ساعدناهم: ا ت ج ف ق ك لب ي، ساعدتهم: م، و (2) ك لب ي، ههنا: ت ق ك لب م ي، هنا: ا ج ف.\r9 ـ في ان: ا ت ج ف ق ك لب ي، اطلاق: م وضع: ا ت ج ف ق ك لب ل ي، يقع: م، و: ا.\r10 ـ بحث: ت ج ق ك، البحث: م، للعقل فيه البنة: ت ف ج ق ك لب ل ي، فيه البتة للعقل: ا، للعقل البتة فيه: م، قد: ت ج ف ي.\r12 ـ انه: ت ف ق ك لب ل ي، ان الله: ج م، تعالى: ق.\r12، 13 ـ بالكلام .. متكلم: ف.\r14 ـ ينكرون: ف، الاعتراف بها: ق م، ذلك: في ت ج، الاعتراف: ل."], [404, "اتصاف ذات الله تعالى بها وبتقدير ذلك ينكرون كونها قديمة وبتقدير ذلك ينكرون كونها واحدة. فالحاصل أن الّذي ذهبوا إليه فنحن من القائلين به، إلا أنا أثبتنا أمرا آخر، وهم ينازعوننا فى الماهية والوجود والقدم والوحدة، فهذه مقدمة لا بد من معرفتها للخائض فى هذه المسألة.\rواحتج الأصحاب على كونه تعالى متكلما بأمور:\rأحدها: إنه تعالى حي. والحى يصح اتصافه بالكلام. فلو لم يكن الله تعالى موصوفا بالكلام لكان موصوفا بضده، وهو نقص على الله تعالى وذلك محال.\rقالت المعتزلة التصديق مسبوق بالتصور: فما ماهية هذا الكلام؟ فإن الّذي نجده من أنفسنا ليس إلا هذه الحروف والأصوات أو تخيل هذه الحروف والأصوات وأنتم لا تثبتونها لله تعالى.\r__________________\r1 ـ ذات الله تعالى: ت بها: ا: ا ت ف ج ق ك ل ي، الذات بها: لب، ذات الباري: م.\r1، 2 ـ قديمة ... كونها: ا ت ج ف ق ك لب: م.\r2 ـ واحدة فالحاصل: ت ج ف ق ك لب ل م، قديمة والحاصل: ي.\r3 ـ ينازعون: ت ج ل.\r4 ـ القدم: ت ج م، العدم: ا ف ل ي.\r6 ـ واحتج: ت ج ل، الاصحاب: ت ق ج ل م ف، اصحابنا: ك.\r7 ـ احدها: ت ج ف ق ل ك لب م ي، ا: ا، تعالى: ف.\r7، 8 ـ فلو لم يكن الله تعالى موصوفا بالكلام: تكرر في: ق.\r8، 9 ـ وهو ... محال: ت ي، وضده نقص على الله تعالى وانه محال: ف، والنقص على الله تعالى محال: لب، وهو نقص وهو على الله تعالى محال: ق ك ل م، وهو نقص وذلك على الله محال: ج.\r10 ـ هذا: ت ج.\r11 ـ ليس الا: ت ج ق ل، اما: ك م، الا: ف لب ي.\r12 ـ تخيل: ا ت ج ل ف ق ك لب ي، يمثل: م."], [405, "فإن قلت أعنى بالأمر طلب الفعل. قلت لم لا يجوز أن يكون ذلك الطلب هو الإرادة. وأنتم حيث حاولتم الفرق بينه وبين الإرادة فقد قلتم الله تعالى قد يأمر بما لا يريد. لكن هذا الفرق إنما يثبت بعد ثبوت كونه تعالى متكلما، وذلك موقوف على تصور ماهية الكلام. فلو بنينا تصور ماهية الكلام عليه لزم الدور. ولئن نزلنا عن هذا المقام. لكن لم قلت: إنه يصح اتصاف ذات الله تعالى به.\rوتقريره بالوجوه الثلاثة المذكورة فى مسئلة السمع والبصر.\rسلمنا أنه يصح اتصافه به، لكن لم قلت ان ضده نقص وآفة، بل الّذي نعده نقصا وآفة فى العرف هو العجز عن التلفظ بالحروف.\rفأما ضد المعنى الّذي ذكرتموه فلم قلتم أنه نقص، بل لو قيل\r__________________\r1 ـ قلت لم: ق ل م ف ت، قلنا فلم: في ك، قلنا لم: ج.\r2، 3 ـ بينه وبين الارادة: ق ك م، بين الارادة وبينه: ت لب ج ي، بينها وبين الارادة: ا، بينهما: ف.\r3 ـ فقد: ا، يكون: م، مشطوب في: ك، ت ج ل، قد: ت ق م، ك.\r4 ـ تعالى: ت ج ق ك لب ل م ي، ف، موقوف: ت ج ف ق لب ل ي، يتوقف: ك م.\r5 ـ بنينا تصوير: ق تصور: ق ك، توقف تصور: ف لب، بينا تصور: ي، تصوير: ل، بتيم: ت، بنيتم تصور ج، بينا: م، عليه: ا ف ج ق ك لب ل ي، به: ت: م. ولئن: ك ج لب ل م ي، وليس: ت، وان: ق، سلمناه: ف.\r6 ـ نزلنا عن على: ق هذا المقام: ت ج ك لب م ي: ف، لكن لم قلت: ت ل ج ق ب م ي، لكن لم قلتم: ف، لم قلت: ك، ذات: ت.\r7 ـ به: ك م، بتلك الماهية: ت.\r9 ـ قلتم: في ف.\r10 ـ نعده: ك م، يعد: ت ج ل.\r11 ـ فاما: ا ت ج ف ق ك لب ي، واما: م، ذكرتموه: ت ج ف ق لب ي، ذكرته: ك م، قلتم: ق لب ل ي، قلت: ت ج م."], [406, "أن ذلك المعنى هو النقص لكان أقرب. فان ثبوت الأمر والنهى من غير حضور المخاطب سفه، وهو نقص وبقية الأسئلة هى التى تقدمت فى المسألة السابقة.\rوثانيها قالوا: لما علمنا أن أفعال الله تعالى يجوز عليها التقديم والتأخير. لا جرم أسندناها إلى مرجح وهو الإرادة.\rفكذلك رأينا أفعال العباد مترددة بين الحظر والاباحة والندب والوجوب. فاختصاصها بهذه الأحكام يستدعى مخصصا، وليس ذلك هو الإرادة، لأن الله تعالى قد يأمر بما لا يريد، وبالعكس فلا بد من صفة أخرى وهى الكلام. وهذا أيضا ضعيف لأنا نقول لم لا يجوز أن يكون معنى الوجوب والحظر هو أن الله تعالى عرف المكلف إنه يريد عقاب من يترك الفعل الفلانى فى الآخرة أو يريد ايصال الثواب إليه فى الآخرة. وهذا القدر مما لا حاجة فيه إلى اثبات الكلام.\r__________________\r1 ـ لكان: ك م، كان: ت ق ج ل، النهي والامر: في ف.\r2 ـ هي التي: ت ج ف لب ي، ما: ق ك: م.\r3 ـ في المسئلة السابقة السائقة: ج ق ك: ت ف لب ي ق ك، م.\r4 ـ وثانيها: ت ف ق ك لب م ي، الثاني: ج، ب: ا. قالوا: ت ج ف ق ك لب ي: م، عليها: ا ت ج ق ك لب ي، عليه: ف ل: م.\r4، 5 ـ التقديم والتاخير: التقدم والتاخر: ج ل.\r5 ـ مرجع: ت ج ق ك ل لب م ي، المرجح: ف، وهو: ك م، وهي: ت ج ل ف.\r7 ـ واختصاصها: في ق.\r9 ـ وهي: ت ق م، وهو: ك، وهذا: ا ت ج ف ق ك ل لب ي، وهو: م.\r10 ـ والحظر: ت ج ق ك لب م ي، او الحظر: ف، تعالى: ق.\r11 ـ في الاخرة: ك م، في اخره: ت.\r12 ـ حاجة ... الكلام: ا ق ك ي، حاجة اليه في اثبات الكلام: ت ج ل لب، حاجة الى اثبات الكلام فيه: م، خاصة اليه"], [407, "فإن ادعيت أمرا وراء ذلك فهو ممنوع.\rوثالثها: أن الله تعالى ملك مطاع، والمطاع هو الّذي له الأمر والنهى، وهو ضعيف جدا، لأنهم ان عنوا بالمطاع نفوذ قدرته ومشيئته فى المخلوقات فهو مسلم. وإن عنوا به أن له أمرا ونهيا فهو أول المسألة.\rورابعها: اجماع المسلمين على كونه متكلما، وهو ضعيف جدا لما بينا أن الاجماع ليس إلا على اللفظ. أما فى المعنى الّذي يقول به أصحابنا فهو غير مجمع عليه، بل لم يقل به أحد إلا أصحابنا والمعتمد قوله تعالى: (وَكَلَّمَ اللهُ مُوسى تَكْلِيماً).\rفإن قيل اسم الكلام موضوع فى اللغة لهذه الألفاظ. وأنتم لا تقولون بكونه تعالى موصوفا بالكلام بهذا المعنى فقد صرفتم اللفظ عن ظاهره. وإذا كان كذلك، لم يكن صرفه إلى المعنى الّذي ذكرتموه أولى من صرفه إلى معنى آخر، وهو الأمر الّذي به عرف الله تعالى ما يفعل بالمكلفين فى الآخرة من الثواب والعقاب ثم ان نزلنا\r__________________\rفي البات الكلام: ف.\r2 ـ ثالثها: ت ف ق ك ل لب م ي، الثالث: ج، ج: ا. ان: ت ج ك م، وهو ان: لب، تعالى: ي.\r4 ـ ان له: ت ج ق ك لب م ي: ف.\r6 ـ جدا: ت ج ق.\r7 ـ اجماع المسلمين: في ق، في: ت ك، ق م، به: ا ت ج ف ك ل لب ي: م.\r8 ـ فهو غير: ت ج ق ك لب ل م ي، فغير: ف.\r9 ـ سورة النساء: 164.\r10 ـ في اللغة موضوع: في ك ل.\r11 ـ تعالى: ق، صرفتم: ا ت ج ف ق ك لب ل ي، حرفتم: م.\r13 ـ به: ا ت ج ف ق ك ل لب ي: ا.\r14 ـ ثم ان نزلنا: ف ل ق ك م، ثم لئن نزلنا: ي، ولئن سلمنا ونزلنا: لب، ثم وليس نزلنا: ت، ثم ولئن نزلنا: ج."], [408, "عنه لكنه اثبات الكلام بالكلام واثبات الشيء بنفسه باطل والجواب ان صرفه إلى هذا المعنى أولى لقول الشاعر:\rان الكلام لفى الفؤاد وإنما ... جعل اللسان على الفؤاد دليلا\r\rوالجواب عن الثانى أنه إثبات كلام الله تعالى بإخبار الرسول عليه السلام والعلم بصدق الرسول لا يتوقف على العلم بكونه تعالى متكلما، لأنا مهما علمنا أنه لا يجوز ظهور المعجزة على يد الكاذب علمنا صدقه، سواء علمنا كلام الله تعالى أو لم نعلم. فهذا منتهى التقرير فى هذه المسألة والله أعلم.\rمسئلة:\rذهب أبو الحسن الأشعرى رضى الله عنه وأتباعه إلى أن الله سبحانه وتعالى باق ببقاء يقوم به. وذهب القاضى، وامام الحرمين إلى نفيه، وهو الحق.\r__________________\r1 ـ عنه: ت ج ق ك لب ل م ي، عن هذا المقام: ف، و (2): م.\r2 ـ لقول: ت ج ف ك ل م ي، لقوله: ق، بقول: لب الشاعر: ق.\r3 ـ ان: ت ج ف ق ك ل لب م ي، انما: ا.\r4 ـ الثاني: ت ج ل م، الباقي: ق، كلام: ت ج ف ق ك لب ل م ي، كلمة: ا.\r4، 5 ـ عليه السلام: ف ق.\r5 ـ بصدق: ت ج ك ل لب م ي، بتصديق: ف، تعالى: ق.\r6 ـ المعجزة: ت ج ك ل لب م ي، المعجز: ف يد: ت ج ف ق ك لب ي: م.\r7 ـ نعلم: ف ج ق لب ي، نعلمه: ك م، يعلم: ت.\r8 ـ التقرير: ت ج ف ك ل لب ي، القول: ق م، مشطوب في: ك، والله اعلم: ا، ت ف ق ك لب م ي.\r10 ـ رضي الله عنه: ت ل ي، رحمه الله: ج الى: ف.\r11 ـ سبحانه و: ف."], [409, "لنا المعقول من البقاء صفة تقتضى ترجيح الوجود على العدم وهذا إنما يعقل فى حق ممكن الوجود. فواجب الوجود لذاته يستحيل أن يكون رجحان وجوده على عدمه معللا بمعنى وأيضا فذلك البقاء لا شك أنه باق. فإن كان باقيا ببقاء آخر، لزم: اما التسلسل، أو الدور وان كان باقيا ببقاء الذات التى فرضناها باقية بذلك البقاء لزم الدور وان كان باقيا بنفسه، وتكون الذات باقية به مفتقرة إليه، وحينئذ انقلبت الذات صفة والصفة ذاتا وهو محال. وأما فى الشاهد، فليس بمعنى أيضا، لأن شرط حصوله فى الجوهر حصول الجوهر فى الزمان الثانى. فلو افتقر حصول الجوهر فى الزمان الثانى إليه، لزم الدور.\rولقائل أن يقول البقاء نفس حصول الجوهر فى الزمان الثانى، لا أنه أمر موقوف عليه. وجوابه أن نفس الحصول فى الزمان ليس صفة زائدة والا لزم التسلسل.\r__________________\r1، 2 ـ من البقاء .. هذا: م .. يعقل: ا ت ج ف ق ك لب م ي،: ف.\r2 ـ نواجب الوجود: ا.\r3 ـ بمعنى: لب.\r4، 5 ـ فان كان .. اما ت ج .. او واما: ق ك م: ت ق ك لب م ي، ف.\r5 ـ و: م.\r6 ـ البقاء لزم الدور: ت ج ف ق ك لب ل ي، لزم الدور: ا، البقاء: م.\r7 ـ به: ا ت ج ف ق ك ل لب ي: م، وحينئذ: لب.\r8 ـ بمعنى: ت ق ك ل م ي، لمعنى: ج ف ل.\r9 ـ الثاني: ت ف ق ك لب م ي، ا.\r11 ـ ولقائل ان يقول: ك م، لا يقال: ق.\r12 ـ امر: ف، وجوابه ان: ك م، لانا نقول ان: ق.\r13 ـ زائدة: ف.\r11، 12 ـ ولقائل ... التسلسل: ج ف ق ك لب م،: ت ل ي."], [410, "احتجوا بأن الذات لم تكن باقية حال الحدوث، ثم صارت باقية فوجب أن يكون البقاء زائدا عليه. والجواب بأنه معارض أن الذات كانت حادثة زمان الحدوث، ثم حال البقاء ما بقيت حادثة. فيلزم أن يكون الحدوث صفة زائدة، وهو محال على ما تقدم.\rفإن قلت الحدوث نفس حصوله فى الزمان الأول قلت البقاء نفس حصوله فى الزمان الثانى وبالله التوفيق.\rمسئلة:\rذهب أكثر المسلمين على أنه تعالى عالم بكل المعلومات خلافا للفلاسفة ولقوم من أهل الملة.\rلنا أن الله تعالى لكونه حيا يصح أن يكون عالما بكل المعلومات. فلو اختصت عالميته بالبعض دون البعض لافتقر إلى المخصص، وهو محال.\rومن الدهرية من زعم أنه لا يعلم ذاته لأن العلم أمر إضافى،\r__________________\r2 ـ عليه: ف لب، انه: ا ت ج ف ق ك لب ل ي، بانه: م.\r3 ـ فيلزم: ت ج ف ق ك لب م، فلزم: ي.\r4 ـ الحدوث: ف.\r5 ـ حصوله: ك م، الحصول: ت ج ل ف.\r6 ـ حصوله: ك م، الحصول: ت ج، وبالله التوفيق: ا ك ل.\r8 ـ ذهب: ف ل لب ي، مذهب: ق ك م، ت ج، على: ت ج، الى: ل ف، انه: ت ج ق ل ف م، ان الله: ك.\r9 ـ لقوم: ت ج ك م، بعض: ل.\r10 ـ ان الله: ت ف لب ي، انه: ج ل ق ك م.\r11 ـ لا افتقر: ق، المخصص: ج ف ق ك ل ي، مخصص: لب م، المخصوص: ت."], [411, "فلو علم ذاته لكانت ذاته مضافة إلى نفسه. واضافة الشيء إلى نفسه محال.\rفإن قلت ذاته تعالى من حيث إنه عالم مغاير له من حيث إنه معلوم، وهذا القدر من التغاير يكفى فى تحقق هذه الاضافة.\rقلت صيرورة الذات عالمة ومعلومة يتوقف على قيام العلم به وهو موقوف على المغايرة والمغايرة موقوفة على صيرورة الذات عالمة ومعلومة فيلزم الدور.\rجوابه إنه منقوض بعلمنا بأنفسنا.\rومنهم من سلم كونه تعالى عالما بنفسه ومنع كونه عالما بغيره. لأن العلم صورة مساوية للمعلوم فى العالم، أو إضافة مخصوصة بين العالم والمعلوم فلو علم الله تعالى الحقائق لحصلت تلك الصور أو تلك الإضافات فى ذاته تعالى فتحصل الكثرة فى ذاته.\rوالجواب أن الكثرة فى الصور أو الإضافات وهى من لوازم\r__________________\r1 ـ ذاته (1): ت ج ف ك ل لب م ي، ا، نفسه: ت ج ل ك م، ذاته: ق.\r3 ـ ذاته: ت ج ف ق ل لب م ي، ذات الله: ا.\r4 ـ تحقق: ج، صحة: ل: ت ك ف م.\r5 ـ به: ت ج ق لب ي، بها: ل ف م: ا ك.\r6 ـ والمغايرة: ت ج ف ك ل لب ي، فالمغايرة ان كانت: ق، التي هي: م.\r8 ـ وجوابه: في ج ق ك.\r9 ـ كونه (1): ت ج م، كون الباري: ل ق ك.\r10 ـ او: ا ت ج ف ق ك لب ل ي، و: م، بين: ا ت ج ق ك لب ل ي، في: م.\r11 ـ وبين المعلوم: في ل، ابو: ا ت ج ف ق ك لب ل ي: و: م.\r12 ـ الاضافات: ا.\r13 ـ والجواب: ت ج ك لب م ي، عن ذلك والجواب."], [412, "الذات لأنفسها.\rومنهم من زعم أنه لا يعلم الجزئيات لأنه لو علم كون زيد فى الدار فعند خروجه منها ان بقى العلم الأول كان جهلا وان لم يبق كان تغيرا.\rوالجواب أنك أن عنيت بالتغير وقوع التغير فى الأحوال الإضافية. فلم قلت إنه محال. ولذلك فإن الله تعالى كان قبلا لكل حادث ثم يصير معه ثم يصير بعده والتغير فى الاضافات لا يوجب تغير الذات فكذلك هاهنا كونه عالما بالمعلوم إضافة بين علمه وبين ذلك المعلوم فعند تغير المعلوم تتغير تلك الإضافة فقط.\rومنهم من زعم أنه لا يعلم الجزئيات إلا عند وقوعها وقبل ذلك فإنه لا يعلم إلا الماهية.\rواحتج عليه بوجهين:\r__________________\rالجواب: ف، او: ل ك، و: ت ج م، وهي: ا ك ج ل، هي: ت ف لب ي، وهو: م: ق، من: ت ج.\r1 ـ الذات: ت ج ق ك لب ل م ي، الماهية: ف.\r2 ـ منها: ا ت ج ف ق ك ل لب ي، عنها: م.\r5 ـ والجواب: ج ق ك ل م، الجواب: ت: ف لب ي، انك: ا.\r6 ـ الاضافية: ت ج ك ل م، الاضافة: ق، لذلك: ت ج ك، كذلك: ل م، قبلا لكل: ت ج ك ل لب م ي، قبل كل: ف ق، قبل: ا.\r7 ـ لم يصر: ق، والتفير: ت ج ك م، فلما كان تغيير القبل والبعد: ق، تغير: ا ت ج لب ي، تغيرا في: ل م، التغير ك ق ك.\r8 ـ فكل لك: ت ج ق، فكذا: ل ك م، ههنا: ا ت ج ف ك ق ل ي، هنا: لب م، بين (2): ا فقط.\r11 ـ فانه: ق.\r12 ـ عليه: ف فقط، بوجهين: ت ج ق ك م ي، لوجهين:"], [413, "الأول: ان المعلوم متميز والشخص قبل وجوده نفى محض، فلا يكون فى نفسه متميزا، فلا يصح أن يكون معلوما.\rالثانى: إنه تعالى لو علم الأشياء قبل وقوعها، وكل ما علم فهو واجب الوقوع. لأن عدم وقوعه يفضى الى انقلاب العلم جهلا، وهو محال. والمؤدى إلى المحال محال فعدم وقوعه محال. فوقوعه واجب وحينئذ يلزم الجبر وإن لا يتمكن الحيوان من فعل أصلا، بل يكون كالجماد، لأن ما علم وقوعه فهو واجب وما علم عدمه، فهو ممتنع.\rوالجواب عن الأول إنه منقوض بعلمنا بالمعدومات الشخصية قبل وقوعها، كعلمنا بطلوع الشمس غدا.\rوعن الثانى بالتزام ان ما علم الله تعالى وقوعه فهو واجب.\rومنهم من أنكر كونه عالما بما لا نهاية له واحتج عليه بثلاثة أوجه:\r__________________\rف لب، من وجهين: ل.\r1 ـ الاول: ت ف ق ك ل لب م ي، احدهما: ج، ا: ا، ان: ت، متحيزا: في ل، وجوده: ل.\r2 ـ الثاني: ت ج ف ق ك ل لب م ي، ب: ا: وكل ما علم: ت ج ل ق ي، وكل ما علم وقوعه: لب، وكل ما علم: ك م، وكل ما هو وقوعه معلوم: ف.\r4 ـ وذلك لان: في ف، عدم وقوعه: ج ك م، عدم الوقوع: ل، عدم وقوعه: ت.\r6 ـ الجبر: ا ج ف ق ك لب ي، الحيز: ل، الخبر: ت، الحيز: م، ان: ك، الحيوان: ت ج ك ل م، البعد: ق.\r7، 8 ـ لان ... ممتنع: ت ج ق ك ل لب م ي، لو وجب وقوع ما علم وقوعه وامتناع وقوع ما علم عدمه: ف.\r9 ـ و: ف، انه: ت فقط، بالمعدومات الشخصية: ت ج ك ل م: بالمعلومات الجزئية: ق.\r11 ـ بالزام: ف، تعالى: ا ت ج ي، واجب: ت ج ف ك ل لب ي، واجب الوقوع: ق م.\r13 ـ عليه: ج ف لب: ت ق ك ل م ي."], [414, "الأول ان المعلومات تتطرق إليها الزيادة والنقصان. فإن بعضها أقل من كلها. وما كان كذلك فهو متناه.\rالثانى ان كل ما كان معلوما فهو متميز عن غيره وكل ما كان متميزا عن غيره فغيره خارج عنه وكل ما كان غيره خارجا عنه فهو متناه. فالمعلوم متناه فما ليس بمتناه وجب أن لا يكون معلوما.\rالثالث أن العلم بكل معلوم يغاير العلم بغيره بدليل أنه يصح أن يعلم كون الشيء عالما بشيء مع الغفلة عن كونه عالما بشيء آخر والمعلوم غير المجهول، فلو كانت المعلومات غير متناهية، لكانت العلوم غير متناهية فهناك موجودات غير متناهية، وهو محال.\rوالجواب عن الأول ما تقدم أن تطرق الزيادة والنقصان إلى الشيء لا يدل على التناهى.\r__________________\r1 ـ الاول: ت ج ف ق ك ل لب م ي، ا: ا، احدها: و.\r2 ـ وما: ت ل ك، وكل ما: ق م ج.\r3 ـ الثاني: ت ج ك ل ي، فالمعلوم متناه الثاني: ق ك لب م، متناهية الثاني: ف.\r5 ـ ان كل ما كان ... خارجا خارج: ا لب .. فالمعلوم معلوم: ا .. ان لا يكون معلوما: ا: ا ل لب م، ان تميز عن غيره والتميز عن غيره فهو خارج عنه وكل ما كان منه فهو متناه فالمعلوم متناه: ف، ان المعلوم متميز عن غيره من غيره متناه فالمعلوم متناه: ت ج ك ي.\r6 ـ الثالث: نسخ، ج: ا، معلوم يغاير العلم: ا ت ج ف م لب ي، المعلوم مغاير للعلم: م.\r7 ـ الشيء: الشخص: في ج ق، بشيء: ت ج ق لب م ي، عن: ق، مع الجهل ب: ا، آخر مع الجهل ب: م، بشيء ت ج ف ق ك ل لب ي، بغيره: م.\r8، 9 ـ لكانت العلوم غير متناهية: لب.\r9 ـ وهناك: في ق.\r10 ـ و (1): ف لب، ما تقدم: ا ت ج ف ق ك لب ل ي، م، الشيء: ا ت ج ك ق لب ي، شيء ف ل م."], [415, "وعن الثانى ان المتميز كل واحد منها وهو متناه.\rوعن الثالث ان العلم واحد لكن نسبته غير متناهية، وهذا ضعيف. لأن الشعور بالشيء إذا كان لا يتحقق إلا مع هذه النسب، فهذه النسب ان لم تكن موجودة، لم يكن العلم موجودا. وان كانت موجودة، عاد الإلزام. وقد ذكرنا أن الأستاذ أبا سهل الصعلوكى التزمه.\rومنهم من أنكر كونه تعالى عالما بجميع المعلومات واحتج عليه بأنه لو علم جميع المعلومات لكان إذا علم شيئا، علم كونه عالما به، وعلم أيضا كونه عالما بكونه عالما به. ويترتب هناك مراتب غير متناهية. وإذا كانت معلوماته غير متناهية وله بحسب كل معلوم مراتب غير متناهية، كانت الصفات غير متناهية. لا مرة واحدة، بل مرارا غير متناهية.\rفإن قلت: العلم بالشيء نفس العلم بالعلم به، قلت هذا باطل. لأن العلم بالشيء إضافة إلى الشيء والعلم بالعلم بالشيء اضافة بين العلم وبين العلم بالشيء والإضافة إلى الشيء غير الإضافة إلى غيره.\r__________________\r1 ـ المتيز .. منها: ت ج ك ل لب ي، تميز .. منها:، المتنميز .. منهما: م، وهو: ق.\r2 ـ واحد: ت ج ك لب م ي، واحد و: ف ق، الواحد: ا، نسيته وتعلقاته: في ل ق.\r3 ـ هذه النسب: ج ق ك ل لب م ي، هذا النسب: ت، هذه النسبة: ا ف.\r4 ـ النسب: ت ج ق ك لب ل م ي، النسبة: ف.\r5 ـ الصعلوكي: ق م، ا ت ج ف ل لب ك ي.\r7 ـ تعالى: ا فقط، عليه: ج فقط.\r8 ـ كونه عالما: تكرر في ك ي، به: ا ف ق ت، بذلك الشي: ج، ك لب ل ف ي قبل: يكونه، ترتب: في ف.\r10 ـ واذا: وان: في ك.\r13، 14 ـ العلم بالشيء .. لان: ف.\r14، 15 ـ والعلم بالعلم .. والاضافة الى الشيء: ت فقط."], [416, "والجواب ان لا نهاية فى النسب والتعلقات، وهى أمور غير ثبوتية. إنما الثابت هو العلم، وهو صفة واحدة. وفيه الإشكال الّذي قدمناه وبالله التوفيق.\rمسئلة:\rذهب أصحابنا إلى أن الله تعالى قادر على كل المقدورات خلافا لجميع الفرق.\rلنا أن ما لأجله صح فى البعض أن يكون مقدورا لله تعالى هو الإمكان، لأن ما عداه أما الوجوب واما الامتناع، وهما يحيلان المقدورية لكن الإمكان وصف مشترك فيه بين الممكنات فيكون الكل مشتركا فى صحة مقدورية الله تعالى، فلو اختصت قادريته بالبعض دون البعض افتقر إلى المخصص وإذا ثبت إنه تعالى قادر على جميع الممكنات وجب أن لا يوجد شيء من الممكنات إلا بقدرته إذ لو فرضنا شيئا آخر مؤثرا لكان إذا اجتمعا على ذلك الممكن، فاما\r__________________\r1 ـ الجواب: في لب، لا نهاية: ت ق م ي، اللا نهاية: ج ف ك لب ل.\r2 ـ وانما: ق، اشكال: في ت.\r3 ـ الذي قدمناه: ت ج ف ق ك ل لب ي، بالذي تقدم: م وانه التوفيق: ل ك.\r5 ـ ذهب: ت ج ف لب ي، فذهب: ق ك م، ذهب بعض ل، الى ج ف ل لب ي، ت ق ك م، كل: ت ج م، جميع ك ل.\r8 ـ واما: ت ج ق ك ل لب م ي، او: ا ف، يحيلان: ج ق ك ل لب م، يخيلان: ا ت ي، يحلان: ف.\r9 ـ لكن: لان: في ك.\r10 ـ قادريته: ج ل ك م، قادرية الله: ت ق.\r11 ـ دون البعض: ا ت ج ف ق ك ل لب ي، م، لافتقر ف ب ق، المخصص: ت ج ك ل م، مخصص: ق، وذلك محال ا ق بعد المخصص. تعالى: ق فقط.\r12 ـ بقدرته: ت ج ق ك ل لب م ي، بقدرة الله تعالى: ف.\r13 ـ فرضنا شيئا: فرض شيء: في ك، لكان: ت ج ف ق ك لب ي، لكانا: م ل."], [417, "أن يقع ذلك الممكن بهما معا. فيجتمع على الأثر الواحد مؤثران مستقلان بالتأثير وهو محال، أو لا يقع بواحد منهما وهو محال. لأن المانع من وقوعه بهذا وقوعه بذلك. فما لم يوجد وقوعه بهذا لا يمتنع وقوعه بذلك وبالعكس. فلو امتنع وقوعه بهذا وذلك لزم وقوعه بهذا وذاك حتى يكون وقوعه بكل واحد منهما مانعا من وقوعه بالآخر، وذلك محال، وإما أن يقع بأحدهما دون الآخر، وهو محال لأن كل واحد منهما لما كان مستقلا بالتأثير، كان وقوعه بأحدهما دون الآخر ترجيحا لأحد طرفى الممكن على الآخر من غير مرجح، وهو محال فثبت أن جميع الممكنات واقع بقدرة الله تعالى وتعلقاته.\rاما الفلاسفة فقد منعوا أن يصدر من الواحد أكثر من واحد. وقد تقدم الجواب عن حجتهم.\rوأما الثنوية والمجوس فقد زعموا انه غير قادر على الشرور لأن\r__________________\r1 ـ معا: جميعا: ف ي.\r2 ـ بالتاثير: ا فقط.\r3 ـ بذلك: بذاك: في م، فما لم يوجد: ت ج ل ي م، فلما لم يوجد: ك، ومن: لب، بهذا (2): ت ج ل ي م، بذلك: ك لب.\r4 ـ لا يمتنع وقوعه بذلك بذاك: م، بهذا: ق: ا ت ج ق ك م ي لب، وبالعكس: ج فقط، وذلك: ت لب، او ذلك: ق، وذاك: ج ا ل، و: ف.\r5 ـ بهذا: بذذلك: في ق، بكل واحد .. وقوعه: ا فقط.\r(13/ 416)، 6 ـ ذلك الممكن ... واما ان يقع: ف فقط.\r6 ـ محال (2): ت ج ل م، باطل: ق.\r8 ـ من غير: ا ت ج ف ك ل لب ي، بلا: م.\r9 ـ واقع: ت ج ق م، واقعة: ك ل، وتعلقاته: ت م، وتعلقاتها: ق ك ي، ج ف ل لب.\r10 ـ واما: في: ف، من (1): ت ف ق ك ل لب ي، من: ج م، واحد: ج لب م ي، الواحد: ت ق ك ل، اكثر من واحد: ف.\r12 ـ فقد: ا ت ج ف ق ك ل لب ي، م، تعالى: في ف بعد: انه، الشرور: ت ج ف ق ك لب ل ي، الشر: م."], [418, "فاعل الخيرات خير وفاعل الشرور شرير. والفاعل الواحد يستحيل أن يكون خيرا شريرا.\rوالجواب إن عنيتم بالخير والشرير موجد الخير والشر، فلم قلتم أن الفاعل الواحد يستحيل أن يكون كذلك؟ وان عنيتم به غيره فبينوا.\rاما النظام فانه زعم انه لا يقدر على خلق القبيح.\rواحتج بأن فعل القبيح محال والمحال غير مقدور.\rاما أنه محال فلأنه يدل على الجهل أو الحاجة وهما محالان والمؤدى إلى المحال محال. وأما أن المحال غير مقدور فلأن المقدور هو الّذي يصح إيجاده. وذلك يستدعى صحة الوجود، والممتنع ليس له صحة الوجود.\rوالجواب لا نسلم أن فعل شيء قبيح يدل على الجهل أو الحاجة،\r__________________\r1 ـ الشر: في ك.\r2 ـ شريرا: ت ج م، وشريرا: ف ق ك ل لب ي.\r3 ـ او الجواب: في ت ج ي، عتيتم: ا ت ج ف ك ل لب ي، متيت: ق م، قلتم: ج ف ك ت لب ي، قلت: ل ق م.\r4 ـ عنيتم: ج ك ل لب ي، عنيت: ت ف ق م، به: م فقط.\r5 ـ فبينوا: ق ك ل م، فاذكروه تتكلم عليه: لب، فايدوه ليكلم لتتكلم: ك هامش عليه: ك ي، فينه: ج، فبين: ا ت، فلابد من بيانه و: ف.\r6 ـ اما: ت ج ل م، واما: ق، فاما: ك، فانه: ت ج ف ق ك ل لب ي، فقد: م، انه: ت ج ل لب م ي، ان: ف، القبيح: ت ج ف ق لب ي، القبح: ل، الجهل وسائر القبائح: ك م.\r8 ـ اما: ت ج ك ل لب م ي، واما: ف ق، او: ت ج ك ل، و: ق م.\r9 ـ فلان المقدور: م فقط.\r10 ـ و (2): ت ج ف ق ل لب ي، او: ا.\r12 ـ شيء قبيح: ف، الشيء القبيح: لب، الشيء: ج ك"], [419, "بل هو مالك قله أن يفعل ما يشاء سلمناه لكن هذا الامتناع إنما جاء من جهة الداعى.\rفلم قلت إنه ممتنع من جهة القدرة. فإن القادر عند انجزام إرادته بالترك يمتنع عليه الفعل نظرا إلى هذا الداعى. ولكنه يكون قادرا على الفعل، نظرا إلى إنه لو حصل له الداعى إلى الفعل بدلا عن الداعى إلى الترك لكان قادرا عليه.\rوأما عباد بن سليمان فإنه زعم أن ما علم الله تعالى أنه يكون فهو واجب، وما علم أنه لا يكون فهو ممتنع. والواجب والممتنع غير مقدور.\rوالجواب أن هذا يقتضي أن لا يكون لله تعالى مقدور أصلا. لأن\r__________________\rي، شيء: ل م، القبيح: ق، الجهل او الحاجة: ل، الجهل والحاجة: ت م .. او: ق ك .. ، الحاجة او الجهل: ج.\r1 ـ المالك: في ق، يشاء: ا ت ج ف ق ك ل ي، شاء: لب م، سلمناه: ا ت ج ف ق ك لب ل ي، سلمنا ه: م، انما: م فقط.\r3 ـ قلت: ت ج ف ك ل م ي، قلتم: ا ق لب، عند: ت ج ف ك لب ي، حال: ق ل م، انجزام: ك م، انحزام: ج، انجرام: ل، انحرام: ت.\r4 ـ ارادته بالترك: ت ج ل ف ق لب، ارادته للترك: ك ي، ازال به الترك: ا، ارادته الترك: م، يمتنع عليه: ا ت ج ق ك ل لب ي، يمتنع عنه: ف، ممتنع: عليه: م، و: ت ج ف لب ي ل.\r6 ـ لكان: ت فقط.\r7 ـ بن سليمان: في ت فقط، تعالى: ا ت ف ق ل لب ي،: ج ك م.\r8 ـ واجب: في ق، انه: ت ج م، بانه: ل، الله انه: ك.\r9 ـ مقدورين: في ق.\r10 ـ لله: ت ج م، الله: ل، مقدور: ت ج ق ك لب ي، مقدورا: ل ف م، اصلا: ت ج ك م، البتة: ل، لان: ك لب م، فان: ف."], [420, "كل شيء فهو إما معلوم الوجود أو معلوم العدم.\rثم نقول إنه وان كان واجبا نظرا إلى العلم لكنه ممكن فى نفسه، فكان مقدورا. ولأن العلم بالوقوع تبع للوقوع الّذي هو تبع القدرة. والمتأخر لا يبطل المتقدم.\rواما البلخى فقد زعم أن الله تعالى لا يقدر على مثل مقدور العبد لأن مقدور العبد، اما طاعة أو سفه أو عبث وذلك على الله محال.\rوالجواب أن الفعل فى نفسه اما حركة أو سكون مثلا وكونه طاعة وسفها وعبثا أحوال عارضة له، من حيث كونه صادرا عن العبد. والله تعالى قادر على مثل ذات ذلك الفعل وأما أبو على الجبائى وأبو هاشم واتباعهما، فقد زعموا أن الله تعالى قادر على مثل مقدور العبد لكن غير قادر على نفس مقدوره. لأن المقدور من شأنه أن\r__________________\r1 ـ فهو اما: ق م، فاما هو: لب، اما: ف، فاما: ك، ي.\r(10/ 419)، ا ـ لان .. العدم: ت ج ل.\r2 ـ نقول: ك، لكن: ف.\r3 ـ للوقوع: ا ت ج ف ك، الوقوع: ق ل لب م ي.\r5 ـ و: م فقط. ان الله تعالى: ت لب ل، ان الله: ج، انه: ق.\r6 ـ لان مقدور العبد: ت فقط، وعبث: ف ك ي، وعبثا: ا، ذلك: كل ذلك: ك، الله تعالى: ك.\r7 ـ الجواب: ف، اما: ك فقط، او: و: في ف، مثلا: ت ج، كونه: ج ق ل م، كونها: ت ك.\r8 ـ او سفها: ج ي فقط، وعبثا: ت ج ف ق ك ل لب ي، او عبث: م، له: ت فقط.\r9 ـ ذات: ت ج ك، الفعل: ت ج واما: ج ف ق ي، اما: ت ك ل لب م.\r9، 10 ـ ابوعلي وابو هاشم: ك م، ابو علي الجياني وابو هاشم: ل، ابو هاشم وابو علي: ت ج ف.\r11 ـ لكن: ت ج ق ل لب ي، لكنه: ك م."], [421, "يوجد عنه عند توفر الدواعى للقادر وأن يبقى على العدم عند توفر صارفه. فلو كان مقدور العبد مقدورا لله تعالى، لكان إذا أراد الله تعالى وقوعه، وكره العبد وقوعه، يلزم أن يوجد لتحقق الداعى، وان لا يوجد لتحقق الصارف، وهو محال.\rوالجواب أن البقاء على العدم عند تحقق الصارف ممنوع مطلقا، بل ذلك إنما يجب إذا لم يقم مقامه سبب آخر مستقل، وهو أول المسألة.\rمسئلة:\rاتفق أصحابنا على أنه تعالى عالم بالعلم قادر بالقدرة حي بالحياة خلافا للفلاسفة والمعتزلة. وأهم المهمات فى هذه المسألة الكشف عن محل النزاع.\rفنقول اما نفاة الأحوال منا فقد زعموا أن العلم نفس العالمية والقدرة نفس القادرية، وهما صفتان زائدتان على الذات. واعترف أبو على الجبائى وأبو هاشم بهذا الزائد إلا أنهم قالوا لا نسمى هذه\r__________________\r1 ـ عنه: ت ج ك: ل م، الدواعي للقادر: ت ج ك ي، الداعي للقادر: ف لب، دواعى القادر: ق ل م.\r2 ـ تعالى (1): ق ك، تعالى (2): ج.\r5 ـ الجواب: ف لب ل.\r6 ـ ان ذلك: ك، مستقل: ت ج م، يستقل: ق ك ل. وهو: ج ف لب ي، وهذا به: ق: ق ك ل م.\r10 ـ خلانا للفلاسفة والمعتزلة: ت ج ق ل لب م ي، والمعتزلة والفلاسفة خالفوا ذلك: ف، خلافا للفلاسفة والمعتزلة والكرامية: ك.\r11 ـ من محل الخلاف: ف ل.\r12 ـ اما: ت ج ف ق ك ل لب م ي، ما: ا.\r13 ـ اعتراف: ل.\r14 ـ الجبائي: ت ج ف ق ك ل لب، م ي، تسمى: ت ج، تسمى: نسخ، مسمى: ل."], [422, "الأمور علما وقدرة، بل عالمية وقادرية. فيكون الخلاف فى الحقيقة لفظيا بل ذهب أبو هاشم إلى أنها أحوال. والحال لا تعلم ولكن تعلم الذات عليها. وعندنا ان هذه الأمور معلومة فى نفسها.\rوقول أبى هاشم باطل قطعا، لأن ما لا يتصور فى نفسه، استحال التصديق بثبوته لغيره.\rوأما أبو على الجبائى فإنه سلم فيها أنها معلومة فعلى هذا لا يبقى بينه وبين نفاة الأحوال منا خلاف معنوى البتة.\rوأما مثبتو الحال منا فقد زعموا أن عالمية الله تعالى صفة معللة بمعنى قائم به وهو العلم، وهو لا يتحقق الخلاف بينهم وبين المعتزلة فى المعنى.\rوأما نحن فلا نقول بذلك لأن الدلالة ما دلت إلا على اثبات أمر زائد على الذات. فأما على الأمر الثالث، فلا دليل عليه البتة لا فى الشاهد ولا فى الغائب.\rأما الفلاسفة؛ فمن مذهبهم أن العلم عبارة عن حصول صورة\r__________________\r1 ـ بل: ت ج ف ق ك لب م ي، بلى: ا.\r2 ـ نعلم (1، 2): نسخ، نعلم: ت ج.\r3 ـ ان: ق ك ل م: ت ج ف لب ي.\r5 ـ لغيره: بغيره: ف.\r6 ـ فيها: ك فقط، انها معلومة: ت ج ق ك ل لب م ي، انه معلوم: ف.\r8 ـ اما: ك.\r9 ـ بمعنى: ا ت ج ف ق ك ل لب ي، لمعنى: م، وهو (2): ف.\r11 ـ فلا نقول بذلك: ت ج ق ك ل لب ي، فلا نقول ذلك: م، لا نقول بذلك: ف.\r12 ـ فاما: ت ج ك لب م ي، واما: ق ل، اما: ف، الامر: ت ج ك م، الاول و: ل.\r13 ـ واما: ق ل ي، ضمن: ت ج ق ك ل لب م ي، في: ف."], [423, "مساوية للمعلوم فى العالم. فإذا كانت المعلومات مختلفة فى الماهيات كانت الصور المساوية لها مختلفة فى الماهية فيكون علم الله تعالى بالمعلومات أمورا زائدة على ذاته تعالى وهى من لوازم ذاته.\rوقد صرح ابن سينا بذلك فى النمط السابع من كتاب الإشارات وعلى هذا فقد سلموا أن علم الله تعالى معنى قائم به إلا أنهم يعبرون عن هذا المعنى بعبارة أخرى.\rفيقولون علم الله تعالى صفة خارجة عن ذات الله تعالى متقومة بتلك الذات فكأنهم عبروا عن المعنى بالصفة الخارجة، وعن القيام بالذات بالتقوم بالذات. فظهر أنهم يساعدون فى هذه المسألة على المعنى بل يبقى الخلاف بينهم وبين مثبتى الحال منا. فانهم لا يقولون إلا بالذات وتلك الصورة اللازمة للذات. ومثبتو الحال منا قالوا بأمور ثلاثة: بالذات والعالمية والعلم فظهر أن الّذي يقوله\r__________________\r1 ـ فاذا: واذا: ا، الماهيات: الماهية: ت ج ل ف.\r2 ـ كانت ... الماهية الماهيات: ق، الداتية: ك: ا ت ج ف ق ك لب ي، م.\r3 ـ امورا: ا ت ج ف ق ل لب ي، امرا زائدا: ك، امور: م، تعالى: ت ج ق ك ل، وهي: وهو: ق.\r5 ـ به: ت ج ف لب ي، بذاته: ق ل م.\r7 ـ فيقولون: ت ج ك م، ويقولون: ق ل، ذات الله: ت ج ك ل م، ذاته: ق، منقومه: ت ج ف ك ل لب م، مقومة: ي، منقوصة: ق.\r8 ـ فكانهم: وكانهم: ا، هذا المعنى: ف ق.\r9 ـ بالتقوم: ت ج ف ق ك ل لب م، بالتقويم: ي، بالمتقوم: ا، في: ي.\r10 ـ على: ا ت ج ف ق ك ل لب ي، من: م، بل: ت ج ف ق ك ل م ي، فهذه المسالة متفق عليها في المعنى بل: لب، مثبتي: ا ت ج ف ق ك ل لب ي، مثبتو: م، الحال: الاحوال: ت ج.\r11 ـ الصورة: ا ت ج ف ل ي، الصور: ق ك لب م، الحال: الاحوال: ت ج ل.\r12 ـ فظير: ت ج ق ك لب ل م، وظهر: ف ي، بقوله: ت ج ف ق ك م ي، يقولونه: ي، يقولوه: ا، يقولو: ل."], [424, "نفاة الحال منا متفق عليه بين كل من أقر بكون الله تعالى عالما قادرا.\rلنا أن بعد العلم بكونه تعالى موجودا يفتقر إلى دليل آخر يدل على كونه تعالى عالما قادرا، والمعلوم ثانيا غير المعلوم أولا، فعلمه تعالى زائد على ذاته.\rاحتج الخصم بأمور أحدها: أن علمه لو كان زائدا على ذاته، لكان مفتقرا إلى ذاته، فيكون ممكنا لذاته، واجبا بعلة وتلك العلة ليست إلا تلك الذات، والموصوف به ليس إلا الذات، فتكون الذات فاعلة وقابلة معا، وهو محال.\rوثانيها: أن عالمية الله تعالى واجبة والواجب يستغنى بوجوبه عن العلة.\rوثالثها: لو كان له علم قديم لكان مشاركا للذات فى القدم.\r__________________\r1 ـ الحال: الاحوال: ت ج ل، متفق عليه بين: ت ج ك ل، يتقف: ق، يكون: ان يكون: ي.\r2 ـ لنا: ت ج ك م، ان نقول: ل، ان: ت ج ق ك ل، انا: م، تعالى: ك، موجودا: موجدا: ت ج، آخر: ف.\r3 ـ تعالى: ف.\r4 ـ فعلمه: فعلم الله: ق.\r5 ـ احدها: ا: ا.\r5، 6 ـ على ذاته لكان: ت ج.\r6 ـ ذاته: الذات: ف، بعلة: ت ج ف ق ك ل لب ي، لعلة: م، ليلة: ا.\r6، 8 ـ العلة .. ليس الا الذات: ك .. قابلة وفاعله: ك ل لب .. وهو محال: ت ج ف ق ك ل لب ي م، العلية ليس الا الذات فيكون فاعلة وقابلة: ا.\r9 ـ وثانيها: ت ق ك ل لب م ي، ثانيها: ف، الثاني: ج، وب: ا، واجبة: واجب: في ك، والواجب: الواجبة: في ل، بوجوبة: ت ج ف ق ل لب ي، وجوده: ل، بوجوه: م، ك.\r11 ـ اللذات: لذات: في ف."], [425, "وذلك يقتضي تماثلهما وان لا يكون أحدهما بكونه ذاتا والآخر بكونه صفة أولى من العكس. ورابعها أنها تكون مغايرة للذات فيلزم القول بقدماء متغايرة وهو محال.\rوخامسها: أن علم الله تعالى المتعلق بمعلومنا يجب أن يكون مثلا لعلمنا، فيلزم من حدوث علمنا حدوث علمه.\rوسادسها: أن العلم بكل معلوم غير العلم بغيره، على ما تقدم. ومعلومات الله تعالى غير متناهية، فيلزم أن يكون له علوم غير متناهية.\rوالجواب عن الأول فقد تقدم.\rوعن الثانى أنه إنما يتوجه على من يثبت عالمية ثم يعللها بمعنى ونحن لا نقول به وأيضا فبتقدير القول به نقول الواجب متى\r__________________\r1 ـ تمائلهما: ت ج ق ك ل، تمائلها. م. يكونه (2): ا ت ج ك ل لب ي: ق م.\r2 ـ ورابعها: انها: ك لب، ان: ف، يلزم ان: ي: ف ق ل ك لب ي، ولانها: ا ت ج ل، لانها: م، تكون: ت ج ق ل لب ك م ي، الصفة: ف.\r3 ـ بقدماء متغايرة وهو محال: ت ج ل ك، بقدماء مغايرة: ف لب م ي، تقدما متغايرة: ا.\r4 ـ خامسها: ف ق ك لب ي، رابعها: ت ج ل م، د: ا، بمعلومنا: ت ج ق ك لب م ي، بعلومنا: ا ف.\r6 ـ سادسها: ف ق ك لب ي، خامسها: ت ج ل م، ه: ا، معلوم، ا ت ج ف ق ك ل لب ي، المعلوم: م.\r6 ـ الجواب: ف ك، الاول ا: في ا، فقد: ت ف ل ي، قد: ج ك لب م.\r10 ـ الثاني: ب: في ا، بثبت: ت ج ف ق ك ل لب ي، م، عالية: ا ت ل لب ي، العالمية: ج، عالميته: ف ق ك م.\r13 ـ به: ا ت ج ف ق ك لب ي: ل م، نقول: ت ق ك ل لب م ي، فنقول: ا، بوجب: ف."], [426, "لا يعلل، إذا كان واجبا بذاته، أو بغيره.\rالأول: مسلم لكن لم قلت أن عالمية الله تعالى واجبة لذاته بل هذا أول المسألة.\rوالثانى: باطل لأن وجوب العالمية بالعلم لا يوجب استغناءه عنه، كما فى الشاهد.\rوعن الثالث: أن الاشتراك فى القدم اشتراك فى وصف سلبى أو ثبوتى وذلك لا يوجب التماثل أصلا. كما أن الضدين لا يلزم من اشتراكهما فى التضاد تماثلهما.\rوعن الرابع أنكم إن عنيتم بالتغاير أن كون كل واحد منهما مخالف للآخر فهو كذلك لكنا لا نطلق هذه اللفظة لعدم الإذن وان عنيتم به جواز المفارقة فى الزمان والمكان، أو الثبوت والعدم فلم قلتم\r__________________\r1 ـ المادة او بغيره: لذاته او لغيرة: في: ف ك.\r2 ـ والاول: في ف م، لكن .. ان: ت ج ك ل لب م ي، لكن لم ينم: ا ي: ولكن لم قلتم بان: ف، عالمية الله: ت ج ف ق ل لب م ي، عالميتة: ا ك، لذاته: لذاتها: في ل.\r2، 3 _ بل: محال: ت هذا هو: ك لب .. المسئلة: ت ج ق ك ل لب م ي، ف.\r6 ـ الثالث: ج: ا، وصف: ا ت ج ف ق ك ل لب ي، الوصف: م.\r7 ـ ل: ت ج ف ل لب م، لا: ق ك ي، ثبوتي: ثبوت في م.\r8 ـ قمائل ما: ت ج ق ك لب ل، مماثلتهما: م.\r9 ـ الرابع: د: في ا، انكم: ك، ان (2): ت ج منهما: ق ك م ي ك ي،: ا ف ل.\r10 ـ مخالف: ج ف م، مخالفا: ا ت ق ك ل ي، هذه اللفئة ا ت ف ق ك ل لب ي، هذا اللفظ: م.\r11 ـ به: ف ق، ت ج ك ل لب م ي، او الثبوت و: ت"], [427, "إنه كذلك وإن عنيتم به معنى ثالثا فبينوه.\rوعن الخامس: أن علمنا وعلمه المتعلق بمعلومنا يشتركان فى التعلق بذلك المعلوم. ولا يلزم من اشتراك الشيئين فى بعض اللوازم تماثلهما.\rولئن سلمناه لكن لا يلزم من حدوث علمنا حدوث علمه، كما لا يلزم من كون وجوده تعالى مساويا لوجودنا فى كونه وجودا حدوث وجوده.\rوعن السادس أن ما ألزمتم علينا فى العلم يلزمكم فى نفس العالمية وهو وارد على جميع الشبه فيه وبالله التوفيق.\rمسئلة:\rالبارى تعالى ليس مريدا لذاته، وهو قول أبى على وأبى هاشم\r__________________\rوالثبوت و: ك ل، او الوجود او: ج قلتم: ت ج ف ك ل م، نقل: ق لب ي.\r1 ـ انه كذلك: ت ج ف، به: لب ك م: ق ل، به: ف ق ج: ت ك ل لب م ي، فبينوه: فبينوا: في ف.\r2 ـ الخامس: ه: ا، علمنا و: ج: ت ك ل م، بمعلومنا .. التعلق: ت ج، بمعلومنا بعلومنا: ف بمعلوماتنا: ق مع علمنا يشتركان في التعلق: ق ك ل ف لب م، بعلومنا تشارك علمنا في المتعلق: ي.\r3 ـ ولا يلزم: ت ج ك م ي، وذلك لازم من لوازمهما لوازمها ق، اللوازم: ف لب ولا يلزم: ف ق ل لب.\r4 ـ تمائلهما: ت ج ق ك، مماتلتهما: ل م، ذلك: لب.\r5 ـ سلمنا: في ي، سلمنا به: في ل.\r8 ـ ان ما: ت ج ق ك لب م ي، انا ما: ل، اما: ف، في العلم: ف.\r9 ـ وهو وارد: ت ج ف لب ي ل، وهذه المعارضة واردة: ا ق لازمة: ا ك ق م، فيه: ي، وبالله التوفيق: م، والله اعلم: ج: ت ك ل ف ق لب ي."], [428, "والخلاف فيه مع النجار.\rلنا ما تقدم. واحتج أبو على وأبو هاشم على أنه تعالى ليس مريدا لذاته. لأنه لو كان مريدا لذاته لكان مريدا لجميع المرادات، كما أنه لما كان عالما لذاته كان عالما بكل المعلومات، لكن ذلك محال لأن زيدا إذا أراد موت رجل، وعمرو أراد حياته، فلو كان الله تعالى مريدا لكل المرادات، يلزم أن يكون مريدا لموته وحياته معا، وهو محال.\rولقائل أن يقول لم قلت انه لو كان مريدا لذاته لكان مريدا لكل المرادات والقياس على العلم لا يسمن ولا يغنى من جوع.\rوقولهم: لو كانت المريدية صفة ذاتية لم يكن تعلقها ببعض المرادات أولى من تعلقها بالباقى، فقد عرفت ضعفه.\rمسئلة:\r__________________\rانا تقدم: ت ج ف ك ل لب، لنا ما تقدم في مسئلة نعلم: ق م، الا ما تقدم: ي، اير على .. انه: ت ج ق ك ل لب ي م، ابو ميثم وابن على انه: ف.\r3 ـ اما ما تقدم: ف ل، بمانه: ق لب م ي، انه: ت. مرريدا الذاته في ف ك ل لب ي، كذلك: م، لجميع الارادات: ف، ت: ج ك م، لما: ت.\r4 ـ ما ورد من ابي ت ج ك ل لب م ي، لوكان: ف ق لكان محل: في حاصل م، فلو كان مريدا لجميع المرادات لكان ذلك صحة ك.\r5 ـ ومن: ف ق م، عمرا: ج لب ي، تعالى: ك.\r6 ـ يلزم: ت ب ق ك ل، للزم: لب م ي.\r8 ـ لكان في ارد ف ك ل لب،: ق م ي.\r9 ـ بكل المرادات هناك ل لب ت ج ك ل لب م ي.\r10 ـ من كل ق لما: م ل، المريدية: المريد في ت، تعلقها في كل م ت ل ي س.\r11 ـ بالثاني: الباني: ل، ضعفه: ضعيفة: ل."], [429, "لا يجوز أن يكون الله تعالى مريدا بإرادة حادثة خلافا للمعتزلة والكرامية، اما عند المعتزلة، فهو تعالى مريد بإرادة محدثة لا فى محل وأما عند الكرامية فهو مريد بإرادة يخلقها فى ذاته.\rلنا أن احداث الشيء لا يصح إلا بالإرادة على ما تقدم. فلو كانت الإرادة حادثة لافتقرت إلى إرادة أخرى ولزم التسلسل.\rمسئلة:\rكلام الله تعالى قديم، خلافا للمعتزلة والكرامية.\rواعلم أن الجمهور منا يعتقدون أن المعتزلة يوافقوننا فى كونه تعالى متكلما ويخالفوننا فى قدم الكلام وأما نحن فقد بينا أن الّذي يقول به المعتزلة فنحن نقول به من حيث المعنى، والّذي نقول به فهم لا يقولون به البته. فإذا حاولنا مكالمة المعتزلة وجب علينا أن نحقق ماهية هذا الكلام ثم نقيم الدلالة على أن الله تعالى موصوف بها ثم نقيم الدلالة على قدمها. فإنهم يخالفوننا فى المواضع الثلاثة:\r__________________\r1 ـ انه كذلك: ت ج ف، به: لب ك م: ق ل، به: ف ق ج: ت ك ل لب م ي، فبينوه: فبينوا: في ف.\r2 ـ الخامس: ه: ا، علمنا و: ج: ت ك ل م، بمعلومنا .. التعلق: ت ج، بمعلومنا بعلومنا: ف بمعلوماتنا: ق مع علمنا يشتركان في التعلق: ق ك ل ف لب م، بعلومنا تشارك علمنا في المتعلق: ي.\r3 ـ ولا يلزم: ت ج ك م ي، وذلك لازم من لوازمهما لوازمها ق، اللوازم: ف لب ولا يلزم: ف ق ل لب.\r4 ـ تمائلهما: ت ج ق ك، مماتلتهما: ل م، ذلك: لب.\r5 ـ سلمنا: في ي، سلمنا به: في ل.\r9 ـ واما: ت ج ف ق ل، فاما: م: ما: ك، فقد: ا ت ج ق ك لب بي، قد: ف م.\r10 ـ فاول (2): ا: يقول.\r11 ـ فاذا: واذا: ق.\r12 ـ هذا: ت ج ق ك ل، م.\r12، 13 ـ ثم نقيم الدلاللة على ان الله تعالى موصوف بها: ق ك ل، ت ج.\r13 ـ على فدمها: في امر قدمها: ي."], [430, "فنقول أما المقامان الأولان وهما المقامان الصعبان مع المعتزلة فقد تقدم القول فيهما وأما الثالث فالدليل عليه من وجهين:\rالأول: ان القائل قائلان: قائل أعترف بكون الله تعالى موصوفا بهذا الكلام وقائل أنكر ذلك. وكل من اعترف به قال إنه قديم. لأن المعتزلة والكرامية لم يعترفوا بكون الله تعالى موصوفا بهذا الكلام. وإنما قالوا بحدوث الكلام الّذي يكون حرفا وصوتا وإذا ثبت ذلك، فلو قلنا بحدوث هذا الكلام كان ذلك قولا ثالثا خارقا للاجماع وهو باطل.\rالثانى: وهو أن هذا الكلام لو كان محدثا، لكان اما أن يحدث فى ذات الله تعالى فيكون الله تعالى محلا للحوادث، وهو محال أو لا يحدث فيه، وهو محال. لأن كون الله تعالى متكلما قد دللنا على أنه من صفاته وصفة الشيء يستحيل أن لا تكون حاصلة فيه، وإلا لجاز أن يكون الجسم متحركا بحركة قائمة بالغير، وذلك محال.\rاحتجوا بأمور:\r__________________\r2 ـ الاول: ا: ا. يكون الله: ت ج ق ل م، يكونه: ك.\r2 ـ هذا الكلام: ت ج ق ك ل لب م ي، الكلام الذي يدعيه: م: لب ي.\r7، 8 ـ لحترها للاجماع: ت ج ف ق ك ل لب ي، وهو خارق في اجتماع ... وهو خرق الاجماع: م.\r8 ـ وهو ان هذا: ا ت ج ق ك ل لب، وهو أن: ي، هو ان وهو ان يكون هذا: م.\r10 ـ الله تعالى: ت ف ق ك ل لب، تعالى: ي: ج م. محل: ل.\r11 ـ قد: فقد: ف.\r11، 12 ـ على انه: عليه انه: ك، صفات: في ق.\r13 ـ الجسم: ف فقط، متحركا: ج ك م، متحرك: ت بحركة: ت ج م، لحركة: ك ق: ل، بالغير: في الغير: في ق.\r14 ـ واحتجوا: ك م."], [431, "أحدها: أن الأمر بلا مأمور عبث، وهو غير جائز على الله تعالى\rوثانيها: أنه تعالى فى الأزل لو كان متكلما بقوله تعالى (إِنَّا أَرْسَلْنا نُوحاً). وهو إخبار عن الماضى لكان كاذبا.\rوثالثها: أن الأمة مجمعة على أن كلام الله تعالى ناسخ ومنسوخ وسور وآيات. وذلك من صفات المحدثات.\rوالجواب عن الأول ان عبد الله بن سعيد ذهب إلى أن كلام الله تعالى، وان كان قديما لكنه ما كان فى الأزل أمرا ونهيا وخبرا ثم صار فيما لا يزال كذلك وهذا فى غاية البعد.\rلأنا لما وجدنا فى النفس طلبا واقتضاء وبينا الفرق بينه وبين الإرادة أمكننا بعد ذلك أن نشير إلى ماهية معقولة، وندعى ثبوتها لله تعالى. فاما الكلام الّذي يغاير هذه الحروف والأصوات، ويغاير ماهية الأمر والنهى والخبر فغير معلوم التصور، فكان القول بثبوته لله تعالى فى الأزل محض الجهالة.\r__________________\r1 ـ احدها: ت ج ف ق ك ل لب ي، ا: ا، اولها: م.\r2 ـ ثانيها: ب: ا، في الازل .. متكلما: ت ج ق ل لب م ي، لوكان متكلما في الازل: ف، لو كان متكلما: ك، تعالى: فقط.\r3 ـ نوحا: ف لب ي، سورة نوح آية ا، كاذبا: كذبا: ك.\r4 ـ ثالثها: ج: ا، مجمعة: اجمعت: ف، على: ك فقط، تعالى: ا ف ل لب ك ي: ت ج ق م.\r6 ـ الجواب: ف، الاول: ا: ا. سعيد: مسعود: ف.\r7 ـ ولكنه: في ك، امرا ونهيا وخيرا: ت ج ف ل لب، امر ونهي وخير: ي، امرا ولا نهيا ولا خيرا: ق ك م.\r8 ـ لا يزال: ت ج ف ق ك ل لب م ي، الانرال: ا، وهذا وهو: ك.\r9 ـ في النفس: من النفس: ف.\r10 ـ ماهية: ق ل م: ت ج ك.\r11 ـ و: ا ت ج ف ك ل لب ي: م."], [432, "وأما جمهور الأصحاب فقد زعموا أن كلام الله تعالى كان أمرا ونهيا فى الأزل.\rثم منهم من يقول المعدوم مأمور على تقدير الوجود. وهذا أيضا فى غاية البعد لأن الجماد إذا لم يجز أن يكون مأمورا فالمعدوم الّذي هو نفى محض كيف يعقل أن يكون مأمورا.\rومنهم من قال إنه كان فى الأزل أمرا من غير مأمور ثم لما استمر وبقى صار المكلفون بعد دخولهم فى الوجود مأمورين بذلك الأمر وضربوا له مثالا وهو أن الإنسان إذا أخبره النبي الصادق بأن الله تعالى سيرزقه ولدا ولكن يموت قبل ولادته فإنه ربما قال لبعض الناس إذا أدركت ولدى بالغا فقل له إن أباك يأمرك بتحصيل العلم. فهنا قد وجد الأمر، والمأمور معدوم، حتى إنه لو بقى ذلك الأمر وذلك الآمر إلى أوان بلوغ ذلك الصبى لصار مأمورا بذلك الأمر.\r__________________\r1، 2 ـ الى في الازل .. الله تعالى: ق.\r2 ـ اذن: ك.\r4 ـ ثم منهم من: ت ج ق ك ل لب م ي، ثم: ف، ايضا: ف ق ب ك ل م.\r5 ـ مودرا: مامور: ك.\r6 ـ وا: ت لمعدوم هو: ل لب م ي الذي و: ل ... مامورا: ت ج ق ك ل لب م ي، ف.\r2 ـ كان في الزل امر: ي، الاول كان امرا: ق ل م، لما: ت لب م ي، اذا: ف.\r6 ـ لان ت ج ف ل ي، لكنه، ق ك لب م، قال: يقول: ق.\r10 ـ الناس: امدفاته: ق، اذا: ت ف ق ك ل م، ان: لب ج ي، ادركت: ت ج ف ق ك ل لب م ي، دركت: ا، ان: ا ت ل لب ي: م.\r11 ـ فهنا: ا ت ج لب ي، فههنا: ف ق ك ل م، قد: ل.\r12 ـ وذلك الامر: ت ج ل، ك م."], [433, "وعن الثانى أن الخبر فى الأزل واحد ولكن تختلف اضافته بحسب اختلاف الأوقات وبحسب ذلك تختلف الألفاظ الدالة عليه، كما فى العلم.\rوعن الثالث أن تلك الصفات عائدة إلى هذه الحروف والأصوات، ولا نزاع فيه إنما الكلام فى الصفة القديمة التى دلت عليها هذه العبارات.\rمسئلة:\rهذه الصفة القديمة المسماة بالكلام عندنا واحدة، خلافا لبعض أصحابنا. فانهم أثبتوا لله تعالى خمس كلمات: الأمر، والنهى، والخبر، والاستخبار، والنداء.\rلنا أن حقيقة الكلام هو الخبر. والأمر، والنهى أيضا خبر لأنه إخبار عن ترتب الثواب والعقاب على الفعل والترك.\r__________________\r1 ـ الثاني: ت: ا، لكن تختلف اضافته: ت ج ك لب ل، لكنه لكن: ف ق مختلف يختلف: ي، بمختلف: ف اضافته: ف ق ي اضاف: ي.\r4 ـ الثالث: ج: ا.\r5 ـ ولا فلا: ك نزاع فيه: ت ج ك ل م، ولا نزاع: ا، بلا نزاع و: ف لب: ف ق لب ي، القديمة: ف.\r5، 6 ـ دلت عليها هذه العبارات: ت ج ف ق ك لب ي، عليها دلت هذه العبارات: ا، دلت هذه العبارات عليها: م، دلت عليه العبارات: ل.\r8 ـ بالكلام عندنا عنها: ي واحدة واحد: ق: ت ج ف ق ك ل لب م ي، عندنا الكلام واحد: ا.\r9 ـ اصحابنا: ت ج ق ك ل لب م ي، الناس: ف، لله تعالى: ق ك ل لب، لله: ت ج ف ي: م.\r11 ـ ان: ا ت ج ف ق ك ل لب ي: م، هو: ت ج ف ق ك ل لب ي، هي: م، خير: ل.\r12 ـ ترتب: ت ج ل م، ترتيب: ق ك، على: ت ج ق ك ل."], [434, "مسئلة:\rخبر الله تعالى صدق، لأن الكذب نقص، وهو على الله تعالى محال. ولأنه لو كان كاذبا لكان كاذبا بكذب قديم. ولو كان كذلك لاستحال منه الصدق لكن التالى محال لأن كل من علم شيئا صح منه أن يخبر عنه فى نفسه خبرا صدقه، وذلك معلوم بالضرورة.\rلا يقال هب أن ما ذكرتموه يدل على أن ذلك الخبر القديم صدق ولكنه لا يدل على كون هذه الألفاظ صدقا. لأنا نقول للمعتزلة هذا أيضا لازم عليكم لأنكم جوزتم الحذف والاضمار لحكمة لا نطلع عليها وتجويز ذلك يرفع الوثوق عن هذه الظواهر.\rمسئلة:\rنحن نعلم بالضرورة أن ذلك الكلام القديم غير مسموع الآن\r__________________\rلب م ي، عن: ف، لو الترك: ف ي.\r2 ـ تعالى: ا ق ك لب ل: ت ج ف م ي.\r3 ـ كاذبا (1): كذبا: في ا، يكذب قديم: بالكذب القديم: في ف.\r4 ـ لكن: ولكن: في م فقط، الثاني: ج ف ق ك م، الثاني: ت ل ي، الباقي ا، لان: ت ج ل لب ف ي، فان: ق ك م، شيئا: الشيء: ف.\r5 ـ ان يخبر عنه في نفسه عن عينه: ق، في نفسه عنه: ا ق ك لب ي، ان الخبر في نفسه عنه: م، الخبر منه في نفسه: ف.\r6 ـ ذكرتموه يدل: ت ج لب ي، ذكرتم يدل: ق ل، ذكرتموه دل: ف، ذكرته يدل: ك م، ذلك: ف.\r7 ـ ولكنه: ت ج لب، لكنه: ق ك ل م، لكن: ف ي، كون هذه الالفاظ: ان ذلك الخير القديم: في ل، صداقا: ت ج ق ك لب م، صدق: ل، صدقه: ف، صادقة: ي.\r8 ـ لازم: ت ج ف ق ك لب ل م ي، الزم: ا، لحكمة: ت ق م، لحكم: ك ل، يحكم: ج.\r9 ـ تجويز: ت ج ف ق ك لب م ي ل، تجوز: ا، الوثوث: الامان: ف."], [435, "وهل يصح أن يكون مسموعا؟ هذا مما لم يقم عندى عليه دليل لأنا إنما جوزنا رؤية ما ليس بجسم ولا بعرض. لأنا لما رأينا الجسم والعرض وثبت أنه لا بد من علة مشتركة وانه لا مشترك إلا الوجود، لا جرم.\rقلنا يجوز رؤية كل موجود. أما فى هذه المسألة فالسمع لم يتعلق بالأجسام والأصوات حتى يفتقر إلى علة مشتركة بل السمع لم يتعلق إلا بالأصوات فجاز أن تكون علة صحة المسموعية هى الصوتية فقط، وحينئذ لا يكون ذلك الكلام مسموعا.\rمسئلة:\rزعم بعض الفقهاء الحنفية أن التكوين صفة أزلية لله تعالى. وان المكون محدث. فنقول لهم القول بأن التكوين قديم أو محدث يستدعى تصور ماهية التكوين. فإن كان المراد منه نفس مؤثرية القدرة فى المقدور، فهى صفة نسبية والنسب لا توجد إلا مع\r__________________\r1 ـ مما: ت ج ك ل لب م ي، ما: ف، عندي .. دليل دلالة: ا ل، دليله: ق: ا ت ج ق ك ل لب م ي، عليه دليل عندي: ف، لانا: لا ادل: ل.\r2 ـ انما: ا ت ج ف ق ك ل لب ي: م ل، لانا: ت ج ف ق ك ل لب ي، لانه: م.\r3 ـ وثبت: ثبت: ا.\r4 ـ لا جرم: ف.\r5 ـ اما: واما ك في م فقط، في: ك ل م: ت ج، لم: ت ج ف ق ل لب م ي، لا: ا ك.\r6، 7 ـ حتى .. بالاصوات: ت.\r7 ـ الا: ج ف ق ك ل لب ي: م.\r10 ـ الفقها ء: ت ج ف ق ك ل ي، فقهاء: لب م، فيها: ا.\r11 ـ او: ا ت ج ف ق ك ل لب ي، و: م.\r12 ـ والنسب: ا فقط. مع: ت ج ف ق ك ل لب ي، عند وجود: م."], [436, "المنتسبين، فيلزم من حدوث المكون حدوث التكوين. وان عنيتم به أنه صفة مؤثرة فى صحة وجود الأثر فهى عين القدرة. وإن عنيتم به أمرا ثالثا فبينوه.\rقالوا: القدرة مؤثرة فى صحة وجود المقدور. والتكوين مؤثر فى نفس وجود المقدور.\rقلنا القدرة لا تأثير لها فى كون المقدور فى نفسه جائز الوجود. لأن ذلك له لذاته. وما بالذات لا يكون بالغير: فلم يبق إلا أن يكون تأثيرها فى وجود المقدور تأثيرا على سبيل الصحة، لا على سبيل الوجوب. فلو أثبتنا صفة أخرى لله تعالى مؤثرة فى وجود المقدور، لكان تأثيرها فى المقدور. وأن كان على سبيل الصحة كان عين القدرة، فيلزم اجتماع المثلين، ويلزم اجتماع صفتين مستقلتين بالتأثير على مقدور واحد، وهو محال. وان كان على سبيل الوجوب لزم استحالة أن لا يوجد ذلك المقدور من الله تعالى، فيكون الله تعالى\r__________________\r1 ـ وان: فان: ك.\r2 ـ به انه: ج، به: ا ف ق ك لب ي: ت ل م، صحة: ت ج ك ي، ق ف ل.\r3 ـ فبينوه: ج ك ل م، فبينوا: ت.\r4 ـ مؤثة: صفة مؤثرة: في م فقط.\r7 ـ لا يكون: يستحيل ان يكون: ف ق.\r8 ـ فاثيرا: ا ت ج ف ق ك ل لب ي، تاثيرها: م.\r9 ـ صفة اخرى لله تعالى: ت ج ق ك ل لب ي، لله تعالى صفة اخرى، ف، صفة اخرى لله: م.\r10 ـ المقدور (2): وجود المقدور: في ف، وان: ج ك ل م، ان: ت ف ق لب ي.\r11 ـ صفتين مستقلتين: ت ج ف ق ك ل لب م ي، الصفتين المستقلتين.\r12 ـ مقدور واحد: ت ج ف ك لب، المقدور الواحد: ق ل م ي.\r12 ـ مقدور واحد: ت ج ف ك لب، المقدور الواحد: ق ل م ي.\r13 ـ لزم استحالة: ت ج ف ق ك ي، استحال: ا، يلزم استحالة: لب ل، المقدور: المقدر: ق."], [437, "موجبا بالذات لا فاعلا بالاختيار، وهو باطل بالاتفاق. وأيضا فالقدرة تنافى هذه الصفة، لأن الموجب بالذات لا يكون قادرا مختارا.\rمسئلة:\rالظاهريون من المتكلمين زعموا أنه لا صفة لله تعالى وراء هذه السبعة أو الثمانية. وأثبت أبو الحسن الأشعرى رضى الله عنه اليد صفة وراء القدرة، والوجه صفة وراء الوجود، وأثبت الاستواء صفة أخرى.\rوأثبت أبو اسحاق الأسفرائيني صفة توجب الاستغناء عن المكان.\rوأثبت القاضى صفات ثلاثة أخرى: وهى إدراك الشم والذوق واللمس.\rوأثبت عبد الله بن سعيد القدم صفة وراء البقاء.\rوأثبت مثبتو الحال العالمية أمرا وراء العلم. وكذا القول فى سائر الصفات.\rوأثبت أبو سهل الصعلوكى لله تعالى بحسب كل معلوم علما، وبحسب كل مقدور قدرة.\rوأثبت عبد الله بن سعيد الرحمة، والكرم، والرضا صفات\r__________________\r4 ـ هذه: ت ج ف ق لب ل: ك م.\r5 ـ او: و: في ا ف، رضي الله عنه: ت ك ل ي، رحمة الله ج، ف ق لب م.\r6 ـ صفة: صفة زائدة: في ق.\r10 ـ صفات ثلاثة اخرى: ت ق ل لب م ي، صفات اخرى ثلاثة: ك، صفات ثلاثة: ج، ثلاث صفات: ف، هي: هو: ف.\r12 ـ سعيد: ف ك ص ل م، مسعود: ت ج.\r13، 14 ـ اثبت مثبتو .. كذلك: ت ي .. الصفات: ف، امرا: امر: ا.\r17 ـ الرحمة والكرم: ت ق ج ك ل لب م ي، الرحمة والكرامة"], [438, "وراء الإرادة.\rوالانصاف أنه لا دلالة على ثبوت هذه الصفات ولا على نفيها، فيجب التوقف.\rواحتج من حصر الصفات فى السبعة أو الثمانية بانا كلفنا بكمال المعرفة، وكمال المعرفة انما يحصل بمعرفة جميع الصفات. ومعرفة جميع الصفات لا يتأتى إلا بطريق، ولا طريق إلا الاستدلال بالأفعال والتنزيه عن النقائص. وهذان الطريقان لا يدلان إلا على هذه الصفات.\rوالجواب لم قلت انا أمرنا بكمال المعرفة ولم لا يجوز أن يقال: انا ما أمرنا بأن نعرف من صفات الله تعالى إلا القدر الّذي يتوقف على العلم به تصديق محمد عليه الصلاة والسلام.\rسلمنا، لكن لا نسلم أنه لا بد من الدليل سيما وعندنا التكاليف\r__________________\rا، الكرم والرحمة: ف، الرضا: ا ت ج ف ق ك ل لب ي، الرضا والسخط: م.\r2 ـ على (2): ت ل.\r3 ـ فيجب: فوجب: ف.\r4 ـ او: و: ت، بانا: ك ج م، انا: ت ل.\r5 ـ بمعرفة لمعرفة: ف.\r6 ـ جميع: ت ج.\r7 ـ الا: ا.\r9 ـ الجواب: في ل، قلت: ت ج ق ك ل م ي، قلتم: ف لب، انا انه انا: ت ... ان يقال: ت ج ف ق ك ل لب م ي،: ا.\r10 ـ انا ما: ت ج ك ل ي، انما امرنا: ف، انا: ق لب، بان تعرف: ان لا نعرف: ق، تعالى: ك، القدر: ا ت ج ف ق ك ل لب، القدرة: م ي.\r11 ـ به بها: ي .. عليه الصلاة و: ك ق م ي، صلى الله عليه وسلم: لب .. السلام: ت ج ق ل لب م ي، به العلم بصدق الرسول عليه السلام: ف، تصديق نبينا محمد عليه السلام: ك.\r12 ـ سلمنا: ت ج ل، سلمناه: ك م، ولكن: في ل، لابد"], [439, "بأسرها تكليف ما لا يطاق. سلمناه لكن لم قلت أن الاستدلال بالأفعال وتنزيه الله تعالى عن النقائض لا يدل إلا على هذه الصفات فقط.\rمسئلة:\rذهب ضرار من المتقدمين والغزالى من المتأخرين إلى أنا لا نعرف حقيقة ذات الله تعالى، وهو قول الحكماء. وذهب جمهور المتكلمين منا ومن المعتزلة إلى أنها معلومة لنا.\rحجة المتكلمين أنا نعرف وجوده، ووجوده عين ذاته. فلا بد وأن نعلم ذاته، وإلا لكان الشيء الواحد بالاعتبار الواحد معلوما مجهولا.\rحجة الفريق الثانى من وجهين:\rالأول إن المعلوم عندنا منه سبحانه وتعالى، أما السلوب: كقولنا ليس بجسم ولا جوهر ولا عرض. ولا شك فى ان الماهية\r__________________\rفي ذلك: في ق، الدليل: ت ج ق ك ل م ي، دليل: ف لب، سيما و: ت ج ك ل م، لاسيما و: ق لب، سيما: ف، بينها و: ي، عندنا: ل، التكاليف: ت ج ك، التكليف: ل.\r1 ـ ما: ت ج ق م، بما: ك ل، سلمنا ه: ت ج ق م، سلمنا: ك ل، سلمنا انه لابد من دليل: لب، لكن: ف، قلتم: لب.\r3 ـ فقط: م فقط.\r5 ـ المتقدمين: ا ج ف ق ك ل هامش لب ي، المتكلمين: لب م: ت، الغزالي رحمه الله: لب.\r7 ـ لنا: ت ج ف ق ك ل لب ي: م.\r8 ـ انا ا ت ج ف ق ك ل لب ي، منا ومن المعتزلة انا: م هامش لب.\r9، 10 ـ مجهولا معلوما: في ف.\r12 ـ الاول: ا: ا، احدهما: ج، ان: ا ت ج ف ق ك ل لب ي، اما: م، عندنا: ت ج ك، سبحانه وتعالى: ت ف ق ك ل ي، سبحانه: ج، تعالى: لب.\r13 ـ عرض ولا بجوهر: في ف، في: ا ق ل لب: ت"], [440, "مغايرة لسلب غيرها عنها.\rوأما الإضافات كقولنا: قادر عالم ولا شك أن الماهية مغايرة لهذه الاضافات. لأن المعلوم عندنا من قدرة الله تعالى أنها أمر مستلزم للتأثير فى الفعل على سبيل الصحة. فماهية القدرة مجهولة والمعلوم منها ليس إلا هذا اللازم وهذا التأثير المخصوص.\rوكذلك المعلوم عندنا من علم الله تعالى ليس إلا أنه أمر يلزمه الإحكام والاتقان فى الفعل. فماهية ذلك العلم غير هذا الأثر. والمعلوم ليس إلا هذا الأثر. فظهر أن ماهية صفات الله تعالى غير معلومة لنا.\rوبتقدير أن تكون معلومة لكن العلم بالصفة لا يستلزم العلم بماهية الموصوف على التفصيل. ولما دل الاستقراء على سبيل الانصاف، انا لا نعلم من حقيقة الله تعالى إلا السلوب والاضافات. وثبت أن العلم بهما لا يستلزم العلم بالماهية. ثبت أنا لا نعلم حقيقة الله تعالى.\r__________________\rج ف ك م ي.\r1 ـ غيرها: ت ج ف ل لب ل، ماعدها: ق ك م.\r2 ـ قادر عالم: ت ج ف ق ل م، عالم قادر: ك لب ي، ولا ا ت ج ف ك ل لب ي، فلا: ق م.\r3 ـ مغايرة: ت ج ك م، صفاته: ل، المعلوم: المعلوم: ي، انها: ت ج ف ق ك ل لب، انه: م، انهما: ي.\r4 ـ للتاثير: ا ت ج ف ق ك ل لب ي، التاثير: م.\r5 ـ منها: ا ت ج ف ق ك لب، منهما: ل: م، هذا (2): ت ج، هو: ل م ك.\r7 ـ يلزمه: يلزم منه: ق لب، يلزم: ل.\r8 ـ غير: ت ج ف ق ك ل لب م ي، عين: ا.\r11 ـ لكن: لنا لكن: ق.\r13 ـ من حقيقة: ت ج ف ق ي، حقيقة: ل: ك لب م، تقدمت الاضافات على السلوب في: ف."], [441, "الثانى: إنا قد بينا فى أول هذا الكتاب أنه لا يمكننا أن تتصور شيئا إلا الّذي ندركه بحواسنا، أو نجده من نفوسنا أو نتصوره من عقولنا، أو ما يتركب من هذه الثلاثة. والماهية الإلهية خارجة عن هذه الأقسام الثلاثة فهى غير معلومة لنا.\rمسئلة:\rالله تعالى يصح أن يكون مرئيا خلافا لجميع الفرق.\rأما الفلاسفة والمعتزلة فلا إشكال فى مخالفتهما.\rوأما المشبهة والكرامية، فلأنهم إنما جوزوا رؤيته لاعتقادهم كونه تعالى فى المكان والجهة. وأما بتقدير أن يكون هو تعالى منزها عن الجهة فهم يحيلون رؤيته. فثبت أن هذه الرؤية المنزهة عن الكيفية مما لا يقول بها أحد إلا أصحابنا. وقبل الشروع فى الدلالة لا بد من تلخيص محل النزاع.\r__________________\r1 ـ الثاني: ب: ا: ت، انا قد: ج ف ق ك ل. لب، انا: ي، لانا قد: ت، انه لا يمكننا ان: ت ج ق ل، انا لا ك.\r2 ـ بالحواس: في ق، نفوسنا: انفسنا: ف ق.\r3 ـ من هذه: ت ج ف ق ك ل ي، عن احد هذه: لب والماهية: ا ت ج ف ق ك ل لب ي، فالماهية: م.\r7 ـ اما: واما: م، المعتزلة والفلاسفة: في ف، مخالفتهم: ت ج ف ق ك لب ي، مخالفتهم: م، مخالفتها: ا ل.\r8 ـ رؤيته: رؤية الله تعالى: ف.\r9 ـ في الجهة والمكان: في ق، واما: اما: في ق، هو تسلتمز: ت ج م ي، الله تعالى: ق ك ل لب: ف.\r10 ـ عن: ت ج ك ل، عن المكان و: ق، يحيلون: ق ك ا، ينكرون: لب، يخالفون في: ي، يختلفون في: ت، يحيلون وجوده فلا عن: ج.\r11 ـ بها: ت ج ف ق ك ل لب ي، به: م، قيل قيل.\r12 ـ من: ا ت ج ف ق ك ل لب ي، في: م."], [442, "فإن لقائل أن يقول: ان أردت بالرؤية الكشف التام، فذلك مما لا نزاع فى ثبوته لأن المعارف تصير يوم القيامة ضرورية. وإن أردت به الحالة التى نجدها من أنفسنا عند إبصارنا الأجسام فذلك مما لا نزاع فى انتفائه. لأنه عندنا عبارة عن ارتسام صورة المرئى فى العين، أو عن اتصال الشعاع الخارج من العين بالمرئى أو عن حالة مستلزمة لارتسام الصورة أو لخروج الشعاع وكل ذلك فى حق الله تعالى محال. وإن أردت به أمرا ثالثا، فلا بد من افادة تصوره. فإن التصديق مسبوق بالتصور.\rوالجواب إنا إذا علمنا الشيء حال ما لم نره، ثم رأيناه. فانا ندرك تفرقة بين الحالتين وقد عرفت أن تلك التفرقة لا يجوز عودها إلى ارتسام الشبح فى العين، ولا إلى خروج الشعاع منها. فهى عائدة إلى حالة أخرى مسماة بالرؤية. فندعى أن تعلق هذه الصفة بذات الله تعالى جائز، هذا هو البحث عن محل النزاع.\r__________________\r1، 2 ـ مما .. ثبوته: ت ج ف ق ل لب، لا نزاع في ثبوته: ي، مسلم: ك م.\r3 ـ به: ا ت ج ك ل، بها: ق م، ابصارنا: ت ج ق ي م، ابصار: ا ف ك ل لب.\r4 ـ انتفاله: الانتفاء به: ف.\r5 ـ بالمرني: ت ج ق ك ل، الى المرئي: م، المرئي: لب ي.\r6 ـ لخروج: ج ق ك ل لب م، وخروج: ا، بخروج: لب ي، الخروج: ت، الشعاع (2): العشاع: في م، الشماع من العين ل.\r5، 6 ـ الخارج ... الشعاع: ا ف.\r7 ـ اردت به: ت ج م ك ل بها: ق، اردتم به: ف.\r9 ـ حال ما لم نره بره: ت: ت ج ي، مالم نره: ف، حال ما لا نراه: ق ل لب ك م.\r10 ـ الحالتين: ا ف ق ل لب ي، الحالين: ت ج ك م.\r11 ـ الشبح: ت ج ك م ي، الصورة: ق ل لب، الشيء: ف.\r12 ـ الصفة: الصفات: ق."], [443, "والمعتمد أن الوجود فى الشاهد، علة لصحة الرؤية. فيجب أن يكون فى الغائب كذلك. وهذه الدلالة ضعيفة من وجوه:\rأحدها: أن وجود الله تعالى عين ذاته وذاته مخالفة لغيره، فيكون وجوده مخالفا لوجود غيره فلا يلزم من كون وجودنا علة لصحة الرؤية، كون وجوده كذلك.\rسلمنا أن وجودنا يساوى وجود الله تعالى فى مجرد كونه وجودا، ولكن لا نسلم أن صحة الرؤية فى الشاهد مفتقرة إلى علة. فإنا بينا أن الصحة ليست أمرا ثبوتيا، فتكون عدمية. وقد عرفت أن العدم لا يعلل. سلمنا أن صحة رؤيتنا معللة فلم قلت أن العلة هى الوجود.\rقالوا: لأنا نرى الجوهر واللون وهما قد اشتركا فى صحة الرؤية والحكم المشترك لا بد له من علة مشتركة ولا مشترك إلا الوجود أو الحدوث. والحدوث لا يصلح للعلية لأنه عبارة عن وجود\r__________________\r1 ـ المعتمد: المعنمد هو: ا، لان: ا.\r2 ـ كذلك في الغائب: ك.\r3 ـ احدها: ا: ا، مخالفة: ا ج ف ق ك ل لب ي، مخالفا: م.\r4 ـ فلا: ت ج ف ق ل لب ي، فلم: ك م.\r6 ـ في: ا ت ج ف ق ك ل لب ي، و: م.\r7 ـ و: ت ج ف ي: ك لب ل م، علة: ا ت ج ف ق ك ل لب ي، العلة: م، قد بينا: في ك.\r8 ـ ليست امرا نبوتيا: ت ج ق ك لب ل م ي، نبوتية: ا، امر ثبوت: ف.\r9 ـ رؤيتنا: ت ج ق ك لب م ي، الرؤية: ف، رؤيته: ل، قلتم: ف لب.\r9 ـ رؤيتنا: ت ج ق ك لب م ي، الرؤية: ف، رؤيته: ل، قلتم: ف لب.\r10 ـ قالوا: ك ل م، قوله: ت ج، لانا: لا: ا، وهما: ت ج ف ك ي، فهما: لب، مرى بان مهما: ل، ق م.\r11 ـ له: ق، ولا: ت ج ل ق م، فلا: ك.\r12 ـ او: ا ت ج ف ق ك ي، و: ق ل لب، الحدوث: تقدم على الوجود في: ك ل لب م."], [444, "مسبوق بالعدم. والعدم السابق لا دخل له فى التأثير فبقى المستقل بالتأثير محض الوجود فيرى فنقول إنا لا نسلم أن الجوهر مرئى على ما تقدم.\rسلمنا، لكن لا نسلم أن صحة كون الجوهر مرئيا يساوى صحة كون اللون مرئيا. فلم لا يجوز أن يقال الصحتان نوعان تحت جنس الصحة. تحقيقه أن صحة كون الجوهر مرئيا يمتنع حصولها فى اللون لأن اللون يستحيل أن يرى جوهرا والجوهر يستحيل أن يرى لونا وهذا يدل على اختلاف هاتين الصحتين فى الماهية.\rسلمنا الاشتراك فى الحكم، فلم قلت إنه يلزم من الاشتراك فى الحكم، الاشتراك فى العلة. بيانه ما تقدم من جواز تعليل الحكمين المتماثلين بعلتين مختلفتين.\rسلمنا وجوب الاشتراك. فلم قلت إنه لا مشترك سوى الحدوث والوجود. وعليكم الدلالة. ثم نحن نذكره تبرعا وهو الإمكان.\r__________________\r1 ـ بالعدم: ت ج ف ق ل لب ي، بالعدم والعدم نفي مستفين: ك م، لا دمل، فلا مدخل: ق، فبقى: ا ت ج ف ك ي، فيبقى: ق ل نيام، التسمل: ج ك م، المستقبل: ت ق ل.\r5 ـ الوجود: ا، فيري، ت ج فقط، انا: ت ج، ان: ا ت ج ف ق ك ل لب، بان: ي، م.\r2 ـ برسر: ف ج ل، سلمناه: ك م.\r3 ـ يساوى سحة كرن: ا ت ج ف ق ك ل لب، يمتع حصولها: ف م ي.\r6 ـ فلم: ت ج ك ل م، ولم: ق، يقال: يكون: في ف.\r8 ـ بمنشح: ت ج ف ك ل م ي، يمنع: ا.\r9 ـ فلم: لا يقال: ق.\r10 ـ لم يبقى منهم: ف لب.\r12 ـ وثباته: ف ف.\r3، 5 ـ الاشتراك: الاشتراك في العلة: ق، قلت: قلتم: ف.\r14 ـ عليكم عليك: ا، نذكره تبرعا: ت ج، نذكر مشتركا اخر: ق، نذكره: ل م، نذكرها: ك."], [445, "ولا شك أن الإمكان يغاير الحدوث.\rفإن قلت الإمكان عدمى قلت فإمكان الرؤية أيضا عدمى، ولا استبعاد فى تعليل أمر عدمى بعدمى.\rسلمنا إنه لا مشترك سوى الحدوث والوجود. فلم قلت ان الحدوث لا يصلح للعلية.\rقوله: لأنه عبارة عن مجموع عدم ووجود. قلنا لا نسلم بل هو عبارة عن كون الوجود مسبوقا بالعدم. ومسبوقية الوجود بالعدم غير نفس العدم.\rوالدليل عليه أن الحدوث لا يحصل إلا فى أول زمان الوجود. وفى ذلك الزمان يستحيل حصول العدم. فعلمنا أن الحدوث كيفية زائدة على العدم. سلمنا أن المصحح هو الوجود.\rفلم قلت إنه يلزم من حصوله فى حق الله تعالى حصول الصحة فى حقنا. فان الحكم كما يعتبر فى تحققه حصول المقتضى يعتبر فيه أيضا انتفاء المانع. فلعل ماهية الله تعالى، أو ماهية صفة من صفاته ينافى هذا الحكم. ومما يحققه أن الحياة مصححة للجهل\r__________________\r1 ـ يغاير الحدوث: ا ت ج ك ل ي، يغاير الحدوث والرجز ف، مغاير للحدوث: ق لب م.\r2 ـ امر: ف، بمدمى: ل.\r4 ـ قلتم: في ف.\r5 ـ يصلح: ك م، يصحح: ت ج، للعلية: ف ق.\r8 ـ غير: ج ل م، عين: ت ك.\r4، 9 ـ وي ... في اول زمان: ل.\r10 ـ يستحيل: ا ت ج ف ق ك ل لب ي، مستحيل: م.\r12 ـ قلت: قلتم: ف.\r13 ـ في حقنا: ت، تحققه: تحقيقه: في ك.\r15 ـ الحياة: حياتنا: ق."], [446, "والشهوة. ثم ان حياة الله تعالى لا تصححها. إما لأن الاشتراك ليس إلا فى اللفظ أو إن اشتركا فى المعنى لكن ماهية ذات الله تعالى أو ماهية صفة من صفاته تنافيها وعلى التقديرين، فإنه يجوز فى هذه المسألة ذلك أيضا.\rسلمنا أنه لم يوجد المنافى، لكن لم لا يجوز أن يكون حصول هذه الرؤية فى عيننا موقوفا على شرط يمتنع تحققه بالنسبة إلى ذات الله تعالى. فإنا لا نرى المرئى إلا إذا انطبعت صورة صغيرة مساوية للمرئى فى الشكل فى عيننا ومن المحتمل أن يكون حصول الحالة المسماة بالرؤية مشروطا بحصول هذه الصورة. أو كان مشروطا بحصول المقابلة ولما امتنع حصول هذه الأمور بالنسبة إلى ذات الله تعالى لا جرم امتنع علينا ان نرى ذات الله تعالى.\rوالمعتمد فى المسألة الدلائل السمعية:\rأحدها أن رؤية الله تعالى معلقة باستقرار الجبل، وهو ممكن،\r__________________\r1 ـ لان: ج ك ل م، ان: ت.\r2 ـ الفظ: الفصل: ق، لو ان: ا ت ج ف ق لب، وان: ل ي، و: ك م، او (2): ت ج ك ل ق، و: م.\r3 ـ تنافيها: ا ت ج ك ي، تنافيهما: ف ق ل لب م.\r4 ـ ذلك ايضا: ج م، ايضا ذلك: ك، مثله ايضا: ل، يضما: ت.\r6 ـ ميننا: ا ت ج ف ك ل لب ي، اميتنا: ق م.\r7 ـ نرى: يدرى: ي، مساوية: ت ج ف ك ل لب ي، متساوية: م.\r8 ـ الشكل: التشكل: ا، عيننا: ا ت ج ف ك ل لب ي، اعيننا: م، من: ا ت ج ف ق ك ل لب ي، في: م، الحالة: هذه الحالة: في ق.\r9 ـ مشروطا (1): مشروط: في ق.\r11 ـ تعالى (1): ك م، علينا: ك.\r12 ـ الدلائل: الدلالة: في ل.\r13 ـ رؤية الله تعالى: الرؤية: ك، معلقة: ت ج ق ك لب م،"], [447, "والمعلق على الممكن ممكن فالرؤية ممكنة.\rفإن قيل لا نسلم أنه علق الرؤية على شرط ممكن، بل على شرط محال لأنه علقها على استقرار الجبل حال كونه متحركا، لأن صيغة إن إذا دخلت على الماضى صارت بمعنى المستقبل.\rفقوله: (فَإِنِ اسْتَقَرَّ)، أى لو صار مستقرا فى الزمان المستقبل فسوف ترانى. ثم إنه فى الزمان المستقبل، إما إن يقال إنه صار مستقرا، أو ما صار مستقرا، فإن صار مستقرا وجب حصول الرؤية لوجوب حصول المشروط عند حصول الشرط. فلما لم تحصل الرؤية بالاجماع علمنا أن الجبل، لم يستقر. وإذا لم يستقر كان متحركا ضرورة أنه لا واسطة بين الحركة والسكون. فاذن الجبل حال ما علق الله تعالى الرؤية باستقراره كان متحركا. ومعلوم أن استقرار المتحرك حال كونه متحركا محال فثبت أن الشرط ممتنع.\rفلا يلزم القطع بجواز المشروط.\rالجواب: سلمنا أن الجبل فى تلك الحالة كان متحركا لكن الجبل\r__________________\rمتعلقة: ا ف ي، معللة: ل.\r2 ـ بل: فالرؤية بل: ف.\r3 ـ الجبل حال: حالة: ق، متحركا: ا ت ج، متحركا وذلك محال: ج هامش وانما قلنا انه علفها على استقرار الجبل حال كونه متحركا: ف ق ك م ي ل هامش ج، وذلك محال وانما قلنا ذلك: لب.\r4 ـ بمعنى: ج ل م، معنى: ت.\r6 ـ انه (2): لو: ك.\r8 ـ فلما لم: فلما: ق.\r9 ـ اذا: ان: ف لب، لم يستقر (2): ا ت ج ل ي، لم يكن مستقرا: ف ق ك لب م.\r10 ـ فاذن: ت ج ف ق ك ل لب ي، فان: م.\r11 ـ تعالى: م فقط.\r12 ـ بجواز: ا ت ج ك لب ل ي، لجواز: ف ق م.\r14 ـ الجواب: ت ج ف ل لب ي، والجواب: ق ك م."], [448, "بما هو جبل يصح السكون عليه. والمذكور فى الآية ليس إلا ذات الجبل وأما المقتضى لامتناع الحركة فهو حصول السكون. فإذا القدر المذكور فى الآية منشأ لصحة الاستقرار وما هو المنشأ لامتناع الاستقرار فغير مذكور فى الآية فوجب القطع بالصحة.\rوثانيها: أن موسى عليه السلام سأل الرؤية، ولو لم تكن الرؤية جائزة لكان سؤال موسى عليه السلام جهلا وعبثا.\rوثالثها: قوله تعالى: (وُجُوهٌ يَوْمَئِذٍ ناضِرَةٌ إِلى رَبِّها ناظِرَةٌ) والنظر أما أن يكون عبارة عن الرؤية، أو عن تقليب الحدقة نحو المرئى التماسا لرؤيته. فإن كان الأول صح الغرض. وإن كان الثانى تعذر حمله على ظاهره فلا بد من حمله على الرؤية. لأن النظر كالسبب للرؤية. والتعبير بالسبب عن المسبب من أقوى وجوه المجاز.\rلا يقال لم كان ذلك التأويل أولى من تأويلنا وهو أن يكون إلى واحد الآلاء، فيكون المراد. وجوه يومئذ ناظرة: نعمة ربها أى\r__________________\rالاستقبال: ف ك.\r1 ـ بما هو: من حيث هو: ا، جبل: الجبل: ك.\r2 ـ الحركة: ا ت ج ل لب ق، السكون: ك ف م ي.\r3 ـ العدر المذكور: ا ت ج ك ف ل لب ي، القدرة المذكورة: ق.\r4 ـ فغير: ت ج ف ق ل لب م ي، يعنى: ا.\r5 ـ والسلام: م، ولو: فلو: ت.\r6 ـ جهلا وعينا: ا ت ج ف ق ي ل، جهلا او عبثا: ك لب، فلما: م.\r7 ـ وثالثها: وج: ا، ثالثها: ج، تعالى: ف، ناضرة: ف ق ي، الى ربها ناظرة: ي، سورة القيامة: 22.\r8 ـ التغيير: التغيير: ف، بالسبب عن المسبب: عن المسبب جايز وهو: ق.\r9 ـ ذلك: كذلك: ا، اولى: اقوى: ك.\r11 ـ الالاء فيكون: الا فكون: ف، ناظرة ناظر: ت اي م: ت ف ج ق ك م ي، ناضرة الى وبها ناظرة اي نعمة:"], [449, "منتظرة، أو نقول المراد إلى ثواب ربها ناظرة.\rلانا نقول أما الأول فباطل. لأن الانتظار سبب الغم، والآية مسبوقة لبيان النعم.\rوأما الثانى فالنظر إلى الثواب لا بد وان يحمل على رؤية الثواب وإلا فتقليب الحدقة نحو الثواب من غير الرؤية لا يكون من النعم البتة. وإذا وجب اضمار الرؤية لا محالة كان اضمار الثواب اضمارا للزيادة من غير دليل. فوجب أن لا يجوز.\rاحتج الخصم بأمور أحدها:\rقوله تعالى: (لا تُدْرِكُهُ الْأَبْصارُ) والاستدلال به من وجهين.\rالأول: أن ما قبل هذه الآية وما بعدها مذكور فى معرض المدح، فوجب أن تكون هذه الآية أيضا مدحا. فإن إلقاء ما ليس بمدح فيما بين المدحين ركيك، كما يقال فلان أجل الناس، وآكل الخبز،\r__________________\r1، ناظرة الى نعمة ربها: لب، ناظرة الى ربها ناظرة نعمة ربها الى منتظرة: ل.\r1 ـ نقول: يقول: ت، المراد: المراد انه: ف.\r4 ـ فالنظر: فاما النظر: ك.\r5 ـ فتغليب: ينقلب: ق، الرؤية: رؤية: ق.\r6 ـ انمار (2): ا، اضمارا: ف.\r7 ـ للزيادة: لزيادة: ي.\r8 ـ احتج: واحتج: ج، بامور احدها: ت ج ف ق ك ل لب م ي، بوجوه ا: ا.\r9 ـ سورة الانعام: 102، وهو يدرك الابصار: ك، بها: ك.\r9، 10 ـ من وجهين: تكرر في ق.\r11 ـ الاول ا: ا، احدهما: ق، هذه: ت.\r12 ـ ايضا: ت ج ل ك ق: م، مدحا: لي، القناء ج ك ل م، توسط: ق.\r13 ـ فلدحين: المدح: ف."], [450, "وأستاذ الوقت. وإذا كان نفى الإدراك مدحا كان ثبوته نقصا. والنقص على الله تعالى محال.\rالثانى: أن قوله تعالى (لا تُدْرِكُهُ الْأَبْصارُ) يقتضي أن لا تدركه الأبصار فى شيء من الأوقات، لأن قولنا تدركه الأبصار يناقض قولنا لا تدركه الأبصار، بدليل إنه يستعمل كل واحد من القولين فى تكذيب الآخر. وإذا صدق أحد النقيضين كذب الآخر، فوجب كذب قولنا: «تدركه الأبصار». وإذا ثبت ذلك ثبت كذب قولنا يدركه بصر واحد، أو بصران ضرورة أن لا قائل بالفرق.\rوثانيها: انه تعالى لو كان مرئيا لرأيناه الآن.\rوثالثها: أنه لو كان مرئيا لكان مقابلا أو فى حكم المقابل.\rوقولنا فى حكم المقابل احتراز عن رؤية الإنسان وجهه فى المرآة، وعن رؤية الأعراض والله أعلم.\rوالجواب عن الأول انا نقول بموجب الآية لأن الادراك، هو\r__________________\r1 ـ الوقت: ت ج ل ق لب م ي، القوم: ف، البشر: ك.\r2 ـ تعالى: ك فقط.\r3 ـ الثاني ان: ت ج ف ق ل لب م ي، ب: ا، الثاني: ك.\r4، 5 ـ في شيء .. لا تدركه الابصار: ت.\r5 ـ انه .... الفولين: ان كل واحد من القولين يستعمل: ك.\r6 ـ واذا: فاذا: ف، كذب (2): ا.\r7 ـ ندركه: ا ت ج ف ق ل لب ي، لا تدركه: ك م، واذا فاذا: ا.\r8 ـ ان: انه: ا ف لب، لا فائل: لا قائل يقابل: ف.\r7، 8 ـ بصر .. بصران: ج ل ك م، بصير .. بصير: ت.\r9 ـ ثانيها: ب: ا، انه تعالى: ف.\r10 ـ ثالثها: ج: ا.\r11 ـ احتراز: احتراظ: ت.\r12 ـ والله اعلم: ا.\r13 ـ الجواب: في ف، الاول: ا: ا."], [451, "رؤية الشيء من جميع جوانبه، لأن أصله من اللحوق. وذلك انما يتحقق فى المرئى الّذي يكون له جوانب. ولما كان ذلك فى حق الله تعالى محالا، لا جرم يستحيل أن يكون مدركا فلم قلت إنه ليس بمرئى.\rوعن الثانى انا بينا أن عند حضور المرئى وحصول الشرائط لا تجب الرؤية. سلمنا وجوبها فى المرئيات التى فى الشاهد دفعا للتشنيعات التى يذكرونها. فلم قلت إنها واجبة فى رؤية الله تعالى. فإن رؤية المخلوقات مخالفة لرؤية الله تعالى. ولا يلزم من وجوب حصول رؤية المخلوقات عند حصول الشرائط وجوب رؤية الله تعالى عند حصول تلك الشرائط.\rوعن الثالث أن قولهم: المرئى يجب أن يكون مقابلا أو فى حكم\r__________________\r1 ـ اصله: اصله انما هو. ف.\r2 ـ ذلك: ف.\r2، 3 ـ ولما تعالى: ج محالا: ت ج ف ق ك ل م ي، وذلك في حق الله محال: لب.\r3 ـ لا جرم: فلا جرم: لب: ف، قلت: قلتم: ف.\r5 ـ حضور: ت ج ف ك لب م ي، حصول: ق ل، وحصول حصول: ل، عند حصول: ف.\r6 ـ تجب: يوجب: ا، سلما: ج م، ولئن سلمنا: ق لب، ولو تم: ي سلمنا: ك ي، وعن الثالث سلمنا: ت، او عن الثالث: ل، وجوبها: ك.\r7 ـ قلت: قلتم: ف ق.\r7، 8 = الله تعالى فان وان: ت: ا ت ج ف ق ك ل لب ي الصانع وان: م.\r8 ـ رؤية المخلوقات: ت ج ق ك لب ل م ي، رؤيته: ف. الله تعالى: ت ج ق ك ل لب م ي، المخلوقات: ف.\r9 ـ حصول (1): ت ج ف، حضور: ق ك ل م، حصول (2): ت ج، حضور: ك م.\r9، 10 ـ وجوب رؤية الله تعالى عند حصول الشرائط: ل.\r10 ـ عند حصول الشرائط: ف، عند: ولا عند: ا، تلك: لب.\r11 ـ وعن الثالث ان: ت، المرئي: ت ج ك ف م، ل."], [452, "المقابل عين المتنازع فيه أو نقول: هب أنه يجب أن يكون كذلك فى الشاهد فلم قلت إنه يجب أن يكون كذلك فى الغائب وتقريره ما ذكرناه الآن وبالله التوفيق.\rمسئلة:\rالإله تعالى واحد لأنا لو قدرنا إلهين، لكان اما أن يصح من أحدهما أن يفعل فعلا، على خلاف الآخر، أو لا يصح. فإن صح فليقدر ذلك لأن ما ليس بممتنع لا يلزم من فرض وقوعه محال. وإلا لكان ممتنعا لا ممكنا. وعند وقوع ذلك الاختلاف، فاما أن يحصل مرادهما فيكون الجسم الواحد متحركا ساكنا أو لا يحصل مرادهما وهو أيضا محال. لأن المانع من حصول مراد كل واحد منهما حصول مراد الآخر فامتناع مراد كل واحد منهما يتوقف على حصول مراد الآخر. فلو امتنعا معا لوجدا معا، وهو محال أو يحصل\r__________________\r1 ـ عين: ت ج ف ق ك لب م ي، على: ا، غير: ل، فيه: ت ج ت ق ك ي، ل لب م، هب: ا ت ج ف ق ك ل لب م، هب: ا ت ج ف ق ك ل لب ي، تمت، م.\r2 ـ قلت قلتم: ف.\r3 ـ ذكرناه: ت ج ف ق ك م ي، ذكرنا، ا ل، الان، ل م، وبالله التوفيق: ك لب: ت ج ف ق ي.\r5 ـ تعالى: تبارك وتعالى: ق.\r7 ـ فليقدر: ا ت ج ف ق ك لب ي، فلنفرض: ل، فلنذر: م، يممتنع: ت ج ف ق لب ل ي، يمتنع: م.\r8 ـ فلما: ت ج ق ك لب م ي، اما: ا.\r9 ـ فيكون: فيلزم ان يكون: ف، الواحد: ت ل ي، متحركا: ت ج ف ك لب م، المتحرك: ل ي، ساكنا: وساكنا: ا، ساكنا وهو محال: ق لب م.\r10 ـ ايضا: ي، حصول: ت ج، وجود: ك م: ل.\r11 ـ منهما (1): ف، حصول: ج، وجود: ت ف ك ل لب ي، وقوع: ا، منهما (2): ي، يتوقف: ا ق ك، متوقف: ف لب ل م ي.\r11، 12 ـ فامتناع ... الاخر: ت."], [453, "مراد أحدهما دون مراد الثانى، وهو أيضا محال. لأن كل واحد منهما قادر على ما لا نهاية له، فلا يكون أحدهما أولى بالرجحان. ولأن الّذي لا يحصل مراده يكون عاجزا، فعاجزيته إن كانت أزلية فهو محال، لأن العجز إنما يعقل عما يصح وجوده، ووجود المخلوق الأزلى محال. فالعجز عنه أزلا أيضا محال. وان كانت حادثة، فهو محال لأن هذا إنما يعقل، لو كان قادرا فى الأزل ثم زالت قادريته وذلك يقتضي عدم القديم، وهو محال.\rوأما ان امتنعت المخالفة، فهو باطل، لأنه إذا كان كل واحد منهما قادرا على جميع المقدورات، والقادر يصح منه فعل مقدوره. فحينئذ يصح من هذا فعل الحركة لو لا الآخر. ومن الآخر فعل السكون لو لا هذا فما لم يقصد أحدهما إلى الفعل لا يتعذر على الآخر القصد إلى ضده لكن ليس تقدم قصد أحدهما على الآخر أولى من العكس. فإذن يستحيل أن يصير قصد أحدهما مانعا للآخر من القصد فصحت المخالفة.\rفإن قيل لم لا يجوز أن يقال أنهما لكونهما حكيمين لا يريدان\r__________________\r(12/ 452) ـ اوجدا: لوجب: ق.\r1 ـ مراد الثاني: ت ج ق م ي ل، الثاني: لب، الاخر: ف ك، محال: باطل: ك.\r2 ـ بالرجحان: بالرجحان من الاخر: ق.\r4، 5 ـ المخلوق الازلي: ت ج ف ق ل لب ي، المخلوقات الازلية: ك، المخلوقات للازلي: ا.\r5 ـ ايضا: ق فقط.\r6 ـ لو: ان لو: ف ق.\r9 ـ مقدوره: مقدور: ي.\r10 ـ لولا: اولا: ت، فعل: ا ت ج ف ق ك ل لب ي، فعله م.\r12 ـ ضده: ا ت ج ف ق ك ل لب ي، فعله: م.\r14 ـ فصحت: ح ف ق ك ل لب ي، وصحة: ت م.\r15 ـ انهما: ا ت ج ف ق ك لب ل ي، ايهما: م، حكيمين: حكمين: ت."], [454, "إلا الأصلح وذلك الأصلح واحد، فلا جرم، يجب توافقهما.\rقلنا الفعل إما أن يتوقف على الداعى أو لا يتوقف. فإن توقف على الداعى، استحال من العبد أن يختار الفعل القبيح، إلا إذا خلق الله تعالى فيه داعيا يدعوه إليه. وإذا كان الداعى إلى القبيح موجبا للقبيح كان قبيحا. وإذا كان الفاعل لذلك الداعى هو الله تعالى لم يجب أن يكون فعل الله تعالى حسنا بالتفسير الّذي تريدونه. فلم يلزم اتفاق الإلهين على الفعل الواحد، فصحت المخالفة بينهما.\rوإن لم يتوقف الفعل على الداعى جاز فى الضدين المتساويين فى الحسن والقبيح ان يختار أحد الإلهين ايجاد أحدهما، والإله الآخر إيجاد الآخر وحينئذ تحصل المخالفة بينهما. وبالله التوفيق.\r__________________\r(15/ 453)، 1 ـ يريدان الا، لا سلح: ا ب ت ف ق ك لب ل ي، يريد: م.\r1 ـ قلنا: قلب: ق، عليه قلنا: ك.\r2 ـ استعال: ا ت ج ف ق ك ل لب ي، لا محال: م، الفعل فعل: ا ك.\r4 ـ تعالى: م، اذا: ب: ق.\r5 ـ للقبيح: ا ت ج ف ق ك ل لب ي، للقبح: م، ضبيحا: ا ت ج ب ف ق ل لب ي، ضنا: م، تعالى: ك.\r6 ـ تعالى: ق م، بالتغيير، على التغيير: ي.\r8 ـ على: م فقط.\r9 ـ الحسن والقبيح: ت، الحسن والقبح: ج ك ل م، الاخر الاخرى: ا.\r10 ـ ايجاد الاخر: ت، الاخر: المنافى: ا، بينهما: ق، الله انتم فيق: ك ل."], [455, "القسم الثالث\r"]], "pg": [378, 455]}, "687.12": {"x": [[455, "الكلام فى الأفعال\rمسئلة:\rزعم أبو الحسن الأشعرى رضى الله عنه أنه لا تأثير لقدرة العبد فى مقدوره أصلا بل القدرة والمقدور واقعان بقدرة الله تعالى وزعم القاضى أبو بكر الباقلانى ان ذات الفعل واقعة بقدرة الله تعالى وكونه طاعة ومعصية صفات تقع بقدرة العبد. وزعم الأستاذ أبو إسحاق أن ذات الفعل تقع بالقدرتين. وزعم أمام الحرمين ان الله تعالى يوجد للعبد القدرة والإرادة، ثم هما يوجبان وجود المقدور وهذا قول الفلاسفة، ومن المعتزلة قول أبى الحسين البصرى.\rوزعم الجمهور من المعتزلة ان العبد موجد لأفعاله لا على نعت الإيجاب بل على صفة الاختيار.\r__________________\r2 ـ الكلام: ت ج ف ق ل لب ي: ك م.\r4 ـ رضي الله عنه: ت ل، رحمه الله: ج ق.\r5 ـ المقدور: المقدورات: ت.\r6 ـ ابو بكر الباقلاني: ف فقط.\r7 ـ ومعصية: معصية: ق، صفات تقع: ا ت ج ف ق ل لب، صفتان نقع: ك ي، م.\r8 ـ ذات الفعل: ت ج ق ك ل لب ي، ذات الفعل وصفاته م، الفعل: ف.\r9 ـ يوجد: ت ج ف ق لب، يوجب: ا، موجد: ل م، هو موجد: ك، هذا: ت ف ق لب ل ي، هذا هو: ج، هو: ك م.\r10 ـ الحسين: ت ج ف ق ك لب، الحسن: ل م ي.\r11 ـ لافعاله: لافعال نفسه: ك."], [456, "لنا وجوه: الأول ان العبد حال الفعل اما أن يمكنه الترك أو لا يمكنه. فان لم يمكنه الترك فقد بطل قول المعتزلة. وان أمكنه، فاما أن لا يفتقر ترجيح الفعل على الترك إلى مرجح، وهو باطل. لأنه تجويز أحد طرفى الممكن على الآخر لا لمرجح، أو يفتقر. وذلك المرجح إن كان من فعله عاد التقسيم، ولا يتسلسل، بل ينتهى الى مرجح لا محالة، لا يكون من فعله. ثم عند حصول ذلك المرجح ان أمكن أن لا يحصل ذلك الفعل، فليفرض ذلك الفعل غير حاصل فحينئذ يحصل الفعل تارة، ولا يحصل أخرى، مع أن نسبة ذلك المرجح إلى الوقتين سواء. فاختصاص أحد الوقتين بالحصول والآخر بعدم الحصول يكون ترجيحا لأحد طرفى الممكن المتساويين على الآخر من غير مرجح، وهو محال.\rوان امتنع أن لا يحصل فقد بطل قول المعتزلة بالكلية، لأنه متى\r__________________\r1 ـ الكلام: ت ج ف ق ل لب ي: ك م.\r2 ـ رضي الله عنه: ت ل، رحمه الله: ج ق.\r3 ـ المقدور: المقدورات: ت.\r4 ـ ابو بكر الباقلاني: ف فقط.\r5 ـ ومعصية: معصية: ق، صفات تقع: ا ت ج ف ق ل لب، صفتان نقع: ك ي، م.\r6 ـ ذات الفعل: ت ج ق ك ل لب ي، ذات الفعل وصفاته م، الفعل: ف.\r7 ـ يوجد: ت ج ف ق لب، يوجب: ا، موجد: ل م، هو موجد: ك، هذا: ت ف ق لب ل ي، هذا هو: ج، هو: ك م.\r8 ـ فلينئد: ت ج ف ق ك ل لب ي، وحينئذ: م.\r9 ـ فيوم الى ت ج ل ي، على السواء: ق ك لب م، على السوية: ان.\r10 ـ والاخر: ا ت ج ف ل ي، ووقت الوقت: ق ك لب ملا ق ك لب م، المتساوين: ت ج ق ك، المتساوي: م:"], [457, "حصل المرجح وجب الفعل. ومتى لم يحصل، امتنع. فلم يكن العبد مستقلا بالاختيار وهذا كلام قاطع.\rالثانى لو كان العبد موجدا لأفعال نفسه، لكان عالما بتفاصيلها إذ لو جوزنا الايجاد من غير علم لبطل دليل اثبات عالمية الله تعالى ولأن القصد الكلى لا يكفى فى حصول الجزئى. لأن نسبة الكلى إلى جميع الجزئيات على السواء، فليس حصول بعضها أولى من حصول الباقى. فثبت أنه لا بد من القصد الجزئى، وهو مشروط بالعلم الجزئى. فثبت أنه لو كان موجدا لأفعال نفسه، لكان عالما بتفاصيلها، لكنه غير عالم بتفاصيلها اما أولا ففى حق النائم، وأما ثانيا فلأن الفاعل للحركة البطيئة قد فعل السكون فى بعض الاحياز، والحركة فى بعضها مع إنه لا شعور له بالسكون وأما ثالثا فلأن عند أبى على وأبى هاشم، مقدور العبد ليس نفس التحصيل فى الحيز، بل علة ذلك التحصيل مع إنه لا شعور لأكثر الخلق بتلك العلة لا جملة ولا تفصيلا.\rالثالث: اذا أراد العبد تسكين جسم. وأراد الله تعالى تحريكه\r__________________\r1 ـ المرجح: الترجح: ك.\r2 ـ وهذا: ا ت ج ف ق ل لب ي، فهذا: م، هذا: ك.\r3 ـ الثاني: ب، ا، موجدا: ا ت ج ف ق ك ل لب، موجبا: م.\r4 ـ من غير: ت ج ل ك، لا عن: ق، علم: ت ف ق ل م ي، العلم: ا ك لب، لبطل: ت ج ف ق ل ي، بطل: ك ل.\r5 ـ ولان: لان: م فقط.\r6 ـ الكلي: الكل: ا فقط، الجزئيات: الممكنات: ا فق.\r7 ـ حصول: ف، الباقي: البعض: ق.\r9 ـ اما: ا ت ج ف ل لب ك، فلا يكون موجدا اما: م.\r10 ـ ثانيا: الثاني: ك، فعل: يفعل: ج ف.\r11 ـ الاحياز: ت ج ف ل م، الاخسار: ا، الاحيان: ق، ا، ي، واما: اما: م فقط.\r15 ـ الثالث: ج: ا، الرابع: ك، جسم و: ا ج ف ق ل"], [458, "فاما أن لا يقعا، وهو محال. لأن المانع من وقوع كل واحد منهما وجود مراد الآخر فلو امتنعا معا لوجدا معا أو يقعا معا، وهو محال. أو يقع أحدهما دون الآخر، وهو باطل. لأن القدرتين متساويتان فى الاستقلال بالتأثير فى ذلك المقدور الواحد. والشيء الواحد، وحدة حقيقية لا يقبل التفاوت. فاذن القدرتان بالنسبة إلى اقتضاء وجود هذا المقدور على السوية إنما التفاوت فى أمور أخر خارجة عن هذا المعنى. وإذا كان كذلك امتنع الترجيح.\rاحتج الخصم بالمعقول والمنقول. أما المعقول فهو أن فعل العبد لو كان بخلق الله تعالى، لما كان متمكنا من الفعل البتة. لأنه ان خلقه الله تعالى فيه لكان واجب الحصول، وإن لم يخلقه الله تعالى فيه كان ممتنع الحصول. ولو لم يكن العبد متمكنا من الفعل والترك، لكانت أفعاله جارية مجرى حركات الجمادات. فكما أن البديهة\r__________________\rلب، جسم، ت، الجسم و: م، تعالى: ا ف ق ل،: ت ج لب م ي.\r1 ـ يقعا: يقعا معا: م، منهما: ج ف ق ك لب م: ت ل ي.\r2 ـ لوجدا .. عما: ت ج ف ق ك لب ي، لوجد معا وهو محال او يقعا معا: ل، لوقعا معا: م.\r1، 3 ـ لان ... وهو محال: ا.\r4 ـ متساويتان: ت ج ف ق ك ل لب م ي، متساويتين: ا، بالتاثير، بالتاثير: م فقط.\r5 ـ انما: وانما: ك ل، امور: امر: ك.\r6 ـ خارجة: ت ج ل م، خارجية: ق، خارج: ك.\r7 ـ فهو: ج ق ك ل لب م، وهو: ف، هو: ت ي.\r8 ـ بخلق: لخلق: ق.\r8، 9 ـ لما كان .. تعالى: ت ج ق ك ل م ي، لانه ان خلقه الله: لب: ف.\r9 ـ لكان: ت ج، كان: ك م، يخلقه: ت ج ف ق ك ل ي، بخلق: لب م الله تعالى: ج ق.\r10 ـ ولو: ت ج ل م ي، فلو: ف لب.\r11 ـ لكانت: ت ج ق ك ل م ي، لكان: لب، كانت: ف، حركات: حركة: ا، فكما ان: ت ل، وكما ان: ج ف ق لب م،"], [459, "جازمة بأنه لا يجوز أمر الجمادات ونهيها ومدحها وذمها، وجب أن يكون الأمر كذلك فى أفعال العباد. ولما كان ذلك باطلا، علمنا كون العبد موجدا.\rوالجواب إنه لازم عليكم. لأن الأمر إن توجه حال استواء الدواعى، ففى تلك الحالة يمتنع الترجيح وان توجه حال الرجحان، فهناك الراجح واجب، والمرجوح ممتنع. ولأن ذلك الفعل، ان علم الله تعالى وجوده فهو واجب، وان علم الله تعالى عدمه فهو ممتنع فثبت أن الإشكال وارد على الكل: وان الجواب هو انه تعالى: (لا يُسْئَلُ عَمَّا يَفْعَلُ وَهُمْ يُسْئَلُونَ) وبالله التوفيق.\rوأما المنقول، فقد احتجوا بكتاب الله تعالى فى هذه المسألة من عشرة أوجه:\rالأول: ما فى القرآن من اضافة الفعل إلى العباد كقوله تعالى:\r__________________\rوكمال: ا، البديهة: البديهية: ك.\r1 ـ الجمادات ونهيها ومدحها وذمها: ت ج ل ف ي، الجهاد ا ت: لب ونهيه ومدحه وذمة: ق لب م.\r3 ـ موجدا: موجدا لا فعاله: ف.\r4 ـ والجواب: ت ج ق ك م ي، الجواب: ل لب ف الامر: ت ج ل م، التكليف: ف ك لب ي.\r4، 5 ـ حال ... وان توجه: ل، يوجد: ك م، توجد: ت.\r5 ـ الدواعي: ت ج، الداعي: ك م، الحالة: ا ت ج ف ت لب، الحال: ك م ي، يمتنع: ت ج ف ق ك لب ي، امتنع: توجه: ج.\r6 ـ ولان: الان: ف واجب الوجود ... ممتنع الوجود ق.\r7 ـ تعالى: ا ف ق ك لب ل ي: ت ج م الله تعالى ا: ا ف ق لب م ي: ت ج ك ل.\r8 ـ انه تعالى: ت ج ق ك ي، انه: ا ف، ان الله تعالى: لب.\r9 ـ وهم يسالون: ق ل، ت ج ف م ي، سورة الانبياء: وبالله التوفيق: ا ك لب.\r23 ـ الاول: ا: ا."], [460, "(فَوَيْلٌ لِلَّذِينَ يَكْتُبُونَ الْكِتابَ بِأَيْدِيهِمْ). (إِنْ يَتَّبِعُونَ إِلَّا الظَّنَّ)، (ذلِكَ بِأَنَّ اللهَ لَمْ يَكُ مُغَيِّراً نِعْمَةً أَنْعَمَها عَلى قَوْمٍ حَتَّى يُغَيِّرُوا ما بِأَنْفُسِهِمْ)، (بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْراً)، (فَطَوَّعَتْ لَهُ نَفْسُهُ قَتْلَ أَخِيهِ)، (مَنْ يَعْمَلْ سُوءاً يُجْزَ بِهِ)، (كُلُّ امْرِئٍ بِما كَسَبَ رَهِينٌ)، (وَما كانَ لِي عَلَيْكُمْ مِنْ سُلْطانٍ إِلَّا أَنْ دَعَوْتُكُمْ).\rالثانى: ما فى القرآن من مدح المؤمن على الإيمان، وذم الكافر على الكفر، ووعد الثواب على الطاعة، والعقاب على المعصية. كقوله تعالى: (الْيَوْمَ تُجْزى كُلُّ نَفْسٍ بِما كَسَبَتْ)، (الْيَوْمَ تُجْزَوْنَ ما كُنْتُمْ تَعْمَلُونَ)، «وَإِبْراهِيمَ الَّذِي وَفَّى أَلَّا تَزِرُ وازِرَةٌ وِزْرَ أُخْرى»، (لِتُجْزى كُلُّ نَفْسٍ بِما تَسْعى)، (هَلْ جَزاءُ الْإِحْسانِ إِلَّا الْإِحْسانُ)، (هَلْ تُجْزَوْنَ إِلَّا ما كُنْتُمْ تَعْمَلُونَ)، (مَنْ جاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثالِها)، (وَمَنْ أَعْرَضَ عَنْ ذِكْرِي)، «أُولئِكَ الَّذِينَ\r__________________\r(12/ 459)، ا ـ تعالى فويل: ف.\r1 ـ يكتبون: يكتمون: ف، بايديهم: ا ت ف ج، سورة البقرة: 79.\r2 ـ سورة النجم: 28، ثم يك: لم يكن: ق.\r3 ـ سورة الانفال: 53، سورة يوسف: 18.\r4 ـ سورة المائدة: 20، يصل سوءا: عمل من سوء: ف، سورة النساء: 123.\r5 ـ سورة الطور: 21، و: النسخ كلها، فاستجبتم لي: ك فقط، سورة ابراهيم: 22.\r6 ـ الثاني: ب: ا.\r8 ـ بما كسبت: ف ي، ما كسبت: ك م، ا ق لب ج ل، سورة غافر: 17 واليوم: في ف.\r9 ـ ما: ا ت ج ل ي، بما: ف ق ك م، سورة الجاثية: 28.\r10 ـ سورة النجم: 7 3، 38 لتجزى: ت سورة طه: 15.\r10، 11 ـ هل جزاء الاحسان الا الاحسان: ق ك م: ت ج ف ل لب ي.\r11 ـ سورة الرحمن: 60، وهل: ف لب م ي، الا: ا، سورة النمل: 9.\r12 ـ سورة الانعام: 160 وفي ك: ومن جاء بالسيئة فلا يجزي"], [461, "اشْتَرَوُا الْحَياةَ الدُّنْيا»، (إِنَّ الَّذِينَ كَفَرُوا بَعْدَ إِيمانِهِمْ).\rالثالث: الآيات الدالة على أن أفعال الله تعالى منزهة عن أن تكون مثل أفعال المخلوقين من التفاوت والاختلاف، والظلم.\rأما التفاوت، فكقوله تعالى: «ما تَرى فِي خَلْقِ الرَّحْمنِ مِنْ تَفاوُتٍ» «الَّذِي أَحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ». والكفر والظلم ليس بحسن. وقوله تعالى: (وَما خَلَقْنَا السَّماواتِ وَالْأَرْضَ وَما بَيْنَهُما إِلَّا بِالْحَقِّ). والكفر ليس بحق وقوله: (إِنَّ اللهَ لا يَظْلِمُ مِثْقالَ ذَرَّةٍ)، «وَما رَبُّكَ بِظَلَّامٍ لِلْعَبِيدِ» «وَما ظَلَمْناهُمْ»، (لا ظُلْمَ الْيَوْمَ)، (وَلا يُظْلَمُونَ فَتِيلاً).\rالرابع: الآيات الدالة على ذم العباد على الكفر، والمعاصى كقوله تعالى: (كَيْفَ تَكْفُرُونَ بِاللهِ) والإنكار والتوبيخ مع العجز عنه محال. وعندكم أنه تعالى خلق الكفر فى الكافر وأراد منه، وهو\r__________________\rالا مثلها، سورة طه: 127 فان له معيشة ضنكا، ق فقط.\r1 ـ سورة البقرة: 86 بالاخره: ف ق ك ي، سورة آل عمران: 90، وان: في ف،: لب.\r2 ـ الثالث: ج: ا.\r3 ـ مثل: ف، المخلوقين: العباد: ك، الظلم: ا ت جف ق ك ل لب ي، العلم: م.\r4 ـ اما التفاوت: ف، فكفولة: ت ج ف ق ك ل لب ي، فلقوله: م، سورة الملك: 3.\r5 ـ سورة السجدة: 22 ثم هدى: ل والظلم: ت ج ف ك ل ي، ق لب م.\r6 ـ تعالى و: ك لب، و: ت ج ف ق ل ي، م، السماء ف لب ي ت ج ل، السماوات: ق ك م سورة الاحقاف: 2.\r7 ـ سورة النساء: 22.\r8 ـ سورة فصلت: 46، سورة هود: 101، سورة المؤمن: 17.\r9 ـ سورة النساء: 49.\r10 ـ الرابع: ا، كقوله: ج ك ل م، بقوله: ت.\r11 ـ كيف: وكيف: ف، سورة البقرة: 28.\r12 ـ اراد: ا ت ج ف ق ك ل لب، ارادة: م ي."], [462, "لا يقدر على غيره فكيف يوبخه عليه.\rواحتجوا فى هذا الباب بقوله تعالى: (وَما مَنَعَ النَّاسَ أَنْ يُؤْمِنُوا إِذْ جاءَهُمُ الْهُدى) وهو إنكار بلفظ الاستفهام. ومعلوم أن رجلا لو حبس آخر فى بيت بحيث لا يمكنه الخروج عنه ثم يقول له: منعك من التصرف فى حوائجى، كان ذلك منه مستقبحا. وكذا قوله تعالى: (وَما ذا عَلَيْهِمْ لَوْ آمَنُوا بِاللهِ). وقوله لإبليس: (ما مَنَعَكَ أَنْ تَسْجُدَ) وقول موسى عليه السلام لأخيه: (ما مَنَعَكَ إِذْ رَأَيْتَهُمْ ضَلُّوا) وقوله تعالى: (فَما لَهُمْ لا يُؤْمِنُونَ)، (فَما لَهُمْ عَنِ التَّذْكِرَةِ مُعْرِضِينَ)، (عَفَا اللهُ عَنْكَ لِمَ أَذِنْتَ لَهُمْ)، (لِمَ تُحَرِّمُ ما أَحَلَّ اللهُ لَكَ).\r__________________\r1 ـ احتجوا: في ك.\r2 ـ سورة الاسراء: 94، اذ: اذا: في ف معلوم: معلوما.\r3 ـ حبس: حبسه: لب، حلبس: ا، آخر في بيت: ت ج، ادخر في بيته: لب، اخر من بيت: ق م، يمكنه: ت ج لب م ي، يمكن: ا، عنه: ا ت ج ف ق ك ل لب ي، منه له: ت ج ق ل م، ف ك لب ي.\r4 ـ من: عن: في ي، في حوائجي: ت ج ق ل لب م، في ك، ف، في جوانب الحي: ك: ي، منه مستقبحا: ت ج ك ل لب م، منه مستقما: ي، مستقبحا منه: ف، وكذا: ت ق ل م، وكذلك: ك.\r6 ـ تعالى: ق ك م، ت ج ف ل لب ي سورة النساء بالله: لب م، لابليس: ك.\r7 ـ سورة ص 75 لما خلقت: ق عليه السلام: ا ت ج ك ل ب: ق م، لاخيه هارون: ك ي، عليهما السلام: ق، لاخيه لب.\r8 ـ قوله فما لهم لا يؤمنون تقدم على قول موسى في: ف اذ: ج ك ل لب م، اذا: ت ف، ضلوا: ضلوا: ف، سورة طه: 93، قوله تعالى: ت ق ل، قولهم تعالى: ج الاسقاق: 20.\r9 ـ سورة المدثر: 49، سورة التوبة: 43.\r10 ـ سورة التحريم: ا، لك: لك تبتغى: ا فقط."], [463, "وكيف يجوز أن يقول لم تفعل مع أنه ما فعله.\rوقوله: «لِمَ تَلْبِسُونَ الْحَقَّ بِالْباطِلِ» «لِمَ تَصُدُّونَ عَنْ سَبِيلِ اللهِ».\rوقال الصاحب بن عباد فى فصل له فى هذا المعنى كيف يأمر بالإيمان ولم يرده. وينهى عن الكفر وأراده، ويعاقب على الباطل، وقدره وكيف يصرفه عن الإيمان، ثم يقول: (فَأَنَّى تُصْرَفُونَ) ويخلق فيهم الإفك ثم يقول: (فَأَنَّى تُؤْفَكُونَ) وأنشأ فيهم الكفر ثم يقول (لِمَ تَكْفُرُونَ) وخلق فيهم لبس الحق بالباطل ثم يقول (لِمَ تَلْبِسُونَ الْحَقَّ بِالْباطِلِ) وصدهم عن السبيل ثم يقول (لِمَ تَصُدُّونَ عَنْ سَبِيلِ اللهِ) وحال بينهم وبين الإيمان، ثم قال (وَما ذا عَلَيْهِمْ لَوْ آمَنُوا بِاللهِ) وذهب بهم عن الرشد ثم قال (فَأَيْنَ تَذْهَبُونَ) وأضلهم فى الدين، حتى أعرضوا. ثم قال (فَما لَهُمْ عَنِ التَّذْكِرَةِ مُعْرِضِينَ).\rالخامس: الآيات التى ذكر الله تعالى فيها تخيير العباد فى أفعالهم\r__________________\r8، 9 (462) ـ فما لهم عن التذكرة معرضين تقدم على فما لهم لا يؤمنون في: ا ك.\r2 ـ سورة آل عمران: 71، تلبسون .. تصدون: ا ج ق ك لب ف ي، يلبسون .. يصدون: ت م، يلبسون .. تصدون: ل تصدون تقدم على تلبسون في: ق.\r3 ـ سورة آل عمران: 99.\r4 ـ الصاحب: ت ج ق ك ل لب م ي، صاحب بن عباد: ف.\r6 ـ سورة الزمر: 6.\r7 ـ تؤفكون: ي، سورة الانعام: 95.\r8 ـ بقول (2): قال: ك م.\r8، 9 ـ ثم يقول لم تلبسون الحق بالباطل: ت.\r9 ـ وصدهم: فصدهم: ي، يقول: قال: م فقط.\r11 ـ بالله: ت ج ل م، بالله واليوم الاخر: ك: ف ق لب ي، فاين: ا ت ج ك لب ي، فانى: م ي.\r11، 12 ـ ثم قال (1) .. ثم قال (2): ل.\r14 ـ الخامس: ه: ا ذكر: ذكرها: ق، ذكره: ف، فيها"], [464, "وتعليقها بمشيئتهم.\rفمنها قوله تعالى «فَمَنْ شاءَ فَلْيُؤْمِنْ وَمَنْ شاءَ فَلْيَكْفُرْ» «اعْمَلُوا ما شِئْتُمْ» «اعْمَلُوا فَسَيَرَى اللهُ عَمَلَكُمْ» «لِمَنْ شاءَ مِنْكُمْ أَنْ يَتَقَدَّمَ أَوْ يَتَأَخَّرَ» «فَمَنْ شاءَ ذَكَرَهُ» «فَمَنْ شاءَ اتَّخَذَ إِلى رَبِّهِ سَبِيلاً» «فَمَنْ شاءَ اتَّخَذَ إِلى رَبِّهِ مَآباً».\rوقد أنكر الله تعالى على من نفى المشيئة عن نفسه، وأضافها إلى الله تعالى فقال: «سَيَقُولُ الَّذِينَ أَشْرَكُوا لَوْ شاءَ اللهُ ما أَشْرَكْنا» «وَقالُوا لَوْ شاءَ الرَّحْمنُ ما عَبَدْناهُمْ».\rالسادس: الآيات التى فيها أمر العباد بالأفعال والمسارعة إليها قبل فواتها كقوله:\r«وَسارِعُوا إِلى مَغْفِرَةٍ مِنْ رَبِّكُمْ» «سابِقُوا إِلى مَغْفِرَةٍ مِنْ رَبِّكُمْ» «أَجِيبُوا داعِيَ اللهِ وَآمِنُوا بِهِ» «اسْتَجِيبُوا لِلَّهِ وَلِلرَّسُولِ» «يا أَيُّهَا\r__________________\rك ف ج ق لب، فيها تخير: ل، فيه تخيير: ا، في معرض الاصاد والتوبيخ وفيها تخيير: ق ك ي، فيها كسر: م.\r1 ـ وانها فيها قوله: ت ج ف ق ل لب م، كقوله: ي، فمن ذلك تعالى: ا فقط، سورة الكهف: 29.\r2 ـ سورة فصلت: 40، سورة التوبة: 105.\r3 ـ سورة المدثر: 37 شاء (1): ف، سورة المدثر: 55 فلم: ا.\r4 ـ سورة الانسان: 29: سورة النبا: 39.\r5 ـ على: ا، واغافها: او اضفتها: ا.\r6 ـ فقال: ل، سورة الانعام: 148، ولا اباؤنا: ا ي.\r7 ـ سورة الزخرف: 20.\r8 ـ السادس و: ا، اليها: ف.\r9 ـ اينما: وفاتها: ف.\r10 ـ ت ج، سورة آل عمران: 133، من ربكم: ك، ولا بد انهم: 21: ت ج ق ل ك هامش.\r13 ـ سورة الاحقاف: 31، سورة الانفال: 24."], [465, "الَّذِينَ آمَنُوا ارْكَعُوا وَاسْجُدُوا وَاعْبُدُوا رَبَّكُمْ» «فَآمِنُوا خَيْراً لَكُمْ» «وَاتَّبِعُوا أَحْسَنَ ما أُنْزِلَ إِلَيْكُمْ مِنْ رَبِّكُمْ» «وَأَنِيبُوا إِلى رَبِّكُمْ»\rقالوا وكيف يصح الأمر بالطاعة والمسارعة إليها مع كون المأمور ممنوعا عاجزا عن الإتيان به وكما يستحيل أن يقال للمقعد العاجز الزمن قم، ولمن يرمى من شاهق جبل احفظ نفسك، فكذا هاهنا.\rالسابع: الآيات التى حث الله تعالى فيها على الاستعانة به كقوله تعالى «إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ» «فَاسْتَعِذْ بِاللهِ مِنَ الشَّيْطانِ الرَّجِيمِ»، «اسْتَعِينُوا بِاللهِ».\rفإذا كان الله تعالى خالق الكفر والمعاصى، فكيف يستعان به. وأيضا يلزم بطلان الالطاف والدواعى لأنه تعالى إذا كان هو الخالق\r__________________\r1 ـ واعبدوا ربكم: ف، سورة الحج: 77، سورة النساء 170.\r2 ـ من ربكم: ف، سورة الزمر: 65، سورة الزمر: 54.\r3 ـ يصح: يصلح: ف.\r4 ـ به: بها: م فقط. العاجز: ا فقط.\r4، 5 ـ للمقعد الزمن: للزمن والمقعد: ل.\r5 ـ جبل: ت ج ي، الجبل: ا ف ق ل لب، ك م.\rفكذا ههنا: ا ت ج ل ف ك ي، فكذا هذا: لب، يستحيل هذا: ق م.\r6 ـ السابع: ز: ا، تعالى: ك ت ج، به: ت ج ل، ك م.\r7 ـ تعالى: ت ج ك ل ق، سورة الفاتحة: 5، واستعذ: في م ي.\r8 ـ سورة النحل: 98، سورة الاعراف: 128 بالصبر: في م، البقرة: 153.\r9 ـ فاذا: ت ج ف ك ل م ي، واذا: ق لب، الله تعالى: ف ق ك ل لب، الله: ت ج ي، خالق: خلق: ك، فكيف ... به: كيف .. بها: ف.\r10 ـ والدواعي: م فقط."], [466, "لأفعال العباد فأى نفع يحصل للعبد من اللطف الّذي يفعله الله تعالى، لكن الالطاف حاصلة لقوله تعالى:\r«أَوَلا يَرَوْنَ أَنَّهُمْ يُفْتَنُونَ فِي كُلِّ عامٍ مَرَّةً أَوْ مَرَّتَيْنِ». «وَلَوْ لا أَنْ يَكُونَ النَّاسُ أُمَّةً واحِدَةً»، «وَلَوْ بَسَطَ اللهُ الرِّزْقَ لِعِبادِهِ» «فَبِما رَحْمَةٍ مِنَ اللهِ لِنْتَ لَهُمْ» «إِنَّ الصَّلاةَ تَنْهى عَنِ الْفَحْشاءِ وَالْمُنْكَرِ». الثامن: الآيات الدالة على اعتراف الأنبياء بذنوبهم، وإضافتها إلى أنفسهم. كقوله تعالى حكاية عن آدم عليه السلام.\r(رَبَّنا ظَلَمْنا أَنْفُسَنا) وعن يونس عليه السلام: (سُبْحانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ). وعن موسى عليه السلام (رَبِّ إِنِّي ظَلَمْتُ نَفْسِي) وقال يعقوب عليه السلام لأولاده (بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ). وقال يوسف عليه السلام «مِنْ بَعْدِ أَنْ نَزَغَ الشَّيْطانُ بَيْنِي وَبَيْنَ\r__________________\r1 ـ اللطف: لطف: م فقط، تعالى: ف.\r2 ـ لقوله: يقوله: ق.\r3 ـ سورة التوبة: 126.\r3، 4 ـ ولولا ان يكون: ا ت ج ف ق ك ل لب ي، ولو جعلنا: م.\r4 ـ سورة الزخرف: 33، لعبادة: ك م لبغوا في الارض، ك: ت ج ل، سورة الشورى: 27.\r5 ـ سورة آل عمران: 159 ولو كنت فظا غليظ القلب الآية: ك، سورة العنكبوت: 45.\r6 ـ الثامن: ج: ا، واضافتها: واضافتهم: ق م فقط.\r7 ـ تعالى: ف، عليه السلام: ا ف ك لب، صلوات الله عليه: لب، ت ج ق ل م ي.\r8 ـ سورة الاعراف: 23، عليه السلام: ا ف ك لب: ت ج ق ل م ي.\r9 ـ سورة الانبياء: 87، عليه السلام: ا ف ك لب: ت ج ق ل م ي، سورة القصص: 16.\r10 ـ عليه السلام: ف ك لب،: ت ج ق ل م ي، سورة يوسف: 18، امرا: ق.\r10، 11 ـ لاولاده .. يوسف عليه السلام: ف.\r11 ـ يوسف عليه السلام: ا ك لب: ا ت ج ق ل لب ي،: ق لب م."], [467, "إِخْوَتِي» وقال نوح عليه السلام (رَبِّ إِنِّي أَعُوذُ بِكَ أَنْ أَسْئَلَكَ ما لَيْسَ لِي بِهِ عِلْمٌ).\rقالوا فهذه الآيات دالة على اعتراف الأنبياء عليهم السلام بكونهم فاعلين لأفعالهم.\rالتاسع: الآيات الدالة على اعتراف الكفار والعصاة بأن كفرهم ومعاصيهم كانت منهم كقوله تعالى:\r(وَلَوْ تَرى إِذِ الظَّالِمُونَ مَوْقُوفُونَ عِنْدَ رَبِّهِمْ)، إلى قوله: (أَنَحْنُ صَدَدْناكُمْ عَنِ الْهُدى بَعْدَ إِذْ جاءَكُمْ بَلْ كُنْتُمْ مُجْرِمِينَ) وقوله: (ما سَلَكَكُمْ فِي سَقَرَ قالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ)، (كُلَّما أُلْقِيَ فِيها فَوْجٌ سَأَلَهُمْ خَزَنَتُها) إلى قوله (فَكَذَّبْنا وَقُلْنا) وقوله: (أُولئِكَ يَنالُهُمْ نَصِيبُهُمْ مِنَ الْكِتابِ) إلى قوله: «فَذُوقُوا الْعَذابَ بِما كُنْتُمْ\r__________________\r1 ـ سورة يوسف: 100، عليه السلام: ف ك لب، ت ج ق ل م.\r2 ـ سورة هود: 47.\r3 ـ عليهم السلام: ا ف ك، ت ج ل لب م ي، بذنوبهم و: ي.\r4 ـ بكونهم فاعلين: ت ج ف ق ل لب م ي، بذنوبهم وانهم فاعلون: ك.\r5 ـ التاسع: ط: ا.\r6 ـ كقوله: ت ج ق ل م، لقوله: ف ك ي، قوله: لب.\r7 ـ نرى، نرى: في م فقط، انحن: نحن: في ت ج ف لب م ي.\r8 ـ سورة سبا: 31، 32، وقوله: وقلنا: ي.\r9 ـ سورة المدثر: 42، 43.\r10 ـ سورة الملك: 8، 9، سالتهم خزانتها الم يانكم تدير: ا، سالهم خزنتها: ك م ي: ت ج ف ق ل لب، فكذبنا وقلنا: ما نزل الله من شيء: ق فقط، وقوله: ا ك، ينالهم: ما لهم: لب، لهم: ف الى قوله: ق.\r11 ـ نصيبهم: ت ج ف ق ك ل ي، نصيب: لب م، العذاب: العقاب: ق."], [468, "تَكْسِبُونَ».\rالعاشر: الآيات التى ذكر الله تعالى فيها ما يوجد منهم فى الآخرة من التحسر على الكفر والمعصية، وطلب الرجعة كقوله تعالى:\r(وَهُمْ يَصْطَرِخُونَ فِيها رَبَّنا أَخْرِجْنا) الآية وقوله تعالى: (قالَ رَبِّ ارْجِعُونِ لَعَلِّي أَعْمَلُ صالِحاً)، (وَلَوْ تَرى إِذِ الْمُجْرِمُونَ ناكِسُوا رُؤُسِهِمْ)، (أَوْ تَقُولَ حِينَ تَرَى الْعَذابَ لَوْ أَنَّ لِي كَرَّةً فَأَكُونَ مِنَ الْمُحْسِنِينَ) فهذه جملة استدلالاتهم بالكتاب العزيز الّذي (لا يَاتِيهِ الْباطِلُ مِنْ بَيْنِ يَدَيْهِ وَلا مِنْ خَلْفِهِ تَنْزِيلٌ مِنْ حَكِيمٍ حَمِيدٍ).\rولا يقال الكلام عليه من وجهين الأول ان هذه الآيات معارضة بالآيات الدالة على أن جميع الأفعال بقضاء الله وقدره كقوله تعالى:\r__________________\r1 ـ يكسبون: ت، سورة الاعراف: 36 39.\r2 ـ ذكر: ذكرها: ت ل، فيها ذكر: ك، فيها: ف ك، منهم: فيهم: م فقط.\r3 ـ التحمير: التحسير: ا ل، الرجعة: الرجوع: ك.\r4 ـ تعالى: ك لب م: ا ف.\r5 ـ ربنا اخرجنا: ا سورة فاطر: 47، الاية: ق ك م ي، منها الاية: لب، منها: ت: ج ل ف، نعمل صالحا: ك وقوله: ل، تعالى: ك لب م: ت ج ل ي.\r6 ـ قال: ف ل، سورة المؤمنون: 99، 100 فيما تركت: ك.\r7 ـ سورة السجدة: 12، او تقول: ا ت ك م ي، ويقولون: ت، يقولون: ف، الاية وقوله او نقول: ق، وكقوله: لب.\r8 ـ المحسنين: المؤمنين: ف، سورة الزمر: 58، استدلالاتهم: استدلالهم: ك.\r9 ـ ولا من خلفه تنزيل من حكيم حميد: ج: ج ق ك م، ا ق ل لب، الاية: ت.\r11 ـ ولا لا: ج ق لب م، عليه: على هذا: ق، الاول: ا: ا"], [469, "«خالِقُ كُلِّ شَيْءٍ» «خَتَمَ اللهُ عَلى قُلُوبِهِمْ» «وَمَنْ يُرِدْ أَنْ يُضِلَّهُ يَجْعَلْ صَدْرَهُ ضَيِّقاً حَرَجاً» «وَاللهُ خَلَقَكُمْ وَما تَعْمَلُونَ» «فَعَّالٌ لِما يُرِيدُ» وهو يريد الإيمان فيكون فاعلا له وإذا كان فاعلا للإيمان كان فاعلا للكفر لأنه لا قائل بالفرق.\rوالثانى: وهو أنا وإن نفينا كون العبد موجدا لأفعال نفسه لكنا نعترف بكونه فاعلا لها ومكتسبا لها. ثم فى الكسب قولان: أحدهما أن الله تعالى أجرى عادته بأن العبد إذا صمم العزم على الطاعة فإنه تعالى يخلقها، ومتى صمم العزم على المعصية فإنه يخلقها وعلى هذا التقدير يكون العبد كالموجد، وإن لم يكن موجدا. فلم لا يكفى هذا القدر فى الأمر والنهى.\rوثانيها: أن ذات الفعل وان حصلت بقدرة الله تعالى ولكن كونها طاعة ومعصية صفات تحصل لها وهى واقعة بقدرة العبد، فلم لا يكفى هذا فى صحة الأمر والنهى.\rلأنا نجيب عن الأول بجواب اجمالى ذكره أبو الهذيل: وهو أن\r__________________\r1 ـ سورة الانعام: 102، سورة البقرة: 7.\r2 ـ سورة الانعام: 125، وقوله: فان برد الله ان يهديه بشرح صدره للاسلام: ق سورة الصافات: 96.\r3 ـ سورة البروج: 16.\r3، 4 ـ اذا: كان .. كان: ا ت ج ف ق ك ل لب ي، فكان: م.\r5 ـ والثاني: ت لب م، الثاني: ج ل ي، ب: ا، الثاني و: ف ق ك.\r6 ـ لها (2): ف.\r7 ـ اذا صهم العزم: ا ت ج ق ف ك ل لب، منى ضم عزمه: م.\r8 ـ تعالى: ا، صهم العزم: ا ت ج ل لب ق ف ي، ضم عزمه: م، الطاعة .. المعصية: المعصية او الطاعة .. الطاعة: ك.\r11 ـ ثانيها: ت ك ل، ثانيهما: ق م، القول الثاني: ج، لكن: لكن: ف.\r14 ـ ابو الهذيل و: ابو الهذيل العلاف: ف."], [470, "الله تعالى أنزل القرآن ليكون حجة على الكافرين لا ليكون حجة لهم. ولو كان المراد من هذه الآيات ما ذكرت من وقوع أفعال العباد بقضاء الله تعالى، لقالت العرب للنبى عليه السلام كيف تأمرنا بالإيمان وقد طبع الله على قلوبنا، وكيف تنهانا عن الكفر وقد خلقه الله تعالى فينا. وكان ذلك من أقوى القوادح فى نبوته عليه السلام فلما لم يكن كذلك، علمنا أن المراد منها غير ما ذكرت. وأما الكلام التفصيلى على كل واحد من الآيات ففى المطولات.\rوعن الثانى أن العبد اما أن يكون مستبدا بادخال شيء فى الوجود واما أن لا يكون فهذا نفى وإثبات، ولا واسطة بينهما. فإن كان الأول، فقد سلمتم قول المعتزلة. وان كان الثانى كان العبد مضطرا لأن الله تعالى إذا خلقه فى العبد حصل لا محالة. وإذا لم يخلقه استحال حصوله فيه فكان العبد مضطرا، فتعود الاشكالات. وعند هذا التحقيق فيظهر أن الكسب اسم بلا مسمى.\r__________________\r1 ـ الكافرين: الكافر: ف.\r2 ـ تعالى: ت ج ل، عليه السلام: ج ل م، صلى الله عليه وسلم: ت، تامرنا: تامر: ك، يامرنا: ل.\r4 ـ تنهانا: ج ل ق ك ف م ي، ينهانا: ا لب، نهانا: ت، خلقه: ت ج ف ق ك لب م ي، خلق: ا ل.\r5 ـ الله تعالى: ف ق ك ل م ي: ت ج لب وكان: ك لب م، فكان ت ج ف ق ل ي، عليه السلام: ت ج ل، عليه الصلاة والسلام: ق، ك م، فما: ولما: ف.\r6 ـ كذلك: ف.\r7 ـ على: عن: ي، واحد: واحدة: ف ق، المطولات: المطولات مذكورة: ق.\r8 ـ مستبدا: ت ج ك لب ي، مستقلا: ف ق م، مستندا: ا ل.\r12 ـ يخلقه: يخلقه فيه فقد: م، يخلقه فيه: ق ك، فيه فكان: ا ت ج ف ق ل لب ي، وكان: م، فيكون: ك، الاشكالات: الاشكال: ف ي.\r13 ـ التحقيق فيظهر: ت، التحقيق يظهر ظهر: ف: ف ل لب م ي، التحقق فيظهر: ك: ا ك."], [471, "قوله: العبد إذا اختار المعصية حصلت وإذا اختار الطاعة حصلت.\rقلنا حصول ذلك الاختيار به أو لا به. والأول قول الخصم والثانى لا يدفع الالزام.\rقوله كونه طاعة ومعصية صفات تحصل لذات الفعل بقدرة العبد.\rقلنا هذا اعتراف بكون القدرة الحادثة مؤثرة وهو تسليم لقول الخصم.\rوالجواب: ان هذه الإشكالات واردة على المعتزلة لأن ما علم الله تعالى أنه يوجد كان واجب الوقوع. وما علم الله تعالى أنه لا يوجد كان ممتنع الوقوع. ولأنه إن لم يوجد رجحان الداعى امتنع الفعل وان وجد وجب. فكان الإشكال واردا عليهم فى هذين المقامين. ولقد كان واحد من أذكياء المعتزلة يقول: هذان السؤالان هما العدوان للاعتزال. ولو لا هما لتم الدست لنا والله أعلم.\r__________________\r1 ـ المعصية .. الطاعة: ت ج ف ل، الطاعة .. المعصية: ك م.\r3 ـ اولا به: ف، والاول: الاول: ي.\r5، 6 ـ بقدرة العبد: ت ج ف ك ل لب ي، بقدرة الله تعالى: ا، بقدرة العبد وذات الفعل تحصل بقدرة الله تعالى: ق م.\r8، 9 ـ الخصم و: ت ج ق لب ي ل و: ل، الخصم وبالله التوفيق: ا ك، المعتزلة و: ف: ف م.\r9 ـ الاشكالات واردة: ت ك م، الاشكال وارد: ج ل.\r10 ـ انه يوجد: وجوده: ا، تعالى (2): ا ف ي ت ج.\r12 ـ وان: ف ج ق ك ل لب ي، فان: م: ت، واردا عليهم: وارد عليهم: ت، وارد عليه: ا، هذين المقامين: هذا المقام: لب.\r13 ـ واحد: واحدا: ق ف.\r13 ـ للاعتزال: والاعتزال: ا، لتم: تم: ت، والله اعلم: ج،"], [472, "مسئلة:\rإنه تعالى مريد لجميع الكائنات خلافا للمعتزلة.\rلنا إنا بينا أنه تعالى خالقها وقد تقدم ان خالق الشيء مريد لوجوده. ولأنه لما علم أن الإيمان لا يوجد من الكافر، كان وجوده من الكافر محالا، كما ظهر، فيكون الله تعالى عالما بكونه محالا، والعالم بكون الشيء محالا، لا يريده، فيستحيل أن يريد الإيمان من الكافر.\rاحتجوا بأمور: أحدها: انه أمر الكافر بالإيمان والأمر يدل على الإرادة.\rوثانيها: ان الطاعة موافقة الإرادة. فلو أراد الله تعالى كفر الكافر، لكان الكافر مطيعا له بكفره.\rوثالثها: إن الرضا بقضاء الله تعالى واجب. فلو كان الكفر\r__________________\rوبالله التوفيق: ق ك: ت لب م.\r2 ـ انه تعالى: الله تعالى: ك، لجميع: بجيمع: ف.\r3 ـ انا: انا قد: ق، تعالى: ت ج ل.\r4 ـ لما علم: ت ج ل ك م، اذا علم الله تعالى: ق.\r5 ـ كما ظهر .. الله: ف .. عالما: ت .. يكونه محالا: ا: ا ت ج ف ق ل لب م: ي.\r6 ـ يريد: ريد الله تعالى: ف.\r8 ـ احتجوا بامور بوجوه: ق احدها انه ان: ك ي: ت ج ق ك ل ي، احتج بانه: ف، ول احتجوا بانه: لب م.\r10 ـ ثانيها: ب: ا، الارادة: ت ج ك لب ل م ي، للارادة: ف ق، تعالى: ق.\r11 ـ له بكفرة: بكفره: ي: ف.\r12 ـ ثالثها: ج: ا، ان: ق، تعالى: ج، فلو: ت ج ف ق، ولو: ك لب م ي."], [473, "بقضائه لوجب الرضا به. لكن الرضا بالكفر كفر.\rوالجواب عن الأول لا نسلم أن الأمر يدل على الإرادة. وسيأتى بيانه إن شاء الله تعالى فى أصول الفقه.\rوعن الثانى أن الطاعة موافقة الأمر، لا موافقة الإرادة.\rوعن الثالث ان الكفر ليس نفس القضاء بل متعلق القضاء. فنحن نرضى بالقضاء لا بالمقضى.\rمسئلة:\rإذا حركنا جسما، فعند المعتزلة حركة يدنا أوجبت حركة ذلك الجسم. وهو عندنا باطل وهذا هو المسألة المشهورة بالتولد.\rلنا أنه إذا التصق جزء واحد بيد زيد وعمرو، ثم جذبه أحدهما حال ما دفعه الآخر، فليس وقوع حركته بأحدهما أولى من وقوعها بالآخر، فاما أن يقع بهما معا، وهو محال لأنه يلزم أن يجتمع على الأثر الواحد مؤثران مستقلان، وهو محال على ما تقدم.\r__________________\r1 ـ به: ت ج ق ل م ي، به تعالى: ف، بقضاه الله تعالى: ك، بالكفر: لب، لكن: ولكن: م.\r2 ـ و (1): ف ك ل م.\r3 ـ ان شاء الله تعالى: ك: تاخرت الى ما بعد الفقه في: ق م، ج ف.\r4 ـ ان: م، الامر .. الارادة: ت ج ك ل لب م ي، للامر .. للارادة: ا ف ق.\r5 ـ عن الثالث: ف.\r8 ـ اوجبت، ت ج ف ق م ي، وجبت: ا.\r9 ـ عندنا: عندي: ق، وهذا هو: ت ج ف ك لب ل، وهذه ه ي: ق م، وهذا هو اول: ا، وهذه المسئلة هي: ي.\r10 ـ انه: ا، واحد: ت ج.\r12 ـ وقوعها: وقوعهما: ف."], [474, "أو لا يوجد بهما وهو المطلوب.\rاحتجوا بحسن الأمر، والنهى بالفعل، والترك.\rوالجواب قد تقدم والزيادة هاهنا أن الله تعالى، لما أجرى عادته بخلق هذه الآثار فى المتأثر عقيب حصول هذه الأفعال فى المتأثر. فلم لا يكفى هذا القدر فى حسن الخطاب وبالله التوفيق.\rمسئلة:\rفى تفصيل قول الفلاسفة فى ترتيب الممكنات.\rقالوا: ثبت أنه سبحانه وتعالى واحد محض والواحد لا يصدر عنه إلا الواحد على ما تقدم. فمعلوله شيء واحد. وهو إما أن يكون عرضا أو جوهرا. والأول باطل لأن العرض محتاج إلى الجوهر\r__________________\r1 ـ يوجد بهما: ت ج ف ي، بواحد منهما: ق ك لب م.\r2 ـ بالفعل: ت ج ف ق ك ي، بالقتل: ل لب م، القتل: ا، السرك: ت ج ف ق ك ي، الكسب: لب، السكسر: ل م لب هامش.\r2 ـ ههنا: ل ق ك لب م، هنا وهو: ف: ت ج ف ي.\r4 ـ المناثر (1): ا ت ج ق ك ل لب ي، المستاثر: ف، المباشر: م، حصول: حضور: ي، المتاثر (2): ت ق ل ك ي، المباشر: ج ف لب فلم: ا ت ج ف ق ك لب ل ي، صح الامر والنهى فلم: م.\r5 ـ وبالله التوفيق: لب.\r7، 8 ـ في تفصيل .. قالوا قالت: ك: ت ج ف ق ك ل لب ي، قالت الفلاسفة: م.\r8 ـ سبحانه و: ا ف ق لب ي: ا ت ج ف ق لب ي، ك ل م، تعالى: ك ل م: ت ج، والواحد: ا ت ج ف ك ل لب ي، والواحد المحض: ق، قالوا واحد: ا، م.\r9 ـ فمعلوله: فمعلومه: ا، شيء: ت ف ق ك لب ي،: ج م، وهو اما: ج ل ك م، انه اما: ا، فاما: ت ل ي.\r10 ـ عرضا او جوهرا: جوهرا او عرضا: ق، الاول: الثاني:"], [475, "فلو كان المعلول الأول عرضا، لكان علة للجوهر، فيكون الجوهر محتاجا إليه، وقد كان محتاجا إلى الجوهر، ولزم الدور فهو إذا جوهر.\rوهو إما متحيز أو غير متحيز. والأول محال لأن المتحيز مركب من المادة والصورة. ولا يجوز صدورهما معا عن واجب الوجود بل لا بد وأن يكون أحدهما أسبق. ولا يجوز أن يكون السابق هو المادة، لأن المادة قابلة فلو كان المعلول الأول هو المادة لكانت فاعلة وقابلة معا، وهو محال. ولا يجوز أن يكون السابق هو الصورة، لأن المعلول الأول لو كان هو الصورة لكانت الصورة علة للمادة، فتكون الصورة فى فاعليتها غنية عن المادة. وكل ما كان فى فعله غنيا عن المادة كان فى ذاته غنيا عن المادة. فلا تكون الصورة صورة هذا خلف.\rفثبت أن المعلول الأول ليس بمتحيز، ولا هيولى، ولا صورة. فهو إذن جوهر مجرد. ولا يجوز أن تكون أفعاله بواسطة الأجسام لأن المعلول الأول يجب أن يكون علة لجميع الأجسام، وعلة جميع الأجسام لا تكون عليتها بواسطة الأجسام فالمعلول الأول ليس بنفس\r__________________\rق، العرض .. الى: ي، محتاج: ت ج ف ق ك لب، يحتاج: ل م: ي.\r1 ـ للجوهر: ج ك ل م، الجوهر: ت.\r2 ـ ولزم: ت ك ل م، فلزم: ج، فيلزم: ق لب، ويلزم: ي.\r5 ـ ولا: فلا: ا.\r6 ـ بل والا فقد صدر عن الواحد اكصر من الواحد بل: ق.\r7 ـ لان المادة .. هو المادة: ت.\r7، 8 ـ فاعلة وقابلة: ت ف ل لب م، قابله وفاعلة: ك، قابلة فاعلة، ق، فاعلة وقليلة: ي.\r10 ـ وكل ما: وكلما: ك.\r15 ـ لجميع: ا ت ج ق ك ل لب ي، بجميع: ف م.\r16 ـ عليتها: ت ج ق ك ل م، علتها: لب ي، عليها: ا."], [476, "فهو عقل محض. فثبت أن أول ما خلق الله تعالى العقل.\rثم نقول ان كان معلوله شيئا واحدا، ومعلول ذلك المعلول شيئا واحدا أبدا لزم أن لا يوجد شيئان إلا وأحدهما علة للآخر، وهو باطل. فإذن لا بد وأن يوجد شيء يكون معلوله أكثر من واحد والمعلولان لا بد وأن يستندا إلى كثرة فى العلة. ولا يجوز أن يكون الكثرة التى فيه من ذاته البسيطة، أو من واجب الوجود، وإلا فقد صدر عن الواحد أكثر من الواحد، فبقى أن يكون له من ذاته شيء، ومن واجب الوجود شيء. فاذا ضم ماله من ذاته الى ماله من غيره حصلت فيه كثرة. لكن الّذي له من ذاته الإمكان والّذي له من الأول الوجود وينبغى أن يجعل الأشرف علة للأشرف. فلا جرم جعلنا امكانه علة للفلك الأعلى ووجوده علة للعقل الثانى. ثم لا يزال يصدر على هذا الترتيب من كل عقل عقل. وذلك إلى أن ينتهى إلى العقل الفعال المدبر لعالمنا.\rواعلم أن هذا باطل، لأنه بناء على أن الواحد لا يصدر عنه إلا\r__________________\r1 ـ فهو: فهو اذن: ج ف، تعالى: ت ف ك لب ل ي، ج ق م.\r2 ـ للاخر: ت ج ف ق ك ل ي، للاخر قريبه وبعيده: لب، لابد وان: ت ج.\r5 ـ يستندا: ج، يستندان: ت ف ق ك لب ل م ي، يستبدان: ا.\r6 ـ الكثرة: ا ت ج ف ق ك ل لب ي، للكثرة: م، او: ا ت ج ف ق ك ل لب ي، ولا: م.\r8 ـ الواحد واحد (2): ق.\r9 ـ له من ذاته الامكان: ا ت ج ف ق ك ل لب ي، ليس بالامكان: م.\r10 ـ له من ا ت ج ف ق ك ل لب ي، له في: م، الاشرف علة للاشرف: ا ج ف ق ك لب ي، الاشرف هو الوجود علة للاشرف: م، الاشرف علة الاشرف، ت، الاشرف: ل، علة: على: ي.\r11 ـ الاعلى: ت ج ل، الاقصى: ك م، علة (2): ا ك.\r14 ـ على: عن: ت."], [477, "الواحد، وقد مر الكلام فيه .. وعلى أن الإمكان مؤثر، وهو محال. لأنه لو كان أمرا وجوديا لكان إما واجبا، وهو محال: أما أولا فلأنه صفة الممكن ومحتاجة إليه. وأما ثانيا فلأن واجب الوجود واحد. وان كان ممكنا لزم التسلسل. ولأنه لا بد له من علة وجودية وعلته ان كان هو واجب الوجود كان واجب الوجود علة للإمكان، والوجود. فقد صدر عنه أثران. وان كان غيره، فهو محال، لأن ما عدا الواجب إما هو أو معلولاته، ولا هو ولا معلولاته علة له.\rفثبت أن الإمكان أمر عدمى فيستحيل أن يكون علة للأمر الوجودى، ولأن الإمكانات متساوية، فلو كان امكان العقل الأول علة لوجود ذلك، فليكن امكان ذلك الفلك علة لوجود نفسه، لكن امكانه له لذاته، فإذا كان وجوده لازما لإمكانه كان واجب الوجود لذاته، فيكون الممكن لذاته واجبا لذاته.\rوأيضا الفلك الواحد فيه موجودات كثيرة لأن فيه هيولى،\r__________________\r1 ـ مر: تقدم: ك.\r3 ـ الممكن ومحتاجة يحتاج: ق: ت ج ف ق لب ل م، للممكن ومحتاج: ك م.\r4 ـ وان: ت ج ق ك ل لب م ي، فلو: ف، ان: ا، ولانه: لانه: ك.\r5 ـ علته: ا ت ج ف ق ك ل لب ي، عليته: م، كان هو: ت ج ل، كانت هي: م ك.\r6 ـ للامكان والوجود: ا ت ج ق ي، للامكان والوجود: لب م، لامكان والوجود: ف ك ل، اثران: ج، غيران: ت، امران: ك م، امرا: ل.\r7 ـ فهو محال: فمحال: ف، ولا: اولا: ف ك.\r11 ـ فليكن: لكان: ك.\r12 ـ له: ك، فاذا: وذا: لب، لامكانه: لامكان لازم له: ف لب في الهامش.\r13 ـ وايضا: ا ت ك ل لب ي ج، هذا خلف وايضا: ق م، الفلك: ا ت ج ف ق ك ل ي، فان في الفلك: لب، في الفلك: م،"], [478, "وصورة جسمية، وصورة نوعية فلكية. وله من كل مقولة عرض. فاسناد هذه الأشياء إلى الجهة الواحدة، وهى الإمكان اسناد الكثرة إلى الواحد، وهو محال.\rمسئلة فى شرح قولهم فى القضاء والقدر:\rزعموا أن الموجود إما خير محض، كالعقول والأفلاك، أو الخير غالب عليه كما فى هذا العالم، فإن المرض وإن كان كثيرا لكن الصحة أكثر. فلما امتنع عقلا ايجاد ما فى هذا العالم مبرأ عن الشرور بالكلية، وكان ترك الخير الكثير لأجل الشر القليل شرا كثيرا، وجب فى الحكمة ايجاده. فلا جرم، الخير والشر مرادان لكن الخير مراد مرضى به والشر مراد بالضرورة ومكروه بالذات وهذه القاعدة قد تكلمنا عليها فى شرح الإشارات.\rمسئلة:\rالحسن والقبح قد يراد بهما ملائمة الطبع، ومنافرته، وكون\r__________________\rفيه: ت ج ف ق ك ل ي: لب م، لان: لا: ف، هيولى: الهيولى: ل ي.\r1 ـ وصورة: ولا صورة: ف.\r2 ـ الجهة: العلة: ف ج في هامش، استاد: واسناد: ا فقط.\r3 ـ الكثرة: الكثير: ف.\r4 ـ في: ق ل لب ي شرح قولهم .. وزعموا: ل ان: ت ج ف ق ل لب ي، قالت الفلاسفة ان: ك: ك م ي.\r6 ـ عليه: فيه: م فقط.\r7 ـ فلما: ولما: ف ق ي، امتنع عقلا: عقل امتناع: ي، امتنع: ك.\r8 ـ وكان: كان: م فقط.\r9 ـ وجب: اوجبت: ك.\r10 ـ مراد: م فقط، به: ت، ومكروه: ت ج ق ك ل، مكروه: م، بالذات: ل."], [479, "الشيء صفة كمال أو نقصان. وهما بهذين المعنيين عقليان. وقد يراد بهما كون الفعل موجبا للثواب والعقاب والمدح والذم وهو بهذا المعنى شرعى عندنا خلافا للمعتزلة.\rلنا وجوه: الأول أن من صور النزاع قبح تكليف ما لا يطاق. فنقول: لو كان قبيحا لما فعله الله تعالى، وقد فعله بدليل أنه كلف الكافر بالإيمان مع علمه بأنه لا يؤمن، وعلمه بأنه متى كان كذلك كان الإيمان منه محالا. ولأنه كلف أبا لهب بالإيمان ومن الإيمان تصديق الله تعالى فى كل ما أخبر عنه، ومما أخبر عنه أنه لا يؤمن، فقد كلفه بأن يؤمن وبأن لا يؤمن، وهذا تكليف الجمع بين الضدين.\rالثانى: لو قبح شيء لقبح إما من الله تعالى أو من العبد، والقسمان باطلان. فالقول بالقبح باطل. أما إنه لا يقبح من الله\r__________________\r1 ـ او: ا ت ج ف ق ك ل، و: م.\r2 ـ بهما: ت ج ق، به: ك م، ل، كون الفعل موجبا: ك م، كونه موجبا: ت ل، كونهما موجبين، ج، وهو بهذا: ت ف ك ل ي، وبهذا: ا ق، وهذا: ل م، وهما بهذين المعتيين: ج.\r3 ـ شرعي: شرعيان: ج ق.\r4 ـ الاول: ت ف ق ك ل م ي، احدها: ج، ا: ا، صور: ج ف ق ك م ي، صورة: ت لب، صرورة: ل.\r7 ـ كان الايمان منه محالا: فالايمان منه محال: ف، كان الايمان فيه محال: ل، لانه: ت ج ف ق ك ل م، او لانه: لب، وانه: ي، بالايمان: للايمان: ق.\r8 ـ في كل: ت ج ك لب م ي، بكل: ف لب، ومما ... لا يؤمن: ت ج ك ل م، وما اخبر عنه انه لا يؤمن: ي لب، انه يؤمن: ف.\r9 ـ فقد: وقد: لب، بان: ج س ف ك ل لب م، بانه: ا ت، ان: ق، وبان: ت ف ي، بان: ا ج ق ك ل لب، بانه: م، هذا، ت ج ف ك ل ي، هو: ق لب م، الجمع: بالجمع: ف ك لب.\r10 ـ الثاني: ب: ا، الثاني انه: ك، شيء ت ج ل، الشيء: ك م.\r11 ـ اما: ا."], [480, "تعالى شيء فمتفق عليه. وأما أنه لا يقبح من العبد، فلأن ما يصدر عن العبد صادر عنه على سبيل الاضطرار لما بينا أنه يستحيل صدور الفعل عنه، إلا إذا أحدث الله تعالى الداعى فيه إلى ذلك الفعل ومتى أحدث الله تعالى الداعى فيه، كان الفعل واجبا. وبالاتفاق لا يقبح من المضطر شيء.\rالثالث: ان الكذب إذا تضمن تخليص نبى من ظالم لا يقال الحسن هناك التعريض، لا الكذب.\rأو يقول الكذبية تقتضى القبح لكنه قد يتخلف الأثر عن المقتضى لمانع. لأنا نجيب عن الأول: بأنه على هذا التقدير لا يبقى كذب فى العالم لأنه لا كذب إلا ومتى أضمر فيه شيء صار صدقا.\rوعن الثانى أنه حينئذ لا يمكننا القطع بقبح شيء من الكذب\r__________________\r1 ـ تعالى شيء: ك ي، تعالى: ت ف لب ل: ج ق م، يصدر: ا ت ج ف ق ل لب، صدر: ك م.\r2 ـ عنه: منه: لب: ا.\r3 ـ الا: لا: ي، الله تعالى: ا ت ج ف ق ك ل ي، تعالى: ل، الله: م، الداعي .. الفعل: ت ج ف ل ي، الداعي الى ذلك الفعل فيه: لب، فيه الداعي الى ذلك الفعل: ق ك م.\r4 ـ الله تعالى: ا ف ق ك، الله: لب م ي: ت ج ل. للداعي فيه: فيه الداعي: ا ف ق ك، الله: لب م ي: ف، كان: ت ج ل لب ق ي، الى ذلك الفعل: ك، الى الفعل: ف، اليه: م، وبالاتفاق: ق ك ل م، بالاتفاق و: ت ج، بالاتفاق: ف لب ي.\r6 ـ الثالث: ج: ا، اذا تضمن تخليص نبي من ظالم: ت ج، قد يحسن اذا تضمن تخلص به: ل اتجاه الشيء من عن: ا ك الظالم تخليص شيء من ظالم: ف ي، انجاء النبي عن الظالم: ق، من ظالم: ل: ف ق ك لب م ي ل.\r8 ـ الكذبية: الكذب: ك، لكنه ... يتخلف: لكن ... تخلف: ف.\r10 ـ لانه لا كذب الا: ا ت ج ف ق ي، لانه ما من كذب الا: ل، الانه لا يكذب: ي: م، ومنى: متى: لب، وقد: ي، صار: فيصير: ي.\r11 ـ شي: ق."], [481, "لاحتمال أنه تخلف الحكم هناك لقيام مانع لا يطلع عليه أحد.\rاحتجوا بأن العلم الضرورى حاصل بقبح الظلم والكذب وحسن الانعام. ولا يجوز اسناده إلى الشرع لحصوله لمن لا يقول بالشرع.\rوالجواب ان أردت به العلم الضرورى بحصول الملائمة والمنافرة الطبيعية، فذلك مما لا يأباه أحد وان أردت به غيره فممنوع.\rمسئلة:\rلا يجب على الله تعالى شيء عندنا البتة خلافا للمعتزلة. فانهم يوجبون اللطف والعوض والثواب والأصلح فى الدين والبغداديون خاصة يوجبون العقاب ويوجبون الأصلح فى الدنيا.\rلنا أن الحكم لا يثبت إلا بالشرع ولا حاكم على الشرع، فلا يجب عليه شيء. ولأن اللطف هو الّذي يفيد ترجيح الداعية بحيث لا ينتهى\r__________________\r1 ـ انه تخلف: ت ج ف ق ك ل لب ي، ان تخلف: ا، ان يتخلف: م، هناك: هناك عن المقتضى: ف، مانع: ت ج ل ي، مانع خفي: ق ك لب م، مانع حقيقي: ف.\r5 ـ فذلك .. اخذ: ق: ا ت ج ف ق ل لب، فذاك مما لا ناباه: ك م ي، غيره ممنوع: ت ج ف ك، غيره فمنوع: ي، غيره فهو ممنوع: ق، غير ممنوع ا ل، غيره فممنوع وبالله التوفيق. لب.\r7 ـ تعالى: ت ج، شيء عندنا البتة: ت ج البتة: ك ت ج ك ل، شيء البتة عندنا: ف ي، عندنا شيء البتة: لب ا ق لب، شيء: م.\r8 ـ اللطف: ت ج ل م ي، اللطف والاصلح في الدين: ق، الاصلح في الدين واللطف: ك لب، والثواب: تقدم على العوض في: ل، والاصلح في الدين: ت ج ف.\r9 ـ خاصة: ت ج ف ق لب ي: ك ل م، يوجبون (2): ا ت ج ف ق لب ي، ك ل م.\r10 ـ حاكم: حكم، ا لب.\r11 ـ يفيد: يوجب: ي، لا ينتهى: ينتهى: ف ل."], [482, "إلى حد الإلجاء. فالداعية الواصلة إلى ذلك الحد شيء ممكن الوجود فى نفسه. والله تعالى قادر على جميع الممكنات فوجب أن يكون الله تعالى قادرا على ايجاد تلك الداعية المنتهية إلى ذلك الحد من غير تلك الواسطة.\rوأما العوض فلو كان واجبا لكان دفع الألم دفعا لتلك المنافع العظيمة، فكان يجب أن يقبح دفع الألم عن الغير، كما قبح المنع من القصد.\rوأما الثواب فلله تعالى من النعم على العبد ما يحسن معه التكليف بهذا القدر من الطاعات، فوجب أن لا يوجب الطاعة الثواب كما فى الشاهد.\rوأما الأصلح فى الدنيا فغير واجب، لأن الأصلح للكافر الفقير أن لا يخلق، حتى لا يكون معذبا فى الدارين. والأصلح أن يخلق العباد فى الجنة وأن يغنيهم بالمشتهيات الحسنة عن القبيحة، وأما\r__________________\r1 ـ الاتجاه: الايجاب: ف.\r2 ـ على جميع: كل: ق لب ي الممكنات: ت جف ق ك ل لب ي، على الممكنات: م: ا.\r3 ـ فوجب .. قادرا: ت ج ق ك ل لب م ي: ا ف.\r4 ـ على ايجاد .. الحد: ف.\r5 ـ واما: ت ج ف ق ك ل لب ي، اما: م.\r6 ـ فكان: ا ت ج ف ق ك لب ل، وكان: م ي، من: عن: ف.\r7 ـ القصد: ا ت ج ص ف ق لب، الفصد: ل م، القصد والحجامة: ك، الفصل: ي.\r8 ـ و: ل، على: ا ت ج ف ق ك لب ل، في: م.\r9 ـ يوجب: يوجد: ف، الطاعة: ت ج ل، الطاعات: م، للطاعة: ك، للطاعة والثواب: ق.\r11 ـ الفقير: والفقير: ف.\r12 ـ يخلق: يخلقه: ف، لا (2): ي.\r13 ـ العباد: ف ج ل، عباده: ق ك لب م، العبد: ي، الجهاد: ت، في الجنة: ل، بالمشهيات: المسبهات: ل."], [483, "العقاب فلأن العذاب حقه وليس له فى استيفائه نفع ولا فى إسقاطه ضرر، فيحسن إسقاطه كما فى الشاهد.\rمسئلة:\rلا يجوز أن يفعل الله تعالى شيئا لغرض خلافا للمعتزلة، ولأكثر الفقهاء.\rلنا أن كل من كان كذلك، كان مستكملا بفعل ذلك الشيء والمستكمل بغيره ناقص لذاته. ولأن كل غرض يفرض، فهو من الممكنات، فيكون الله تعالى قادرا على ايجاده ابتداء، فيكون توسط ذلك الفعل عبثا.\rلا يقال لا يمكن تحصيله الا بتلك الواسطة. لأنا نقول الّذي يصلح أن يكون غرضا ليس إلا ايصال اللذة إلى العبد وهو مقدور الله تعالى من غير شيء من الوسائط.\rاحتجوا بأن ما يفعل إلا لغرض فهو عبث والعبث على الحكيم غير جائز.\r__________________\r1 ـ العقاب: ك لب ي، العذاب: ص، العقوبة: ق م، العفو: ا ت ج ف.\r1، 2 ـ استيفائه نفع ولا في اسبقاطه ضرر: اسقاطه ضرر ولا في استيفائه منفعة: ك.\r2 ـ فيحسن: ت ج ف ق ك م ي، فحسن: لب، فتحسين: ا، فلحسن: ل.\r4 ـ يفعل: يقول: ت، تعالى: م، شيئا: ف.\r6 ـ بفعل: بقول: ت.\r7 ـ ولان: فلان: ج، لان: ت.\r9 ـ توسط: ت ق ك ل ي، توسيط: ج لب م.\r10 ـ يمكن: يكن: ا.\r11 ـ غرضا: ا ت ج ف ق ك لب ل ي، لغرضنا: م.\r12 ـ الله: لله: ف ي.\r13 ـ بان: ان: لب، الا: ت ف، لا: ج ق ك ل لب م ي."], [484, "قلنا ان أردت بالعبث الفعل الخالى عن الغرض فهو استدلال بالشيء على نفسه وان أردت به غيره فبينه.\rمسئلة:\rقالت المعتزلة علة حسن التكليف التعريض لاستحقاق النعم فإن التفضيل بالنعم قبيح. وهذا عندنا باطل. لأنه بناء على الحسن والقبح والوجوب على الله تعالى. وبعد تسليمه فلا نسلم أن التفضيل بالنعم قبيح ممن يستحيل عليه النفع والضر. وبتقدير تسليمه، فاستحقاق النعم لا يتوقف على التكليف بالأفعال الشاقة بدليل أن التلفظ بكلمة الشهادة أسهل من الجهاد والصوم، مع أن النعيم المستحق به أعظم. فلو كان المقصود استحقاق النعيم لكان من الواجب أن يزيد الله تعالى فى قوتنا ثم يكلفنا ما لا يشق علينا ليحصل الاستحقاق من غير المشقة.\r__________________\r1 ـ الفعل: ق، فهو: ت ج ل، فهذا: ك م.\r2 ـ وان: فان: ك، به: ج ق ك.\r3 ـ قالت: قال: ت علة: ا، التعويض .. النعم: ت ج ل، التعويض .. التعظيم: لب م، التعويض التعويض: ف، التعوض: ك ي ف .. الثواب: ف ق ك ي.\r5 ـ التفضيل: ا ت، التفضل: ج ف ق ك لب ل م ي، بالنعم: ت ج ف ك ل ي، بالتعظيم: ق لب م، على: على عين: ت.\r6 ـ تعالى: ف، فلا: ل م، ولا: ت، لا: ج ق، التفضيل: ا ت، التفضل: ج ف ق ك ل لب م ي.\r7 ـ بالنعم: ت ج ف ك ل ي، بالتعظيم: ق لب م، ممن: ا ت ج ف ق ك ل لب ي، محال: م.\r8 ـ النعم: ت ج ك ل، النعيم: ف ي، التعظيم: قق لب م، الشاقة: السابقة: ا.\r9 ـ النعيم: ت ج ف ل ي، النعم: ك، التعظيم: ا ق لب،: م.\r10 ـ النعيم: ت ج ف ل ي، النعم: ك، التعظيم: ق لب م. تعالى: ق، ما: ا ت ج ف ق ك ل ي، بما: لب م، علينا: ا ت ج ف ق ك ل لب ي، عليها: م، ليحصل لنا: ق."], [485, "احتج نفاة التكليف بأمور أحدها: أنه إذا كان الكل بخلقه وإرادته ففيم التكليف؟ والمعتزلة وان أنكروها فقد اعترفوا بالعلم. فما كان معلوم الوجود فهو واجب الوقوع. وما كان معلوم العدم فهو ممتنع الوقوع ففيم التكليف.\rوثانيها: أن التكليف إن كان عند استواء الداعيتين فهو محال. لأن فى هذه الحالة الفعل ممتنع. وإن كان عند الرجحان فالراجح واجب، والمرجوح ممتنع ففيم التكليف؟.\rوثالثها: أن التكليف بالفعل: اما أن يقع حال حضور الفعل أو قبله. والأول محال لأن إيجاد الموجود محال. ودفعه حال وجوده محال والثانى أيضا باطل لأن كونه فاعلا للشىء لا معنى له، إلا حصول المقدور عن القدرة فعلى هذا يستحيل أن يكون هو فاعلا فى الحال لفعل لا يوجد فى الحال. فلم يكن هو مأمورا فى الحال بشيء أصلا\r__________________\r1 ـ احتج: واحتج: ق ك، احدها: ا: ا.\r2 ـ ففيم: ت ج ك، ففيما: م، فيم: ل، انكروها: ت ج ف ل لب ي، انكروها: ق ك م.\r3 ـ فما: مما: ت، الوجود: الموجود: ت.\r4 ـ الوقوع: ا ت ج ف ك ل لب ي، الوجود: ق م، فغيم: ت ج ل، ففيما: ف ق ك ي، فيم: لب.\r5 ـ ثانيها: ت ق ك ل م، الثاني: ج، ب: ا، ان: وهو ان: م، الداعيتين: ت ج ل، الداعيين: ك م، الداعية: ق.\r7 ـ ففيم: ت ج ف ق ك ل، فيم: لب، ففيما: م.\r8 ـ ثالثها: الثالث: ج، ج: ا، بالفعل: ف، حضور: ت ج ف ق ل ي، حصول: ك م، الحصول: لب، الفعل: لب.\r9 ـ الموجود: الموجودات: ل، ودفعه: رفعه: ق ك لب م ي ا .. محال: ت ج ق ك ل لب م ي: ف.\r10 ـ باطل: ت ج ف ل ي، محال: ق ك لب م، حصول: ج ك م، الحصول: ل، حضور: ت.\r11 ـ عن: من: ا، فعلى هذا يستحيل: ت ج ف ق ل لب ي، فيستحيل: ك م، هو: ت ج ف ق ل لب ي، ك م.\r11، 12 ـ في الحال لفعل: للفعل في الحال: لب.\r12 ـ هو مامورا في الحال: ت ج، مامورا في الحال: ف،"], [486, "بل يكون ذلك اعلاما بأنه سيصير فى الزمان الثانى مأمورا به.\rفإن قلت كونه فاعلا للفعل أمر زائد على حصول الفعل عن القدرة.\rقلت فذلك الزائد اما أن يكون مقدورا للمكلف أو لا يكون مقدورا له فإن كان مقدورا له. فاما أن يؤمر بايقاعه حال وجوده أو قبله ويعود المحذور المذكور. وان لم يكن مقدورا له استحال أن يكون مأمورا به.\rورابعها: أن الأمر بالفعل الشاق ان لم يكن لغرض، فهو عبث وهو غير جائز على الحكيم. وان كان لغرض يستحيل عوده إلى من يستحيل عليه النفع والضر. ويستحيل عوده إلى العبد لأن ذلك\r__________________\rمامورا: ا، هو في الحال مامورا: لب م، في ذلك الحال مامورا: ك بشيء: لشيء: ا.\r1 ـ يسصير: لب، به: ت ج ف ق ك ل لب، باموراته: ا.\r2 ـ امر زائد: امرا زائدا: ك، حصول: ا ت ج ف ق ك ل لب ي، صدور: م.\r4 ـ فذلك: ك.\r5 ـ معدورا له: ت ج ل ي، مقدورا: ي، ق ك لب م، فان كان مقدورا له: ي، بايقاعة: ت ج ف ق لب ي، بارتفاعه: ك م.\r5، 6 ـ فاما ان ... لم يكن مدورا له: ل.\r6 ـ الذكور: ا، له: ت ج ف ق لب ي: ك م.\r8 ـ ورابعها: ت ف ق ك لب ل م ي، الرابع: ج، ود: ا. عبث: ا ت ج ف ق ك ل لب، عيب: ف م.\r9 ـ وهو: ت ج ك لب م، و: ف ل ي، لغرض: ا ت ج ف ق ك ل لب ي: م، يستحيل: ت ج ل، ويستحيل: ا ف، فيستحيل: ق ك لب م ي.\r9، 10 ـ عودة ... ويستحيل: ل.\r10 ـ التفع: ف، الضر: الضرر: ف لب."], [487, "النفع اما فى العاجل أو فى الآجل.\rوالأول باطل لأن الإنسان يتأذى به فى الحال. والثانى محال لأن ذلك الغرض ليس إلا وصول اللذة إليه والله تعالى قادر عليه ابتداء فيكون توسط التكليف عبثا. والجواب عن الكل انه مبنى على طلب اللمية، وهو باطل. لأنه ليس يجب فى كل شيء أن يكون معللا. وإلا لكانت علية تلك العلة معللة بعلة أخرى، ولزم التسلسل. بل لا بد من الانتهاء إلى ما لا يكون معللا البتة. وأولى الأمور بذلك أفعال الله تعالى وأحكامه. فكل شيء صنعه لا علة لصنعه. والله تعالى أعلم.\r__________________\r1 ـ في العاجل او في الاجل: ا ج ق لب، لعاجل او لاجل: ت م، للعاجل وللاجل او الاجل: ي: ف ي، في العاجل والاجل: ك.\r2 ـ محال: ا ت ج ف ق ك ل لب ي، باطل: م.\r3 ـ وصول: ت ج ف ل ي، حصول: ق ك لب م، اليه: ج، فيه: ت: ك ل م، الله: ا ت ج ف ق لب ل م، انه: ك م، تعالى: ج.\r4 ـ توسط: ت ق ل، توسيط: ج م ك.\r4، 5 ـ فيكون ... اللمية: ف.\r6 ـ معللة: ا، ولزم: فلزم: لب.\r7 ـ ما: اما ان: ا.\r8 ـ فكل وكل: م .. ولا ولا: ا ت ج ل، لا: ي: ا ت ف ق ك لب ل م ي، فعلة كل شيء صنعة ولا علة لصيغة: ت.\r9 ـ والله تعالى: ل اعلم: ج ل، وبالله التوفيق: ت لب،: ت ف ك م ي."], [488, "القسم الرابع\r"]], "pg": [455, 488]}, "687.13": {"x": [[488, "الكلام فى الأسماء\rاسم كل شيء اما أن يدل على ماهيته، أو على جزء ماهيته، أو على الأمر الخارج عن ماهيته، أو على ما يتركب عنهما. والخارج اما أن يكون صفة حقيقية أو اضافية أو سلبية أو ما يتركب عنها وهل يجوز أن يكون لماهية الله تعالى اسم أم لا؟ فإن قلنا ماهية الله تعالى معلومة للبشر جاز، وإلا فلا. وأما الاسم الدال على جزء ماهية الله تعالى فذلك محال، لامتناع التركب فى حقيقة ذات الله تعالى. وأما سائر الأقسام فجائزة. ولما كانت السلوب والاضافات بسيطة، ومركبة غير متناهية، لا جرم جاز وجود أسماء لا نهاية لها متناسبة. والله أعلم.\r__________________\r2 ـ الكلام: ا ج ل.\r3 ـ اما ان: ا.\r4 ـ الامر الخارج: ت ج ق ك ل م ي، ما هو خارج: ف، امر خارج: لب، عنهما: ف ق ل م، عنها: ت ج ك لب ي.\r5 ـ سلبية او حقيقية او اضافية: في ك، او ما يتركب: تكرر في ق.\r5، 6 ـ والخارج فالخارج: ف ... عنها عنهما: ف ك: ت ج ف ق ك لب ل م ي: ا.\r6 ـ ام: او: ك.\r7 ـ ماهية الله تعالى: ا ف ق ك لب ل ي، ماهيته تعالى ت ج ا: ت ج م.\r8 ـ ماهية الله تعالى: ج: ت ج ف ل ي، الماهية: ق ك لب م، التركب: التركيب: ق ك ل.\r10 ـ ومركبة: مركبة: ف، جاز: ت ج ل ك، يجوز: م.\r11 ـ متناسبة والله اعلم: ج: ت ج ل ق، وان كاتب ق، مناسبة: لب متباينة وبالله التوفيق: ق ك لب، متباينة: م ي."], [489, "الركن الرابع\rمن هذا الكتاب فى السمعيات وهو مرتب على أقسام:\rالقسم الأول\r"]], "pg": [488, 489]}, "687.14": {"x": [[489, "فى النبوات\rمسئلة:\rالمعجز أمر خارق للعادة مقرون بالتحدى، مع عدم المعارضة وإنما قلنا: أمر لأن المعجز قد يكون إتيانا بغير المعتاد وقد يكون منعا من المعتاد وإنما قلنا أنه خارق للعادة ليتميز به المدعى عن غيره. وإنما قلنا أنه مقرون بالتحدى لئلا يتخذ الكاذب معجز من مضى حجة لنفسه وليتميز عن الإرهاص والكرامات. وإنما قلنا أنه مع عدم المعارضة ليتميز عن السحر والشعبذة.\rمسئلة:\rمحمد رسول الله صلىلله عليه وسلم خلافا لليهود، والنصارى،\r__________________\r2 ـ من هذا الكتاب: ت ج ك م ي، هذا من الكتاب: ل، من هذا الباب: لب، من الكتاب: ق، ف.\r3 ـ القسم: ت ج ق ك ل، سنذكره: ا، م.\r6 ـ للعادة: للعادات: ق ققط.\r7 ـ امر: انه امر: ك، اثيانا بغير: ج ق ك ل م ي، اثباتا لغير: ف، اثباتا لغير: لب، اتيانا ب: ت.\r8 ـ من عن: ق ق المعتاد: ت ج ف ق ل لب م ي، للمعتاد: ك، انه: ك، غيره: ت ج ك ل م، غير المدعي: ق.\r9 ـ انه: ا، معجز: ا ت ج ف ك ل لب ي، معجزة: ق م، من: عن: ف.\r10 ـ ليتميز: ا ت ج ف ق ك ل لب ي، يتميز: م، انه: ا.\r12 ـ صلى الله عليه وعلى آله: لب وسلم: ت ف ك لب، عليه من التحايا ما جاوز مدى النهاية: ج: ق ل م ي."], [490, "والمجوس وجماعة من الدهرية.\rلنا وجوه ثلاثة: الأول وعليه التعويل إنه ادعى النبوة وظهر المعجز على يده وكل من كان كذلك فهو نبى ورسول وإنما قلنا إنه ادعى النبوة للتواتر. وإنما قلنا إنه ظهر المعجز على يده لثلاثة أوجه:\rأحدها: انه أتى بالقرآن والقرآن معجز. اما إنه أتى بالقرآن ولم يأت به غيره فبالتواتر. وأما إنه معجز فلأنه تحدى الفصحاء لمعارضته وهم عجزوا عنها وذلك يدل على كونه معجزا.\rوثانيها: إنه نقل عنه معجزات كثيرة نحو اشباع الخلق الكثير من الطعام القليل، ونبوع الماء من بين أصابعه ومكالمة الحيوانات العجم\r__________________\r1 ـ من: ف ي.\r2 ـ وجوه ثلاثة: ا ت ج ف ق ك ل ي، وجوه: م: لب الاول: ا: ا، احدها: ج، وعليه التمويل: تقدمت على النبوة: م، وسقطت: في: ا لب.\r2، 3 ـ ظهر المعجر على يده عليه: م: ق ك ل م، ظهر: لب ظهرت المعجزة على يده: ف لب ي، اظهر المعجزة على يده: في ج، عليه: في ت، عليها المعجزة: ل متن: ت جل.\r3 ـ كذلك: ف، فهو نبي ورسول: ت: ت ف، فهو سول: ج، كان نبيا ورسولا: ق ل: ق ك ل م، و (2): ك.\r3، 4 ـ وانما .. للتواتر: ف.\r4 ـ للتواتر: ا ت ق ك، بالتواتر: ج ل لب، فللتواتر: م ي. انه: ل ف لب ي، ظهرت ظهر: لب ق ك م المعجز المعجزة: ف لب ي ل: ت ف ق ك ل لب م ي، اظهرت المعجزة: لثلاثة اوجه: ت ج ف ك ل لب ي، فلثلاثة اوجه: م، لوجوه ثلاثة: ق.\r5 ـ انه (1): ف.\r6 ـ فبالتواتر: فللتواتر: ق.\r7 ـ لمعارضته وهم ... عنها: ا ت ج ف ق ك ل لب ي، ممعارضته فعجروا عنه: م.\r8 ـ ثانيها: ب: ا، كثيرة نحو: ت ج ق ك ل لب ي، كثيرة عنها: م، نحو: ق.\r9 ـ الحيوانات: الحيوان: م فقط."], [491, "وكل واحد منها وأن لم يبلغ مبلغ التواتر، لكن التواتر يدل على صحة واحد منها. وأى واحد منها صح حصل الغرض.\rوثالثها: أنه أخبر عن الغيوب والإخبار عن الغيب معجز.\rوإنما قلنا أن من ادعى النبوة وظهر المعجز على يده كان رسولا لأن الرجل إذا قام فى المحفل العظيم وقال إنى رسول هذا الملك إليكم. ثم قال يا أيها الملك ان كنت صادقا فى مقالتى، فخالف عادتك وقم عن مكانك فمتى قام الملك اضطر الحاضرون إلى صدقه. فكذا هاهنا.\rالطريق الثانى فى إثبات نبوته عليه السلام، الاستدلال باخلاقه وأفعاله وأحكامه وسيره. فإن كل واحد منها. وان كان لا يدل على النبوة لكن مجموعها مما يعلم قطعا أنه لا يحصل إلا للأنبياء. وهذه طريقة اختارها الجاحظ وارتضاها الغزالى فى كتاب المنقذ.\rالطريق الثالث: اخبار الأنبياء المتقدمين فى كتبهم السماوية عن\r__________________\r2 ـ منها صخ: صح منها: ا، منها ومتى صح: لب.\r3 ـ الغيوب: الغيب: م، الغيب معجز: الغيوب معجزا: ا.\r4 ـ ظهر: ك ج م، اظهر: ت ل، المعجز على يده: ك، على يده المعجزة المعجز: ف: ف ق ي، عليه المعجز المعجزة: ج ل: ت ج ل، رسولا: ا ت ج ف ق ك ل لب ي، نبيا: م.\r5 ـ وقال: ت ج ل ك، فقال: م.\r6 ـ في مقالتي: ا ت ج ف ق ك ل لب ي، فيما قلت: م.\r7 ـ مكانك: مقامك: ق لب، الحاضرون: الحاضر: ا، هها ا ت ج ف ق ك ل لب ي، هنا: م.\r8 ـ الثاني: ب: ا، في: ا ت ج ف ق ك ل لب ي، م، نبوته: النبوة لنبينا: ك.\r9 ـ بافعاله واخلاقه: ق، منها: ك.\r11 ـ للانبياء: للانبياء عليهم السلام: ق، طريقة: الطريقة: ا، الجاحظ: الحافظ: ي، ارتضاها .. رحمه الله ق للب كتاب: ت ج ف ق ك ل لب ي، ارتضى بها .. كتابه: م.\r12 ـ المنفد: المنقد من الضلال: ل ج هامش.\r13 ـ الطريق: ا ت ف ق ل لب ي، ج ك م، الثالث: ج"], [492, "نبوته عليه السلام فهذه مجامع أدلة نبوته عليه السلام والاستقصاء فيها مذكور فى المطولات.\rفإن قيل لا نسلم أنه ظهر المعجز على يده قوله فى الوجه الأول أن القرآن ظهر على يده وهو معجز.\rقلنا الاستقصاء فى الأسئلة والأجوبة على هذا الوجه مذكور فى كتاب النهاية. قوله فى الوجه الثانى: أشبع الخلق الكثير من الطعام القليل.\rقلنا هذه الأشياء لو وجدت لنقلت نقلا متواترا لأنها أمور عجيبة والدواعى متوفرة على نقل العجائب. فلما لم تنقل نقلا متواترا، علمنا أنها ليست صحيحة. سلمنا سلامتها عن هذا الطعن ولكن لا نزاع فى أنها لم تنقل نقلا متواترا، بل إنما نقلت على سبيل الآحاد ورواية الآحاد لا تفيد العلم.\rقوله: مجموع رواة المعجزات بلغوا حد التواتر وذلك يدل على\r__________________\rا، المتقدمين: المتقدمين عليهم السلام: ق.\r1 ـ عليه السلام: ا، فهذه: ا ت ف ق ك لب ي، فهذا: ج م، ادلة نبوته: الادلة في نبوته: ق.\r3 ـ ظهر المعجز: ظهرت المعجزة: ج، ان: ت ج ف ق ك ل ي، انه: لب، م.\r1 ـ هو: ت ج ف ق ك ل م ي، القرآن ا: لب.\r5 ـ على هذا الوجه: ف ي.\r6 ـ كتاب: ك.\r8 ـ لنقلت: ت ج ف ل لب ي، لنقلت الينا: ق ك م، لانها: الا انها: ف.\r9 ـ متوفرة .. العجائب: ا ت ج ف ق ك ل لب ي، على نقلها متوفرة: م.\r10 ـ هذا: ا ت ج ف ق ك ل لب ي: م، و: ت ج ف ل ي: ق ك لب م.\r11 ـ نقلا: ت ج ل ك، الينا نقلا: م.\r13 ـ رواة المعجزات المعجزة: ف ي: ت ج ف ق لب ل"], [493, "صحة واحد منها. وأيها صح حصل الغرض.\rقلنا لا نسلم أن رواة الغرائب التى يمكن الاستدلال بها على الرسالة بلغوا حد التواتر فإنه ليس كل ما يذكر فى كتب دلائل النبوة مما يصح الاستدلال القطعى به على الرسالة. إنما الّذي يصح الاستدلال به على ذلك أمور قليلة، نحو نبوع الماء من بين أصابعه وأمثاله. ولا نسلم أن رواة أمثال هذه الأشياء بلغوا إلى حد التواتر.\rقوله فى الوجه الثالث: أخبر عن الغيب.\rقلنا أخبر عن الغيب على وجه يخالف العادة أو يوافقها.\rالأول ممنوع والثانى مسلم.\rبيانه ان العادة جارية بأن الرؤساء إذا حاولوا ترغيب الرعية فى محاربة خصومهم وعدوهم بأن اليد لهم والدولة راجعة إليهم.\r__________________\rي، الرواة: ك م.\r1 ـ ايها: انها: ا ف.\r2 ـ ان: ت ج ف ق ك ل لب ي: م.\r3 ـ حد: عدد: ف ي، كل ما: كلما: ك، كب: ا ت ج ف ق ك ل، كتاب م.\r4 ـ القطعي به: ا ف ت ك ل، به قطعا: ف ي، به من طريق القطع: م، به: ج، القطع به: لب.\r5 ـ اصابعه: الاصابع: ك.\r6 ـ الى: ق.\r8 ـ الثالث: الثالث انه: ق.\r9 ـ يوافقها: على وجه يوافق العادة: ق.\r10 ـ الاول: ا ت ج ف ق ل لب ي، فالاول: م، الاول .. مسلم: ج ل م، الاول ع والثاني م: ت، ع م: ك.\r12 ـ وعدوهم: ا ت، يخبرون: ج هامش ف ك لب ل هامش، يخبرونهم: م، اخبروهم: ق، وعدوهم او اعداءهم: ف."], [494, "فقوله تعالى: (وَعَدَ اللهُ الَّذِينَ آمَنُوا مِنْكُمْ وَعَمِلُوا الصَّالِحاتِ لَيَسْتَخْلِفَنَّهُمْ فِي الْأَرْضِ) من هذا الباب.\rوأيضا الرجل المعتقد فيه قد يخبر عن أمور كلية على سبيل الاجمال. فان وقع شيء من ذلك جعله حجة على صدقه، وان لم يقع قال أنا ما عينت الوقت، بل سيقع بعد ذلك.\rفقوله تعالى: (الم غُلِبَتِ الرُّومُ فِي أَدْنَى الْأَرْضِ) من هذا الباب سلمنا أنه أخبر عن الغيب على سبيل التفصيل فلم قلت إنه معجز والدليل عليه أن المحدثين رووا فى كتب دلائل النبوة ان قسا وسطحيا أخبرا عن أحوال محمد صلىلله عليه وسلم مع أنهما ما كانا من الأنبياء. فعلمنا أن الكاهن قد يخبر عن الغيب وكذا المعبرون قد يخبرون عن الغيوب المفصلة بناء على الرؤيا وكذا المنجمون وأصحاب العزائم. وإذا كان كذلك لم يكن ذلك معجزا.\r__________________\r1 ـ منكم: ف.\r2 ـ سورة النور: 55 الباب: القبيل: ق.\r3 ـ فد: ك.\r4 ـ حجة: ا ت ج ل لب ق ك: م.\r5 ـ انا: ق.\r6 ـ فقوله تعالى: ت ج ف ق، قوله تعالى: ل لب م، فقوله ا، وقوله: ك، في ادني الارض: ل، وهم من بعد غلبهم: ك، سورة الروم: ا، الباب: القبيل: ق.\r7 ـ الغيب: الغيوب: لب.\r8 ـ كتب: كتاب: م.\r9 ـ اخيرا: اخبر: ت صلى زز سلم: ت ج ل، عليه ا الصلاة و: م السلام: ا ق ك لب ي.\r10 ـ ان: ت ج ك ل، انه ليس بمعجز فكذلك: ق، قد (2) ت ج ق ل لب، ف ك م ي.\r11 ـ الغيوب: ا ت ج ف ق ك ل لب ي، الغيب: م.\r12 ـ لم يكن ذلك: ك معجزا: ت ج ل م، علمنا انه ليس بمعجز: ق."], [495, "ثم نقول ان كان ما ذكرتموه دالا على ظهور المعجز على يده. فمنعنا ما يدل على أنه ممتنع وبيانه وهو أنه لو جاز انخراق العادات عن مجاريها لجاز أن ينقلب الجبل ذهبا ابريزا والبحر دما عبيطا، وأن ينقلب ما فى البيت من الأمتعة أناسا فاضلين. ومعلوم أن تجويزه يقدح فى البديهيات.\rسلمنا ظهور المعجز على يده فلم قلت أن كل من كان كذلك كان رسولا.\rوتقريره أن الاستدلال بظهور المعجز على الرسالة يتوقف على مقامات ثلاثة أحدها: أنه فعل الله تعالى. وثانيها أن الله تعالى فعله لأجل التصديق. وثالثها أن كل من صدقه الله تعالى فهو صادق.\rأما المقام الأول ففيه النزاع من وجوه: أحدها أنا ان أثبتنا النفس الناطقة فلعل نفس النبي عليه السلام مخالفة بالماهية لنفس غيره فلا جرم\r__________________\r1، 2 ـ ذكرتموه ذكرته: ا ق ك لب .. فمنعنا ما: ا ت ج ف ق ك ل لب ي، ذكرتم: م.\r2 ـ وبيانه: ت ج ف ق ك ل لب ي، وبيانه من وجوه احدها: م، العادات: ت ج ق ل، العادة: ك م.\r3 ـ عبيطا: ت ج ف ل لب م ي، غبيطا: ا ك.\r4 ـ الامتعة: ا ت ج ف ق ل لب، الاواني: م، المتاع: ك اناسا: انسانا: ي.\r5 ـ بقدح: ا ت ج ف ق ك ل لب ي، قادح: م.\r6 ـ المعجز: المعجزة: ا ق.\r8 ـ المعجدز: المعجزة: ا ك ل.\r9 ـ ثلاثة: ت ج ك ل، ثلاث: ق م، احدها: ت ج ف ق ك ل لب ي، ا: ا، الاولى: م، انه: ان: ت، ثانيها: ب فعله: فعلها: م فقط.\r10 ـ ثالثها: ج، ا، صدقه: صدق: م فقط، تعالى: ق.\r11 ـ المعام: اتهام: ت، ق، احدها: ا: ا. اثبتنا النفس: قلنا بالنفس: لب.\r12 ـ فلعل: فعل: ي، النبي: الذي: ا عليه السلام: ت"], [496, "قدر على ما لم يقدر عليه غيره. وان لم نقل بالنفس الناطقة، فلا بد وأن يكون الإنسان عبارة عن البدن المخصوص. فلعله كان لمزاج بدنه خصوصية، لم تحصل تلك الخصوصية لسائر الأبدان، فلا جرم قدر على ما لم يقدر عليه غيره.\rوثانيها: أن النبي عليه الصلاة والسلام لعله وجد جسما نباتيا أو حيوانيا له خاصية عجيبة مستعقبة لتلك الآثار الغريبة التى أظهرها النبي عليه السلام ولما لم يقع ذلك الجسم فى يد آخر لا جرم، عجز الكل عن معارضته.\rوثالثها: لعل الجن والشياطين أعانوه عليه وما أعانوا عليه غيره أو الأرواح الفلكية أعانوه عليه أو الملائكة أعانوه عليه. بل هذا ظاهر. لأن الأنبياء عليهم السلام يحيلون أكثر الأشياء على الملائكة. ونحن إنما علمنا وجودهم وعصمتهم بقول الأنبياء عليهم السلام فقبل العلم بتصديقهم جوزنا وجودهم. وذلك كاف فى\r__________________\rج ك ل ي، صلعم: ف،: ق لب م.\r1 ـ ما لم: ما لا: لب ل.\r4 ـ ما لم: ما لا: ت ل.\r5 ـ ثانيها: ب: ا، الصلاة و: م فقط.\r6 ـ حيوانيا: حيوانا: ت ق م، مستعقبة: ت ج ف ق ك ل لب ي، مستتبعة: م.\r7 ـ النبي: ف ي، عليه السلام: ق م، ولما: فلما: لب، آخر: ت ج ف ك ل ي، احد: ا لب، غيره: ق.\r9 ـ ثالثها: ج: ا، الجن: الحي: ا، الشياطين: الشيطان: الشيطان: ك، اعانوه: اعانوا: ي، وما ايمانوه: واما اعانوه: ا.\r9، 10 ـ عليه غيره: ت ج ف ل ي، غيره عليه: لب م، غيره: ك.\r10 ـ اعانوه عليه (1): ا ك ق لب، اعانوه: ت ج ف ل ي: م.\r11 ـ السلام: ا ت ج ف ق ك ل لب ي، الصلاة والسلام: م. على: في ا.\r12، 13 ـ عليهم السلام: ا ق، ت ج ف ك ل لب ي.\r13 ـ فقبل العلم: ف بتصديقهم بصدقهم: ف ق ك لب م ي: ت ج ف ق ك ل لب م ي: م.\r13، (1/ 497) ـ ذلك كاف في تحقق: ت ج ل، وذلك كان في تحقق"], [497, "تحقق الاحتمال.\rوأما المقام الثانى: ففيه النزاع من وجهين: أحدهما لا نسلم أنه خلق المعجز لأجل التصديق فإن المعجز لا شك أنه ليس نفس التصديق فلو لم يكن الغرض منه التصديق، لم يبق للمعجز دلالة على التصديق. لا سيما وقد بينتم أن الله تعالى لا يجوز أن يكون فعله معللا بالغرض. ومما يحقق هذا أن الفعل بدون الداعى أما أن يكون جائزا واما أن لا يكون، فإن كان جائزا لم يمكن القطع بأن الله تعالى فعل المعجز لأجل التصديق، بل لعله فعله، لا لأمر أصلا. وان لم يجز توقف فعلنا للقبائح على داع يخلقه الله تعالى، فيكون الله تعالى فاعلا لما يوجب القبيح وإذا جاز ذلك من الله تعالى فلم لا يجوز أن يضل عباده. وإذا جاز ذلك\r__________________\rتحقيق: ا: ا م، عدم عصمتهم وذلك كان في تحقق تحقيق: ك: ف ق ك لب ي.\r2 ـ و ـ: الثاني: ب: ا، احدهما: ت ف ق ك ل لب م ي، الاول: ج، ا: ا.\r3 ـ انه: ا ف ق ك ي، ان: ت ج لب ل، م، لاجل التصديق: ت ج ف ك م ي، الفرض فضلا من عن: ق ان يكون للتصديق: ق ل لب.\r2،5 ـ فان المعجز ... للمعجز للمعجزة: ل، المعجزة: ق .. التصديق ا ت ج ف ق ك ل ي: م.\r6 ـ الله: ت ج ل ف، افعال الله: ك م، فعله معللا: ت ج ل ف، معللة: ك لب م، فعلة: ي.\r7 ـ الداعي: الدواعى: ف، واما ان: ت ج ف ق ل لب، واما: ي، او: ك م.\r8 ـ يمكن: ت ج لب م، يكن: ف ق ك ل ي، تعالى: فعل: ي: ت ج، المعجز: المعجزة: ق.\r9 ـ فعلنا للقبائح: ك ل لب م، فعلنا القبائح: ق، فجعل القبائح: ف ي، فعله القبائح: ت ج.\r10 ـ تعالى (1): ي، فيكون: فينا فيكون: ق، تعالى: (2) ج، واذا: ا ت ج ك ل لب ي، فاذا: ق م.\r11 ـ فلم لا: ج ك ل م، وعلم انه: ت، ان يضل: ا ت ج"], [498, "منه بطل الاستدلال بالمعجز على التصديق.\rالثانى سلمنا أنه تعالى فعل المعجز لمقصود، لكن لم قلت أن ذلك المقصود ليس إلا التصديق. فلعله تعالى فعله لغرض آخر وعليكم بيان الحصر ثم إنا على سبيل التبرع نذكر أمورا أخر.\rأحدها: أن يفعله ليكون ابتداء عادة.\rوالثانى ان يكون تكرير العادة متطاولة فإن الفلك الثامن لا يستكمل الدورة إلا فى ستة وثلاثين ألف سنة. فيكون وصولها إلى أول الحمل فى مثل هذه المدة عادة لها. فلعل هذا الحادث يكون من هذا الباب.\rوثالثها: أن يكون ذلك كرامة ومعجزة لنبى آخر فى طرف آخر من أطراف العالم.\rورابعها: أن يكون ذلك ارهاصا لنبى يأتى بعد ذلك، كالأحوال\r__________________\rف ق ك ل لب ي، من افضل: م ز\r1 ـ بطل: ت ج ف ك ل لب ي، بطل اصل: م.\r2 ـ الثاني: ب، ا، انه تعالى، م، ان: ك، المعجز: المعجزة: ق، لكن: ولكن: ف ق، قلتم: في ق.\r3 ـ فلعله: ولعله: م فقط، تعالى ك ت ج.\r4 ـ بيانه: بان: ت، الدليل على: ل، ثم: قلت: ي. نذكر تقدم على على سبيل في: ك.\r4، 5 ـ اخر احدها: ا: ا.\r6 ـ الثاني ان يكون: ت ج ف ل ي، ب ان يكون: ا، ثانيها ان يكون: ك لب، ثانيا ليكون: ق م، تقرير: تكرر: ك.\r7 ـ الف: ا.\r8 ـ اول: ك.\r10 ـ ثالثها: ج: ا، يكون: لب، ومعجزة: ت ج، او معجزة: ف ك ي، لولى او معجزة: ق ل لب م، آخر (2): ا ف ق لب ك ي.\r12 ـ رابعها: د: ا، لنبي: ت ج ل، لنبي آخر: ك م"], [499, "التى ظهرت على محمد عليه السلام قبل بعثته. وكالنور الّذي يحكى أنه كان يظهر فى جبين آبائه.\rوخامسها: أن يكون ذلك امتحانا لعقول المكلفين، كما أنزل المتشابهات امتحانا لعقولهم.\rالمقام الثالث سلمنا أن الله تعالى صدقه، لكن لم قلت أن كل من صدقه الله تعالى فهو صادق فإن عندكم الله تعالى خالق الكفر والفواحش. فإذا لم يقبح ذلك من الله تعالى، فلم لا يحسن منه أيضا تصديق الكاذب. وهذا السؤال الأخير مختص بنا دون المعتزلة.\rثم نقول: هب أنا لم نذكر شيئا من هذه الاحتمالات. فلم قلت أن كل من ظهر عليه المعجز كان رسولا، والرجوع فيه إلى المثال ضعيف. لأنا لا نقطع فى ذلك المثال بصدق المدعى. لأنه ربما قام\r__________________\r1 ـ عليه السلام: ت ج ف ق ك ل لب ي، م.\r2 ـ آبائه: ت ج ك ل لب، ابيه: ف ق م ي.\r3 ـ خامسها: ه: ا، ذلك: ت ج ف ق ل لب ي: ك م.\r4 ـ لعقولهم: بعقولهم: ا.\r5 ـ المقام الثالث: ت ج ك م، والمقام الثالث: ل، اما المقام ج: ا، لم قلت: فلم قلت: م فقط.\r6 ـ تعالى (1): ت ق ك ل ي، ج م، خالق: ا ت ج ف ق ك ل ي، خلق: لب م.\r7 ـ ذلك تاخر الى ما بعد تعالى في: لب، فلم لا: ت ج ف ك م، فلم: ي، فلا، لب، يحسن: يقبح: لب، منه: ف.\r8 ـ الكاذب: الكافر: ف، الاخير: ق ك لب م: ت ج ف ل ي.\r9 ـ هب: ههنا هب: ف، لم نذكر: ت ج ف ق ل لب ي، لا نذكر: ك م، ندرك: ا.\r10 ـ كل: ك، عليه: ت ج ك م، على يده: ق ل، المعجز: المعجزة: ق ج."], [500, "الملك فى ذلك الوقت لأنه حدث فى بطنه ألم أو شاهد شيئا فخاف أو تذكر أمرا فقام طلبا له.\rوبالجملة فليس هنا إلا الدوران وهو أنه قام عند التماس المدعى. وما قام قبل ذلك. والدوران لا يفيد إلا الظن الضعيف. فإنه يحكى أن واحدا كان يجلس فى المسجد فكلما دخل المؤذن واذن قام ذلك الإنسان وخرج. فقال له المؤذن ما لي أراك كلما أذنت خرجت؟ فقال لا بل كلما هممت بالخروج أذنت. وهذا يدل على أن دلالة الدوران على العلية ضعيفة. ثم ان سلمنا دلالة ذلك الفعل على التصديق فلم قلت إنه فى حق الله تعالى كذلك. وستعرف أن القياس المؤيد بالجامع لا يفيد إلا الظن فكيف هذا القياس الخالى عن الجامع. فهذا هو الاعتراض على الدليل الأول على النبوة.\rوأما الدليل الثانى وهو الاستدلال بمحاسن أحواله على نبوته،\r__________________\r1 ـ الملك: الملك العظيم: م فقط، لانه الما: ت ل الم: ا ت ج ف ق ك ل لب ي، لحدوث الم في بطنه: م، او: و: ت، فخاف: فخافه: ق.\r2 ـ او: ان: ف، طلبا له: ك لب م هامش ج، طلبا: ل، طالبا: ت ج ف ي، طالبا له: ق.\r3 ـ هنا: ههنا: ق ك لب، هناك: ل.\r4 ـ وما: ما: ي، و (2): ا، الضعيف: الضعيف فانه يحكي ان واحدا كان يجلس في المسجد فلما قيل ذلك والدوران لا يفيد الا الضعيف: ف.\r5 ـ المسجد: ت ج ف ي، مسجد: ق ك لب م، واذن: ت ج ف ق ك لب ي، م.\r7 ـ لا بل: لانك: ت، على: لب.\r8 ـ العيبة ضعيفة ضعيف: م: ت ج ف ق ك لب م ي، العلة ضعيفة: ا، ثم ونم: ي، ان: اذا: ك، ذلك الفعل: ا ت ج ف ق ك لب ي، العقل: م.\r4، 10 ـ الضعيف ... الا الظن: ل.\r10 ـ فكيف: وكيف: ي.\r11 ـ فهذا: وهذا: ت.\r12 ـ و ـ: م."], [501, "فضعيف. لأن غاية ما فى الباب أنها تدل على كون ذلك الإنسان متميزا عن سائر الناس بمزيد الفضيلة. ولكن من أين تدل على النبوة. كيف ويحكى عن أفاضل الحكماء فى الأخلاق أمور عجيبة جعلها الناس قدوة لأنفسهم فى الدنيا والآخرة، مع ما بقى عنهم من العلوم الدقيقة.\rوأما الدليل الثالث وهو الاستدلال بما جاء فى التوراة والإنجيل على نبوة محمد عليه السلام، فالاعتراض عليه أنكم اما أن تقولوا إنه جاء فى هذه الكتب صفة محمد عليه السلام على سبيل التفصيل بمعنى أنه تعالى بين أنه سيجيء فى السنة الفلانية فى البلدة الفلانية شخص وصفه كذا وكذا فاعلموا أنه رسولى، وإما أن لا يقولوا ذلك بل يقولوا أنه تعالى بين ذلك بيانا مجملا من غير تعيين الزمان،\r__________________\r1 ـ فضعيف: ت ج ق ك ل م، قالوا فضعيف: لب، فهو ضعيف: ا، ضعيف: ف ي، لان غاية: الرعاية: ا، انها تدل انه يدل: م، ذلك: ك.\r2 ـ متميزا: متميز: ك.\r3 ـ النبوة ... ويحكى: ا ت ج ق، النبوة وكيف يحكى: ك لب، ميوة ويحكى: ف ي، وكيف يحكى: ا، النبوة وكيف وقد حكى: م.\r4 ـ بقى: ا ت ج ك لب ل، نقل: ف م ي.\r7 ـ عليه السلام: ا ت ج ف ق ك ل لب ي، صلى الله عليه وسلم: م، فالاعتراض: فالاعراض: ي.\r8 ـ انا جاء في هذه: جاء في هذا: ا.\r7، 8 ـ بالا عتراض ... السلام: ق.\r9 ـ السنة: سنة: ك ف، العلانية (1): ا ت ج ف ق ك ل لب وجل: ف ق ي، القابلة: م.\r10 ـ شخص: ت ج ك لب م، فيلخص: ل: ف ق ي، وصفة، ج م، وصفة: ت، وصفته: ك، صفته: ق، صفة: ل، انه: ف، رسولي رسول الله ل، ذلك: ت ج ف ك ل ي، كذلك: م.\r11 ـ بل: بان: ت، غير: ف، تعيين: ت ج ك لب م،"], [502, "والمكان، والوصف فإن ادعيتم الأول، فهو باطل. لأنا نجد التوراة والإنجيل خاليا عنه.\rلا يقال اليهود والنصارى حرفوا هذين الكتابين. لأنا نقول هذان الكتابان كانا مشهورين فى المشارق والمغارب. ومثل هذا مما لا يصح تطرق التحريف إليه كما فى القرآن.\rوإن ادعيتم الثانى فبتقدير المساعدة عليه لا يدل ذلك على النبوة. بل إنما دل على ظهور إنسان فاضل شريف. وان دل على النبوة لكن لا يدل على نبوة محمد عليه السلام، إذ ربما كان المبشر به إنسانا آخر.\rسلمنا أن ما ذكرتموه يدل على النبوة لكن هنا ما يدل على القدح فيها وهو من وجوه:\r__________________\rتعين: ف ل ي.\r1 ـ والوصف: والوقت والوصف: ك.\r2 ـ خاليا: ا ت ك ل ي، خالية: م، خاليين: ج ق، حاليتين: ف.\r3 ـ هذين: ت ج ق ل لب م ي، عن هذين: ف، ا ك.\r4 ـ الكتابان .. مشهورين: ا ت ج ف ق ك ل لب ي، كتابان مشهوران: م، مشار الارض ومغاربها: ق، هذا مما: ت ج ف ك م، هذا: ا لب: ا ي.\r4، 5 ـ لا يصح نطرق بطريقة: ت: ت ج ك ل لب م، لا يتطرق: ف ي، لا يصح: ق.\r6 ـ اليه التحريف: في ف.\r7 ـ انما: ت ج ف ي، ربما: ق ك ل لب م، دل (1): ت ج ق ك لب ل م، بدل: ف ي، و: او: ك م.\r8 ـ عليه السلام: ا ت ج ف ق ك ل لب ي، صلى الله عليه وسلم، م.\r10 ـ ذكرتموه: ت ج، ذكرتم: ك م، ذكرته: ف ل لب ي، النبوة: نبوة محمد عليه السلام: ف، هنا: معنا: ل، ما (2): دليل آخر: ي.\r11 ـ وهو: وبيانه: ل."], [503, "أحدها: شبهة الدهرية وهى القدح فى الفاعل المختار، وانكار كون الصانع قادرا عالما بالجزئيات مريدا.\rوثانيها: شبهة منكرى التكليف. فإنهم يقولون الأنبياء إنما جاءوا من عند الله تعالى بالتكليف، لكن القول بالتكليف محال على ما تقدم كلامهم فيه.\rوثالثها: شبهة البراهمة وهى من وجهين: الأول ان ما جاء به الرسول ان علم حسنه بالعقل، كان مقبولا سواء ورد به الرسول، أو لم يرد. وان علم قبحه بالعقل كان مردودا، سواء ورد به الرسول أو لم يرد وإن لم يعلم لا حسنه ولا قبحه، فان كان فى محل الحاجة حسن الانتفاع به، سواء ورد به الرسول أو لم يرد، لما تقرر فى العقل ان كل ما ينتفع به الإنسان وكان خاليا عن أثارة الضرر، كان\r__________________\r1 ـ احدها: ت ج ف ق ك ل لب ي، ا: ا، الاول: م، شبيهة: شبه: ك، القدح: ا ل لب، بالقدح: ت ج ف ق ك م ي.\r2 ـ قادرا عالما بالجزئيات: ا ت ج ف ل لب ي قادرا: ك، عالما قادرا بالحركات بالجزئيات: ق: ق م، ومريدا: في لب.\r3 ـ ثانيها: ب، ا، شبهة: شبه: ك.\r3، 4 ـ فانهم ... الانبياء عليهم السلام: ق ك .. جاء: ف .. تعالى: ت ج ي .. بالتكليف: ف .. محال: على ما تقدم كلامهم: ف، فيه: ت ج ق ل لب ي: ت ج ف ق ك ل لب م ي، محال على ما تقدم كلامهم فيه: ا.\r6 ـ ثالثها: ج: ا، شبهة: ك، وهي: ي، وجهين: وجوه: لب، الاول: ا، ا، احدها: ج.\r7 ـ ان: ت ج، به: فيه: ق.\r8 ـ علم: ت ج ق ك ل لب م، كان علم يعلم: ي: ف ي.\r8، 9 ـ وان علم ... او لم يرد و: ا.\r10 ـ الانتفاع به: ت ج ق ك ل لب م ي، الافعال: ف، سواء: ي، او: و: ي، لما: ت ج ق ل، ولما: ا ك م، اذ: ف ي، على ما: لب.\r11 ـ كل ما: كلما: ك، وكان: ان كان: ف، اثارة: ت ج"], [504, "الانتفاع به حسنا. وان لم يكن فى محل الحاجة يقبح الانتفاع به سواء ورد به الرسول أو لم يرد لأنه إقدام على ما يحتمل الضرر من غير حاجة أصلا.\rالثانى: أن دلالة النبوة ليس إلا المعجز بالاتفاق. لكنا بينا أن المعجز لا يدل البتة، فامتنع الجزم بالصدق.\rورابعها شبهة اليهود وهى من وجهين:\rالأول: ان الله تعالى لما شرع شريعة موسى عليه السلام فاما أن يكون قد بين فيها انها باقية إلى يوم القيامة، أو بين فيها أنها باقية إلى الوقت الفلانى فقط، أو بين الشرع فقط ولم يتعرض لبيان التأييد والتأقيت. فإن قلنا إنه تعالى بين التأبيد لم يجز نسخه.\rأما أولا فلأنه تعالى لما أخبر أن هذا الشرع ثابت أبدا، فلو لم\r__________________\rف ك ل ي، امارة: ق لب م، الضرر: الضرر ظاهرا: ف ي.\r1 ـ وان: واو نق، يقبح ت ج، ضح: ك ل م.\r2 ـ به: ا ت ج ف ق ك ل لب بعد الرسول في: ي،: م.\r3 ـ حاجة: حاجة اليه: ق.\r4 ـ الثاني: ب: ا، المعجز: ا ت ج لب، المعجزة: ف ق ك ل م ي.\r5 ـ المعجز: المعجزة: ق، يدل: يدرك: ك، البتة، ت ج ك ل م ي، البتة عليها: ق، البتة عليها: ل، عليه البتة: ف ق.\r6 ـ رابعها: د: ا، وهي: ت ج ق ك ل م ي، وهي ان: ف: لب.\r6، 7 ـ من وجهين الاول: ا: ا، ان: ج: ا ج ق ك م، من: ت، ان: ل.\r7 ـ عليه: عليه الصلاة و: م فقط.\r8 ـ انما: ان تكون: م فقط.\r9 ـ فقط (2): لب م.\r9، 10 ـ التابيد والتاقيت: التاقيت والتابيد: ا، التاكيد: ف، دلنا: قلت: في م فقط.\r11 ـ تعالى لما: ت ج ف ك لم: ل لب ي، تعالى: ا ق،"], [505, "يبق ثابتا أبدا كان ذلك كذبا وهو غير جائز على الله تعالى.\rوأما ثانيا: فلأنه لو جاز أن يقضى الله تعالى على أن شرع موسى عليه السلام ثابت ثم إنه لا يبقى ثابتا. فلم لا يجوز أن يقضى الله تعالى على أن شرع محمد عليه السلام ثابت أبدا ثم إنه لا يبقى ثابتا أبدا فيلزمكم تجويز نسخ شرعكم.\rوأما ثالثا فلأنه لو جاز أن يخبر الله تعالى بالتأبيد مع أن التأبيد لا يحصل، ارتفع الأمان عن كلامه، ووعده، ووعيده. وذلك باطل بالاتفاق. وأما أن يقال أنه تعالى بين فى شرع موسى عليه السلام إنه ثابت إلى الوقت الفلانى، كان هذا من الأمور العظيمة التى تتوفر الدواعى على نقله، فوجب أن ينقل ذلك التوقيت نقلا متواترا.\rوالنقل المتواتر لا يجوز الاطباق على اخفائه، فكان يلزم أن يكون\r__________________\rم فلو: فلم: ف.\r1 ـ ابدا: ك، ذلك: ا ت ج ف ق ل لب ي، ك م، تعالى: ف ق ك ل لب م، عزوجل: ي: ا ت ج.\r2 ـ يقضى: ت ج ف ل، ينص: ق ك لب م ي، يتغن: ا.\r3 ـ عليه السلام: ج ف ق، ثم انه لا يبقى ثابتا: ت ج، مع انه لم يبق ثابتا: ل، ابدا: ا، ابدا ثم انه لا يبقى ثابتا: ك ابدا: ي: ف ق ك لب م ي.\r3، 4 ـ فلم لا ... يقضى بنص: ق ك لب م ي الله تعالى ت ج ق ل ي على: ان: م شرع محمد عليه الصلاة و: م، صلى الله عليه وسلم: ل السلام انه: م ثابت ابدا: ت ج، ا.\r4 ـ ثم انه لا يبقى: ت ج ف ل ي، مع انه لا يكون: ا ق ك لب م، مع انه لا يكون ثابتا ابدا: تكرر في: ا.\r5 ـ تجويز: ك.\r6 ـ بالتاييد: ت ج ف ل، عن التاييد: ك لب م ي.\r8 ـ يقال: ت ف ل، قلنا: ج ق ك لب م ي، تعالى: ك.\r9 ـ كان هذا: هذا ايضا باطل الان هذا كان: ق.\r10 ـ نقلا: ج ف لب: ت ق ك ل م ي.\r11 ـ والنقل: فالنقل: م فقط، فكان: وكان: لب ل."], [506, "العلم بانتهاء شرع موسى عليه السلام عند مبعث عيسى عليه السلام وانتهاء شرع عيسى عليه السلام عند مبعث محمد صلىلله عليه وسلم معلوما بالضرورة للخلق، وأن يكون المنكر له منكرا للتواتر، وأن يكون ذلك من أقوى الدلائل لعيسى ومحمد عليهما السلام على دعواهما فلما لم يكن الأمر كذلك، علمنا فساد هذا القسم.\rولأنه لو جاز أن لا ينقل هذا التوقيت نقلا متواترا، لجاز أن يقال أن محمدا عليه السلام حول الصوم من رمضان إلى شوال، والقبلة من الكعبة إلى غيرها. وأنه عليه السلام قال إن شرعى يبقى مؤيدا إلى الوقت الفلانى، مع أنه لم ينقل شيء من ذلك وتجويزه قدح فى شرع محمد عليه السلام.\r__________________\r1 ـ عليه السلام (1): ج ل م، عليه السلام (2): ج م.\r2 ـ عليه السلام: ج ف م ل ي، صلى .. وسلم وآله: ل: ت ل، عليهم السلام: ا ج، عليه السلام: ق ك لب ي، عليه الصلاة والسلام: م.\r3 ـ المتواتر: ت ج ل م ي، المتواترات: ا ق ك لب.\r4 ـ لعيسى ومحمد عليهما السلام: ا ت ف ق ك ل، لعيسى عليه السلام ومحمد عليه الصلاة والتحية: لب، لعيسى ومحمد عليه السلام: ي، لعيسى ومحمد: ج م.\r6 ـ لا ينقل: ت ج ك ل لب م ي، ينقل: ا ف.\r7 ـ ان محمدا: ج م، ان محمد: ت، محمد: ل، عليه: ا ت ج ف ق ك ل ي، عليه الصلاة و: لب م حول: حصول: ا، من: في: ت ج.\r8 ـ انه: ت ج ف ل لب، فانه، ق، انه قال: ك، لانه: م، عليه ا ت ج ف ق ك ل لب، عليه الصلاة و: م، ان: ا ت ج ف ق ك ل لب ي، م، يبقى مؤيدا مؤيدا: ل، ثابتا: ي، موقتا: ج: ت ج ل لب م ي، لا يبقى مؤيدا بل يبقى الى: ق، مؤيدا، ا، ثابتا: ف.\r9 ـ تجويز: هو: لب.\r10 ـ عليه السلام: ا ت ج ف ق ك ل لب م، عليه الصلاة والسلام: م: ي."], [507, "وأما ان قلنا أنه تعالى بين فى شرع موسى عليه السلام أنه ثابت، ولم يبين التأبيد والتوقيت. فهذا محال لما إنه سنبين فى أصول الفقه: أن الأمر لا يفيد إلا وجوب الفعل مرة واحدة. ومعلوم أن شرع موسى عليه السلام لم يكن كذلك. فان التكاليف كانت متوجهة بذلك الشرع إلى الخلق إلى زمان عيسى عليه السلام بالاتفاق. ولما ظهر فساد هذين القسمين الأخيرين ثبت الأول. ويلزم من صحته امتناع النسخ.\rالثانى: ان اليهود والنصارى على كثرتهم وتفرقهم فى المشارق والمغارب يخبرون عن موسى وعيسى عليهما السلام أن كل واحد منهما أخبر أن شرعه باق إلى يوم القيامة. وخبر التواتر يفيد العلم، وإلا لما أمكنكم إثبات وجود محمد عليه السلام فضلا عن نبوته. وإذا\r__________________\r1 ـ اما: ا ت ج ف ق ك ل لب ي: م، قلنا: يقال: ف، انه (1): ان الله: ق، عليه السلام: ت ج م، انه (2): ل.\r2 ـ يبين: بين: ا، والتوقيت: ا ت ج ف ل لب ي، ولا التوقيت: ك ق م، لما: كما: ك، انه: ا ت ج ف ك ل لب ي، انا: ق: م، ستبين: ستبين ان شاء الله تعالى: ك لب.\r3 ـ الا وجوب الفعل: ت ج ف ق ك ل لب ي، الوجوب الا: م، الوجوب: ا.\r4 ـ عليه السلام: م فقط، التكاليف: التكليف: لب، كانت: م فقط.\r5 ـ بذلك: في ذلك: ج الى (1): ت ج، على: ك ل م.\r6 ـ ولما: ت ج ف ق ل لب، فلما: ك م ي، هذين: م فقط، صحته: صحة: م ي.\r8 ـ الثاني: ب: ا، القسم الثاني: ك.\r9 ـ عليهما: ا ت ج ف ق ك ل ي، عليه: لب، عليهما الصلاة و: م.\r10 ـ اخبر: اخير: ا، قد اخبر: ك، شرعة باق: ا ت ج ف ق ك ل لب ي، شريعته باقية: م.\r11 ـ لما امكنكم: ا ت ج ف ق ك لب، لما امكننا: ل، لما امكنهم: ي، لم يمكنكم: م، السلام: ا ت ج ق ك ل لب ي، الصلاة والسلام: م، الصلاة: ف، عليه السلام: ج، نبوته: اثبات نبوته: ا، واذا: ا ت ج ك ل لب ي، م اذا: م، اذا: ف."], [508, "صح ذلك عنهما، فلا شك أن قولهما حجة، لا يقال شرط التواتر استواء الطرفين، والواسطة. وهذا مفقود فى ذلك النقل.\rأما اليهود فلأن بختنصر قتلهم حتى لم يبق منهم إلا عدد يسير دون عدد التواتر. وأما النصارى فلأنهم كانوا قليلين فى ابتداء الأمر. لأنا نقول أما قتل اليهود فضعيف، لأن اليهود كانوا أمة عظيمة، وكانوا متفرقين فى شرق الأرض وغربها، وفى البلاد المتباعدة جدا، فمن المستحيل قتل هذه الأمة العظيمة إلى حيث لا يبقى منهم على وجه الأرض عدد التواتر.\rوأما حديث النصارى فضعيف أيضا لأن ذلك يوجب القدح فى رسالة عيسى عليه السلام قبل مبعث محمد عليه السلام. وذلك مما لم يقل به أحد.\rوالجواب أن المعتمد فى رسالة محمد عليه السلام ظهور القرآن عليه وسائر الوجوه إنما نذكر للتتمة والتكميل.\r__________________\r2 ـ النقل: ا ت ج ف ق ك ل لب ي، المعنى وهو النقل: م، فيهم: لب هامش.\r3 ـ منهم: لب.\r4 ـ دون: اقل من: لب.\r5 ـ كانوا: ا.\r6 ـ شرق: ك، وفى: في: ا.\r7 ـ فمن: ومن: ق، هذه: من: ف، الى حيث: بحيث: م.\r7، 8 ـ منهم: تاخر اني ما بعد الارض في: م.\r9 ـ حديث النصاري: حديث فلة عدد النصاري في ابتداء الامر: ق.\r10 ـ رسالة: ت ج ف ل ي، شرع: ك لب م، محمد: ف، عليه: عليه الصلاة و: م.\r11 ـ مما: ما: ي، يقل: يحصل: ف، احد: احد وبالله التوفيق: ك لب.\r12 ـ عليه السلام: ا ت ج ف لب ي، صلى الله عليه وسلم: ق ل، عليه وآله السلام: ك، عليه الصلاة والسلام: م.\r13 ـ عليه: ف ي، نذكر: ا ت ف ك، يذكر: ج ق ل"], [509, "قوله لو جاز انخراق العادات لارتفع الأمان عن البديهيات. قلنا هذا لازم على الفلاسفة لاحتمال أن يحدث شكل فلكى غريب يوجب هذه الغرائب فى هذا العالم.\rقوله: يجوز أن يكون حدوث المعجز لا من الله تعالى. وإن كان منه، لكن الغرض منه شيء آخر سوى التصديق قلنا المعتزلة عولوا فى الجواب عنه على حرف واحد. وهو أنه لو كان المدعى كاذبا، لوجب على الله تعالى أن يمنع من ظهور ذلك المعجز منعا للعباد من الوقوع فى الضلال، وهذا الجواب ضعيف. لأنه يقال إنما يجب على الله تعالى كشف الحال فيها، لو لم يحتمل ظهور المعجز وجها آخر سوى دلالته على تصديق الله تعالى ذلك المدعى. فاما لما احتمل ذلك واحتمل غيره فلو قطع المكلف بأحد الاحتمالين دون الآخر كان التقصير من قبل العبد، لا من الله تعالى.\rوفى مثل ذلك لا يجب على الله تعالى كشف الحال. ألا ترى أنه\r__________________\rلب م ي، للتتمة: تتمة: ك، التكميل: التكملة: ك ل.\r1 ـ العادات لارتفع: ا ت ج ف ق ك ل لب ي، الصادة ارتفع: م.\r2 ـ لازم: لان: ا.\r4 ـ قوله: قوله و: ت، لا: لان: ي، وان: او ان: ق.\r5 ـ شيء: آخر: الدل: ا ج ف ق ل لب م ي، ت.\r6 ـ عنه: م فقط، حرف: حروف: ت.\r7 ـ يمنع: يمتنع: ت ك، من: عن: ق: م.\r8 ـ الضلال: ت ج ف ق ل م ي، الاضلال: ا ك لب.\r8، 9 ـ على الله: تعالى: ك م: ك ل م، عليه تعالى: ج: ت ج.\r9 ـ الحال: ف، فيها: ت ج ق ك ل لب، منها: ا، فيه: ف ي، المعجز: المعجزة: ق.\r10 ـ تعالى: ج ل، ذلك (1): ا ت ج ف ق ل لب ي، بذلك: ك، لذلك: م، فاما لما: فلما: ا.\r11 ـ فلو: فلما: ك.\r12 ـ التفسير: التفسير: ت.\r13 ـ مثل: ف ي، تعالى: ا ت ج ف ق ك ل، لب م."], [510, "لم يقبح انزال المتشابهات من الله تعالى، لما أنها محتملة غير قاطعة. فكذا هاهنا وأيضا فإنه سبحانه وتعالى يعين الكفرة على المسلمين، ويمكنهم من قتل أوليائه. والمسلمون يجتهدون فى الدعاء وسؤال المعونة على الكفار، وقد لا يجيب دعاءهم ولا يعطيهم مناهم. والكفار يقولون فى دعواتهم: اللهم انصر أحب الفئتين إليك، وان لم ترض ما نحن فيه من تكذيب مدعى النبوة والمخالفة له ولأصحابه. فاسلب عنا ما أعطيتنا من القوى والتمكن، والرب تعالى قد لا يفعل ذلك. فيجب أن يكون هذا موهما لتصديق الكفرة. فلما لم يلزم هذا فكذا ما قالوه.\rوالجواب الحق إنه مبنى على مقدمة واحدة وهى أن تجويز الشيء\r__________________\rي، الحال: ذلك الحال: ل، نرى: ا ت ج ق ك ل ي، نرى: ف لب، يرى: م.\r(13/ 509)، 1 ـ انه لم: ج ك ل لب م ي، ان لم: ت، انه لا: ف.\r1 ـ لما: كما: ك، غير: لا: ك.\r2 ـ ههنا: ا ج ف ق ك ل ي، هنا: ت لب م، فانه: ان الله: ك، سبحانه وتعالى: ت ق لب، سبحانه: ا ج ي، تعالى: ف ك ل م.\r3 ـ سؤال: السؤال و: ك.\r5 ـ دعوائهم: ا ت ف ل لب ي، دعائهم: م، في الدعاء: ج ق: ك، اللهم: ي.\r6 ـ ما: ت ج م، بما: ا ف ق ك ل لب ي، المخالفة: المختلفة: ف.\r7 ـ فاسلب عنا: ج م، فاسلبنا: ك، فان سلب: ت، التمكن: التمكين: ف، والرب تعالى: ق قد لا: ج ق ك ل لب م ي، والرب فلان: ف، والذب ومدلا: ت.\r8 ـ ذلك: وفق مرادهم: ق، موهما: موهوصا: ك، لتصديق: تكرر في: ق، يلزم: ت ج ف ق ل لب ي، يلزم ممن: ك، يكن: م.\r9 ـ هذا: هذا موهما: ا، قالوه: ت ج ف ق ل لب، قالوه في التبيين: ا، قالوا: ك م ي.\r10 ـ الحق: الحق انه: ا لب، واحدة: ا ج ك: ت ف ق ل لب م ي، هي: هو: ا، ان: انه: ت."], [511, "لا ينافى القطع بعدمه. فانا نجوز أن يخلق الله تعالى إنسانا شيخا فى الحال من غير الوالدين وأن يقلب الأنهار دما، والجبال ذهبا. ثم أنا مع هذا التجويز نقطع بأنه لم يوجد، ولأن من واجه غيره بالشتم فعبس المشتوم وجهه، ونظر إلى الشاتم شزرا علم بالضرورة غضبه. وكذلك القول فى حجالة الخجل وصفرة الوجل مع أن حصوله ابتداء بدون الغضب ممكن وهذا أيضا لازم على الفلاسفة على ما قررناه.\rوإذا ثبت هذا فنقول إنما علمنا أن المحدث لهذا المعجز هو الله تعالى لما قدمناه أن جميع الممكنات واقعة بقدرة الله تعالى. وانما قلنا أنها دالة على التصديق لما أنا رأينا النبي عليه السلام يقول: يا إلهى إن كنت صادقا فى دعواى الرسالة، فسود وجه القمر مثلا. وكما قال النبي عليه السلام ذلك أسود. صرنا مضطرين إلى العلم بأنه\r__________________\r1 ـ تعالى: ا ت ج ف ق ك ل لب ي: م.\r2 ـ يقلب: ت ص ف ق لب م ي، تنقلب: ا ج ك ل، الجبال الجبل: ا لب، لما: ان: ا.\r3 ـ هذا: م فقط، التجويز: تجويز: ك، تقطع بانه: يفطع: ك، فانه: ا.\r4 ـ فعبس: فعكس: ا، وجه: في وجهه: ا، سزرا: فشتم: ا.\r5 ـ كذلك: كذا: ك لب ج، حجالة: ت ج ل، حمرة: ك م ص، الخجل: الحجل: لب ي.\r6 ـ ممكن: ا ت ج ف ق ك ل ي، جائز: م.\r7 ـ انما: ك، لهذا المعجز: ل م، لهذه المعجزة: ا ت ج ف ي، بهذه لهذه: ك المعجزات: ق ك لب.\r8 ـ تعالى: ج، قدمناه: ت ف ي، قدمنا: ج ك ل لب م.\r9 ـ دالة: ت ج ف ك ل لب ي، دلالة: ق م، اسالما: ت ج ف م، انا: ل لب ي، لان ا: ق، لما: ك، عليه السلام م فقط.\r9، 10 ـ بقول يا: ت ج ق ك ل م ي، قال يا: لب: ف.\r10 ـ دعواي: ت ج ف ي، دعوتي: ا، دعوى: ق ك ل لب م.\r11 ـ وكما: فكما: ك، كما: ف، عليه السلام: ا ج ف ق ك لب ي، صلى الله عليه وسلم: ت ل: م، صرنا: ا ت ج ق ك ل لب ي، صوتا: ف، قلنا: م، بانه: بان الله: ا ك."], [512, "تعالى صدقه فى تلك الدعوى ولذلك فإن كل من أقر فى القرون الماضية بأن هذه المعجزات من فعل الله تعالى آمن بصدق المدعى، ولم يبق له فيه شك وتجويز سائر الأقسام بحسب العقل لا يقدح فى هذا العلم الضرورى كما ضربناه من المثال.\rوأما شبهة الدهرية ونفاة التكليف فقد تقدم الجواب عنها.\rوأما شبهة البراهمة فهى مبنية على الحسن والقبح، وقد تقدم القول فيه.\rولنذكر فوائد البعثة على التفصيل: فنقول قد عرفت ان الأمور قسمان منها ما يستقل العقل بادراكه، ومنها ما لا يستقل. والأول كعلمنا بافتقار العالم إلى الصانع الحكيم. وفائدة بعثة الرسل فى هذا النوع تأكيد دليل العقل بدليل النقل وقطع عذر المكلف من كل الوجوه على ما قال تعالى:\r(لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى اللهِ حُجَّةٌ بَعْدَ الرُّسُلِ) وقال «وَلَوْ أَنَّا\r__________________\r1 ـ لذلك، ت ج ق ل لب م، كذلك: ف ك ي، القرون: القران: ا.\r2 ـ بان هذه: ك، المعجزات: ت ج ق ل لب م، المعجزة: ف ي، المعجزارات: ك، تعالى .. ا، امن بصدق: ت ج ل، اقر بصدق: ك م ق ي، من تصديق: ف، يبقى: ل.\r3 ـ فيه شك: ا ت ج ل ف ي، شك فيه: ق ك لب م، لا: ت ج ف ل ي، مما لا: ا ك لب ق، مما لم: م.\r4 ـ من: في: ف م.\r5 ـ و (1): ق ك لب م، شبهة: شبه: ي، ونفاه الجواب عنها عنه: ل ت: الجواب عنها: ك.\r6 ـ و (1): ت، شبهة: شبه: ي.\r8 ـ لنذكر: ليذكر: ك، فوائد: فضائل: ي.\r9 ـ بادراكه: بادراكها: ا.\r10 ـ الصائع الحكيم: صانع حكيم: ك، الرسل. الرسول: ق.\r11 ـ دليل: ج ف ق ك ل لب ي: ت م، بدليل: ك.\r12 ـ سورة النساء: 166، وقال: ك، ولو: لو: ل، انا"], [513, "أَهْلَكْناهُمْ بِعَذابٍ مِنْ قَبْلِهِ لَقالُوا رَبَّنا لَوْ لا أَرْسَلْتَ إِلَيْنا رَسُولاً فَنَتَّبِعَ آياتِكَ مِنْ قَبْلِ أَنْ نَذِلَّ وَنَخْزى» فبين الله تعالى أن بعثة الرسل لقطع الحجة.\rوالعلماء ذكروا وجوها ثلاثة فى تلك الحجة: أحدها أن يقولوا ان الله تعالى جل ثناؤه أن خلقنا لنعبده، فقد كان يجب أن يبين لنا العبادة التى يريدها منا أنها ما هى وكيف هى وكم هى فإنه وان وجب أصل الطاعة فى العقل لكن كيفيتها غير معلومة لنا، فبعث الله تعالى الرسل لقطع هذا العذر فإنهم إذا بينوا الشرائع المفصلة زالت أعذارهم.\rوثانيها: أن يقولوا أنك ركبتنا تركيب سهو وغفلة وسلطت علينا\r__________________\rا ت ج ف ق ك ل لب ي: م.\r1 ـ ربنا: ا ت ج ف ق ك لب ي، ل م.\r1، 2 ـ لقالوا ... نخزى: لقالوا الاية: ق.\r2 ـ سورة طه: 134. الله تعالى: ك ل، الله: ي، تعالى: ت ف ق ج ل م، ان بعثة الرسل نقطع: ت ف ل م ي، انه بعث الرسل لقطع. الرسول لتقطع: ا عذر المكلف: ج: ج ق ك لب.\r3 ـ الحجة: وحجته: ج.\r4 ـ في تلك الحجة: م فقط، احدها ان يقولوا قالوا: لب، يقول: ف: ت ف ق ك ل لب، الاول ا: ا ان يقولوا قالوا: م: ا م.\r5 ـ تعالى: جل ثناؤه: ت ج ف ك: ت ج ف ك ق ل لب م، عز ثناؤه: ي، ان: ت ج ف ل ي، ان وان: ا كان: ا ق لب م، خلقنا: جعلنا: ك، لتبده: لتعبده: ا.\r6 ـ يريدها: يريد: ك، كيف هي وكم هي: ت ج ف ل ي، كم هي وكيف هي: ق لب م، فانه وان وجب: ا ت ج ف ق ي لب، وان فان: م وجب وجبت: م، ك ل م.\rاصل: نفس: لب، لكن كفيتها: فكيفيتها: ف ي، غير معلومة: كررة في: ف، الله تعالى: ت ج ف ل ي، الله: ق ف ك، لب.\r8 ـ بينوا: بلغوا: لب.\r10 ـ ثانيها: الثاني: ج، ب: ا، فانابتهم: ك، سهو: ت ج"], [514, "الهوى والشهوات. فهلا أمددتنا يا إلهنا بمن إذا سهونا نبهنا، وإذا مال بنا الهوى منعنا، ولكنك لما تركتنا مع نفوسنا وأهوائنا، كان ذلك إغراء لنا على تلك القبائح.\rوثالثها: أن يقولوا هب أنا بعقولنا علمنا حسن الإيمان وقبح الكفر ولكن لم نعلم بعقولنا ان من فعل القبيح عذب خالدا مخلدا. لا سيما وكنا نعلم أن لنا فى فعل القبيح لذة، وليس لك فيه مضرة. ولم نعلم أن من آمن وعمل صالحا استحق الثواب لا سيما وقد كنا علمنا أنه لا منفعة لك فى شيء. فلا جرم لم يكن مجرد العلم بالحسن والقبح داعيا ولا وازعا. أما بعد البعثة اندفعت هذه الاعذار فكانت البعثة قطعا لعذر المعاندين من هذه الوجوه.\rوأما فائدة بعثتهم فيما لا يستقل العقل بدركه فقد ذكروا أمورا:\r__________________\rف ق م ي، من سهو: ل، شهوة: ا ك لب.\r1 ـ امددتنا يا الهنا: ت ج ق م ل، اندرتنا: ك، يمن: من: ل، فيهنا: ت ج ق ل م، ك.\r2 ـ مال: قال: ك، كان: فيكون: لب.\r3 ـ على تلك: عن: ل.\r4 ـ ثالثها: الثالث: ج، ج: ا، يقولوا: يقول: ك.\r5 ـ الكفر: ت ج ف ك ل لب ي، الكفران: ق م، لم: ت ج ف ق ك ل لب ي، لا: م، القبيح: القبح: م، عذاب ابدا: ف ي: ت ج ف ك ل لب م، عذابه: ا، يستحق العذاب: ق، مخلدا: مخلدا في النار: م فقط.\r6 ـ كنا: ت ج ف ق ك ل لب ي، انا: م، فعل القبيح: ا ت ج ق ك لب ي، الفعل القبيح: ف ل، فعل القبح: م، لك: ا، فيه: منه: ت، ج.\r7 ـ نعلم: يعلم: ا، الثواب: الثواب الخالد: في م فقط.\r7، 8 ـ وقد كنا: ت ج ل وكنا قد: ق ك لب م .. منفعة لك: ت ج ق ك ل لب م، وقد علمنا انه مالك منفعة: في ي.\r9 ـ اندفعت: فقد زالت: لب، فكانت: وكانت: ا ل.\r10 ـ البعثة: بعثة الانبياء: ف، قطعا لعذر: عذرا: ي. المعائدين: ت ج ف ق ل لب ي، المعذورين: ا، العاذرين: ك، المعذورين: م.\r11 ـ بعثهم: ا ت ج ق ك، بعثهم: ف ل لب م ي، فيما:"], [515, "أحدها ان العقل لا يدل إلا على الصفات التى يحتاج الفعل إليها. أما السمع والبصر والكلام وسائر الصفات الخبرية فلا طريق إليها إلا السمع.\rوثانيها: أن المكلف يبقى خائفا فيقول لو اشتغلت بالطاعات كنت متصرفا فى ملك الله تعالى بغير إذنه، ولو لم أشتغل بها فربما عذبت بترك الطاعة، فيبقى فى الخوف على التقديرين وعند البعثة يزول هذا الخوف.\rوثالثها: أنه ليس كل ما كان قبيحا عندنا، كان قبيحا فى نفسه. فإن النظر إلى وجه الحرة العجوزة الشوهاء قبيح، وإلى وجه الأمة الحسناء حسن فى العقل لا فى الشرع.\rورابعها: أن الأشياء المخلوقة فى الأرض منه غذاء ومنه دواء ومنه\r__________________\rفما: ي.\r1 ـ احدها: ا: ا، يدل: بد: ا، الفعل: ت ج ق ك ل، العقل: ف لب ي، م.\r2 ـ الخيرية: الجزئية: م ي.\r4 ـ ثانيها: ب: ا. فيقول: يقول: ي، بالطاعات: بالطاعة: ق ك، كنت: لكنت في م، كيف: ل.\r5 ـ اشتغل: ت ج ق ك ل لب ي، يشتغل: ف م، بها: ج ق ك لب ل م، به: ت ف ي، فريما: ك، عذبت: ت ج ك ل لب ي، عذب: ا ف ق، اعذب: م.\r6 ـ بترك: ت ج، على ترك: ك ل م، يزول: الاول: ا.\r6، 7 ـ على التقديرين وعند البعثة يزول هذا الخوف: ت.\r8 ـ ثالثها: ج: ا، عندنا: ت.\r9 ـ وجه العترة: الوجه: ا، وجه: ق ك لب، العجوزة: ت، العجوز: ج ك م، المعجوزة: ل، الشوها ء: الشهواء: ك.\r10 ـ في العقل لا في الشرع: ق، ولا كذلك في الشرع: لب، وفي الشرع خلافة: ل، في الشرع: ت ج ف ك م ي.\r11 ـ رابعها: د: ا، المخلوقة: المخلوق: ف، منه (1 ـ 3): ا ت ج ل لب، منها: ف ق ك م، منه غداء و: ل."], [516, "سم. والتجربة لا تفى بمعرفتها إلا بعد الأدوار العظيمة. ومع ذلك ففيها خطر على الأكثر. وفى البعثة فائدة معرفة طبائعها ومنافعها من غير ضرر وخطر.\rوخامسها: أن المنجمين عرفوا طبائع درجات الفلك، ولا يمكن الوقوف عليها بالتجربة لأن التجربة يعتبر فيها التكرار، والأعمار البشرية كيف تفى بأدوار الكواكب الثابتة. ثم هب انهم وقفوا على الكل بالرصد. فكيف وقفوا على أحوال عطارد مع أن الآلات الرصدية لا تفى بأحواله لصغره، وخفائه وقلة نوره، وقلة بعده عن الشمس حالتى التشريق والتغريب.\rوسادسها: أن الإنسان مدنى بالطبع والاجتماع مظنة التنازع المفضى إلى التقاتل. فلا بد من شريعة يفرضها شارع لتكون مرغبة فى الطاعات وزاجرة عن السيئات.\rوسابعها: لو فوض كيفية العبادة إلى الخلق فربما أتى كل طائفة\r__________________\r1 ـ الا بعد: ف، الادوار: الادوا: ك.\r2 ـ وفي: فغي: ق.\r3 ـ ضرر و: ك.\r4 ـ خامسها: ه: ا، طبائع: ك.\r5 ـ النكرار: الفكر: ا.\r5، 6 ـ لان ... الثابتة: ف.\r6 ـ هب: ا ت ج ف ق ل لب ي، ك م، وقفوا: وان وقفوا: ك.\r7 ـ بالرصد: بالبصر: ي، الالات: الاله: لب.\r8 ـ لصفرة: الصغيرة: ا، قلة: ت ج ق ك، فله: ف لب ي: م.\r9 ـ عن: ك.\r10 ـ سادسها: و: ا، الاجتماع: ج ق لب م ي، الاحتياج: ت ج هامش ل ف.\r11 ـ المغضى: ك، التقاتل: ج ق ك لب م ي، التقابل: ت، التقاطع: ا، القتال: ف، بياض في ل، يفرضها: يعرضها: ا.\r12 ـ وزاجرة عن السيئات: ج ق ك لب م، ت ف ل ي.\r13 ـ سابعها: ز: ا، ج، فوض: ت ج ف ق ل لب م"], [517, "بوضع خاص، ثم أخذوا يتعصبون لها فيفضى ذلك إلى الفتن. أما وضع الشريعة مما ينافى ذلك.\rوثامنها: الّذي يفعله الإنسان بمقتضى عقله، يكون كالفعل المعتاد والعادة لا تكون عبادة. وأما الّذي يأمر به من كان معظما فى قلبه ولا يكون هو واقفا على لميته، كان اتيانه به لمحض العبادة. ولذلك ورد الأمر بالأفعال الغريبة فى الحج.\rوتاسعها: أن العقول متفاوتة والكامل نادر. والأسرار الإلهية عزيزة جدا، فلا بد من بعثة الأنبياء، وإنزال الكتب عليهم، إيصالا لكل مستعد إلى منتهى كماله الممكن له، بحسب شخصه.\rوعاشرها: أن كل جنس تحته أنواع فإنه يوجد فيما بين تلك\r__________________\rي، فتص: ا، فرض: ك.\r1 ـ بوضع: موضع: في ف م، يتعصبون لها: ت ج ق ك ل لب، يتعصبون بها: ا: ف ي، يبقضون لها: ه.\r2 ـ مما: ت ج ل، فعما: ف ق لب م، فما: ي، فغيما ما: ك.\r3 ـ ثامنها: ج: ا، سابعها: ج، للذي: ت ج ف ل ي، ان الذي: لب م، كالفعل: ا ت ج ف ق ل لب ي، كالطفل: ك، كفعل: م.\r4 ـ عبادة: عادة: ف، واما: اما: ق ك لب، به من: وان: ك.\r5 ـ واقفا: مقتضى عقلة واقفا: ق، لميته: ا ج ف ك لب ل ي، كميته: ق، سببه: م، هيئته: ت، اتيانه: اثباته: ك، به: م فقط، لمحض: ا ت ج ف ك ل ي، محض: ق لب م.\r7 ـ تاسعها: ط: ا، ثامنها: ج، الالهية: الازلية: ق.\r8 ـ الانبياء: الانبياء عليهم السلام: ق.\r8، 9 ـ ايصالا لكل: ج ل، ايصالا فكل: لب، ليصير كل: ف ي، ايضا لا لكل: ت ق ك م.\r10 ـ عاشرها: ي: ا، تاسعها: ج كل: ت ج ف ق ك ل لب م ي، لكل: ا."], [518, "الأنواع نوع واحد، هو أكملها. وكذا الأنواع بالنسبة إلى الأصناف، والأصناف بالنسبة إلى الأشخاص، والأشخاص بالنسبة إلى الأعضاء. فأشرف الأعضاء ورئيسها هو القلب، وخليفته الدماغ ومنه تنبعث القوى على جميع جوانب البدن. فكذا الإنسان لا بد فيه من رئيس. والرئيس اما أن يكون حكمه على الظاهر فقط، وهو السلطان، أو على الباطن وهو العالم، أو عليهما معا، وهو النبي عليه السلام أو من يقوم مقامه فالنبى يكون كالقلب فى العالم. وخليفته كالدماغ. وكما أن القوى المدركة إنما تفيض من الدماغ على الأعضاء فكذلك قوة البيان والعلم إنما تفيض منه بواسطة خليفته على جميع أهل العالم.\rوحادى عشرها: الهداية إلى الصناعات النافعة. قال الله تعالى فى داود عليه السلام: (وَعَلَّمْناهُ صَنْعَةَ لَبُوسٍ لَكُمْ). وقال لنوح\r__________________\r1 ـ الانواع (1): ك، هو: وهو: ق، الانواع (2): ك.\r(10/ 517)، 2 ـ فانه .. الاصناف: ي.\r2 ـ الاصناف (1، 2): الاضافات: ا.\r3 ـ هو: ت ج ف ق ل ي، ك لب م.\r5 ـ فيه: له: ق، والرئيسي: ف.\r6، 8 ـ او عليهما معا ... النبي الشيء: ك عليه السلام: ف ي، صلى الله عليه وسلم: ت او من يقوم مقامة .. في العالم: ت ج ف ق ك لب ل ي، او عليهما معا وهو النبي فالنبي يكون كالقلب في العالم: م: ا.\r9 ـ فكذلك: ت ج ف ل ي، فكذا: ا ق ك لب، وكذا: م، العلم: ق ك م، التعليم: ج لب ي، التعلم: ق ف، تعيض (2): يفيد: ف.\r10 ـ منه: فيه: ق.\r11 ـ حادي عشرها: يا: ا، عاشرها: ج.\r12 ـ داود: قصة داود: ا، حق داود: ق ل لب، عليه السلام: ا ت ق ك ل لب ي، عليه الصلاة والسلام: م: ج، لكم: لب، سورة الانبياء: 80، لنوح: ت ج ك ل م ي، تعالى لنوح: تب، نوح: ف، في نوح: ق."], [519, "عليه السلام: (وَاصْنَعِ الْفُلْكَ بِأَعْيُنِنا) ولا شك أن الحاجة إلى الغزل والنسج والخياطة والبناء وما يجرى مجراها أشد من الحاجة إلى الدرع. وتوقيفها على استخراجها بالتجربة خطر عظيم للخلق فوجب بعثة الأنبياء لتعليمها.\rوثانى عشرها: أنه لا بد فى المعيشة من علمى الأخلاق والسياسة. فلا بد من البعثة لتعليمها ولهذا قال الله تعالى لنبيه عليه السلام: (خُذِ الْعَفْوَ وَامُرْ بِالْعُرْفِ وَأَعْرِضْ عَنِ الْجاهِلِينَ). وقال: (إِنَّ اللهَ يَامُرُ بِالْعَدْلِ وَالْإِحْسانِ). وقال تعالى: (فَبِما رَحْمَةٍ مِنَ اللهِ لِنْتَ لَهُمْ) وقوله: (وَإِنَّكَ لَعَلى خُلُقٍ عَظِيمٍ) فقد ظهرت فوائد البعثة من هذه الوجوه.\r__________________\r1 ـ عليه السلام: ا ت ق ك ل لب ي، عليه الصلاة والسلام: م، ج، سورة هود: 37، ان: بان: لب.\r2 ـ النسج والخياطة: ت ج ف ق ك ل لب، النسج والحياكه: ي، الخياطة: م، مجراها: مجراهما: ك.\r3 ـ توفيقها: ج ك م، توفيقها: ت ل، ضرر عظيم خطر: ل للخلق: ا ت ف ك ل لب ي، للخلق ضرر عظيم: ج، خطر عظيم عني الخلق: ق، خطر عظيم: م، فوجب: فواجب: ل.\r4 ـ لتعليمها: ت ج ف ك ل ي، لتعلمها: م، عليهم السلام لتعليمها: ق لب.\r5 ـ ثاني عشرها: يب: ا، حادي عشرها: ج، انه: م، علمى الاخلاق: ا ت ج ق ك ل لب، علم الاخلاق: ف ي، علم الاحكام: م.\r6 ـ لتعليمها: ت ج ك لب ي، بتعليمها: ل، تعليمها: ف، ليعلمها: م، لتفهيمها: ق، الله: ا ق ل ي: ت ج ف لب م، عليه السلام: م.\r7 ـ سورة الاعراف: 199، قال: قال تعالى: م، ان الله: ان الله تعالى: لب.\r8 ـ سورة النحل: 90، تعالى: ج ف لب م ي ت، ا ق ك، سورة آل عمران: 159 ولو كنت الاية: ك.\r9 ـ وقوله: ج ف م ي، الى قوله: ا ت ل، وقوله تعالى: لب، وقال تعالى: ك، الى قوله فتوكل على الله وقال تعالى: ق، سورة القلم: 4، وانك: انك: ا ك، البعثة: ف."], [520, "وأما شبهة اليهود، فالجواب عن أولاهما أن الله تعالى بين أن شريعة موسى عليه السلام مؤقتة بيانا اجماليا، ولم يبين كمية الوقت.\rقوله لو كان كذلك لعرف ذلك بالتواتر، كما عرف أصل ذلك الدين بالتواتر. قلنا لم لا يجوز أن يكون توتر الدواعى إلى نقل الأصل أتم من توفرها على نقل الكيفية. فلا جرم كان أحد التواترين أقوى من الآخر.\rوالجواب عن أخراهما أن بلوغ رواة هذا الخبر إلى حد التواتر فى جميع الأعصار غير معلوم وإذا كان كذلك، لا جرم لا يحصل العلم بهذا الخبر. وبالله التوفيق.\rمسئلة:\rفى عصمة الأنبياء عليهم السلام.\r__________________\r1 ـ شبهة: ق ل لب م، شبهتها: ت ج ف ي، شبه: ك، فالجواب: والجواب: ت، عن اولاهما: ت ج ف ق ل، اولهما: ا، الاول منها وهو: ي، الاول: ك لب، عنها: م.\r2 ـ شريعة موسى عليه السلام: ت ف ق ل ي: ت ج ف ق ل ي، شريعته: ك لب م.\r3، 4 ـ كما عرف .. ذلك: ت ج ل الدين: ل ا قلنا: قلت: م: ت ج ق ك ل لب م، قلنا: ف ي.\r4 ـ الى: ا ت ج ك ل لب، على: م ي.\r5 ـ اتم: اتم واقوى: ق، لو فرها: ت ج ق ل ي، توفره: م، توفر الدواعي: لب، توافرها: ك، فرها: ف، التواترين: ا ت ج ف ك ل لب ي، التومين: م.\r6 ـ من: عن: لب.\r7 ـ اخراهما: اخراها: ك.\r6، 8 ـ اقوى من ... حد التواتر: تكرر في ك ك.\r8 ـ معلوم: ا ت ج ف ق ك ل لب ي، معلوم لنا: م، واذا: ولما: ا، لا (2): ت ف ل لب ي، لم: ج ك م.\r9 ـ العلم بهذا: بهذا العلم: ل، وبالله التوفيق: ف ك لب.\r11 ـ عليهم: ا ت ج ف ك لب ل ي، عليهم الصلاة و: ق م."], [521, "القائلون بالعصمة منهم من زعم أن المعصوم هو الّذي لا يمكنه الإتيان بالمعاصي.\rومنهم من زعم أنه يكون متمكنا منه. والأولون منهم من زعم أنه المختص فى بدنه أو نفسه بخاصية تقتضى امتناع إقدامه على المعاصى.\rومنهم من ساعد على كونه مساويا لغيره فى الخواص البدنية لكن فسر العصمة بالقدرة على الطاعة أو بعدم القدرة على المعصية وهو قول أبى الحسن الأشعرى. والذين لم يسلبوا الاختيار فسروها بأنه الأمر الّذي يفعله الله تعالى بالعبد وعلم أنه لا يقدم مع ذلك الأمر على المعصية بشرط أن لا ينتهى فعل ذلك الأمر إلى حد الالجاء.\rوهؤلاء احتجوا على فساد قول الأولين من العقل بأن الأمر لو كان كما قالوه، لما استحق المعصوم على عصمته مدحا، ولبطل الأمر، والنهى، والثواب والعقاب. ومن النقل بقوله تعالى: «قُلْ إِنَّما\r__________________\r1 ـ من زعم: وزعم: ي.\r2 ـ الاتيان: الانبياء: ك.\r1، 2 ـ ان المعصوم ... ان المعصوم هو: ك م، انه ان: ف: ت ج ف ق ك ل لب م، انه: ي.\r4 ـ نفسه: ت ج ف ق ل لب ي، في نفسه: ك م.\r6 ـ ساعد: ت ج ف ق ل لب م، يساعد: ي، تباعد: ا،: ك.\r7 ـ او بعدم وبعد: ي، ومعلوم: ك .. المعصية: ا ت ج ف ق ك ل لب ي: م.\r8 ـ ابي: ابو: ا، الحسن: الحسين: ق، الاشعري: ت ج ك م، ف ق ل لب ي، الذين: ج ك م، الذي: ت ل، فسروها: فسروه: ا ك.\r9 ـ بانه: بانها: لب تكرر في ق، تعالى: ق، يقبدم مع: يتقدم في: ق، مع: ك.\r10 ـ ان: انه: ك.\r12 ـ بقوله: ت ج ف ق ل لب ي، لقوله: ا، قوله: ك م. قل: ت ج ق ك ل."], [522, "أَنَا بَشَرٌ مِثْلُكُمْ يُوحى إِلَيَّ» و «لا تَجْعَلْ مَعَ اللهِ إِلهاً آخَرَ» «وَلَوْ لا أَنْ ثَبَّتْناكَ لَقَدْ كِدْتَ تَرْكَنُ إِلَيْهِمْ شَيْئاً قَلِيلاً» «وَما أُبَرِّئُ نَفْسِي».\rثم ان هؤلاء زعموا أن أسباب العصمة أمور أربعة:\rأحدها: أن يكون لنفسه أو لبدنه خاصية تقتضى ملكة مانعة من الفجور. والفرق بين الفعل والملكة معلوم.\rوثانيها: أن يحصل له العلم بمثالب المعاصى، ومناقب الطاعات.\rوثالثها: تأكيد تلك العلوم بتتابع الوحى والبيان من الله تعالى.\rورابعها: أنه متى صدر عنه أمر من باب ترك الأولى أو النسيان لم يترك مهملا بل يعاتب وينبه عليه ويضيق الأمر فيه عليه.\rفإذا اجتمعت هذه الأمور الأربعة، كان الشخص معصوما عن المعاصى لا محالة. لأن ملكة العفة إذا حصلت فى جوهر النفس، ثم\r__________________\r1 ـ يوحى اليه: ت ج ف ل ي: ق ك لب م، سورة الكهف: 110، سورة الاسراء: 39.\r2 ـ اليهم: ل، شيئا قليلا: ق ك ج، سورة الاسراء: 74 وقوله: م، نفسي: ج سورة يوسف: 53.\r3 ـ ان (1): ك اربعة: ك.\r4 ـ احدها: ا: ا، لبدنه: ت ج ك ل م ي، بدنه: ف لب.\r5 ـ الفعل: ت ج ف ك ل م ي، العقل: لب.\r6 ـ ثانيها: ب: ا.\r7 ـ ثالثها: ج: ا، تلك العلوم: ذلك المعلوم: ك.\r8 ـ رابها: د: ا، امر: ا ت ج ف ق ل لب، امر من الامور: ك م.\r9 ـ يعاتب: ف ق ك ل م ي، يعاقب: ا لب،: ت ج، فيه عليه: عليه فيه: ي، عليه: ف ق.\r10 ـ فاذا: واذا: ف ي.\r11 ـ لا محالة: ك."], [523, "انضاف إليها العلم التام بما فى الطاعة من السعادة وفى المعصية من الشقاوة، صار ذلك العلم معينا له على مقتضى الملكة النفسانية. ثم الوحى يصير متمما لذلك ثم خوف المؤاخذة على القدر القليل يكون مؤكدا لذلك الاحتراز فيحصل من اجتماع هذه الأمور تأكد حقيقة العصمة.\rثم اتفقت الأمة على كون الأنبياء معصومين عن الكفر إلا الفضيلية من الخوارج. فإنهم اعتقدوا أن كل ما ينطلق عليه اسم العصيان فهو كفر. ثم انهم جوزوا على الرسل المعاصى. فلا جرم جوزوا الكفر عليهم. ويدل على فساده أنه لو جاز الكفر عليه لكان الاقتداء به فيه واجبا لقوله تعالى: (فَاتَّبِعُونِي) وفساد ذلك يدل على فساد قولهم.\rومن الناس من لم يجوز الكفر لكنه جوز اظهار الكفر على سبيل التقية.\rواحتجوا عليه بأن اظهار الإسلام إذا كان مفضيا إلى القتل كان\r__________________\r1 ـ الطاعة من السعادة: الطاعات من السعادات: ق.\r2 ـ معينا: معيا: ف، التفسانية: الانسانية: ف.\r3 ـ متمما: ج ل ك م، متهما: ت، لذلك: له: ك.\r4 ـ مؤكدا: ا ت ج ف ق ك ل لب ي، توكيدا: م، الاحتراز الاحراز: ك، الامور: ق، تاكد: ت ج ف ق ل لب ي، تاكيد: ك م.\r6 ـ عن: من: لب الفضيلية: ج ق لب م، الفضيلة: ا ت ف ل، الفضلية: ك ي.\r7 ـ فانهم: ا، ما: من ا ينطلق: ت ج ف ق ك ل لب ي، يطلق، م.\r8 ـ كفر: كافر: ا، ثم انهم: لانهم: ك.\r9 ـ الكفر: ف، عليه: ا ت ف ك ي ل، عليهم: ج ق لب م.\r10 ـ به فيه: ا ت ج ل ي، بهم فيه: ق ك، به: ف، بهم: م، تعالى: ق م، فاتبعوه: ج م، سورة آل عمران: 31.\r12 ـ يجوز: بجوزوا: ف."], [524, "اظهاره إلقاء للنفس فى التهلكة، وهو غير جائز وهذا أيضا باطل لأنه يفضى إلى خفاء الدين بالكلية. ولأنه لو جاز ذلك لكان أولى الأوقات به مبدأ ظهور الدعوة. لأن الخلق فى ذلك الوقت يكونون بالكلية منكرين له فكان يلزم أن لا يجوز لأحد من الأنبياء اظهار الدعوة. ولأن الخوف الشديد كان حاصلا لإبراهيم عليه السلام فى زمان نمرود وموسى عليه السلام فى زمان فرعون. مع أنهم لم يمتنعوا عن اظهار الحق.\rومن الناس من لم يجوز الكفر ولا اظهاره، لكنه جوز الكبائر عليهم.\rوالأكثرون لم يقولوا به لوجوه:\rالأول: لو صدرت الكبيرة عنهم لكانوا أقل درجة من عصاة الأمة. وذلك غير جائز. بيان الملازمة أن درجات الأنبياء فى غاية\r__________________\r1 ـ اظهاره: ف، النفس: ا ت ج لب ل، النفس: ف ق ك م ي، التهلكة: الهلكة: ي.\r2 ـ خفاء: ت ك ل لب م ي، اخفاء: ج ف ق، ذلك: ك.\r3 ـ الاوقات .. ظهور: ت ج ل م، اوقات منه بذلك منذ اظهر: ك، الدعوة: الذين: ل، في ذلك الوقت: ف.\r4 ـ فكان: ا ج ف ك ي، وكان: ق ل لب م، الانبياء: الانبياء عليهم السلام: ق.\r7، 5 ـ الان الخلق ... اظهار الدعوة: ت موجود في هامش ج ايضا.\r5 ـ ولان: ب ج ق ك ل لب م ي، لان: ا.\r6 ـ انهم: ا ت ج ف ق ك ل لب ي، انهما: م.\r7 ـ اظهار الحق: ا ت ج ف ق ك ل لب ي، الدعوة: م.\r8 ـ يجوز: ا ت ج ف ق ك ل لب ي، يجوزوا: م، لكنه: ا ت ج ف ق ل ي، لكنهم: ك م، ولكنه: ل، جوز: ا ج ف ق ي، جوزوا: ت ل لب م ك، الكبائر: الكفار: ف.\r10 ـ به او جوه: بوجوده: ف.\r11 ـ الاول انه: ق: ا: ا، الكبيرة: الكبير: ف.\r12 ـ حائر: ك، الانبياء: الانبياء عليهم السلام: ق."], [525, "الشرف. وكل من كان كذلك كان صدور الذنب عنه أفحش. ألا ترى إلى قوله تعالى: (يا نِساءَ النَّبِيِّ مَنْ يَاتِ مِنْكُنَّ بِفاحِشَةٍ مُبَيِّنَةٍ يُضاعَفْ لَهَا الْعَذابُ ضِعْفَيْنِ) والمحصن يرجم وغيره يحد وحد العبد نصف حد الحر وأما إنه لا يجوز أن يكون النبي أقل حالا من الأمة فبالاجماع.\rالثانى: أن بتقدير إقدامه على الفسق وجب أن لا يكون مقبول الشهادة لقوله تعالى (إِنْ جاءَكُمْ فاسِقٌ بِنَبَإٍ فَتَبَيَّنُوا) لكنه مقبول الشهادة وإلا لكان أدنى حالا من عدول الأمة.\rالثالث: أن بتقدير إقدامه على الكبيرة يجب زجره عنها. فلم يكن ايذاؤه محرما لكنه محرم لقوله تعالى: (إِنَّ الَّذِينَ يُؤْذُونَ اللهَ وَرَسُولَهُ لَعَنَهُمُ اللهُ فِي الدُّنْيا وَالْآخِرَةِ).\r__________________\r1 ـ من: ما: ا.\r2 ـ ترى: ا ت ج ق ك ل ي، يرى: ف م، تعالى: ا.\r3 ـ ضعفين: ت ف ك ل لب، سورة الاحزاب: 30، والمحصن يرجم: ا ت ج ف ق ك ل لب ي، يرجم: م، يعد: ا ت ج ك ل لب، يجلد: ف ق ي: م، حد: كان حد: م فقط.\r4 ـ الحر: الامة: ف، يكون: ك، النبي: النبي عليه السلام لب، حالا: حال: ك.\r5 ـ فلالاجماع: فالاجماع: ك.\r6 ـ الثاني: ب: ا، وثانيها: ج يتقدير: بالتقدير: ك، اقدامه: قدامه: ق.\r7 ـ سورة الحجرات: 6.\r9 ـ الثالث: ج: ا، وثالثها: ج، الكبيرة: الكبائر: ك.\r9، 10 ـ ثم يكن: ا ت ج ف ق ل ي، ولم يكن: م، ولا يكون: لب، ولو وجب زجره عنها لم: ك.\r10 ـ ايدازه: ل، لكنه: ت ج ق ك ل لب م، وايدازه: ق ي محرما: محرم: ت، تعالى: ت ي، مؤدون: يؤذن: ت.\r11 ـ في الدنيا والاخرة: م، سورة الاحزاب: 57."], [526, "الرابع: لو أتى بالكبيرة لوجب علينا الاقتداء به لقوله تعالى: (فَاتَّبِعُونِي) فيفضى إلى الجمع بين الحرمة والوجوب وهو محال. أما الذين لم يجوزوا الكبائر، فقد اختلفوا فى الصغائر. واتفق الأكثرون على أنه لا يجوز منهم الإقدام على المعصية قصدا سواء كانت صغيرة أو كبيرة، بل يجوز صدورها منهم على أحد وجوه ثلاثة:\rأحدها: السهو والنسيان.\rوالثانى: ترك الأولى.\rوالثالث: اشتباه المنهى بالمباح.\rواختلفوا فى الوقت الّذي تعتبر فيه العصمة. أما الفضيلية من الخوارج فقد جوزوا بعثة من يعلم الله تعالى منه أنه يكفر. ومنهم\r__________________\r1 ـ الرابع: د: ا، ورابعها: ج، بالكبيرة: الكبيرة، ك، علينا: لب، به: ت ج ف ق ك ل لب، به فيها: م هامش ج. لقوله: كقوله: م.\r(10/ 525)، 1 ـ ان الذين .. لقوله: ي.\r2 ـ سورة آل عمران: 21، الحرمة والوجوب: الوجوب والحرمة: في م فقط.\r3 ـ اما: واما: ق م، فقد: ت ج ف ق ك ل لب ي، منهم فقد: ا: ا م، واتفق: ا ت ج ف ك لب، فاتفق: ل، والا اتفق: م.\r4 ـ على (1): ج ل، منهم على: ك م، ت، قصدا: ا ت ج ك ل لب ي، قصد: ف.\r4، 5 ـ منهم ... بل يجوز: ق.\r5 ـ منهم: عنهم: ق، ك.\r7 ـ احدها: ا: ا.\r8 ـ الثاني: وثاني: ك، ب: ا.\r9 ـ الثالث: ج: ا، بالمباح: بالمبرح: ك.\r10 ـ الفضيلية: ج ف ق لب م، الفضيلة: ت ك ل ي، الفضليلة: ا.\r11 ـ تعالى: ك."], [527, "من لم يجوز ذلك، ولكن جوز بعثة من كان كافرا قبل الرسالة وهو قول ابن فورك، لكنه زعم أن هذا الجائز لم يقع.\rومن الحشوية من زعم أن الرسول عليه السلام كان كافرا قبل البعثة لقوله تعالى (وَوَجَدَكَ ضَالًّا فَهَدى). ولقوله تعالى (ما كُنْتَ تَدْرِي مَا الْكِتابُ وَلَا الْإِيمانُ) واتفق المحصلون على فساد ذلك.\rومن الناس من طرد هذا الحكم فى الأئمة وقال كما لا يجوز كون الرسول كافرا قبل البعثة، لا يجوز أن يكون الامام أيضا كافرا قبل الإمامة. ولذلك يقدحون فى إمامة الشيخين.\rوأما أنه هل يجوز فعل الكبيرة على الأنبياء قبل البعثة فالأكثرون من أهل السنة جوزوا ذلك مستدلين بأحوال اخوة يوسف عليهم السلام ومنهم من لم يقل به، ولم يقل بنبوتهم. ثم الذين جوزوا ذلك قالوا منهم من فعل الكبيرة قبل البعثة، لكنهم إنما جوزوا ذلك\r__________________\r1 ـ ولكن: ت ج ف، ولكنه: ي، لكنه: ك لب م ي، لكن: ل.\r2 ـ الرسول: النبي: ق، عليه السلام: ت ك م ي صلى الله عليه وسلم: ا ف، عليه الصلاة والسلام: ق: ج ل لب.\r4 ـ تعالى (1): م، سورة الضحى: 7، تعالى (2): ت ج م ي، ما: وما: لب م.\r5 ـ سورة الزخرف: 52، المحصلون: المحققون: ق.\r6 ـ طرد: زعم اطراد: ق، قال: قالوا: ك.\r7 ـ الرسول: الرسول عليه السلام: ف.\r7، 8 ـ لا يجوز ... الامام: كذلك الامام لا يجوز ان يكون: لب. ايضا: ت ج ف ي، قيل ان يكون في: م، ناقص في: ك ل.\r8 ـ امامه: امامة حق: ك.\r9 ـ واما: ت ج ف ل ي، فاما: ق ك م، اما: لب، فعل: تكرر في ف، الانبياء: الانبياء عليهم السلام: ق لب.\r10 ـ باحوال: ت ج ف ل لب ي، افعال: ك لب م.\r11 ـ عليهم السلام: ت ف لب ي، عليه السلام: ل ق ك، م، لم يقل به: ف.\r12 ـ قالوا: ج قالوا منهم ... ذلك: ت."], [528, "على سبيل الندرة بحيث يتوبون عنه ويشتهر حالهم فيما بين الخلق بالصلاح. فاما لو أصروا على الكبائر بحيث يصيرون مشهورين بالخلاعة، فذلك غير جائز، لأن المقصود من بعثتهم يفوت على هذا التقدير.\rواما أنه هل يجب كونهم معصومين عن الصغائر قبل البعثة وبعدها، فالروافض أوجبوا ذلك، ومن عداهم جوزوا ذلك لكن اختلفوا فى كيفيتها.\rأما النظام والأصم وجعفر بن مبشر فإنما جوزوا ذلك على طريق السهو والنسيان فيقال لهم اما أن يقولوا. إنه حال السهو مكلف، وهو غير جائز، لأنه تكليف ما لا يطاق، أو لا يبقى مكلفا، فحينئذ لا يكون ذلك معصية، أو يقولوا إنما عوتبوا على ترك التحفظ من النسيان، وهو قول أهل السنة.\r__________________\r1 ـ الندرة: الندر: ت، يشتهر: ت ج ق ك ل، يشتمر: لب، يستر: ف م، على سبيل ... حالهم: ي.\r2 ـ لو: ان: لب، يحيث: ا.\r3 ـ بالخلاعة: ت ج ك ل لب م ي، بالخلافة: ف، بالفسق: ق، لان: ولان: ك، بعثهم: بعثهم: ف ي، هذا: ت ج ف ك ق لب ق ي، ذلك: م.\r6 ـ اوجبوا: وجبوا: ف، جوزوا ذلك: م، جوزوا: ف ي، جوزوها: ا ت ج ق ك ل لب.\r8 ـ مبشر: ا ت ج ف ك ل لب ي، المبشر: ق، بشر: م هامش ل.\rفانما ... اما ان: ا ت ج ف ق ك ل لب ي: م.\r9 ـ يقولوا به: ي تقولوا: ك: ا ت ج ف ق ك ل لب ي، يقولون: م، انه .. والنسبان: ك .. مكلف: ت ج ل ك م، انه يبقى حال السهو والنسيان: ق مكلفا: ف ق، انه حالى السهو: ي يبقى مكلما: لب ي.\r10 ـ ما: بما: ق، مكلفا: ملكا: ي، فحينئذ: وحينئذ: م فقط.\r11 ـ يقولوا: نقول: لب، عوتبوا: عوقبوا: ق ل.\r12 ـ السنة: السنة والجماعة: في م فقط."], [529, "ومن الناس من حمل تلك الزلات على ترك الأولى، لا يقال لو كان ترك الأولى سببا لاستحقاق العقاب لعوتبوا أبدا. اذ لا عبادة إلا وفوقها عبادة ولا يستحق العقاب على المباحات. لأنا نقول استحقاق العقاب على ترك الأفضل إنما يتوجه إذا كان يلزم منه فوات مصلحة أو حصول مفسدة لا يمكن احتمالها فى الاعتذار عن قصة آدم عليه السلام.\rمنهم من زعم أن قوله تعالى: (وَعَصى آدَمُ) أى عصى أولاد آدم كما فى قوله (وَسْئَلِ الْقَرْيَةَ).\rومنهم من سلم أن المراد منه آدم، ثم زعم ابن فورك ان ذلك كان قبل الرسالة.\rومنهم من قال كان ذلك بعد الرسالة ثم زعم الاصم أنه كان على\r__________________\r2 ـ الاولى: ت ج ف ل م ي، الافضل: ق ك لب، العقاب: ت ق ك ل لب م، العتاب: ج ف ي، لعولبوا: لموقب: ك.\r3 ـ عبادة (2): عبادة اخرى: ق لب ج، ولا يستحق: ت ج ف ق ل ي، لاستحقوا: ك لب م، العقاب: ت ف ق لب م، العتاب: ج ك ل ي، المباحاث: المناجات: ك.\r4 ـ العقاب: ت لب م، العتاب: ج ف ك ل ي، اذا كان يلزم: ت ج، اذا لزم: م، اذ لو يلزم: ك، اذا لم يلزم: ا ف ق ل ي.\r5 ـ مفسدة: ت ج، مضرة: ك ل ف م.\r6 ـ عليه الصلاة و: م السلام: ا ت ج ف ق ك ل لب، ي.\r7 ـ تعالى: ك م، ت ج ف ل لب، وعصى: ا ت ج ف ق ك ل، فعصى: لب م، سورة طه: 111 وبه فغوى: م، ربه: ق، عصى (2): وعصى: ف ق لب، منهم ومنهم: ك من زعم .. اولاد آدم: ي.\r8 ـ في قوله: في قوله منهم: ي، في قوله تعالى: ل.\r9 ـ منه: ج، به: ف ق ي: ت ك ل لب م، آدم: آدم عليه السلام: ق ك لب، ثم: و: لب، زعم: زعموا: ف.\r11 ـ بعد: ف، انه: انه ان: ك."], [530, "سبيل النسيان، لقوله تعالى (فَنَسِيَ). والاعتراض عليه أن إبليس ذكر لآدم وقت الوسوسة أمر النهى، فقال: (ما نَهاكُما رَبُّكُما عَنْ هذِهِ الشَّجَرَةِ). ومع هذا التذكير يمتنع حصول النسيان. وأيضا أن الله تعالى عاتبه على ذلك فى قوله: (أَلَمْ أَنْهَكُما عَنْ تِلْكُمَا الشَّجَرَةِ) وآدم وحواء اعترفا بالزلة: فقالا (رَبَّنا ظَلَمْنا أَنْفُسَنا). والله تعالى قبل توبتهما فقال: (فَتابَ عَلَيْهِ). وكل ذلك ينافى النسيان.\rومنهم من سلم أن آدم كان متذكرا للنهى لكنه أقدم على التأويل وهو من وجوه.\rأحدها: زعم النظام أن آدم فهم من قوله تعالى (وَلا تَقْرَبا هذِهِ الشَّجَرَةَ) الشخص وكان المراد النوع. وكلمة هذا كما تكون إشارة إلى الشخص كذلك تكون إشارة إلى النوع كقوله عليه السلام:\r__________________\r1 ـ سورة طه: 115، و: ا ت ج ف ق ل ي: ك لب م.\r2 ـ لادم: ف ق م ي، آدم: ا ت ج ك ل، آدم عليه السلام: لب، وقت: قبل: ا.\r3 ـ سورة الاعراف: 20، التذكير التذكر: ا لب يمتنع: ا ت ج ف ق ك لب ل ي، التذكير امتنع: م، ان الله: ا ت ج ف ك ل لب ي، فان الله: ق، انه: م.\r4 ـ في قوله: ت ج ق ك ل لب م تعالى: ك لب، فقال: ف ي: سورة الاعراف: 22.\r5 ـ وآدم: فادم: م، بالزلة: باللذلة: م فقط، افقسنا: ا ت ج ف ل لب، سورة الاعراف: 23.\r6 ـ عليه: عليهما: لب، سورة البقرة: 37.\r7 ـ متذكرا: متنكر: ت ك.\r7، 8 ـ التاويل وهو: ج ف ل من وجوه: ت ج ف ل، التناول القول: ق بالتاويل هو من وجوه: ك: ق ك لب م.\r9 ـ احدها: ا: ا، زعم: ذهب: م فقط، من قوله: لقوله ق، تعالى: ت.\r10 ـ سورة الاعراف: 19، المراد: المراد منه: ج.\r11 ـ كذلك: ت ج ل، فكذلك: ف ي، فقد: ق ك لب، قد، م، عليه السلام: ق ك لب، صلى الله عليه وسلم: م، ت ا ج ل ي."], [531, "هذا وضوء لا يقبل الله الصلاة إلا به.\rوزعم آخرون ان النهى وان كان ظاهرا فى التحريم لكنه ليس نصا فيه، فصرفه عن الظاهر لدليل عنده.\rمسئلة:\rالكرامات جائزة عندنا خلافا للمعتزلة والأستاذ أبى إسحاق منا لنا التمسك بقصة مريم وآصف ثم تتميز الكرامة عن المعجزة بتحدى النبوة.\rمسئلة:\rالأنبياء أفضل من الملائكة عندنا خلافا للمعتزلة والقاضى منا والفلاسفة.\rلنا قوله تعالى: (إِنَّ اللهَ اصْطَفى آدَمَ وَنُوحاً) وسواء أجريناه على العموم أو حملناه على عالمى ذلك الزمان، كما فى قوله تعالى:\r__________________\r1 ـ هذا: فهذا: ج.\r2 ـ لكنه: ت ف ق ك لب ي ل، لكن: ج، ولكنه: م، ليس: ف.\r3 ـ نصا فيه: فيه نصا: ك، لدليل: الدليل: ت، عنده: عنده والله تعالى اعلم: ل.\r5 ـ جائزة عندنا: عندنا جائزة: في م فقط، ابي اسحاق: ابو اسحاق: ك، منا: ا.\r6 ـ مريم: مريم عليها السلام: ك ل، آصف: اصف بن برخيا: ل، الكرامة: ت ج ل م، الكرامات: ا ف ق ك لب ي، المعجزة: ت ج ق ل لب م، المعجز: ف ك ي.\r9 ـ الانبياء: الانبياء عليهم السلام: ق.\r10 ـ و: ت.\r11 ـ سورة آل عمران: 23 وآل ابراهيم الاية: ك: ج ك.\r12 ـ حملناه: ك، عالمي: عالم: ل، تعالى: ك ل لب م،: ت ج ف ي ق."], [532, "(وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعالَمِينَ). فالمقصود حاصل. ولأن البشر يعرفون الله تعالى ويعبدونه مع كثرة الصوارف عنه من الشهوة والغضب، والموانع الداخلة والخارجة. وليس للملائكة شيء من ذلك فتكون طاعة البشر أشق، فيكون أفضل لقوله عليه السلام أفضل العبادات أحمزها أى أشقها.\rأما الفلاسفة فقد احتجوا على أن الملك أفضل بوجوه:\rأحدها: أن الروحانيات بسائط والجسمانيات مركبات. والبسيط أشرف من المركب.\rوثانيها: أن الروحانيات مطهرة عن الشهوة والغضب التى هى منشأ للأخلاق الذميمة، والجسمانيات غير خالية عنها.\rوثالثها: أن الروحانيات صور مجردة كمالاتها حاصلة بالفعل\r__________________\r1 ـ اني: ف ق ي، سورة البقرة: 122، لان: ي.\r2 ـ يعرفون: تكرر في: ف، تعالى باياته: ف ي: ت ج ف ق ل لب ي: م ك، يعبدونه: ت ج، يحبونه: ك ل م. عنه: ت ج ك، لهم: ق، م، الشهوة الشهوات: ا ف: ا ت ج ف ق ك ل لب ي، السهو: م.\r3 ـ الغضب: لعصبة: ي، الموانع: الرابع: ل، شيء: م فقط.\r4 ـ مفضل: افضل العبادات: ا، عليه السلام: ا ت ج ف ق ك ل لب ي، صلى الله عليه وسلم: م.\r5 ـ العبادات: ت ق ل لب م ي، الاعمال: ا ج، العبادة ك، اشقها: اشقها على البدن: لب.\r6 ـ الملك: الملائكة: ا ق، بوجوه: لوجوه: لب.\r7 ـ احدها: ا: ا. بسائط: ج ك م، بسيطة: ل، ت.\r7، 8 ـ البسيط .. المركب: البسائط .. المركبات: م فقط.\r9 ـ ثانيها: ب: ا، ان: ك م، التي هي: الذي هو: م، الذين هما: ق.\r9، 10 ـ منشا للاخلاق: ت، المنشا للاخلاق: ا، المنشيات للاخلاق: ق، منشا الاخلاق: ج ف ل لب م ي، الاخلاق: ك.\r11 ـ ثالثها: ج: ا، ان: ت ج ل ف ي: ق ك لب م."], [533, "والنفوس البشرية مادية إما بجوهرها عند من يجعل النفس مزاجا أو فى أفعالها عند من يجعلها مجردة. وعلى التقديرين فهى بالقوة، وما بالفعل التام أشرف مما بالقوة.\rورابعها: الروحانيات صور مجردة ليس فيها طبيعة الانفعال فتكون وجودات محضة وخيرات محضة. والجسمانيات مركبة من مادة وصورة والمادة منبع العدم والشر والخير أفضل من الشر.\rوخامسها الروحانيات نورانية علوية لطيفة. والجسمانيات ظلمانية كثيفة.\rوسادسها: الروحانيات فضلت الجسمانيات بقوى العلم والعمل. أما العلم فلاحاطتها بالأمور الغائبة عنا، واطلاعهم على مستقبل الأحوال الجارية علينا، ولأن علومهم علوم كلية، وعلوم الجسمانيات جزئية وعلومهم فعلية. وعلوم الجسمانيات انفعالية، وعلومهم\r__________________\rصور: ت ج ف ق ل لب ي، صورة: ك م، حاصلة: ت ج، حاضرة: ف ق ك ل لب ي، ظاهرة: م.\r1 ـ بجوهرها: بجواهرها: م.\r2 ـ يجعلها: يفعلها: ا، مجردة: منجردة: ت.\r3 ـ التام اشرف: اشرف: اشرف دائم: ك، التالم شرف: ت.\r4 ـ رابعها: د: ا، رابعها ان: ق، صور: صورة: ك م.\r6 ـ صورة: سور: ت ي، العدم والشر: الشر والعدم: م، الشر والفتن والعدم: ق.\r7 ـ خامسها: ه: ا، خامسها ان: ق، الجسمانيات: الجسمانية: ك.\r7، 8 ـ خامسها ... كثيفة: ف، ظلمانية كثيفة: ا ت ج ك ل لب ي، كثيفة وسسفلية: م، مركبة من مادة وصورة والمادة ظلمانية كثيفة: ق.\r9 ـ سادسها: و: ا، سادسها ان: ق، بقوى: ا ت ج ق ك لب، في قوى: ي، في قوى: ف، لقوى، م، معى: ل.\r10 ـ اطلاعهم: اطلاعها: ق، مستقبل: مستقل: ا.\r11 ـ علوم: ت ج ل ي: ف ك لب م.\r12 ـ انفعالية: الفعالية: ي."], [534, "فطرية آمنة من الغلط. وعلوم الجسمانيات كسبية متعرضة للغلط.\rوأما العمل فلكونهم عاكفين على العبادة (يُسَبِّحُونَ اللَّيْلَ وَالنَّهارَ لا يَفْتُرُونَ). والجسمانيات ليسوا كذلك.\rوسابعها: ان الروحانيات لها قوة قوية على تصريف الأجسام والزلازل القوية من غير أن يعرض لها فتور، وكلال بخلاف الجسمانيات.\rوثامنها: ان الروحانيات اختياراتها متوجهة إلى الخير ونظام العالم والجسمانيات اختياراتها غير جازمة، بل مترددة بين جهتى السفالة والعلو.\rوتاسعها الروحانيات مختصة بالهياكل العلوية النورانية والجسمانيات مختصة بهذه الهياكل الفاسدة ونسبة الأرواح نسبة\r__________________\r1 ـ فطرية: ا ت ج ف ك لب ي، نظرية: ل م، آمنة: ت ج ف ك ل لب، امينة: م ي، من: عن: م، متعرضة: معترضة: لب (12/ 533)، 1 ـ انفعالية ... الجسمانيات: ق.\r2 ـ فقونهم: فانهم: ف، على: عن: ت، العبادة: العبادات: لب، عتبة العبادة: ق، ويسبحون: ك م.\r3 ـ ولا يفترون: في ق م، سورة الانبياء: 20، ليسوا: ت ج، ليست: ك ل م، كذلك: لها: ك.\r4 ـ سابها: ز: ا، ان: لب م، قوية: قوسه: ي، ف.\r5 ـ والزلازل: ت ج ل ي، كالسحاب والزلازل: ف ق ك لب م، كلال: انحلال: ف ي.\r7 ـ ثامنها: ج: ا، ثامنها ان: ف ي، اختياراتها: باختياراتها: ي، الخير: ت ج ف ل، الخيرات: ق ك لب م، الخيرة: ي.\r8، 9 ـ السفالة والعلو: السفلية والعلوية: لب، السفل والعلو: ق.\r10 ـ تاسعها: ط: ا.\r11 ـ الجسمانيات: الجسمانية: ي، الهياكل: كل: ك:"], [535, "الهياكل. فلما كانت الهياكل السماوية أشرف، كانت الأرواح السماوية أشرف.\rوعاشرها: الأرواح الفلكية متصرفة فى هذا العالم. فإنها هى المدبرات أمرا وهى المبدأ والمعاد: وهما أشرف من ذى المبدأ وذى المعاد. فالروحانيات أشرف.\rأما المسلمون فقد احتجوا على التفضيل بقوله تعالى: (ما نَهاكُما رَبُّكُما عَنْ هذِهِ الشَّجَرَةِ إِلَّا أَنْ تَكُونا مَلَكَيْنِ) وقوله: (لَنْ يَسْتَنْكِفَ الْمَسِيحُ أَنْ يَكُونَ عَبْداً لِلَّهِ وَلَا الْمَلائِكَةُ الْمُقَرَّبُونَ) وقوله (ما هذا بَشَراً إِنْ هذا إِلَّا مَلَكٌ كَرِيمٌ).\rوالجواب عن شبهة الفلاسفة مبنى على فساد أصولهم وقد نقدم ذلك وعن التمسك بالآيات مذكور فى الكتب البسيطة وبالله التوفيق.\r__________________\rف، نسبة .. نسبة، ا ت ج ف ك ل لب ي، نسبة .. كنسبة: ق، لشبه .. لشبه: م.\r3 ـ عاشرها: ي: ا، فاتها: وانها: ق.\r4 ـ وهي: تكرر في: ي، وهما: هما: ل.\r4، 5 ـ ذي المعاد: المعاد: ف ي.\r5 ـ فالروحانيات اشرف: ف ي.\r7 ـ هذه: ف ك ق ل م ي، تلكما: ت لب، تلك: ج سورة الاعراف: 20، لن: ولن: في م، تعالى لن: لب.\r8 ـ سورة النساء: 172.\r9 ـ سورة يوسف: 31.\r10 ـ والجواب: ت ج ف ق ك ل لب م ي، وهذا انما يصح لو كان الملك افضل والجواب: ق، الجواب: ا، فساد: ا ت ج ف ق ك، الفساد: ل لب، ابطال: م.\r11 ـ وعن التمسك: ا ت ج ف ق ك لب، عن التمسك: م، وعن الشبهة: ل ي مذكور: ا ت ج ف ك لب، مذكور: ق، المذكورة: م: ل، البسيطة: البسيط: في ت.\r11، 12 ـ وبالله التوفيق: ا ك لب: ت ج ف ق ل م ي."], [537, "القسم الثانى\r"]], "pg": [489, 537]}, "687.15": {"x": [[537, "فى المعاد\rمسئلة:\rاختلف أهل العالم فيه، فأطبق المسلمون على المعاد البدنى، والفلاسفة على المعاد النفسانى وجمع من المسلمين والنصارى عليهما وجمع من الدهرية على نفيهما، وتوقف جالينوس فى الكل.\rأما القائلون بالمعاد البدنى فمنهم من زعم أن الله تعالى يعدم البدن ثم يعيده. ومنهم من زعم أنه يفرق الأجزاء ثم يجمعها. والكلام فيه يتفرع على مسائل:\rمسئلة:\rالّذي يشير إليه كل أحد بقوله: أنا اما أن يكون جسما أو جسمانيا، أو لا جسما ولا جسمانيا، أو متركبا عن هذه الأقسام تركيبا ثنائيا أو ثلاثيا.\r__________________\r4 ـ اهل: ا، العالم: العلم: ك ي، فيه: ق، المسلمون: المليون: ا ق، المعاد: معا: في ت.\r5 ـ على: الى: ف، عليهما: عليها: ي.\r6 ـ على نفيهما: ك، جالينوس: ف، الكل: ذلك: ك.\r7 ـ فمنهم، منهم: م فقط.\r8 ـ الاجزاء: الاجسام: ي، يجمعها: يجمعهما: ي.\r9 ـ مسائل: المسائل: ف.\r11 ـ احد: ت ج ل، واحد: ف ي، انسان: ق ك لب م، انا: ك، جسما أو: ف.\r12 ـ متركبا: ا ت ج ف ل ي، مركبا: ق ك لب م، عن: من: ك.\r13 ـ تركيبا: ا ت ج ف ق ك ل لب، تركبا: ي م."], [538, "أما المتكلمون فزعموا أنه جسم. ثم الجمهور منهم يقول إنه هذه البنية المحسوسة. وهو ضعيف.\rأما قوله هذه البنية فلأنها دائما فى التغير، ومنتقلة من الصغر الى الكبر، ومن الذبول إلى السمن، مع أن كل واحد يعلم أن هويته ثابتة فى الأحوال كلها.\rأما قوله: المحسوسة فضعيف أيضا لأن المحسوس هو اللون والشكل القائمان بسطحه الظاهر. والإنسان ليس عبارة عن مجرد هذا الشكل واللون، وإلا لكانت الأجزاء الداخلة بأسرها خارجة عن هويته فثبت أن ما هو حقيقة الإنسان غير محسوسة بالاتفاق.\rومنهم من زعم أنها أجزاء أصلية باقية من أول العمر إلى منتهاه. ثم اختلفوا فيه فزعم ابن الراوندي أنه جزء لا يتجزأ فى القلب. وزعم النظام أنه أجسام لطيفة سارية فى الأعضاء والأطباء زعموا أنه الروح\r__________________\r1 ـ فزعموا: ا ت ج ف ق ك ل لب، فقد زعموا: م، يقول: ت ج ل، يقولون: ك م، انه: ت ج ق ك ل م، انه هو: ا، انها: لب، ان: ف ي.\r2 ـ البنية: الهيئة: ي، هو: ت ج ف ق ك ل لب ي، هذا: م.\r3 ـ دائما: دائمة: ا ك، ذائبة: لب، في التغيير: في التغيير: ت: لب.\r3، 4 ـ منتقلة منقلبة: ق: ت ج ف ق ك ل لب م، منقلبة من الصغير الى الكبير: ا، من الصغر الى الكبر: ي.\r5 ـ ثابتة: ا ت ف ل ي، باقية: ج ف ك لب م.\r6 ـ اما: ت ج ف ل ي، واما: ق ك لب م، المحسوسة: المحسوس: ف ي، فضعيف ايضا: ضعيف: ك.\r9 ـ فثبت ... بالاتفاق: ا ت ج ف ق ك ل لب ي: م.\r10 ـ انها: ك، منتهاه: آخر منتهاه: ك.\r11 ـ فيه: ا ق ك لب: ت ج ل م ي، الرواندي: روندي، الروندي: لب.\r12 ـ جسام: ا ت ج ف ق ك ل لب ي، اجزاء: م، انه: ان ك."], [539, "اللطيفة الموجود فى الجانب الأيسر من القلب. ومنهم من جعله الروح الدماغى ومنهم من جعله الاخلاط الأربعة والدم خاصة.\rأما الذين قالوا إنه جسمانى. ومنهم من جعله عبارة عن المزاج واعتدال الاخلاط.\rومنهم من جعله عبارة عن شكل البدن، وتخطيطه، وتأليفات أجزائه. ومنهم من جعله عبارة عن الحياة.\rأما الذين قالوا أنه غير جسم ولا جسمانى فهم الفلاسفة ومن المعتزلة معمر ومنا الامام الغزالى رحمه الله والحجة القوية لمثبتيها من وجهين:\rالأول: أن العلم بالله تعالى غير منقسم إذ لو انقسم لكان اما أن يكون كل واحد من أجزائه علما، أو لا يكون فإن كان علما فاما أن يكون علما بذلك المعلوم فيكون الجزء مساويا للكل، هذا خلف وان لم يكن علما بذلك المعلوم فعند اجتماع تلك الأجزاء، إن لم\r__________________\r1 ـ اللطيفة الموجود: ا ت ج ف ق ك لب ل ي، اللطيفة: م، جعله: جعل: م ف ك ل ي.\r2 ـ الدماغي: الموجود في الدماغ: لب، جعله: ت ج ف ك، جعل: ل م، و (2): ت ك ل، او: ج ق م.\r3 ـ اما: ت ج ق ل لب ي، واما: ق ك م، ومما، ت ج ك ل م.\r4 ـ و: او: ف ي، اعتدال: الاعتدال: ت.\r7 ـ اما: ت ج ل م، واما: ف ق ك لب ي، ولا جسماني: م، فهم: وهم م.\r8 ـ المعتزلة: الفلاسفة: ك تكرر، الامام: ق، رحمه الله: ا ت ف لب ي، رضي الله عنه: ل، ج ق ك م، لمثبتيها: ت ج ف ق ل م، لمثبتها: ا ك ي، التي تمسكوا بها: لب.\r10 ـ الاول: ا: ا، تعالى: ق لب م، ا ت ج ف ك ل، انقسم: تقسم: ي.\r12 ـ بذلك: بكل ذلك: م فقط، الجزء: بالجزء: ك."], [540, "يحصل هيئة زائدة لم يحصل العلم بالله تعالى، هذا خلف. وان حصلت هيئة زائدة، فإن انقسمت عاد التقسيم، وإلا حصل المقصود.\rوإذا ثبت ذلك وجب أن لا يكون محله منقسما، لأن الحال فى المنقسم، منقسم وكل متحيز منقسم بناء على نفى الجوهر الفرد، فمحل العلم بالله تعالى غير متحيز ولا حال فى المتحيز.\rوجوابه إنا بينا اثبات الجوهر الفرد. ثم قوله الحال فى المنقسم منقسم منقوض بالنقطة والواحدة والإضافة والوجود.\rالثانى: محل العلم والقدرة وسائر الأعراض النفسانية ان كان هو البدن، فاما أن يكون محلها جزأ واحدا من البدن أو أكثر من واحد. والأول محال. أما أولا فلاستحالة الجزء الّذي لا يتجزأ. وأما ثانيا فلأنه يلزم أن يكون ما عدا ذلك الجزء ميتا جمادا، وهو مكابرة. وأما الثانى فاما أن يكون الأجزاء موصوفة بعلم واحد\r__________________\r1 ـ هذا خلف: ا.\r2 ـ التقسيم: التسويق: ف، والاحصل لحصل: م المقصود: ت ج ق ك ل لب ي، ف.\r3 ـ واذا: فاذا: ك.\r4 ـ كل: ذلك: ق.\r5 ـ تعالى: ق لب م: ا ت ج ف ك ل ي، حال: حالا: ا، في المتحيز: ت ج ف ل ي، فيه: ق ك لب م.\r6 ـ وجوابه: ت ي ف م، جوابه: ا ق ك لب ج ل، قوله: ا ت، ف ق ك ل لب ي، ان قوله: م.\r7 ـ منقوض: ت ج ف ق ك ل لب ي، باطل: م.\r8 ـ الثاني: ت ق ي، والثاني: لب، الوجه الثاني: ل، الثاني في الحجة الثانية: ك، الثاني ان: ج ف م.\r9 ـ فاما: اما: ف ي، يكون: ك، جزءا واحدا: جزء واحد: ك.\r9، 10 ـ من احد و: من الواحد: ك.\r11 ـ جمادا: ك.\r12 ـ مكابرة: مصاهبة: ي، مناهبة: ف، الاجزاء جميع الاجزاء: م موصوفة: الاجزاء الموصوفة: ا."], [541, "وقدرة واحدة، فيكون العرض الواحد حالا فى المحال الكثيرة، وهو محال، أو يكون القائم بكل واحد منها علما على حدة، وقدرة على حدة، فلا يكون الإنسان الواحد عالما واحدا، بل علماء لكنه باطل بالضرورة فإن كل واحد يدرك نفسه شيئا واحدا لا أشياء.\rجوابه أنه منقوض على مذهب أبى على بالحواس الخمسة الظاهرة والباطنة والشهوة والغضب. وبقية أدلتهم مع الجواب مذكورة فى كتبنا الحكمية.\rحجة النفاة ان المدرك للجزئيات هو البدن فالمدرك للكليات هو البدن. بيان الأول أنا نعلم بالضرورة انا نحس الحرارة بإصبعنا إذا لمسنا النار وإنكاره مكابرة.\rوبيان الثانى من وجهين:\rالأول: إنا إذا أحسسنا بحرارة جزئية أمكننا حمل الحرارة الكلية عليها، والحامل للكلى على الجزئى مدرك لهما ضرورة أن التصديق مسبوق بالتصور. وإذا كان المدرك للجزئيات هو البدن، كان المدرك\r__________________\r2 ـ منها: منهما: ي، علما: علم: لب ي.\r3 ـ عالما: علما: ي، واحدا: لب.\r4 ـ لا اشياء: الا اشياء: ف.\r5 ـ انه: ف ي، الخمسة: ت ج ك، الخمس: ق ل م.\r6 ـ الشهوة: ا ث ج ف ق ك ل لب ي، السهو: م، بقية: نصب مع: ك، مذكورة: ت ج ف ق ك ل ي، مذكور: لب م.\r8 ـ النفاة: الثقات: م فقط. المدرك: ت ج ف ق ك ل لب ي، المدركة: م، فالمدرك: والمدرك: ك، هو البدن ... للكليات: هو المدرك للكليات: ق فقط.\r11 ـ و: ت ف ق ك ل لب ي، م.\r12 ـ الاول: ا: ا، احسنا: احسينا: ك، بحرارة جزئية: ا ت ج ف ق ك ل لب ي، الحرارة الجزئية: م.\r13 ـ عليها: ك، للكل: الكل: ا، مدرك: يكون مدركا:: ق.\r14 ـ كان (2): لكان: لب، المدرك (2): ك."], [542, "للكليات هو البدن. إلا أن يقال البدن مدرك للجزئيات فقط، والنفس مدركة لهما لكنه باطل لأنه حينئذ يكون الإنسان مدركا للجزئيات مرتين.\rالثانى ان الماهية التى عرضت لها أنها كلية جزء من الجزئى لأن الإنسان جزء من هذا الإنسان. ومن أدرك المركب، فقد أدرك المفرد. فمن أدرك هذا الإنسان فقد أدرك الإنسان، لا محالة والإنسان كلى ولا يندفع هذا، إلا بأن يقال المدرك من هذا الإنسان ليس المركب، بل أحد قيديه، وهو كونه هذا، لكنه باطل.\rأما أولا فلانا دللنا على أن التعين لا يجوز أن يكون وصفا وجوديا زائدا، وإلا لزم التسلسل. وإذا لم يكن التعين وجوديا، استحال أن يكون متعلق الإبصار والإدراك.\rوأما ثانيا فلأن متعلق الحس إذا كان مجرد التعين، ومجرد التعين\r__________________\r2 ـ مدركة: ج ف ق ي / مدرك: ت ل: ا ك لب م، لهما ت ج ف ق ل لب ي، لهما معا: م، لهما فقط: ا ك، حينئذ: ت ج ق ك لب ل ي، وبعد يكون: م.\r2، 3 ـ الانسان ... مرتين: الانسان مدرك للكليات والجزئيات مرتين: ك.\r4 ـ الثاني: ب: ا، الماهية: الماهيات: ا.\r5 ـ ادرك (1، 2): ادراك: ا.\r6 ـ فمن: ومن: ف لب م، والانسان: فالانسان: ق.\r7 ـ ولا: لا: ك، المدرك: للمدرك: ك، هذا: ك.\r8 ـ فنديه: ت ج ق ك ل لب م، قيد به: ف، قوله من قيد به: ي.\r9 ـ اولا: الاول: ت ل، فلانا دللنا: فلانا د للعقل: ل، التعين: التعيين: ق ل.\r10 ـ وجوديا زئدا: ثبوتيا: ا، واذا: وانا اذا: ي، التعيين: التعيين: ف ق ل، وصفا: ك.\r11 ـ والادراك: ت ج، ك ل م.\r12 ـ متعلق: ي، اذا: ا ت ج ق ك ل لب ي، ان: ف م."], [543, "أمر واحد فى جميع المتعينات، فما هو متعلق الحس من المتعينات أمر واحد فى الكل، فوجب أن لا يحس بالاختلاف، البتة من جهة الابصار. وكذب التالى يدل على كذب المقدم ولنذكر الآن بعض أحوال النفس.\rمسئلة:\rمذهب ارسطاطاليس وأتباعه ان النفوس البشرية متحدة بالنوع.\rواحتجوا بانها لو اختلفت بالماهية بعد اشتراكها فى كونها نفوسا بشرية، كانت مركبة، لأن ما به الاشتراك غير ما به الامتياز. وكل مركب جسم، فالنفس جسم.\rالاعتراض لم لا يجوز أن يقال كونها نفوسا بشرية معناه أنها مدبرة للأبدان البشرية، وكونها مدبرة من عوارضها فلم لا يجوز أن يقال أنها مختلفة بتمام الماهية ومشتركة فى العوارض. وذلك غير ممتنع، كما فى الضدين فانهما مع اختلافهما مشتركان فى الاختلاف والتضاد. سلمناه لكن لم قلت ان كل مركب جسم، بل مذهبكم ان\r__________________\r1 ـ المتعينات (1، 2): ج ف لب ي ل لب في الاول، المعينات: ت ق م ل لب في الثاني.\r1، 2 ـ في جميع .. واحد: ك.\r2 ـ لا يحس: الحس: ا، بالاختلاف: الاختلاف: ك، باختلاف البنية: ق.\r3 ـ التالي: الثاني: ك ي.\r7 ـ اشتراكها: اشتراكهما: ف، كونها: كونه: ق.\r10 ـ الاعتراض: هذا خلف الاعتراض: ف ق ك.\r11 ـ للابدان: الابدان: ك ل.\r12 ـ و (1) م فقط، ومشتركة في العوارض: لكنهما يشتركان في الاوصاف: لب.\r13 ـ مشتركان: ا ت، يشتركان: نسخ اخرى.\r14 ـ سلمناه: ا ت ج ق ك ل لب ي، سلمنا: ف م، لكن: ت ل، قلت: قلتم: ف لب بل: بلى: ت ج."], [544, "الجسم مركب من الهيولى والصورة. لكن الموجبة الكلية لا تنعكس كنفسها. وكيف وعندهم الجوهر جنس النفوس والعقول. وكل ما كان تحت جنس فماهيته مركبة من الجنس والفصل.\rومنهم من زعم أنها مختلفة بالماهية، واحتجوا بأنها مختلفة بالعفة، والفجور، والذكاء والبلادة. وليس ذلك من توابع المزاج لأن الإنسان قد يكون بارد المزاج، وفى غاية الذكاء، وقد يكون بالعكس. وقد يتبدل المزاج والصفة النفسانية باقية، ولا من الأسباب الخارجية. لأنها قد تكون بحيث يقتضي خلقا والحاصل ضده. فعلمنا أنها من لوازم النفس. واختلاف اللوازم يدل على اختلاف الملزومات، وهذه الحجة اقناعية.\rمسئلة:\rزعم ارسطاطاليس وأتباعه انها حادثة خلافا لافلاطون، ومن قبله. حجة القائلين بالحدوث أنها لو كانت أزلية، لكانت اما أن تكون\r__________________\r(14/ 542)، 1 ـ كل مركب ... الهيولي: ان كل جسم مركب من الهيولي: ك.\r1 ـ لكن: ت ج ف ق ك ل م ي، ولكن، لب، والمادة ولكن.\r2 ـ كنفسها: لنفسها: ا ف ل، كميتها: ك، وكيف: فكيف: ج وعندهم: وعندكم: ل، النفوس: ت ج ق، للنفوس: ل م ك.\r3 ـ كان تحت جنس فماهيته: ت ج ف ي، كان كذلك فما هيته ل، دخل تحت الجنس جنس: ك لب، كانت ماهيته: ق ك لب م.\r4 ـ من: ت، بالماهية: ا ت ج ف ق ك ل لب ي، بالماهيات م، احتجوا: احتجوا عليه: ج، باللغة: في العفة: ا ك لب.\r7 ـ ولا: و: ق فقط.\r8 ـ الخارجية: الخارجة: ل ي ضدة: صورة: ك.\r9 ـ انها: ا ت ج ف ق ك ل لب ي، انه: م، لوازم: ذوات: ف.\r10 ـ الحجة: حجة: ف ي.\r13 ـ انها: بانها: م فقط."], [545, "واحدة، أو كثيرة. فان كانت واحدة، فعند التعلق بالأبدان ان بقيت واحدة، فكل ما علمه واحد علمه كل أحد، وبالعكس، هذا خلف.\rأولا تبقى واحدة، فقد انقسمت وذلك محال لأن الهويتين اللتين حصلتا بعد الانقسام، ان كانتا حاصلتين قبل ذلك فقد كانت الكثرة حاصلة قبل حصولها هذا خلف وان قلنا انهما ما كانتا حاصلتين، وقد حدثتا الآن فهاتان النفسان قد حدثتا الآن والنفس التى كانت موجودة قبل قد فنيت. وأما ان كانت كثيرة فلا بد من الامتياز بأمور وهو أما الذاتيات أو لوازمها وهما محالان، لأن النفوس البشرية متحدة بالنوع، وإن لم تتحد كلها بالنوع فلا أقل من أن يحصل من كل نوع شخصان.\rواما بالعوارض فهو محال لأن الاختلاف بالعوارض إنما يتحقق\r__________________\r2 ـ واحدة: كل واحدة: ك، واحد: حد: ا، احد: ا ت ب ك ل، واحد: ج ق لب م ي.\r3 ـ انقسمت: ا ت ج ف ق ك ل لب ي، انقسم: م.\r3 ـ بعد: ك، الانقسام الاقسام: ك، الكثرة: ج ف ق ل لب م ي، الكثيرة: ا ك.\r5 ـ وان: فان: ي، ما: ا ج ف ق ك ل لب ي، م.\r(4، 5) حبل ذلك .. فانما حاصلتين: ت.\r(5، 6) وحدة فقد: ق ك حدثنا: ج ف ل ك م، فقد حدثنا: ل ف لب ي.\r6 ـ حدثنا (2): ج ق ك ل م، حدثنا: ب لب ف ي الان (2) موجوده موجوده: ك.\r7 ـ قبل: ا، قد: ك، فنيت: ا ت ج ف ق ك ل لب ي عدمت: م، يامور: ت ف ي، يامر: ج لب م، من امر: ل: لغو وو هو: ج لب ل م ي، هو: ت، وهي: ف ك.\r9 ـ وان: ولو: ك.\r11 ـ دام الارض: ا ج ف ك ي، العوارض: ت ق لب ل م، فان ج ل م ي، وهو: ت ف ق ك لب، لان الاختلاف: فكر في: ف."], [546, "عند تغاير المواد وقبل البدن لا مادة، فلا يتحقق الاختلاف بالعوارض.\rالاعتراض لا نسلم أنه يوجد نفسان من نوع واحد. وبيانه ما مر. سلمناه لكن لم قلت ان الامتياز لا بد وأن يكون بزائد. وبيانه ما مر. سلمناه لكن لم لا يجوز أن يكون الاختلاف بالعوارض. قوله: قبل هذا البدن لا مادة. قلنا لا نسلم فلم لا يجوز أن تكون قبل تعلقها بهذا البدن كانت متعلقة ببدن آخر فانتقلت منه إلى هذه على سبيل التناسخ.\rمسئلة:\rالقائلون بحدوث النفس اتفقوا على فساد التناسخ لوجوه ثلاثة:\rأحدها: انا قد دللنا على حدوث النفس، فيكون حدوثها عن\r__________________\r1 ـ المواد: ا ت ج ف ق ك ل لب ي، امادة: م، لا مادة: فلا مادة: ف ي، فلا: ولا: ق.\r2 ـ انه: ان: ت ج، يوجد: وجد: لب، نفسان: ت ج ف ق ك ل لب م ي، نفسا: ا.\r4 ـ سلمناه و: ق: ا ت ج ق ك لب ل، سلمنا: ف م ي، قلت: ا ت ج ف ق ك ل ي، قلتم: لب م، برائد: ت ج ل، نزايد ف ق لب ي، زائدا: ك م.\r5 ـ سلمناه: ا ج ق ل لب ي، سلمناه: ك م: ت.\r5، 6 ـ يكون الانتلاف ... يجوز لن: لب، قوله .. لا ماده: ت ج م قلنا قلت: ف ت ج ف م، قوله لا مادة قبل هذا البدن قلنا: ق، ما هو سلمناه لكن لم لا يجوز قوله هذا البدن يكون العوارض قلنا: ي، هذا البدن لا بدن قلنا: ك.\r6 ـ قبل: ك، تعلقها: تعلقهما: ي.\r5، 7 ـ قبل هذا ... كانت: ل.\r7 ـ كانت لن كانت: ت: م فقط. فانتقلت: ت ج ف ك ل لب ي، انتقلت: ق، فانقلبت: م، هذه: ت ج ك، هذا: م، هذا البدن: ل.\r10 ـ على: في: م، ثلاثة: م.\r11 ـ احدها: الاول: ف، ا: ا."], [547, "مبدأها القديم موقوفا على حدوث شرط. وإلا لم يكن حدوثها الآن أولى من حدوثها قبل ذلك. وذلك الشرط ليس إلا حدوث البدن. فإذن حدوث الاستعداد البدنى علة لفيضان النفس على الجسد من المبدأ القديم. فالبدن الحادث الّذي يتعلق به نفس على سبيل التناسخ ولا بد وأن يستعد لقبول نفس أخرى ابتداء فيجتمع النفسان على بدن واحد وهو محال. لأن كل واحد يجد ذاته شيئا واحدا لا شيئين.\rالاعتراض هذه الحجة مبنية على حدوث النفس. ودليلكم فى حدوث النفس مبنى على فساد التناسخ على ما لاح الحال فيه، فيكون دورا. سلمنا أنه لا دور، لكن لم لا يجوز أن يقال النفوس مختلفة بالماهية. فالبدن المستعد لواحدة منها لا يكون مستعدا لغيره.\rسلمنا التساوى لكن لا بد من التباين فى الهوية، وما به التباين غير مشترك فيه، فلم يلزم من كون البدن المخصوص مستعدا للنفس\r__________________\r2 ـ علة: عليه: ت، لفيضان: نقصان: ل.\r3، 4 ـ على الجسد: ت ج من عن: ف ق ك لب المبدا: ا ت ج ف ق ك لب، عن مبدئها: م، عن مبدا ل.\r4 ـ الذي: ت ف ل ي.\r5 ـ ولابد: ت ف ي، لابد: ج ق ك لب م: ل، فيجتمع فيجمع: ك.\r6 ـ واحد (2): ت ج ف ل م ي، احد: ق ك لب.\r7 ـ لا: الا: ي، شيئين: اثنين: لب.\r8 ـ هذه: ان هذه: ك، على هذه:، الحجة: الحجة انها: ق، مبنية: مبني: ف ك.\r9 ـ الحال: في الحال: ك.\r10 ـ النفوس: ت ج ك لب ل م، النفوس البشرية: ف ق، النفس البشرية: ي.\r11 ـ فالبدن: والبدن: م، لواحدة: ت ف ل ي، لواحد: ف ق ك لب م، لغيرة: لغيرها: ف ي.\r12 ـ في الهوية: بالهوية: ق.\r13 ـ غير: ما به غير: لب مستعدا: مستعد: ت، للنفس:"], [548, "الموصوفة بهذه الخصوصية كونه مستعدا للأخرى. سلمنا حصول المساواة فلم لا يجوز تعلق النفسين بالبدن.\rقوله لأن كل واحد يجد نفسه شيئا واحدا. قلنا الّذي يدرك منى نفسى هو نفسى وكل نفس تجد نفسها نفسا واحدا لا غير فلم يلزم محذور.\rوثانيها لو كانت هويتنا موجودة قبل بدننا فى بدن آخر لتذكرنا تلك الحالة.\rوالاعتراض لم لا يجوز أن يكون تذكر أحوال كل بدن موقوفا على التعلق بذلك البدن.\rوثالثها أنه لو صح التناسخ، لكان اما أن يكون واجبا، فيلزم أن يكون عدد الهالكين مثل عدد المحدثين، أو جائزا، وهو محال. لأنه يلزم بقاء النفس معطلة فيما بين هذين التعلقين. وضعف هذه الحجة لا يخفى.\r__________________\rللنفوس: لب.\r1 ـ الموصوفة: الموصوف: م، الخصوصية: الحاصبة: ف ي للفوري: النفس الاخرى: م، لنفس اخرى: لب.\r2 ـ النفسين: ا ت ج ف ق ل لب ك، النفس: م ي، بالبدن: بالبدن الواحد: ك، ي.\r3 ـ واحد: ق ك لب م ي، احد: ت ج ف ل، سيوتا: سك، الموضوع: ج ف ق ل ي، من: ت لب م.\r4 ـ هو: فهو: ق، نفسي: نفس: ت، يجد: ت ج ل يحد لب، نجد: ف ق ك ي، يحد: م، واحدا: ت ج ل ف ي، واحد ك، واحدة: ق لب م، لاغير: ف ي.\r6 ـ ثانيها: ب: ا، هويتنها: هويتها: لب، هو هنا: ا. في بدن: ببدن: ف، لتذكرنا: ت، لذكرنا: ي، ليذكرنا: ل.\r8 ـ بل عليك ق، تذكر: تدرك: ا.\r10 ـ ثالثها: ج: ا.\r12 ـ هذين التعلقين: التعليقين: م."], [549, "مسئلة:\rاتفقت الفلاسفة على امتناع عدم الأرواح.\rواحتجوا بأن العدم لو صح عليها لكان امكان العدم متقدما لا محالة على العدم، وذلك الامكان يستدعى محلا، ويجب أن يكون المحل باقيا عند ذلك العدم. لأن القابل واجب الحصول عند المقبول والشيء لا يبقى عند عدمه. فإذن كل ما يصح عليه العدم فله مادة. فلو صح العدم على النفس لكانت مركبة من المادة والصورة. لكن ذلك باطل لما بينا أنها ليست بجسم، ولأنا على هذا التقدير إذا نظرنا إلى الجزء المادى لم يكن قابلا للعدم والا لافتقر إلى مادة أخرى. ولا محالة ينتهى إلى ما لا مادة له. فيكون ذلك الشيء غير قابل للفساد.\rالاعتراض لا نسلم ان الامكان أمر ثبوتى وعلى هذا التقدير، لا يستدعى محلا. وأيضا فالنفس حادثة. فتكون مسبوقة بالإمكان فالامكان السابق لما لم يوجب كونها مادية. فكذلك امكان فساده.\rسلمنا أنها لو قبلت العدم لكانت مادية. فلم لا يجوز؟.\r__________________\r3 ـ لكان: ق، متفدما: قدما: ك م.\r2 ـ متقدما لا محالة: لا محالة متقدما: ق.\r4 ـ التقدم: المعدوم: لب.\r5 ـ المحل: ك.\r6 ـ فاذن: فماذا: ي، كل ما: كلما: ف.\r7 ـ النفسي: نفسي: ك.\r10 ـ الى ما لا مادة له اذا ما: لب: ا ت ج ف ك لب ل ي، الا مادة له: ف، الى مادة له: م، غير قابل: قابلا: ك.\r12 ـ الاعتراض: الاعتراف: ا.\r13 ـ فتكون: فكونها: م فقط.\r14 ـ فالامكان: م، لما: ا، امكان: الامكان: ت فساده: ا ت ج ل لب، فسادها: ق ك م ي، فساد: ف.\r15 ـ لا يجوز: لا يجوز ان تكون مادية: ق."], [550, "قوله كل مادى جسم. قلنا لا نسلم. بل مذهبكم أن كل جسم مادى. والموجبة الكلية لا تنعكس كنفسها. وكيف وهو تحت الجوهر. فيكون مركبا.\rقوله إذا نظرنا إلى الجزء المادى وجب أن يكون باقيا، قلنا هب أنه يجب بقاء مادة النفس، لكن لا يلزم من بقاء مادة النفس بقاء النفس، لأن المركب لا يبقى ببقاء أحد أجزائه. وتحقيقه أن المقصود من اثبات بقاء النفس إثبات سعادتها وشقاوتها. وذلك غير حاصل على هذا التقدير، لأنه على تقدير بقاء مادتها دون صورتها، لا يمكن القطع ببقاء كمالاتها لاحتمال توقف امكان تلك الكمالات على حصول الجزء الصورى الفائت.\rمسئلة:\rالنفس الناطقة تدرك الجزئيات عندنا خلافا لارسطاطاليس وأبى على.\rلنا أن هاهنا شيئا يحمل الكلى على الجزئى وذلك الشيء مدرك\r__________________\r1 ـ كل: ف، بل: بلى: ت.\r2 ـ الكلية: ت، كنفسها: لنفسها: ل، كميتها: ك، وكيف: ت ق ك لب م، فكيف: ج ف ل ي، وهو: وهي: م.\r3 ـ الجوهر: ت ج ف ل ي، جنس الجوهر: ق ك لب م، فيكون مركبا: فتكون مركبة: م.\r4 ـ قلنا هب: قلنا ثبت: ا، هب: م.\r5، 6 ـ انه يجب ... بقاء النفس: ف.\r6 ـ لان ومن: ا.\r9 ـ لاحتمال توقف: لاحتمال فوقف: ا، لامكان توقف: م.\r10 ـ الغايت: ا ت ج ك ل لب، الفاني: ف ق ي، الثابت: م.\r12 ـ تدرك الجزئيات: ا ت ف ق ك ل ي، مدركة للجزئيات: لب م.\r12، 13 ـ ابي علي: ابي علي بن سينا: ل.\r13 ـ هنا شيئا: ج، ههنا شيئا: ق ك لب م، هنا شيءء: ت،"], [551, "لهما والمدرك للكلى هو النفس فالمدرك للجزئى هو النفس.\rاحتجوا بأنا إذا تخيلنا مربعا مجنحا بمربعين ميزنا بين الجناحين. فهذا الامتياز ليس فى الخارج. إذ ربما لم يكن ذلك موجودا فى الخارج فهو إذا فى الذهن. فمحل أحد الجناحين ان كان محلا للثانى، استحال حصول الامتياز. لأن امتياز أحدهما عن الآخر، ليس بالماهية، ولا بلوازمها المشتركة بين الأفراد لكن الامتياز حاصل فمحل أحدهما غير الثانى. وذلك لا يعقل إلا فى الجسم أو الجسمانى.\rوالجواب الإدراك ليس نفس الانطباع على ما حققناه. ولأن عندكم الصورة منطبعة فى الخيال. ولا إدراك هناك، بل غايته أنه مشروط. فلو لا يجوز أن يقال تلك الصورة منطبعة فى آلة جسمانية، ثم النفس تدركها وتطالعها.\r__________________\rههنا شيء: ل، هذا شيء: ي، هذا: ف، يحمل: ك.\r1 ـ للكلي: الكلي: ا، فالمدرك للجزئي: تكرر في: ق، للجزئي: الجزئي: ا، للجزئي ايضا: لب.\r2 ـ بانا اذا: بان لو: ك، ميزنا بين: ا ت ج ك ل، ممتازين: ق ي، متمايزين: ف، متميزين: لب، مبربابين: م، الجناحين: ت ج ك ل م، بالجناحين: ف ق ي: لب.\r3 ـ لم يكن: لا يكون: في م فقط.\r4، 5 ـ محلا للشاني: ا ف ق ك لب، محل للشاني: ت، محل الثاني: ج ل م.\r6 ـ بلوازمها: ج ق م، للوازمها: ت ك، الثاني: للثاني: لب.\r7 ـ غير: ا ت ف ي، غير محل: ج ق ل لب م.\r5، 7 ـ ن الآخر ... فمحل: ل.\r9 ـ و (1): لب ج م، الادراك: ان الادراك: ك.\r10 ـ الصورة: ت ف ك ج ل، الصور: ق م، ولا: اولا: ك هناك: ت ج ف ق ك ل لب ي، م.\r11 ـ بقال: يقال ان: ك، الصورة: الصور: ق.\r12 ـ تدركها وتطالعها: ت ج ف ك ل ي، تطالعها وتدركها: ق لب م."], [552, "مسئلة:\rاتفقت الفلاسفة على سعادة النفوس العالمة النقية عن الهيئات البدنية بعد الموت.\rواحتجوا عليه أن اللذة إدراك الملائم. والملائم لها إدراك المجردات. والادراك حاصل بعد الموت فاللذة حاصلة هناك فيقال لهم ان قلتم اللذة نفس الإدراك فهو باطل بحصول الإدراك الآن دون اللذة\rوان قلت الإدراك سبب اللذة فما الدليل عليه؟ والاستقراء لا يفيد إلا الظن، والقياس على سائر اللذات كذلك أيضا.\rسلمناه لكن لا يلزم من حصول السبب حصول المسبب، لا محالة لاحتمال توقف تأثير المؤثر فى ذلك الأثر على حضور شرط لم يحضر، أو على زوال مانع لم يزل.\rمسئلة:\r__________________\r2 ـ الثانية: البقية: ت. البينات: اليهية: ق.\r3 ـ هلوت: المؤمن: ي.\r4 ـ عليه: ل.\r5 ـ يلزم: ا ت ج ف ق ك ل لب ي، وهو: م.\r6 ـ الالة: ان اللذة: م، نفس: هو: ل، ت ب، فهو: ا ت ج ف ق ك ل لب ي، وهو: م، يحصول: ت ج ل، لحصول: ب ق ك لب م، فحصول: ي الان: ت ج ف ق ك ل، لب ي ان قلتم .. دون: تكرر في ق.\r7 ـ ان ولئن: ك، قلت: ا ت ج ك ل لب، قلتم: ف ق م ي.\r8 ـ سلمناه: ا ت ج ق ل لب، سلمنا: ف م ي، لا يفيد العلم سلمناه: ك، لا: لم: ا لب، حصول المسبب: ك.\r10 ـ الاثر: ا.\r11 ـ ت: و: ت ك، لم يزل: ا ت ج ف ق ك ل لب ي، لم يزل والله اعلم: م."], [553, "اتفقوا على شقاوة النفوس الجاهلة ووصف حجتهم فيه مذكور فى كتبنا الحكمية واتفقوا على أن تلك الشقاوة مخلدة. وأن الشقاوة الحاصلة بسبب الهيئات البدنية منقطعة. وقد بينا ضعف قولهم فى الفرق وبالله التوفيق.\rفهذا جملة الكلام فى المعاد النفسانى ولنتكلم الآن فى المعاد البدنى.\rمسئلة:\rاعادة المعدوم عند أصحابنا جائزة خلافا للفلاسفة والكرامية، وأبى الحسين البصرى من المعتزلة.\rلنا أن بعد العدم ان كان ممتنعا للماهية أو لشيء من لوازمها، وجب امتناع مثله. وان كان لأمر غير لازم، فعند زوال ذلك العارض، يزول الامتناع. لا يقال الحكم عليه بأنه ممتنع لذاته أو\r__________________\r1 ـ اتفقوا: ا ت ج ف ق ك ل لب ي، اتفقنا: الفلاسفة: م. الجاعلة: الجاهلوا: ك، وصف: ت ف ل م ن ت ي لت ق ت لب فيه: ا ك، مذكورة: ك.\r2، 3 ـ لعيسى ومحمد عليهما السلام: ا ت ف ق ك ل، لعيسى عليه السلام ومحمد عليه الصلاة والتحية: لب، لعيسى ومحمد عليه السلام: ي، لعيسى ومحمد: ج م.\r4 ـ وبالله التوفيق: ا ق ك: ت ل ب ف ل لب م ي.\r5 ـ اللام: ا ت ج ف ق ك لب ل ي، استعلام الاول: م.\r5، 6 ـ في المعداد .. الان: ك .. البدني: ت ج ق ك ل لب المعداد البدني والنغساني: ي، في المعاد التقصاص في اتفقو والنفساني: ف.\r8 ـ منذ اصحابنا: عندنا: ق ك، جائرة: بالسر: ا ي، العلا علة المعتزلة: ك.\r9 ـ الحسين: الحسين: ف.\r10 ـ ان: انه: ق م، ك، بعد العدم: ك.\r11 ـ لامر: الامر: ك.\r12 ـ العلوس: المعارض: ك ي، يرول: يرول ذلك: م، يزول"], [554, "لغيره لا يصح، لأن الحكم على الشيء يستدعى امتياز المحكوم عليه من غيره. والامتياز يستدعى الثبوت وهو مناف للعدم لانا نقول الحكم عليه بأنه لا يصح الحكم عليه حكم فيكون متناقضا.\rواحتج المخالف بأمور أحدها أن الشيء بعد عدمه، نفى محض لم تبق هويته أصلا، فلا يصح الحكم عليه بصحة العود. لأن المحكوم عليه متميز عن غيره. والمتميز ثابت.\rوثانيها أنه بتقدير الوقوع لا يتميز عن مثله وما يفضى إلى أن لا يتميز الشيء عن مثله كان باطلا وثالثها أنه لو أعيد، لاعيد وقته الأول معه فيلزم أن يكون مبدأه من حيث أنه معاد وهو متناقض.\rوالجواب عن الأول ان قولك أنه لا يصح الحكم عليه متناقض، كما تقدم.\rوعن الثانى: لا يتميز عن مثله فى علمنا وذلك لا مضرة فيه وأما\r__________________\rك.\r1 ـ عليه: م.\r2 ـ من: عن: ق م.\r3 ـ حكم: ت ج ف ل م ي، حكم عليه: ا ق ك لب، متناقضا: مناقضا: م.\r4 ـ احدها: ا: ا.\r5 ـ ثم: ت ج ف ل ي، ولم: ق ك لب م.\r7 ـ ثانيها: ب: ا، انه: ك، يقضى: يقضى: ت.\r8 ـ الشيء: م، ثالثها: ج: ا، لاعيد: ج ف م ي، ا ت ل لب ك.\r8 ـ فيلزم: ت ج ف ل ي، يلزم: ك لب م، ان يكون: ك، مبداه ... متناقض: ت ج ف ل لب، مبتدا مستندا: ا من حيث مع: م وهو وذلك: لب م: ا ك (متناقض: م) متناض: ا ق ك م.\r10 ـ عن الاول: عن ا: ا، قلنا عن الاول: ف، متناقض: تناقض: م.\r12 ـ الثاني: ت ج ف ل ك ي، الثاني انه: ق لب م، ب: ا"], [555, "فى نفسه فلم.\rوعن الثالث: أنه إنما يكون مبدأ، لو وجد مع الوجود المبتدأ لذلك الوقت.\rمسئلة:\rأجمع المسلمون على المعاد بمعنى جمع الأجزاء بعد تفرقها خلافا للفلاسفة.\rلنا أنه فى نفسه ممكن والصادق أخبر عنه فوجب القول به. وانما قلنا أنه فى نفسه ممكن لأن الإمكان إنما يثبت بالنظر إلى القابل. والفاعل وهما حاصلان. أما بالنظر إلى القابل، فلأن قبول الجسم الأعراض القائمة به أمر ثبت له لذاته. وما بالذات كان حاصلا فذلك القبول حاصل أبدا. واما بالنظر إلى الفاعل فلأنه تعالى عالم\r__________________\rذلك لا: ا ت ج ف ق ك ل لب ي، ذلك ممالا: م، واما: ت ج ف ل ي، اما: ق ك لب م.\r2 ـ الثالث: ج: ا مبدا: ت ج ل، مبتدا: ق ك لب م ي، مستندا: ا.\r3 ـ لذلك: ذلك: ا ق لب، الوقت: الوقت وبالله التوفيق: ك.\r5 ـ المسلمون: المليون: ا، بمعنى: لمعنى ا، تفرقها: تفرقها: ف ك لب.\r7 ـ به: بانه: ت.\r8 ـ في نفسه: ت ق ل: ك ج م، يثبت: ثبت: م.\r9 ـ و (1): او: م، حاصلان: ماخدان: ي.\r10 ـ الاعرضا: للاعرضا: ك، القائمة به: الفاعلية: م فقط. ثبت: ت ج ل لب م، ثابت له: ك، ثابت: ف ي، وما بالذات: الذات: ف ي، حاصلا: ت ج ابدا: ق ك لب م، حاصل ابدا ف ي.\r11 ـ فذلك: فكذلك: ف ي، حاصل: حاصلا: ا، تعالى: ق، عالم: عالم ابدا: لب، بدا: م."], [556, "بأعيان أجزاء كل شخص، لكونه عالما بالجزئيات، وقادر على جمعها، وخلق الحياة فيها لكونه قادرا على كل الممكنات وإذ كان كذلك كانت الاعادة ممكنة.\rوإنما قلنا إن الصادق أخبر عنه لأن الأنبياء عليهم السلام أجمعوا على القول به. وإذا ثبت المقدمتان، ظهر المطلوب. فإن قيل أما الكلام فى الامكان فمبنى على أصول تقدم القول فيها، فلا نعيدها. سلمناه لكن لا نسلم أن الصادق أخبر عنه.\rقوله الأنبياء عليهم السلام أجمعوا عليه.\rقلنا لا نسلم فإن سائر الأنبياء لم يقولوا إلا بالمعاد الروحانى فاما محمد عليه السلام فإنه قد جاء فى شرعه ما يدل على المعاد الجسمانى ولكنك قد علمت أن دلالة الألفاظ ليست قطعية، بل ظنية. وأيضا فكما جاء القول بالمعاد البدنى، فقد جاء القول بالتشبيه فى القرآن\r__________________\r1 ـ اجزاء: جزء: م فقط، وقادر: وقادرا: م فقط.\r4 ـ ان: ق، عليهم الصلاة و: م السلام: ت م ف ق ل لب ي، ا ل.\r6 ـ ما بقى: مبنى: ك، فيهافلا: ت ج ف ل، فما: ي، فيها وعليها فل: ق لب م، فيما لها وصليها فلا: ك.\r7 ـ سلمناه: ت م ق ك لب ل ي، سلمنا: ف م، ها ولكن: ف لب.\rعليهم السلام: ا ق لب.\r7، 9 ـ ان الصادق .. قلنا: ق.\r9 ـ قلنا: فلانا: م، الايمان الانبياء عليهم السلام: ق.\r9، 10 ـ انما محمد: ت ج ك م ي، فان محمدا: ف، ولما محمد به ف ك: ل.\r10 ـ فان للصلاة: ك م السلام: ا ف ق ل لب ي صلى الله عليه وآله وسلم: ت ج ف ب: ك قد: ا ت ج ق ك ل لب، ب ك.\r11 ـ فلما: لب، قد علمت: ا، الالفاظ: ك.\r12 ـ فلما: ت ج ك لب م ي، كما: ف، فلما: ق ل، القول"], [557, "والتوراة، فإذا جاز المصير إلى تأويل الجسمانى بالروحانى فى باب التشبيه. فلم لا يجوز مثله فى هذا الباب. سلمنا أن دليلكم يدل على قولكم لكنه معارض بأمور:\rأحدها: أن العالم أبدى على ما تقدم فالقول بالحشر باطل.\rوثانيها: أن الجنة والنار اما أن تكونا فى هذا العالم أو فى عالم آخر. أما فى هذا العالم. فاما أن تكون فى عالم الأفلاك أو فى عالم العناصر. والأول محال لأن الأجرام الفلكية لا تقبل الخرق والالتئام ولا يخالطها شيء من الفاسدات.\rوالثانى: هو محض التناسخ وأما فى عالم آخر، فمحال. لأن الفلك بسيط على ما لاح فيكون شكله كريا. فلو فرض عالم آخر\r__________________\rم:، القول بالتشبيه: القول في التشبيه: ف، التشبيه: ي. (12/ 556) 1 ـ في القرآن والتوراة: في التوراة والانجيل والقرآن: ق.\r1 ـ فاذا: واذا: م، جاز: جار: ك، تايين فرض ك، (12/ 556) 2 ـ في القرآن .. التشبيه ل.\r2 ـ في هذا الباب: في هذا: ك، ههنا: ل، دليلم: ا ت ب ف ي، دليلك: ق لب م، ذلك: ك.\r3 ـ قولكم: ا ت ج ف ل ي، قولك: ق ك لب م.\r4 ـ احدها .. ا، تسدها: ف، لمن الصالم .. ت فقط. ابدي على ما تقدم: ت ج ق ك ل لب ي، ابدي: م، ابد عني ما تقدم ف، فالقول بالحشر: ت ج ف ق ل لب م ي، فالفوا بالقوم ا فالبشر: ك، باطل: محال: م.\r5 ـ ثانيها: ب ا تكونا: يكون: ا، هذا: ك، اوفى: او: ك.\r6 ـ اما في: فان كان في: ك، في (2): ك.\r7 ـ الخرق والالنام: ا، الخرق: ت ج ك ل لب م، الاثر ا ق ف ق ي.\r8 ـ ولا: فلا: ف ق ي.\r9 ـ هو: وهو: ج ق م، ي، واما: ما: م.\r10 ـ فيكون شكله: ت ج، فشكله: ق ل م، كريا: ت، الكرة: ج ك لب م، الكرى: ل، كرى: ف ق ي."], [558, "لكان كريا فيفرض بين العالمين خلاء وهو محال.\rوثالثها: وهو أن إنسانا إذا أكله إنسان آخر حتى صار جزء بدن أحدهما جزء بدن الآخر. فليس بأن يعاد جزأ لبدن أحدهما أولى من أن يعاد جزأ لبدن الآخر، وجعله جزأ لبدنيهما معا محال، فلم يبق إلا أن لا يعاد واحد منهما.\rورابعها: أن المقصود من البعثة اما الإيلام أو دفع الألم، أو الالذاذ والأول لا يصلح أن يكون مقصودا للحكيم.\rوالثانى باطل أيضا فإنه يكفى فيه البقاء على العدم فيبقى الثالث لكن ما يتخيله لذة فى هذا العالم فهو فى الحقيقة ليس بلذة بل كل ذلك خلاص عن الألم، وانتقال من ألم إلى ألم آخر. إنما اللذة بالحقيقة\r__________________\r1 ـ كريا: كذبا: ا، فيفرض: فنفرض: لب، فتعترض: ا، فيلزم: ق.\r2 ـ ثالثها: ج: ا، وهو: ق، انسانا: انسان: ك.\r2، 3 ـ جزء بدن احدهما: ا.\r3 ـ لبدن: ت ج، بدن: ا ق ك ل لب، البدن: ي، في: م، احدهما: الاخر هما: ي.\r3، 4 ـ فليس ... من ان بان: ك معا: م: ت ج ق ك ل لب م ي، وجعل جزء البدن جزء البدنين معا: ف.\r4 ـ لبدن الاخر: ت ج، بدن الاخر: ا ق ك ل لب، لبدن آخر: م، البدن الاخر: ي، جملة: ت ج ك ل لب م، جعل جزء البدن: ق ي، لبدنيهما: ت ق، لبدنهما: ج ك لب م ي، بدنهما: ا.\r5 ـ لا: ت ج فقط.\r6 ـ رابعها: د: ا، البعثة: ت ك ل لب م، البعث: ج ف ق ي.\r7 ـ يصلح: يصح: م، للمحكيم: ت ج ف ق ك ل لب ي، لحكيم م.\r8 ـ البقاء: من البقاء: ف، الابقاء: لب، فيبقى انا ت فبقى: ج ك م.\r9 ـ يقيله: فتقبله: ق، ليس بلدة: قبل فهو انا ق.\r10 ـ و: ت ج ف ق ل ي، او: ك لب م، الى الم: الى: ك"], [559, "هى اللذة الروحانية. وإذا كان كذلك كان رد النفس إلى البدن عبثا.\rوالجواب أنه ثبت بالتواتر أنه عليه السلام كان يثبت المعاد البدنى وذلك لا يقبل التأويل.\rأما المعارضة الأولى فالجواب عنها قد تقدم وعن الثانية أن الخلاء جائز. وعن الثالثة أن الجزء الأصلي لأحدهما فاضل للآخر، ورده إلى الأول أولى. وعن الرابعة ما نقدم فى باب الاعراض من اثبات اللذة الحسية.\rتنبيه:\rالمعاد بمعنى جمع الأجزاء لا يتم إلا مع القول باعادة المعدوم لما مر أن هوية الشخص ليست مجرد الجسم، بل لا بد فيها من الأعراض، وهى قد عدمت عند التفرق، فلو لم يمكن إعادة المعدوم امتنعت إعادته من حيث أنه هو.\rمسئلة:\r__________________\rانما: اما: ك.\r1 ـ واذا: فاذا: ا ك.\r2 ـ السلام: الصلاة والسلام: م فقط.\r3 ـ ذلك: كذلك: ف.\r4 ـ قد: م فقط، الثانية: ب: ا.\r5 ـ الثالثة: الثالث: ك ي، ج: ا، الاصلي اصلى ي، فاضل: واصل: ك، ورده: ا ت ل، فرده: ج ف ق ك لب م ي.\r6 ـ الرابعة: الرابع: ج ك، د: ا، الاعرضا: الاعتراض: ك م.\r11 ـ هي: ف ك ي، يمكن: ج ل م ي، يكن: ت ك ف. فلو ... العدوم: فلو امنتعت المادة المعدوم: ق، المعدوم: ف.\r12 ـ امتنعت: ت ج ف ل ي، جائزة لامتنعت: لب، لامتنعت: ك م."], [560, "لم يثبت بدليل قطعى أن الله تعالى يعدم الأجزاء ثم يعيدها، واحتج القاطعون عليه بآيات:\rأحدها: قوله تعالى (كُلُّ شَيْءٍ هالِكٌ إِلَّا وَجْهَهُ)، والهلاك هو العناد. وثانيها قوله تعالى: (هُوَ الْأَوَّلُ وَالْآخِرُ) وإنما كان أولا لأنه كان موجودا قبل وجودها. فكذا إنما يكون آخرا إذا كان موجودا بعد وجودها.\rوثالثها قوله تعالى: (كَما بَدَانا أَوَّلَ خَلْقٍ نُعِيدُهُ) بين أن الإعادة كالابتداء. وكان الابتداء عن العدم فوجب أن تكون الإعادة أيضا عن العدم.\rوالجواب عن الأول: لا نسلم أن الهالك هو المعدوم بل هو الّذي خرج عن حد الانتفاع، والأجسام بعد تفرقها تصير كذلك سلمنا أنه المعدوم لكن الآية على هذا التقدير لا يمكن اجراؤها على ظاهرها، لأن وصفها بكونها هالكة يقتضي أن تكون معدومة فى\r__________________\r2 ـ وجوه ثلاثة: ا ت ج ف ق ك ل ي، وجوه: م: لب الاول: ا: ا، احدها: ج، وعليه التمويل: تقدمت على النبوة: م، وسقطت: في: ا لب.\r3 ـ ظهر المعجر على يده عليه: م: ق ك ل م، ظهر: لب ظهرت المعجزة على يده: ف لب ي، اظهر المعجزة على يده: في ج، عليه: في ت، عليها المعجزة: ل متن: ت جل.\r4 ـ كذلك: ف، فهو نبي ورسول: ت: ت ف، فهو سول: ج، كان نبيا ورسولا: ق ل: ق ك ل م، و (2): ك.\r5 ـ وانما .. للتواتر: ف.\r8 ـ للتواتر: ا ت ق ك، بالتواتر: ج ل لب، فللتواتر: م ي. انه: ل ف لب ي، ظهرت ظهر: لب ق ك م المعجز المعجزة: ف لب ي ل: ت ف ق ك ل لب م ي، اظهرت المعجزة: لثلاثة اوجه: ت ج ف ك ل لب ي، فلثلاثة اوجه: م، لوجوه ثلاثة: ق.\r10 ـ انه (1): ف.\r12 ـ فبالتواتر: فللتواتر: ق. ك ل م، فان: ج، ت."], [561, "الحال، وهو بالاتفاق باطل. فوجب تأويلها. فإن حملتموه على أن مآلها إلى الهلاك، ونحن حملناه على أنها قابلة للهلاك، فلم كان تأويلكم أولى من تأويلنا.\rوعن الثانى لم لا يجوز أن يقال: هو الأول والآخر، بحسب الاستحقاق لا بحسب الزمان\rوعن الثالث أن تشبيه الشيء بغيره لا يقتضي مشاكلتهما فى كل الأمور.\rمسئلة:\rسائر السمعيات من عذاب القبر والصراط والميزان وانطاق الجوارح، وتطاير الكتب وأحوال أهل الجنة والنار، فهى فى أنفسها ممكنة والله تعالى عالم بالكل قادر على الكل فكان خبر الصادق عنها مفيدا للعلم بوجودها.\rمسئلة:\r__________________\r1 ـ فان حملتموه: ت ج، قلتم او انتم: ل حلمتموه ها: ق: ا ف ق ك ل لب، فانهم حملوها: م.\r2 ـ حملناه: ا ت ج ف ك ل لب ي، حملناها: ق م، كان يكن: في م فقط.\r(10/ 560)، 5 ـ استبدل ما بعد لاول ... الزمان الى ما بعد الثاني في م فقط فيه تقديم وتاخير بين المادتين.\r6 ـ الثالث: ج: ا، ان: انه: ت، الشيء: شيء: ق، مشاكلتهما: ت ج، مشابهتهما: ك ل م.\r7 ـ الامور: ت ج ل م، وبالله التوفيق: ك.\r9 ـ سائر: ت ج ق ل م: ك، انطاق: انطلق: ت.\r11 ـ ممكنة: ممكن: ت، و: ف ك لب قادر على الكل: ف م فقط، فكان: وكان: م.\r12 ـ بوجودها: ا ت ج ق ك لب ي، لوجوها: ف، بوجوبها وصحتها: م، بوجوها: ل."], [562, "وعيد أصحاب الكبائر منقطع عندنا خلافا للمعتزلة.\rلنا قوله تعالى: (فَمَنْ يَعْمَلْ مِثْقالَ ذَرَّةٍ خَيْراً يَرَهُ وَمَنْ يَعْمَلْ مِثْقالَ ذَرَّةٍ شَرًّا يَرَهُ). ولا بد من الجمع بين العمومين. فإما أن يقال صاحب الكبيرة يدخل الجنة بإيمانه، ثم يدخل النار، وهو باطل بالاتفاق. أو يدخل النار بكبيرته ثم ينقل إلى الجنة وهو الحق.\rوأيضا قوله تعالى: (مَنْ عَمِلَ صالِحاً مِنْ ذَكَرٍ أَوْ أُنْثى وَهُوَ مُؤْمِنٌ فَأُولئِكَ يَدْخُلُونَ الْجَنَّةَ).\rدليل ثان يعترف الخصم بأن المؤمن استحق الثواب بإيمانه. فإذا فعل الكبيرة فالاستحقاق الأول إما أن يبقى أو لا يبقى فإن بقى وجب إيصال الثواب إليه ولا طريق إليه إلا بنقله من النار إلى الجنة. وان لم يبق فهو محال لوجوه:\r__________________\r1 ـ وعيد وعند: ت اصحاب: ا ت ج ف ق ك لب ل ي، وعيد: م.\r2 ـ الزلزلة: 7 ـ 8، من الجمع: للجمع: م.\r5 ـ او و: ت يدخل: ا ت ج ف ق ك ل لب ي، لولا يدخل احدها وهو باطل ايضا او يدخل: م، بكبيرته: بكبيرة: ف، بمعاصية: لب، بكفره: ت، ينقل الى: يدخل: م فقط، وهو: بايمانه وهو: م فقط.\r6 ـ ايضا: ل، تعالى: لب م، عمل: ا ت ج ف ك ل لب ي، يعمل: ق م، وهو: فهو: ا.\r7 ـ سورة المؤمن: 40، هذا دليل على ان صاحب الكبيرة يدخل الجنة: ق.\r8 ـ يعرف الخصم: ج ل، لان: ا الخصم يعترف: ا ق لب، يقر الخصم: ف ي، ان: م الخصم معترف: ك م، فاذا: واذا: ي.\r8، 9 ـ الخصم ... فعل: ت فقط.\r9 ـ فالاستحقاق الاول: ت ك ل م، فانما: ج.\r10 ـ ايصال ... اليه: ا ت ج ف ق ل لب ي، اتصال الثواب: ك م.\r11 ـ وان: فان: ق."], [563, "الأول: وهو إنه ليس انتفاء الباقى لطريان الحادث أولى من اندفاع الحادث لوجود الباقى.\rالثانى: وهو أنهما أو كانا ضدين كان طريان الاستحقاق الطارئ مشروطا بزوال الاستحقاق السابق. فلو كان زواله لأجل طريان الحادث لزم الدور.\rالثالث: وهو أنه إذا استحق عشرة أجزاء من الثواب ثم فعل معصية استحق بها خمسة أجزاء من العقاب فليس انتفاء استحقاق احدى الخمستين أولى من انتفاء استحقاق الخمسة الأخرى. لأن أجزاء الثواب لما كانت متساوية كانت استحقاقها متساوية أيضا. فإما أن ينتفى مجموع العشرة وهو ظلم، أو لا ينتفى شيء منها وهو المطلوب.\rالرابع: إذا استحق عشرة أجزاء من الثواب ثم فعل ما به يستحق عشرة أجزاء من العقاب فالطارئ اما أن يحبط الأول ولا ينحبط\r__________________\r(11/ 562)، 1 ـ لوجوه الاول احدها: ج لب م: ت ج ف ق ك ل لب م، لوجوه ا: ا، الامور الاول: ي.\r1 ـ وهو: ا ت ج ق ك ل لب، هو: ف ي: م.\r2 ـ الثاني والثاني: لب م: ب: ا، وهو انهما: هو انهما: ف، كونهما: ي، الاستحقاق: ف.\r4 ـ السابق: الباقي: لب.\r5 ـ طريان: طريان هذا: ك م.\r6 ـ الثالث: ج: ا، ثم: و: ك لب م.\r7 ـ استحق: ك م، يستحق: ت ج ل، العقاب: العذاب: ف، العتاب: ك، استحقاق: ف ي.\r8 ـ الخمستين: الخمسين: ا ق ل، استحقاق: ف ي.\r9 ـ استحقاقها: ا ت ج ل لب، استحقاقاتها: ف ق ك م ي.\r10 ـ وهو: فهو: م فقط.\r11 ـ المطلوب: مطلوب: ك.\r12 ـ الرابع: د: ا، به: ك.\r13 ـ العقاب: العتاب: ك، يحيط: يحبطه: م، و: او: ق"], [564, "كما هو قول أبى على الجبائى أو يحبط وينحبط كما هو قول أبى هاشم فى الموازنة.\rوالأول باطل لأنه يصير فعل الطاعة السالفة لغوا محضا لا يظهر له أثر فى جلب نفع، ولا فى دفع ضرر. وهو باطل لقوله تعالى: (فَمَنْ يَعْمَلْ مِثْقالَ ذَرَّةٍ خَيْراً يَرَهُ).\rوالثانى: باطل لأن سبب زوال الاستحقاق الأول حدوث الاستحقاق الثانى. فإذا ما لم يوجد الاستحقاق الثانى لا يزول الاستحقاق الأول. وإذا وجد الاستحقاق الثانى، وزال به الأول استحال أن يزول هذا الاستحقاق الثانى. لأنه ليس له مزيل فيصير هذا هو القسم الأول الّذي كان مذهبا لأبى على، وقد أبطلناه، يبقى أن يقال كل واحد من الاستحقاقين يزول بالآخر دفعة، لكن هذا محال لأن علة عدم كل واحد منهما وجود الآخر، فلو عدما دفعه لوجدا دفعة، لكن العلة موجودة، حال حدوث المعلول فهما\r__________________\rك ي.\r1 ـ الجباني: ك، ينحبط: يتحبط: ا ف، يحبط: ق.\r3 ـ السالفة: السابقة: ق ك.\r4 ـ ق (2): ت ج ل لب م، جلب نفع تاخر الى ما بعد ضرو في: لب.\r5 ـ سورة الزلزلة: 7.\r6 ـ حدوث: وهو حدوث: ي.\r6، 7 ـ سبب ... لم يوجد: سبب زوال: ف.\r7 ـ فاذا: فاما اذا: ك.\r8 ـ الاستحقاق (1): ت ج ق، ك ل م، وزال به: ت ج ف ق ك ي م، وزال به الاستحقاق: ل، فزال به: لب، زال به: ا.\r9 ـ له: ك، مزيل: مزيد: ت.\r10 ـ كان مذهبا: هو مذهبنا: ك، ابطلناه: بطلناه: ف.\r11 ـ يبقى: ت ك ل م، فبقى: ق لب، وبقى: ي، بقى، ف، لكن: ولكن: م.\r12 ـ عدم: ك فلو: ولو: ف.\r13 ـ المعلول: فلمعلولين: ا."], [565, "موجودان حال كونهما معدومين، هذا خلف. فهذه وجوه دالة على فساد قولهم فى المحابطة. ومتى ثبت ذلك ثبت انقطاع العقاب.\rدليل ثالث قوله تعالى: (إِنَّ اللهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ ما دُونَ ذلِكَ لِمَنْ يَشاءُ). وكذا قوله تعالى (وَإِنَّ رَبَّكَ لَذُو مَغْفِرَةٍ لِلنَّاسِ عَلى ظُلْمِهِمْ) وكلمة «على» للحال. يقال رأيت الأمير على أكله، أى حال أكله. فالآية تقتضى حصول المغفرة حال اشتغال العبد بالظلم، وهو يدل على حصول المغفرة قبل التوبة.\rدليل رابع أجمع المسلمون على كونه تعالى عفوا، والعفو لا يتحقق الا عند إسقاط العذاب المستحق. وعند الخصم ترك العقاب على الصغيرة قبل التوبة، وعلى الكبيرة بعدها واجب، فلا يبقى للعفو معنى إلا إسقاط العقاب على الكبيرة قبل التوبة. احتج الخصم بقوله تعالى: (وَمَنْ يَقْتُلْ مُؤْمِناً). وبقوله: «وَإِنَّ الْفُجَّارَ لَفِي\r__________________\r1 ـ موجودان: موجودين: ا، معدومين: معدومان: ك، على: في م فقط.\r2 ـ فساد: بطلان: ق، في: ب: ف ي، منى: اذا: ا، ذلك: هذا: ي، ثبت انتقطاع: انقطع: لب.\r3 ـ ثالث: ج: ا.\r4 ـ سورة النساء: 116.\r5 ـ سورة الرعد: 6، اي: اي علي: ق.\r7 ـ وهو: فهي: ك، على: على حال: ك.\r8 ـ رابع: د: ا.\r10 ـ وعلى: على: ا، بعدها: قبل التوبة: ا، واجب: واجبة م فقط، فلا: ت ج ق ك ل لب ي، ولا: ف، لا: م.\r11 ـ الا اسقاط: لاسقاط: ك، الاسقاط: ق، العقاب: العذاب: ي: ف ق.\r12 ـ سورة النساء: 92 متعمدا فجزاؤه جهنم خالدا فيها م، متعمدا الاية: ك: ق ك، وبقوله: وبقوله تعالى: ق، ا ف."], [566, "جَحِيمٍ».\rوالجواب سنبين فى أصول الفقه أن صيغ العموم ليست قاطعة فى الاستغراق، بل ظاهرة فيها محتملة للخصوص وإذا كان كذلك لم يكن التمسك بها فى القطع على الوعيد. وأيضا فهى معارضة بآيات الوعد ولا طريق الى التوفيق إلا ما ذكرناه.\rمسئلة:\rأجمعوا على أن وعيد الكافر المعاند دائم. أما الكافر الّذي بالغ فى الاجتهاد ولم يصل إلى المطلوب، فقد زعم الجاحظ والعنبرى أنه معذور لقوله تعالى (وَما جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ) والباقون أبوه وادعوا فيه الإجماع وبالله التوفيق.\r__________________\r1 ـ سورة الانفطار: 14، وان: ان: ك، وان الابرار الاية: ك.\r2 ـ سنبين: سياتي: ك، الفقه: الفقه انشاء الله تعالى: ا ك لب، صنع: صيغة: ا.\r3 ـ فيها: ا ت ج ل لب، فيه: ف ق ي، ك م، واذا: فاذا: ا.\r4 ـ يكن: ت ك ل، يمكن، ج م، التمسك: للتمسك: ي، المتمسك: لب، بها في القطع: ا ت ج ف ق ل ي، جازما في القطع: لب، بالقطع فيها: ك، بها والقطع: م، فهي معارضة: فهو معارض: م.\r5 ـ الوعد: الموعد: ي، التوفيق: التوقيف: ق ك، الا: سنين: ق، ذكرناه: ذكرنا: ت ف ل م.\r7 ـ لجمعوا: المسلمون اجمعوا: لب، الكافر المعاند: الكافر والمعاند: ي، الكفار المعاندين ك.\r8 ـ وعبد الله بن الحسين العنبري: ج ق ك لب، العنتري م، ت ف ي، انه: ف.\r9 ـ وما: ت ق ك ل م، سورة الحج: 78.\r10 ـ وادعوا: ق ك لب م ي، فادعوا: ا ف ل، ادعوا: ت. الاجماع: من الاجماع: م، وبالله التوفيق: ق ك لب م، ا ت ج ف ل ي."], [567, "القسم الثالث\r"]], "pg": [537, 567]}, "687.16": {"x": [[567, "فى الأسماء والأحكام\rمسئلة:\rلا نزاع فى أن الإيمان فى أصل اللغة عبارة عن التصديق، وفى الشرع عبارة عن تصديق الرسول بكل ما علم بالضرورة مجيئه به، خلافا للمعتزلة فإنهم جعلوه اسما للطاعات والسلف فإنهم قالوا إنه اسم للتصديق بالقلب، والاقرار باللسان، والعمل بالأركان.\rلنا أن هذه الطاعات لو كانت جزأ من مسمى الإيمان شرعا لكان تقييد الإيمان بالطاعة تكريرا، وبالمعصية نقضا لكنه باطل لقوله تعالى: (إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ) وبقوله تعالى (الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمانَهُمْ بِظُلْمٍ).\r__________________\r4 ـ اصل: ا ك.\r5 ـ الرسول: الرسول عليه السلام: ق ك، به: ل.\r6 ـ للطاعات للطاعة: ا ي والسلف: ا ت ف ي ل، للطاعات وللسلف ج لب، للطاعات واما السلف ق، للطاعات وللسعادات م، انه: ك.\r8 ـ لكان: كان: ت.\r9 ـ نقضا: ت ج ك لب ي، نقصا: ف ل، نقصا: ق م، لقوله: بقوله: ق م.\r10 ـ تعالى (1، 2): ت ج ل، وبقوله: ت ج ل ك، وقوله م، سورة الكهف: 107.\r10، 11 ـ ان الذين ... بظلم: ا ت ج ف ق ك ل لب ي، الذين آمنوا ولم يلبسوا ايمانهم بظلم وقوله تعالى الذين آمنوا وعملوا الصالحات: م، سورة الانعام: 82."], [568, "واحتج الخصم بأمور:\rأحدها: أن فعل الواجبات هو الدين لقوله تعالى: «وَما أُمِرُوا إِلَّا لِيَعْبُدُوا اللهَ مُخْلِصِينَ) ـ إلى قوله ـ (ذلِكَ دِينُ الْقَيِّمَةِ». فقوله تعالى (وَذلِكَ) يرجع إلى كل ما تقدم. فكان كل ما تقدم هو الدين والدين هو الإسلام لقوله تعالى: (إِنَّ الدِّينَ عِنْدَ اللهِ الْإِسْلامُ). والإسلام هو الإيمان. إذ لو كان غيره، لما كان مقبولا ممن ابتغاه. لقوله تعالى: (وَمَنْ يَبْتَغِ غَيْرَ الْإِسْلامِ دِيناً فَلَنْ يُقْبَلَ مِنْهُ)، ولما كان الإيمان مقبولا منه علمنا أنه الإسلام وإذا ثبت ذلك لزم أن فعل الواجبات هو الإيمان.\rوثانيها: ان قاطع الطريق يخزى يوم القيامة. والمؤمن لا يخزى يوم القيامة. فقاطع الطريق غير مؤمن أما أن قاطع الطريق يخزى.\r__________________\r1 ـ واحتج: احتج: ت ج ل، احتجوا: لب.\r2 ـ احدها: الاول: لب، ا: ا، ان فعل .. الدين: تمسكوا: ي، الدين لقوله: الدين بقوله: م ي، الذي لقوله: ا.\r3 ـ مخلصين: ف ق م، ذلك: فذلك: م، تعالى وذلك لب فقوله: وقوله: ق، ا ك.\r4 ـ تعالى: لب م، وذلك: فذلك: ل، يرجع: راجع: ف.\r5 ـ سورة آل عمران: 19.\r6 ـ غيره لما كان: ك، لما كان مقبولا: لكان غير مقبول: ل، ممن ابتغاه: ي.\r7 ـ تعالى: ل، يبتغ غير ك ابتغى عن: ت، سورة آل عمران: 85.\r8 ـ منه: ت ج ف: ق ك ل لب م ي، انه الاسلام: ف ق ك لب م، ان الاسلام وهو الايمان: ج: ت ج، ممن ابتغاه فعلمنا ان الاسلام ه الايمان: ي، ذلك: هذا: لب.\r10 ـ ثانيها: ب: ا، يخزى (1): يجزي: ك م، يخزى (2): يجزى: ك م.\r11 ـ فقاطع طريق: فالقاطع: م فقط، يخزى: يجزى: ا ف ك ي يوم القيامة: ك لب ي."], [569, "فلأن الله تعالى يدخله النار يوم القيامة لقوله تعالى فى صفتهم: (وَلَهُمْ فِي الْآخِرَةِ عَذابُ النَّارِ) وكل من أدخل النار فقد أخزى. لقوله تعالى: (رَبَّنا إِنَّكَ مَنْ تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ) وانما قلنا أن المؤمن لا يخزى لقوله تعالى (يَوْمَ لا يُخْزِي اللهُ النَّبِيَّ وَالَّذِينَ آمَنُوا مَعَهُ).\rوثالثها: أنه لو كان الإيمان فى عرف الشرع عبارة عن التصديق، لكان كل من صدق الله تعالى أو الجبت والطاغوت مؤمنا.\rورابعها: قوله تعالى (وَما كانَ اللهُ لِيُضِيعَ إِيمانَكُمْ) أى صلاتكم.\rوالجواب عن الأولين أنا نحمل ذلك على كمال الإيمان ضرورة التوفيق بين الأدلة. وعن الثانى المراد منه الكفار.\r__________________\r1 ـ فلان الله: فا الله: ك، فلانه: ف، تعالى (1): ق، القيامة: ي، تعالى (2): لب، في صفتهم: ف.\r1، 2 ـ و: ت ج ل لهم في الاخرة: كل النسج عذاب النار: ت ج ف ل لب م، الحشر: 3، ولهم في الاخرة عذاب النار: ت ج ف ل لب م، الحشر: 2، ولهم في الاخرة عذا ب عظيم: ي المائدة: 33، 41، ولهم عذاب عظيم: ف ك آل عمران: 176.\r2 ـ ادخل: ادخل في: ي، دخل: ا، اخرى: ليجزي: م، اخرى: ا ف.\r3 ـ ربنا: ق، ان: بان: م.\r4 ـ والذين: ت، سورة التحريم: 8.\r5 ـ ثالثها: ج: ا، انه: ك م، لو كان الايمان: وهو ان الايمان لو كان: لب.\r6 ـ تعالى: ت ي، او و: ت، وصدق: ك، والطاغوت او الطاغوت: ق، مؤمنا: كان مؤمنا: ا لب.\r7 ـ رابعها قوله تعالى: د: ا، سورة البقرة: 143.\r7، 8 ـ اي صلاتكم: ت ج ف ل.\r9 ـ الاولين بانا: ت ق ك ل ي، ابانا: ا، الاولين انا: ج ف م، الاولين ان: لب، ذلك: لب.\r10 ـ التوفيق: التوقيف: ك، الادلة: الادلة وعن ب، المراد منه الكفار: ا."], [570, "وعن الثالث بأنا نخصصه ببعض التصديقات. والتخصيص أهون من التغيير.\rوعن الرابع: انا نحمل ذلك على الإيمان بتلك الصلاة لا على نفس الصلاة.\rتنبيه:\rصاحب الكبيرة عندنا مؤمن مطيع بإيمانه عاص بفسقه. وعند المعتزلة لا يسمى مؤمنا ولا كافرا. وعند جمهور الخوارج كافر لقوله تعالى: (وَمَنْ لَمْ يَحْكُمْ بِما أَنْزَلَ اللهُ فَأُولئِكَ هُمُ الْكافِرُونَ) وعند الأزارقة مشرك، وعند الزيدية كافر النعمة وعند الحسن البصرى منافق، لقوله عليه السلام: آية المنافق ثلاث.\rمسئلة:\rالإيمان عندنا لا يزيد ولا ينقص لأنه لما كان اسما لتصديق\r__________________\r1 ـ الثالث: ج: ا، والتخصيص: ك.\r2 ـ التغيير: التغير: ي.\r3 ـ الرابع: د: ا، تحمل ذلك: تحمله: م، تحمل: ا، لا: ا، على (2): عن: ق.\r4 ـ نفس: يقين: ك.\r6 ـ الكبيرة: الكبيرة هو: ا.\r7 ـ مؤمنا ولا كافرا، مؤمن ولا كافر: ك، عند: م. جمهور: الجمهور و: ك.\r8 ـ سورة المائدة: 44.\r9 ـ مشرك: مشركة: 2، مشترك ي، الزيدية: الردية: ا، البدرية: ف، النعمة: للنعمة: ك، لنعمه: م، لب.\r10 ـ عليه: والصلاة و: م، آية المنافق: انه لمنافق: ت.\r11 ـ مسئلة: والله اعلم مسئلة: ق، ك.\r12 ـ الايمان عندنا: عندنا الايمان: لب، لانه: انه: ق."], [571, "الرسول فى كل ما علم بالضرورة مجيئه به. وهذا لا يقبل التفاوت. فمسمى الإيمان لا يقبل الزيادة والنقصان.\rوعند المعتزلة لما كان اسما لأداء العبادات، كان قابلا لهما.\rوعند السلف لما كان اسما للاقرار والاعتقاد، والعمل، فكذلك. والبحث لغوى. ولكل واحد من الفرق نصوص. والتوفيق أن يقال الأعمال من ثمرات التصديق. فكل ما دل على أن الإيمان لا يقبل الزيادة والنقصان كان مصروفا إلى أصل الإيمان، وما دل على كونه قابلا لهما فهو مصروف إلى الإيمان الكامل.\rمسئلة:\rأكثر أصحابنا قالوا أنا مؤمن إن شاء الله، لا لقيام الشك، بل اما للتبرك أو للصرف إلى العاقبة.\rمسئلة:\r__________________\r1 ـ الرسول: الرسل: لب.\r2 ـ فمسمى ... الزيادة: ا ت التفاوت: ج: ا ت ج ف ي، فكان وكان: ق لب مسمى الايمان غير قابل للزيادة: ق ك لب م، الزيادة: ل التفاوت.\r3 ـ الاداء العبادات: للطاعات والعبادات: ف، كان (2): ق لهما: ك.\r4 ـ اسما: قابلا: ك، والاعتقاد: بالاعتقاد: ك، فكذلك: فكذلك وظهر الطرق: ق.\r5 ـ ولكل: فلكل: ي.\r6 ـ فكل: وكل: لب.\r7، 8 ـ كونه قابلا: انه قابل: م.\r8 ـ لهما: للزيادة والنقصان: لب، الايمان: نمرات الايمان: ك.\r10 ـ انا مؤمن: انا مؤمن: ي، الله تعالى: ي بل: ف ق لب ل ج ي: ك ت ك م.\r11 ـ للتبرك: للتبرك يقول الملف: ي، او للصرف: ج ف د م ي، او و، ل الطرف: ا لب ل، للعمير: ت."], [572, "الكفر عبارة عن انكار ما علم بالضرورة مجىء الرسول به فعلى هذا لا يكفر أحد من أهل القبلة لأن كونهم منكرين لما جاء به الرسول غير معلوم ضرورة، بل نظرا والله أعلم.\r__________________\r1 ـ علم، عرف، لب، مجيء: من مجيء، ك، الرسول عليه السلام: ك.\r2 ـ يكفر احد: ا ت ف ق ك ل، تكفر احدا: ج لب م ي.\r3 ـ الرسول: الرسول عليه السلام: ف، والله اعلم: ت، وبالله التوفيق والحمد لله رب العالمين والصلاة على سيدنا محمد وآله اجمعين: م، والله اعلم تم الكتاب بحمد الله وعونه وحسن توافيقه ومنه وكرمه .. على ايدي محمد بن عبيد بن محمد الهلالي غفر الله له ولوالديه ولجميع المسلمين: ك، والله عزوجل اعلم بالصواب واليه المرجع والماب: ي، والله اعلم تم الكتاب بحمد الله وعونه ووفيقه ويمه وصلواته على سيدنا محمد النبي وعلى آله واصحابه وسلم تسليما كثيرا مباركا طيبا كتبه عثمان بن علي بن عبد الواحد القرشي وكان فراغه فينصف ذي القعدة منسنة 664 حسنا الله ونعم الوكيل، (120 ـ) وباغه للفقيه عمر سراع بمدرسة الكامل الشراء من ناصر الدين السماع الكتبي بمصر المحروسة بتاريخ شوال سنة اربع وستين وستمائة: ك، ا ج ف ق لب ل."], [573, "القسم الرابع\r"]], "pg": [567, 573]}, "687.17": {"x": [[573, "فى الامامة\rمسئلة:\rمن الناس من قال بوجوبها. ومنهم من لم يقل بذلك. أما القائلون بوجوبها فمنهم من أوجبها عقلا، ومنهم من أوجبها سمعا. وأما الموجبون عقلا فمنهم من أوجبها على الله تعالى ومنهم من أوجبها على الخلق. فالذين أوجبوها على الله تعالى هم الإمامية. ثم ذكروا فى وجوبها وجوها.\rأحدها أن يكون لطفا فى الزجر عن المقبحات العقلية. وهو قول الاثنى عشرية.\rوثانيها: أن يكون معلما لمعرفة الله تعالى وهو قول السبعية.\r__________________\r3 ـ مسئلة: فصل: م، ي.\r4 ـ من الناس: منهم: ي م، بذلك: م.\r5 ـ القائلون: من قال: ف، فمنهم: ت ج ق، منهم: ل م، سمعا: شرعا: ق.\r6 ـ واما: ا ف ي، اما: ج ق ل لب م: ت، عقلا: لها عقلا: ا ف ي.\r7 ـ فالذين ا ت ف ق ي، ثم الذين: لب، والذين: ج ل م هم: فهم: ف، ت.\r8 ـ وجوبها: وجوبه: ل، وجوها: وجوه: ج.\r9 ـ احدها: ا: ا، لطفا في الزجر: ت ج ف ل لب م، زاجرا: ا ي.\r11 ـ ثانيها: الثاني: م، ا، لمعرفة: بمعرفة: م، السبعية: لب م ن، الشيعة: ا ت ج ل ي، الاسماعيلية: ف ق."], [574, "وثالثها: أن يعلمنا اللغات ويرشدنا الى الأغذية ويميزها عن السموم. أما الذين أوجبوها على الخلق لا على الله تعالى فهو قول الجاحظ والكعبى وأبى الحسين البصرى. وأما الذين أوجبوها سمعا فقط، فهم جمهور أصحابنا، وأكثر المعتزلة. وأما الذين لا يقولون بوجوبها فهم الخوارج والأصم.\rلنا أن نصب الامام يتضمن دفع الضرر عن الناس فيكون واجبا. أما الأول فلأنا نعلم أن الخلق إذا كان لهم رئيس قاهر يخافون بطشه ويرجون ثوابه، كان حالهم فى الاحتراز به عن المفاسد أتم مما إذا لم يكن لهم هذا الرئيس.\rوأما أن دفع الضرر عن الناس واجب فبالاجماع عند من لا يقول بالوجوب العقلى وبضرورة العقل عند من يقول به.\r__________________\r1 ـ ثالثها: ج: ا، يعلمنا وان: ت ج ف ل لب: ت ج ف ق ل لب م، يعلم اللغات ر: ا ي، عن: من: ق.\r2 ـ اما: واما: م، الخلق لا على: الخلق على: ا، على غير م، فهو قول: ج ل لب م، وهو قول: ي، فهم: ف ق، ف: ت.\r3 ـ ابي: ج ل لب م، ابو: ا ت ف ق ي.\r4 ـ فهم: فهو: ت، وهم: م، واما: فاما: ا، اما: ج ل.\r5 ـ لا يقولون: ا ت، لم يقولوا: ج ف ق ل لب م ي، بوجوبها: لوجوبها: ف.\r6 ـ ان: ف، الناس: ا ت ي، النفس: ج ف ق ل لب م.\r7 ـ ان الخلق .. لهم: ا ت ج ف ق ل لب ي، اذا كان الخلق لهم: م.\r8 ـ كان حالهم في الاحتراز به: ت: ت ج ف ق ل لب ي، ايم في الاحتراز: ا، احترازهم: م.\r9 ـ مما: بما: ا، منه: ق ي، هذا: ذلك: لب.\r10 ـ الناس: ت ي، النفس: ج ف لب ل م، لا يقول: ا ت ج ل لب ي، لا يقولوا: ف، يقول: ق م.\rهنا انتهى شرح المفضل للقزويني الانه لم ير حاجة لتفصيل مذاهب الشيعة حيث انها موجودة في كتب الامام.\r11 ـ العقلي: ي."], [575, "مسئلة:\rالشيعة جنس، تحته أربعة أنواع: الإمامية، والكيسانية، والزيدية والغلاة، أما الإمامية فالذين استقر عليه رأيهم. أن الإمام بعد الرسول عليه السلام على بن أبى طالب رضى الله عنه ثم ولده الحسن، ثم أخوه الحسين، رضى الله عنهما ثم ابنه على، ثم ابنه محمد الباقر، ثم ابنه جعفر الصادق، ثم ابنه موسى الكاظم، ثم ابنه على الرضا ثم ابنه محمد التقى ثم ابنه على النقى، ثم ابنه الحسن الزكى، ثم ابنه محمد وهو القائم المنتظر.\rولقد كان لهم فى كل واحد من هذه المراتب اختلافات:\rفنقول: القائلون بالنص الجلى على على بن أبى طالب رضى الله\r__________________\r2 ـ الشيعة: ت، الشيعي: ج ل، للشيعة: ا ف ي، للشيعي: ق لب، للشيء: م.\r3 ـ اما: م، عليه رابهم: ا ف ق ل ي، عليهم رايهم: ت ج، رابهم على: لب م.\r4 ـ الرسول: ج م، رسول الله: ف، النبي: ت ل، عليه السلام: ت ف لب ي، صلى الله عليه وسلم وآله: ق ل: ا ق ل، عليه الصلاة والسلام: م، اين ابي طالب: ف، رضي الله عنه: ا ف ي، كرم الله وجهه: ت، عليه السلام: ق ل: لب ج م.\r5 ـ رضي الله عنهما: ف فقط.\r7 ـ التقي: ج ق ل، المتقي: م، ابنه على النقي النقي: لب م: ج ف ق لب ل م، ي، الحسن: ج ق لب م، الحسين: ي، ف.\r7، 8 ـ علي موسى: ل الرضا ... ابنه محمد: ت.\r8 ـ المنتظر: ا ت ج ف ق لب ي، المنتظر رضوان الله عليهم اجمعين: م.\r9 ـ لقد: ا ت ج ف ق لب ل ي، قد م، كل واحد واحدة: ف ي من: ا ت ج ف ق لب ل ي، في: م، المراتب: الرواتب: ي.\r10 ـ فنقول: ت ج ف، فيقول: م، امامة على: لب، علي: ت ج ف ق م: ي."], [576, "عنه، اتفقوا على أنه كان متعينا للإمامة.\rوعن فرقة من الإمامية أنهم قالوا الأمر بعد الرسول عليه السلام إلى على بن أبى طالب رضى الله عنه يفعل فى الإمامة ما أحب ان شاء جعلها لنفسه وان شاء ولاها غيره.\rوزعمت الكاملية وهم أصحاب أبى كامل معاذ بن الحصين النبهانى، أن الصحابة كفرت بمخالفتهم النص الجلى. وأن عليا عليه السلام كفر بترك القتال معهم.\rأما الأكثرون فاتفقوا على أنه كان متعينا للإمامة. وان كان محقا فى ترك القتال للتقية. ثم اختلفوا بعد موته.\r__________________\r(10/ 575) 1 ـ رضي الله عنه: م، كرم الله وجهه: ف، صلوات الله عليه، ق، عليه السلام: ج لب ي.\r1 ـ اتفقوا على انه كان متعينا: ج ل ف، على انه كان متعينا: ا ت، اتفقوا على انه متعين: لب م.\r2 ـ وعن ... قالوا: وهم فوق قال بعضهم: ف، من: ت ل ج ق لب: م، الرسول: ت ق، النبي: ج لب ل م ي. عليه السلام: ج ف ق لب، عليه الصلاة والسلام: م، صلى الله عليه وسلم: ا ي ل: ت.\r3 ـ رضي الله عنه عنهم، ي: ا ت ج ي، عليه السلام: ق ل: ف لب م، يفعل: ينفعل: ا، في الامامة: بالامامة: ت.\r4 ـ غيره: ت ج ل لب م ي، الى غيره: ف، لغيره: ق.\r5 ـ زعمت: ت ج ف ق ل ي، زعم: لب م، وهم اصحاب ابي ابو: ج كامل معاذ بن الحصين الحسين: ج ق التبهاني التيهاني: ف م، اليماني: ل: ج ف ق ل لب، ا ت ي.\r6 ـ بمخالفتهم: لمخالفتهم: ق ل.\r7 ـ عليه السلام: ت فقط، بترك: ت ف ي، بتركه، ج ل، لترك: ق لب م، ترك: ا.\r8 ـ فاتفقوا: ا ت ق ل لب ي، قد اتفقوا: ج، اتفقوا: ف م، للامامة: ا ت ج ف ل لب ي، في الامامة: ق م.\r9 ـ للتقية: ت ج ل م، للتقية معهم: ق، ثم: ت ج ف ل م ي، و: لب."], [577, "فزعمت السبائية أصحاب عبد الله بن سبأ أنه لم يمت، وإنه فى السحاب وان الرعد صوته والبرق سوطه. وإنه ينزل إلى الأرض بعد حين، فيقتل أعداءه. فاذا سمع هؤلاء صوت الرعد قالوا عليك السلام يا أمير المؤمنين.\rوأما الباقون فقطعوا بموته. ثم اختلفوا فمنهم من قال الامام بعده محمد بن الحنفية وهو قول بعض الكيسانية على ما سيأتى تفصيل قولهم فى فصل مفرد والأكثرون قالوا الإمام بعده الحسن ثم اختلفوا بعد موت الحسن. فمنهم من ساق الإمامية إلى ولده الحسن وهو الملقب بالرضا من آل محمد. ومنه إلى ولده عبد الله ومنه إلى ولده محمد، وهو النفس الزكية، ثم إلى أخيه إبراهيم.\rوالأكثرون ساقوها من الحسن إلى الحسين. ثم اختلفوا بعد\r__________________\r1 ـ فزعمت: ت ج ل ف لب ي، وزعمت: م، السبائية: السينائية: ا ق، عبد الله: في ف، ابن سبا ابن سينا: ا.\r2 ـ انسحاب: ا ت ج ف ق ل لب ي، السموات: م، صوته: ا ت ج ف ق ل لب ي، سوطه: م، سوطه، م ت ل ف ق، صواته: ي، ينزل: نزل: ا.\r3 ـ فيقتل: فيقبل: ا، ويصل: ف، اعداءه: اعداده ويكسر الصليب ويقتل ويملا الارض عدلا كما ملئت جورا: ق، قالوا: ا ت ج ف ق ل لب ي، يقولون: م.\r5 ـ فقطعوا: ج ق ل لب م، قطعوا: ا ت ف ق، فمنهم: منهم: م فقط، الامام: ف.\r6 ـ وهو قول بعض: فهو قوي: م، الكيسانية: الكتابية: ي.\r7 ـ تعصيل: م، الامام م. بعده بعد: ق.\r8 ـ فمنهم: منهم: ق، ولده: ا ج ف ل ي، ولد: ق م، ت، الحسن: ت ج ق ل م، الحسين: ا ف ي.\r9 ـ الى ولده عبد الله: ي، وسنه: ا ت ف لب ي، تم: ق م ل ج.\r10 ـ وهو: ق.\r11 ـ ساقوها: ساقوهما: ا."], [578, "قتله. فمنهم من ساقها إلى أخيه محمد بن الحنفية، وهو قول أكثر الكيسانية. والأكثرون ساقوها إلى ولده على زين العابدين ثم اختلفوا بعد موته فالزيدية ساقوها إلى ولده زيد بن على كما سيأتى شرح أحوال الزيدية فى فصل مفرد.\rوالإمامية ساقوها إلى محمد الباقر. واختلفوا بعد موته. فمنهم من قال إنه لم يمت وينتظرونه. ومنهم من قطع بموته، وهم الأكثرون.\rثم اختلفوا. فمنهم من ساقها إلى غير ولده وهم فريقان:\rأحدهما: الذين ساقوها إلى محمد بن عبد الله بن الحسين ابن الحسن، وهو قول أصحاب المغيرة بن سعيد البجلي.\rوثانيهما: الذين ساقوها إلى أصحاب منصور العجلى على ما سيأتى شرح هاتين الفرقتين فى فصل الفلاة.\r__________________\r1 ـ قتله: موقه: ق، فمنهم: منهم: ق لب.\r2 ـ الكيسانية: الكتابية: ي، على: علي بن ي، علي بن الحسين: لب.\r2، 3 ـ الى والده على ... ساقوها: ت.\r3 ـ كما: على ما: لب.\r5 ـ محمد بن علي: ق.\r3، 5 ـ فالزيدية ... بعد موته: ي.\r6 ـ وينتظرونه: فينتظرونه: ل ق، ينتظرونه: م.\r9 ـ احدهما: الاول: ق، ا: ا.\r9، 10 ـ الحسين بن الحسن: ا ت ي، الحسن: ج ل، الحسن بن الحسن: ق، الحسن بن الحسين: ف م، للحسين لب بن (2)، من، ا: ت، سمية: ت.\r11 ـ ثانيهما: ب: ا، اصحاب: ابي: م فقط، العجلي: البلخي: م فقط.\r12 ـ الفرقتين الفرقتين، ت ل."], [579, "أما الذين ساقوها إلى ولده جعفر الصادق، فقد اختلفوا بعد موته على قولين:\rأحدهما: الذين قطعوا بأنه لم يمت، ولن يموت حتى يظهر أمره، وهو القائم المنزل، ورووا عنه أنه قال لو رأيتم رأسى مدهدها عليكم من هذا الجبل فلا تصدقوا فإنى صاحبكم صاحب السيف.\rثم اختلفوا هؤلاء فقالت الناووسية بغيبته. وقال آخرون انه لم يغب وأن أولياءه يرونه فى بعض الأوقات وإنه يعدهم ويمنيهم. ولكنه ما عين لهم وقتا للخروج وثانيهما: الذين قطعوا بموته وهؤلاء اختلفوا على أربعة أوجه:\rأحدها: الذين زعموا أن جعفرا مات ولا إمام بعده وسيرجع إلى الدنيا فيملأها عدلا كما ملئت جورا وهم الناووسية. وثانيها:\r__________________\r1 ـ من اما اللذين ساقوها الى وقده جعفر الى س 584 الى علي النقي: ناقص في ج.\r3 ـ احدها: ا: ا، ولن يموت: ي.\r4 ـ المنزل: ا ت ي، المهدي: ف ق لب ل م، رووا: روى: لب، مدهدها: يدهده: ل لب، تردا: ي.\r5 ـ عليكم: ت ق ي، هذا ا ق ي، فانى: وانى: م.\r6 ـ اختلفوا هؤلاء: ا ت ف ي، اختلف هؤلاء ق ل لب، اختلفوا: م، فقال: قال: لب، القاووسية: ا ت ف ق ل م ي هامش، السادسية: لب، انه: ق.\r7 ـ يغب: بمت: م.\r8 ـ لكنه: لكن: ل ي، لهم: ت ف لب، له: م ي، ل، وقتا للخروج: ت ف ق لب م، وقت الخروج: ي، وقتا وقتا للخروج: ل، ثانيهما: ف ق، ب: ا، ثانيها: ل لب ت م ي.\r8، 10 ـ قطعوا ... فريقة خمسة: ق ... احدها ا: ا: ان: ل الذين زعموا: ا ت ف ق ل لب ي، آمنوا: م.\r10 ـ جعفرا: ت ق ل لب ي، جعفر: ف م، ولا امام بعده: ت ف ل لب م: ا ي.\r11 ـ فيملاها: ت ف لب ل ي يملاها: ا، فيلا الدنيا: م، ثانيها: ف ق ل لب ي، ب: ا، ثالثها: ت م."], [580, "الذين ساقوا الإمامة إلى ولده. وثالثها: الذين ساقوها إلى غير ولده.\rورابعها: الذين جوزوا الأمرين. أما الذين ساقوها الى ولده، فاعلم أنه كان له من الأبناء المعتبرين أربعة: عبد الله، ومحمد، وإسماعيل، وموسى.\rاما القائلون بإمامة عبد الله فيقال لهم الافطحية، لأن عبد الله كان أفطح، ويقال لهم العمارية لانتسابهم إلى واحد من أكابرهم يقال له عمار.\rوأما القائلون بإمامة إسماعيل فهم الاسماعيلية الشيعية.\rوأما القائلون بإمامة إسماعيل فهم الاسماعيلية الشيعية.\rوأما القائلون بإمامة موسى فيقال لهم الفضلية. وهاهنا قول آخر وهو أن الإمامة كانت لأولاده الأربعة، وهو قول الفضيلية أصحاب الفضل بن سويد الطحان.\r__________________\r1 ـ ثالثها: ج: ا،: ت م، ساقوها: ا ت ف لب ي، الامامة: ق ل م.\r3 ـ الذين جوزوا ... ورابعها (ص 581) ـ: ق م.\r4 ـ له: ا ل لب: ت ف ي، الابناء: ا ت ل لب ف، ابنائه: ف ي.\r5 ـ موسى: موسى عليهم السلام: ق.\r6 ـ لهم الافطحية: ا ت، لهم الفطحية: ف ي، الفطمية: لب، لهم البطخية: ل.\r7 ـ افطح: ابطخ: ل، لانتسابهم: ولانتسابهم: ا ي.\r7، 8 ـ العمادية ... عماد: ع ن.\r9 ـ الشمطية: الرطبة: ن.\r10 ـ الشيعية: ن.\r11 ـ الفضلية: المفضلية: ت ل ن، وههنا .. آخر: ت ف ل لب ي ن، منها ... الاخر: ل.\r12 ـ لاولاده: ف ل لب، لاولاد: ت، الاولاد: ا، في الاولاد: ي.\r13 ـ الفضل: فضل: لب، فضيلة: ن، سويد: سود: ت."], [581, "أما الذين ساقوها من جعفر إلى غير أولاده اختلفوا على خمسة أقوال:\rأحدها: الطفية أصحاب موسى بن الحسن الطفي. زعموا أن الصادق أوصى بالإمامة إليه.\rوثانيها: البزيعية أصحاب بزيع بن موسى الحائك. زعموا أن الصادق أوصى بها إليه.\rوثالثها: الأقمصية أصحاب موسى بن عمران الأقمصى الكوفى. زعموا أن الصادق أوصى بها إليه.\rورابعها: التميمية أصحاب عبد الله بن سعيد التميمى.\rوخامسها: الجعدية أصحاب أبى جعدة من الكوفة. وأما الذين اتفقوا فى سوق الإمامة من جعفر إلى ولده وغير ولده فهم اليعفورية\r__________________\r1 ـ ساقوها: ساقوا الامامة: لب.\r2 ـ احدها: ا: ا، الطغية: الطبرية: ع ن، الحسن: حسن: ت: لب، الطفى: الطبري: ع، البصري: ن، زعموا: قالوا: لب.\r4 ـ اليه: ن.\r5 ـ ثانيها: ب: ا، البزيعية: ي ف، البدعية: ا ت ف، البرمعية: لب، البرمعية: ل، يزيع: ي، برمع: ا ت ف، يرمع: لب، يرسع: ل.\r6 ـ بها: بالامامة: ت، به: ل، اليه: اليها: ا.\r7 ـ ثالثها: ج: ا، موسى: ا ت ي، سعاد: ف ل لب، اين عمران: ت.\r8 ـ زعموا: وزعموا: لب، بها: به: ل، بالامامة: ن، اليه: اليها: ا.\r9 ـ رابعها: د: ا، التميمي: ت.\r10 ـ خامسها: ه: ا.\r11 ـ اتفقوا: ا ت ف ي، توقفوا: ق ل لب م، فهم: وهي: م، فيقال لهم: ل، اليقورية: ت جف ق ل لب م، اليعقوبية: ي."], [582, "أصحاب أبى يعفور. فانهم جوزوا كلا الأمرين.\rثم اختلف القائلون بإمامة موسى بن جعفر بعد موته. فمنهم من توقف فى موته. وقال لا أدرى مات أو لم يمت. ويقال لهم الممطورة لأن يونس بن عبد الرحمن وهو من علماء الشيعة قال لهم ما أنتم الا كلاب ممطورة.\rومنهم من قطع بأنه لم يمت، وإنه حي. ثم اختلفوا.\rفزعمت البشرية أصحاب محمد بن بشر، أن موسى حي لم يمت، ولا يموت إلى الوقت المعلوم، وأنه أوصى بالإمامة إليه.\rوزعمت القرامطة أن موسى أوصى بها إليه.\rوأما القاطعون بموته فمنهم من ساقها إلى ولده أحمد ابن موسى. والأكثرون ساقوها إلى ولده على الرضا. ثم القائلون\r__________________\r1 ـ يعفور: يعقوب: ي.\r3 ـ الممطورة: ا ت ف، الممطورية: ق لب م، المنطورة: ي، المطمورة: ل.\r4 ـ علماء اغلاة م لب، الشيعة: الشيعية: ل م.\r5 ـ ممطورة: ل.\r6 ـ بانه: ت ف ق ل لب ي، انه: م، وانه حي ثم: وانه قد ف، ثم: ق.\r6، 7 ـ ثم اختلفوا ... موسى: تكرر في ك.\r7 ـ البشرية ... بشر الاسترية ... استر ع ن، موسى حي: يحي: ف.\r8 ـ ولا يموت: ا، وانه: ت ل م، فانه: ا ي، بالامامة بالامام: ت.\r7، 8 ـ موسى حي ... اليه: ف.\r9 ـ القرامطة: م، القرمطية: ق ن، القراطية: لب، القراطبة: ف، القتراطية: ي، الفيراطية: ت، وزعمت ... اليه: ل. بها: ق.\r10 ـ القاطعون: ف ل لب م ي، القاتلون: ت ق، فمنهم: ومنهم: لب."], [583, "بإمامة على اختلفوا بعد موته.\rفمنهم من لم يقل بإمامة ولده محمد النقى لصغره وعدم علمه فى ذلك الوقت. فإن زمان موت الرضا كان سن النقى أربعة.\rومنهم من قال ثمانية. واما الأكثرون فقالوا بإمامة النقى. ثم اختلفوا.\rفقال قوم لا يبعد أن يخلق الله تعالى فيه العلوم بكل الدين أصوله وفروعه. وإن كان صغيرا، كما فى حق عيسى عليه السلام.\rوقال آخرون إنه كان إماما على معنى أن الأمر له دون سائر الناس. ولكن لا يجوز أن يكون إماما فى الصلاة ومفتيا فى الحوادث. وأنما المفتى كان بعض أصحابه إلى أن صار بالغا.\rثم القائلون بإمامة النقى اختلفوا بعد موته فمنهم من ساقها إلى\r__________________\r1 ـ بامامة على: ت ل لب م ي، بامامة علي بن موسى: ق، بامامته: ف.\r2 ـ فمنهم: ومنهم: ق، النقي: ت، النفي: ل، التقي: م.\r3 ـ فان زمان موت: ت، فانه زمان: ا، فانه لما مات: ن ق ل لب م، حين مات: ي، التقي: ت، التقي: م ن، اربعة: ت ل م، اربع سنين: ا ي.\r4 ـ ثمانية: ت ف ق لب م، ثمانيا: ي، تمهنه: ل ن، بامامته: ا، واما: ا ت ن ف ق ل ي، فاما: م، و: لب، فقالوا: ل ق، قالوا: ت م، التقي التقي النقي ل.\r6 ـ تعالى: ف ق لب، بكل: ا ت ف ق ن لب، لكل: ل م، فكل: ي.\r7 ـ عليه السلام: ق لب م، صلوات الله عليه: ل، ا ت ف ي.\r8 ـ معنى: ا، له: اليه: ف.\r9 ـ الصلاة: ا ت ن ق ل لب ي، الصلوات: م، ان يكون ... مغتيا: له الامامة في الصلاة والافتاء: ف.\r10 ـ وانما: ا ت ف ل لب ي، واما: ق م.\r11 ـ القائلون: القاطعون: ل، التقي: ا ت ل، التقي: ف ق."], [584, "ولده موسى. والأكثرون ساقوها إلى على النقى، ثم اختلفوا بعد موته.\rفزعم بعضهم أنه حي وهو المنتظر. ومنهم من ساقها إلى ولده جعفر. والأكثرون ساقوها إلى ولده الحسن بن على ثم اختلفوا بعد موت الحسن على أثنى عشر قولا:\rأحدها: أنه لم يمت. لأنه لو مات وليس له ولد ظاهر لخلا الزمان عن الإمام المعصوم وإنه غير جائز.\r__________________\rلب م ي ساقها: ساقوها: لب.\r1 ـ على: علم: ت، ق، النقي: ت ل، النقي: م.\r(11/ 582)، 2 ـ فمنهم ... بعد موته: ي.\r3 ـ حي و: م، المنتظر: ل م، منتظر: ت.\r6، 4 ـ هو المنتظر ... بن علي: ج.\r4 ـ ثم اختلفوا: ا ت ف ق ل لب م، بسم الله الرحمن الرحيم له تتمة مسئلة الامامة في كتاب المحصل صنفه المولى ناصر الحق حجة الله على الخلق فخر الملة والدين، مفخر الاسلام والمسلمين بمحمد بن عمر الرازي ثم اختلفوا: د.\r5 ـ الحسن: الحسن العسكري: ن، الحسين: ج ق.\r6 ـ احدها: ا ف ق ي، الاول: ج ن م، ت ل، ولد: لب ي.\r6، 7 ـ لخلا خلى: م الزمان: ا ف ج ق ن ل لب م ي، يخلى الزمان: د، لجلى الزمان: ت.\r7 ـ عن: عند: ل الامام المعصوم ... جائز: كل النسخ، ت ق.\rوالله اعلم بالصواب، تم الكتاب عون الله سبحانه وتعالى يوم الجمعة الثاني عشر من شهر محرم سنة ست عشر وستمائة، كتبه العبد الضعيف الراحي الى عفو الله تعالى اي المناقب محمد بن محمد ابن علي النفاس الهمداني، وصلى الله على سيدنا محمد وآله اجمعين، ختم احمد بن اسماعي ل باشا محمد تيمور بمصر 1320 نسخة دار الكتب المصرية.\rوالله اعلم بالصواب تم الكتاب بحمد الله وعونه وتوفيقه، ي آخر نسخة ي.\rوالله اعلم بالصواب واليه المرجع والمآب فرغت من نسخة"], [585, "والثانى: أنه مات لكن سيجيء وهو المعنى بكونه قائما أى يقوم بعده.\rوالثالث: أنه مات ولا يجيء ولكنه أوصى بالإمامة إلى أخيه جعفر.\rالرابع: بل أوصى بها إلى أخيه محمد.\r__________________\rبتوفيقه وعونه يوم السبت في سلخ ذي الحجة سنة ست عشر وستمائة كتبة العبد الضعيف ابو الحسين مرتضى بن المطهر بن المرتضى الحسني البطحاوي يعرف بالهذلي، اللهم تمم حفظه وارزقنا حقيقته ومتعنا به واعف عنا ولجميع المؤمنين برحمتك يا ارحم الراحمين: ا اخر نسخة ا.\rوامرى الى الله موكل، تم كتاب المحصل الذي صنفه افضل العالم مفخر بني آدم فخر الملة والدين جامع علوم الاولين والاخرين محمد ابن عمر الرازي قدس الله روحه العزيز. وقد اتفق من ركن الثالث الى اتمام الكتاب بكتبه ثلاثة ايام وليايليها بتصوير العبد الضعيف خادم اهل العلم داود بن اسحق بن ابراهيم بن محمد بن ابي الرجاء بن محمد ابن عقبل الحبطاني بخطه صح، حامدا لله تبارك وتعالى ومصليا على نبيه محمد وآله ومستعفرا، في تاريخ يوم الثلاثاء السابع والعشرين في شهر الله المعظم رجب عظم الله بركته سنة احدى وخمسين وستمائة ل آخر نسخة ل.\rوالله اعلم بالصواب، تم الكتاب، والحمد لله رب العالمين والصلاة والسلام على سيدنا محمد وآله واصحابه اجمعين وذلك سليخ الخامس عشر من سفر سنة واحد وعشرين وستمائة: ج، آخر نسخة ج، وفيه هذا القيد الاني: ولقد قري على هذا الكتاب في قسططينية في مدرسة المغلى التمهيد سنة ثمانية عشر ومائة والف، نمقة الفقير الى الله ولي الدين جار الله.\r1 ـ والثاني: وثانيها: ق، الثاني: ن، لكن: ق.\r2 ـ بعده: بعد: ن.\r3 ـ الثالث: د ف لب ن: والثالث: م، وثالثها: ق، يجيء: ق لب م ن، سبجيء: د، لكنه اوحى: د ق لب ن، ولكنه اوحى، م.\r5 ـ بل: د ف لب م، انه، ن، موسى: د ف لب ن، اوحى: م."], [586, "الخامس: أنه لما مات من غير عقب، علمنا أنه ما كان إماما. وأن الإمام كان جعفرا.\rالسادس: بل ظهر أن الإمام كان محمدا. لأن جعفرا كان مجاهرا بالفسق. والحسن كان فاسقا فى الحقيقة فتعين محمد للامامة.\rالسابع: أن الحسن خلف ابنا ولد قبل موته بسنتين اسمه محمد لكنه استتر خوفا من عمه جعفر وغيره من الأعداء وهو المنتظر.\rالثامن: له ابن ولد بعد موته بثمانية أشهر.\rالتاسع: لما مات الإمام ولا ولد له فلا يجوز انتقال الإمامة منه إلى غيره، فبقى الزمان خاليا عن الإمام، وارتفعت التكاليف.\rالعاشر: يجوز أن يكون الإمام لا من ذلك النسل بل من نسل آخر غيره من العلوية.\r__________________\r(4، 5/ 585) ـ جعفر ... اخيه: ق.\r1 ـ الخامس: والخامس: م، انه: م ن، د ف لب.\r2 ـ كان جعفرا: ف ق لب ن، كان: م جعفر: د م.\r3 ـ السادس: اكثر: ق، كان: ف، محمدا: لب م ن، محمد: د ف.\r4 ـ الحقيقة: د ف ن، الخفية: لب م.\r5 ـ بسنتين: ف لب ن، بستين: ق م، حسين، د.\r6 ـ لكنه: د ف ق لب ن، م.\r7 ـ له ابن: د ف ق لب، ان له ابن: ت، ان له اينا: م، بثمانية: ثمانية: ق.\r8 ـ التاسع: ق، ولا: د ف ن، فلا، لب م، لا: ق انتقال: ن.\r9 ـ فبقى بقى: ف .. عن من: م: د ف م ن: فيبقى .. عن: ق لب.\r10 ـ العاشر: ق، لا من ذلك التسل بل: ن.\r10، 11 ـ تسل آخر غيره: ن، نسل غيره ف.\r11 ـ غيره: د نسل آخر: م، من: عن: ق."], [587, "الحادى عشر لما لم يجز انتقال الإمامة من ذلك النسل إلى نسل آخر، ولا يجوز خلو الزمان عن الإمام علمنا أنه بقى من نسله ابن، وان كنا لا نعرفه بعينه فنحن على ولائه إلى أن يظهر.\rالثانى عشر: أمر الإمامة معلوم إلى على الرضا. وبعده متخبط فنتوقف فى الكل.\rواعلم أن هذا الاختلاف العظيم من أدل الدلائل على عدم النص الجلى المتواتر على هؤلاء الاثنى عشر.\rفصل:\r"]], "pg": [573, 587]}, "687.18": {"x": [[587, "فى شرح فرق الكيسانية هم أصحاب كيسان مولى أمير المؤمنين على، رضى الله عنه، اعتقدوا فيه الاعتقاد العظيم، وانه أخذ علم التأويل والباطن والآفاق والأنفس عن ابن الحنفية رحمة الله عليه وانتهى الأمر بهم إلى رفض الشرائع، وانكار القيامة، والقول\r__________________\r1 ـ الحادي عشر: ق.\r2 ـ عن: عن غير: ق، الامام: الزمان: ف، علمنا: ق.\r3 ـ يعينه: د ف لب ن: ق م، فنحن: ونحن: ف، ولانه: ولايته: ق م، يظهر نفعرف لب.\r4 ـ الثاني عشر ق، الامامة: الامام: ق، متخيط: د ف، يختبط: لب، مختلطة: ق، مختلف: م ن.\r5 ـ فتتوقف: ق لب، فتوقف: ف ن، فيتوقف: م، في الكل: م فقط.\r6 ـ هذه الاختلافات العظيمة: ق فقط، ادل: اول: د، النص: نص: د.\r7 ـ على: عن: لب، عشر: ق م ن، عشرية: د ف لب.\r8 ـ فصل: مسئلة: ق.\r10 ـ رضي الله عنه: ف م، كرم الله وجهه: لب، عليه السلام ق، صلى الله عليه وسلم: ن.\r11 ـ والباطن والافاق: والاوقات: ق فقط. عن: من: د، الحنفية رحمه الله: م: د ف ن م، الحنيفية: ق لب.\r12 ـ رفض: دفع: ق."], [588, "بالحلول والتناسخ. وكان المختار بن أبى عبيد الثقفى الكوفى القائم يثأر الحسين رضى الله عنه، خارجيا أولا، وزبيريا ثانيا، وشيعيا ثالثا، وسنيا رابعا.\rويقال أن عليا رضى الله عنه كان يسمى المختار بكيسان. فهذه الفرقة يقال لها الكيسانية. وهم المتفقون على إمامة محمد بن الحنفية. ثم اختلفوا فذهب الحيانية أصحاب حيان بن زيد السراج إلى أنه كان إماما بعد على بن أبى طالب. واحتجوا عليه إن عليا رضى الله عنه دفع إليه الراية يوم الجمل. وقال له:\rاطعن بها طعن أبيك تحمد ... لا خير فى الحرب إذا لم توقد\r\rوهذا يدل على أن عليا رضى الله عنه أقامه مقام نفسه، وهو يوجب الإمامة. والأكثرون منهم أثبتوا إمامته بعد قتل الحسين رضى الله عنه. واحتجوا عليها بوجهين:\rالأول: أن الحسين لما عزم على الكوفة أوصى بالإمامة إليه.\r__________________\r1 ـ ابي عبيد الله: م: ف لب م ن، عبد: د، ق.\r2 ـ رضي الله عنه: د ق، اولا: د.\r4 ـ يقال: قال: د، رضي الله عنه: د ق ن، بكيسان: بالكيسان: ق، فهذه: وهذه: ق.\r5 ـ الفرقة: انفرق: ف، لها: لهم: ق: د.\r6 ـ ثم اختلفوا: د، الحيانية: ق م ن، الحنانية: د ف، الحسانية: لب، حيان: ق م ن، حنان: د ف، يحسان: لب، العراج: ف م ن، بن السراج: ق: لب.\r7 ـ رضي الله عنه: ق لب، كرم الله وجهه: ف، د م ن.\r9 ـ بها: به: ن، د، طعن: د توقد: ق م ن، ترتد: لب، ترتده: ق، مريد: د.\r10 ـ ان: انه: د رضي الله عنه: ف لب، عليه السلام: ق، م ن، وهو: د ف لب ن، فهو: م.\r11 ـ يوجب: ف لب ن، موجب: م، لوجوب: د، الامامة: للامامة: م.\r12 ـ رضي الله عنه: ف م ن، عليه السلام: ق: د."], [589, "الثانى أن الّذي بقى من ولد الحسين وهو زين العابدين كان صبيا، ولم يكن أهلا للإمامة فتعين محمد لها. ثم إن المختار دعى الناس إلى محمد بن الحنفية. وزعم أنه من دعاته. ثم تنبأ. فلما عرف محمد ذلك تبرأ منه.\rثم إن مصعب بن الزبير لما قتل المختار استوت خراسان والعراق والحجاز واليمن لعبد الله بن الزبير، فدعا ابن الحنفية إلى طاعته فهرب منه إلى عبد الملك بن مروان فكره عبد الملك كونه بالشام، وأمره بالرجوع إلى اليمن فخرج إلى اليمن، فمات فى طريقه.\rثم اختلفت الكيسانية: فمنهم من قال إنه حي فى جبل رضوى، وانه بين أسد ونمر يحفظانه، وعنده عينان نضاختان يجريان بماء وعسل ويعود بعد الغيبة فيملأ الأرض عدلا كما ملئت جورا، وهو المهدى المنتظر. وإنما عوقب بالحبس هناك لخروجه إلى عبد الملك\r__________________\r1 ـ ان: د ق م: ق لب ن، الحسين عليه السلام: ق، زين: ف ق لب ن، زيد بن زيد: م.\r2 ـ ان: ف.\r3 ـ محمد: ق، ابن: ف م ن،: د، زعم: زعموا: لب دعاته: دعى: د، تثبا: لب، نسى: د ف ن، نتسا: ق، تبناه: م.\r4 ـ ذلك: ق.\r5 ـ ان: ف، الزبير: زبير: د، المختار: مختارا: لب، خراسان: الخراسان: ق.\r5، 6 ـ العراق والحجاز: د ف لب ن، الحجاز والعراق: ق م.\r6 ـ الزبير: زبير: د.\r7، 8 ـ فكره ... الى اليمن: ق.\r8 ـ امره: امر: لب، اليمن (1): الى: ف، فخرج الى اليمن: ف لب.\r9 ـ اختلفت اختلف: د: دف لب م ن، اختلفوا فقال قوم: ق، حي: حي متيم: ق.\r10 ـ بين: بني: د.\r11 ـ وعل: عسل: ق، جورا: جورا وظلما: م.\r12 ـ وانما: م ن، ف ق لب، هناك: ف لب ن."], [590, "بن مروان وقبله إلى يزيد بن معاوية وهذا قول الكربية أتباع أبى كرب الضرير وكان السيد الحميرى على هذا المذهب وهو يقول:\rألا قل للوصى فدتك نفسى ... اطلت بذلك الجبل المقاما\r\rفى أبيات ومنهم من أقر بموته. واختلفوا على قولين:\rالأول الذين ساقوا الإمامة بعده إلى زين العابدين.\rالثانى: الذين ساقوها إلى أبى هاشم عبد الله بن محمد بن الحنفية وهم الأكثرون من الكيسانية، وزعموا أن محمدا أفضى إليه الأسرار من علم التأويل والباطن. واختلفوا بعد موت أبى هاشم على سبعة أوجه:\rالأول: أن الإمام بعده زين العابدين.\rالثانى: أن أبا هاشم مات منصرفا من الشام بأرض السراة\r__________________\r(12/ 589)، 1 ـ وانما عوقب ... معاوية.\r1 ـ معاوية: معاوية عليهم لعنة السماء والارض: ق، الكربية د ف ن، الكرابية: م، الكروبية: ق، ابي: ف لب.\r2 ـ السيد: سيد: لب ق، هذا: د، يقول: يقول في ابيات: ف ق.\r3 ـ الا قل: الاول: د للوصي: الوصي: ف فدتك فداك لب، قد تكون: ق، نفسي: نفسه: ق.\r4 ـ في ابيات ومنهم فمنهم: م: لب م ن في اثبات: د، ومنهم: د ف ق، قولين: القولين: م.\r5 ـ العابدين: العابدين عليه السلام: ق.\r7 ـ ابن الحنفية: الحنفية: د، افضى: ف لب ن، اوسى: د، وصي: ق، اقصى: م.\r8 ـ الاسرار: ف ق لب ن، بالاسران: م.\r9 ـ على: الى: م فقط.\r10 ـ ان: ق.\r11 ـ من: د ف لب ن، الى: م."], [591, "وأوصى بالإمامة إلى على بن عبد الله بن عباس ثم أوصى على إلى ابنه محمد وأوصى محمد إلى ابنه إبراهيم المقتول بحران.\rثم إن القائلين بهذه المقالة ظهروا بخراسان، ودعوا الناس إليها، فقبلها أبو مسلم صاحب الدولة، ودعا الناس إلى إبراهيم ولما عرف مروان بن محمد أن الدعوة إليه أخذه، وحبسه فتحيرت الشيعة فقال لهم يقطين بن موسى وهو أحد قدماء الدعوة انى رأيت إبراهيم الامام فى حبس مروان، فقلت له إلى من تكلنى فقال إلى ابن الحارثية، وأراد أخاه أبا العباس السفاح.\rويقال أن أبا مسلم حين كان كيسانيا واقتبس من دعاتهم علومهم على أن تلك العلوم مستودعة فى أهل البيت فكان يطلب المستقر فيه فبعث إلى الصادق انى قد دعوت الناس عن موالاة بنى أمية إلى موالاة أهل البيت، فان رغبت فيها فلا مزيد عليك فكتب إليه الصادق ما أنت من رجالى، ولا الزمان زمانى، فمال إلى بنى العباس.\r__________________\r1 ـ بالامامة: بامامة: ق، الامامة: لب، على (2): ق.\r2 ـ واوصى: فلوص: لب بحران: بنخراسان لب.\r3 ـ القائلين: العالمين: ق، بخراسان: الخراسان: د.\r4 ـ فقيلها: فقيل: ق م، الدولة: د ف ق م ن، الدعوة لب، دعا: زعموا: ق.\r5 ـ فتحيرت: ضجرت: د.\r6 ـ يقلن: يقطان: ق انى رايت د ف ق لب ن، الى: م.\r7 ـ من تكلني: علني لنا.\r9 ـ دعاتهم: د ف ق لب ن، عادتهم و: م.\r10 ـ على: د ق م ن، علم: ف لب.\r11 ـ فيه: فيها: ف.\r12 ـ فلا: بلا: ن، فكتب: وكتب: ق.\r13 ـ اليه: ق لب، الى: الا د، بلى: د ق لب ن، بين ف، ابي."], [592, "الثالث: أن أبا هاشم أوصى بالإمامة إلى ابن أخيه الحسن ابن على بن محمد بن الحنفية. فلما هلك الحسن أوصى بالامام إلى ابنه على بن الحسن فهلك، ولم يخلف، فرجعوا عنه إلى الوقوف على محمد بن الحنفية وهم أصحاب عبد الكريم بن عمر البزاز.\rالرابع: لا بل أوصى بها إلى بنان بن سمعان الفهدى الغالى.\rالخامس: لا بل أوصى بها إلى عبد الله بن عمرو بن حرب الكندى.\rالسادس: لا بل أوصى إلى عبد الله بن معونة بن جعفر بن أبى طالب فهذه الاختلافات الكثيرة تحكمات محضة لا طائل لها.\rفصل:\r"]], "pg": [587, 592]}, "687.19": {"x": [[592, "فى شرح فرق الزيدية.\r__________________\r1 ـ الحسن: د م ن، الحسين: ف ق لب.\r2 ـ بن الحنفية: الحنفية: د، الحسيس: د م ن، الحسين، ف ق لب، بالامام: ن فقط، الى ق.\r3 ـ فرجعوا عنه: ن لب، فرجعوا عنده: د ف ق، فرجع عنده: م.\r4 ـ محمد: ق، وهم: وزعم انه يحي بعد موته: ق عصرنا عبد: ف.\r5 ـ لا: د بها: ق، بنان: بنا: لب، بيان: ف: م ن الفهدى المهدي: ل لب، العندى: ن ف: م.\r6 ـ بها: د ق لب ن، عمرو: عمر: ن، حرب: ط ن، حرث لب م، الحرث: ف.\r8 ـ بن معونة: معونة: لب، مهوية: ق، د.\r9 ـ محضة: م فقط، لها: د ف، تحتهاا: لب، فيها: ف، لها وبالله التوفيق: والمدد: م، ق م.\r10 ـ فصل: مسئلة: ق."], [593, "فالذى يجمعهم أن الإمام بعد الرسول عليه الصلاة والسلام على ابن أبى طالب رضى الله عنه بالنص الخفى ثم الحسن ثم الحسين ثم كل فاطمى مستجمع لشرائط الإمامة دعى الخلق إلى نفسه شاهرا سيفه على الظلمة.\rواختلفوا فقال بعضهم أن الرسول عليه الصلاة والسلام نص على على، والحسن والحسين وقال الآخرون الرسول عليه السلام نص على على وهو نص على الحسن والحسن نص على الحسين. وفرقهم ثلاثة:\rالجارودية أصحاب أبى جارود بن زياد بن منقذ العبدى زعم أن الرسول عليه الصلاة والسلام نص على على رضى الله عنه بالوصف دون التسمية والناس قد قصروا حيث لم يتعرفوا الوصف. وانما\r__________________\r1 ـ يجمعهم: عرفهم: د، يجمعون: ق، عليه لصلاة والسلام: م، عليه السلام: ق ن، صلى الله عليه وسلم: د.\r2 ـ رضي الله عنه: م، كرم الله وجهه: ف لب، عليه السلام ق، د ن.\r3 ـ مستجمع: د ف لب ن، يستجمع: ق، مستحق: م، دها: ودعا: د.\r5 ـ ان: ف فقط، عليه الصالة و: م السلام: ف ق لب م، عليكم: د، ن، على: عليه السلام: ف ق لب.\r6 ـ قال: ن، الاخرون: دن، آخرون: ف م، عليه السلام: ق فقط.\r7 ـ وهو نص على، وصدر نص علي عليه السلام: ق، الحسن (2): الحسين: ق، نص (2): د.\r7، 8 ـ فرقهم ثلاثة: د فقط: هم ثلاث فرق: لب.\r9 ـ جارود: الجارود: د، زياد: ق ن، وزياد: د ف، ياد لب م، منقذ العبدي القهدي: لب: ف لب ن، سعيد المنذر العبدي: ق، متعد العبدي: د م.\r10 ـ عليه الصلاة و: م: د ف ق لب م، ن، رضي الله عنه: لب، صلى الله عليه وسلم: ن.\r11 ـ قد: ن ف لب، حيث: ف."], [594, "نصبوا أبا بكر رضى الله عنه باختيارهم ففسقوا.\rوالسليمانية أصحاب سليمان بن جرير، زعموا أن البيعة طريق الإمامة وأثبتوا إمامة الشيخين بالبيعة، أمرا اجتهاديا ثم تارة يصوبون ذلك الاجتهاد وتارة يخطئونه، لكنهم يقولون الخطأ فيه لا يبلغ الفسق، وطعنوا فى عثمان وكفروه وكفروا عائشة وطلحة والزبير ومعاوية لقتالهم عليا رضى الله عنه.\rوالصالحية أصحاب الحسن بن صالح بن حي الفقيه كان يثبت إمامة أبى بكر وعمر رضى الله عنهما ويفضل على بن أبى طالب على سائر الصحابة رضى الله عنهم إلا أنه توقف فى عثمان وقال إذا سمعنا ما ورد فى حقه من الفضائل اعتقدنا إيمانه، وإذا رأينا أحداثه التى نقمت عليه وجب الحكم بفسقه، فتحيرنا فى أمره، وفوضناه إلى الله تعالى. وقول هؤلاء فى الأصول قريب من مذهب المعتزلة.\rفصل فى الإشارة إلى عمدة مذهب الإمامية مدار مقالتهم فى\r"]], "pg": [592, 594]}, "687.20": {"x": [[594, "__________________\r1 ـ رضي الله عنه: م فقط، ففقوا: ففقوا به: م.\r2 ـ السليمانية: السلامية اصحاب السلمن ثلاثة فالجريرية: ق، زعموا: وزعموا: م د.\r3 ـ امامة الشيخين بالبيعة: الامامة لشيخين: ق، يصوبون: يصيبون: لب.\r5 ـ وطعنوا ... وكفروه: د: ق.\r6 ـ رضي الله عنه: صلى الله عليه وسلم: ق م.\r7 ـ الصالح: ف ق لب، صالح: دن، على: م، الفقيه: فقيه: ق.\r8 ـ رضي الله عنهما: ف فقط، ابي طالب: ابي طالب عليه السلام: ق، صلى الله عليه وسلم: ن.\r9 ـ رضي الله عنهم: ف.\r10 ـ ورد: وارد: ف، الفضائل: الاخبار: ق.\r11 ـ نقمت عليه: احدث بها: ق، فتحيرنا: فعنبر: ق.\r12 ـ قريب: قريبة: ق، من: عن: م.\r13 ـ فصل: مسئلة: ق."], [595, "الاستدلال على قاعدة وفى الجواب عن كلمات خصومهم على قاعدة أخرى.\rأما الأول إن الإمامة لطف لانا نعلم بالضرورة بعد استقراء العرف أن الخلق إذا كان لهم رئيس قاهر يمنعهم عن القبائح. فإن امتناعهم عنها أكثر من القلب. واللطف يجرى مجرى التمكين وإزالة المفسدة. ولما كانا واجبين على المكلف الحكيم كانت الإمامة أيضا واجبة وبنوا على هذا عصمة الإمام قالوا إمكان صدور القبيح عن الخلق محوج لهم إلى الإمام فلو تحقق هذا فى حق الإمام لافتقر هو إلى إمام آخر، ولزم التسلسل وبنوا كون الإجماع حجة على هذا لأنه لما ثبت امتناع خلو الزمان عن المعصوم والمعصوم لا يقول إلا الحق كان الإجماع كاشفا عن قول المعصوم الّذي هو حق فكان الاجماع حجة فظهر بهذا أن العلم بكون الاجماع دليلا لا يتوقف على العلم بصدق الرسول.\rوبنوا إمامة على بن أبى طالب كرم الله وجهه على وجوب عصمة\r__________________\r1 ـ وفي: د ق لب ... على قاعدة: د ق لب م ن، لما ف.\r3 ـ اما: ق الامامة: الامام: م فقط.\r4 ـ فان: كان: ف.\r5 ـ القلب: العكس: م.\r7 ـ على هذا تاخر بعد الامام: د، الامام: د ف لب ن، الائمة: ق، الانبياء: م، عن: من: ق.\r8 ـ محوج: محرج: د، فلو: ولو: ق.\r10 ـ ثبت: يدل: ق، والمعصوم: ل ف لب ن، والمعصوم الذي: ق، م.\r11 ـ الحق: د ف لب ن، بالحق: ق ن، كان: وكان: ن، الذي ب: م.\r12 ـ حجة: دليلا: لب، ف، فظهر ... دليلا: ق.\r14 ـ كرم الله وجهه: ف، عليه السلام: ق، صلى الله عليه وسلم: ن: د لب م."], [596, "الإمام، ووجوب حقيقة الإجماع بيانه أن العقل لما دل على أن الامام واجب العصمة. وكل من قال بذلك، قال إنه على بن أبى طالب رضى الله عنه وذلك معلوم بالضرورة بعد الاستقراء من دين محمد عليه الصلاة والسلام.\rفلو قلنا: بأن الإمام غير على، كان ذلك خرقا للإجماع.\rوبهذا أثبتوا إمامة سائر أئمتهم وأثبتوا وجود محمد بن الحسن وغيبته وإمامته قالوا لأن وجود هذا الشخص وبقاؤه فى هذه المدة الطويلة ممكن والله تعالى قادر على الممكن وثبت امتناع خلو الزمان عن الإمام المعصوم. وكل من قال بذلك قال إنه هذا، فلو كان غيره لقدح ذلك فى الاجماع.\rلا يقال أليس قد تقدم بيان الاختلاف العظيم بين الشيعة فى بعض الأئمة؟ فكيف ادعيتم اجماع الكل على هذا الترتيب؟ ولأن\r__________________\r(14/ 595) 1 ـ عصمة الامام: العصمة: ق.\r1 ـ الاجماع: د ف ق لب ن، الاسلام: م.\r3 ـ رضي الله عنه: ف لب، عليه السلام: ق، صلى الله عليه وسلم: ن: د م، معلوم: معلوم قلة: ق، بعد: وبعد: ف م.\r4 ـ عليه الصلاة و: م السلام: د ف ق لب م ن.\r5 ـ بان: د لب ن، ان: ف ق م، كان ذلك: ق، خرفا للاجماع: د ف لب ن، خرق للاجماع: ق م.\r6 ـ العتهم: الائمة: ف، وجود: د لب ن، وجود امامه: ق م، وجوب وجود: ف الحسن: الحسن العسكري: ف م، الحسين: د.\r7 ـ الان: د ف لب ن، ان: م.\r8 ـ تعالى: د م ن، الممكن: ف م ن، كل الممكنات: د، ثل ممكن: ق، خلو: ف.\r9 ـ وكل ... بذلك: د ق لب م ن، فكل ممن كان ذلك: ف.\r10 ـ لقد ح: ق د م ن، يقدح: ف لب.\r11 ـ لا: ولا: ف.\r12 ـ اجماع: ق."], [597, "الاسماعيلية فرقة عظيمة فى زماننا وهم ينازعون فى هذا الترتيب.\rلأنا نجيب عن الأول بأن القائلين بغير هذا الترتيب انقرضوا. فلو كان قولهم حقا كان أهل الزمان مع اجماعهم على ترك ذلك القول مجمعين على الخطأ، وإنه غير جائز. وأما خلاف الاسماعيلية فغير قادح لما بينا أن الإمام يجب أن يكون معصوما، وهم فساق، بل كفرة، لقدحهم فى الشرع، وقولهم بقدم العالم، فهذا غاية تقرير مذهبهم.\rثم إن على هذا المذهب اعتراضا وهو أن عليا وأولاده، لو كانوا أئمة فلم لم يشتغلوا بالإمامة وما حاربوا الظلمة لأجلها، فعند هذا قررت الشيعة قاعدة أخرى، وهى القول بجواز التقية قياسا على جواز اختفاء النبي عليه السلام فى الغار فظهر أن اعتمادهم فى مذهبهم أما فى الاستدلال، فعلى وجوب الإمامة عقلا، وأما فى دفع الاعتراضات فعلى القول بالتقية، فان صح كلامهم فى هاتين المقدمتين فالدست لهم، وإلا فلا.\rوأما تمسكهم بالنصوص من القرآن والأخبار فذلك مما يشاركهم\r__________________\r(12/ 596)، 1 ـ ولان ... الترتيب: ف.\r2 ـ لانا ... الترتيب: ق.\r3 ـ اهل: د ن، اهل هذا: ف م.\r4 ـ واما: ف د ق ن، اما: د، واما مع: م، فغير: ف م ن، بغير: د.\r6 ـ كفرة: كفرا: ف، بقدم: لقدم: ف.\r8 ـ اولاده: اولاده رضي الله عنهم: ف.\r9 ـ ما: ف د لب ن، م.\r10 ـ الشيعة: الشيعية: ف، وهي: ف ن، وهو: د ق لب م.\r11 ـ عليه الصلاة و: م: د ف ق لب م ن، فظهر: وظهر: ق.\r12 ـ الاعتراف د ق م ن، الاعتراض: ف، صح: انصح: ف."], [598, "الزيدية فيه.\rوأما رواية النص الجلى فالأذكياء منهم يعترفون بأنه لا يجوز ادعاء التواتر فيها حتى أن الشريف المرتضى وهو أجل الإمامية قدرا وأكثرهم علما، وأغوصهم فكرا ونظرا روى فى كتاب الشافى عن أبى جعفر بن قبة أن السامعين لهذا النص كانوا قليلين.\rوالاعتراض لا نسلم وجوب الإمامة، ولا نسلم كونها لطفا.\rقوله الخلق إذا كان لهم رئيس قاهر فالأمر كذا وكذا، قلنا لو كانت القضاة والأمراء كلهم معصومين لكان اللطف أتم، فيلزمكم وجوب ذلك فلما لم يجب ذلك بالاتفاق، علمنا أن ذلك إما لأن فى نصب الأمراء والقضاة المعصومين فى كل محلة وان حصلت المنفعة المذكورة، لا أن هناك مفسدة خفية أستأثر الله تعالى بعلمها، أو لأن ذلك، وان كان لطفا محضا خاليا عن شوائب المفاسد لكن اللطف\r__________________\r1 ـ الزيدية فيه: فيه الزيدية: ق.\r2 ـ رواية: د ف لب ن، رواة: م، النص: نص: د، يعترفون: د ف، معترفون: ق م ن.\r2، 4 ـ قدرا و، وقد زاد: د.\r4 ـ اعوصهم: ن.\r5 ـ فيه: فقيه: لب.\r7 ـ قوله: وقوله: م.\r7، 8 ـ قاهر .. وكذا: ف ق لب .. لكان: د ف ق لب ي، معصوم كان: م.\r9 ـ ذلك: ق، علمنا ان ذلك: فكذا ههنا: ق، ذلك (2) ذلك غير واجب: لب فقط.\r9، 10 ـ اما الان في: د ف ن، الا ان يقولوا فمن: لب، وان تعلوا ثم بان في: ق، اما لان: م.\r10 ـ محلة: محل: ق م، المنفعة: د ف ق لب ن، النفقة: م.\r11 ـ الستائر انفرد: لب .. بعلمها علمها: ق م: د ف ق لب م ن.\r12 ـ لان في ق، كان ق."], [599, "غير واجب وعلى التقديرين فالقول فى الإمام الأعظم مثله وهذه النكتة هاهنا كافية، والاستقصاء مذكور فى كتبنا المطولة.\rسلمنا وجوب الإمامة فلا نسلم أن الإجماع حجة.\rقوله: الإجماع يكشف عن قول المعصوم. قلنا نعنى بالاجماع الإجماع الّذي لا نعرف له مخالفا أو الّذي نعرف أنه لا يخالف فيه.\rوالأول: ممنوع لأن عدم علمنا بالمخالف لا يدل على عدمه.\rوالثانى: مسلم لكن لا نسلم أنه لا يمكننا العلم بالاجماع على هذا الوجه فمن الّذي يمكنه القطع بأنه ليس فى أقصى الشرق والغرب أحد يخالف فى هذه المسألة.\rلا يقال أنه يمكننا أن نعلم أنه لا مخالف. لأن العبرة بالعلماء لا بالعوام والعلماء من أهل كل عصر معروفون مشهورون. فيمكننا أن نتعرف أقوالهم، ولأن ما ذكروه يفضى إلى سد باب الاجماع وأنتم لا تقولون به.\rلأنا نجيب عن الأول بأنا لا نسلم أن العلماء من أهل كل عصر\r__________________\r1 ـ واجب و: واجب: د، فالقول: فانقول: ق، في: ب: د.\r2 ـ المطولة: الكلامية: د.\r5 ـ يخالف: د ن، مخالف: ف م، فيه: د ف لب، له: م ن.\r6 ـ والاول: الاول: ف: ق.\r7 ـ لا (2): ن فقط.\r8 ـ بانه: ن، انه: د ف م.\r9 ـ احد .. ف، بخالف: د ق م، مخالف: ف لب ن، في: ق م.\r11 ـ كل: ق، معروفون: معرفون: ف، معروفون و: لب.\r12 ـ نتعرف: د ق م ن، نعرف: لب ف.\r14 ـ كل عصر: د ف ق لب ن، العصر: م."], [600, "معروفون فى العالم. لأن أهل المغرب لا خبر عندهم من علماء المشرق وبالعكس. ولأن الإمام المعصوم أجل الأئمة وأفضلهم مع أنه غير معروف فى العالم فإن العلماء الذين نعرفهم فى العالم نعلم فى كل واحد منهم أنه ما عاش ثلاثمائة سنة وأكثر، وإنه ليس ولد الحسن العسكرى بل نعلم أباه وجده وحينئذ نقول: لو صح ما ذكرتموه لكان ذلك من أقوى الدلائل على نفى إمامكم.\rلأنا نقول لو كان مشهورا فيما بين الناس وإذ ليس بمشهور فهو غير موجود.\rلا يقال إنه معروف ولكنه مجهول النسب والعمر لأنا نقول لو جاز خفاء ذلك لجاز أيضا خفاء قوله ومذهبه إذ ليس تجويز أحدهما بأبعد من تجويز الآخر.\rوعن الثانى: إنا إنما نعترف بامكان الإجماع حيث يكون العلماء قليلين تحويهم بلدة وأما الآن فلا ندرى، فلعل فى أهل العالم من\r__________________\r1 ـ المغرب: الغرب: ق، علماء: العلماء: ف.\r2 ـ المعصوم: د.\r3 ـ في: ق.\r4 ـ عاش: عاش العسكري: ف، و (1): د ف لب ن، او: م ق، و (2): د ليس: ليس يعلم: ق.\r5 ـ العسكري: ف، نقول: ف ق لب، نقوله: م، يقول: د.\r6 ـ ذكرتموه: د ف ق لب ن، دعوتموه: م، امامكم: د ف ق لب، امامتكم: م ن.\r7 ـ اذ: انه: لب، اذا: ف.\r8 ـ بمشهور: مشهورا: ق.\r9 ـ انه معروف ... لانا نقول: م فقط.\r10 ـ خفاء (1): ق.\r12 ـ تحويهم: ف م ن، تحوزهم: د لب، متاكلة في: ق، بلدة بلد: ن، فلعل: ولعل: م فقط، في: د."], [601, "يزعم أن أبا بكر واجب العصمة أو يدعى ذلك فى إنسان آخر وإذا ظهر هذا الاحتمال انقطع القطع.\rسلمنا أن الإجماع حجة يكشف عن قول المعصوم، لكن قول المعصوم متى يكون حجة مطلقا أم عند عدم التقية. الأول ممنوع بالاتفاق بيننا وبينكم.\rوالثانى: مسلم لكنه لا يدل على أن القرآن المجمع عليه حجة لا يقال إن الإمام وافق على ذلك تقية وخوفا. وعلى هذا التقدير يسقط التمسك بالإجماع.\rسلمنا صحة دليلكم، لكنه معارض بأنه لو كان إماما لأظهر الطلب كما أظهره على رضى الله عنه مع معاوية، وكما أظهره الحسين مع يزيد حتى آل الأمر إلى قلة المبالاة بالقتل. ولأن عبد الرحمن بن عوف لما بايع يوم الشورى عليا على كتاب الله تعالى وسنة رسوله وسيرة الشيخين لم يرض على بالتزام\r__________________\r1 ـ ابا بكر: ابا بكرر رض الله عنه: لب، واذا: د ف ق ن، فاذا: لب م.\r3 ـ حجة: د.\r4 ـ يكون: د ف ق لب ن، كمن: م، مطلعا: ام طنيفا: ق.\r5 ـ بالاتفاق بيننا وبينكم: د لب ن، بيننا وبينكم بالاتفاق: ق م، بالاولى بيننا وبينكم: ف.\r6 ـ لكنه: ولكنه: لب، القرآن: د م ن، القول: ف ق لب.\r7 ـ لا يقال: م: لب، لاحتمال: د ف ن، للاحتمال: ق، وافق: د ف لب ن، واقف: م، متاكلة في ق.\r8 ـ يسقط: سقط: ن، التمسك بالاجماع، ف لب م ن، بالاجماع: د، الاجماع: ق.\r10 ـ اظهره (1): اظهر: د، رضي الله عنه: م ف، صلى الله عليه وسلم: ن،: د ق، اظهره (2): اظهر: لب م.\r11 ـ الحسين: الحسين عليه السلام: ق ن.\r12 ـ بايع: رضي: ق.\r13 ـ تعالى: د ف."], [602, "سيرة الشيخين فترك الإمامة لذلك مع أنه كان يمكنه ذكر ذلك اللفظ وإنه كان ينوى به غير ظاهره فإن فى المعاريض لمندوحة عن الكذب فمن لا يرضى بهذا القدر كيف يقال إنه رضى بالكفر للتقية. وتمام الكلام مذكور فى النهاية.\rولنختم هذا الكتاب بما يحكى عن سليمان بن جرير الزيدى أنه قال: إن أئمة الرافضة وضعوا مقالتين لشيعتهم لا يظفر معهما أحد عليهم.\rالأول: القول بالبداء فإذا قالوا إنه سيكون لهم قوة وشوكة ثم لا يكون الأمر على ما أخبروه قالوا بدا لله تعالى فيه قال زرارة ابن أعين من قدماء الشيعة وهو يخبر عن علامات ظهور الإمام.\rفتلك أمارات تجيء بوقتها ... ومالك عما قدر الله مذهب ...\rولو لا البداء سميته غير فائت ... ونعت البداء نعت لمن يتقلب ...\rولو لا البداء ما كان ثم تصرف ... وكان كنار دهرها تتلهب\r__________________\r(13/ 601)، 1 ـ لم يرض ... رضي الله عنه: صلى الله عليه وسلم: ن بالتزام: بالتراب: د .. الشيخين: د ف لب ن: ق م.\r1 ـ الامامة لذلك: ف لب ن، الامر لذلك كذلك: م: ق م، الامامة لبذلك انه: د.\r2 ـ وانه: ولن: ن، به: ن، في: د.\r3 ـ لا يرضى: د ف ن، لم يرض: لب م، لا يرضى: ق، يقال: ف.\r5 ـ و: د، الكتاب: الكلام: م فقط، يحكى: على: د، ابن جرير: جرير: د، انه: ف.\r6 ـ ائمه: الائمة: ق، لانفة: د الرافضة: الروافض: لب، الروافضية: ق، الرافضية: د، وضعوا مقالتين: مقالين: د.\r8 ـ قالوا قال: ف، سيكون: يكون: ف.\r9 ـ على ما اخبروه: كذلك: ف، اخبره: د بدا: ابدا: ف، تعالى: ف، فيه: ق، زراره: ف ق، زراره: لب، رواده: د، زراه: ن.\r10 ـ ابن اعين: ف لب م ل، ابن عين: ق، فراعن: د."], [603, "وكان كضوء مشرق بطبيعة ... ولله عن ذكر الطبائع مرغب\r\rوالثانى: التقية فكلما أرادوا شيئا تكلموا به فإذا قيل لهم هذا خطأ أو أظهر بطلانه قالوا إنما قلناه تقية.\rوهذا آخر هذا الكتاب والله أعلم بالصواب، وإليه المرجع والمآب"], [605, "الفهرس\rالموضوع ... الصفحة\r\r* المقدمة\rدراسة مقارنة بين شراح المحصل\rوموقف فخر الدين الرازى من علم الكلام 5\r* نسخ المخطوطات التى اعتمدنا عليها فى التحقيق 60\r* صور بعض المخطوطات 65\r* كتاب «محصل أفكار المتقدمين والمتأخرين» 77\rالركن الأول\rفى المقدمات\r* المقدمة الأولى: فى العلوم الأولية 81\r* القول فى التصورات [امكان المعرفة] 81\r* القول فى التصديقات 86\r* المقدمة الثانية: فى أحكام النظر 121\rـ النظر ترتيب تصديقات يتوصل بها الى تصديقات اخر 121\rـ الفكر المفيد للعلم موجود 122\rـ لا حاجة فى معرفة الله الى المعلم 126\rـ الناظر يجب أن لا يكون عالما بالمطلوب 129\rـ معرفة الله واجبة ولا يمكن تحصيلها الا بالنظر 130\rـ وجوب النظر سمعى 134\rـ اختلفوا فى أول الواجبات 136"], [606, "الموضوع ... الصفحة\r\rـ حصول العلم عقيب النظر الصحيح 136\rـ النظر الفاسد لا يولد الجهل ولا يستلزمه 137\rـ حضور المقدمتين فى الذهن لا يكفى لحصول النتيجة 138\rـ العلم بوجه دلالة الدليل على المدلول هل هو عين العلم بالمدلول أم لا؟ 139\r* المقدمة الثالثة: فى الدليل وأقسامه 141\rـ الدليل هو الّذي يلزم من العلم به العلم بوجود المدلول 141\rـ الدليل اللفظى لا يفيد اليقين الا عند تيقن أمور عشرة 142\rـ النقليات بأسرها مستندة الى صدق الرسول 142\rـ الاستدلال بشيء على شيء 143\rالركن الثانى\rفى تقسيم المعلومات\r* المسألة الأولى: فى أحكام الموجودات 147\r* المسألة الثانية: المعدوم اما أن يكون ممتنع الثبوت أو ممكن الثبوت 149\rـ تفصيل قول الفلاسفة والمعتزلة فى المعدومات 157\r* المسألة الثالثة: لا واسطة بين الموجود والمعدوم 163\rـ التفريع على القول بالحال 173\rـ تقسيم الموجودات على رأى الحكماء 173\rـ خواص الواجب لذاته عشرة 177\rـ خواص الممكن لذاته وهى ست 185\rـ تقسيم الموجودات على رأى المتكلمين 208\rـ خواص القديم والمحدث 209\rـ تقسيم الممكنات على رأى الحكماء 216\rـ تقسيم المحدثات على رأى المتكلمين 230\rـ فصل فى أحكام الأعراض وأقسامها 262\rـ النظر فى مقومات الاجسام وعوارضها 268"], [607, "الموضوع ... الصفحة\r\rـ الجواهر الروحانية 324\rـ القول فى الملائكة والجن والشياطين 325\r* خاتمة فى أحكام الموجودات: 326\rـ بيان الوحدة والكثرة 326\rـ العلة والمعلول 331\rالركن الثالث\rفى الالهيات والنظر فى الذات\rوالصفات والأفعال والأسماء\r* القسم الأول: فى الذات 337\r* القسم الثانى: فى الصفات 357\rـ القول فى السلوب 357\rـ القول فى الصفات الثبوتية 372\r* القسم الثالث: الكلام فى الأفعال 455\rـ تأثير قدرة العبد فى مقدوره 455\rـ الله تعالى مريد لجميع الكائنات 472\rـ تفصيل قول الفلاسفة فى ترتيب الممكنات 474\rـ الحسن والقبح 478\rـ لا يجب على الله سبحانه شيء 481\rـ علة حسن التكليف التعريض لاستحقاق النعم 484\r* القسم الرابع: الكلام فى الأسماء 488\rالركن الرابع\r* القسم الأول: فى النبوات 489\rـ المعجز أمر خارق للعادة مقرون بالتحدى 489\rـ اثبات نبوة ورسالة محمد صلىلله عليه وسلم 489"], [608, "الموضوع ... الصفحة\r\rـ الرد على شبه المنكرين 502\rـ عصمة الأنبياء عليهم السلام 520\rـ الأنبياء أفضل من الملائكة 531\r* القسم الثانى: فى المعاد 537\rـ الاختلاف فى المعاد بدنى أو نفسى 537\rـ مذهب ارسطاطاليس أن النفوس البشرية متحدة بالنوع 543\rـ القائلون بحدوث النفس اتفقوا على فساد التناسخ 546\rـ اتفقت الفلاسفة على امتناع عدم الأرواح 549\rـ النفس الناطقة تدرك الجزئيات 550\rـ اتفقت الفلاسفة على سعادة النفوس العالمة النقية عن الهيئات البدنية بعد الموت 552\rـ اتفقوا على شقاوة النفوس الجاهلة 553\rـ اعادة المعدوم جائزة 553\rـ أجمع المسلمون على المعاد بمعنى جمع الأجزاء بعد تفرقها 555\rـ وعيد أصحاب الكبائر 562\rـ وعيد الكافر المعاند دائم 566\r* القسم الثالث: فى الأسماء والأحكام 567\rـ تعريف الايمان فى اللغة والشرع 567\rـ الايمان عندنا لا يزيد ولا ينقص 570\r* القسم الرابع: فى الامامة 573\rـ الكلام على وجوبها أو عدم وجوبها 573\rـ طوائف الشيعة واختلافهم 575\rـ شرح فرق الكيسانية 587\rـ شرح فرق الزيدية 592"]], "pg": [594, 608]}}, "units": {"5": {"tit": "محصل أفكار المتقدمين والمتأخرين للرازي (606)", "lvl": 1, "pg": [5, 79]}, "79": {"tit": "[نص الكتاب]", "lvl": 1, "pg": [79, 608]}}};
